-- 自动生成：仅含中文译文与匹配指纹。来源见 SOURCES.md。
local D=LegionChineseDB
local S=D.SharedStrings
D.Strings[99424]="我喜欢来这里思考。看着这座雕像，我的心情就平静了下来。"
D.Strings[99425]="我们身上的担子很重。"
D.Strings[99426]="我看到巨大的黑暗笼罩着虚空之光神殿。那是燃烧军团，他们要攻击了。"
D.Strings[99427]="教团会毁在他手中，所有人都将死去。"
D.Strings[99428]="这就是命运。我们注定要死于恐惧魔王巴纳扎尔之手。"
D.Strings[99429]="这就是命运……除非……"
D.Strings[99430]="我看到了一条通往胜利的道路！你沐浴着圣光，指引我们前行。"
D.Strings[99431]="我很清楚自己的道路。"
D.Strings[99432]="幻象更清晰了。"
D.Strings[99433]="昔日的敌人将成为盟友。"
D.Strings[99434]="被遗忘的暗影再次崛起！"
D.Strings[99435]="圣光之下，我们万众一心。"
D.Strings[99436]="向着目标前进吧。"
D.Strings[99437]="去追寻属于你的和谐吧。"
D.Strings[99438]="我知道有人把艾伦·阿斯塔瓦带到这里来了。告诉我他在哪儿。"
D.Strings[99439]="冷静点。"
D.Strings[99440]="我感觉到了你内心的不安。"
D.Strings[99441]="重新思考一下你的道路吧。"
D.Strings[99442]="记住，种瓜得瓜种豆得豆。"
D.Strings[99443]="滚开！你给我惹的麻烦已经够多了。"
D.Strings[99444]="有话就快说吧。"
D.Strings[99445]="真可耻。"
D.Strings[99446]="想要惹火我吗？真古怪。"
D.Strings[99447]="月郡家族必将崛起。"
D.Strings[99448]="语言也是武器。"
D.Strings[99449]="很高兴看到你安然无恙，塞纳苟斯。"
D.Strings[99450]="要不是你朋友的努力，我恐怕就没这么好受了。"
D.Strings[99451]="我不知道，真的……我是……摔下来的。"
D.Strings[99452]="<怀疑地上下打量着你。>"
D.Strings[99453]="小心！艾萨拉的爪牙不会轻易放弃辛艾萨莉之心的。"
D.Strings[99454]="橡树之心保护了世界之树无数岁月，从未放松警惕。这真是个悲剧。"
D.Strings[99455]="你处理好这里的事情之后就告诉我，然后我们就可以离开了。"
D.Strings[99456]="你有一个来自炎魔之王族裔的强大腕轮。这可不是玩具，$r。这种腕轮甚至能威胁到伟大的元素领主。它们极其危险，难以控制。\n\n你想用这些腕轮来囚禁风元素领主吗？还是有别的打算？"
D.Strings[99457]="我不怕风元素领主。只要我有这个腕轮，他就会害怕我。"
D.Strings[99458]="坚强点，年轻人。没有人能躲过梦魇的魔爪。"
D.Strings[99459]="呃……但愿你喜欢吃生鱼，$n。"
D.Strings[99460]="……我让您失望了，我的大人，迪瑟洛克……"
D.Strings[99461]="看看你都干了些什么。你就是不愿意听话，对吧？"
D.Strings[99462]="生命缚誓者在上……我以为辛艾萨莉之心只是一个传说。"
D.Strings[99463]="我可不在乎你的腕轮。\n\n通过大地之环的努力，桑德兰已经归来。新的风元素领主已经崛起，你应该跟他去聊聊这些破玩意儿。\n\n但即使如此，一个腕轮对风元素领主也是没什么用的。"
D.Strings[99464]="真是狂妄啊，$r。元素领主可不是以宽宏大量著称的。\n\n不过，你要是能凑齐两个腕轮，以及足以激活它们的强大矿石，那我可以安排你与风元素领主桑德兰见一面。\n\n利用这段时间好好想想你该在会面时如何表现吧。如果你回不来，我也可以理解。"
D.Strings[99465]="我要怎么才能见到风元素领主？"
D.Strings[99466]="够了！我来亲自对付你。"
D.Strings[99467]="我并不想囚禁风元素领主。我想与他达成一个协议。"
D.Strings[99468]="有意思。\n\n通过大地之环的努力，桑德兰已经归来。新的风元素领主已经崛起，你应该跟他去聊聊这些破玩意儿。\n\n但即使如此，一个腕轮对风元素领主也是没什么用的。"
D.Strings[99469]="滚吧，$r。我对你的愚蠢计划毫无兴趣。"
D.Strings[99470]="我们拿到所需的一切了。干得好！"
D.Strings[99471]="成……成功了！"
D.Strings[99472]="别让他们靠近我，我来把这家伙弄出来。"
D.Strings[99473]="难以置信！但一个精华的力量还不够。"
D.Strings[99474]="噢，卡雷苟斯！我们才刚刚开始呢。我们必须深入梦魇本身。"
D.Strings[99475]="我曾经是鲁文大人的贴身侍从。如今我却只能给那些暴躁而又娇惯，还没有实权和影响力贵族递送酒水和甜食。\n\n真可悲。"
D.Strings[99476]="我的鲁文大人承诺过，如果他能晋升到皇宫，就会给我那种力量。而我相信了！我还制定了计划！\n\n如今他死了，我每次露面都会招来瞪视。我好羞愧。\n\n他这样的人为何会堕落至此？"
D.Strings[99477]="噢，我亲爱的鲁文……\n\n他是个非常自以为是的孩子，非常傲慢。我早就知道，他有一天一定会把巨大的力量据为己有。\n\n但是……我想的不是这样。噢，我的孩子……"
D.Strings[99478]="我听说科恩·斯特拉瑞斯开始购买暮湾家族剩下的侍从了——是真的吗？"
D.Strings[99479]="我在拜访斯特拉瑞斯家族时偷听到一个粗俗的笑话，拿可怜的鲁文寻开心。我想你一定不愿意听……"
D.Strings[99480]="街上有流言说，在他的尸体旁边发现了一个银色月牙——是真的吗？"
D.Strings[99481]="当然不会！他为什么会这么做？他没有荣誉感可言吗？"
D.Strings[99482]="……他为什么要这么做……？"
D.Strings[99483]="这是斯特拉瑞斯家族的标志……但是，这不可能。科恩是鲁文最要好的朋友……"
D.Strings[99484]="不，根本不可能……"
D.Strings[99485]="荒谬！拿我家大人开玩笑？只有疯子才会这么做！"
D.Strings[99486]="……但是如果有人笑得出来，那就一定是他们了。"
D.Strings[99487]="如我所料，无冕者来救我了。"
D.Strings[99488]="记住……别在那里待得太久，好吗？"
D.Strings[99489]="我们得帮忙，卡雷苟斯。这股力量太强大了！"
D.Strings[99490]="你恐怕还不明白他们有多么邪恶，兄弟。我们必须做出万全的准备，否则依然有可能失败。"
D.Strings[99491]="感谢你所做的一切，塞纳苟斯。我们后会有期。"
D.Strings[99492]="我们必须把肖尔从这个牢笼里弄出来。"
D.Strings[99493]="陶矢，把锁撬开。我来对付恶魔。"
D.Strings[99494]="很少有人能在深入黑暗后再安然返回。"
D.Strings[99495]="只有月之守卫通晓强化辛艾萨莉之心的魔法。你一定要救救他们。"
D.Strings[99496]="来，去和萨瑞乌斯他们聊聊。我们需要他们的知识来强化辛艾萨莉之心。"
D.Strings[99497]="让我出去，我可以帮忙。"
D.Strings[99498]="很快就会有机会的。马迪亚斯。"
D.Strings[99499]="还剩一个。"
D.Strings[99500]="怎么了，陶矢？"
D.Strings[99501]="以圣光的名义净化你们！"
D.Strings[99502]="这股力量……这怎么可能？"
D.Strings[99503]="达里安，我的孩子！这是什么意思？"
D.Strings[99504]="看看你都干了些什么！你的盟友们英勇的鲜血玷污了这座神圣的礼拜堂。这都是你一手造成的！"
D.Strings[99505]="很好。那你们邪恶的远征就到此为止了。四骑士休想归来。"
D.Strings[99506]="我是不会让我的儿子变成一个怪物的！"
D.Strings[99507]="这是我们必须背负的重任，我的儿子。"
D.Strings[99508]="死亡领主！你该走了，永远别再回来。"
D.Strings[99509]="我们会复活英勇的逝者，但我们会记住黑锋骑士团的所做所为的。"
D.Strings[99510]="四骑士终于要有个领袖了……"
D.Strings[99511]="快……去……黑锋之门。"
D.Strings[99512]="美美！他们干了什么！？"
D.Strings[99513]="快跑吧！跑得远远的！"
D.Strings[99514]="莎侬……她还好吗？你一定要帮帮其他人！"
D.Strings[99515]="我什么都做不了！他们……杀了他！"
D.Strings[99516]="这简直疯狂！太疯狂了！"
D.Strings[99517]="我从下水道护送马迪亚斯去安全的地方。"
D.Strings[99518]="我们在暗影大厅见，$n。"
D.Strings[99519]="|TInterface\\Icons\\INV_Misc_Herb_Liferoot_Stem:20|t%s正在施放|cFFFF0000|Hspell:212786|h[连根拔起]|h|r，注意邪棘花苗！"
D.Strings[99520]="你必须解决那个威胁，$n！"
D.Strings[99521]="看看我……看看他们都干了些什么！你一定要立刻解决这个威胁！"
D.Strings[99522]="我们必须夺回自己的土地！"
D.Strings[99523]="这都是那个家伙干的！把那些恶魔赶出这片土地！"
D.Strings[99524]="我帮不了他们！"
D.Strings[99525]="看看他们都干了些什么！你一定要阻止他们！"
D.Strings[99526]="我以前从没见过这种东西！我不明白……"
D.Strings[99527]="这……这是什么！？我要怎么……阻止他们！你一定要阻止他们！"
D.Strings[99528]="我的剑！这些血迹……还是新鲜的！我们必须去警告其他人！"
D.Strings[99529]="如果你看到了异常，就要说出来。说给别人。"
D.Strings[99530]="我知道我的风度迷人，让你不能自拔，但是如果你没有事情跟我谈的话，就不应该留在这里。"
D.Strings[99531]="这些小巷很危险。不知道什么时候就会被人顺走财物。"
D.Strings[99532]="我会在有空的时候自己前去拜访凡瑟尔。你如果没事情要我去做的话，就忙你的去吧。"
D.Strings[99533]="我们需要你帮忙“规劝”一些贵族支持莉莉丝争取顾问的位置。你愿意吗？"
D.Strings[99534]="你脸上的表情不是很舒展啊。碰到什么麻烦了吗？你需要我用的……专业技能吗？\n\n<阿鲁因慵懒一笑。>"
D.Strings[99535]="这就是她的计划？勇敢的姑娘。我很乐意帮忙，可……"
D.Strings[99536]="你进入了自由PvP区域！"
D.Strings[99537]="接受火焰的净化！"
D.Strings[99538]="我需要你的帮助，治疗者！"
D.Strings[99539]="请治疗一下我的伤口，这样我才能继续战斗！"
D.Strings[99540]="我受了很重的伤！"
D.Strings[99541]="这些伤口太重，我支持不了多久。"
D.Strings[99542]="我们破译了命令法典。"
D.Strings[99543]="我要继续战斗，直到自己支离破碎为止！"
D.Strings[99544]="告诉我的孩子们，我尽力了，只是由于没有任何英雄来为我治疗，所以我死了。"
D.Strings[99545]="嘿！有人能看看我的伤口吗？我知道你们当中有人能治疗的！"
D.Strings[99546]="大领主，你回来了。还有德拉丝！好久不见，朋友。"
D.Strings[99547]="Ishnu'alah，姐妹。感谢你的热情欢迎。"
D.Strings[99548]="必须摧毁邪焰隘口的传送门。大领主，下令吧，我会和阿拉托尔去解决它。"
D.Strings[99549]="让我陪你一起去吧，姐妹。我会送信去虚空之光神殿，让牧师教团派援军来。"
D.Strings[99550]="你帮我们肃清了要塞，我们仍然欠你一份大人情。我们该怎么报答你呢？"
D.Strings[99551]="冲弗洛格来吧，精灵小怪物们！"
D.Strings[99552]="小心点，萨满。徘徊在那片废墟里的魔古早就死了，可他们的灵魂还在……还有他们留下的陷阱。"
D.Strings[99553]="小心点，朋友。你可能需要花点时间才能赢得堕夜精灵的信任。"
D.Strings[99554]="你一定要向他们讨要艾露迪斯卷轴。只有它才拥有我们需要的信息！"
D.Strings[99555]="这个方法看起来不太对是吧？重新激活盒子，再试一次吧。"
D.Strings[99556]="跟我走。我们直接飞去潘达利亚。"
D.Strings[99557]="就是它！我站在这里都能感应到它！"
D.Strings[99558]="燃烧军团不是唯一能够横渡宇宙打击敌人的势力。$B$B下令吧，$n。我会在这边维持传送门开启的。"
D.Strings[99559]="是时候了。送我们去尼斯卡拉吧。"
D.Strings[99560]="对，对，都在这里头。只要有正确的仪式，我们就能安全地给这颗心注入最强大的魔力！"
D.Strings[99561]="你驯服了%s。"
D.Strings[99562]="很好。可以开始测试咒语了吗？"
D.Strings[99563]="虽然我们人数稀少，但一定会让燃烧军团闻风丧胆。"
D.Strings[99564]="我要杀光你们这些精灵！"
D.Strings[99565]="让我们立刻开始仪式吧。"
D.Strings[99566]="你确定这会管用吗，赛拉娜？"
D.Strings[99567]="我不确定。但为了我们的朋友，必须得试试。"
D.Strings[99568]="你知道自己看到的是什么吗，小个子的外来者？这是蔑潮的命运，那时他们还没有被潮水淹没。\n\n是那个邪恶的海巫海拉，她的怒火吞噬了他们的舰队，她邪恶的迷雾击溃了最强大的维库战士。族长们别无选择，只能放弃大海，因为战斧和长剑无法斩杀迷雾和海水。"
D.Strings[99569]="海拉的国度控制着那些弱者的灵魂，而那些光荣战死的战士将穿过勇者之门面见奥丁，并接受训练，为最后的决战做准备。但海拉，那个心怀嫉妒的女巫，不满足于被分给她的那些灵魂。\n\n于是，她创造了克瓦迪尔。这些生前强大的维库人被她的邪恶魔法扭曲腐蚀。他们永远效忠于她，为她掠夺生者的灵魂，满足她对死亡的无尽渴望。\n\n他们就像一场瘟疫，外来者，纯粹的瘟疫。"
D.Strings[99570]="你对克瓦迪尔了解多少？"
D.Strings[99571]="到秩序大殿里来找我吧。我得为仪式做好准备。"
D.Strings[99572]="在这个悲伤的日子里，总算有点好消息了。"
D.Strings[99573]="矩阵开始震荡了！"
D.Strings[99574]="一定有办法保护辛艾萨莉之心不受军团魔力的冲击。我有主意了。"
D.Strings[99575]="在离开礼拜堂后不久，我们抵达了邪焰隘口。这本日志记录了我们的旅途。"
D.Strings[99576]="德拉丝应约带来了教团的牧师与我们并肩战斗。我们的部队相处甚欢。"
D.Strings[99577]="牧师们也在找巴纳扎尔。他们的领袖，先知维伦预见了那个恐惧魔王将毁灭艾泽拉斯。"
D.Strings[99578]="燃烧军团还没发现我们。他们的首领，蛛后艾拉米丝每天都在营地里转悠。"
D.Strings[99579]="进攻定在明天。愿圣光保佑我们。"
D.Strings[99580]="我们低估了军团的狡诈！我军进攻后，传送门突然启动。巴纳扎尔出现并撕碎了我们的防线。"
D.Strings[99581]="我们还活着，可被他们带过了传送门……前往他们的世界。那边会有什么呢？"
D.Strings[99582]="我逃脱了片刻。如果谁发现它，你就是我们获救的唯一希望。"
D.Strings[99583]="我可是很能打的！"
D.Strings[99584]="盯紧他们！别让他们离开你们的视线！"
D.Strings[99585]="我向你们保证——这绝不会是我们今天干掉的最后一头恶魔！"
D.Strings[99586]="让他们看看你们的本事吧！为了联盟！"
D.Strings[99587]="奥丁的勇气跟他的胃口一样大。他是个真正的战士。"
D.Strings[99588]="上尉，你这是在瞎胡闹。你这种情况根本没法返回战场。"
D.Strings[99589]="别发牢骚了！你的士兵都训练有素。他们能做到的。"
D.Strings[99590]="够了！这么大喊大叫地只会让你的伤势恶化！"
D.Strings[99591]="你必须得把这个责任交给他们了！现在，这是他们的战争了！"
D.Strings[99592]="你需要休息，而且你的士兵们都经过了良好的训练。现在，坐好别动。"
D.Strings[99593]="上尉！你一定要好好休息！如果你再不听话，我就让那个恶魔亲自来修理你！"
D.Strings[99594]="准备战斗吧，勇士。即使是瓦拉加尔也不敢如此靠近海拉的国度。"
D.Strings[99595]="等等……是你吗？哈！你来了，我的凡人朋友。你帮我击败了洛肯，现在又指挥了奥丁的大军！"
D.Strings[99596]="你是谁？这是什么意思？"
D.Strings[99597]="伊利达雷的存在让我觉得不安。自从我弟弟陨落后，他们就被囚禁了起来。"
D.Strings[99598]="我理解，亲爱的。但既然玛维释放了他们，那局势一定比我们所知的还要糟糕。"
D.Strings[99599]="为了抢夺伊利丹大人的遗体，燃烧军团攻破了守望者地窟。现在，遗体已落入古尔丹之手。"
D.Strings[99600]="那个怪物要为这种亵渎行为付出代价！"
D.Strings[99601]="谢谢你。我们不能让神圣的传世之宝落入这种怪物的手中！"
D.Strings[99602]="我带来了紧急消息，陛下。你的处境很危险！"
D.Strings[99603]="她往那边去了！欧恩哈拉想让你跟着她。"
D.Strings[99604]="站起来吧，勇士！"
D.Strings[99605]="我很高兴欧恩哈拉祝福了我们。我之前还担心鲜血图腾惹恼了她。现在我们可以前往风暴峡湾了！"
D.Strings[99606]="以圣光的名义，你将再次浴火重生！"
D.Strings[99607]="我想它是来帮忙的。看她的翅膀——噢！谢谢你！"
D.Strings[99608]="大领主！这边！"
D.Strings[99609]="打得好！可我担心那不过是沧海一粟。我们得解决剩下的威胁，勇士们！"
D.Strings[99610]="看来又有援军到了！"
D.Strings[99611]="啊，一个$c！你来得正是时候！"
D.Strings[99612]="这样才叫$c！看看那身盔甲！我以前从没见过那么出色的护甲！看来这个恶魔死到临头了。"
D.Strings[99613]="又有勇士赶来了！做好准备！"
D.Strings[99614]="鹰身人会肆意破坏她们占据的森林。去跟她们战斗，赶走这些入侵者吧。"
D.Strings[99615]="我们决不能容忍鹰身人这么邪恶的敌人。他们的存在就是一种腐蚀，而腐蚀必须得到净化。"
D.Strings[99616]="石血鹰身人正在使用黑暗魔法把埃洛瑟尔助祭变成石头！请救出我们高贵的盟友。"
D.Strings[99617]="你解救了许多助祭，但是鹰身人依然步步紧逼。我们如果要保护这片土地，就必须保持警惕。"
D.Strings[99618]="许多高贵的英灵仍在生者的土地上行走，但拉文凯斯领主被诅咒的追随者已经没救了。你最好在他们强攻鲑鱼溪之前击败他们。"
D.Strings[99619]="幽灵的势力被削弱了……但这是暂时的。死人就不能好好死掉吗？"
D.Strings[99620]="这次那些林精太过分了！他们居然捕捉和猎杀可爱的小月翼精灵龙。去吧！把它们救出来！"
D.Strings[99621]="精灵龙太珍贵了！看到有人保护它们，我很宽慰。"
D.Strings[99622]="梦魇对月神殿的攻击无休无止。我们必须伸出援手，保卫这个神圣之地。"
D.Strings[99623]="梦魇像流脓的伤口一般渗入了现实。但你击退了黑暗，至少暂时如此。"
D.Strings[99624]="黑林德鲁伊在用植物对付我们！如果放任不管，更多的森林就会落入这些叛徒手中！"
D.Strings[99625]="扭曲德鲁伊魔法是最让我愤怒的行为。黑林德鲁伊这是罪有应得！"
D.Strings[99626]="虫爪鹰身人攻击了暗影沼泽。谢天谢地，幸存者安全逃离了！但如果你能找回他们过去生活中的一些回忆，就是为他们做了件大好事。"
D.Strings[99627]="真正的英雄，并不只是对魔法的掌握，或是对战斗的熟稔，最重要的是扶助他人的意愿。今天，你证明了自己的英雄之心！"
D.Strings[99628]="鹰身人想要诅咒我们森林里优雅的猫头鹰。快行动！我祈祷你们还来得及阻止他们……"
D.Strings[99629]="你把猫头鹰从可怕的命运中拯救了出来。真是高尚！"
D.Strings[99630]="鲑鱼溪的人民真可怜！他们为了逃脱狼人诅咒而离开吉尔尼斯，现在又要面对拉文凯斯领主麾下的兵痞。他们的村子需要你的保护。"
D.Strings[99631]="虽然我们有些分歧，但鲑鱼溪那里的仍是我的同胞。感谢你帮助了他们。"
D.Strings[99632]="一种肮脏的毒药渗入了薄雾谷的水域。直觉告诉我，这一定是某个腐化的德鲁伊干的。把亵渎者找出来，终结这场痛苦。"
D.Strings[99633]="怎么会有人的内心如此扭曲，以至于污染了这么漂亮的湖泊？好在你拨乱反正了。"
D.Strings[99634]="传说中的叶须来了！他是个古老的灵魂，能讲述上古之战的动人传说。专心点，你或许能学到一些宝贵的知识，帮助你击败燃烧军团。"
D.Strings[99635]="上古之战中发生了许多伟大的战役，就像刚刚的那场一样。当时，全艾泽拉斯的守护者合力打败了恶魔，这次也会的。"
D.Strings[99636]="世界树的根被梦魇腐蚀了。净化感染沙拉尼尔的腐蚀吧。"
D.Strings[99637]="我们迟早会夺回沙拉尼尔，并净化世界树的根须。我们要奋战到底，为瓦尔莎拉带来黎明！"
D.Strings[99638]="梦魇的爪牙还在亵渎月爪谷。击退它们吧，勇士！"
D.Strings[99639]="山谷中黑暗依然肆虐，但你带来了一束希望之光。我感激不尽。"
D.Strings[99640]="我们的守护者和树妖盟友都被梦魇的潜伏之力扭曲了。你要终结他们的痛苦。"
D.Strings[99641]="失去梦境的仆人令我难过，但他们至少安息了。我要感谢你。"
D.Strings[99642]="真是场激烈的战斗！去帮助霍迪尔吧，我来给你断后。"
D.Strings[99643]="虽然我们唤醒了被困在沉眠者地穴中的德鲁伊，但梦魇又卷土重来了。把污染那里的秽邪住民干掉！"
D.Strings[99644]="萨维斯的腐化触须无处不在！沉眠者地穴需要净化！"
D.Strings[99645]="林荫山谷的熊以温顺著称，可我感觉它们有些不安。据说附近出现了林精……我感觉他们又在恶作剧了！"
D.Strings[99646]="爱捣蛋的小鬼！你狠狠教训了那些林精，这些熊又能平静地生活了。"
D.Strings[99647]="所有人都必须团结起来，才能击败燃烧军团。"
D.Strings[99648]="拉维斯，让我看看你的本事吧。"
D.Strings[99649]="是时候了，死亡领主。提里奥·弗丁在等着呢。"
D.Strings[99650]="回阿彻鲁斯。来吧，骑士们，缚魂仪式在等着我们。"
D.Strings[99651]="哪怕是对你而言，下一个任务可能也太过危险了，小个子的外来者。先好好磨练一下再回来找我吧。\n\n只有这样，你才有可能战胜纳格法尔号并活下来。"
D.Strings[99652]="恐惧之根曾经是片美丽的林地，但是如今却被梦魇的怪物占据。简直不可容忍！"
D.Strings[99653]="这里被邪恶侵染的伤口也许永远无法痊愈，但我们仍要竭尽全力。"
D.Strings[99654]="劣魔一般不与外界来往，但他们最近胆子变大了，竟敢攻击灰野熊怪部族！我担心他们马上就会侵占整个村子。"
D.Strings[99655]="我们必须维护这片森林的安宁。灰野部族一直都是瓦尔莎拉居民的盟友，你应该帮助他们。"
D.Strings[99656]="枭兽是神圣之地的庇护者，但如果切断了与月神之光的联系，它们就会非常好斗。将树妖从他们的手中救出来吧！"
D.Strings[99657]="它们居然会杀死树妖并把他们转化为怪物……我从不知道枭兽会施展这种恶毒的魔法！幸好你阻止了它们。"
D.Strings[99658]="这就是塔尔艾什。这位就是我的勇士。"
D.Strings[99659]="我可不用躲在勇士的身后。我要亲手捍卫自己的名誉。"
D.Strings[99660]="想死就来大殿顶上见我吧，小崽子。"
D.Strings[99661]="我们得阻止纳格法尔号，可你还不够强大。"
D.Strings[99662]="等你准备好迎接挑战时再回来吧，外来者。"
D.Strings[99663]="一切都在按计划进行。你不用担心。"
D.Strings[99664]="我准备好面对科恩了。"
D.Strings[99665]="我会改进你的伪装，让你能像我们一样战斗。"
D.Strings[99666]="帮我赢得胜利吧。"
D.Strings[99667]="拿下这座塔楼！格雷迈恩的部队必将在部落的力量面前四分五裂！"
D.Strings[99668]="这些狗在面对真正的力量时就畏缩了。这座塔楼属于部落！"
D.Strings[99669]="部落又占领了属于我们的守望高塔。去让他们看看联盟的怒火吧！"
D.Strings[99670]="随着我们在群岛上的推进，被遗忘者的阵线必将支离破碎。前进吧，为了联盟！"
D.Strings[99671]="我好像弄丢了我的强化伪装……"
D.Strings[99672]="真希望能避免这种悲剧，但你做得很好。"
D.Strings[99673]="你准备好之后，我就送你回酒馆。"
D.Strings[99674]="凡人$r。你太唐突了，居然敢召唤我。"
D.Strings[99675]="炎魔之王拉格纳罗斯曾用你手里这种腕轮囚禁过我。"
D.Strings[99676]="而你们这些贪婪的凡人释放我，只是为了攻击我，偷走我的武器和力量。"
D.Strings[99677]="但既然大地之环帮助我归来，我还是决定展现一下我的耐心。你的任务或许并不是那么愚蠢。"
D.Strings[99678]="把腕轮给我，我可以用它们来对付炎魔之王和它的爪牙。我也会回报你的善意的。"
D.Strings[99679]="那就这么说定了，$r。不要再召唤我了。"
D.Strings[99680]="你以前也得到过这种腕轮。你将我从那个永恒的监狱中放了出来，只是为了寻求我的力量。"
D.Strings[99681]="鉴于你们曾经对我做过的事，以及你们偷走的东西，我应该打倒你。"
D.Strings[99682]="这边走。大灾变时，我在瓦丝琪尔的深海中呆了好几个月，它就像我的第二故乡。"
D.Strings[99683]="我们失踪的萨满，波涛语者安德莉在消失前，追踪潮汐权杖来到了这座海底之城。"
D.Strings[99684]="如果我们能找到她，那权杖也就不远了！"
D.Strings[99685]="这座古城曾是卡利姆多的明珠之一。去挖地三尺，找到安德莉。"
D.Strings[99686]="那是安德莉的法杖。唔。它指向了深渊之喉。也许莎拉达尔就在那里？我让她不要孤身犯险的……"
D.Strings[99687]="安德莉提到过一块强大的海浪之石。我现在明白她的意思了。它能防止耐普图隆察觉持有者的举动，让那个纳迦悄然潜入了他的国度。"
D.Strings[99688]="幸好安德莉的日志是用防水的鱿鱼墨汁写的。里面记载了她搜寻权杖的过程。我得研究一下——把它给我。"
D.Strings[99689]="线索表明安德莉跟踪权杖进入了深渊之喉。她的踪迹很明显……但这太容易了。我们可能踏入了陷阱。"
D.Strings[99690]="我们得前往深渊之喉的潮汐王座，权杖就在那里。我们得小心点——我担心耐普图隆的国度可能已经沦陷了！"
D.Strings[99691]="|TInterface\\Icons\\Sha_Ability_Mage_FireStarter_nightmare:20|t%s正在施放|cFFFF0000|Hspell:191325|h[腐化之息]|h|r！"
D.Strings[99692]="你……得到了强大的奥丁的祝福。我完全没想到会是这样！"
D.Strings[99693]="感谢你的帮助，艾希迪尔。请原谅，我们还有几只恶魔要对付。"
D.Strings[99694]="谢谢你，朋友。愿圣光保佑你。"
D.Strings[99695]="被他们带着穿过传送门时，我还以为我们死定了呢。谢谢你，$c。"
D.Strings[99696]="我一直都相信自己会得救的。谢谢你。"
D.Strings[99697]="我从未放弃希望，$c。谢谢你。"
D.Strings[99698]="我的祈祷终于得到了回应。谢谢你，$c。"
D.Strings[99699]="没想到会是白银之手的人来救我们。谢谢你和你的骑士团。"
D.Strings[99700]="谢谢你，大领主。为了白银之手！"
D.Strings[99701]="很高兴见到你，$n。愿圣光保佑你。"
D.Strings[99702]="荣耀与正义与你同在，大领主。我会继续为骑士团而战的！"
D.Strings[99703]="我这就动手！"
D.Strings[99704]="卡里杜斯准备好了！"
D.Strings[99705]="指挥官，阿隆索斯——抱歉打断一下，我带来了重要的消息。"
D.Strings[99706]="很好，德拉丝。一旦你获得任何有用的信息，请立刻返回神殿。"
D.Strings[99707]="你在召唤狂风？"
D.Strings[99708]="好的，伙计。我明白了！"
D.Strings[99709]="我将为师傅带来荣耀！"
D.Strings[99710]="我会完成任务的！"
D.Strings[99711]="提瑞斯秘法会必胜！"
D.Strings[99712]="废话少说，该行动了！"
D.Strings[99713]="我能给你的只有痛苦！"
D.Strings[99714]="你救不了他的——他现在已经生不如死了！"
D.Strings[99715]="啊！我投降！"
D.Strings[99716]="有人命令我把他扔给了肉食动物。你现在只能找到他的骨头了！"
D.Strings[99717]="我会想办法解决的！"
D.Strings[99718]="要出发了，男爵！我们走！"
D.Strings[99719]="小心，$r。夜之子受到了鼓动，正在离开他们城市的边境。"
D.Strings[99720]="夜眼又出去巡逻了。希望他这次能一路平安。"
D.Strings[99721]="夜眼去侦察动物园了。但愿他能照顾好自己！"
D.Strings[99722]="他们将成为我的猎物！"
D.Strings[99723]="不用再说了！"
D.Strings[99724]="尝尝痛苦的滋味吧！"
D.Strings[99725]="我会去达拉然找个地方来破译这些符文石。"
D.Strings[99726]="这头野兽逃出来了！干掉它！"
D.Strings[99727]="没有野兽能与军团抗衡！"
D.Strings[99728]="苏伊什逃出来了！武装起来！"
D.Strings[99729]="蠢货们！苏伊什已经从动物园逃跑了！"
D.Strings[99730]="杀了它！马上！"
D.Strings[99731]="这是详细的旅行日志。看来燃烧军团正在扭曲虚空里肆虐……可是为什么呢？"
D.Strings[99732]="我认识这地方。这是……虚空之光神殿？军团打算入侵牧师的总部？"
D.Strings[99733]="这是先知维伦的投影！他可能有生命危险。"
D.Strings[99734]="用武力可以恢复城市的秩序！"
D.Strings[99735]="任何公开反对主人的，都会被消灭！"
D.Strings[99736]="你是来找他的？你休想过去！"
D.Strings[99737]="快走，碾碎所有胆敢抵抗军团的人！"
D.Strings[99738]="我们找了这座虚空之光神殿几百年！而它就躲在我们鼻子下面！"
D.Strings[99739]="我们终于发现了它。圣光照破虚空，闪耀刺眼！"
D.Strings[99740]="现在，我们即将发动攻击，神殿必将毁灭……先知维伦将给它陪葬！"
D.Strings[99741]="敌人可能用了魔法来误导我们！不要放松警惕！"
D.Strings[99742]="神殿……必将……毁灭……"
D.Strings[99743]="是时候扳回劣势了。"
D.Strings[99744]="德拉丝，天呐，你还活着！"
D.Strings[99745]="你回来了！我还以为自己要死了呢。"
D.Strings[99746]="不会的，朋友。圣光是团结的。"
D.Strings[99747]="等你做好突袭暗夜要塞的准备后再来找我吧。在此之前，我和萨瑞乌斯会继续完善计划。"
D.Strings[99748]="阿拉托尔，你还活着吗？"
D.Strings[99749]="对，我没事。那个鬼母靠得太近了。"
D.Strings[99750]="你该回传送门那儿去。剩下的就交给我和大领主吧。"
D.Strings[99751]="暗夜井中淌出了一颗衰减时间粒子。"
D.Strings[99752]="我和萨瑞乌斯制定了一个突袭暗夜要塞的详细计划。"
D.Strings[99753]="我到前头去帮助其他人。我们要一起离开这儿，姐妹。"
D.Strings[99754]="他们背叛了我们。他们死定了。"
D.Strings[99755]="正在释放"
D.Strings[99756]="暗夜井中溢出了一颗枯竭的粒子。"
D.Strings[99757]="我要离开这条该死的船！我要立刻回我妈妈身边去。"
D.Strings[99758]="要在敌人中间找到一个盟友恐怕并不容易。"
D.Strings[99759]="你该去面对黑暗化身本人……古尔丹了。"
D.Strings[99760]="每周只能拿一件物品，头儿。这是规矩。"
D.Strings[99761]="在大魔导师指派好顾问之前，你绝对不能离开我的视线。答应我！"
D.Strings[99762]="谢谢你。去告诉莉莉丝，我是支持她的。"
D.Strings[99763]="这是我们唯一能够导出碎片中能量的地方：月光熔炉。"
D.Strings[99764]="当然了！但整座要塞里全是夜之子。"
D.Strings[99765]="那我想我们只能请他们离开了。"
D.Strings[99766]="我来护送辛艾萨莉之心，我们要塞里见。月之守卫应该已经占领了那一带。"
D.Strings[99767]="回家的感觉真好，哪怕只是暂时的。"
D.Strings[99768]="等你准备好，我们就动手。"
D.Strings[99769]="让痛苦来与我对话吧。"
D.Strings[99770]="一起……战斗？那好吧。"
D.Strings[99771]="成功了。真的成功了！"
D.Strings[99772]="谢谢，真是一段不可思议的旅程。如果你还想冒险的话，你知道该到哪儿去找我。"
D.Strings[99773]="我的耐心有限。在开战前，快把你的美食给我，否则你今天休想得到我的祝福！"
D.Strings[99774]="想要得到我的祝福，连你也得完成英灵殿的古老试炼，瓦拉加尔。"
D.Strings[99775]="至于你，我的瓦拉加尔……干得好。非常好！"
D.Strings[99776]="我们恐怕时间不多了，英雄。拉基什还在这里——只有阻止他，才能让我的人民重获和平。"
D.Strings[99777]="我知道你千里迢迢赶来找我，是为了传达一个可怕的消息。"
D.Strings[99778]="你掌握着一件至关重要的东西。能让我看看吗？"
D.Strings[99779]="<将神秘的缚光物体放在地上。>"
D.Strings[99780]="你下次再想把剑架在别人脖子上时，最好掂量清楚对手是谁。"
D.Strings[99781]="现在我们扯平了。生意还是一切照旧。你可以随意使用坩埚。"
D.Strings[99782]="暴风城的情况比我们想的还要糟。我们制定了拆穿迪瑟洛克那个骗子的计划。肖尔大师？"
D.Strings[99783]="特塞斯会送我们去港口，我们必须潜入军情七处，绝不能飞进去，迪瑟洛克在屋顶上安排了狙击手，而且我们的脸都上了悬赏布告。"
D.Strings[99784]="首先，我要向你们表达我的谢意。谢谢你们冒着生命危险来救我。"
D.Strings[99785]="我保证你们不会为这个决定而后悔的。我的建议要危险得多。"
D.Strings[99786]="陶矢说的对。局势非常危急，而且还在快速恶化中。联盟即将对部落发动袭击。"
D.Strings[99787]="迪瑟洛克伪装成我的样子，在暴风城的新国王耳边滔滔不绝地说着有关部落的谎言。我们必须阻止他，否则就太迟了。"
D.Strings[99788]="我的计划很简单：潜入暴风城，拆穿迪瑟洛克，然后杀了他。"
D.Strings[99789]="谢谢你，肖尔大师。计划就是这样。大家同意吗？"
D.Strings[99790]="发现燃烧军团的工事！就在塔伦米尔西南边的田野里！摧毁它！"
D.Strings[99791]="联盟的战士们——都上坐骑！西边的山里挤满了恶魔渣滓！"
D.Strings[99792]="东点哨塔遭到攻击！"
D.Strings[99793]="快向南点大门派遣援军！"
D.Strings[99794]="又一头恶魔！在东点哨塔！我们要尽可能地挡住它！"
D.Strings[99795]="一头该死的大恶魔冲进了我们在南海镇的营地。我们急需援军。"
D.Strings[99796]="能让我看看吗？"
D.Strings[99797]="快动手吧！我宁愿死，也再不想为你的扭曲信仰出力了！"
D.Strings[99798]="我已不再使用他们的名义，价值观也不同了。"
D.Strings[99799]="我只想帮助我的牧师同伴对抗燃烧军团。"
D.Strings[99800]="真没想到——血色牧师会出现在我们的神殿里。"
D.Strings[99801]="在这个年代，我们无法拒绝任何人的帮助。欢迎你成为我们的新盟友。"
D.Strings[99802]="你给了我一个自我救赎的机会，我会用我的生命去努力尝试的。"
D.Strings[99803]="只要你有需要，暗影就会在你身边。"
D.Strings[99804]="说吧，德拉丝，你发现了什么？"
D.Strings[99805]="恶魔杀害了我的大部分萨满。我们退到了这里，准备背水一战。$B$B<努波顿叹了口气。>"
D.Strings[99806]="石化的软泥怪已经在魔法回廊涌肆虐了好几个星期了。去解决它吧！"
D.Strings[99807]="我一直在和奥伯妮·亮鬃以及她的组织首领合作。我们破译了燃烧军团在邪焰隘口建立入侵基地的计划。"
D.Strings[99808]="我想带一小队牧师陪同圣骑士们去搜索那里。如果那恐惧魔王真的在那儿，我们一定能找到他。"
D.Strings[99809]="站住！只有牧师才能踏入这座神殿。"
D.Strings[99810]="请让我进去吧。我有德拉丝·月牙的消息！"
D.Strings[99811]="愿圣光指引你的道路。"
D.Strings[99812]="你不是这条路上唯一的人。"
D.Strings[99813]="魔法回廊散逸的魔力制造出了一个怪物！快去在它造成更大的威胁前解决它吧！"
D.Strings[99814]="奥术师纳兰还没有从魔法回廊回来。去看看他出什么事了，再回来向我报告。"
D.Strings[99815]="我的灵魂将与虚空融为一体！"
D.Strings[99816]="找到为这些大厅供能的钥石。它蕴含的魔力能帮助到我们！"
D.Strings[99817]="谢谢你，牧师。沉重的黑暗消失了。"
D.Strings[99818]="一股瘟疫正在魔法回廊肆虐。快在它进一步扩散前净化它！"
D.Strings[99819]="启航前往暴风城。"
D.Strings[99820]="你是说德拉丝？"
D.Strings[99821]="快住手！"
D.Strings[99822]="我能为你做些什么吗？"
D.Strings[99823]="我想征召一些追踪者。"
D.Strings[99824]="我想征召一些游侠。"
D.Strings[99825]="多亏了你，魔法回廊距离昔日的辉煌又近了一步。"
D.Strings[99826]="我从没想到蛇可以长得这么大！你救了我们所有人。"
D.Strings[99827]="要不是你帮忙，我们可能就要失去奥术师纳兰了。谢谢你。我欠你一份人情。"
D.Strings[99828]="这块钥石能确保我们战胜大魔导师。我们不会忘记你的努力的。"
D.Strings[99829]="多亏了你，瘟疫不会继续扩散了。"
D.Strings[99830]="我讨厌我这张乌鸦嘴。"
D.Strings[99831]="我已经毛骨悚然了。"
D.Strings[99832]="你有什么毛病？把魔力酒全洒在我身上了！"
D.Strings[99833]="什么都没有！给你10秒钟时间给我道歉，否则我把你揍趴下！"
D.Strings[99834]="对不起。我没看到你。我本来……"
D.Strings[99835]="嗯，既然必须这样，我也只好……"
D.Strings[99836]="偷袭！"
D.Strings[99837]="你不该小看小人物。我们也有很多……花招。"
D.Strings[99838]="抱——抱歉。我没看到……"
D.Strings[99839]="没看到什么？"
D.Strings[99840]="我再给你些酒吧，请不要伤害我。"
D.Strings[99841]="你真是个弱者，对我卑躬屈膝，只想逃避真正的战斗。"
D.Strings[99842]="该教训你一下了。只有强者才能生存！"
D.Strings[99843]="圣光之母！我……我很抱歉。我不知道。"
D.Strings[99844]="我会边走边解释的。你准备好了就说一声，但请抓紧时间。"
D.Strings[99845]="你带给我的东西名为圣光之心。它是纳鲁的始祖：泽拉的感知核心。"
D.Strings[99846]="她的……后裔。沃洛斯……不！"
D.Strings[99847]="哈！敲打能让它发出美妙的音乐！多么可爱的生物！我很乐意毁掉它。"
D.Strings[99848]="这场入侵只是一个障眼法。我们像牲畜一样被赶到了一起，而这正中他们的下怀。现在，他们已经找到了沃洛斯——圣光之母最后的子嗣！"
D.Strings[99849]="鼓起勇气，英雄。我们必须尽快行动！"
D.Strings[99850]="你准备好去救援沃洛斯后，就告诉我一声，我们立刻就出发。"
D.Strings[99851]="你准备好从拉基什手中救出沃洛斯，并解开圣光之心中的秘密了吗？"
D.Strings[99852]="我准备好了，维伦！"
D.Strings[99853]="在我们出发前，你还能告诉我什么有关泽拉和那个纳鲁的事吗？[我穿上了我的红衬衣，戴上了巫师帽]"
D.Strings[99854]="在我们出发前，你还能告诉我什么有关泽拉和那个纳鲁的事吗？"
D.Strings[99855]="王座厅里有恶魔！保护国王！"
D.Strings[99856]="打碎他们的传送门！把燃烧军团赶出去！"
D.Strings[99857]="看了你的剑，我忍不住要想，它变成斧子后会不会变得更强。那把斧子应该是什么样子呢？到底有没有这么一把斧子的存在呢？"
D.Strings[99858]="有能和斯多姆卡媲美的斧子吗？"
D.Strings[99859]="一定会有的。像灭战者一样强大，但更擅长劈砍的斧子。一定会有这么一把斧子的！"
D.Strings[99860]="那是开启雷神宫殿的钥匙吗？你是从哪儿弄来的？\n\n看来老交情的份上，我很乐意再去一次雷电之王的藏宝库。下令吧。"
D.Strings[99861]="让我们去雷神岛用掉这把钥匙吧。"
D.Strings[99862]="我们可能活不过今天，朋友们。但即便如此，我们也要英勇地战死！"
D.Strings[99863]="伊米隆国王被击败了。他战斗起来很勇猛。"
D.Strings[99864]="<奥丁大笑了起来，笑声低沉而浑厚。>$B$B你真是个狡猾的家伙，$n。你说得对，这个主意很有趣。那就这样吧！"
D.Strings[99865]="我想让他加入我们的军队。"
D.Strings[99866]="那不可能。$B$B伊米隆国王背叛了他的人民，把他们变成了被诅咒的存在。$B$B虽然他是英勇战死的，可我还是很讨厌他。相信他也同样讨厌我。"
D.Strings[99867]="话虽如此，但强迫他用余生为你效劳难道不是更好的惩罚吗？"
D.Strings[99868]="你的剑真是不可思议。我很好奇，有没有能配得上它的斧子。"
D.Strings[99869]="有时，我们最好走上战场，亲眼看看战争。这样，我们的战局才能好转。"
D.Strings[99870]="这并不意外。伊米隆是个残酷而邪恶的统治者，但他战斗时总是很勇猛。"
D.Strings[99871]="我今天是来和艾泽拉斯的敌人战斗的。我可不想把力气浪费在你身上。你想干什么？"
D.Strings[99872]="你是部落有史以来最伟大的战士之一。你的奥金斧让敌人闻风丧胆。"
D.Strings[99873]="大家有些言过其实了。我是来拯救艾泽拉斯和部落的。我感觉你是带着目的来的。你想要什么？"
D.Strings[99874]="<将海尔加的要求告诉萨鲁法尔。>"
D.Strings[99875]="你们太看得起我了，我很荣幸。我确实经历过不少战斗。"
D.Strings[99876]="战斗爆发时，我正在寻找风行者将军。$b$b你有什么需要吗？"
D.Strings[99877]="你也经历过不少战斗，或许是该看看你如今的实力了。让我们决斗一次吧，然后我就帮助你的铁匠。"
D.Strings[99878]="你准备好之后，就派信使来告诉我一声吧。我会来的。"
D.Strings[99879]="安度因国王要我前往达拉然。你能帮我开一座传送门吗？"
D.Strings[99880]="我读过一本由一个专业商人所写的书，里面详细记载了灰烬使者的事。\n\n这本书基本已经散佚殆尽了，残破的书页早就消逝在了风中。\n\n我在想，某个地方会不会还藏着那么几本呢？如果我们能把它拼回去的话，肯定能有所发现！"
D.Strings[99881]="我这就帮你开启。然后，我就去向游侠将军报告我的发现。祝你好运！"
D.Strings[99882]="虽然我无意帮助你们联盟增强实力，但燃烧军团的威胁太大了，我们不能错过任何可能的机会。"
D.Strings[99883]="修女，你能帮我看看这些吗？它们可能就是那本书里散落的残页！"
D.Strings[99884]="我知道你的事迹，但在满足你的要求前，我必须亲眼看看你的实力。我们来次决斗吧。"
D.Strings[99885]="<爱尔达仔细地翻看着书页，快速扫视着有些褪色的文字。>\n\n圣光在上，大领主——我想你是对的！这肯定就是那本书！\n\n我应该可以把它们拼合起来——请稍等我一下！"
D.Strings[99886]="我为什么要被带回来为你而战呢？"
D.Strings[99887]="你看起来很满意。你找到合适的战士了吗？"
D.Strings[99888]="<将萨鲁法尔和他的要求告诉海尔加。>"
D.Strings[99889]="欢迎来到达拉然！我很乐意为你做任何事。"
D.Strings[99890]="我们这儿就有合适的地方。到荣耀之环去吧。我会派一个瓦格里去接引这位萨鲁法尔的。"
D.Strings[99891]="我必须把你带来的消息转告议会。祝你好运，$n！"
D.Strings[99892]="这要不了多少时间。噢，这真是太激动人心了！"
D.Strings[99893]="我们回暗影大厅见吧。"
D.Strings[99894]="我会印刷一个副本留作存档，这样你就可以留下这个全本了，大领主。"
D.Strings[99895]="太神奇了。这个纳特·帕格听起来是个很出色的冒险者啊！"
D.Strings[99896]="啊哈！成功了！"
D.Strings[99897]="你应该去找找更了解这本书的人。我认为它暗示了一件比“钓鱼”更加重大的事！"
D.Strings[99898]="我来了。别再浪费时间了！"
D.Strings[99899]="很高兴见到你，朋友。我可以挡住他们，但我担心很快就会涌过来更多。"
D.Strings[99900]="够了！你已经证明了你的能力。我会满足你的要求的。"
D.Strings[99901]="你好啊，$g帅哥:靓妹;！如果你要去达拉然巨坑的话，最好小心点，摔下去可不得了。\n\n我手头正好有几架滑翔机。如果你有需要的话，我可以卖一架给你。\n\n10金一架。\n\n我们不接受退款！"
D.Strings[99902]="当然，我要一架。"
D.Strings[99903]="我看到了一场精彩的战斗！萨鲁法尔大师，我相信$n选择你是正确的。现在，能让我看看你和你的斧子吗？"
D.Strings[99904]="好的，不过我从来没见过哪个铁匠是这么干活儿的。"
D.Strings[99905]="知识丰富的铁匠总能看到细节。刃口的划痕还有陈旧的斧柄表明了战斗的激烈程度，以及它最常被击中的地方是哪里。看看你轻易举起它的样子。自如的握姿说明你有多年的经验。虽然它无法被重铸，但我可以在打造新武器时，在恰当的地方改进一下，让持有者的攻击更加精准，生存能力更强。"
D.Strings[99906]="明智的选择！你一定要在落地前使用它。否则它就没用了。"
D.Strings[99907]="元素感应到了这里的骚动。保护好你自己！"
D.Strings[99908]="一个地精滑翔器工具包的价格为："
D.Strings[99909]="这只是个开始。枯法者很快就会被如此庞大的能量吸引过来的。"
D.Strings[99910]="为什么不都说说呢，阁下？如果你能给我详细讲讲这本书和灰烬使者的事，我可以告诉你黑龙奈法利安是怎么死的。"
D.Strings[99911]="拜托，英雄，我们不能再浪费时间了！快来！"
D.Strings[99912]="好险啊。我以为他们不会停下呢。"
D.Strings[99913]="什么？！夜之子在攻击我们！"
D.Strings[99914]="这是我的最后一点力量了。接受它，去消灭这些叛徒吧！"
D.Strings[99915]="这应该是最后一批了。我可以用最后一点力量逃出去。再见了，朋友们。"
D.Strings[99916]="啊，对，我听说奈法利安死了，如果我能亲眼看到他悲惨的下场就好了。要不是被困在这座大厅里，我或许会去拜访一下他的巢穴的。 \n\n也许以后会的。\n\n至于我们的交易么，灰烬使者的故事始终都是我的最爱。\n\n<王子瞥了一眼你的武器，微微一笑。>\n\n可你看来已经很熟悉这个传说了。"
D.Strings[99917]="那这本书呢？你能告诉我它是什么意思吗？"
D.Strings[99918]="很多年以前，一个人类法师给了我这本书。他一直想要说服我帮助他，唠叨着什么以火攻火的鬼话。\n\n可你知道，我无法离开这个地方，所以我后来就没再见过那个怪人了。我想他应该是去找他的盟友了吧。\n\n但你不是第一个询问这本书的人。我在想……"
D.Strings[99919]="还有谁来找过你？"
D.Strings[99920]="如果我没记错的话，那是个牛头人——我通常很少犯错。\n\n他带着一本跟你一样的书来到这里，但他拿不出那头黑龙已死的证据，所以我一个字都没说。他很想知道灰烬使者的下落。\n\n如果你能找到他的话，他或许可以给你进一步的线索。"
D.Strings[99921]="如果我没记错的话，那是个矮人——我通常很少犯错。\n\n她带着一本跟你一样的书来到这里，但她拿不出那头黑龙已死的证据，所以我一个字都没说。她很知道灰烬使者的下落。\n\n如果你能找到她的话，她或许可以给你进一步的线索。"
D.Strings[99922]="你知不知道这个巫师制造出了什么东西，才招致了这样的命运？"
D.Strings[99923]="奥杜尔的大军，听从奥丁的召唤吧！"
D.Strings[99924]="父亲！我们曾发誓响应迦拉尔之角的召唤，可现在不行。"
D.Strings[99925]="奥杜尔的殿堂被燃烧军团占领了。我们正在奋勇搏杀，可他们简直无穷无尽。"
D.Strings[99926]="我不知道。\n\n据说只有十字军才知道真相，但他们已经被全部消灭了。\n\n也许你该到他们曾经的要塞里去，自己寻找答案。"
D.Strings[99927]="恐怕我也不知道。\n\n只有那些杀死他的十字军才知道真相，但他们中没有人能活到现在把真相揭示出来了。\n\n如果是我，就到他们曾经的要塞去寻找答案。"
D.Strings[99928]="托里姆……孩子！坚持住！我会派我的勇士去帮你。"
D.Strings[99929]="诸位！今天，多亏了瓦拉加尔的新任战争领主，我们首次在燃烧军团的世界里赢得了一场决定性的胜利。"
D.Strings[99930]="<其中有一部分比其他的要陈旧一点。>\n\n……那个讨厌的巫师比我想的更加坚强。\n\n不过，向他展示圣光的怒火已经成了我这几周以来最大的乐趣之一。这已经便宜了那个异教徒——谁会想用我们渴望消灭的暗影来创造如此邪恶的东西呢？！\n\n我就知道他这种人靠不住。"
D.Strings[99931]="向瓦拉加尔致敬，向战争领主致敬！"
D.Strings[99932]="<翻页。>"
D.Strings[99933]="我不能在这里解决那个可怜虫；如果他被人发现，就会引起注意。这只会让我伟大的工作变得更加复杂。\n\n不……我有个更好的主意。我要把他带去死神的家门口，把他丢在瘟疫之地。\n\n河边有一只非常邪恶的软泥怪，绝对能让这个卑鄙的叛徒死无全尸……如果我能找到那只该死的怪物的话。"
D.Strings[99934]="现在的孩子一点都不懂得尊重文献。我做学徒的时候可是很重视它们的！"
D.Strings[99935]="为了收集信息，我找遍了整个世界！我把一切都写了下来，包括一些琐事。我见过不可思议的奇人异事，$G小子:丫头;。绝对超出你的想象！"
D.Strings[99936]="我写下了这个组织的故事。可那个该死的学徒把它们都弄丢了。全丢了！我跟你说，这真是太荒唐了。他用一页几个铜板的价钱把它们给卖了！"
D.Strings[99937]="我把这本买了回来，可其他的早就丢了。为了它，我可是大出血了，那个该死的蠢货几个铜板就把它们卖掉了，买回来的时候我花的可是真金白银！我找遍了各地，但除了一些流言，其他几卷的下落仍然不明。我这把老骨头已经没法再像从前那样去冒险了。"
D.Strings[99938]="我同意，$n。"
D.Strings[99939]="呸，真不懂得尊重老人。"
D.Strings[99940]="你干了什么？"
D.Strings[99941]="那很好啊。"
D.Strings[99942]="我不应该相信它们吗？"
D.Strings[99943]="你写了什么？"
D.Strings[99944]="这太可怕了。"
D.Strings[99945]="走开。我没时间招待你。"
D.Strings[99946]="啊，灰烬使者还活着。真神奇。"
D.Strings[99947]="你不用在这里大打出手，圣骑士。我伤害不了你，跟你想要摧毁的那些黑暗生物也毫无瓜葛。"
D.Strings[99948]="你疯了吗？除了能让我揪掉胡子之外，这事儿远远称不上好。"
D.Strings[99949]="我想你大概不知道。我们原本是不会碰面的。\n\n我的故事很简单。你那把剑最初的持有者最终没能抵挡住威胁这个世界的无穷亡灵大军。\n\n于是我决定采用另一种方式……一种万无一失的方式。"
D.Strings[99950]="<接过书。>"
D.Strings[99951]="什么方式？"
D.Strings[99952]="所有导管都激活了。你能放大供给器吗？"
D.Strings[99953]="我发明了一种用天灾军团的魔法来对付天灾军团的方法。它的步骤很简单，真的——我从暴怒的巫妖王手下抢来了一大票灵魂供我驱使。\n\n最终，我创造出了一个与驱动灰烬使者的圣光圣物完全相反的东西。可还不等我找到一把合适的剑来把它封印进去，我就被伊森利恩和他的走狗发现了。\n\n后来，就像人们常说的那样，就是极端的痛苦。"
D.Strings[99954]="那颗水晶怎么样了？"
D.Strings[99955]="在被慢慢吞噬之前，我做了两件事。\n\n第一件，很明显，就是实践我的死灵知识，将我的灵魂封印在你发现的那个护命匣里。它对死亡的痛苦毫无帮助……但它起到了应有的作用。\n\n然后，在我被那个怪物吃掉一半的时候，我将水晶扔进了你边上的那条河里，希望有人能用它来对抗黑暗力量。\n\n<这个巫妖的脸扭曲了起来，形成了一个疑似微笑的表情。>\n\n如果你想找它，可以去那里找。"
D.Strings[99956]="你知道吗，我很怀念自己有血有肉的日子。也许我们能想想办法？"
D.Strings[99957]="不，下等人。我绝对不干。"
D.Strings[99958]="不错……不错。可为什么是绿眼睛？我的是灰色的。"
D.Strings[99959]="我感觉附近有个黑暗的存在……"
D.Strings[99960]="你也感觉到了吗，大领主？情况有些不对劲。"
D.Strings[99961]="我发现了一块黑暗但强大的水晶，玛克斯韦尔。\n\n如果我们能控制它的力量，它或许能帮我们对抗燃烧军团。"
D.Strings[99962]="我明白了。\n\n我相信你的智慧，大领主，但我不知道自己能不能接受这种事。\n\n我们怎么能确定那玩意儿里的力量不会……改变你？"
D.Strings[99963]="没有影，就没有光。我们应该在两者间达成平衡。"
D.Strings[99964]="你说得对，但我们怎么安全地吸取它的力量呢？我们的力量只会……\n\n<泰罗索斯顿了顿。>\n\n黑锋骑士团。"
D.Strings[99965]="苏伊什开心地对$n吼了一声。"
D.Strings[99966]="我不配得到你的怜悯。"
D.Strings[99967]="谢谢你，$n。我不会忘记你的善举的。"
D.Strings[99968]="你给了我第二次机会。我不会浪费掉它的。"
D.Strings[99969]="终于自由了！我已经被他们的信仰禁锢了太久了。"
D.Strings[99970]="苏伊什开始紧张地猛烈摇摆。趁她还没把你扔下去，快回头！"
D.Strings[99971]="我知道该怎么帮你，小家伙。"
D.Strings[99972]="我知道该怎么帮你，大咒术师。"
D.Strings[99973]="鳞卫，把他们冻成冰雕！"
D.Strings[99974]="唤潮者，掩护我！"
D.Strings[99975]="大法师瓦格斯，你的力量是从哪儿来的？"
D.Strings[99976]="我想再试一次酿酒挑战。"
D.Strings[99977]="我的任务就是留下来，确保不让燃烧军团渗透大门。"
D.Strings[99978]="你带来了什么消息，女祭司？"
D.Strings[99979]="这确实危险，可若非如此，神殿将不堪一击。我们得团结起来。"
D.Strings[99980]="万一那个陌生人没有遵照诺言赶来怎么办？他可靠吗？"
D.Strings[99981]="你要相信那个陌生人的话？那个长得像恐惧魔王一样的家伙？"
D.Strings[99982]="巴纳扎尔肯定没想到会受到激烈抵抗。或许我们能彻底干掉他。"
D.Strings[99983]="虚空神殿已危在旦夕。白银之手的骑士们，让我们团结起来与巴纳扎尔决一死战！"
D.Strings[99984]="除此之外，一切都未可知。但愿圣光会回应我们的祈祷。"
D.Strings[99985]="我做好一去不回的准备了。"
D.Strings[99986]="我是古尔丹！我是黑暗的化身！这不……可能。"
D.Strings[99987]="该让这个恶魔猎手的灵魂回到躯体中……防止军团之主占据它了！"
D.Strings[99988]="你才打倒了一颗棋子，就想挑战他的主人？真是傲慢！"
D.Strings[99989]="见证即将降临的阴影吧，见证即将吞噬这世界的无边黑暗吧。"
D.Strings[99990]="成为黑暗的载体吧！"
D.Strings[99991]="感受心魔的……力量吧！"
D.Strings[99992]="看着你们所熟悉……并为之奋斗的一切覆灭吧！"
D.Strings[99993]="这……怎么……可能？"
D.Strings[99994]="他差点……就占据了……这个泰坦……"
D.Strings[99995]="你们就这点能耐吗？"
D.Strings[99996]="太迟了！我是不可阻挡的！"
D.Strings[99997]="苏伊什跑过来喝了口水。"
D.Strings[99998]="现在，我要说说斯科瓦尔德是怎么窃取王位，以及背叛养育他的母亲的。"
D.Strings[99999]="就这样，神王斯科瓦尔德踩着亲人的鲜血崛起了。"
D.Strings[100000]="去死吧，伪王的走狗！"
D.Strings[100001]="这次，那个假神王也救不了你们了！"
D.Strings[100002]="斯科瓦尔德必败！"
D.Strings[100003]="愚蠢的孩子。你以为你的邪恶伎俩能帮你抵挡我的怒火吗？"
D.Strings[100004]="就算你谋杀了你的父亲和兄弟。你也没有资格统治我们的人民！"
D.Strings[100005]="你准备好之后，就回去面对梦魇的力量吧。然后，我们会计划下一步的行动。"
D.Strings[100006]="你……不再是……我的儿子了……"
D.Strings[100007]="不，母亲。我是你们的王！"
D.Strings[100008]="请慎重选择。破碎群岛的命运就掌握在你的手中。"
D.Strings[100009]="我们很可能有去无回。迪瑟洛克肯定在等着我们。你准备好了就说一声。"
D.Strings[100010]="圣光指引着我的剑！"
D.Strings[100011]="好好挖掘你内心深处的力量吧。"
D.Strings[100012]="我以艾露恩的名义而战！"
D.Strings[100013]="愿圣光指引我。"
D.Strings[100014]="军情七处见。祝你好运，$n。"
D.Strings[100015]="我们分头潜入。继续前行。遇到麻烦时，就利用那些干草垛。"
D.Strings[100016]="你成功了！我为你开启了返回的传送门。快！我只能让它维持一会儿。"
D.Strings[100017]="你们！请帮帮我，听听我的请求吧！"
D.Strings[100018]="谢谢你们。我与自然沟通后回到了这里。我们必须净化这一带的邪恶力量。"
D.Strings[100019]="哦不！乌索克的灵魂又被控制了？快，朋友们，我会尽力帮忙的！"
D.Strings[100020]="原谅我……我们太弱小了……"
D.Strings[100021]="我们是被逼不得已的……我只希望我们今天没有做错。谢谢你们，朋友们。"
D.Strings[100022]="站住。接受检查。"
D.Strings[100023]="准备接受审查。"
D.Strings[100024]="侦测到可疑个体。"
D.Strings[100025]="出示你的身份。遵守命令。"
D.Strings[100026]="正在扫描奥术精华……"
D.Strings[100027]="|TInterface\\Icons\\Spell_Shadow_SoulGem:20|t一个|cFFFF0000|Hspell:209489|h[古尔丹之眼]|h|r锁定了你！"
D.Strings[100028]="我真的很紧张，万一我掉下去怎么办？"
D.Strings[100029]="我已经等不及要遨游云海了。"
D.Strings[100030]="我真的不太习惯这种……"
D.Strings[100031]="这是我们做过的最恐怖的事！"
D.Strings[100032]="我在想，如果我想吃虫子怎么办……"
D.Strings[100033]="啊，伟大的大自然！"
D.Strings[100034]="我们将在你的指挥下背水一战，勇士！准备好了就说一声。"
D.Strings[100035]="在滑翔的过程中，注意寻找能够让你浮空的热气流。这种体验对你来说可能有些陌生，但你慢慢会习惯的。"
D.Strings[100036]="使用你的尾羽来控制方向。你可能还不习惯使用这块肌肉，不想撞树的话，就多练习一下吧！"
D.Strings[100037]="其他鸟类可能会喜欢上你的新形态。小心……它们的求偶行为。"
D.Strings[100038]="你的喙不仅仅可以聊天，你要多用它来清理羽毛，否则你身上可能会爬满跳蚤！"
D.Strings[100039]="注意，你可能会非常想吃虫子。我必须要强调——不要吃，你会后悔的。"
D.Strings[100040]="你展开双翼后，要用它们兜住迎面而来的气流，让你自己上升。"
D.Strings[100041]="你可能需要一点时间来适应双眼的新位置。最好在栖木旁边练习。"
D.Strings[100042]="你去哪儿了？没去哪儿！"
D.Strings[100043]="轰！出其不意！"
D.Strings[100044]="我不会让那些异端得逞的。\n\n领袖的灵魂虽然迷失在了虚空中，但我们会保存好她的身躯，等待她的归来。"
D.Strings[100045]="当领袖归来之时，遗忘之影必将再次崛起。"
D.Strings[100046]="哎哟，那下看起来很疼啊。"
D.Strings[100047]="艾泽拉斯从未面对过燃烧军团的全部实力，但依靠勇气和努力，黑锋骑士团必将赢得胜利。"
D.Strings[100048]="别担心，头儿。我会给它们献花的。"
D.Strings[100049]="现在，摆个胜利的姿势吧！"
D.Strings[100050]="好了，干掉那些穿裙子的。"
D.Strings[100051]="记住，一定要在大路上战斗。傻子才会去当靶子呢。"
D.Strings[100052]="我已经开始打旗子了！我们赢了吗？"
D.Strings[100053]="我们每干掉一个敌人，都要摆个酷帅的姿势。"
D.Strings[100054]="谢谢你，陌生人。狂怒……腐蚀消失了。现在我得去照看水域了。我已经好久没有去了。"
D.Strings[100055]="让开！未来的角斗士来了！"
D.Strings[100056]="纯粹的生命精华……但愿这点能足够。"
D.Strings[100057]="[松了口气]……平衡恢复了。阿坎多尔不会再衰退了。"
D.Strings[100058]="我们会担起这个重任的，山谷行者。有点信心。"
D.Strings[100059]="援军就快到了！"
D.Strings[100060]="大领主，你的马鞍已经备好，随时可以上战场！"
D.Strings[100061]="霍斯瓦尔德邪恶的秘术师还在腐化阵亡战士们的灵魂。进入这个我和我的姐妹们不敢踏足的地方，摧毁他们堕落的黑暗符文吧。"
D.Strings[100062]="谢谢你，勇士。如果让那些秘术师继续胡作非为，那些黑暗符文还会夺取无数其他瓦拉加尔的灵魂。"
D.Strings[100063]="欢迎光临我们简陋的医务室。你有伤口需要处理吗？还是来找补给品的？"
D.Strings[100064]="生效啊，该死的。快！"
D.Strings[100065]="成功了！这力量定能让燃烧军团方寸大乱。"
D.Strings[100066]="我是出城来找我的女儿的。她是敢于反抗艾利桑德的人之一……"
D.Strings[100067]="她已经过世了。我以为我也会和她一样，变成废墟中无脑的行尸，可你……"
D.Strings[100068]="你救了我。"
D.Strings[100069]="现在，我得去找个容身之处了。但愿我们后会有期，朋友。"
D.Strings[100070]="骑士们，邪恶的命运在等着我们！返回阿彻鲁斯。"
D.Strings[100071]="泰尔安将军……他是上古之战的英雄之一。他死而复生了，可失败的痛苦令他发了疯。去让他永远地安息吧。"
D.Strings[100072]="干得好。我对此深感悲痛，但我们不得不这么做。"
D.Strings[100073]="某些自然的造物没有活下去的资格。老寡妇在黑鸦堡垒里筑了巢。快去杀了它！"
D.Strings[100074]="多么可怕的怪物。想到它我就发抖。"
D.Strings[100075]="在蒙昧时期，我们曾肆意实验魔法。加里昂很聪明，但这里的邪恶魔法逼疯了他。我们必须阻止他。"
D.Strings[100076]="他的力量必须得到遏制。你做得很好。"
D.Strings[100077]="巴萨卡斯是个邪恶的燃烧军团指挥官，连恶魔都害怕他。据说，他会杀掉那些不值得他尊重的弱小恶魔。为了艾泽拉斯，去杀了他！"
D.Strings[100078]="一头邪恶至极的怪物。你做得很好。"
D.Strings[100079]="|TInterface\\Icons\\inv_misc_trinket6oih_orb4:20|t一个|cFFFF0000|Hspell:211152|h[强化古尔丹之眼]|h|r锁定了你！"
D.Strings[100080]="我的造物将成为你的送葬者！"
D.Strings[100081]="站起来吧，消灭这个入侵者！"
D.Strings[100082]="很好，我要亲手解决你。"
D.Strings[100083]="恶魔正在侵占这座岛屿，你或许该离开了。"
D.Strings[100084]="呵呵，你觉得我是个愚蠢的老兽人，已经衰弱得要去喂狼了吗？\n\n你还在襁褓中的时候，我已经在跟恶魔沟通了。"
D.Strings[100085]="你肯定知道很多内情。你能帮我们击败他们吗？"
D.Strings[100086]="他们不是你的敌人，蠢货。\n\n现在，滚吧。"
D.Strings[100087]="上面出什么事了？有人在战斗吗？"
D.Strings[100088]="他们在楼上，$n！"
D.Strings[100089]="这边！我们得阻止拉基什，拯救沃洛斯！"
D.Strings[100090]="这是什么意思，$n？我以为我们是一伙儿的！"
D.Strings[100091]="愿圣光诅咒他！"
D.Strings[100092]="我才是真正的马迪亚斯·肖尔。"
D.Strings[100093]="不，我才是！杀了他，$n！"
D.Strings[100094]="够了！我需要更多的空间。"
D.Strings[100095]="哟！我今天为你准备了一件特殊的礼物哟！"
D.Strings[100096]="你们的联盟和部落注定要摧毁彼此……"
D.Strings[100097]="我们会占据上风的。"
D.Strings[100098]="我们找了你好久，先知维伦。你以为躲在这里，就能逃过军团的眼睛了吗？"
D.Strings[100099]="现在，你的灵魂终于属于我了！"
D.Strings[100100]="巴纳扎尔，你太傲慢了。但艾泽拉斯的英雄会打败你的！"
D.Strings[100101]="白银之手的圣骑士，靠近大领主！进攻！"
D.Strings[100102]="什么？白银之手骑士团？小意思。我照样能毁灭你们！"
D.Strings[100103]="不错，英雄。让我看看没了盟友，你还有什么本事吧！"
D.Strings[100104]="现在只剩你们了，英雄们。你们没帮手了！"
D.Strings[100105]="够了！厌倦这个游戏了。"
D.Strings[100106]="现在，尝尝燃烧军团的真正力量吧！！！"
D.Strings[100107]="守住阵地！他们休想轻易打垮我们！"
D.Strings[100108]="敌人太多了！"
D.Strings[100109]="这没用！先知的预言实现了……"
D.Strings[100110]="你们的圣光在哪儿呢，英雄们？"
D.Strings[100111]="我还以为他肯定死了……"
D.Strings[100112]="诺瑞莎飞快地扫了一眼信。"
D.Strings[100113]="噢，阿布索伦……"
D.Strings[100114]="盟友们，不要绝望，这里是圣光军团的高阶指挥官洛萨克森。"
D.Strings[100115]="按照大主教图拉扬的命令，我们已经尽快赶来了。我这就派人支援你们。"
D.Strings[100116]="英雄们，站到圣光中来！巴纳扎尔，准备受死吧。"
D.Strings[100117]="谢谢你。我会把他的话记在心里的。"
D.Strings[100118]="不！我不可能被击败！"
D.Strings[100119]="让亿万太阳的烈焰烧死你们！"
D.Strings[100120]="我要看着你们的世界灰飞烟灭！"
D.Strings[100121]="我们成功了。那个恐惧魔王死了。"
D.Strings[100122]="谢谢你们，白银之手的圣骑士。"
D.Strings[100123]="白银之手的骑士们！今天，我们大获全胜！"
D.Strings[100124]="我们击退了燃烧军团，保护了盟友，消灭了敌人！"
D.Strings[100125]="我们证明了我们的意志是经得起考验的！"
D.Strings[100126]="在大领主的带领下，我们绝地反击……并取得了胜利。"
D.Strings[100127]="大领主万岁，白银之手万岁！"
D.Strings[100128]="或许吧，但最近不会，恶魔。"
D.Strings[100129]="结束了。准备好了就跟我说，$n。我把大家送出暴风城。"
D.Strings[100130]="我对你所做的一切感激不尽，$n。你让我重新控制了军情七处，还让联盟和部落避免了一场代价高昂、难以承受的战争。\n\n要不是你，燃烧军团会毁了我们所有人。\n\n没什么好说的，如果我能为你做点什么的话，你尽管开口。\n\n你准备好返回达拉然的暗影大厅了吗？"
D.Strings[100131]="我准备好了。让我们离开这儿吧，马迪亚斯。"
D.Strings[100132]="你已经了解那个卷轴里的所有内容。你太聪明了！"
D.Strings[100133]="让我们向实现这一切的英雄祝贺吧，我们新晋的暗影之刃，$n！"
D.Strings[100134]="迪瑟洛克死了，肖尔又成为军情七处的首领了。"
D.Strings[100135]="联盟和部落的全面战争得以避免。现在，我们可以全力对付燃烧军团了。"
D.Strings[100136]="我们要不择一切手段摧毁他们。不管是用阴谋诡计还是下毒暗杀。如果有必要，我们甚至可以献出生命。"
D.Strings[100137]="将枯木赶出我的王国，我就让你进入我父亲的墓穴。"
D.Strings[100138]="骨语者惊扰了历代先王的尸骨。那些高贵的亡者理应得到安息。去阻止这些叛徒吧。"
D.Strings[100139]="小心抓起"
D.Strings[100140]="早在我的时代之前，长眠于盾憩岛的亡者就不曾受到过打扰。今天，你帮了我的人民一个大忙。"
D.Strings[100141]="海拉加尔在亵渎盾憩岛的陵墓。快去赶走他们！"
D.Strings[100142]="盾憩岛是风暴峡湾最古老的先王和尊贵的亡者长眠的地方。那时，蔑潮氏族还不曾畏惧大海。"
D.Strings[100143]="别老是压榨萨满行吗？"
D.Strings[100144]="邪恶的蛆虫！你只是我兄弟的一条走狗！"
D.Strings[100145]="斯科瓦尔德要为他的背叛付出代价。"
D.Strings[100146]="你认识这件圣物吗？"
D.Strings[100147]="我才是长子，王位是我的。而不是斯科瓦尔德那个小崽子！"
D.Strings[100148]="你是在哪儿找到它的？都已经好多年了……\n\n<达克苏尔翻看着手中的圣物，然后把它还给了你。>\n\n幽灵早已停止了低语。它们已经沉寂了一段时间。\n\n然后它们又响了起来，但发生了变化，变得更深沉，更黑暗。"
D.Strings[100149]="这个核心里锁着智慧……对我们战胜燃烧军团至关重要。"
D.Strings[100150]="泽拉之子以及埃索达的核心——沃洛斯，是整个多元宇宙中唯一能够破译圣光之心里信息的生物。"
D.Strings[100151]="但只有通过她的后裔，我们才能解开圣光之心里的秘密。所以你才会受命将核心带来给我。"
D.Strings[100152]="这也是燃烧军团入侵埃索达的真正目的。"
D.Strings[100153]="跟我说说这些低语。"
D.Strings[100154]="泽拉一脉的末裔，沃洛斯就在埃索达的核心里。如果他们毁了沃洛斯，圣光之心的信息就将彻底失传。"
D.Strings[100155]="我召唤不到他们，蠢货。"
D.Strings[100156]="<达克苏尔的瞳孔收缩，目光涣散。他的头微微抬起，仿佛在倾听着某种你听不到的声音。>"
D.Strings[100157]="达克苏尔？"
D.Strings[100158]="伊瑟拉攻击神殿时，我逃离了瓦尔莎拉。我很走运，在路上遇到了米萨多斯。"
D.Strings[100159]="我们来自沙拉尼尔外的一个村子。我必须承认，那是一次惊险的逃亡。"
D.Strings[100160]="你又恢复正常了。出什么事了？"
D.Strings[100161]="无论我们走到哪里，梦魇总是如影随形。直到穿过苏拉玛后，我们才摆脱了它。"
D.Strings[100162]="那些低语召唤过你。\n\n<达克苏尔深深地叹了一口气，看起来愈发苍老虚弱。>\n\n在这座群岛生活的日子里，我学到了很多。我曾进入过不该进入的地方，发现过想要忘掉的秘密。\n\n现在，我只想一个人呆着，直到黑暗彻底吞噬我。\n\n你走吧。"
D.Strings[100163]="我们出发时，人数要比现在更多。要不是梅鲁娜赶到，我也已经死了。"
D.Strings[100164]="我们欠米萨多斯和他的德鲁伊同伴一条命。多亏了他，我们才能在苏拉玛定居下来。"
D.Strings[100165]="感谢你的帮助，陌生人。它的意义比你以为的更加重大。"
D.Strings[100166]="最伟大的英雄们汇聚一堂，准备面对军团。"
D.Strings[100167]="但只靠英雄是救不了这个世界的。生者付不起救赎的代价。"
D.Strings[100168]="四骑士的时代到来了……而你将让他们归来。"
D.Strings[100169]="首先，就是阵亡的部落将军纳兹戈林。去吧，完成这个任务。"
D.Strings[100170]="该让第二名骑士回归了，死亡领主。"
D.Strings[100171]="在阿拉索的悬崖上，屹立着陨落的激流堡王国。"
D.Strings[100172]="你可以在那里找到伟大的战士索拉斯·托尔贝恩的墓穴。"
D.Strings[100173]="他的战斗力无人能及。而在死后，他将变得更加强大。"
D.Strings[100174]="站出来，挑战本届的锦标赛冠军吧！胜利者将获得丰厚的奖品！免责声明：某些奖品可能不怎么丰厚。"
D.Strings[100175]="干得好！继续努力，孩子，你正在走向胜利……还顺便帮我赚了一堆金币！"
D.Strings[100176]="你带来了厄运，牧师。"
D.Strings[100177]="大检察官怀特迈恩是个牧师。个人的悲剧造就了她对圣光的狂热。"
D.Strings[100178]="你仔细想过洛肯最后对你说的那段话吗？"
D.Strings[100179]="她狂热的意志对于加强四骑士间的联系至关重要。"
D.Strings[100180]="去血色修道院的大教堂，将这位高阶审判官从墓穴中唤起吧。"
D.Strings[100181]="在四骑士中，必须有一位领袖。"
D.Strings[100182]="没有领袖，四骑士就无法团结一致。"
D.Strings[100183]="黑锋骑士团该重返圣光之愿礼拜堂了。"
D.Strings[100184]="伟大的提里奥·弗丁就长眠于礼拜堂的地下。"
D.Strings[100185]="去吧，做你该做的事。"
D.Strings[100186]="本次锦标赛将限时推出一只艾泽拉斯的传奇生物。快来考验一下你自己的实力吧！"
D.Strings[100187]="放轻松……放轻松！留点给其他参赛者吧，行吗？"
D.Strings[100188]="先是我的推土机趴窝了，然后那些家伙就追了过来……我再也不到这儿来瞎转悠了！"
D.Strings[100189]="噢呵呵！你发现了一位锦标赛的流动训练师！你又获得一次展示实力，并帮我挣钱的机会！"
D.Strings[100190]="别人说，我对锦标赛的比赛下注严格来说是“非法”的。但只要神不知鬼不觉，这又有什么不好的呢！"
D.Strings[100191]="我的宫廷和盟友需要帮助。你的朋友们或许能帮忙。"
D.Strings[100192]="干得好！我代表我的宫廷和盟友感谢你，英雄。"
D.Strings[100193]="有东西威胁着瓦尔莎拉的生物。也许你可以让你的伙伴们来帮帮忙。"
D.Strings[100194]="梦魇依然感染着瓦尔莎拉的森林，但是你和你的伙伴们也为保护它作出了贡献。"
D.Strings[100195]="我们必须保护好自己的土地。但愿你的伙伴们都准备好了！"
D.Strings[100196]="谢谢你。在防御时，我们必须保持警惕。"
D.Strings[100197]="是时候考验一下你和你的同伴了。你是否有资格获得瓦拉加尔的青睐呢？"
D.Strings[100198]="你显现出了巨大的潜力。"
D.Strings[100199]="帮助堕夜精灵的办法有很多。你的小伙伴们也能派上用场。"
D.Strings[100200]="你的努力保障了堕夜精灵的未来。"
D.Strings[100201]="马林，我发现了这枚硬币，上面有你的名字。"
D.Strings[100202]="这就叫互惠互利！再去仓库里挑一样东西吧，$n。"
D.Strings[100203]="达里安·莫格莱尼为黑锋骑士团牺牲了一切。"
D.Strings[100204]="而他就支离破碎地躺在你面前。"
D.Strings[100205]="但死亡只能威胁生者，它对亡灵毫无意义。"
D.Strings[100206]="你的第四位骑士就在你面前，死亡领主。让他站起来吧。"
D.Strings[100207]="赤蹄期待地看着米萨多斯。"
D.Strings[100208]="噢，我的天，真是一朵稀有的花。"
D.Strings[100209]="谢谢你，高贵的赤蹄。我们接受你的祝福，并对此表示感谢。"
D.Strings[100210]="神圣风暴会消耗三层神圣能量。"
D.Strings[100211]="使用神圣风暴！"
D.Strings[100212]="好吧。在跟指挥官谈完正事前，你可以留在这里做客。"
D.Strings[100213]="我会把祝福直接带给米萨多斯。我们在那里见面吧！"
D.Strings[100214]="你的宠物已经死亡！使用复活宠物将它复活。"
D.Strings[100215]="那……是什么！？"
D.Strings[100216]="那东西……我必须离开这儿！"
D.Strings[100217]="你……你是谁？"
D.Strings[100218]="我在哪儿？出什么事了？"
D.Strings[100219]="那种感觉。我说不清楚！"
D.Strings[100220]="离开这儿！快！"
D.Strings[100221]="消失能让你脱离战斗，并快速逃离战场。"
D.Strings[100222]="这口月亮井会滋养并保护它周围的一切。我们终于可以把这里称为家园了。"
D.Strings[100223]="你可以在盾憩岛的山上发现裂天龙。这些幼龙强大、古老而且疯狂。去召集盟友打倒一头裂天龙吧，这也是为它们好。"
D.Strings[100224]="裂天龙都曾是可敬的风暴幼龙，受命守护盾憩岛。可现在，它们被海拉的黑暗魔法影响，陷入了疯狂。"
D.Strings[100225]="这个研究太神奇了！我这就把破译出来的历史写在这本书上。"
D.Strings[100226]="如果你想阅读一下自己武器的有关历史的话，我刚刚在这本书里添加了新内容。"
D.Strings[100227]="随着研究的深入，我会不断添加新内容的。如果你有时间的话，它还是很值得一看的。"
D.Strings[100228]="我又添加了你那把武器的新历史。如果有时间的话，你应该去看看。"
D.Strings[100229]="我们又发现了一段有关你那把武器的神奇历史。如果你想看的话，我已经把它添加在这本书里了。"
D.Strings[100230]="你这把武器的历史还真是多姿多彩。如果你有兴趣的话，我在书里加入了最新的内容。"
D.Strings[100231]="如果你想看的话，我刚刚又写下了一段有关你那把武器的历史。"
D.Strings[100232]="我在你那把武器的历史故事里加入了新的段落。如果你有时间的话，最好去读读看。"
D.Strings[100233]="好了，就是这样，$n。经过几个星期的研究，我们终于挖掘出了你那把武器所有的历史。"
D.Strings[100234]="感谢你为我们的工作投入了这么多资源。希望我们的发现能对你有用。"
D.Strings[100235]="我刚刚往我们的书里添加了最后一章内容。你一定要读一下。"
D.Strings[100236]="你们这些蠢货。你们真以为圣光会对此视而不见吗？"
D.Strings[100237]="就算是巫妖王本人来了也没用！"
D.Strings[100238]="圣光保护着这座礼拜堂，达里安。圣光绝不容忍任何黑暗！"
D.Strings[100239]="达里安！"
D.Strings[100240]="四骑士……我对此持保留意见，但我听你的，死亡领主。"
D.Strings[100241]="部落会气疯的，但纳兹戈林会成为强大的死亡骑士。"
D.Strings[100242]="索拉斯·托尔贝恩是史上最伟大的君王之一。联盟恐怕不会高兴的。"
D.Strings[100243]="总之，你的意志必将实现，死亡领主。我们很荣幸能将索拉斯国王招至麾下。"
D.Strings[100244]="这世上很少有人能比大检察官怀特迈恩更加坚定。"
D.Strings[100245]="死亡能让发热的头脑冷静下来……相信她会坚定不移地效忠黑锋骑士团。"
D.Strings[100246]="提里奥·弗丁是有史以来最伟大的勇士之一！"
D.Strings[100247]="这么做的话……就得付出代价。"
D.Strings[100248]="那好吧，死亡领主。可是别忘了……"
D.Strings[100249]="一旦这么做，我们就没有回头路了。"
D.Strings[100250]="在再次进入战斗前，你得先等一等，瓦拉加尔。"
D.Strings[100251]="只要我还有一口气在，你就休想打倒我！"
D.Strings[100252]="来人啊！救命！"
D.Strings[100253]="感谢你制止了那些低语。现在，该轮到你来忍受虚空无尽的饥渴哭号了。"
D.Strings[100254]="我会带我们进入飞船的核心。待在我的保护屏障内，我来清除沿途的邪能污染。"
D.Strings[100255]="继续前进吧。"
D.Strings[100256]="太感谢了。我们得继续前进。"
D.Strings[100257]="他们正在这片土地上肆虐！我们必须阻止他们！"
D.Strings[100258]="你真是个厉害的$c，不是吗？谢谢你。"
D.Strings[100259]="快跑！能跑多快跑多快！快！"
D.Strings[100260]="其他人都被抓了。我亲眼看见的。到处都是敌人！"
D.Strings[100261]="牧师！这边！"
D.Strings[100262]="部队音效"
D.Strings[100263]="不准惊扰夫人的财产。"
D.Strings[100264]="求求你……我已经几周没补充过魔力了……"
D.Strings[100265]="魔力……我需要……魔力。"
D.Strings[100266]="科洛恩·夜刃……那个人渣在上古之战中帮助燃烧军团谋杀了拉文凯斯领主！燃烧军团复活了他。快去干掉那个恶棍！"
D.Strings[100267]="就算死上一百次也洗刷不了他的罪孽。干得好。"
D.Strings[100268]="我也要去见我的兄弟姐妹了。再见，莱瑞娅。"
D.Strings[100269]="胜利者出现了！宝箱争夺战到此为止！"
D.Strings[100270]="你该回传送门那去。剩下的就交给我和大领主吧。"
D.Strings[100271]="谢谢，艾希迪尔。我们的确有事。"
D.Strings[100272]="<给奥术师科罗林50份远古魔力。>"
D.Strings[100273]="谢谢你……保重。"
D.Strings[100274]="我……差点就变成枯法者了。靠近点，接受我的魔力吧。它能保护你免受任何伤害。"
D.Strings[100275]="今天，我们战胜了强敌，并让军团明白，艾泽拉斯是不会默默沦陷的。"
D.Strings[100276]="先知维伦，圣光的战士们，真是精彩的大胜。我从不小看艾泽拉斯的英雄。"
D.Strings[100277]="连阿克蒙德的斩杀者都接受了这世界的命运！那就过来吧。"
D.Strings[100278]="你是个怪物，达里安！"
D.Strings[100279]="我们开始吧。拿起权杖，别把自己弄死了。它可是……很难控制的。"
D.Strings[100280]="没有怪物，就没有英雄。"
D.Strings[100281]="唔唔，打得好。"
D.Strings[100282]="别把那玩意儿放进嘴里。你都不知道它是哪儿来的。噢，也别把它塞进他的嘴里！"
D.Strings[100283]="有谁想打个瞌睡吗？……我。"
D.Strings[100284]="这个东西叫做“酒”。莉迪小姐需要它才能熬过这一天！"
D.Strings[100285]="如果你们想要快点长大，升到二十五级的话，就要把宠物饼干吃光哦。"
D.Strings[100286]="如果你们今天都乖乖的，我就读你们最喜欢的故事“奔波尔霸的伟大冒险”。"
D.Strings[100287]="该做手工了咯！等等，谁把浆糊和水钻都吃了？我得叫家长了，万一出问题就糟了。"
D.Strings[100288]="小心点，旅行者。这一带已经不再安全了。"
D.Strings[100289]="勇士们！财富在荣耀竞技场中等着你们！为了荣耀和财富而战吧！"
D.Strings[100290]="瓦拉加尔！胜利或死亡在荣耀竞技场中等待着你！用战斗证明你自己吧！"
D.Strings[100291]="我打了一辈子仗，也没见过这么大的牺牲。"
D.Strings[100292]="圣光破坏了他的遗体。我们救不了他了。"
D.Strings[100293]="大领主！"
D.Strings[100294]="我们经受了意志的考验！"
D.Strings[100295]="大领主万岁，白银之手骑士团万岁！"
D.Strings[100296]="你们太迟了！克洛苏斯将成为你们的送葬者！"
D.Strings[100297]="我才是今天的冠军！为了奥丁！"
D.Strings[100298]="你的敌人从海上派来了援军。让我那些怕水的孩子们看看，该怎么打沉一条船吧。"
D.Strings[100299]=S[6097]
D.Strings[100300]="%s掸了掸衣服。"
D.Strings[100301]="你确定要离开了吗？你该留下来完成训练，$r。"
D.Strings[100302]="我想离开竞技场。"
D.Strings[100303]="敌人就在我们中间！"
D.Strings[100304]="你发现得太晚了，伊利达雷！魔刃者，攻击！"
D.Strings[100305]="传送门开启了！他们来了！"
D.Strings[100306]="导火索已经点着了。快跑！"
D.Strings[100307]="我已经打扮好了。聚会在哪儿开？"
D.Strings[100308]="你确定要去参加聚会吗？它可能会很远。"
D.Strings[100309]="今天的梭鱼真的很活跃啊！现在钓鱼太危险了。$b$b哈哈，开个玩笑！这是尖头木棍和火药鞋。去抓住那些鱼吧，伙计！"
D.Strings[100310]="今天的梭鱼很活跃啊！"
D.Strings[100311]="听起来不错。我们动手吧！"
D.Strings[100312]="霍斯瓦尔德曾经是一片圣地，现在却被讨厌的渡鸦玷污了。那些肮脏生物的嘴巴太臭。你能去活动一下身体，用爪钩清除一些鸟巢吗？"
D.Strings[100313]="有时，渡鸦真的很粗鲁。你肯定也听过那些粗野的家伙是怎么议论你和你亲戚的。谢谢你清除了它们的巢穴。"
D.Strings[100314]="输入坐标"
D.Strings[100315]="至高岭"
D.Strings[100316]="风暴峡湾"
D.Strings[100317]="苏拉玛"
D.Strings[100318]="那就让议会讨论吧。"
D.Strings[100319]="这次我让奥丁失望了，但我还会重返战场的！"
D.Strings[100320]="现在，去吧。等你证明了自己以后再回来。"
D.Strings[100321]="我们面临一个艰难的抉择。是帮助牧师对抗巴纳扎尔，还是拒绝教团的求援，等待单独与他决战的时机？"
D.Strings[100322]="他们的神殿在燃烧军团的地盘深处。我们需要冒很大的风险。"
D.Strings[100323]="你以为我看不出你的真面目吗，恶魔？"
D.Strings[100324]="没错，但如果洛萨克森说的是真的话，这可能是我们消灭巴纳扎尔的唯一机会。"
D.Strings[100325]="你要相信一个恐惧魔王？"
D.Strings[100326]="我感觉不到他有任何恶意，只有亲切。我不知道他到底是什么，但我相信他。"
D.Strings[100327]="我同意阿拉托尔，波鲁斯。我感觉他的心是纯洁的。"
D.Strings[100328]="这很危险，但良机稍纵即逝。这可能是唯一的办法。"
D.Strings[100329]="巴纳扎尔肯定想不到会遭遇教团和白银之手骑士团的联军。"
D.Strings[100330]="那就这么决定了。"
D.Strings[100331]="我一直在等你，$n。\n\n德拉丝已经把巴纳扎尔攻击虚空之光神殿的消息通知了议会。现在的问题在于，圣骑士要不要参与这场战斗？要的话，我们又该在其中扮演什么样的角色？如果我们选择援助教团，就要冒巨大的风险。\n\n这件事可不能草率决定。我们得召集议会讨论该怎么做。"
D.Strings[100332]="我侦测到，这里有一个奇怪的信号。"
D.Strings[100333]="这是夜之子的魔法……可它在召唤我们。"
D.Strings[100334]="过来。我看到石头上有条裂缝。"
D.Strings[100335]="赶上了！感谢仁慈而荣耀的圣光，我来治疗沃洛斯，然后再对付拉基什。"
D.Strings[100336]="你失败了，拉基什！沃洛斯重生了。现在，你要为你的暴行付出代价！"
D.Strings[100337]="明智的选择，可别叫我“勇士”。"
D.Strings[100338]="|TInterface\\Icons\\spell_nature_web.blp:20|t你被|cFFF00000|Hspell:215288|h[痛苦之网]|h|r缠住了。"
D.Strings[100339]="你想让鲁尔做点什么？"
D.Strings[100340]="你准备好之后，我就启动仪式。"
D.Strings[100341]="啊，命中注定的英雄们赶来了。看来你击败了我，维伦。"
D.Strings[100342]="不经历失败，又怎能理解胜利？来吧，失败和死亡。"
D.Strings[100343]="回头吧。幽灵船无法离开这片水域。"
D.Strings[100344]="但在投降并面对圣光的审判前，我还有最后一件事要做。"
D.Strings[100345]="我们会保护国王不受伤害的。"
D.Strings[100346]="愿艾露恩照亮你的道路，勇士。"
D.Strings[100347]="我的人民会想办法帮忙的！"
D.Strings[100348]="啊！他们来了！快跑！"
D.Strings[100349]="哈！我们会用这些大石头解决他们的！"
D.Strings[100350]="好了！这次总算干掉他们了！"
D.Strings[100351]="啊！我们很抱歉！我们保证！"
D.Strings[100352]="小心点，头儿。外域是个很危险的地方，沙塔斯城也好不到哪儿去。"
D.Strings[100353]="那把剑！它太强大了！"
D.Strings[100354]="小心背后，小心钱包。"
D.Strings[100355]="我闻到了族人的血腥味！"
D.Strings[100356]="我的先祖在尖叫！"
D.Strings[100357]="我被幽灵包围了！"
D.Strings[100358]="这一次的招募速度很快，但以后就需要更多时间了。"
D.Strings[100359]="瓦罗莫克遭到攻击！我们遭到了地狱火的轰炸！"
D.Strings[100360]="我不想吓唬任何人，可一头巨大而丑陋的恶魔刚刚在我们沿海的营地着陆！我们正在阻拦他，可我们需要支援！"
D.Strings[100361]="火箭车的北边！刚刚飞下来了一头巨型金属机械怪物。那到底是什么鬼玩意儿？"
D.Strings[100362]="燃烧军团还在继续进攻！又一头恶魔接近了大门！"
D.Strings[100363]="我发誓！这根法杖活了过来！我一定要搞清楚这是怎么回事！"
D.Strings[100364]="只要再变几只羊！我马上就能解开这件神器的秘密了！"
D.Strings[100365]="胡扯！别相信这个疯子！"
D.Strings[100366]="闭嘴，种田的！"
D.Strings[100367]="你疯了吧，牧羊人！"
D.Strings[100368]="留着你那些童话故事吧！这里不欢迎你了！"
D.Strings[100369]="他把我的家人都变成了绵羊！"
D.Strings[100370]="真的！那头死掉的绵羊是我的堂兄强尼！"
D.Strings[100371]="什么事？有话快说！我还要做实验的。\n\n不！别碰它！"
D.Strings[100372]="你听到什么声音没有？那是……羊叫吗？"
D.Strings[100373]="|TInterface\\Icons\\Sha_Ability_Rogue_EnvelopingShadows_nightmare:20|t%s开始施放|cFFFF0000|Hspell:210264|h[显形腐蚀]|h|r！"
D.Strings[100374]="噢，绵羊！"
D.Strings[100375]="|TInterface\\ICONS\\spell_shaman_earthquake:20|t海底之王泰德罗斯正在施放|cFFFF0404|Hspell:222482|h[海啸]|h|r。躲到掩体后头去！"
D.Strings[100376]="你是谁，陌生人？你不是军团的人。"
D.Strings[100377]="我们是一伙儿的，圣光的战士们。感谢你们放我出来。"
D.Strings[100378]="燃烧军团的大军很快就会袭击虚空之光神殿。我们必须不惜一切代价保住这里。"
D.Strings[100379]="我会带着盟友去保护神殿，可他们还远在天边。我需要你们帮忙挡住敌人，直到我们赶到。"
D.Strings[100380]="没时间详细解释了。你们必须相信我，相信圣光。"
D.Strings[100381]="那就这么定了。白银之手骑士团将援助教团，决不能把神殿拱手让给燃烧军团。"
D.Strings[100382]="燃烧军团在用传送门将恶魔不断送往勇者之门。去吧，勇士，找到那些传送门，然后召唤我们。我的子嗣会摧毁它们的。"
D.Strings[100383]="这应该能阻止如潮的恶魔。谢谢，勇士。"
D.Strings[100384]="*沃洛斯逐渐解体的过程中唱出悲伤的挽歌*"
D.Strings[100385]="告诉大家，一定要对他客气点。否则我们明天醒过来时可能就都死了。你明白我的意思吧？"
D.Strings[100386]="你拥有一件传说中的武器。我发现了一些有关它的历史，并把它们写了下来，以便让所有人了解它的光辉历史。"
D.Strings[100387]="我会继续记录下我的发现的。如果有你时间的话，它还是很值得一读的。"
D.Strings[100388]="这个研究太神奇了！我这就把破译出来的历史写在这个卷轴上。"
D.Strings[100389]="祝你好运，头儿。"
D.Strings[100390]="明智的选择。我一定会确保任务完成的。和你这样的专业人士合作真是愉快，$n。"
D.Strings[100391]="该死！你还要假装没看见吗？"
D.Strings[100392]="啊，巫妖王的代理人。我能为你做些什么吗？"
D.Strings[100393]="伊利丹之手。我能为你做点什么吗，主人？"
D.Strings[100394]="树叶们担忧地窃窃私语着邪能之火和梦魇的降临，但只要你能保持坚定，那我们也不会动摇。\n\n我能帮你什么忙吗？"
D.Strings[100395]="失败可以带来智慧。没有必要害怕我们面前的挑战。"
D.Strings[100396]="暗影低语着各种秘密，只有足够勇敢的人才能听清。"
D.Strings[100397]="风在窃窃私语着你过去和现在的事迹。如果我知道正确的提问方式，就能从它们那里得到许多消息。"
D.Strings[100398]="这真是悲惨的故事，但我很喜欢。"
D.Strings[100399]="<吸鼻子。>谢谢你……"
D.Strings[100400]="我会听话的，我保证！"
D.Strings[100401]="这些石板讲述了奥丁所见证的最波澜壮阔的战斗。\n\n最近，我稍稍了解了一下你们种族的事迹。我没想象到你们这些小个子也能如此勇猛。"
D.Strings[100402]="妈妈，你在哪儿？？"
D.Strings[100403]="风告诉了我很多事，包括最近的和古代的。你那把武器有一个故事。我已经开始撰写了。"
D.Strings[100404]="在研究出更多信息后，我会继续完善这本书的。"
D.Strings[100405]="我已经了解了不少。过去拥有过那把武器的英雄在你手中得到了解脱。他们的传说很值得被永远地刻下来，让强大的战士们了解他们的勇气。"
D.Strings[100406]="在收集整理的过程中，我还会继续把它们刻在石板上的。我已经等不及要把这些波澜壮阔的故事写下来了。"
D.Strings[100407]="好、好……饿啊……"
D.Strings[100408]="去搞清楚军情七处的计划，$n。在这个阶段，我们决不能容忍任何未知的变数。"
D.Strings[100409]="凡瑟尔……凡瑟尔！"
D.Strings[100410]="意识越来越……模糊了……"
D.Strings[100411]="他们想要……杀了我们……"
D.Strings[100412]="跑不掉的……太饿了……"
D.Strings[100413]="算你聪明，$g小子:丫头;。老扬希可不会自己乖乖上船。"
D.Strings[100414]="告诉他，要是没本事拉到足够的水手，他就得用拉壮丁的老办法了。"
D.Strings[100415]="我们得回礼拜堂去，大领主。必须把这消息告诉议会。"
D.Strings[100416]="大领主，我们回职业大厅，还有很多事要讨论。"
D.Strings[100417]="嘿，头儿。你需要什么吗？"
D.Strings[100418]="我已经在石头上刻下了你那把武器的更多历史。"
D.Strings[100419]="我已经刻下了更多的文字。真是个英勇的传说。"
D.Strings[100420]="我已经在石头上刻下了你那把武器的更多传说。"
D.Strings[100421]="我又在石头上刻下了更多的故事。"
D.Strings[100422]="如果你想阅读一下自己武器的相关历史的话，我刚刚在这个卷轴里添加了新内容。"
D.Strings[100423]="我又添加了你那把武器的其他历史。如果有时间的话，你应该去看看。"
D.Strings[100424]="我们又发现了一段有关你那把武器的神奇历史。如果你想看的话，我已经把它添加在这个卷轴里了。"
D.Strings[100425]="你这把武器的历史还真是多姿多彩。如果你有兴趣的话，我在卷轴里加入了最新的内容。"
D.Strings[100426]="我在你那把武器的历史卷轴里加入了新的段落。如果你有时间的话，最好去读读看。"
D.Strings[100427]="我刚刚往我们的卷轴里添加了最后一章内容。你一定要读一下。"
D.Strings[100428]="我刚刚往我们的书里添加了最后一章内容。你应该读一下。"
D.Strings[100429]="风寂静无声，$n。我想我们已经发掘出了你那把武器的所有的故事。"
D.Strings[100430]="最后一段石刻也完成了。你应该读一下。"
D.Strings[100431]="真是一个英雄的传奇，完全配得上这座圣殿和你。作为它的讲述者，我很自豪。"
D.Strings[100432]="我们的旅程到此为止了，瓦拉加尔。我已经了解了你那把武器的一切，以及它所参加过的战争。"
D.Strings[100433]="$n释放了服务器工程师的可怕怒火。"
D.Strings[100434]="汪？"
D.Strings[100435]="我想要施放服务器工程师的可怕怒火。"
D.Strings[100436]="$n放出了一个上古邪神，整个艾泽拉斯都为之颤抖。\n\n饥渴的库苏莫斯将再次行于大地之上……"
D.Strings[100437]="小英雄，我们来跟你一起战死沙场了！但我想我们或许还能赢。总之，我们来战斗了！"
D.Strings[100438]="$g小子:丫头;，你干嘛要丢下我们自己赶来呢？你知道没有法师的传送门，要赶来这座挤满坏蛋的岛有多麻烦吗？"
D.Strings[100439]="这个白痴卡里杜斯非要我带上他。我拒绝了，可他死活要跟来。让我们快点搞定这件事吧，免得我失去耐心，把它烧成灰。"
D.Strings[100440]="$n得到了毁灭之锤——我觉得这是最好的结果了。"
D.Strings[100441]="这是毁灭之锤！请保护好这座城市，$n。"
D.Strings[100442]="$n会解决燃烧军团的。$g他:她;得到了毁灭之锤。"
D.Strings[100443]="那是毁灭之锤吗，$n？萨尔还活着吗？"
D.Strings[100444]="向毁灭之锤选定的拥有者——先知$n致敬！"
D.Strings[100445]="毁灭之锤很合适你，$n。收好它。"
D.Strings[100446]="所以这是真的——$n拿到了毁灭之锤！"
D.Strings[100447]="我很高兴大地之环没有抛弃我们，$n。继续战斗吧！"
D.Strings[100448]="放置封印。"
D.Strings[100449]="你完全接受了圣光，莉亚德琳！看来太阳之井恢复了你的活力！"
D.Strings[100450]="这真可怕。"
D.Strings[100451]="赞美圣光。很高兴见到你，伊莎娜。"
D.Strings[100452]="我们还有机会。"
D.Strings[100453]="使用|TInterface\\Icons\\ability_vehicle_sonicshockwave.blp:20|t |cFFFF0000|Hspell:78675|h[日光术]|h|r打断埃瑞丁的引导！"
D.Strings[100454]="法多雷曾是精灵……现在，他们是怪物，从枯死的阿坎多尔的混乱能量中诞生。我们得消灭他们。"
D.Strings[100455]="别为他们难过。这是我们必须纠正的错误。"
D.Strings[100456]="法兰纳尔地下的阿坎多尔失去稳定，造成了灾难性的后果。用你的磁石收集破碎轨迹的能量，以便我们搞清原因吧。"
D.Strings[100457]="这能帮我们保持阿坎多尔的稳定。我们决不能失败。"
D.Strings[100458]="那家伙的灵魂应该会很有用。"
D.Strings[100459]="又死了一个废物。"
D.Strings[100460]="不堪一击。"
D.Strings[100461]="它有没有认真打？"
D.Strings[100462]="臣服于你的主人吧！"
D.Strings[100463]="我想研究破碎轨迹里的能量。去那里抓一些以水晶为食的小动物来。我要活的！"
D.Strings[100464]="太好了。这让我们离理解阿坎多尔的独特力量又进了一步。"
D.Strings[100465]="燃烧军团大军压境——而艾利桑德就直接放他们进来了。真是恶心。去攻击邪魂堡垒！让燃烧军团看看，不是所有的夜之子都那么软弱的！"
D.Strings[100466]="Ru-shanna shal'dorei。夜之子永垂不朽。"
D.Strings[100467]="这么说，$n拿到了毁灭之锤？我猜部落是要完蛋了。"
D.Strings[100468]="$n手里拿着的是毁灭之锤。荣耀属于联盟！"
D.Strings[100469]="那是毁灭之锤吗，$n？在第二次大战中杀害了安度因·洛萨爵士的那把武器？"
D.Strings[100470]="很高兴看到毁灭之锤落入了联盟之手，$n。"
D.Strings[100471]="传言是真的。$n拿到了毁灭之锤！"
D.Strings[100472]="我想不出有谁能比你更有资格获得那把战锤了，$n。"
D.Strings[100473]="联盟的勇士拿着毁灭之锤？看来世界末日真的要来了……"
D.Strings[100474]="燃烧军团已经开始进攻了。教团需要你的帮助。"
D.Strings[100475]="一万年来，我们躲在一片人造天幕下。现在走了出来，看到的却满是恶魔的天空。使用邪魂堡垒里的火炮击落那些的魔蝠吧！"
D.Strings[100476]="等燃烧军团彻底滚蛋后，我们就能平静地仰望天空了。"
D.Strings[100477]="他们正在城里搜捕无辜的市民。不可原谅！杀了那些士兵，拿走控制宝珠，解放我的人民。"
D.Strings[100478]="你救出的大部分人肯定会被流放。今天，你拯救了许多人。"
D.Strings[100479]="把这些枯法者带到法兰纳尔坍塌的隧道里去。训练他们战斗，并寻找对我们有帮助的圣物吧。"
D.Strings[100480]="我就在另一边等你。祝你好运，$n。"
D.Strings[100481]="欧库勒斯，你能看见他们吗？"
D.Strings[100482]="能，我看见他们了。稍等……"
D.Strings[100483]="稍等，塔莉萨。我给你传了个上锁的箱子过去。"
D.Strings[100484]="我等着呢，欧库勒斯。"
D.Strings[100485]="哇。这箱子真大。"
D.Strings[100486]="小心点，$n。尽量减少我们的损失。"
D.Strings[100487]="小心点。别让这些枯法者出师未捷身先死。"
D.Strings[100488]="精灵杀手？多么可怕的称号。"
D.Strings[100489]="有个枯法者逃跑了。抓住他，别让他迷失在隧道里！"
D.Strings[100490]="看来$n遇到麻烦了，塔莉萨。我这就把他们弄出来。"
D.Strings[100491]="这些可怜的人吃了不少苦头。欧库勒斯，送他们回去。"
D.Strings[100492]="$n！你成功了！"
D.Strings[100493]="没有魔力酒，许多平民就会在这座城里变成枯法者。尽量多弄点酒来，我会照顾好他们的。"
D.Strings[100494]="我能用这些魔力酒救很多人。它们能改变许多人的命运。"
D.Strings[100495]="就连这片土地上的山脉都将在萨格拉斯大人面前崩塌！"
D.Strings[100496]="要保护阿坎多尔不受害虫侵袭，就需要法力浮龙。再去苏拉玛城酒庄抓几只来吧。"
D.Strings[100497]="没有平衡，混乱就会降临。这些浮龙可以保持生态平衡。"
D.Strings[100498]="我的魔力酒足够城里的需要。去找那些无法来我酒馆的人，让他们也喝几口吧。"
D.Strings[100499]="以圣光之名，重生吧！"
D.Strings[100500]="不要放弃，$n！圣光必胜！"
D.Strings[100501]="养活穷人这么简单的事，却被艾利桑德搞得危机四伏。你的英勇是阻止他们沉沦的唯一希望了。"
D.Strings[100502]="如果酒庄的产量不足，受苦的首先就是平民。去帮他们达成目标吧，这样才能维持魔力酒的定量供应。"
D.Strings[100503]="你会成为出色的酿酒师！酒庄又开始定量供应魔力酒了。"
D.Strings[100504]="幽灵般的眼睛盯着我们的一举一动。我们在这片土地上毫无隐私可言，主人。"
D.Strings[100505]="信使们会为城里的军官们传递敏感指令和消息。去拦截他们，拿到他们身上的信件吧。"
D.Strings[100506]="干得好。我会查看这些信件，看看有没有对我们的行动有用的消息。"
D.Strings[100507]="我要你帮我调查一个潜伏在酒馆中的可疑人物。去找到他的藏身之处，远远跟着他，搞清楚他的目的。"
D.Strings[100508]="他一直在监视我们！幸好我们把他揪出来了……大魔导师知道的越少越好。"
D.Strings[100509]="圣骑士们，以圣光为证，让我们协助盟友，保卫神殿！"
D.Strings[100510]="夜之子还在围攻月之守卫的堡垒。去让他们看看，傲慢也要有个限度。"
D.Strings[100511]="决不能让艾利桑德抢走月之守卫的秘密。"
D.Strings[100512]="月之守卫有着训练作战角鹰兽的悠久传统。骑上这头角鹰兽，让正义的制裁从天而降吧！"
D.Strings[100513]="德拉丝，准备好传送门。"
D.Strings[100514]="你的话真让人窝心，$n。我……我不知道该怎么办。我最好还是走吧。告诉威廉，让他注意安全。"
D.Strings[100515]="谢谢，但你是个老练的$c。而我只是个卖面包的！我还是等安全了之后再回来吧。"
D.Strings[100516]="我会让夜之子结束长期的孤立政策，作为艾泽拉斯的保卫者，而不是征服者。"
D.Strings[100517]="艾利桑德的部队打算扫荡整座城市，搜索异见者。如果苏伊什逃出动物园去阻止他们，那就太遗憾了。"
D.Strings[100518]="这会有点疼，死亡骑士。"
D.Strings[100519]="压力减轻了，苏伊什也吃饱了。我们又熬过了一天。"
D.Strings[100520]="邪能灌注在那些急于讨好燃烧军团的人中间很流行。这些叛徒已经没救了——去干掉他们！"
D.Strings[100521]="这就像时尚。将来我们都会奇怪，怎么会有人觉得邪能漂亮。"
D.Strings[100522]="不要放弃！大祭司已经带着援军赶来了！"
D.Strings[100523]="命运指引我来此，或许我能帮上忙！"
D.Strings[100524]="我临死前，看到的将是你们的脸。在我灰飞烟灭前，这将是最后一段痛苦的记忆。我欢迎它的到来……"
D.Strings[100525]="你们自以为赢了？尝尝失败的苦果吧，哪怕我将因此而死！"
D.Strings[100526]="使用|TInterface\\Icons\\spell_deathknight_strangulate.blp:20|t |cFFFF0000|Hspell:49576|h[死亡之握]|h|r来打断埃瑞丁的引导！"
D.Strings[100527]="鹰身人和林精打破了泰安诺神圣的安宁。让我们的先祖重新恢复应有的宁静吧。"
D.Strings[100528]="泰安诺恢复了庄严，我的祖先又能安息了。谢谢你。"
D.Strings[100529]="我们先休息一下，再让神殿恢复它应有的荣耀吧。"
D.Strings[100530]="阿古斯即将喷出你们的末日！灭世者即将装填完毕，并引爆一颗塌缩星辰的力量！我们脚下的世界将化为灰烬！"
D.Strings[100531]="很好。我随时都能为你而战。"
D.Strings[100532]="我欠你一命，大法师。我愿意成为你的勇士，为秘法会服务！"
D.Strings[100533]="我愿意随时为你效力，朋友。让我们一起保护艾泽拉斯吧！"
D.Strings[100534]="我很乐意为提瑞斯秘法会出力，咒术师。我听说过你的事迹。"
D.Strings[100535]="太好了！我会效忠于你和秘法会的！"
D.Strings[100536]="等我当上了头儿，你一定会后悔的！我是说……当上我的头儿，你一定不会后悔的！"
D.Strings[100537]="奥术毁灭者发出几个颤抖的音节，激动地拍起手来。"
D.Strings[100538]="我很荣幸能为你领导的提瑞斯秘法会服务，大法师。让我们为艾泽拉斯而战吧！"
D.Strings[100539]="依靠你的指引和力量，我们赢得了一场原本会毁掉我们的战斗。"
D.Strings[100540]="这不会是最后一次袭击，但我们该思考一下这场胜利，并为今天真正的英雄，我们的大祭司庆贺。"
D.Strings[100541]="向大祭司致敬！"
D.Strings[100542]="是的，我欢迎一切愿意践行圣光之道的人。到勇士大厅来见我吧。"
D.Strings[100543]="抱歉，我还得考虑一下。"
D.Strings[100544]="不用着急，大领主。我的决心是不会动摇的。"
D.Strings[100545]="谢谢你，大领主！我准备好了。"
D.Strings[100546]="好了，让我们开打吧！"
D.Strings[100547]="噢耶，为了联盟！"
D.Strings[100548]="噢耶，为了部落！"
D.Strings[100549]="我会竭诚为你效劳的。"
D.Strings[100550]="我们的敌人将瑟瑟发抖！"
D.Strings[100551]="联盟狂热者很仰慕你。"
D.Strings[100552]="联盟狂热者向你靠近了一点。"
D.Strings[100553]="联盟狂热者为你喝彩！"
D.Strings[100554]="联盟狂热者为你鼓掌。"
D.Strings[100555]="联盟狂热者偷了你一缕头发。"
D.Strings[100556]="主人的圣殿中，有一千个世界阴燃的残骸。而我来到这里，为你们在明天的废墟中预留一个位置。"
D.Strings[100557]="联盟狂热者把你的名字写在一个小爱心上。"
D.Strings[100558]="而我来到这里，为你们在明天的废墟中预留一个位置。"
D.Strings[100559]="部落狂热者很仰慕你。"
D.Strings[100560]="部落狂热者向你靠近了一点。"
D.Strings[100561]="部落狂热者为你喝彩！"
D.Strings[100562]="部落狂热者为你鼓掌。"
D.Strings[100563]="部落狂热者偷了你一缕头发。"
D.Strings[100564]="部落狂热者把你的名字写在一个小爱心上。"
D.Strings[100565]="质疑奥丁可不明智。他说你是头儿，那你就是头儿！"
D.Strings[100566]="不……我的团队……"
D.Strings[100567]="重获新生，重返战场！战斗的荣耀在等着我！"
D.Strings[100568]="这下达戈要发大财了！"
D.Strings[100569]="我宁愿相信是命运让我们走到一起。"
D.Strings[100570]="你是说我们要并肩作战，干掉攻击奥杜尔的恶魔？算我一个！"
D.Strings[100571]="我会将雷霆之怒倾泻到敌人头上！"
D.Strings[100572]="我欠你一份人情。北风愿意为你效劳。"
D.Strings[100573]="不……不！我是伊米隆国王！我不是仆人！"
D.Strings[100574]="我还记得去圣光之愿礼拜堂的路。我去那儿等你。"
D.Strings[100575]="在你的领导下，我们一定会节节胜利的，大祭司。"
D.Strings[100576]="我们要一起摧毁燃烧军团！"
D.Strings[100577]="我们愿意供你差遣。"
D.Strings[100578]="以前，我曾指引我的丈夫古伊尔走上萨满的道路。但他的下一个试炼只能由他独自走完。那你呢？你的道路是什么？$b$b你是要代表自然之力摧毁我们的敌人？还是成为智慧之泉，明察秋毫，完成万灵的愿望？或是成为一个治疗者，抚慰伤痛，提升士气？我告诉你一个真相吧，$n：$b$b真正的萨满必须能达到以上这三种境界。"
D.Strings[100579]="你有天然的生存本能，只有在这个危机四伏的时代才能让它大放异彩。"
D.Strings[100580]="如果你打算带领组织去帮助那些有需要的人，那我一定会不遗余力地帮助你的。"
D.Strings[100581]="你已经跟男爵成为朋友了。所以，你也是我的朋友。"
D.Strings[100582]="赫米特恐怕也不会教得更好了。我随时都愿意跟你出去狩猎！"
D.Strings[100583]="如果必须战斗，那我希望能与你并肩作战。"
D.Strings[100584]="有只巨大的恶魔直接往北城墙去了！别让它攻破大门！"
D.Strings[100585]="难以置信！又有两只恶魔冲哨兵岭来了！一只往南边去了，另一只则去了北门！"
D.Strings[100586]="卫兵有恶魔撑腰，每天都在践踏我的人民。去让他们看看，我们有能力反击！"
D.Strings[100587]="只要有大魔导师部队的地方，我们就会反击！"
D.Strings[100588]="我是来帮助枯法者进行战斗训练的。"
D.Strings[100589]="很好。我们可以在法兰纳尔塌方的隧道里训练。$b$b你准备带几个枯法者去？"
D.Strings[100590]="你确定自己准备好了吗？一旦你将你的枯法者带往法兰纳尔，就不能再将他们带回来了。"
D.Strings[100591]="相信圣光，勇士们！让它的仁慈增强你们的力量吧！"
D.Strings[100592]="枯法者已经准备好了。我们开始吧。"
D.Strings[100593]="哨兵岭的居民们受到了鼓舞，纷纷加入了对抗燃烧军团的战斗！"
D.Strings[100594]="在使用魔法的时候，停摆的钟才是最好的钟！"
D.Strings[100595]="我在哪儿？这是谁的身体？"
D.Strings[100596]="火星，气泡，爆炸，噢耶！"
D.Strings[100597]="祝大家火焰节快乐！"
D.Strings[100598]="蚂蚁！蚂蚁蚂蚁蚂蚁蚂蚁！"
D.Strings[100599]="呜噜哇啦！"
D.Strings[100600]="火星，闪光，气泡！"
D.Strings[100601]="我们有伴儿了！把恶魔打坏的东西都记下来……我要把账单寄给他们！"
D.Strings[100602]="保持警惕，各位！保护好贸易大王的财产，这是你们的神圣使命！"
D.Strings[100603]="又来了！这些恶魔完全不尊重私有财产！狠狠教训他们吧！"
D.Strings[100604]="朋友，很高兴见到你。"
D.Strings[100605]="我今天掌握了一个新法术！"
D.Strings[100606]="来到这里，你是不是和我一样激动呢？"
D.Strings[100607]="今天是个练习魔法的好日子！"
D.Strings[100608]="小心点，朋友。"
D.Strings[100609]="如果你需要我的帮助，尽管开口。"
D.Strings[100610]="我开始头疼了。"
D.Strings[100611]="我觉得执着是一个好品质。"
D.Strings[100612]="你肯定还有更有意义的事要做吧？"
D.Strings[100613]="你没别的地方可去了吗？"
D.Strings[100614]="知识就是力量。"
D.Strings[100615]="再见。如果你遇到什么趣事，一定要告诉我！"
D.Strings[100616]="你再这样，我就让你看看我的剑术了。"
D.Strings[100617]="不要考验我的耐心。"
D.Strings[100618]="随时都有可能发生魔法事故……"
D.Strings[100619]="如果亡灵再人性化一点，就不会那么麻烦了。"
D.Strings[100620]="今年我的植物长势很好。其中的关键就是从一种非常古老的莲花上做了嫁接，你可以称其为母本。这可是一件非常珍贵的财产。"
D.Strings[100621]="我最喜欢的炉石卡牌？那绝对是闪电箭了！"
D.Strings[100622]="我是瓦拉加尔！"
D.Strings[100623]="下次战斗再见。"
D.Strings[100624]="祝你百战百胜。"
D.Strings[100625]="给你的敌人带去死亡吧！"
D.Strings[100626]="什么事？！"
D.Strings[100627]="我们不会战斗……至少今天不会。"
D.Strings[100628]="我的盾坚不可摧。"
D.Strings[100629]="不要撩拨我的战矛！"
D.Strings[100630]="这一次……你要活下去。"
D.Strings[100631]="那你就走吧。"
D.Strings[100632]="战场上见。"
D.Strings[100633]="死亡是无法阻止我的。"
D.Strings[100634]="我侍奉着更强大的力量。"
D.Strings[100635]="我生活在暗影界。"
D.Strings[100636]="有一天，我或许会来接引你的。"
D.Strings[100637]="孩子，你问我是否预见到了这一天。"
D.Strings[100638]="我……我预见到了……但之前，我始终不明白。"
D.Strings[100639]="在久远的过去，我有过一个儿子。在他出生那天，我看到了一个幻象。"
D.Strings[100640]="在幻象中，我抱着一个濒死的艾瑞达哭泣。他的皮肤上布满邪能疱疹与疤痕。"
D.Strings[100641]="就像你一样……"
D.Strings[100642]="但基尔加丹夺走我的家人后，我埋葬了那个幻象。无数年来，它藏在我最黑暗的记忆里。"
D.Strings[100643]="现在，当我抱着你时，我终于明白了。"
D.Strings[100644]="燃烧军团夺走了我的一切。我们的一切。"
D.Strings[100645]="我把我的一切都给了你，从未要求过什么回报！饶我这一次吧！"
D.Strings[100646]="这样的重任并不是我们自己要求担负的，先知，但这是命运的决定。"
D.Strings[100647]="你不是真想派我们的朋友去执行这种任务吧？那是自杀。"
D.Strings[100648]="我亲眼见过阿坎多尔的能量对枯法者的影响。我相信它值得我们冒险。"
D.Strings[100649]="唔。那就让我们拭目以待吧。"
D.Strings[100650]="罗姆尔还活着吗？"
D.Strings[100651]="先知怎么了？"
D.Strings[100652]="我非常享受战斗。"
D.Strings[100653]="我的生命属于白银之手，大领主。"
D.Strings[100654]="我无所畏惧，大领主！为了骑士团！"
D.Strings[100655]="圣光将指引我的道路，大领主。"
D.Strings[100656]="我不会让你倒下的，大领主。"
D.Strings[100657]="我的父母会为我们的成就骄傲的。我会继续为他们而战的，大领主。"
D.Strings[100658]="圣光无处不在。无论荣耀还是死亡，我都会拥抱它。"
D.Strings[100659]="我很荣幸能加入你们，大宗师。我的师傅会为我骄傲的。"
D.Strings[100660]="我欣赏你，德鲁伊。你的灵魂熠熠生辉。你不会把我们引上歧途。"
D.Strings[100661]="要做的太多了……可时间太少了！"
D.Strings[100662]="我们得立刻去紫罗兰监狱，具体的边走边说吧。"
D.Strings[100663]="数百年来，守护者熔炉一直是提瑞斯法议会的强大动力源。"
D.Strings[100664]="在燃烧军团得知熔炉的存在后，议会不得不把它藏到安全的地方去。"
D.Strings[100665]="所以它被秘密送往了紫罗兰监狱。这里不但是全达拉然最安全的地方，也是最隐秘的地方。"
D.Strings[100666]="那个古怪的帅哥是谁？"
D.Strings[100667]="我们以前见过吗？"
D.Strings[100668]="我说，你看起来很眼熟啊……"
D.Strings[100669]="我不信，像这么时髦、年轻又精神的法师，我见过一次肯定不会忘记。"
D.Strings[100670]="现在卡萨纳提尔知道了它的下落，我很担心它的安全。"
D.Strings[100671]="看来我不是杞人忧天！那个恐惧魔王已经进去了。我们快走！"
D.Strings[100672]="赫达沙尔上次突袭至高岭时，抓走了一些俘虏。我想请你帮我把他们救出来。我欠那些人的祖先一个大人情，所以我想报答他们。"
D.Strings[100673]="有蒙面暴徒在骚扰我的支持者。肯定是斯特拉瑞斯家族的畜生！"
D.Strings[100674]="<叹气。>又是这种政治伎俩。或许等我们解放苏拉玛后，我的对手会明白，他们站错队了。"
D.Strings[100675]="在那牛头人的帮助下，我的血肉化为树木，皮肤变成树叶，智慧得以永存。即使我的人民都忘了，我也会牢记这份恩情。"
D.Strings[100676]="没有比大清早来一杯咔啡，或是在经过一天的血战后来一杯冰凉的至高岭冰咖啡更舒服的。在临睡前，我喜欢喝一杯香料茶。你试过配上蜂蜜的羊角包吗？非——常——美味！$B$B至少我是这么觉得的。但你知道吗，我其实不是来谈咖啡的。"
D.Strings[100677]="但愿你们这些英雄买足了弹药！"
D.Strings[100678]="他们来了！该证明你们的价值了！"
D.Strings[100679]="我不喜欢那声音！不管你们是高矮胖瘦……都给我站直了！"
D.Strings[100680]="这群似乎……更多。但这不是懈怠的理由！"
D.Strings[100681]="他们来了！让他们看看，我们可不是懒鬼！"
D.Strings[100682]="我看错了吗？他们是不是更愤怒……更热血了？"
D.Strings[100683]="快干掉这家伙！他在破坏我们的财产！"
D.Strings[100684]="告诉他们，艾萨拉只有一个头儿……那就是我！"
D.Strings[100685]="这恶魔想在我的地盘上撒野。快阻止它！"
D.Strings[100686]="他们散开了！现在，我批准你们进行义务加班……去找到他们！"
D.Strings[100687]="这些恶魔还真是不客气……这是我的地盘！散开，阻止他们！"
D.Strings[100688]="他们在拓展业务！嘿，只有我才能这么干！"
D.Strings[100689]="我们还有很多事要做！别让我发现你们打瞌睡！"
D.Strings[100690]="别放松！你们有义务保护我的资产！"
D.Strings[100691]="我要这些恶魔在晚餐时间前消失。我可不想错过一顿大餐！"
D.Strings[100692]="呃！目前最丑的恶魔！以英俊的贸易大王之名，战斗吧！"
D.Strings[100693]="这家伙想当头儿！抱歉，伙计，这位子……是我的！"
D.Strings[100694]="干掉带头的！把它的脑袋……还有钱包拿来给我。尤其是后者！"
D.Strings[100695]="我们反败为胜了！干得好！但我还是会给你们寄损坏赔偿账单的。"
D.Strings[100696]="搞定了！贸易大王为你们骄傲。不过在靠近我的王宫时，记得擦靴子！"
D.Strings[100697]="干得好！你们的战斗技巧和广告上说的一样出色。贸易大王最懂广告了！"
D.Strings[100698]="正在灌注……"
D.Strings[100699]="托里姆，你的力量是从哪儿来的？"
D.Strings[100700]="戴尔格特全是海盗……吸血鬼……海盗鬼……吸血海盗？啊！去杀光他们就是了。那些蠢货在挖掘我们埋藏的圣物。那些被诅咒的神器不该重新现世。"
D.Strings[100701]="如果落入贪婪的人手中，那些神器会造成严重的破坏。幸好你夺回了它们。"
D.Strings[100702]="你好啊，旅行者！谢谢你来看我。"
D.Strings[100703]="我跟你说过我的外孙女艾丽克西斯，凯尔希和卡拉吗？都是聪明的姑娘！$B$B我已经很久没见过她们了……<佩吉顿了顿，然后慈祥地笑了起来。>$B$B我很想她们，希望她们一切都好。"
D.Strings[100704]="你准备好观看榨汁演示了吗？"
D.Strings[100705]="使用|TInterface\\Icons\\spell_arcane_blink.blp:20|t |cFFFF0000|Hspell:111771|h[闪现术]|h|r通过虚空屏障。"
D.Strings[100706]="又一位族长光荣地战死了！今天，我们将纪念他的辞世。来吧，英雄，跟我们一起狂欢！不过……小心别害死自己。"
D.Strings[100707]="这正是你向阵亡战士致敬的方式！但我想你今天已经闹够了。"
D.Strings[100708]="大魔导师有令，你犯有煽动叛乱罪。你妨碍了我的权威，必须为此付出代价。"
D.Strings[100709]="拜托，小心那根法杖……"
D.Strings[100710]="我愿意尝试你的道路。"
D.Strings[100711]="圣光之怒，我还以为它遗失了……"
D.Strings[100712]="有了它，你或许能救出我们所有人。"
D.Strings[100713]="你是一个值得追随的榜样。"
D.Strings[100714]="你准备好之后，我就把你送进艾林裂隙去面对萨维斯。"
D.Strings[100715]="送我去艾林裂隙吧！"
D.Strings[100716]="奥杜尔遭到了攻击。把我和所有准备好的部队派去援助他们吧！"
D.Strings[100717]="托里姆的时间不多了。快去跟艾瑞莉娅谈谈，去支援奥杜尔吧！"
D.Strings[100718]="希尔乐将一朵暮色百合放在监视者杜兰特的尸体上。"
D.Strings[100719]="去寻找萌芽的树，但是要小心饥肠辘辘的鱼儿！"
D.Strings[100720]="我们并不想担此重任，先知，但这是命运的决定。"
D.Strings[100721]="你的孩子被欺诈者变成了一股黑暗力量。无论是生前还是死后，他都对真相一无所知——无论是何种真相。"
D.Strings[100722]="不要让我们今天所做的牺牲白费。黑暗很快就会将我带走，所以请听好了。"
D.Strings[100723]="对于一段未实现的命运来说，圣光之心就是第二次机会。"
D.Strings[100724]="你必须找到受月神眷顾的孩子。你的旅程将由他开始。"
D.Strings[100725]="圣光之心会指引你的。"
D.Strings[100726]="将圣光之心还给卡德加吧。告诉他……告诉他圣光死于此时此地。"
D.Strings[100727]="我不是先知，也不是棋子。不再是了。"
D.Strings[100728]="有人发现，沉船海湾的鱼人在崇拜一个叫浮骸的海巨人。去干掉这个家伙吧。"
D.Strings[100729]="浮骸真应该躲在海里的。谢谢你，勇士。多亏了你，我的人民更安全了。"
D.Strings[100730]="来看看我的优质货物吧。"
D.Strings[100731]="我有你要的东西。"
D.Strings[100732]="这当然是正版的！"
D.Strings[100733]="嘿，不能退款哦，明白吗？"
D.Strings[100734]="跟你做生意真愉快。"
D.Strings[100735]="一手交钱，一手交货。"
D.Strings[100736]="别问这些货是从哪儿来的。"
D.Strings[100737]="你是来买东西还是偷东西的？"
D.Strings[100738]="别担心，这些可不是偷来的。我只是还没付款而已。"
D.Strings[100739]="看看这个——科赞手工制作，加基森手工偷来的！"
D.Strings[100740]="别错过，要是错过了六触的货物，你哭都来不及！"
D.Strings[100741]="又是你们？斯纳格，消灭他们！"
D.Strings[100742]="系统过载？那是什么意思？哇啊啊啊！"
D.Strings[100743]="把我和……我的钱埋在一起……"
D.Strings[100744]="想要砸破谁的脑袋吗？"
D.Strings[100745]="接着说，伙计。"
D.Strings[100746]="我会搞定的。"
D.Strings[100747]="你不是应该去杀野猪啥的吗？"
D.Strings[100748]="我以为我已经摆脱你了。"
D.Strings[100749]="我听说那座山顶上有条龙。他可能看着吓人，但我敢肯定，掏他的口袋肯定很容易。"
D.Strings[100750]="来次打靶训练怎么样？我数到十——你就跑。"
D.Strings[100751]="该让你吃枪子了！"
D.Strings[100752]="这不公平！你作弊……"
D.Strings[100753]="我是来引导强者前往苍穹要塞的！"
D.Strings[100754]="啊，马格纳的拯救者。这对你来说应该很简单！"
D.Strings[100755]="那两把剑应该很有用吧？克瓦迪尔可能会想在天黑前把它们抢回去。"
D.Strings[100756]="蓝风海湾有条暴露的魔网管道，它干扰了网络。去放一些测量设备，我要监控它的混乱能量，并解决它们！"
D.Strings[100757]="我只要找出混乱中的规律，然后修改传送法术绕过它们。我喜欢这工作！"
D.Strings[100758]="采摘……"
D.Strings[100759]="我已经准备好摆脱魔瘾，带领我的人民获得救赎了。"
D.Strings[100760]="我也会跟欧库勒斯吃一样的东西。"
D.Strings[100761]="我要第一个试吃。如果有什么副作用的话，就让我承担吧。"
D.Strings[100762]="<递上阿坎多尔的果实。>"
D.Strings[100763]="那两把剑，我认得是奥丁的造物。帮帮我，战士！"
D.Strings[100764]="被流放的夜之子都被燃烧军团抓起来了。在他们遭遇悲惨的下场之前，快去放了他们！"
D.Strings[100765]="我也不知道哪个更糟糕——是变成枯法者还是成为燃烧军团战争机器的燃料。谢谢你救了他们。"
D.Strings[100766]="呸！你以为你能配得上我？！我的肌肉比你强多了。"
D.Strings[100767]="你是在跟我调情？还是你的脸有什么问题？"
D.Strings[100768]="你干嘛摆出那副表情？停下吧！我讨厌它。"
D.Strings[100769]="别浪费我的时间。你的脸蛋太……娘娘腔了。"
D.Strings[100770]="别逼我把那副表情从你脸上扇掉。"
D.Strings[100771]="呸！你以为你能配得上我？！或许待会儿能让你证明一下。"
D.Strings[100772]="唔……你的模样还挺温柔……"
D.Strings[100773]="大酋长！你召唤的$c已经到了。现在就等希尔瓦娜斯了。"
D.Strings[100774]="唔。好吧，不试试怎么知道呢……"
D.Strings[100775]="啊，$n，我很……高兴你能来。我们的时间……不多了。"
D.Strings[100776]="你肯定是抱着必死的信念说出这些话的吧。我欣赏你。"
D.Strings[100777]="让我去叫治疗者吧，大酋长。你的伤势必须处理了！"
D.Strings[100778]="来不及了，血蹄。我还有……最后一个任务。确保部落的……稳定。"
D.Strings[100779]="为什么不呢？我最喜欢砸碎小东西了。"
D.Strings[100780]="联盟的国王死在破碎海滩上。他们正在叫嚣着复仇。"
D.Strings[100781]="那就好。如果不能封印那座墓穴，艾泽拉斯……就会陷落……"
D.Strings[100782]="我在肯瑞托的联络人告诉我，六人议会的某些成员并不反对邀请部落重返达拉然。"
D.Strings[100783]="我们会想办法赶走燃烧军团的，酋长。我们发誓！"
D.Strings[100784]="女妖之王来了，沃金。你想跟我们说什么？"
D.Strings[100785]="你在干什么？你的身体怎么了？"
D.Strings[100786]="你为什么扭得这么奇怪？"
D.Strings[100787]="呸！如果你喜欢的话，就尽管跳吧。可你丢下了你的朋友……"
D.Strings[100788]="我可没心情容忍你这种行为。"
D.Strings[100789]="停下！这太蠢了。"
D.Strings[100790]="我们夜之子无与伦比的优雅和智慧都源自一份古老的遗产。长眠于泰安诺的先祖应该得到体面的祭品。"
D.Strings[100791]="啊，你来了！符文绘制课正要开始呢。$b$b你学到哪个符文了来着？"
D.Strings[100792]="对，当然了，没错。那你学到什么程度了？"
D.Strings[100793]="很好，这就是你的符文轮廓了。祝你好运！"
D.Strings[100794]="奥术。"
D.Strings[100795]="火焰。"
D.Strings[100796]="冰霜。"
D.Strings[100797]="新手。"
D.Strings[100798]="中级。"
D.Strings[100799]="初级。"
D.Strings[100800]="高级。"
D.Strings[100801]="噢，你好，欢迎来到达拉然。我是路灯保养员。"
D.Strings[100802]="温德尔，我的魔杖怎么对那些路灯不起作用了？"
D.Strings[100803]="噢，是的，非常抱歉。我想自己去点亮那些路灯。这对我来说很重要。\n\n所以请你让它们保持现状吧。"
D.Strings[100804]="这些书很有趣吧？我喜欢通过阅读了解居住在我们世界的各种生物。$b$b跟我一起来读一本书吧。你想读哪一本呢？"
D.Strings[100805]="啊……狗头人。很好的选择！它们也是我的最爱之一。$b$b你最感兴趣的书是哪一本？"
D.Strings[100806]="啊，没错，海巨人。神奇的野蛮人，对吧？$b$b你最感兴趣的书是哪一本？"
D.Strings[100807]="当然。谁不为强大的魔法生物着迷呢？$b$b你最感兴趣的书是哪一本？"
D.Strings[100808]="狗头人。"
D.Strings[100809]="海巨人。"
D.Strings[100810]="狗头人王国。"
D.Strings[100811]="狗头人社会指南（推荐人数：3人）"
D.Strings[100812]="蜡烛之前：狗头人帝国兴衰史（推荐人数：10人）"
D.Strings[100813]="剖析海巨人"
D.Strings[100814]="完整版海巨人武器词典（推荐人数：3人）"
D.Strings[100815]="高戈奈斯之子：名垂青史的海巨人们（推荐人数：10人）"
D.Strings[100816]="龙语纲要第四卷"
D.Strings[100817]="我从蓝翼栖地带来了《蓝龙故事选集》（推荐人数：3人）"
D.Strings[100818]="上古艾泽拉斯蓝龙（推荐人数：10人）"
D.Strings[100819]="欢迎来到纳萨拉斯学院。你请随意。这里欢迎所有热爱学习的人。"
D.Strings[100820]="我们这儿的活动可丰富了。你可以随意阅读我们的藏书，使用训练假人练习战斗技巧，或是跟你的同学们聊天。如果你愿意的话，甚至还能带几个朋友来。这里很安全。$b$b此外，导师妮蒂尔开设了一门符文绘制课程，我们的助理研究员塞索尼则在进行一项有关生物战斗的研究。我相信他们两个都会很乐意跟你合作的。"
D.Strings[100821]="现在还不行。多花点时间跟其他导师互动吧，然后我才会考虑这件事。"
D.Strings[100822]="决斗？如果你坚持的话。我想一场小小的战斗也不会伤害到任何人。不过这一点可能不太准确。\n你准备好了就告诉我一声吧！"
D.Strings[100823]="我投降。打败院长可不是什么小成就。祝贺你。"
D.Strings[100824]="这可真有趣。谢谢你给了我一个动用魔杖的机会。现在，所有人都给我回去学习！"
D.Strings[100825]="我能在这儿做些什么？"
D.Strings[100826]="有兴趣来场决斗吗？"
D.Strings[100827]="有兴趣来场决斗吗？（推荐人数：10人）"
D.Strings[100828]="你可真矮小。"
D.Strings[100829]="你得到了奥丁的青睐？"
D.Strings[100830]="你为什么要找我说话，矮小的$c？"
D.Strings[100831]="我觉得你的衣服看着很古怪。"
D.Strings[100832]="你是来喝酒的还是来打架的？要么就是来喝酒，顺便打架？"
D.Strings[100833]="你的手真小。"
D.Strings[100834]="小心！它过来了！躲开！"
D.Strings[100835]="又一位族长前往奥丁的大厅畅饮美酒了。悄悄告诉你，我一直都不喜欢那个族长。"
D.Strings[100836]="现在，族长加入了瓦拉加尔，去侍奉奥丁了。让我们喝一杯，祝他们好运吧。"
D.Strings[100837]="老实说，我会想念那位族长的。他在的时候，总是会有丰盛的宴会。"
D.Strings[100838]="有些人或许会想念族长的。我不会，但有人会的。"
D.Strings[100839]="阿鲁因来了吗？我好几天没看见他了……"
D.Strings[100840]="阿鲁因恐怕来不了了。为了让我们能把这个交给你，他付出了自己的生命。<递上阿坎多尔的果实。>"
D.Strings[100841]="肚子在咕咕叫……"
D.Strings[100842]="我为什么要吃那么多鱼人？"
D.Strings[100843]="噢，亮晶晶！"
D.Strings[100844]="那是我的！"
D.Strings[100845]="呃……太臭了。"
D.Strings[100846]="咿……毛太多了。"
D.Strings[100847]="呸……太丑了。"
D.Strings[100848]="该走了，大祭司。我们得把这事告诉盟友。"
D.Strings[100849]="很高兴看到那两把剑摆脱了克瓦迪尔的魔掌。"
D.Strings[100850]="传说是真的，大地守护者之鳞真的存在……"
D.Strings[100851]="嘿，伙计！$b$b我就送你三句话：升级！升级！升级！虽然我还是个新人，可我知道怎么让你的部队发挥出潜力。我能让你的火更旺，水更急，地更猛，风更狂！"
D.Strings[100852]="末日就要再次降临！"
D.Strings[100853]="我们的时代结束了，净化的火焰即将来临！"
D.Strings[100854]="这个世界即将焕然一新！"
D.Strings[100855]="在超乎想象的力量面前，我们根本不值一提！"
D.Strings[100856]="燃烧的碧火将净化我们的堕落！"
D.Strings[100857]="这是注定的命运，无法逃避！"
D.Strings[100858]="我们的领袖保护不了我们！"
D.Strings[100859]="虽然我还是个新人，可我知道怎么让你的部队发挥出潜力。我能让你的火更旺，水更急，地更猛，风更狂！"
D.Strings[100860]="就把这当做……回敬你之前的无礼吧，瓦拉加尔！"
D.Strings[100861]="你需要召唤元素吗？"
D.Strings[100862]="还没结束呢，凡人！我要夺回我的剑，而你的灵魂也将在我的手中哀嚎！"
D.Strings[100863]="<举杯>"
D.Strings[100864]="<辱骂>"
D.Strings[100865]="保持警惕，$n。我们能发现邪能风暴中飞出的东西，那燃烧军团也能。"
D.Strings[100866]="我想购买破碎命运印记。"
D.Strings[100867]="你需要破碎命运印记吗？"
D.Strings[100868]="我不动如山。"
D.Strings[100869]="好的。"
D.Strings[100870]="我听候你的吩咐。"
D.Strings[100871]="你把我弄糊涂了……"
D.Strings[100872]="你惹火我了！"
D.Strings[100873]="我要碾碎你的骨头！"
D.Strings[100874]="风在呢喃着你的名字。"
D.Strings[100875]="有风的地方就有我的身影。"
D.Strings[100876]="天空听候你的差遣。"
D.Strings[100877]="我糊涂了。"
D.Strings[100878]="这可不好玩。"
D.Strings[100879]="我们还有正事要办呢。"
D.Strings[100880]="我要抗议这种行为！"
D.Strings[100881]="这太粗鲁了！"
D.Strings[100882]="听候你的差遣。"
D.Strings[100883]="我们的命运掌握在你的手中。"
D.Strings[100884]="战场在等着我。"
D.Strings[100885]="你有什么指示吗？"
D.Strings[100886]="我们的时间有限。"
D.Strings[100887]="你这是在浪费时间！"
D.Strings[100888]="我的耐心是有限的……"
D.Strings[100889]="这一点儿都不好笑！"
D.Strings[100890]="愿元素指引你的道路。"
D.Strings[100891]="大地与流水。"
D.Strings[100892]="我很荣幸能为你效劳。"
D.Strings[100893]="我与元素融为一体。"
D.Strings[100894]="我没时间陪你闹。"
D.Strings[100895]="斗牛者必将死于牛角之下！"
D.Strings[100896]="我的期待之火正在熊熊燃烧。"
D.Strings[100897]="我是火焰的化身。"
D.Strings[100898]="愿你的烈焰永不熄灭。"
D.Strings[100899]="我们的敌人必将灰飞烟灭。"
D.Strings[100900]="一切都将燃烧……"
D.Strings[100901]="我只想做一件事……"
D.Strings[100902]="这里热起来了……"
D.Strings[100903]="你想要几成熟？ 烤焦还是全熟？"
D.Strings[100904]="快说！"
D.Strings[100905]="我是怒火的化身！"
D.Strings[100906]="有话快说！"
D.Strings[100907]="我必将君临天下。"
D.Strings[100908]="不要失败。"
D.Strings[100909]="我在等。"
D.Strings[100910]="你会屈服的。"
D.Strings[100911]="万物都将熊熊燃烧。"
D.Strings[100912]="我受够你了！"
D.Strings[100913]="我要焚烧你的灵魂！"
D.Strings[100914]="说吧，我在听。"
D.Strings[100915]="勇敢前行吧，凡人。"
D.Strings[100916]="大地就是你的后盾。"
D.Strings[100917]="石母能帮你什么忙吗？"
D.Strings[100918]="你想干什么，凡人？"
D.Strings[100919]="我要把你埋葬！"
D.Strings[100920]="你面前是一个伟大的存在。"
D.Strings[100921]="不要违抗我！"
D.Strings[100922]="我无处不在。"
D.Strings[100923]="风是你的盟友。"
D.Strings[100924]="我是逐风者！"
D.Strings[100925]="有何贵干？"
D.Strings[100926]="你的行为很讨厌！"
D.Strings[100927]="我真为那些蠢到来惹风元素领主的白痴感到悲哀！"
D.Strings[100928]="我是来为你效劳的。"
D.Strings[100929]="黑锋骑士团必胜。"
D.Strings[100930]="没人能对抗你，死亡领主。"
D.Strings[100931]="谁都别想阻挡我们！"
D.Strings[100932]="我们要不惜一切代价赢得胜利！"
D.Strings[100933]="死亡只是个小小的挫折。"
D.Strings[100934]="你应该跪迎一位国王。"
D.Strings[100935]="有话快说！我的时间有限……"
D.Strings[100936]="你是来进贡的吗？"
D.Strings[100937]="下次，你一定会跪在我面前。"
D.Strings[100938]="快点回来，否则我要放狗了。"
D.Strings[100939]="激流堡的荣耀已经唾手可得。"
D.Strings[100940]="靠嘴可打不赢这场战争。"
D.Strings[100941]="我们是黑夜中的守护者。"
D.Strings[100942]="我的心脏仍随着战鼓的鼓点跳动。"
D.Strings[100943]="无需牺牲的胜利只是一种妄想。"
D.Strings[100944]="死亡也阻止不了我们。"
D.Strings[100945]="我们的死，是为了让别人更好地活下去。"
D.Strings[100946]="在死后，我才明白自己真正的使命。"
D.Strings[100947]="亡灵得不到安息。"
D.Strings[100948]="腐肠？"
D.Strings[100949]="腐肠。"
D.Strings[100950]="腐肠……"
D.Strings[100951]="烂——肠——"
D.Strings[100952]="腐肠！"
D.Strings[100953]="有事吗，我的学生？"
D.Strings[100954]="死亡欢迎你，年轻人。"
D.Strings[100955]="你今天想学点儿什么呢？"
D.Strings[100956]="不要忘了你得到的教训。"
D.Strings[100957]="你最大的力量……就是你自己。"
D.Strings[100958]="末日即将来临！\n\n要来本小册子吗？"
D.Strings[100959]="你有质疑者的灵气。"
D.Strings[100960]="我要一本小册子。"
D.Strings[100961]="她显然已经死了，蠢货！"
D.Strings[100962]="你确定吗？她可能只是睡着了！"
D.Strings[100963]="才不是呢，笨蛋！她背上插着把刀子！"
D.Strings[100964]="她睡觉的时候，干嘛要在背上插把刀？"
D.Strings[100965]="不不不……这个肤色完全不对。这可不行。"
D.Strings[100966]="呃，那个脑袋让我想起了一个自负的学徒。把它拿走。"
D.Strings[100967]="就是它！就是这个！快把它给我。"
D.Strings[100968]="我准备好了，可以前往苏拉玛了。"
D.Strings[100969]="小心点，$g先生:女士;！苏拉玛很危险！"
D.Strings[100970]="你好像有点不对劲……"
D.Strings[100971]="看看他们，尽情放纵，就像燃烧军团不存在一般。去教育他们一下什么是现实吧？"
D.Strings[100972]="看起来你已经准备好让世界燃烧了。噢，我能跟你一起去就好了。"
D.Strings[100973]="我拿一瓶魔力之火好了。"
D.Strings[100974]="你知道我是谁吗，小子？"
D.Strings[100975]="说话小心点，丫头，当心我让你去走木板！"
D.Strings[100976]="谁能给我翻译一下？我听不懂他那滔滔不绝的海盗黑话。"
D.Strings[100977]="木板？"
D.Strings[100978]="他说那封信是一种高级密码写成的，不容易破译。"
D.Strings[100979]="那个不明物体就在这片浑浊的水域里。该试试你的水性了，$n。"
D.Strings[100980]="在激战中集中精神，同时为盟友治疗——对萨满来说，这是无上的荣耀，也是最大的挑战。$b$b如果你想要练习自己在战场上的治疗技巧的话，这座大厅里就有训练假人。$b$b如果你想重新接受训练，就跟附近的女族长托拉谈谈吧。她经历过黑暗的年代，也曾见识过光明，有丰富的经验。"
D.Strings[100981]="在紧急关头，神盾的主人赶到了。你会用到它的力量的。"
D.Strings[100982]="这里的维库人有个传说，一位坚毅的战士挥舞着金色利刃横行于风暴峡湾。那究竟是谁呢？"
D.Strings[100983]="你将成为我的狩猎小队的最佳外援！"
D.Strings[100984]="我愿意跟那些先行者一起，为你和隐秘通途效劳。"
D.Strings[100985]="阿卡玛。你的两面三刀并没有让我感到意外。"
D.Strings[100986]="快看北边，$n！那是苏拉玛的暗夜要塞！里面会有怎样的秘密呢？"
D.Strings[100987]="我早就应该把你和你那些畸形的同胞全部杀掉。"
D.Strings[100988]="我愿意用我的余生为你以及隐秘通途效劳。"
D.Strings[100989]="太迷人了！古代上层精灵的废墟随处可见。海滩上好像还有一个维库人定居点！有意思。"
D.Strings[100990]="这两把剑是属于我的！别以为我会手下留情！"
D.Strings[100991]="$n即将进入竞技场，证明自己的实力！"
D.Strings[100992]="欢迎光临瘤节之枝！请随意看看，如果有什么特别想要的，可以问我。"
D.Strings[100993]="哇！这副墨镜不错嘛，$n！"
D.Strings[100994]="该死的$n！又戴着漂亮的墨镜回来招摇了！"
D.Strings[100995]="你看起来不错嘛，$n！"
D.Strings[100996]="这边，$n……看看那副墨镜！"
D.Strings[100997]="外来者！"
D.Strings[100998]="你怎么进来的？"
D.Strings[100999]="快跑！他们有武器！"
D.Strings[101000]="城里的贵人整天醉生梦死，而平民却在受苦。去阿斯塔瓦港见我的助手艾欧薇恩，结束这场狂欢吧。"
D.Strings[101001]="这或许能让他们睁眼看看周围的穷苦人。"
D.Strings[101002]="$n！你真是我的好朋友！$b$b下一次，葛拉什一定要去抓一条大船，掰开它，把所有人都倒进水里，告诉他们：“$N是最好的萨满，哈哈哈！”"
D.Strings[101003]="<你的回答让这个海巨人非常高兴。>$b$b<波涛语者安德莉等着你。>"
D.Strings[101004]="<葛拉什难过低地下了头。>$b$b好吧。"
D.Strings[101005]="别那么做！"
D.Strings[101006]="葛拉什很难钻进这个洞里。我不知道其他萨满会不会像我们一样接受他。"
D.Strings[101007]="救命！卫兵！有个纵火犯正逍遥法外！"
D.Strings[101008]="卫兵们，快制止这疯狂的行为！我们付你们的薪水是干什么的？"
D.Strings[101009]="我们的船都着火了！救命！"
D.Strings[101010]="暗影必将再次崛起。"
D.Strings[101011]="我没空陪你闹。"
D.Strings[101012]="你这是在挑战我的耐心。"
D.Strings[101013]="我要把你打入虚空！"
D.Strings[101014]="%s不赞同地瞪着$n。"
D.Strings[101015]="愿圣光照耀着你。"
D.Strings[101016]="我会为自己赎罪的。"
D.Strings[101017]="我将被救赎。"
D.Strings[101018]="我受的苦还不够多吗？"
D.Strings[101019]="你还想要我怎么样？"
D.Strings[101020]="你是个固执的家伙，对吧？"
D.Strings[101021]="你的风度呢？"
D.Strings[101022]="你该住手了。"
D.Strings[101023]="别逼我做出一些会让我俩都后悔的事。"
D.Strings[101024]="我是圣光的化身。"
D.Strings[101025]="魔枢宝库就在主塔的下方。你可以在塔楼最底层的大厅里找到它的入口。"
D.Strings[101026]="好了，来，试试这个……"
D.Strings[101027]="不对不对，举起你的手，就像小耳朵。像这样！"
D.Strings[101028]="现在，跳一跳。就像这样。"
D.Strings[101029]="%s大笑起来！"
D.Strings[101030]="哇——哈！哈哈"
D.Strings[101031]="我在跳熊猫舞！"
D.Strings[101032]="它在那儿！落到海滩上，去调查一下！"
D.Strings[101033]="这地方……有点古怪。\n\n<希尔维林整了整袖口。>\n\n但这总比送命强。\n\n我想我应该感谢你，因为你敢于行动。我是个懦夫，但至少玛尔迦没有白死。\n\n我欠你一份人情。"
D.Strings[101034]="我思念我的妻子，更思念我们的女儿。\n\n在这里，我至少能静静地怀念她们。"
D.Strings[101035]="隐秘通途将再次响应我们的召唤，无私地帮助最有需要的无辜人民。"
D.Strings[101036]="枯法者的伤害提高了！"
D.Strings[101037]="现在，投掷石块，让敌人流血！"
D.Strings[101038]="它不在这儿。那些野兽肯定把它拖进洞里去了。继续找！"
D.Strings[101039]="感谢你！我已经快要坚持不住了！"
D.Strings[101040]="啊！他们逼我看着我的部落被屠杀殆尽……一遍又一遍！这一切真的只是一场梦吗？"
D.Strings[101041]="不！我受够了！"
D.Strings[101042]="蜜蜂！到处都是蜜蜂！啊啊啊！"
D.Strings[101043]="这……这是什么巫术？都是我想象出来的吗？"
D.Strings[101044]="我仍然能够感觉到它们在抓挠着我的意志。"
D.Strings[101045]="时间就是金钱，朋友。"
D.Strings[101046]="哟！"
D.Strings[101047]="请讲吧。"
D.Strings[101048]="有事儿吗？"
D.Strings[101049]="没看到我正忙着吗？"
D.Strings[101050]="呵呵，我很高兴能帮上忙。"
D.Strings[101051]="加油吧。"
D.Strings[101052]="快点儿回来。"
D.Strings[101053]="你帮我一把，我就出钱找人来帮你。"
D.Strings[101054]="是的，很搞笑。"
D.Strings[101055]="我没时间陪你闹！"
D.Strings[101056]="真不专业！"
D.Strings[101057]="你不该这么对我。我可是加基森贸易巨头。"
D.Strings[101058]="你想让我的保镖揍你一顿吗？"
D.Strings[101059]="好吧，那就这样吧。我要签个合同买你的脑袋。"
D.Strings[101060]="只要团结起来，我们就能击败燃烧军团。"
D.Strings[101061]="我有一个覆灭燃烧军团的计划。"
D.Strings[101062]="我迟早会夺回神殿的。"
D.Strings[101063]="我信你，但不信伊利丹。"
D.Strings[101064]="这是你们的古怪风俗吗？"
D.Strings[101065]="你的手指太小了，所以更招人烦。"
D.Strings[101066]="如果你就是想惹我发火的话，那你成功了。"
D.Strings[101067]="连玛瑟里顿都比你有风度。"
D.Strings[101068]="我迟早要毁了你和你的那些追随者。"
D.Strings[101069]="我摆脱控制之日，就是你的死期。"
D.Strings[101070]="我有的是时间来复仇。"
D.Strings[101071]="抱歉，$c。搏击俱乐部暂时停业修整。头儿说，我们要准备一个大惊喜。"
D.Strings[101072]="抱歉，$c。巴泽法兰老板说了，竞技场暂时停业修整。她说“我们要准备一个大惊喜”。"
D.Strings[101073]="如果你饿了，我们有食物。如果你渴了，我们有饮料。如果你累了，我们有床铺。$b$b如果你来这儿是别有用心，那你最好是个深藏不露的高手。"
D.Strings[101074]="勇敢前进吧！"
D.Strings[101075]="说重点！"
D.Strings[101076]="我就在这儿等你！"
D.Strings[101077]="你好！"
D.Strings[101078]="你以为自己在跟谁说话？"
D.Strings[101079]="我开始讨厌你了。"
D.Strings[101080]="我才不管你是不是奥丁的选民，你再这样我就把你的脑袋劈成两半！"
D.Strings[101081]="你惹火我了！！！"
D.Strings[101082]="燃烧军团开始进攻了！我们得立刻通知其他盟友。"
D.Strings[101083]="隐蔽！"
D.Strings[101084]="月郡侍从向你点点头，从容地离开了酒馆。"
D.Strings[101085]="哼！！"
D.Strings[101086]="我要踢爆你的屁股，奥丁都救不了你！"
D.Strings[101087]="该战斗了吗？"
D.Strings[101088]="希尔维林扬起下巴，踱步离开了酒馆。"
D.Strings[101089]="我会一直跟着你的。谢谢你允许我陪伴你。"
D.Strings[101090]="Quel'vala thonos。高贵源自传统。谢谢你，外来者。"
D.Strings[101091]="你好啊。好消息！我的书终于到了，至少大部分都到了。\n\n你看起来还有点糊涂，我再解释一下吧。你瞧，达拉然上一次整体传送时，我的一些书也因此损坏了。所以这一次，我让它们飞来我们的新地址。没错，就是用飞的。\n\n不幸的是，它们才飞到卡兹莫丹上空时，我们又传送了。大部分的书籍上周才刚刚抵达，并回到了城市各处。有一些还在借阅它们的同事手里，很快就会自行返回。事实上，如果它们再不回来，我就得去调查了。"
D.Strings[101092]="<摩戈尔难过地点点头。这个老鱼人不再看你，转头凝视着波涛起伏的灰色大海，一言不发。>"
D.Strings[101093]="%s开始挥动毁灭之锤到处乱砸。"
D.Strings[101094]="显然%s完全不知道自己在做什么了。"
D.Strings[101095]="%s开心地咯咯笑着。"
D.Strings[101096]="<摩戈尔被你的反应搞糊涂了。稍微冷静了一下，他继续说道：>\n\nUrgleblerg mra'graggle berk urgleblag。Murgle urg grablurg urgle blerg ur Lake Minnetonka burgle bleg。Urg urkegle blerk murgle-gurgle，Azshara glurg'ug。 \n\nGurg blurgle urg-mulurk，“Sharas'dal” gurp blergle urkle-klep。Blergle，$n？\n\n<神谕者指了指你手中的权杖，示意你把它交给他。>"
D.Strings[101097]="%s感激地深深鞠躬。"
D.Strings[101098]="<摩戈尔看起来对自己非常满意。>"
D.Strings[101099]="<肯定地点点头。>"
D.Strings[101100]="<摇头拒绝。>"
D.Strings[101101]="<感谢他付出的时间。>"
D.Strings[101102]="<把毁灭之锤借给他。>"
D.Strings[101103]="<走近一些，将脑袋靠过去，倾听神谕者的古老智慧。>"
D.Strings[101104]="<把莎拉达尔，潮汐权杖借给他。>"
D.Strings[101105]="纳迦正在卡德拉尔遗迹肆虐。如果他们在那里站稳了脚跟，就可能威胁到整个海岸。"
D.Strings[101106]="谢谢你。这类威胁很容易被忽视，让它们成了气候。"
D.Strings[101107]="什么……哪个捣蛋鬼在洛拉希尔丢了这么多橡实？我知道这个任务有点微不足道，但你能弄走一些松鼠，砸掉你遇见的坚果吗？"
D.Strings[101108]="看看$n！多么有时尚品味的潜行者啊！"
D.Strings[101109]="松鼠入侵真是个难啃的核桃。明白么？"
D.Strings[101110]="你看起来不错嘛，$n！真的很棒！"
D.Strings[101111]="$n有心上人了吗？你说我有机会吗？"
D.Strings[101112]="有些小精灵具有卓越的能力，能把树苗快速催生成大树。去找隐秘之池，与那里的一个小精灵交个朋友吧。"
D.Strings[101113]="哪怕在黑暗时代，自然之美依旧光彩夺目。"
D.Strings[101114]="我选了些极具价值的目标。你要好好拜访这些……讨厌的盟友。"
D.Strings[101115]="我们要像吃魔法汉堡那样逐步蚕食敌人。噢——我饿了。"
D.Strings[101116]="有个梦境守护者遭到了梦魇的攻击！愿艾露恩保佑你拯救这头神圣的巨龙。"
D.Strings[101117]="梦魇企图腐化我们的整片森林！"
D.Strings[101118]="守护翡翠海湾的德鲁伊巡逻队还没回来。也许是林精在搞鬼……"
D.Strings[101119]="他们让我们的德鲁伊在鲨鱼肆虐的水域沉眠？还好你及时赶到。"
D.Strings[101120]="薄暮岛礁是鱼人和龙虾人永远的战场。有时候其中一方会占据上风，此时我们就必须介入，让他们的争斗继续下去。"
D.Strings[101121]="菲比什么时候到？她说过她会在一个小时之前抵达的！"
D.Strings[101122]="有些人可能觉得，屠杀这些生物很残忍，但我们必须保持均势，否则获胜的一方就会游到大陆上来。"
D.Strings[101123]="这里的咖啡可真浓！"
D.Strings[101124]="鲑鱼溪沿海的多头蛇又到繁殖的季节了。我们得防止它们的数量过度膨胀，从而对村子造成威胁。"
D.Strings[101125]="大家不用担心多头蛇了，起码这个季节算是过去了。"
D.Strings[101126]="冷静点，我相信她很快就会到的。"
D.Strings[101127]="神秘的低语为你提供了难以言喻的力量……"
D.Strings[101128]="你是怎么得到邀请的？不管了，狩猎已经开始了！"
D.Strings[101129]="好吧，好吧！他们往那边去了。虽然这么说无关紧要，但是你肯定追不上的……"
D.Strings[101130]="梦魇像瘟疫一样在这里四处传播！我们也许能将它拦在这里，防止它腐蚀整个瓦尔莎拉！"
D.Strings[101131]="现在可不是闲聊的时候。你们的神殿正在遭受攻击！"
D.Strings[101132]="传播慢下来了，谢谢你的英勇行为，$n。"
D.Strings[101133]="唔，这位马瑞斯看到的东西会把你的脸色吓得跟我一样白。但是就连他都被这洞窟吓得不轻。说是做噩梦和腐化的精灵什么的。哼！我们追踪一个强大的萨特来到这洞窟。奴役这个萨特……如果我们连试都不去试的话，一定会受到诅咒……更多的诅咒。"
D.Strings[101134]="你是谁？尼姆罗德领主和蒂亚娜夫人呢？"
D.Strings[101135]="这是我们的猎场，滚开！"
D.Strings[101136]="那只狐狸是属于我们的！"
D.Strings[101137]="把它的毛皮给我们，否则我们就扒了你的皮！"
D.Strings[101138]="一路顺风！"
D.Strings[101139]="我喜欢你。别逼我讨厌你！"
D.Strings[101140]="别闹了！"
D.Strings[101141]="这些符文很漂亮，是吧？"
D.Strings[101142]="你真是不懂得节制！"
D.Strings[101143]="好吧，来吧！该教教你什么是天高地厚了！"
D.Strings[101144]="先是霍迪尔，然后是托里姆……现在又是你！"
D.Strings[101145]="我以为我们……我以为我们是朋友……"
D.Strings[101146]="*啜泣*"
D.Strings[101147]="小声点儿！有人来了……"
D.Strings[101148]="嘘！我们有伴儿了！自然点儿……"
D.Strings[101149]="嘘！小声点儿……"
D.Strings[101150]="闭嘴！有人来了……"
D.Strings[101151]="又怎么了？！！"
D.Strings[101152]="我的仇恨在燃烧！！"
D.Strings[101153]="如果燃烧军团杀不了你，你迟早会死在我手上！"
D.Strings[101154]="哼……"
D.Strings[101155]="这个主意不怎么样。恶魔是一回事，可是萨特？他们是堕落的暗夜精灵。"
D.Strings[101156]="塔莉萨说你能帮我潜入暮光酒庄。"
D.Strings[101157]="滚开！！！"
D.Strings[101158]="我要唾弃你的坟墓！"
D.Strings[101159]="好啦好啦。唔，如果我们一碰到精灵变的恶魔就躲得远远的，那我们就没有恶魔可猎了。快静下心来，集中注意力。我们有伴了。"
D.Strings[101160]="还要多久？"
D.Strings[101161]="你休想干扰我布道！"
D.Strings[101162]="这些保险箱有点复杂……马上就好。"
D.Strings[101163]="安玻·吉尔妮曾是我们的战友……不敢相信，我们居然要来暗杀她。"
D.Strings[101164]="这是肖尔大师亲自下达的命令……你就别乱问了。"
D.Strings[101165]="你确实干掉她了，对吧？我们可不能搞砸了！"
D.Strings[101166]="啊！邪恶的怪物。你们都会臣服在我脚下！"
D.Strings[101167]="我告诉过你了……我从不失手。"
D.Strings[101168]="在黄金海湾时，我们就该杀了她……在达拉然搞暗杀太危险了！万一有目击者……"
D.Strings[101169]="让这些符文再发挥一下余热吧。你能过来搭把手吗？"
D.Strings[101170]="呃！我没抓到。但是不试一下又怎么知道。"
D.Strings[101171]="你阻止不了我们，法师！你的前导师为我们打开了通向胜利的道路！卡拉赞必将属于我们！"
D.Strings[101172]="我对你恨之入骨！！！"
D.Strings[101173]="只要能让你吃点苦头，我宁愿死上一千次！！！"
D.Strings[101174]="那里？不对……那里！不对……"
D.Strings[101175]="你为什么不让我去死！！！？？？"
D.Strings[101176]="你该死！！！你全家都该死！！！我要****进******你的喉咙*****奥丁自己*****"
D.Strings[101177]="敌人比我们想的还要接近。"
D.Strings[101178]="燃烧军团逃不出我们的掌心。"
D.Strings[101179]="这改变不了什么，法师！你的防线必将土崩瓦解，你的世界也必将化为火海！"
D.Strings[101180]="有话就说，凡人。"
D.Strings[101181]="我时刻警惕着。"
D.Strings[101182]="我效忠于苍穹要塞。"
D.Strings[101183]="战争永不停歇。"
D.Strings[101184]="你知道这种行为是什么意思吗……"
D.Strings[101185]="海姆达尔是全知……全能的！"
D.Strings[101186]="而你……"
D.Strings[101187]="我开始质疑奥丁的选择了。"
D.Strings[101188]="你就不懂得放弃吗？"
D.Strings[101189]="说真的，住手。"
D.Strings[101190]="我要把我的彩虹桥塞进你的嘴里！"
D.Strings[101191]="随便你。"
D.Strings[101192]="说吧，朋友。"
D.Strings[101193]="愿北风与你同在。"
D.Strings[101194]="我是霍迪尔！"
D.Strings[101195]="霍迪尔！"
D.Strings[101196]="我欠你一份人情，可你也别太过分了！"
D.Strings[101197]="冷静点！"
D.Strings[101198]="别让我讨厌你，小朋友！"
D.Strings[101199]="那可真冷。"
D.Strings[101200]="下雪可是大事。"
D.Strings[101201]="欢迎你，雄鹰之爪的主人。"
D.Strings[101202]="我已经做好了一切准备。"
D.Strings[101203]="快说吧！"
D.Strings[101204]="愿你的刀剑锋锐如初！"
D.Strings[101205]="我们的心中毫无恐惧！"
D.Strings[101206]="血战到底！"
D.Strings[101207]="你看起来很紧张。"
D.Strings[101208]="我吓到你了吗？"
D.Strings[101209]="你的手很漂亮。"
D.Strings[101210]="如果它们有什么闪失那就太可惜了。"
D.Strings[101211]="我真的、真的受够那头恶魔了！"
D.Strings[101212]="从现在开始，你最好不要把爪子伸出来。"
D.Strings[101213]="随时准备战斗！"
D.Strings[101214]="你有什么话就说吧！"
D.Strings[101215]="握紧你的剑！"
D.Strings[101216]="不要退缩！"
D.Strings[101217]="毫无保留地战斗吧！"
D.Strings[101218]="我带着头盔，听不清你的声音。"
D.Strings[101219]="它能很好地保护你的脑袋，可是会妨碍听力。"
D.Strings[101220]="我可以点头。但你最好别跟我说话了。"
D.Strings[101221]="你好，雄鹰之爪的主人。"
D.Strings[101222]="你是带着雄鹰之爪来帮助我们的吗？"
D.Strings[101223]="啊，是那本吗？没错！就是它！"
D.Strings[101224]="我真是个了不起的法师！"
D.Strings[101225]="这样我大概就有事可做了。"
D.Strings[101226]="恶魔也抓住了这个家伙！"
D.Strings[101227]="我要立刻飞往阿彻鲁斯。"
D.Strings[101228]="它在那儿！那个巨人的手里！让巨人交出宝藏的方法只有一个。你知道该怎么做，$n。"
D.Strings[101229]="该死的旱鸭子！小偷！我要把你砸成巢穴里的一滩烂泥！"
D.Strings[101230]="等等！只要跨过那座传送门，你就会直接掉下去！那高度完全能摔死人！你最好先做好准备。"
D.Strings[101231]="你准备好了就告诉我一声，可不要拖得太久了。"
D.Strings[101232]="如非必要，我们不能在这里停留太久。\n\n我们在这里不怎么安全。"
D.Strings[101233]="我们得靠近一点，以防万一。"
D.Strings[101234]="你不是这里唯一的大领主，圣骑士。你来找四骑士做什么？"
D.Strings[101235]="他们不属于这里。卫兵！干掉——"
D.Strings[101236]="他们值得尊重。让他们说出来意吧。"
D.Strings[101237]="没错。在了解他们胆敢来此的原因之后，我们再决定怎么处置他们也不迟。"
D.Strings[101238]="告诉他们吧，大领主。"
D.Strings[101239]="死亡领主在上……"
D.Strings[101240]="我以为它只是个传说……"
D.Strings[101241]="你们竟敢把它带到这里来？你们不会是想……"
D.Strings[101242]="没错，只要有你的帮助，我们就能成功。这是你欠我们的，达里安。"
D.Strings[101243]="他说得对。我们必须得试试。灰烬使者已经不是我们的敌人了。"
D.Strings[101244]="那好吧。骑士们，帮我一把。今天，我们要让灰烬使者重新认识我们的力量！"
D.Strings[101245]="<看到你走近，莎侬将书放到了一边。>"
D.Strings[101246]="这本书好看吗？"
D.Strings[101247]="你好啊！\n\n对！很好的书。"
D.Strings[101248]="你是肯瑞托的成员吗？你在这里做什么？"
D.Strings[101249]="噢，我是负责整理书籍的！我就喜欢干这个。\n\n如果我能每天把它们全部拿下来，然后再一本本放上去的话，那就好了。\n\n可我前几次这么干的时候，他们都很生气。"
D.Strings[101250]="在这里呆久了肯定很无聊吧？"
D.Strings[101251]="哈！才不会的。有这么多书读，怎么会无聊呢？\n\n我还会写作。根据我的想象创作作品。你想看看吗？"
D.Strings[101252]="这是我从一本魔法书里学来的……试了好几次才成功的。"
D.Strings[101253]="好了，我得回去看书了。很高兴见到你！"
D.Strings[101254]="<沃平害怕地颤抖着。>"
D.Strings[101255]="<沃平开心地跳着。>"
D.Strings[101256]="<莎侬专心地看着书。>"
D.Strings[101257]="你成功了！那些声音消失了。"
D.Strings[101258]="我将是你的送葬者！"
D.Strings[101259]="我死也不说！"
D.Strings[101260]="我什么都不会告诉你的！"
D.Strings[101261]="下等人渣！我不会说的！"
D.Strings[101262]="在这儿要睁大你们的眼睛。审判官最喜欢他们的眼球了。"
D.Strings[101263]="我想升级我的装备。"
D.Strings[101264]="我投降！我什么都告诉你！"
D.Strings[101265]="科维林……我们的脏活儿都是他在干。你可以在下面码头附近找到他。"
D.Strings[101266]="斯特拉瑞斯家族不会跟你这样的下层渣滓说话。"
D.Strings[101267]="我的生命……献给斯特拉瑞斯家族……"
D.Strings[101268]="这只渡鸦不悦地冲你叫了两声。"
D.Strings[101269]="呸！那家伙太专横了。"
D.Strings[101270]="不，这不对。我……我来过这里，可这就意味着……"
D.Strings[101271]="英雄们，别杀他！住手！求你们了！"
D.Strings[101272]="如果你们不停手，那我只能阻止你们了！"
D.Strings[101273]="这是他逼我们的，维伦！如果我们不毁掉这台机器，这个地方和里面所有的生灵就都完了！"
D.Strings[101274]="出于某些原因，哈维的伙伴似乎不太喜欢你。"
D.Strings[101275]="这只渡鸦对你的到来表现出了不满。"
D.Strings[101276]="这都是你的错……"
D.Strings[101277]="我的错？我说的是“眼睛”，不是“已经”，你这个瞎了眼的饭桶！"
D.Strings[101278]="天啊……好险。我把我的法力分一点给你，作为我的谢礼吧。"
D.Strings[101279]="我们的敌人慢下来时，正是我们快速行动的时机。还有……谢谢你。你让我的心灵免遭悲惨的命运。"
D.Strings[101280]="愿它成为你的利刃，为苏拉玛带来正义之光。"
D.Strings[101281]="你好，$c。大领主说了，只要不惹麻烦，你就是我们的贵宾。"
D.Strings[101282]="我……我的烈焰又被点燃了。你真是太慷慨了。我可以给你一些我的魔力，以强化你的战斗力。"
D.Strings[101283]="熊熊燃烧吧，去打敌人一个措手不及。"
D.Strings[101284]="用正义的烈焰烧灼那些想要威胁苏拉玛的人的灵魂吧！"
D.Strings[101285]="城里的臭虫已经泛滥成灾了。到处都是臭虫！\n\n我是个工程师。确切的说，是自动化工程师。我想帮忙解决这个问题。"
D.Strings[101286]="这个小家伙是谁？"
D.Strings[101287]="这是温顿！\n\n走来走去、一只一只地找臭虫太无聊了，所以我制造了他来帮我找。\n\n这小家伙很不错，虽然很吵，但我已经习惯了。"
D.Strings[101288]="别小看我！"
D.Strings[101289]="我的利刃就是你的末日。"
D.Strings[101290]="又一个弱者来陪我玩了！"
D.Strings[101291]="不用了，温顿可以搞定的。\n\n不过还是要谢谢你！\n\n很高兴见到你。"
D.Strings[101292]="我感觉你有着自然的灵魂，好心人。"
D.Strings[101293]="我听到你的召唤了，德鲁伊。你想要什么？"
D.Strings[101294]="在暗影中，我们与那些看不见的存在融为了一体。"
D.Strings[101295]="站在我面前的是一头强大的野兽！你有什么要求，$G兄弟:姐妹;？"
D.Strings[101296]="<这个盲萨满听到了你靠近的脚步声。但他没有把脸转过来。>\n你不是个萨满。在这里，你要放轻脚步，$c,。这里的每一块石头都在盯着你的一举一动。"
D.Strings[101297]="<这个盲萨满听到了你靠近的脚步声。他抬起手触摸着你的脸庞。>\n\n联盟。唔……$r，对。<咳嗽>或许我们以前在战场上见过。\n\n很久很久以前，我听到过元素的召唤。在另一个地方，另一个时代。<咳嗽>我能看到你体内闪耀的元素之灵……我能感觉到轻风与海浪都服从你的意志。对，非常强大。你的联盟一定很为你感到骄傲。\n\n这是个黑暗的时代，$r。但你的力量给了这个老兽人希望。或许我能报答你的善意……<咳嗽>……如果你不介意接受昔日旧敌的帮助的话……"
D.Strings[101298]="<接受德雷克塔尔的祝福。>"
D.Strings[101299]="大技师罗姆尔还活着，长官！"
D.Strings[101300]="很好。去找罗姆尔，让他动手修理飞船。我们要回家了。"
D.Strings[101301]="兄弟，我来了……"
D.Strings[101302]="成功了。我们扯平了，大领主。"
D.Strings[101303]="谢谢你，达里安。你父亲会为你骄傲的。"
D.Strings[101304]="别在我面前提他，圣骑士。现在，滚吧，别再回来了！"
D.Strings[101305]="要送你回家吗？"
D.Strings[101306]="请送我返回达拉然。"
D.Strings[101307]="谢谢你，朋友。我已经好多了，可以回去战斗了！"
D.Strings[101308]="谢谢你，德鲁伊。这场战斗还没有结束！"
D.Strings[101309]="我刚才伤得很重，但现在我又能继续战斗了！"
D.Strings[101310]="我已经好多了。谢谢你，德鲁伊。"
D.Strings[101311]="你的英勇事迹必将被谱写成传说！"
D.Strings[101312]="请别叫卫兵。我是来向沃金致敬的，不是来惹麻烦的。$b$b他是一位老朋友。我们曾并肩对抗过强大的敌人。我欠那个巨魔一条命。$b$b我们曾经发过誓，如果我们中的哪一个被害，另一个人就要为他复仇。我一直以为他会比我长命的……$b$b无论要付出什么代价，我都会实现我的诺言。"
D.Strings[101313]="走开，我在工作呢。人群中可能有敌对分子。"
D.Strings[101314]="我看着像是要找死的样子吗？我是说，像是想再死一次的样子吗？$b$b如果你对凋零者的脸感兴趣，你就去问他本人吧，或是去问黑暗女王也行。他们都很乐意跟你聊天的。$b$b<黑暗游侠冷冷一笑，又回到自己的岗位上去了。>"
D.Strings[101315]="你知道纳萨诺斯为什么看起来那么……与众不同吗？"
D.Strings[101316]="前几天，我好像召唤出了一个气元素！\n\n那天，我打了一个特别响的饱嗝！"
D.Strings[101317]="如果你真的是一个非常非常优秀的萨满，那你能召唤……一个冰淇淋元素吗？"
D.Strings[101318]="火。火！火才是最棒的。我喜欢火。"
D.Strings[101319]="唤地者耶法太聪明了。她说她的世界被恶魔占领了，可她逃了出来，对抗他们。你跟恶魔战斗过吗，$n？"
D.Strings[101320]="水元素代表了祥和与新生。可我们必须小心一些，因为水之灵很善变。"
D.Strings[101321]="如果你能与风对话，就能听到来自远方的消息。如果有足够的控制力，萨满还能驾驭雷霆与风暴的怒火。"
D.Strings[101322]="新晋萨满金矿也曾是我的学生。可你不要被他那个样子吓到了。"
D.Strings[101323]="大地承载万物。如果我们与大地融为一体，在面对敌人时就能像大山一样坚定不屈。"
D.Strings[101324]="大部分人沟通火元素都是为了毁灭，但在温柔的双手中，火也能烹煮食物、温暖房间。我的学生们，你们会怎么使用火焰的力量呢？"
D.Strings[101325]="我是来保护大酋长的。如果你敢对大酋长拔刀相向，那在你的鲜血落到地面之前，你就已经死了。$b$b至于其他的……那不关你的事。明白吗？"
D.Strings[101326]="你看起来有点与众不同，凋零者……"
D.Strings[101327]="于是我又试了一下那个图腾解谜游戏。"
D.Strings[101328]="连续不断的失败和越来越低的期望，最终在绝望的深渊中完全灭绝。"
D.Strings[101329]="火！水！火！水！不知道怎么搞的，我把其中一个变成了大地图腾，谜题大师老罗就把我踢出来了。"
D.Strings[101330]="经过几个小时的连续失败，我渐渐有了痛彻心扉的领悟，最初那点小小的期待是多么可笑。"
D.Strings[101331]="就像在海岸上撞得粉身碎骨的浪花，我不停追逐着渐渐远去的希望之光，口中满是又咸又苦的泪水。"
D.Strings[101332]="你还是……别玩了。"
D.Strings[101333]="振作起来，小朋友。下一次你肯定会做得更好的。"
D.Strings[101334]="你或许应该休息一段时间。"
D.Strings[101335]="你这次表现如何？"
D.Strings[101336]="狂……狂怒，再也没有蒙蔽我的思绪！谢谢你，纳兰度！"
D.Strings[101337]="一个好领袖、好朋友就这么走了。等我死后，但愿能与他在英灵殿再大战一场。"
D.Strings[101338]="为什么要用船呢？"
D.Strings[101339]="过去，我们的风俗是将族长放进小船，推进海里，然后点燃船只。但自从我们的海岸被迷雾笼罩后，我们就不敢这么做了。否则他就会变成克瓦迪尔，再度归来。"
D.Strings[101340]="艾泽拉斯的居民们。"
D.Strings[101341]="今天，我们将力挽狂澜。"
D.Strings[101342]="今天，我们要夺回我们的世界。"
D.Strings[101343]="并将燃烧军团赶回他们的地狱去。"
D.Strings[101344]="征程就在眼前。"
D.Strings[101345]="创世之柱在等着我们。"
D.Strings[101346]="就在破碎群岛！"
D.Strings[101347]="大领主！我们得做点什么，否则就迟了！"
D.Strings[101348]="哈！我的熊会把你的麝牛撕成碎片！"
D.Strings[101349]="你！小个子！我们来比一比，看谁的野兽更强大！"
D.Strings[101350]="魔刃豹跑了起来！"
D.Strings[101351]="我们要让燃烧军团付出代价！"
D.Strings[101352]="如果你累了，那我就把你换掉。"
D.Strings[101353]="酒庄工人畏惧地看了看身后，跑回去干活儿了。"
D.Strings[101354]="我一点儿都不累。请饶了我。"
D.Strings[101355]="我们等着你的命令。"
D.Strings[101356]="蠢货！你以为你能成功吗？连我这个萨格拉斯的选民都失败了！"
D.Strings[101357]="所有试图驯服乌萨勒斯的人都被吞噬了。你也好不到哪儿去！"
D.Strings[101358]="让乌萨勒斯吞噬你吧！"
D.Strings[101359]="你也将成为它镰下的亡魂！"
D.Strings[101360]="乌萨勒斯将享用你的灵魂。"
D.Strings[101361]="不可能……你会被……吞噬的……"
D.Strings[101362]="大领主，我们达成一致了，但还得你说了算。我们该怎么做？"
D.Strings[101363]="我们要守住虚空之光神殿。"
D.Strings[101364]="你好，$c。\n\n格雷迈恩已经通知我，向风暴峡湾的所有盟友开放兵营。如果你需要使用我们的床位，告诉我一声就行。"
D.Strings[101365]="这些兽人建筑可能不如幽暗城的墓穴那么舒适，但原木比碎石好搬运多了。"
D.Strings[101366]="大酋长希尔瓦娜斯万岁！"
D.Strings[101367]="为沃金报仇！"
D.Strings[101368]="战胜燃烧军团！"
D.Strings[101369]="记住破碎海滩！"
D.Strings[101370]="打倒联盟！"
D.Strings[101371]="部落长存！"
D.Strings[101372]="恶魔必败！"
D.Strings[101373]="外来者，在这儿？！"
D.Strings[101374]="卫兵！救救我们！"
D.Strings[101375]="让酒庄的人都老实点，我绝不容忍任何反抗。"
D.Strings[101376]="求求你们，别伤害我们。"
D.Strings[101377]="你好，$n。我有奥丁的重要口信！"
D.Strings[101378]="奥丁在等你。他的大军已经整装待发！"
D.Strings[101379]="$n。你来了。我有事要告诉你。"
D.Strings[101380]="战争领主加尔顿说有非常重要的事要找你商量。"
D.Strings[101381]="他希望你能尽快赶回邪能之槌号。"
D.Strings[101382]="既然你证明了自己，我想我可以继续训练你了。如果你有制造材料的话，还可以跟我交换配方！"
D.Strings[101383]="嘘，$n。过来点儿，我有事跟你说。"
D.Strings[101384]="谁拉到仇恨了？！？！？！"
D.Strings[101385]="我自己起！"
D.Strings[101386]="拉文霍德大人有重要的事情跟你商量。"
D.Strings[101387]="强尼好像AFK了……"
D.Strings[101388]="给坦克上误导！"
D.Strings[101389]="快把术士拉起来，最后一个阶段要术士！！！"
D.Strings[101390]="他希望你能立即返回暗影大厅。"
D.Strings[101391]="全球首杀！！！"
D.Strings[101392]="哇啊啊！！！"
D.Strings[101393]="如果掉了蛋刀，能给我吗？"
D.Strings[101394]="注意了，伙计们。用药水！"
D.Strings[101395]="谁有多余的药水？"
D.Strings[101396]="怎么……不给我……加血……"
D.Strings[101397]="我就算是死……也要怪坦克……"
D.Strings[101398]="我不应该让猎人先攻击的……"
D.Strings[101399]="我只管加血，可不管加智商……"
D.Strings[101400]="他们怎么看见我的……"
D.Strings[101401]="看见了没？我们不用去地下城也能拿到好装备。它的手套归我了！"
D.Strings[101402]="外面的战斗怎么样了，$c？看到什么值得剥的皮了吗？"
D.Strings[101403]="我的学徒都能把你炸飞！"
D.Strings[101404]="我想招募一队学徒。"
D.Strings[101405]="我想招募一队咒术师。"
D.Strings[101406]="你好，大德鲁伊。我来带了梦境林地的消息。"
D.Strings[101407]="很好，大德鲁伊。祝你一帆风顺。"
D.Strings[101408]="大宗师，我一直在找你！"
D.Strings[101409]="我在迷踪岛等你，大宗师。"
D.Strings[101410]="大领主，我需要耽误你一点时间。"
D.Strings[101411]="我们在圣光之愿礼拜堂等着你。"
D.Strings[101412]="%s害怕地逃跑了！"
D.Strings[101413]="啊，谢谢你。"
D.Strings[101414]="我又能思考了。"
D.Strings[101415]="呃……什……什么？噢——是你！谢谢，外来者。"
D.Strings[101416]="但愿你不用经历那种痛苦……"
D.Strings[101417]="看来我今天不用挨饿了。"
D.Strings[101418]="|TINTERFACE\\ICONS\\Spell_Arcane_PrismaticCloak:20|t奥术师特尔安开始施放|cFFF00000|Hspell:218807|h[黑夜的召唤]|h|r！"
D.Strings[101419]="|TINTERFACE\\ICONS\\Spell_Arcane_PrismaticCloak:20|t日心学者特尔安开始施放|cFFF00000|Hspell:223437|h[暗夜坍缩]|h|r！"
D.Strings[101420]="该死的恶魔！总是肆意破坏……我一点利润都赚不到了！"
D.Strings[101421]="梦魇的扩散比我们预想的还远。我要好好想想，大德鲁伊。"
D.Strings[101422]="你要训练狂热者吗？"
D.Strings[101423]="你要训练黑暗狂热者吗？"
D.Strings[101424]="塔什瑞尔领主偷走了我图书馆里的书。他的妄想会毁了我们。快去把那些书夺回来！"
D.Strings[101425]="你这儿有炸药卖吗？"
D.Strings[101426]="这是谁画的？真是太不可思议了！"
D.Strings[101427]="我一定要把它买下来，这细节太棒了！"
D.Strings[101428]="这幅画真细腻。"
D.Strings[101429]="<使用10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得折跃行走。>"
D.Strings[101430]="别碰我们！啊！"
D.Strings[101431]="……可没人过来。"
D.Strings[101432]="你就快抵达目的地了。欧库勒斯应该就在这座大厅的另一边等你。"
D.Strings[101433]="我又要请你把这些枯法者带到法兰纳尔了。训练他们战斗，并寻找对我们有帮助的圣物吧。"
D.Strings[101434]="是否要花费10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取折跃行走？"
D.Strings[101435]="<阿鲁因对你点点头。>"
D.Strings[101436]="我向来耳聪目明。我可以把我知道的告诉你……但这是有代价的。"
D.Strings[101437]="营业中。"
D.Strings[101438]="我向来欢迎富有成效的工作关系。"
D.Strings[101439]="那么……800份远古魔力吧，我对这玩意儿可是久仰大名了。"
D.Strings[101440]="省省你那空洞的威胁吧，$c。我输了，已经没什么可以给你这个可怜的“组织”了。"
D.Strings[101441]="你去过梦境林地了？你见到米露恩了吗？她是我梦中的女神。"
D.Strings[101442]="够了……够了……"
D.Strings[101443]="“大地之环”。呸，我看应该叫“泥巴议会”才对。"
D.Strings[101444]="“大地之环”。哈！还不如叫……“渣滓之环”比较好。"
D.Strings[101445]="“大地之环”。呸。我看应该叫……“垃圾之月”什么的。"
D.Strings[101446]="“大地之环”。噗！你们这些家伙全是欺世盗名之辈！"
D.Strings[101447]="“大地之环”。听起来就像……“泥巴之盘”、泥巴团，或者是——我想不出来了。反正你们这些家伙太差劲了。"
D.Strings[101448]="“大地之环”。真可笑！我看更像“蠢货之环”，哈。"
D.Strings[101449]="“大地之环”。别逗了。哈哈。来不及了。我已经笑出声了。没错，我笑的就是你们这群乌合之众。"
D.Strings[101450]="够了……我投降……"
D.Strings[101451]="森林已经悄悄将你的到来告诉了我，$c。它说有个人将成为自然的勇士，是森林的一份子。$b$b有些人对我们神圣的森林不够尊重。但你将指引他们改邪归正。"
D.Strings[101452]="哇哈哈哈哈！从你的表情来看，你掌握的唯一一种元素应该是吃惊元素吧。哈！"
D.Strings[101453]="你净化了梦境之路里的梦魇，可它现在又在腐蚀我宝贵的山谷了。"
D.Strings[101454]="是……你……我在梦境中见过你，被阴影所追逐。当我醒来时，却发现那些阴影已经蔓延到了我们的世界。"
D.Strings[101455]="我们不欠你们什么。我要挑战你！"
D.Strings[101456]="<使用80份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得魔网精通。>"
D.Strings[101457]="<使用70份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得魔网精通。>"
D.Strings[101458]="<使用60份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得魔网精通。>"
D.Strings[101459]="<使用50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得魔网精通。>"
D.Strings[101460]="<使用40份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得魔网精通。>"
D.Strings[101461]="<使用30份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得魔网精通。>"
D.Strings[101462]="<使用20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得魔网精通。>"
D.Strings[101463]="<使用10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得魔网精通。>"
D.Strings[101464]="是否要花费80份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取魔网精通？"
D.Strings[101465]="是否要花费70份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取魔网精通？"
D.Strings[101466]="是否要花费60份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取魔网精通？"
D.Strings[101467]="是否要花费50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取魔网精通？"
D.Strings[101468]="是否要花费40份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取魔网精通？"
D.Strings[101469]="是否要花费30份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取魔网精通？"
D.Strings[101470]="是否要花费20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取魔网精通？"
D.Strings[101471]="是否要花费10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取魔网精通？"
D.Strings[101472]="哎哟。"
D.Strings[101473]="拉我起来，谢谢！"
D.Strings[101474]="拉我，谢谢。"
D.Strings[101475]="还有复活吗？"
D.Strings[101476]="我怎么没有灵魂石？！"
D.Strings[101477]="我都没准备呢。"
D.Strings[101478]="我怎么死了？！"
D.Strings[101479]="我怎么死了？？？我根本没靠近它！"
D.Strings[101480]="我知道黄金海湾。我很了解它。"
D.Strings[101481]="我先走一步，去找线索。我们到那儿见！"
D.Strings[101482]="那些是深红之剑的船！肯定是……"
D.Strings[101483]="你去找风味朗姆酒……我去抓几个废物来！"
D.Strings[101484]="这可不是你们的地盘……谁派你们来的，小子？"
D.Strings[101485]="嘿，这封信用的可不是普通密码。这种密码真是是个杰作！"
D.Strings[101486]="我是血帆海盗的特塞斯！"
D.Strings[101487]="现在，我再问你一次……谁派你们来的？"
D.Strings[101488]="我们弄到想要的情报了。你先去达拉然，我就来！"
D.Strings[101489]="军情七处和深红之剑有勾结？这下糟了……"
D.Strings[101490]="哟呵！哟呵呵！我喜欢朗姆酒！"
D.Strings[101491]="我……我重获自我了！！谢谢你，纳兰度！愿狂怒再也无法控制你。"
D.Strings[101492]="狂怒……再也控制不了我了！赞美月神，你找到了我，尖牙大师。或者，用我们狼群的称谓，纳兰度。"
D.Strings[101493]="我的大脑依然有点迷糊，但是我记得有战斗……啊对……我们在跟萨特交战，然后就被狂怒所控制。"
D.Strings[101494]="我的手！我的腿！我……我又完整了！等一下……那不是月神镰刀吗？谢谢你救了我，纳兰度！"
D.Strings[101495]="我给你找了个目标。快行动吧。这是对抵抗军的严重威胁。"
D.Strings[101496]="你的快速反应拯救了许多生命。我们欠你的情。"
D.Strings[101497]="反对大魔导师的叛徒就藏在我们眼皮底下。我们要找到他们，结束这场叛乱！"
D.Strings[101498]="如果平民们不肯听话，我们就要用力量和恐惧来统治他们。针对大魔导师的叛乱即将破产！"
D.Strings[101499]="阿克蒙德，到此为止了！艾泽拉斯之魂起来反抗你了！"
D.Strings[101500]="我眼前的迷雾散开了，英雄们。阴影退去，梦境重获新生。"
D.Strings[101501]="这批货比你的命还值钱！你怎么敢这么粗心大意的！"
D.Strings[101502]="我的手滑了！请原谅我！"
D.Strings[101503]="我很怀念那段单纯的日子。只是把狗头人赶出去就能被称为英雄。$b$b那时人人都懂得尊重老人。那时候这个巨魔还有他的……小巨魔还没有出现。"
D.Strings[101504]="我记不起后来的事情了，只记得我和几个同胞醒来，一起集结行动，穿过了翡翠梦境。过了一段时间，我们来到了这片土地，然后大家就分道扬镳了。"
D.Strings[101505]="这头老牛沉浸在过去的记忆里无法自拔了。他太自欺欺人了。$b$b这个世界有一些很残酷的真相。它们就像妈妈的巴掌，足以把你从傻笑中打醒。"
D.Strings[101506]="唔。他们说那些瀑布太喧嚣了，伙计。你都分不清它们是从哪儿来的，要到哪儿去了。"
D.Strings[101507]="唔，你知道的，伙计。他们说这地方是深棕色的。我知道很多地方都比这里更绿。"
D.Strings[101508]="唔。你看到那些树了吗？他们说那些树太黑了，伙计。他们说黑不好。"
D.Strings[101509]="唔，你知道的，伙计。我觉得你需要换换风景。如果你喜欢棕色，就去西部荒野看看吧。"
D.Strings[101510]="早点把你的同伙说出来……你的痛苦就能早点结束。"
D.Strings[101511]="我们迟早会搞清楚是谁在苏拉玛跟燃烧军团作对。老实交代吧，我就在你发疯前给你痛快。"
D.Strings[101512]="救命……谁来停止这疯狂的一切。"
D.Strings[101513]="我是清白的！我是支持大魔导师的！"
D.Strings[101514]="我做什么都可以……只要放我走！"
D.Strings[101515]="谢谢，英雄们。"
D.Strings[101516]="快跑！我们得救了！"
D.Strings[101517]="我们的机会来了！快跑！"
D.Strings[101518]="纳兰度，如果你看到我的同胞，请将他们从狂怒中解救出来，就像你对我做的那样。"
D.Strings[101519]="仁慈的艾露恩啊，狂怒消失了！谢谢你，纳兰度！"
D.Strings[101520]="这……这是真的吗？我又能控制自己了！祝福你，纳兰度！"
D.Strings[101521]="我的心灵又自由了！我欠你一份人情，纳兰度！"
D.Strings[101522]="诅咒……已经……消失了！谢谢你，纳兰度！"
D.Strings[101523]="黑暗离开了我的心灵！我……我又是完整的人了！谢谢你，纳兰度！"
D.Strings[101524]="艾露恩祝福你。"
D.Strings[101525]="我已经恢复了。谢谢你。"
D.Strings[101526]="谢谢你，大德鲁伊。我们必须赢下这场战斗！"
D.Strings[101527]="我还以为自己要回归大地的怀抱了呢。谢谢你，大德鲁伊。"
D.Strings[101528]="感谢艾露恩的仁慈，我又能继续战斗了。谢谢你，大德鲁伊。"
D.Strings[101529]="我不会忘记你的恩情的，大德鲁伊。请接收我诚挚的谢意。"
D.Strings[101530]="看，敌人就在我们中间！"
D.Strings[101531]="你掩盖不了你的真面目，恶魔！"
D.Strings[101532]="我们中间还有他们的人！"
D.Strings[101533]="|TInterface\\Icons\\Spell_Fire_LavaSpawn:20|t席安良|cFFFF0404|Hspell:224588|h[热力迸发]|h|r！快将他移到水池里去！"
D.Strings[101534]="现在不行。"
D.Strings[101535]="你应该照顾好自己，$c。这是个危险的时代。"
D.Strings[101536]="我们要扩充部队。去找那些枯法者，平息他们的怒火吧。我会召唤他们前往沙尔艾兰。"
D.Strings[101537]="干得好。他们一定会对能帮助我们的事业而感到自豪的。"
D.Strings[101538]="我们继续前进！"
D.Strings[101539]="进战倒数，5！"
D.Strings[101540]="武器不错啊，$n。想帮忙的话，就去跟杰斯和阿莱利谈谈吧。"
D.Strings[101541]="大法师卡德加？$n？这可真让人意外。"
D.Strings[101542]="再次感谢你把我从那些海巨人手里救出来，$n。"
D.Strings[101543]="欢迎来到我的酒馆。没怎么收拾，真是抱歉，因为我不喜欢早起……"
D.Strings[101544]="看来你的研究进度良好。继续加油。"
D.Strings[101545]="努力钻研吧，总有一天，你甚至能超过我！"
D.Strings[101546]="你的工作将开创一个占星学的新时代！"
D.Strings[101547]="你有什么东西要修吗？"
D.Strings[101548]="$n，你能来真是太好了。主母为我们的部队开启了往返邪能之槌号的传送门，以便我们巩固这里的防御力量。\n\n燃烧军团已经入侵了法罗纳尔地峡。我有一个计划，可以在他们占领整个阿苏纳之前拦截并击溃他们。\n\n我需要你帮忙带领伊利达雷走向胜利。"
D.Strings[101549]="你好，$c。你是来帮助伊利达雷消灭燃烧军团的吗？"
D.Strings[101550]="你好，$n。在你的领导下，法罗纳尔的燃烧军团一定会迅速灭亡的。"
D.Strings[101551]="$n$g大人:女士;。我们非常感谢你能来领导我们战胜燃烧军团。"
D.Strings[101552]="我们欠你一份人情，$c。谢谢你来帮我们抵抗燃烧军团。"
D.Strings[101553]="我们得下去，$n。你的伊利达雷需要我们帮忙消灭燃烧军团。\n\n解决了恶魔之后，我们就可以着手寻找阿苏纳的创世之柱了。"
D.Strings[101554]="你来带领伊利达雷抵抗恶魔，我来研究一下我们在阿苏纳的下一步行动。\n\n我们必须找到创世之柱。我知道它就在这里的某个地方。"
D.Strings[101555]="感谢你来法罗纳尔帮忙，$n。我很尴尬，我们中居然出了一个叛徒，变成了燃烧军团的魔誓者。\n\n我们会让他们付出代价的。"
D.Strings[101556]="我们得让他们集中精力对付燃烧军团，而不是抱着过去的仇恨不放。"
D.Strings[101557]="感谢你挽救了法罗纳尔的战局，$n。\n\n我真不敢相信，赛娅娜居然叛变了。她背叛了我们所有人。还有其他人也成为了魔誓者。我们会追杀他们到天涯海角，让他们给燃烧军团的新主子陪葬！\n\n我发誓！"
D.Strings[101558]="非常抱歉，$n。我刚来这里侦察法罗纳尔的燃烧军团部队时受伤了。\n\n我还能为你做些什么吗？"
D.Strings[101559]="$n，战斗进行得怎么样？你需要补给或是修理装备吗？"
D.Strings[101560]="$n，燃烧军团派出了手下最强大的恶魔来对付我们。他们肯定不想输掉这场第三次大战，不将我们彻底从艾泽拉斯抹去，他们是不会罢手的。\n\n我们应该携起手来，好好“报答”他们的这番“深情厚谊”。"
D.Strings[101561]="虽然你之前的慷慨大方令我满意，但我必须坚持。\n\n你是知道现状的——经济环境时刻在变化，街上的人不断在死去——我只是在做生意而已。\n\n能弄来多少魔力就弄来多少。这是我现在的要价。\n\n<阿鲁因亲切一笑。>\n\n除非你不需要我的帮助。"
D.Strings[101562]="提供：1200份 |TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t|Hcurrency:1155|h|cFFFFFFFF 远古魔力|h|r"
D.Strings[101563]="此行为会令你减少1200份远古魔力。你确定要继续吗？"
D.Strings[101564]="我喜欢操练一点权术。不瞒你说，我还掌握了一定诀窍。"
D.Strings[101565]="求求你……帮帮我……"
D.Strings[101566]="那些上了船的人再也没有回来……别让他们带走我。"
D.Strings[101567]="我不想死，可他们会杀掉所有逃跑的人。"
D.Strings[101568]="别让他们带走我！"
D.Strings[101569]="他们把我们像畜生一样赶到一起。我不知道他们要把我们送去哪儿，可我知道我不想去。求求你……"
D.Strings[101570]="你好啊，亲爱的。希望你不要介意，奥图里斯让我帮忙把你的一些部队传送过来。\n\n看来燃烧军团已经在那座岛上站稳了脚跟。他认为我们最好别让他们占领整个阿苏纳。\n\n别担心。如果有需要的话，我可以将伊利达雷送回邪能之槌号，也能将他们再送过来。只要你有需要，他们随叫随到。"
D.Strings[101571]="你好啊，亲爱的。希望你不要介意，凯恩让我帮忙把你的一些部队传送过来。\n\n看来燃烧军团已经在那座岛上站稳了脚跟。他认为我们最好别让他们占领整个阿苏纳。\n\n别担心。如果有需要的话，我可以将伊利达雷送回邪能之槌号，也能将他们再送过来。只要你有需要，他们随叫随到。"
D.Strings[101572]="阿鲁因示意你上前。"
D.Strings[101573]="这边——我有发现。"
D.Strings[101574]="让我的蜂群毁灭你们！"
D.Strings[101575]="睡吧，忘记一切吧。"
D.Strings[101576]="战术撤退吗？"
D.Strings[101577]="等会儿再来干掉你……我是说，再见！"
D.Strings[101578]="什么？快住手！"
D.Strings[101579]="我要忍……忍！"
D.Strings[101580]="你就是这么消磨时光的吗？看来你不太会利用时间啊。"
D.Strings[101581]="你知道吗，这地方其实挺不错的。我们应该去放几把火。"
D.Strings[101582]="你知道吗？在我的世界里，小鬼们被折磨就是为了取乐。我本人就很擅长这种事。"
D.Strings[101583]="传说这个世界上有一些我们的先祖，他们没有加入燃烧军团。我敢打赌，他们都很无聊。"
D.Strings[101584]="伙计，我的胳膊都酸了。"
D.Strings[101585]="很好，我正想找你呢。"
D.Strings[101586]="跟你说吧，我就知道你需要有人来指导你。"
D.Strings[101587]="让我看看，今天该让你去干点什么呢……"
D.Strings[101588]="你现在明白了吗，人类？这个世界的命运早已注定。燃烧军团是不可阻挡的。"
D.Strings[101589]="军团的凝视锁定了你！快跑！"
D.Strings[101590]="|TInterface\\Icons\\inv_bannerpvp_01.blp:20|t你获得了|cFFFF0000|Hspell:224811|h[为了部落]|h|r效果！"
D.Strings[101591]="呃……$g主人:夫人;……"
D.Strings[101592]="这是恶作剧吗？我被恶搞了？真好笑，$g主人:夫人;！"
D.Strings[101593]="<使用50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力，获得首席奥术师的守护。>"
D.Strings[101594]="是否要花费50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:20|t远古魔力以获取首席奥术师的守护？"
D.Strings[101595]="这不是玩笑？可……这是宇宙的邪恶与黑暗中心！你肯定不是认真的吧！"
D.Strings[101596]="别把我们当成走私者。你应该把我们看做专业的救捞队。\n\n我们可是打捞专家，擅长回收各种海上漂浮物、废弃物、船难货物，当然，还有珍稀的考古发现。\n\n噢，还有，你最好避开南边的神殿一带。我派人去那里进行商业调查了，我可不希望你被当成来抢饭碗的。\n\n<沙考尔先生指了指无冕者的标志，悄悄跟你握了握手，然后眨了眨眼睛。>\n\n你想待多久都行，$n$g先生:女士;."
D.Strings[101597]="我们要不惜一切代价禁锢住它！"
D.Strings[101598]="抓住它！"
D.Strings[101599]="集中精神！绝不能让它跑了！"
D.Strings[101600]="你很快就能在我这里用金币或是职业大厅资源换取破碎命运印记了。但我现在还没有东西可以提供给你。"
D.Strings[101601]="感谢你的帮助，$n。我授权你代表我去跟恶魔猎手谈谈。"
D.Strings[101602]="你拥有的印记已经达到上限了！来找我之前，先把那些印记用掉吧。"
D.Strings[101603]="部落也没那么差劲。侏儒们，从另一个角度来说……"
D.Strings[101604]="噢，我有许多故事可讲！灰谷森林里激烈的游击战，北郡丘陵的混战，骑着巨龙在外域的天空中翱翔，还有奥格瑞玛的早餐。"
D.Strings[101605]="有没有和牛头人约会过？没有。"
D.Strings[101606]="救兵来了。"
D.Strings[101607]="回去干活。"
D.Strings[101608]="有没有拿着剥皮小刀跟雪人战斗过？没有。"
D.Strings[101609]="听说猪和哨声旅店来了几个海盗。那一定很有意思。"
D.Strings[101610]="你知道谁才是最伟大的战士吗？我可以让你猜一次。"
D.Strings[101611]="抓住他，抓住他，抓住他！！！"
D.Strings[101612]="不对，不是那个。是那个！！！"
D.Strings[101613]="达格洛普摇了摇头。"
D.Strings[101614]="哇，看来你不太擅长这种事啊。"
D.Strings[101615]="你想挨揍吗？"
D.Strings[101616]="真是惨，我的旧主人，就是那个肮脏的艾瑞达恶魔，都没有挨过这么多下。"
D.Strings[101617]="把你唤来唤去的可真有意思……我待会儿再回来。"
D.Strings[101618]="别担心，我一会儿会给你更多的指导。"
D.Strings[101619]="好好活下去，我还用得着你呢。"
D.Strings[101620]="这个契约可是有约束力的，我还会回来的。"
D.Strings[101621]="总有一天，我会成为你的主人，你得听我的！！"
D.Strings[101622]="你不是我的仆从？不过，我有的是手段来使唤你。"
D.Strings[101623]="谁把自己的契约给你了？我待会儿再去找他们算账。现在，到那儿去！"
D.Strings[101624]="抱歉，$n。补给品暂时被封存了。"
D.Strings[101625]="你恐怕很难找到还在营业的商店了，$n。"
D.Strings[101626]="现在恐怕不行。"
D.Strings[101627]="抱歉，$n。我的货物暂时不对外出售。"
D.Strings[101628]="抱歉，$n。上头要求我们封存货物，等待进一步的通知。"
D.Strings[101629]="对不起，我现在没有东西可卖了。"
D.Strings[101630]="我现在不收购新的补给品了，$n。$B$B这可能要持续一段时间。在事态平息之前，所有购买、出售和交易活动都是严格禁止的。"
D.Strings[101631]="抱歉，$n。麻烦等一切都平静下来之后再回来找我吧。"
D.Strings[101632]="不用担心，$n。训练很快就会恢复正常的。但现在，我们得先处理好手头的事。"
D.Strings[101633]="我现在恐怕帮不了你，$n。上头要求我们随时保持警戒状态。"
D.Strings[101634]="我非常愿意帮助你训练，但现在不行，$n。抱歉了。"
D.Strings[101635]="训练很快就会恢复的，$n。我向你保证。"
D.Strings[101636]="改天再说吧，$n。现在，我们必须保持警戒。"
D.Strings[101637]="小心点，$n。在事态平息之前，上头说了，访客的安全是第一位的。"
D.Strings[101638]="让我看看悬槌堡的围城。"
D.Strings[101639]="让我看看悬槌堡的奥秘圣殿。"
D.Strings[101640]="让我看看悬槌堡的元首高塔。"
D.Strings[101641]="让我看看黑石铸造厂的黑色熔炉。"
D.Strings[101642]="让我看看黑石铸造厂的熔渣车间。"
D.Strings[101643]="让我看看黑石铸造厂的钢铁装配车间。"
D.Strings[101644]="让我看看黑石铸造厂的黑手的熔炉。"
D.Strings[101645]="让我看看地狱火堡垒前的地狱破城者。"
D.Strings[101646]="让我看看地狱火堡垒的鲜血大厅。"
D.Strings[101647]="让我看看地狱火堡垒的暗影堡垒。"
D.Strings[101648]="让我看看地狱火堡垒的毁灭者高台。"
D.Strings[101649]="让我看看黑暗之门的阿克蒙德之死。"
D.Strings[101650]="我正想找人好好聊聊呢。"
D.Strings[101651]="注意那些树叶，我的朋友。"
D.Strings[101652]="愿森林保佑你。"
D.Strings[101653]="<这头双足飞龙拍打着翅膀，期待着即将到来的战斗>"
D.Strings[101654]="我还不能死。可惜，你们却要死了。"
D.Strings[101655]="请原谅我所做的一切。"
D.Strings[101656]="为了赢得战争，我需要更多的力量……"
D.Strings[101657]="我需要你的生命能量，忠诚的月之守卫。"
D.Strings[101658]="大人，军团干扰了我们的远程传送网，令我们的旅途变得……充满挑战。"
D.Strings[101659]="睁大你的眼睛，$n……那边有一群海盗！"
D.Strings[101660]="我接受你的效忠，$n。部落长存！"
D.Strings[101661]="它一定会的。"
D.Strings[101662]="说得好！"
D.Strings[101663]="我们准备好了，开始执行任务吧。"
D.Strings[101664]="真理守护者……"
D.Strings[101665]="白银之手……"
D.Strings[101666]="你必须留在神殿之巅！"
D.Strings[101667]="我，马迪亚斯·肖尔大师，在此授权深红之剑追杀叛逃探员安玻·吉尔妮。"
D.Strings[101668]="把她的脑袋给我带来，深红之剑就将得到皇室的赦免，并可自由出入暴风城港口。"
D.Strings[101669]="我……我是不会说的！"
D.Strings[101670]="这么说的话……你确实有点眼熟。"
D.Strings[101671]="噢，天呐，不！我听说过你……别杀我！"
D.Strings[101672]="是军情七处！是他们出钱让我们追杀安玻·吉尔妮的！"
D.Strings[101673]="你不在的时候，我们会努力守住离神殿更近的一个地方。愿月神指引你，$n。"
D.Strings[101674]="我……我都吓尿了！求求你……别杀我！"
D.Strings[101675]="嘘……小声点！如果让人看见我们说话，我们就死定了！"
D.Strings[101676]="是诺格弗格派我来的。我要打开保险箱。"
D.Strings[101677]="如果你是来找麻烦的，我可不想掺一脚……我这是在糊弄谁呢？什么都比这玩意儿好赚！"
D.Strings[101678]="是崔克西妮派我来的。我需要保险箱的钥匙……他说，这是你“欠她”的。"
D.Strings[101679]="抱歉，$n。鉴于最近的局势，我这阵子恐怕都不能给大家理发了。其他商人基本也都关门大吉了。$B$B<看了看周围的商人。>$B$B街上有流言说出事了，而且这些流言还不仅仅局限在这一带。整座城市都充满了……呃，我也不知道，还是不要多嘴的好。我可不想制造紧张气氛。我们都已经受够了。"
D.Strings[101680]="最近真是一团糟。他们可能还在遭受后遗症的折磨吧。搬迁整个达拉然可不容易！$B$B但愿一切都能尽快恢复正常。"
D.Strings[101681]="要我说的话，这里的空气不干净。自从我们来了这儿以后，大家的行为就变得古怪起来。还有议会……他们开会的频率也变高了。"
D.Strings[101682]="谁在那儿鬼鬼祟祟的？！"
D.Strings[101683]="有人溜进来了！"
D.Strings[101684]="我的殿下！那个陌生人的武器上带有艾萨拉女王本人的印记。"
D.Strings[101685]="这儿有人！"
D.Strings[101686]="出来，我看见你了！懦夫！"
D.Strings[101687]="我知道你在那儿……出来！"
D.Strings[101688]="你在这儿！现在你可以去死了！！"
D.Strings[101689]="我发现你了！去死吧！"
D.Strings[101690]="我要把你砸成肉泥！"
D.Strings[101691]="四处乱窜的家伙，你惹火我了！"
D.Strings[101692]="那把权杖不属于你，萨满。把它交出来！"
D.Strings[101693]="有入侵者！"
D.Strings[101694]="那把权杖属于我们的女王……"
D.Strings[101695]="你要为此付出代价！"
D.Strings[101696]="你怎么敢将我们敬爱的女王的权杖据为己有……"
D.Strings[101697]="不属于你……那把权杖不属于你……"
D.Strings[101698]="拜托，死亡骑士。不要用那把邪恶的战斧亵渎这片圣地。我在这儿都能感觉到它的饥渴。"
D.Strings[101699]="我们是防止燃烧军团毁灭这个世界的最后力量。"
D.Strings[101700]="这绝对是千载难逢的抢钱机会！"
D.Strings[101701]="马上就会有被爱情冲昏头脑的家伙对我们砸钱了！"
D.Strings[101702]="我们每闪现一次，我都要花上几天的时间来整理我的藏品。要是能有更轻松简便的整理方法就好了。"
D.Strings[101703]="伊利丹大人指引着我们。"
D.Strings[101704]="去找调酒师伊扎克，他应该知道怎么才能弄到保险箱的钥匙。"
D.Strings[101705]="如果他不说的话，你就提醒他一下，他在“那个地方”还欠我一样“那个东西”呢……听明白了吗？"
D.Strings[101706]="艾泽拉斯决不能陨落。"
D.Strings[101707]="你的剑……它们被诅咒了。请不要把死亡的寒意带进这片圣地！"
D.Strings[101708]="让燃烧军团去死吧。"
D.Strings[101709]="你今天可真走运，朋友！此时此刻，加里维克斯正在他的私人桑拿浴室里放松呢。"
D.Strings[101710]="如果你能潜入桑拿浴室，就可以拿到钥匙了。也只有在那个时候，他才不会随身带着钥匙！"
D.Strings[101711]="听好了，巨怪们！忘忧宫属于禁区！我不希望任何人踏足我的财产！"
D.Strings[101712]="你那把斧子……那是燃烧军团的武器。你确定自己能控制住它的嗜血欲望吗？"
D.Strings[101713]="现在，我要去蒸个桑拿放松放松……给我送杯冰镇鸡尾酒来，还有可可油！"
D.Strings[101714]="巨怪！可可油呢？！可！可！油！你们到底是哪个字听不懂？！"
D.Strings[101715]="好的，我做好揍人的准备了！"
D.Strings[101716]="呼……开始热起来了。该小睡一会儿了……"
D.Strings[101717]="等等……我的钥匙……有人偷了我的保险箱钥匙！！"
D.Strings[101718]="不管是谁都要付出代价！巨怪！找到他们！找到他们！"
D.Strings[101719]="那是……诅咒之喉吗？用燃烧军团的武器来对付燃烧军团吗？我喜欢你的想法，$n！"
D.Strings[101720]="这是何等亵渎的行为，$n？你怎么敢重铸那把该死的剑？这把剑毁灭了洛丹伦和它的王子！我警告过阿尔萨斯别去碰霜之哀伤，现在我同样要警告你：把那对玩意儿扔进海里去，否则它们迟早会毁了我们所有人。"
D.Strings[101721]="看来幽暗城的流言是真的——霜之哀伤被重铸了！你最好小心点，$n。那两把剑可能有着自己的意志。"
D.Strings[101722]="你的剑上缠绕着疾病和瘟疫，死亡骑士。离塞纳苟斯远一点。"
D.Strings[101723]="你那把恶魔之剑——它散发着腐蚀的气息，死亡骑士。快点办完你的事，然后带着那把剑离开这座神殿。"
D.Strings[101724]="呃——那把剑——你带的是个什么玩意儿？你身上全是疾病和腐败，死亡骑士！"
D.Strings[101725]="你也感觉到了吗，我都起鸡皮疙瘩了……"
D.Strings[101726]="你知道出什么事了吗？"
D.Strings[101727]="你最好暂时不要把这座旅店设为你的家。你下次用炉石返回时，我们可能已经不在位置了。"
D.Strings[101728]="唔……什么都没了，$n。所有的货物都被封存了，需要等待上头通知。$B$B这儿已经完全毁了。闪现一座城市……谁说这是个好主意的？我们得花上几个星期才能让这里恢复正常。"
D.Strings[101729]="抱歉，这儿太乱了。我们已经整理了一段时间了。$B$B<扫视了他的商店>。不过看起来成效不大。这地方简直就像是遭了龙卷风一样。我的货物都损坏了。这叫我怎么卖？$B$B下次再移动城市时，我一定要提前把所有东西都固定好。"
D.Strings[101730]="噢，我都没看见你来了！$B$B我们一直在忙着打扫。麻烦等我们收拾好之后再回来吧。"
D.Strings[101731]="这么多文件。这让我们怎么记录？它们洒得到处都是。$B$B我得花上好几个星期才能把它们整理好！"
D.Strings[101732]="请原谅。我最近经常头晕眼花的。自从我们抵达后不久，这种状况就开始了。"
D.Strings[101733]="欢迎光临，$n。抱歉，店里有点乱。我们正在打扫。$B$B上次的闪现给我们添了不少乱子！"
D.Strings[101734]="这可可油怎么这么滑？给我拿条毛巾来！这是谁送来的？他被炒了！"
D.Strings[101735]="只要你一声令下，我就能为你找出潜在的威胁！"
D.Strings[101736]="圣光在上……那是什么意思？"
D.Strings[101737]="图拉扬和奥蕾莉亚……我真不敢相信，他们这些年来一直活着……"
D.Strings[101738]="要不是亲眼所见，我根本不会相信。"
D.Strings[101739]="阿拉托尔说的对。图拉扬和奥蕾莉亚跨越千山万水给我们送来了警告。大领主，这事应该交给你来做决定。我们应该怎么做？"
D.Strings[101740]="我听说过这两位英雄的许多事迹。我毫不怀疑，他们的口信一定极其重要。"
D.Strings[101741]="母亲……父亲……"
D.Strings[101742]="道标沉寂了一段时间，它没有发出任何求援信号。你能修复它真好。"
D.Strings[101743]="在它所有的使用者中，那个德莱尼将道标运用得最好。在其他人都死去的时候，那个德莱尼也有活下来的希望。"
D.Strings[101744]="你的法杖，和维伦的水晶一样，都是来自我们的礼物。它们可以挽救你们免于覆灭。 别让它堕入虚空，这样的礼物已经所剩无几了。"
D.Strings[101745]="多使用道标，圣光的力量是无穷且无私的。"
D.Strings[101746]="$n！我看到你夺回了瓦雷迪斯·邪魂的双刀。希望你能更好地控制自己的心魔。"
D.Strings[101747]="你别忘了，纳萨诺斯，我杀过的人比你多多了！"
D.Strings[101748]="杰斯·织暗说的是真的。你拿到了奥达奇战刃，$n！在你的带领下，伊利达雷必将所向披靡。"
D.Strings[101749]="我是你的勇士，黑暗女王。我的责任就是保护你的安全。"
D.Strings[101750]="专找借口的勇士吗？！"
D.Strings[101751]="<低声嘟哝>"
D.Strings[101752]="你对自己做了什么，$n？与其说你是$r，不如说你更像恶魔。"
D.Strings[101753]="但愿你能在这片圣地里控制好自己的……能力……“恶魔猎手”。我们会盯着你的。"
D.Strings[101754]="你到底是站在哪边的，$n？这么多恶魔能量……"
D.Strings[101755]="一个恶魔猎手！很好，我正找你呢。"
D.Strings[101756]="随便选一张石床吧，伙计。纳瓦罗格说你可以在这里休息。"
D.Strings[101757]="我要招募瓦格里。"
D.Strings[101758]="我要招募女武神。"
D.Strings[101759]="很高兴再次见到你，$n。你一切都好吧？\n\n<马迪亚斯看了看四周，然后压低了声音。>\n\n无冕者的情况怎么样了？作为军情七处的首脑，我不能公开支持你们。\n\n不过，在与燃烧军团的战争结束前，我一定会全力支持你们的，哪怕是只能暗中行事。\n\n后会有期。"
D.Strings[101760]="你没有撒谎，埃利亚斯。恶魔猎手都跑出来了。小心——$n的眼睛能看见一切。"
D.Strings[101761]="一个恶魔猎手？真恶心！你的皮膜翅膀太恐怖了。"
D.Strings[101762]="一个恶魔猎手？呃——你的皮膜翅膀太恐怖了。"
D.Strings[101763]="来吧，旅行者。跟我们一起坐坐。$b$b我们的壁炉就是你的壁炉。$b$b留下来，跟我们一起坐坐。$b$b跟我们一起坐坐……"
D.Strings[101764]="欢迎你，外来者。$b$b你们很少出现在这么高的山上，但我们同样欢迎你们。"
D.Strings[101765]="卓格巴尔的袭击害得我们拿不出多少东西来招待客人，但我们的就是你的，英雄。"
D.Strings[101766]="我有想法的时候，就会去立柱子。"
D.Strings[101767]="等能付得起你的报酬之后，我还会回来的，阿鲁因。"
D.Strings[101768]="我的思维……正在枯竭……需要……帮助。"
D.Strings[101769]="这里的感觉有些奇怪。空气很新鲜，可是给人的感觉有点诡异。$B$B自从我们来了这里之后，人们的行为就变得很古怪。我不是说闪现造成的头晕，而是说人们的行为举止，还有那些偶尔传出的流言。"
D.Strings[101770]="<给织魔者科罗林喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>"
D.Strings[101771]="这么做将会消耗25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？"
D.Strings[101772]="你最好直接前往格罗玛什要塞，$n。"
D.Strings[101773]="就算是最敬业的工匠也需要偶尔休息一下。去拖一条毛毯，在我的壁炉旁安心睡一觉吧。"
D.Strings[101774]="接受痛苦的试炼吧，$n。我们会做好准备，随时响应你的召唤。"
D.Strings[101775]="只要你一声令下，我就能揪出敌人！"
D.Strings[101776]="嗯？有事儿吗？$B$B请原谅我的暴躁，可我已经要求过无数次了，在决定搬迁城市之前，麻烦提前通知我们一声。看看我的商店……东西洒得到处都是！伊尔蒂和瓦妮萨又要忙上几个月了$B$B现在，请你原谅，我得在他们决定再次搬迁城市前完成这些附魔！"
D.Strings[101777]="噢，嗨，亲爱的。你需要什么吗？还是我要找人帮你弄点什么来呢？\n\n噢，如果你只是想来聊聊，那尼基也随时奉陪。"
D.Strings[101778]="下去的路可不短，朋友。\n\n需要我帮忙吗？"
D.Strings[101779]="我老婆丢下我，跟一个一无是处的人跑了。"
D.Strings[101780]="看我跳舞可是要收费的！"
D.Strings[101781]="谁看见斯坦奇了？我有点担心了。"
D.Strings[101782]="往右扭！现在，往左扭！"
D.Strings[101783]="事情已经不可能更糟了，不是吗？"
D.Strings[101784]="那是什么味儿？"
D.Strings[101785]="谁看见我的兄弟达瑞尔了？"
D.Strings[101786]="去找斯奇马克要你的热啤酒和冷香肠吧！告诉他是乔伊让你去的！"
D.Strings[101787]="下水道鲨鱼？一群恶心的家伙，我只看到过一次。"
D.Strings[101788]="大……大人，我要死了……"
D.Strings[101789]="力量……在衰退……"
D.Strings[101790]="动不了了……太虚弱了……"
D.Strings[101791]="你不能这么做，伊利丹。"
D.Strings[101792]="住手！你会杀了我们的！"
D.Strings[101793]="下达勇士武器订单。"
D.Strings[101794]="我的锁链会捆住你。"
D.Strings[101795]="你是个怪物，伊利丹！"
D.Strings[101796]="你休想轻易杀了我！"
D.Strings[101797]="鸦堡卫队，把这些恶魔送回老家去！为了艾萨拉！为了卡利姆多！"
D.Strings[101798]="你不是我的队长了，伊利丹！去死吧！"
D.Strings[101799]="你背叛了我们！"
D.Strings[101800]="你想要我的法力？来啊！有种就来拿啊！"
D.Strings[101801]="你不比那些袭击我们的恶魔好多少！"
D.Strings[101802]="你想要魔力？来啊，尝尝吧！"
D.Strings[101803]="我这也是逼不得已！"
D.Strings[101804]="你将为更伟大的事业献身，忠诚的助祭！"
D.Strings[101805]="看看周围！这是唯一的方法！"
D.Strings[101806]="能够得到这个效忠的机会，你应该心存感激！"
D.Strings[101807]="为了拯救世界，你们中的一些人必须死！"
D.Strings[101808]="你没资格批判我！我这都是为了艾泽拉斯！"
D.Strings[101809]="军团的威胁需要用生命去抵抗。你们的生命！"
D.Strings[101810]="我会照顾好你的家人的，朋友。"
D.Strings[101811]="难道你没看见我为了拯救世界而做的牺牲吗？！"
D.Strings[101812]="伊利丹……为什么？"
D.Strings[101813]="月神，带我走吧！"
D.Strings[101814]="这是一条黑暗的道路，伊利丹。一条不归路……"
D.Strings[101815]="我也不想挑起重担，但这是命运的决定……"
D.Strings[101816]="你的生命能量将带给我们殊死一搏的机会，助祭。"
D.Strings[101817]="如果有别的办法就好了，可我需要力量，才能让我们活下去。"
D.Strings[101818]="感谢你的牺牲。我不会让你白死的。"
D.Strings[101819]="你的死能让我活下去！我必须实现我的命运！拯救这世界！"
D.Strings[101820]="我是艾泽拉斯的复仇化身！"
D.Strings[101821]="你的生命能量强化了我！我是不可阻挡的！"
D.Strings[101822]="军团将在我面前瑟瑟发抖！所有人都一样！"
D.Strings[101823]="我发现一个！立刻收紧这一带的防御。"
D.Strings[101824]="帮帮我……求求你。我的思绪……越来越慢。"
D.Strings[101825]="<给时占师薇林亚喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>"
D.Strings[101826]="无冕者必须用我们最擅长的方式打击燃烧军团：包括但不限于各种诡计、阴谋、骗术，还有政治。\n\n在燃烧军团被击败前，我们的合作就不会终止，这也将是我的第一要务，$n。我相信这对你们来说也是一样的。"
D.Strings[101827]="戴上时髦的间谍眼镜，找到血迹！"
D.Strings[101828]=S[498]
D.Strings[101829]="我的火焰……黯淡了。我恐怕不久于世了。"
D.Strings[101830]="<给织焰者欧文喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>"
D.Strings[101831]="升腾者不会被命令，只能被释放。"
D.Strings[101832]="招募升腾者"
D.Strings[101833]="为了帮助别人，我成为了一名女祭司。但我最近一直在想，我是否还能发挥更大的作用？"
D.Strings[101834]="这头魔刃豹发出温柔的呼噜声，示意你靠近些。"
D.Strings[101835]="专家？我都被困在这儿好几个小时了！"
D.Strings[101836]="嘿！慢点儿！如果有可能的话，我还想留着这两条腿……等等！我都到这儿了，那我的其他部分呢！？"
D.Strings[101837]="噢，看呐，又一个看热闹的。好吧……尽管看吧。大家都来围观我这个可怜的侏儒了。等我下来之后……"
D.Strings[101838]="对，如果有恶魔出现的话，记得保护好我！你懂的，我现在完全没有自我保护能力了。"
D.Strings[101839]="我以前都没发现，这里的地砖保养得不错嘛。"
D.Strings[101840]="“可能要等到我们下次传送”是什么意思？我不能待在这儿！我还有事儿呢！"
D.Strings[101841]="那是什么？住手！有人在另一边捅我！"
D.Strings[101842]="我们可以开始了。"
D.Strings[101843]="为聚焦水晶充能"
D.Strings[101844]="凡瑟尔认为我们呆在这里会更安全。在我的宝贝康妮遇到这种事之后，我也这么认为。\n\n堕夜精灵的生活很艰难，但我们必须坚持下去。\n\n谢谢你救了我的女儿。"
D.Strings[101845]="好吧，我们可以等下次传送，谁知道呢？船到桥头自然直！"
D.Strings[101846]="你准备好之后，就到祭坛上来宣誓吧。"
D.Strings[101847]="如果我们顺时针转一下，那么……不行。可能要逆时针……"
D.Strings[101848]="别担心，我们会把你和你的……另一半用拉链缝起来的。我干嘛老说这种话呢？"
D.Strings[101849]="我还得想想。这种情况很特殊。这种事可不能……半途而废啊。"
D.Strings[101850]="在这种特殊情况下，我也想不到什么好法子了。等一等吧！我们一定会想到办法的。"
D.Strings[101851]="幸好鱼缸在传送前是空的。否则就完全是另一回事了！"
D.Strings[101852]="<这头魔刃豹盯着你，你身上可能有它想吃的东西。>"
D.Strings[101853]="<给魔刃豹喂食10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>"
D.Strings[101854]="今天，在不朽的勇士见证之下，我在此宣誓："
D.Strings[101855]="我将誓死捍卫骑士团，"
D.Strings[101856]="与同胞一起效忠白银之手。"
D.Strings[101857]="以此誓言为证，我将重生，"
D.Strings[101858]="成为圣光的战士。"
D.Strings[101859]="我将成为人民之盾，奉献之手，制裁之剑。"
D.Strings[101860]="保护弱者，坚守正义，践行正道。"
D.Strings[101861]="这地方真是一团糟！"
D.Strings[101862]="我们几乎把一切都考虑到了！谁能想到传送达拉然会造成这些问题呢？再来一支笔，几只鸟，一切就能恢复正常了！$B$B<环顾房间>。$B$B好吧，除了鱼缸里那个可怜的家伙。但愿他们能尽快解决这个问题。"
D.Strings[101863]="我的奶酪只过来了一半！一半！$B$B守着一大堆红酒和一点奶酪屑，这叫我们怎么开红酒奶酪店？这真是太离谱了！还有……$B$B噢，我的天！我开始头晕了。这世界到底怎么了？"
D.Strings[101864]="噢，别管他。那家伙太健忘了。在传送前，我们已经把以前的货物都放好了。$B$B等商店重新开业后再来找我们吧！我相信我们很快就能抵达目的地了！"
D.Strings[101865]="有不少人都来找我解决传送的后遗症了。$B$B要是能找到以前那些配方就好了……它们肯定就在这里！"
D.Strings[101866]="如果你要找多萝希的话，她就在里面。但如果你是来买补给品的话，那我们恐怕暂时无法供应，抱歉。"
D.Strings[101867]="但我们有个小问题，那就是系统崩溃。"
D.Strings[101868]="我要你按下那个写着“不要按这个按钮”的红色大按钮。"
D.Strings[101869]="下次再有人告诉你，他们要用魔法传送一座城市时，你最好做好最坏的打算！我说的是，“最坏”的打算！"
D.Strings[101870]="这个盒子闪耀着明亮的光芒。"
D.Strings[101871]="这个盒子开始发出美妙的音乐。"
D.Strings[101872]="音乐声越来越响。"
D.Strings[101873]="这个盒子又闪了一次光。再来一段旋律，它就能彻底激活了！"
D.Strings[101874]="如果你还没有学过怎么在潘达利亚飞行，就借用加多克飞去锦绣谷吧。"
D.Strings[101875]="我……太虚弱了……"
D.Strings[101876]="可怕……太可怕了。"
D.Strings[101877]="我……我想我能自己回去。谢谢你。"
D.Strings[101878]="自由……总算自由了。我该怎么离开这儿？"
D.Strings[101879]="求求你……杀光那些怪物。"
D.Strings[101880]="|TInterface\\Icons\\spell_deathknight_necroticplague.blp:20|t你受到了|cFFF00000|Hspell:206480|h[腐肉瘟疫]|h|r的影响！"
D.Strings[101881]="有何指令?"
D.Strings[101882]="发出先锋的召唤"
D.Strings[101883]="下达一份勇士武器订单。"
D.Strings[101884]="鲁妮尔……我最亲爱的鲁妮尔……我怎么能让你遇到这种事？"
D.Strings[101885]="开始召唤"
D.Strings[101886]="开始为邪能之锤充能"
D.Strings[101887]="时候到了吗？"
D.Strings[101888]="开始仪式"
D.Strings[101889]="我得处理完这批样本，$n！上一批太不稳定了，在传送的时候差点害死我们！$B$B你可别把这事告诉别人啊。"
D.Strings[101890]="我要听听这个恶魔猎手想说什么。"
D.Strings[101891]="他们杀了她……那些枯法者杀了我的鲁妮尔。我……已经一无所有了。"
D.Strings[101892]="下达一份勇士武器订单"
D.Strings[101893]="<给洛瑞安喂食25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>"
D.Strings[101894]="你需要什么吗，小$n？"
D.Strings[101895]="谢……谢谢你……我……我不知道该怎么活下去了……我已经失去得太多了。"
D.Strings[101896]="等等……你听到没有？"
D.Strings[101897]="枯法者！他们追上我们了。求求你，救救我！"
D.Strings[101898]="把死者带来给我，我会好好利用他们的。"
D.Strings[101899]="抱歉，$n，但我们收到通知，暂时不接受任何新学员。我保证，等抵达最终的目的地后，一切都会恢复正常的。"
D.Strings[101900]="看看这个乱劲儿！我们的东西被扔得到处都是！书籍躺在地板上，工具掉了一地……我真希望我们在传送整座城市前，能先通知一声！$B$B看看那边的多利安。那个可怜的家伙还没缓过劲儿来呢。"
D.Strings[101901]="欢迎光临瘤节之枝，$n。"
D.Strings[101902]="如果你不想毁掉这双靴子的话，最好退后一点。"
D.Strings[101903]="我欠你两条命……我现在身无长物，但你可以随意查看我的补给品，挑选你需要的东西。"
D.Strings[101904]="哟，这不是奥丁的勇士吗！"
D.Strings[101905]="我听说过你的事迹。让我看看它们是否言过其实吧！好吗？"
D.Strings[101906]="冰霜巨龙已经蠢蠢欲动了。"
D.Strings[101907]="这边，$c朋友！我这里有亮晶晶的宝贝提供。来看看吧！"
D.Strings[101908]="<树叶的沙沙声>"
D.Strings[101909]="招募一棵战争古树"
D.Strings[101910]="愿奥丁的荣耀与你同在，瓦拉加尔。"
D.Strings[101911]="招募一位天神化身"
D.Strings[101912]="这些食尸鬼随时都能为您效劳，死亡领主。"
D.Strings[101913]="抱歉了，$n。我不会插手试炼，哪怕是对我选中的勇士！"
D.Strings[101914]="我这儿或许有你用得上的东西，$n。"
D.Strings[101915]="在我那会儿，这些树比现在要绿多了。"
D.Strings[101916]="天哪！真是时移世改。"
D.Strings[101917]="既然托尔里说你是来帮我们的，那你就能在我们的壁炉旁休息，并分享我们的烤肉和蜜酒！"
D.Strings[101918]="他们怎么会相信使徒的谎言呢？听我说——这一定是有黑暗魔法在作祟。\n\n拜托了，如果你有办法阻止的话，就快动手吧。已经死了太多无辜的人……"
D.Strings[101919]="侍从的训练通常都不会这么快完成，但我帮你突击训练了一批。"
D.Strings[101920]="唔……今天没有特别的绵羊吗？该死！但愿明天能有好运气吧？"
D.Strings[101921]="欢迎，$n。愿至尊天神保佑你。"
D.Strings[101922]="欢迎，$n。我这儿或许有你用得上的东西。"
D.Strings[101923]="你休想绕过我们，凯丽翠丝夫人！"
D.Strings[101924]="嗨，$n！我今天能帮你什么忙吗？"
D.Strings[101925]="无论你做什么，都不要吃碗里的果子。$b$b那玩意儿的质量太差了。如果你想尝尝苏拉玛最好的美食，就让我来给你展示一下真正的美味吧。"
D.Strings[101926]="别*嗝儿*捣乱！我们需要暗夜井的力量……"
D.Strings[101927]="今天你的火焰烧得真旺，$n。"
D.Strings[101928]="黄金能够照亮最黑暗的地方。"
D.Strings[101929]="嗨，$n。我这儿或许有你用得上的东西。"
D.Strings[101930]="所有人请后退！这只是城市传送的副作用而已。我们很快就会恢复营业的！"
D.Strings[101931]="诸位！诸位！拜托了……这看起来可能有点诡异，但一切都在我们的掌握之中。我们已经呼叫了额外的守卫来防止财物遗失。"
D.Strings[101932]="对，对。我们知道它看起来很吓人。等恢复营业之后，你们托管的财物都会好好的。我向你们保证。"
D.Strings[101933]="完全不必担心。这只是传送巨型魔法城市的副作用而已。"
D.Strings[101934]="我们的员工正在加班加点地工作，保护大家的财产安全！大家完全不必恐慌。"
D.Strings[101935]="请过几天再来吧。我们重视每一位客户……"
D.Strings[101936]="我辜负了我的王国和我的人民……我不会再辜负这个世界了。"
D.Strings[101937]="我将获得新生，成为人民之盾，奉献之手，与制裁之剑。"
D.Strings[101938]="不……哦，不，是对。"
D.Strings[101939]="前景很明确。你死定了！"
D.Strings[101940]="输定了。"
D.Strings[101941]="回复……很模糊……再试一次？"
D.Strings[101942]="你或许能活下来。希望很大。"
D.Strings[101943]="让我跟线人商量一下……不行。"
D.Strings[101944]="让我跟线人商量一下……可以。"
D.Strings[101945]="在这条时间流……不太可能。"
D.Strings[101946]="前景不明，再收集4289个埃匹希斯水晶后再问吧。"
D.Strings[101947]="你的声卡运转得很好。"
D.Strings[101948]="谢谢你把我从那个可怕的地方救出来。$b$b我很擅长修理装备。你有什么东西要修理吗？"
D.Strings[101949]="我……谢谢你。他们听起来都饿了……"
D.Strings[101950]="我会到安全的地方去的。他们休想在再抓住我！"
D.Strings[101951]="想要再比一场吗，$n？我随时随地都可以。"
D.Strings[101952]="我们完全了解情况，一切都在掌握之中！"
D.Strings[101953]="这很正常。别大惊小怪的！"
D.Strings[101954]="我们很快就能解决这个问题！请稍微忍耐一下。"
D.Strings[101955]="麻烦提醒吉恩一下，我可是要额外收费的。从技术上说，我还在上班呢。"
D.Strings[101956]="一切正常！像平时一样去办你的业务吧。一切都在我们掌控之中！"
D.Strings[101957]="啊，又一位宝贵的客户！欢迎欢迎！"
D.Strings[101958]="吉恩！……吉恩！……麻烦你提醒吉恩一下，我还在这里耐心等待恢复正常呢。谢谢。"
D.Strings[101959]="这些瓦拉加尔候选者会帮我们对抗燃烧军团的！"
D.Strings[101960]="放心吧，这些弓箭手绝对能百发百中。"
D.Strings[101961]="但愿这些小鬼能帮上你的忙，虚空领主。"
D.Strings[101962]="在我们抗击燃烧军团时，这些元素一定会成为有用的盟友。"
D.Strings[101963]="我能帮你什么忙吗，影行者$n？"
D.Strings[101964]="破碎之手一定会让部落恢复昔日的荣光。"
D.Strings[101965]="有什么我能帮得上忙的事情吗？"
D.Strings[101966]="让开！天知道这玩意儿会撞上什么东西！"
D.Strings[101967]="让开！这玩意儿可不安全！"
D.Strings[101968]="小心！我控制不了这玩意儿了！"
D.Strings[101969]="让开！这艘飞艇发疯了！"
D.Strings[101970]="飞艇失控啦！大家快跑啊！"
D.Strings[101971]="滚出去，恶棍！"
D.Strings[101972]="我想交易。"
D.Strings[101973]="我想把炉石绑在这里。"
D.Strings[101974]="在沙尔艾兰安个新家？"
D.Strings[101975]="<给夜之子贱民喂食5份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>"
D.Strings[101976]="这么做将会消耗20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？"
D.Strings[101977]="我过去的罪孽都是我一个人的。但燃烧军团腐化了我的教团，让我们偏离了正道。$b$b我要让燃烧军团为他们的谎言付出代价！"
D.Strings[101978]="召唤师，开始仪式！"
D.Strings[101979]="对，对，起作用了！"
D.Strings[101980]="仪式完成了，抓住它，快！"
D.Strings[101981]="Elune-Ado……等等，你手上拿的不是月神镰刀吗？太了不起了！"
D.Strings[101982]="大导师，要小心使用这把镰刀。我还是希望自己的意识归自己管。"
D.Strings[101983]="你背着的是月神镰刀吗？它真的可以把你变成野兽吗？"
D.Strings[101984]="月神镰刀！如果需要这样危险的武器的力量才能拯救我们，那么末日看来的确是近了。"
D.Strings[101985]="欢迎，大导师。能亲眼看到月神镰刀的主人，实在是荣幸。"
D.Strings[101986]="那对爪子看起来足以削铁如泥。你能站在我们这边实在太好了。"
D.Strings[101987]="传言是真的。$n使用着乌索克之爪！"
D.Strings[101988]="我们的勇士手持乌索克之爪，屹立于此！军团的日子不多了！"
D.Strings[101989]="欢迎大德鲁伊$n，乌索克选中的救世之星！"
D.Strings[101990]="特塞斯会为我们安排一条船。我们会远离陆地，等到天色昏暗，且海上浓雾弥漫时，再送我们上岸。\n\n你准备好出发后，就告诉我一声吧，$n。"
D.Strings[101991]="阿莎曼之牙！那么灰烬德鲁伊神殿受到攻击的传言是真的！"
D.Strings[101992]="那对匕首样子好奇怪。是……牙齿吗？"
D.Strings[101993]="阿莎曼之牙！我以为灰烬德鲁伊绝不会让它脱离视线！"
D.Strings[101994]="你好，$n。我已经听说了你抗击燃烧军团入侵的事迹。"
D.Strings[101995]="我并不想干扰这么重要的任务，但我需要你帮忙……从中斡旋。我恐怕会惹恼一个老朋友。"
D.Strings[101996]="$n，我认得这对匕首。这是阿莎曼之牙，是吧？你一定是为灰烬德鲁伊做了什么了不起的事情，他们才会让你拿走这对匕首。"
D.Strings[101997]="为了保卫东部王国，达拉然移动了位置。它就在逆风小径的卡拉赞上方。请到这里来见我。"
D.Strings[101998]="你能加入塞纳里奥议会，我实在太高兴了，阿莎曼之牙的持有者！"
D.Strings[101999]="加尼尔的守护者在此！愿月神祝福你，$n。"
D.Strings[102000]="很高兴看到加尼尔有了个好去处。"
D.Strings[102001]="是$n！这位英雄清除了加尼尔的腐蚀！"
D.Strings[102002]="是加尼尔的守护者！我们全靠你了，$n。"
D.Strings[102003]="咒法师们，开始引导法术吧！"
D.Strings[102004]="<腐肠转向你的方向，打了一个响嗝儿。>$b$b腐肠……腐……肠！"
D.Strings[102005]="水晶充能完毕。请随意使用吧。"
D.Strings[102006]="你好啊，亲爱的！$b$b我能为你做点什么吗？"
D.Strings[102007]="我们没有酒水了，但有各种美食、饮品和宽敞舒适的休息环境！"
D.Strings[102008]="请坐，好好放松一下吧！"
D.Strings[102009]="欢迎光临。我能为你做点什么吗？"
D.Strings[102010]="啊哦。$b$b你的护甲好像需要修理了。"
D.Strings[102011]="我的技术无与伦比！$b$b但我听说来了个竞争者。有人在城外开了个铁匠铺。$b$b我喜欢挑战。放马过来吧！哈哈哈！"
D.Strings[102012]="如果你还不太确定自己要走的道路，我可以把你送回地面。需要我这么做吗？"
D.Strings[102013]="我要返回地面。"
D.Strings[102014]="<这个防御矩阵似乎缺少能量。>"
D.Strings[102015]="<将20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力放入防御矩阵。>"
D.Strings[102016]="恶魔的利刃能够发现你的护甲上最小的裂缝，$n。修理一下吧，否则你的脑袋可能会被恶魔挂在枪头上。"
D.Strings[102017]="银月城就是你的后盾，$n。请让我们用神圣的力量祝福你的武器吧。"
D.Strings[102018]="|TInterface\\Icons\\sha_spell_shadow_shadesofdarkness_nightmare:20|t%s开始施放|cFFFF0000|Hspell:214876|h[梦魇猛兽]|h|r！"
D.Strings[102019]="这里……比我想象的还要糟糕。"
D.Strings[102020]="让我从这场梦魇中醒来吧！"
D.Strings[102021]="别再摆弄那些魔精了，我们要把它带去破碎海滩！"
D.Strings[102022]="督军！"
D.Strings[102023]="别干站着，$n！这些恶魔可不会自己死掉！"
D.Strings[102024]="迟到总比不到强，小伙子。我们的人还在浴血奋战！你准备——"
D.Strings[102025]="如果我们不能阻止萨维斯，梦魇就会吞噬艾泽拉斯。"
D.Strings[102026]="我们被打了个措手不及！我们要彻底解决这些恶魔！"
D.Strings[102027]="击退他们！我们不能失去这座城市！"
D.Strings[102028]="了不起，你的武器和经验说明，哪怕是瓦拉加尔也能从年轻种族身上学到些什么。在我漫长的生命中，我也从没见过这些新敌人和新的战斗方式。你给我提供了一次丰富的工作和学习的机会，谢谢你。"
D.Strings[102029]="联盟的英雄们，在这最黑暗的时刻，我对你们写下这段话。燃烧的大军，正从地狱之喉涌出，回到了艾泽拉斯。"
D.Strings[102030]="看起来很久没人用这泉了。"
D.Strings[102031]="新一代的霜火之怒，艾索洛托斯之子，艾舍尔想要赐予你他的祝福。"
D.Strings[102032]="<提供20份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。>"
D.Strings[102033]="你们成功了，勇士们！你们解锁了梦魇之虹。只要你们一声令下，我就能打开它。"
D.Strings[102034]="梦魇的守护者倒下了。为了打开通向萨维斯的道路，我们还要做些什么？"
D.Strings[102035]="你听到塔中传来了某个复杂仪式富有韵律的吟唱声和踱步声。"
D.Strings[102036]="仪式中断了。悬浮在暗夜井中的身影苏醒了。"
D.Strings[102037]="我希望能有比这些恶魔更大的发现。或许我们能找到一个深渊领主。我一直希望能束缚一个深渊领主。"
D.Strings[102038]="我们应该继续巡逻。天知道这一带还藏着多少入侵者。"
D.Strings[102039]="我们不能再等下去了。我们必须正面迎战燃烧军团。"
D.Strings[102040]="我做好保卫虚空之光神殿的准备了。"
D.Strings[102041]="清醒精华能指引我们进入梦魇的核心吗？"
D.Strings[102042]="郭雅夫人打包带走了所有的货物，留下我看房子。她提到了天空之城什么的。哈哈！城市才不会飞呢！"
D.Strings[102043]="我们必须在古尔丹完成仪式前阻止他。"
D.Strings[102044]="今天燃烧军团必将失败，勇士。"
D.Strings[102045]="这个结界脉动着充盈的能量。"
D.Strings[102046]="前进，我们不能在这儿耽搁太久。"
D.Strings[102047]="<使用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力抽取一部分魔网能量。>"
D.Strings[102048]="我一直在等待着回家的这一天……"
D.Strings[102049]="暗夜井的力量在召唤我。"
D.Strings[102050]="我们冲破了监狱大门！通往达拉然的道路打开了！"
D.Strings[102051]="艾利桑德要为她的背叛付出代价。"
D.Strings[102052]="教团与你同在。"
D.Strings[102053]="要求得到祝福"
D.Strings[102054]="来吧，卑贱的外来者。我甚至可以让你先出手。抓紧机会吧。"
D.Strings[102055]="你到底要不要先攻击我，还是要像个哭哭啼啼的懦夫一样对我干瞪眼？"
D.Strings[102056]="等会再钓鱼，先帮我打倒这个元素！"
D.Strings[102057]="我向来讨厌水元素……尤其是这么大的！"
D.Strings[102058]="这就是魔法的问题，你永远不知道它什么时候会跟你作对！"
D.Strings[102059]="大人，你身后！又是邪能之喉！"
D.Strings[102060]="月之守卫，将你们的能量集中到我身上！让这些怪物看看魔法的力量！"
D.Strings[102061]="我们需要休息，大人。"
D.Strings[102062]="跟我说说你的柱子。"
D.Strings[102063]="哈！我已经说了十三个字了，这是我的极限。"
D.Strings[102064]="骄傲地穿上你的战袍吧，$n。我们的红色战袍可以让敌人看不见你的伤口。"
D.Strings[102065]="达拉然遇袭，$n！军团想击落我们！"
D.Strings[102066]="我们需要创世之柱，才能将恶魔赶回扭曲虚空并拯救我们的世界。"
D.Strings[102067]="到逆风小径上空的达拉然来见我。我有一个计划，很危险……但至少是个计划！"
D.Strings[102068]="这些恶魔到底放出了什么魔崽子啊？！愿月神保佑我们！"
D.Strings[102069]="来吧，$n。到守护者熔炉来见我。"
D.Strings[102070]="白银之手的圣骑士们！到战场上来吧！"
D.Strings[102071]="大人，我愿意助你一臂之力。"
D.Strings[102072]="正在破译"
D.Strings[102073]="<传送门散发着魔力。>"
D.Strings[102074]="我还没准备好。"
D.Strings[102075]="我们在这里的任务极其重要。但如果你需要再准备一下，我可以把你送回以太大厅。你确定要回去吗？"
D.Strings[102076]="是的，送我回去。我还有其他事要做。"
D.Strings[102077]="是时候了！白银之手先锋，战斗吧！"
D.Strings[102078]="梦魇开始占据你了！"
D.Strings[102079]="和我一起到纪元之种来，大德鲁伊。在那里，我们会解开更多你武器中的谜团。"
D.Strings[102080]="|TInterface\\Icons\\ability_priest_shadowyapparition:20|t%s召唤了一个|cFFFF0000|Hspell:226089|h[暗影镜像]|h|r！快放逐它！"
D.Strings[102081]="你们的入侵早就被发现了，但仪式必须进行下去。"
D.Strings[102082]="闯入者！"
D.Strings[102083]="别怕，我会抽取暗夜井的力量消灭他们的！"
D.Strings[102084]="宫廷卫士！保护我们继续仪式！"
D.Strings[102085]="恐痕恶魔随时听候你的吩咐，大统领。\n\n愿敌人的世界都匍匐在你的脚下。"
D.Strings[102086]="是时候让你接过四骑士之首的位置了。"
D.Strings[102087]="你准备好之后，就来上层找我吧，死亡领主。"
D.Strings[102088]="骑士们，我们的时代降临了！"
D.Strings[102089]="看来我们来得正是时候。"
D.Strings[102090]="燃烧军团开始攻击了。我们必须保住虚空之光神殿！"
D.Strings[102091]="我们已经全副武装，随时可以战斗，大祭司。"
D.Strings[102092]="让我们帮助圣光的盟友，并保卫虚空之光神殿吧。去传送门！"
D.Strings[102093]="我是主宰之子。你不是我的对手。"
D.Strings[102094]="在我正式行动前，你会是个很好的热身。"
D.Strings[102095]="精彩的战斗……"
D.Strings[102096]="你听到背后有什么东西飞快地离开了……然后就是一片死寂。"
D.Strings[102097]="我将为你而战。"
D.Strings[102098]="我的生命属于圣光。"
D.Strings[102099]="让我给你展示一下燃烧军团的力量吧！"
D.Strings[102100]="你听到暮色森林的传送门那边传来一声诡异而凶猛的尖叫。"
D.Strings[102101]="你听到菲拉斯的传送门那边传来一声诡异而凶猛的尖叫。"
D.Strings[102102]="你听到辛特兰的传送门那边传来一声诡异而凶猛的尖叫。"
D.Strings[102103]="这些貌似普通的武器蕴藏着隐蔽的力量。"
D.Strings[102104]="招募白银之手骑士"
D.Strings[102105]="招募白银之手圣殿骑士"
D.Strings[102106]="<这个孤独的流浪者遭遇了某种可怕的灾难。>"
D.Strings[102107]="<这个孤独的流浪者遭遇了某种可怕的灾难。>\n\n<不幸的是，你没法把他放出来。>"
D.Strings[102108]="我已经收集到全套的编年史了。"
D.Strings[102109]="太好了！我很高兴看到你这样的年轻英雄还愿意花时间来研究历史。总算有人明白，被我们抛在脑后的东西才是最重要的了。\n\n我这儿有点东西……一本完全不同的书。我想把它送给你，以感谢你付出的努力。你喜欢吗？"
D.Strings[102110]="守卫嗅了嗅你，轻轻咕哝了两声。"
D.Strings[102111]="这是我的岛！"
D.Strings[102112]="再去找个该死的岛吧！！"
D.Strings[102113]="可怕的任务，但你别无选择。我来把艾露恩之泪送走。到紫罗兰城堡来见我。"
D.Strings[102114]="你休想抢走我的岛！！"
D.Strings[102115]="我们最好快一点，$n！"
D.Strings[102116]="我准备好了。去奥杜尔吧！"
D.Strings[102117]="忙啊，忙死了。得、得去干活了。"
D.Strings[102118]="没空聊天了。我还得大扫除呢。"
D.Strings[102119]="有什么需要清洁的吗？"
D.Strings[102120]="哈！现在你的嗜魔者在哪儿呢？！"
D.Strings[102121]="你想抢我的岛！很好！我要用你的鲜血染红它！"
D.Strings[102122]="苏伊什跑出来了！快逃！"
D.Strings[102123]="卫兵，我们花钱养你们是干什么呢？快杀了这头野兽！"
D.Strings[102124]="我有钱，我不能就这么死掉！"
D.Strings[102125]="不！我绝不允许黑锋骑士团垮掉！"
D.Strings[102126]="骑士们！命运掌握在我们手中！"
D.Strings[102127]="燃烧军团将在四骑士的力量面前瑟瑟发抖！"
D.Strings[102128]="暴风城敬佩你为联盟所做的贡献。"
D.Strings[102129]="暴风城长存。"
D.Strings[102130]="有时，我们必须为信念而战。"
D.Strings[102131]="正义的事业始终值得为之而战。"
D.Strings[102132]="联盟高于一切。"
D.Strings[102133]="国王只因他践行的道路而高贵。"
D.Strings[102134]="暴风城永远欢迎你。"
D.Strings[102135]="不要失去希望。"
D.Strings[102136]="圣光必胜。"
D.Strings[102137]="现在可不是时候。"
D.Strings[102138]="你在考验我的耐心。"
D.Strings[102139]="<这头魔刃豹被燃烧军团禁锢住了，但使用远古魔力让水晶过载可以释放这头野兽。>"
D.Strings[102140]="我现在是国王了，你知道吧？"
D.Strings[102141]="圣光会制裁你！"
D.Strings[102142]="<花费50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力，释放邪缚魔刃豹。>"
D.Strings[102143]="这么做将会消耗50份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？"
D.Strings[102144]="雄鹿"
D.Strings[102145]="幽灵们！将这些凡人丢进水里去！！！"
D.Strings[102146]="所有召唤摆渡人的人，都得买船票！"
D.Strings[102147]="你想前往冥狱深渊？那就如你所愿！"
D.Strings[102148]="召唤我的人，付钱吧，我要没收你们永恒的灵魂！"
D.Strings[102149]="我期待着与麦格尼的重逢。我们已经好久没见了。"
D.Strings[102150]="米米尔隆给了我一个紧急情况下使用的传送台。我想这就是紧急情况了！"
D.Strings[102151]="指令已经下达了，我们这就开始给裂隙之核充能。"
D.Strings[102152]="裂隙之核充能完毕，按照你的需要部署裂隙火炮吧。"
D.Strings[102153]="我看看我们收集到的其他神器的消息。"
D.Strings[102154]="最好别让我听到你打坏任何东西。"
D.Strings[102155]="管住你的手，小鬼。"
D.Strings[102156]="安静点，让妈妈逛一会儿。"
D.Strings[102157]="别在玻璃上留下指印，我们说好的。"
D.Strings[102158]="如果你把它打坏了，妈妈就得把它买下来了。"
D.Strings[102159]="安静点，我们很快就回家。"
D.Strings[102160]="我准备好去寻找最后一把剑了。"
D.Strings[102161]="机械"
D.Strings[102162]="双头飞龙"
D.Strings[102163]="淡水兽"
D.Strings[102164]="多头蛇"
D.Strings[102165]="恐角龙"
D.Strings[102166]="无冕者是末日的使者。燃烧军团的末日。"
D.Strings[102167]="你听到楼下的传送门处传来一阵奇怪的爆裂声。"
D.Strings[102168]="我会保护大家的。"
D.Strings[102169]="你听到前面的洞穴中传来一阵古怪的吼叫声。"
D.Strings[102170]="海达希亚水元素与你同在，先知。军团休想征服我们！"
D.Strings[102171]="什么玩意儿？"
D.Strings[102172]="如果你需要去达拉然的话，我的蝙蝠已经准备好了。"
D.Strings[102173]="这个模块看来早就失去了能量源。"
D.Strings[102174]="<用25份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力激活模块。>"
D.Strings[102175]="千光神殿里充斥着发疯的幽灵。你得去提醒它们注意自己的行为。"
D.Strings[102176]="就连幽灵也害怕力量。干得好！"
D.Strings[102177]="这座神殿里最强大的法师正在密谋对付守夜人。让他们看看我们是怎么对待敌人的！"
D.Strings[102178]="我准备好突袭赫达沙尔了。"
D.Strings[102179]="打得好！跟守夜人为敌者都将付出高昂的代价。"
D.Strings[102180]="我们幸运地收到了玛洛恩的警告，但它很可怕。我非常担心翡翠梦境。如果梦境都被腐蚀了，那它对艾泽拉斯的影响就更不用说了。"
D.Strings[102181]="我们为何而战？"
D.Strings[102182]="我想我们的伤已经好得差不多了。我要继续去侦察了。保重，莉莉娅。"
D.Strings[102183]="我想我看到一个$c在城里找你，还提到了古代武器什么的。在前往破碎群岛之前，你应该先去跟他们谈谈。你需要团结一切可团结的盟友。\n\n我是说……如果你真想走的话，我可以帮你安排。但我不建议你这么做。"
D.Strings[102184]="你能帮我离开这里吗？"
D.Strings[102185]="瓦格里！召唤已经发出！准备战斗吧！"
D.Strings[102186]="瓦格里，该轮到我们了！战斗吧！"
D.Strings[102187]="我的长矛随时为你效劳。"
D.Strings[102188]="我的生命属于奥丁！"
D.Strings[102189]="我们的怒火会让他们瑟瑟发抖的。"
D.Strings[102190]="呵呵，这家伙完蛋了。"
D.Strings[102191]="拉里要把你榨成美味的肉汁。"
D.Strings[102192]="你好，亲爱的市民，有什么问题吗？"
D.Strings[102193]="我知——道——，你和燃——烧军团是一伙的。就是你，听你说话就知道了。"
D.Strings[102194]="看什么看，快滚！"
D.Strings[102195]="告诉我，$c，你见识过达拉然的神奇货物吗？如果你找不到想要的东西，我或许可以指点你一下。"
D.Strings[102196]="我都跟他们说了会这样。\n\n我早就告诉他们了。\n\n有谁听了？！"
D.Strings[102197]="小心点，$c……"
D.Strings[102198]="贾格诺斯会……毁了你的……"
D.Strings[102199]="阿莎，你自由了。"
D.Strings[102200]="瑟留斯，你还好吗？"
D.Strings[102201]="敌人和梦魇很狡猾。他们选择的这个时机正值荒野诸神陨落千年之际。为了保护艾泽拉斯，他们陨落在了与燃烧军团的战争中。"
D.Strings[102202]="我一点儿也不喜欢这个地方！让我们解决这些入侵的怪物吧，大德鲁伊！"
D.Strings[102203]="此刻，荒野诸神一定因为旧日景象的重现而难过不已。我只能想象多年前燃烧军团入侵时的恐怖景象。"
D.Strings[102204]="这里没有梦魇的位置，我们必须想尽办法保护玛洛恩。没有了他，自然的平衡就会变得很脆弱。$B$B我想没有比拯救他更重要的事了……哪怕是要付为此出我们的生命。"
D.Strings[102205]="安息吧，老朋友。"
D.Strings[102206]="你来到了万物创生的熔炉寻找答案。那就仔细倾听，寻找启迪吧。"
D.Strings[102207]="很久很久以前，爆发了一场决定诸界命运的大战。在这场决战中，全知全能的泰坦万神殿败于自己人：萨格拉斯之手。"
D.Strings[102208]="这次惨败之后，再无人能对抗萨格拉斯的意志。无人制衡的黑暗泰坦和他的燃烧军团准备继续燃烧的远征，毁灭无数世界。"
D.Strings[102209]="在那些破灭世界的灰烬中，出现了一些对抗恶魔的幸存者。他们后来被称为圣光军团。"
D.Strings[102210]="但现在，这支黄金军团已濒临毁灭，他们的阿古斯战役即将以惨败收场。一旦他们倒下，军团就会发动新的燃烧远征，整个宇宙都将为之震动。"
D.Strings[102211]="我是来此作最后一搏的。我要寻找光与影之子：这孩子注定将终结恶魔的纪元。"
D.Strings[102212]="他的名字是，伊利丹·怒风。"
D.Strings[102213]="它太强大了！这太疯狂了！"
D.Strings[102214]="我们没有足够的力量……"
D.Strings[102215]="这头恶魔很有斗志！"
D.Strings[102216]="$n，是你啊。\n\n当时我们正在追踪一个恐惧魔王。不幸的是，他将我们引入了陷阱。"
D.Strings[102217]="<凯赛尔·夜棘的尸体几乎无法辨认。他受到了残酷的折磨，而后伤重而死。>"
D.Strings[102218]="<瑟留斯·黑翼的脸色苍白得像鬼。他止不住地颤抖着。>"
D.Strings[102219]="我一听说预言实现了，就立刻赶回了达拉然。\n\n和我预见的一样，你将圣光团结在了一起。希望你的努力能给予我们足够的力量，彻底击败巴纳扎尔。"
D.Strings[102220]="我们立刻就赶去虚空之光神殿。"
D.Strings[102221]="只要你一声令下，我们就出发！"
D.Strings[102222]="我叫泽拉，我是宇宙定序时期诞生的第一批纳鲁之一。"
D.Strings[102223]="别紧张，凡人。我只是把你的意识投射到我位于黑暗虚空的星界内而已。"
D.Strings[102224]="趁法力怨魂分心时赶快移动！"
D.Strings[102225]="祝你们好运。"
D.Strings[102226]="奥杜尔藏着许多秘密。"
D.Strings[102227]="这事等不得。恶魔已经混入你们中间。让我帮你把他们揪出来吧。"
D.Strings[102228]="你好，朋友！这其实不是我，卡德加，只是我粗犷而英俊的脸庞和丰富的知识而已。如果你有任何问题需要解答，只要说出你的问题，然后要求我回答就行了。\n\n我的精神世界是如此广阔，只有用魔法空间才能将部分答案放入这个装置。所以，你的问题必须非常精确才行。"
D.Strings[102229]="提问的人是我，告诉我答案！"
D.Strings[102230]="如果你想要获得风暴之神的武器，就进去了解他的事迹和他的陨落吧……"
D.Strings[102231]="|TInterface\\Icons\\sha_ability_rogue_envelopingshadows_nightmare:20|t伊格诺斯即将完成|cFFFF0000|Hspell:223121|h[最终的蛰伏]|h|r！"
D.Strings[102232]="我知道你的秘密。"
D.Strings[102233]="呵。"
D.Strings[102234]="我没什么可说的。"
D.Strings[102235]="那就跟我打一场吧。"
D.Strings[102236]="你吓不倒我的。"
D.Strings[102237]="<他一言不发，警惕地盯着你。>"
D.Strings[102238]="<她一言不发，警惕地盯着你。>"
D.Strings[102239]="这么说艾里克斯是被这个叫巴拉杜尔的艾瑞达伏击了？那法杖可能就在他手里……\n\n在燃烧军团入侵的大背景下，我相信他要么已经来了，要么就在观望。我有一个……大胆的计划。\n\n我们要重现艾里克斯的仪式！在入侵基地举行仪式可以吸引巴拉杜尔的注意。他很可能会再次发动伏击，而我们却早有准备。"
D.Strings[102240]="谁？菲尔麦夫？那个老古董？他已经在达拉然当了几十年档案员了。我还是学徒时，他就在了，整天就在书堆里转悠。他什么都能找到。$b$b后来，第三次大战爆发了，阿尔萨斯屠城时，菲尔麦夫和很多人一样失踪了——只是无数死难者中的一员而已。谁也没把这当一回事儿。"
D.Strings[102241]="就这样过了很多年。在诺森德战役中，我们将整座城市搬到了冰冠冰川上空。$b$b有一天，老菲尔麦夫突然走进了紫罗兰之塔，就那么慢悠悠地晃进来了！他什么都没说，直接开始整理图书和文档，好像什么都没发生过似的。从那之后，他就回到这个岗位上。$b$b<瓦伦萨斯凑了过来，小声道：>$b$b我想他还不知道自己已经死了。"
D.Strings[102242]="那边的老菲尔麦夫有什么故事吗？"
D.Strings[102243]="我不知道这些花是怎么了！我已经不用自己去摘花了，它们会……呃，自己把自己摘下来！$B$B太奇怪了，对吧？"
D.Strings[102244]="我改变主意了。让我看看还有哪些神器可以选择。"
D.Strings[102245]="你先走。我很快就来找你。我需要……整理一下思路。"
D.Strings[102246]="我们前往奥杜尔的旅途还真是七灾八难的，但还有更多任务在等着我们呢。"
D.Strings[102247]="看看，是谁活过来了！$g伙计:女士;，你已经昏迷了三天。看到他的老朋友苏醒了，卡德加一定会很欣慰的。我？我还是一头该死的海狮。"
D.Strings[102248]="痛苦会被抚平，勇士。你有了我的印记，我能用它观察并感知你的行动。有空时再来找我吧。我们有很多事要做。"
D.Strings[102249]="你好，$n。你感觉还好吗？不少人都报告说有恶心头晕的症状出现。"
D.Strings[102250]="你好啊！你是刚到城里的吗？你看起来好像没有任何后遗症。"
D.Strings[102251]="你醒了！你的勇士没法在职业大厅里唤醒你，所以来找了我。我们就把你送进了这座医院。出什么事了？"
D.Strings[102252]="我们已经受不了了！"
D.Strings[102253]="简直没完没了！他们还在不断涌来！"
D.Strings[102254]="这样坚持不了多久！我们很快就会被淹没的！"
D.Strings[102255]="他们肯定很快就会搬走城市的！我们不能再这么下去了！"
D.Strings[102256]="议会已经有计划了。我敢肯定！"
D.Strings[102257]="我们还得再坚持一段时间。"
D.Strings[102258]="保持警惕，$n。$B$B杜比虽然是个固执的矮人，但我和他都确信一点——这里有些不对劲。"
D.Strings[102259]="你感觉到森林里的生命了吗？我们已经保护了这片土地那么多年，但是到了现在，仅凭我们的力量已经没办法保护这里了。你愿意帮助我们吗？"
D.Strings[102260]="你有勇气帮我们击败燃烧军团吗？"
D.Strings[102261]="我们必须夺回我们神圣的家园。"
D.Strings[102262]="肯瑞托感谢你的帮助。"
D.Strings[102263]="再跟我说说伊利丹吧。"
D.Strings[102264]="再跟我说说古尔丹吧。"
D.Strings[102265]="再跟我说说卡德加吧。"
D.Strings[102266]="你们两个遇到什么麻烦了吗？我收到报告说，这一带出现了不稳定的能量。"
D.Strings[102267]="这里情况如何？有什么不同寻常的动静吗？"
D.Strings[102268]="在你的领导下，我们重建了白银之手骑士团，并有了新的方向和指引。$B$B我们还有很多工作要做。"
D.Strings[102269]="嘿，格林德……噢，伙计。我都还没开口呢。这家伙全归你了。"
D.Strings[102270]="看来你们已经基本控制住了。"
D.Strings[102271]="$n！能耽误你一会儿吗，我这儿或许有你感兴趣的东西。"
D.Strings[102272]="你真是个可靠的帮手。她很快就会把你从这里调走的！"
D.Strings[102273]="主人！我这儿有好货。来看看吧。"
D.Strings[102274]="这里目前看来一切正常！"
D.Strings[102275]="我没时间跟你开玩笑，恶魔猎手。$b$b就像我跟其他伊利达雷说的那样，我还有很多事要考虑。$b$b在部分盟友叫嚣着要向部落复仇时，我得让大军做好对抗燃烧军团的准备。"
D.Strings[102276]="如果遇到什么事，我们会通知你的。"
D.Strings[102277]="没什么特别的。偶尔有能量爆发，但我没发现什么危险。"
D.Strings[102278]="$n！我有合适你的货物！来看看吧！"
D.Strings[102279]="等这一切结束后，我还得再去吃一顿！"
D.Strings[102280]="有空的时候，我一定要请你看看我收藏的叶子！"
D.Strings[102281]="每天早上，我都要绕着迷踪岛跑两圈！我可不能在训练中落后。"
D.Strings[102282]="在上周的牦牛大赛上，我得了第二名。我需要一头跑得更快的牦牛！"
D.Strings[102283]="喝得越多，我的战术就越神奇……嗝儿！"
D.Strings[102284]="有空的时候，我一定要请你看看我收藏的玩具！"
D.Strings[102285]="有空的时候，我一定要请你看看我收藏的杯子！"
D.Strings[102286]="有空的时候，我一定要请你看看我收藏的宠物！"
D.Strings[102287]="有空的时候，我一定要请你看看我收藏的卷轴！"
D.Strings[102288]="有空的时候，我一定要请你看看我收藏的硬币！"
D.Strings[102289]="有空的时候，我一定要请你看看我收藏的坐骑！"
D.Strings[102290]="有空的时候，我一定要请你看看我收藏的战袍！"
D.Strings[102291]="这场战斗不公平！你们应该再派点援军来对付我，恶魔！"
D.Strings[102292]="你是什么类型的法师？"
D.Strings[102293]="你做了应该做的事。这是种可贵的品质。"
D.Strings[102294]="伊利丹，你真是既优雅又强大。我很荣幸能看到你的英姿。"
D.Strings[102295]="感谢你帮我对付这种敌人。"
D.Strings[102296]="跟你并肩战斗让我学会了不少新战术，伊利丹。"
D.Strings[102297]="我的战斧随时为你效劳。"
D.Strings[102298]="伊利丹！你好像天生就会骑龙！"
D.Strings[102299]="我还以为这场血战不会结束了呢！"
D.Strings[102300]="我来守住天空，队长。地面上仍然需要你。"
D.Strings[102301]="让烈焰净化你们吧，恶魔！"
D.Strings[102302]="伊利丹！墓穴里可能有个恐惧魔王。我们很乐意接受你的帮助。"
D.Strings[102303]="精彩的战斗。我一个人绝不可能打倒一名恐惧魔王。"
D.Strings[102304]="我对此感到有些不适，伊利丹大人。"
D.Strings[102305]="我不是英雄，队长，但我很乐意与你并肩战斗。"
D.Strings[102306]="伊利丹大人，你的力量真强大！"
D.Strings[102307]="这地方建造得非常坚固，几乎能经受任何攻击，但燃烧军团的实力远超预计。"
D.Strings[102308]="我只希望他们的牺牲能有价值。"
D.Strings[102309]="你的战刃又快又准，加洛德。跟我一起结束战斗吧！"
D.Strings[102310]="我只是做了应该做的事。"
D.Strings[102311]="我会记住你的牺牲的。"
D.Strings[102312]="我好像把我的达拉然炉石弄丢了，能再给我一块吗？"
D.Strings[102313]="他们像雨点一样从天而降。啊，美妙的宣泄。"
D.Strings[102314]="军团以为这点小把戏能出奇制胜，但我们早有预料！"
D.Strings[102315]="别虚张声势了，恶魔！你们击败不了我！"
D.Strings[102316]="[%s]忏悔：我不知道炉石到底是什么东西，而且过了这么久了，我更不敢问了。"
D.Strings[102317]="[%s]忏悔：我还以为我们已经击败燃烧军团了。"
D.Strings[102318]="[%s]忏悔：我不敢相信牛头人的武器有多大。"
D.Strings[102319]="[%s]忏悔：我花了很多时间在海里寻找阿湿兰，多到我都不好意思承认。"
D.Strings[102320]="[%s]忏悔：我把用不着的东西都卖店了，因为我懒得用拍卖行。"
D.Strings[102321]="[%s]忏悔：我一直很好奇，维库人的胡子是不是比小猫的还柔软。"
D.Strings[102322]="[%s]忏悔：在讨论怎么打新的副本首领时，我总是走神。"
D.Strings[102323]="[%s]忏悔：我就是那个老开豹群守护的家伙。"
D.Strings[102324]="[%s]忏悔：我更喜欢老的达拉然。不是那个，是另一个。"
D.Strings[102325]="[%s]忏悔：我很久没去过我的要塞了。希望我的追随者们一切都好。"
D.Strings[102326]="[%s]忏悔：我曾偷偷希望船坞里的一条船能在执行任务时失败。但它从来没失败过。"
D.Strings[102327]="[%s]忏悔：我不明白破碎群岛这个名字是怎么来的。所有的岛难道不都是破碎的吗？"
D.Strings[102328]="[%s]忏悔：我真的真的很喜欢闪金镇的旅店。"
D.Strings[102329]="[%s]忏悔：我一直以为加尔鲁什是个好人。"
D.Strings[102330]="总算来了个能让我动斧子的敌人！"
D.Strings[102331]="[%s]忏悔：我不喜欢跟戈隆战斗，我感觉他们总是在盯着我看。"
D.Strings[102332]="[%s]忏悔：在拍卖行卖东西的时候，我总是喜欢削价一铜来抢生意，因为我乐意。"
D.Strings[102333]="战斗开始了，伊利丹大人！"
D.Strings[102334]="别让这玩意儿靠近我！"
D.Strings[102335]="快来人啊，阻止这个玩意儿！"
D.Strings[102336]="就没有人能控制住它们吗？"
D.Strings[102337]="没有希望了……"
D.Strings[102338]="圣光熄灭了……"
D.Strings[102339]="全……完了……"
D.Strings[102340]="我将回归……黑暗虚空……"
D.Strings[102341]="祝福你……"
D.Strings[102342]="滚出我们的商店！"
D.Strings[102343]="这下是给你的，$n！"
D.Strings[102344]="没有他，我们就全完了！"
D.Strings[102345]="你已经阻止不了他们了！"
D.Strings[102346]="这些家伙还在不断涌来！"
D.Strings[102347]="圣光熄灭了！你还不明白吗？"
D.Strings[102348]="我们都完蛋了！"
D.Strings[102349]="我本来已经计划好了精密的越狱行动，但你的方法显然更奏效。"
D.Strings[102350]="我是大法师卡德加，肯瑞托的领袖。诸位恶魔猎手，艾泽拉斯需要你们的帮助。"
D.Strings[102351]="全力投入吧，$n。看看我们能挡住这些恶魔多久。"
D.Strings[102352]="让我的剑净化你！"
D.Strings[102353]="我跟你一样吃惊，$n。"
D.Strings[102354]="你是不会成功的！"
D.Strings[102355]="愿我的快剑送你上西天！"
D.Strings[102356]="击退他们！决不能让达拉然陷落！"
D.Strings[102357]="我就知道是这样！我早就有预感了！$B$B肃清城市，$n！我们得挡住他们！"
D.Strings[102358]="翱翔天际总是充满了乐趣！"
D.Strings[102359]="|TInterface\\Icons\\sha_spell_warlock_demonsoul_nightmare:20|t使用玛法里奥的|cFF00FFFF|Hspell:212630|h[净化大地]|h|r躲避|cFFFF0000|Hspell:210279|h[蠕行梦魇]|h|r的伤害。"
D.Strings[102360]="古老的回忆出现了异动。你准备好了就召唤我。让我们一起发掘伊利丹的过往。"
D.Strings[102361]="伊利丹充满了潜力。他的命运形成于大定序时期，并被抛入了宇宙风中，最终在艾泽拉斯找到归宿。这个小小的载体能让大轮回重新开始。"
D.Strings[102362]="很少有人体会过这种失败和抛弃。大部分人都会就此放弃，但伊利丹却在命运之手的指引下继续奋斗。他的命运在别处。"
D.Strings[102363]="总要有人做出艰难的抉择，但要想成功完成任务，你就得理解伊利丹的观点。如果换了你来，会有什么不同吗？"
D.Strings[102364]="真相灼瞎了伊利丹的双眼，但他没有动摇。就算是在燃烧军团之主的注视下，伊利丹依然保持坚定，勇于反抗。"
D.Strings[102365]="泰兰德……对我们而言，周围的人和这世界一样重要。哪怕在最后，她在伊利丹眼中，仍然清晰如初。他从未忘记他的世界。你又能为你的世界走得多远？"
D.Strings[102366]="更糟糕的是，如果不加以阻止，竞技场的那个怪物就会突出重围！带上月之守卫，瓦解针对黑鸦堡垒的这次恶魔入侵！"
D.Strings[102367]="注意寻找影歌队长和他的那两个异族盟友！我们在第一波攻击时失散了。但愿他们还活着！"
D.Strings[102368]="你都干了什么！你杀光了他们，伊利丹！"
D.Strings[102369]="你被解除职务了，伊利丹！罗宁，从现在起，由你指挥月之守卫！"
D.Strings[102370]="我都看见了！伊利丹！拉文凯斯让我来接手！我们得协同进攻，恢复秩序！"
D.Strings[102371]="海里出现了一头巨兽。去把它送回深海吧！"
D.Strings[102372]="干得好。我们能暂时……松口气了。"
D.Strings[102373]="那些讨厌的幽灵法师召唤了一个狂野的魔法生物！快挡住他们！"
D.Strings[102374]="魔法的回响平息了。谢谢你。"
D.Strings[102375]="<向瓦尔托伊出示塔莉萨的徽记。>"
D.Strings[102376]="死了？泰坦们都死了？"
D.Strings[102377]="难怪，可我还是忍不住感到悲痛。"
D.Strings[102378]="我们只能靠自己。在我们诞生前，诸神就陨落了。"
D.Strings[102379]="至于圣光军团和伊利丹，我都糊涂了。我从没这么无力过。"
D.Strings[102380]="伊利丹死了，而黄金军团则在宇宙的另一边，以我们之名鏖战不休……"
D.Strings[102381]="赞美女神。今晚，她赐给了我们新的生命。"
D.Strings[102382]="诞生的不是一个，而是两个健康的男孩。"
D.Strings[102383]="$r，您找我有何贵干？"
D.Strings[102384]="这是你的名字缩写吗？"
D.Strings[102385]="干得好，伊利丹，但战斗才刚开始。"
D.Strings[102386]="女士，我想再挑战一次崩溃。"
D.Strings[102387]="军团屠杀了我们一半的部队，并打散了剩下的一半。你看到的就是保卫要塞的鸦堡卫队所有的残余部队了。"
D.Strings[102388]="你是最后的希望，伊利丹！"
D.Strings[102389]="窃贼！你胆敢盗取我的财物？！"
D.Strings[102390]="你的葬礼。"
D.Strings[102391]="%s漠然地耸耸肩，然后把你踢到天上。"
D.Strings[102392]="做你该做的吧！一旦黑鸦堡垒倒下，苏拉玛就完了！"
D.Strings[102393]="怒风队长给了我们一战的机会！鸦堡卫队，守住壁垒！前进！！"
D.Strings[102394]="$n！卡德加！熔炉在上，我找到你们了！你们肯定不会相信！但是我哥哥麦格尼回来了！"
D.Strings[102395]="什么？？拉文凯斯派了个小崽子来对付我？我要让你学会尊重强者，小鬼！"
D.Strings[102396]="你……杀了自己的士兵？！疯狂的蠢货！你这是找死！"
D.Strings[102397]="这小崽子的牙……还挺利……"
D.Strings[102398]="跑吧，小拉文凯斯，快跑吧！你或许还来得及逃跑，然后躲到哪个树洞里度过悲惨的余生！"
D.Strings[102399]="两个？"
D.Strings[102400]="是怒风家族的双胞胎。"
D.Strings[102401]="真漂亮。几乎一模一样，除了——"
D.Strings[102402]="那个！他的眼睛是金色的！"
D.Strings[102403]="是的。这个孩子注定会有一个伟大而光辉的未来。他的名字是……伊利丹。"
D.Strings[102404]="伊利丹，你的怒火发错了地方。我并没有冒犯你。"
D.Strings[102405]="你要把我赶走吗，塞纳留斯！"
D.Strings[102406]="不。你可以留在这里，但我不会再做你的老师了。"
D.Strings[102407]="你要我要向一个新人学习……而不是一位大师？"
D.Strings[102408]="你需要学会尊重别人。"
D.Strings[102409]="要走上这条道路需要做出牺牲，伊利丹……牺牲是你现在还无法理解的。"
D.Strings[102410]="弟弟——"
D.Strings[102411]="看吧，这就是军团之力。"
D.Strings[102412]="<痛苦地尖叫>"
D.Strings[102413]="不管这个世界如何反抗，都终将陨落。"
D.Strings[102414]="我们的眼睛……欺骗了我们。"
D.Strings[102415]="这支军队之外，还有另一支……还有无数支……"
D.Strings[102416]="即使我们在这里把他们击败，也毫无意义。"
D.Strings[102417]="我们没希望了……"
D.Strings[102418]="而我，会找到那个办法。"
D.Strings[102419]="我不会让你失望的，大人！"
D.Strings[102420]="为了召唤防护屏障，我们几乎用尽了能量。如果再逼这些月之守卫，他们会死的。"
D.Strings[102421]="如果能修复那个被关闭的传送门，我就能得到所需的援军，和恢复能量的源泉了。"
D.Strings[102422]="伊利丹心中想着。"
D.Strings[102423]="太好了！只要我留在附近，传送门中溢出的能量就能为我补充力量。如果我感到疲劳，就可以回到这些传送门附近来。"
D.Strings[102424]="我准备好了，拉文凯斯领主！放下闸门！"
D.Strings[102425]="放下城门，打起精神！投刃车准备！"
D.Strings[102426]="遵命，队长！"
D.Strings[102427]="大法师，我们得走了。"
D.Strings[102428]="她的邪能魔法太强大了。我可以从月之守卫身上吸取能量，用它们毁灭这个恶魔，但我的法师们也会死的。"
D.Strings[102429]="唉，还能怎么办呢？如果我失败，苏拉玛明天就会完蛋，还有我心爱的泰兰德。我得立刻行动！"
D.Strings[102430]="你竟敢藐视燃烧军团？在所向披靡的邪能面前跪下吧！"
D.Strings[102431]="你说得对，恶魔。邪能比奥术更强大，但你运用得太拙劣了！来看看大师能用它造成怎样的破坏吧！"
D.Strings[102432]="|TInterface\\Icons\\Spell_Nature_EyeOfTheStorm:20|t赫娅开始施放|cFFFF0404|Hspell:192305|h[风暴之眼]|h|r！"
D.Strings[102433]="|TInterface\\Icons\\Spell_Holy_HolyNova:20|t赫娅开始施放|cFFFF0404|Hspell:192206|h[圣洁庇护]|h|r！"
D.Strings[102434]="我很欣慰，我们都完好无损地从卡拉赞出来了。"
D.Strings[102435]="我和大法师茉德拉会继续查找我们从卡拉赞带回来的书籍。我们会找到那些创世之柱的，$n！"
D.Strings[102436]="唔……这让我想到了一个主意……等你解决那些畸体后，我们可以商量一下。"
D.Strings[102437]="鲜血与雷鸣，$n。你的船，还有辉煌的胜利，都在等着你。"
D.Strings[102438]="战争真是让人血脉贲张，$n！难道你的战斧不渴望来场决斗吗？"
D.Strings[102439]="听到战斗的咆哮了吗，$n？它在召唤着你！"
D.Strings[102440]="$n使用星光玫瑰茶，为所有人恢复了生命值和法力值！"
D.Strings[102441]="$n摧毁了地狱火宝典，使所有人获得了减伤效果！"
D.Strings[102442]="$n吸收了邪能宝珠，使所有人的爆击率提高了！"
D.Strings[102443]="$n释放了深黯之花的孢子，令所有人的急速提高了！"
D.Strings[102444]="$n使用了夜影小食，令所有人的生命值提高了！"
D.Strings[102445]="$n引导魔法灯笼中的能量，令所有人的伤害提高了！"
D.Strings[102446]="$n破译了浸水的卷轴，令所有人的移动速度提高了！"
D.Strings[102447]="$n摧毁了奥术能量导管，令所有构造体卫兵过载了！"
D.Strings[102448]="$n偷偷在庄严静夜合剂中下了毒。"
D.Strings[102449]="我把我所有的大石头都弄来帮助投石车了。格瑞格想要加入部落。"
D.Strings[102450]="如果你希望继续研究荒野，那你可以和你的兄弟一起学习。"
D.Strings[102451]="眼观六路的主人已经看清了你的命运，$n！你必将失败，世界也将化为火海！"
D.Strings[102452]="这“绝对”是个好主意。"
D.Strings[102453]="必须挫败燃烧军团！"
D.Strings[102454]="达拉然决不能倒下，$n。"
D.Strings[102455]="我们会战胜燃烧军团的。"
D.Strings[102456]="我会召唤初代提瑞斯法守护者阿洛迪的灵魂。你准备好了，就告诉我一声。"
D.Strings[102457]="玛法里奥会成为第一个德鲁伊，因为他是个专注的学生。而你……不是这样。"
D.Strings[102458]="我的粗心导致了这次挫折。我会从失败中吸取教训，并卷土重来的。"
D.Strings[102459]="别再那么做了！"
D.Strings[102460]="在这里，我能看见整个苏拉玛！"
D.Strings[102461]="或许是风吹散了雾气。"
D.Strings[102462]="他们简直无穷无尽！"
D.Strings[102463]="我每杀一头恶魔，就会涌出来两头！"
D.Strings[102464]="我得想办法关闭那座传送门！"
D.Strings[102465]="有谁能抵挡这种力量？"
D.Strings[102466]="我要终结这一切……我必须做到！"
D.Strings[102467]="我叫伊利丹，恶魔！记住这名字，它就是你的末日！"
D.Strings[102468]="又来了这么多！看来恶魔大军都是从下方庭院的传送门里出来的。为了活命，我得去摧毁它，但我需要月之守卫的帮助。"
D.Strings[102469]="你很大胆，竟敢挑战燃烧之影！仆从们，杀了这“英雄”！"
D.Strings[102470]="恶魔太多了。我……还需要月之守卫的力量。我是不是太过分了？不，我得保持专注！人民的未来就在我的手中！"
D.Strings[102471]="一个叫巴拉杜尔的艾瑞达保护着奈兰传送门。普通的法术对它不起作用。我得召唤宇宙的怒火摧毁传送门。然后，就是我和那个恶魔之间的事了。"
D.Strings[102472]="我从未感受过这种力量……好痛苦……"
D.Strings[102473]="快没能量了。我得找个传送门休息下，或是从月之守卫身上吸取精华。"
D.Strings[102474]="我可以召唤初代守护者的灵魂！"
D.Strings[102475]="有人在召唤！几百年了，好久没有人召唤我帮忙了。"
D.Strings[102476]="你好，阿洛迪。我是卡德加，肯瑞托的大——"
D.Strings[102477]="我知道你。拒绝继承我传下的衣钵的学徒。你找我做什么。"
D.Strings[102478]="燃烧军团又回来了。为了阻止他们，我们翻遍了卡拉赞的图书馆，找到了你所撰写的《古艾泽拉斯知名文物》一书。"
D.Strings[102479]="你读了我的书？想不到现在的年轻人还会看书。你们总是喜欢玩游戏，四处冒险……"
D.Strings[102480]="可惜我们看不见风暴峡湾。"
D.Strings[102481]="我们想找五件名为“创世之柱”的古老神器。你的书里没有提到该去哪里找它们。"
D.Strings[102482]="当然没有了！创世之柱代表着原初之力。哪怕身为守护者的我，也不敢轻忽它们。"
D.Strings[102483]="我们必须找到这些神器。只有创世之柱才能封印萨格拉斯之墓里的燃烧军团传送门。"
D.Strings[102484]="那好吧。我的研究指向了破碎群岛。虽然我始终没有发现它们的确切下落，但我相信创世之柱就在那片古老土地的居民手里。"
D.Strings[102485]="至少我们知道该从何处下手了。如果有必要，我们会翻遍破碎群岛的每一寸土地。"
D.Strings[102486]="谢谢你，守护者。你再次帮助了艾泽拉斯。"
D.Strings[102487]="你们必须尽快找到它们。在燃烧军团手中，创世之柱会给我们的世界带来难以想象的灾难。祝你们好运。"
D.Strings[102488]="你准备好之后，就告诉我一声吧，$n。"
D.Strings[102489]="|TInterface\\Icons\\spell_shadow_zdemonformgreen:20|t%s正在施放|cFFFF0000|Hspell:199193|h[恐惧魔王的狡诈]|h|r！"
D.Strings[102490]="你还需要训练吗？"
D.Strings[102491]="我是多元宇宙最强大的法师猎手！你毫无机会，小精灵！"
D.Strings[102492]="伊利丹占领了庭院！鸦堡卫队，前进！"
D.Strings[102493]="我们要加入竞技场的战斗！怒风队长，带头冲锋！"
D.Strings[102494]="我用尽一切手段也奈何不了这个怪物。我得让月之守卫帮我最后一次。"
D.Strings[102495]="想想办法，伊利丹！它在撕裂我们的阵型！堡垒快坚持不住了！"
D.Strings[102496]="愿月神宽恕我的所作所为……"
D.Strings[102497]="伊利丹，不！"
D.Strings[102498]="如此狂野……"
D.Strings[102499]="难道我们要变得跟那些怪物一样？"
D.Strings[102500]="那你说怎么办，库塔洛斯？向军团的新主子点头哈腰，让他们将世界化为灰烬吗？"
D.Strings[102501]="一定有其他办法的！我们可以……"
D.Strings[102502]="我们可以怎么样？你瞎了，拉文凯斯！你们都瞎了！"
D.Strings[102503]="这是一场入侵。他们差点杀光在场的所有人，占领苏拉玛。"
D.Strings[102504]="而你们只会批评我吗？我的法师们为拯救世界而死。你们又付出了什么？牺牲了什么？"
D.Strings[102505]="你这蠢货，拉文凯斯！没关系。我已经没有东西要从你那儿学了。"
D.Strings[102506]="只要掌权的是你这种懦夫，我们就别想打败军团。"
D.Strings[102507]="再见了……祝你们好运。下次，你们还是直接求他们饶命吧。"
D.Strings[102508]="你来啊……"
D.Strings[102509]="|TInterface\\Icons\\Spell_Shadow_Possession:20|t %s开始施放|cFFFF0000|Hspell:227233|h[腐化咆哮]|h|r。小心！"
D.Strings[102510]="达拉然的资源任由你们调动。联盟和部落的英雄将从这里出发，去搜寻创世之柱！"
D.Strings[102511]="我听说有一些强大的神器或许会对你的战斗有帮助。睁大你的眼睛，有用的线索或许就会自动浮现出来！"
D.Strings[102512]="现在，我得去招呼其他访客了。祝你好运，$n！"
D.Strings[102513]="我们必须合力施法。移动一座城市的法术可是很费力的。"
D.Strings[102514]="我们从来没在这么短的时间内让达拉然移动两次过。"
D.Strings[102515]="我会尽力帮助你们的。为肯瑞托效劳是我的荣幸。"
D.Strings[102516]="给我们点时间准备一下，$n。$b$b去帮助城市抵挡燃烧军团吧，或是用你的地图去找一处入侵点并阻止他们。$b$b等能够开始后，我会召唤你的。"
D.Strings[102517]="布莱恩·铜须？唔，这可真是出人意料。"
D.Strings[102518]="你准备好了吗？我要驱散这道屏障了。"
D.Strings[102519]="我们去救麦格尼吧！"
D.Strings[102520]="你得跟卡德加一起找到创世之柱，$n！"
D.Strings[102521]="我准备好了，可以前往卡拉赞了。"
D.Strings[102522]="你准备好进入天文台了吗？"
D.Strings[102523]="我们进去吧！"
D.Strings[102524]="我想征调一些黑暗收割议会的部队。"
D.Strings[102525]="大地之环与你同在，先知！我们将不惜一切，与你并肩对抗燃烧军团！"
D.Strings[102526]="黑锋骑士团必胜。挡我们路的人……都得死。"
D.Strings[102527]="我要踏入竞技场去消灭这个怪物。月神，请赐予我力量。"
D.Strings[102528]="|TInterface\\Icons\\ability_mage_arcanebarrage_nightborne:20|t|cFFF00000|Hspell:220871|h[不稳定的魔法]|h|r瞄准了你！"
D.Strings[102529]="你必须低于101级才能参加军团入侵活动。"
D.Strings[102530]="你还有飞行管理员的哨子吗？"
D.Strings[102531]="你感觉传送门的另一边有个惊人的存在触碰了你……"
D.Strings[102532]="<大嘴警惕地盯着你。>"
D.Strings[102533]="<骑上大嘴。>"
D.Strings[102534]="跳起以躲避|cFFFF0404|Hspell:211901|h[聚变高压]|h|r的伤害！"
D.Strings[102535]="%s与$n相撞，制造出了一个星象三角！"
D.Strings[102536]="%s的星座效果结束了，制造出了一个星象三角！"
D.Strings[102537]="我就指望你了，$n。"
D.Strings[102538]="任务是什么？"
D.Strings[102539]="我辜负了你，萨格拉斯……"
D.Strings[102540]="进军艾泽拉斯的军队，不过是燃烧军团中的沧海一粟。"
D.Strings[102541]="除非我们能找到其他办法对抗他们。"
D.Strings[102542]="燃烧军团正在逆风小径围攻达拉然。他们的攻势显然十分猛烈。\n\n我何不在这头完成仪式呢？然后你就能到破碎群岛上空来见我们了。"
D.Strings[102543]="我没法到逆风小径上空的达拉然去帮助你们，请将我直接传送到破碎群岛的达拉然去。"
D.Strings[102544]="我以前听过这个故事……<跳过《军团再临》引导任务，从达拉然开始你的旅程。>"
D.Strings[102545]="确定要跳过破碎海滩的引导任务吗？\n你可以在破碎群岛的达拉然城找档案员艾丽西娜重新获取该任务。"
D.Strings[102546]="风中有血腥味。"
D.Strings[102547]="魔力酒变酸了……你得重新开始！"
D.Strings[102548]="如果你丢下那些枯法者，他们会迷路的！"
D.Strings[102549]="我们的诅咒都是法罗迪斯造成的……他会付出代价的！"
D.Strings[102550]="只要我们还被诅咒着，法罗迪斯就别想安宁！"
D.Strings[102551]=S[8686]
D.Strings[102552]="我还要一块魔力探测石。"
D.Strings[102553]="你想听听过去的故事吗，$n？"
D.Strings[102554]="我想体验破碎海滩及其后续的故事。"
D.Strings[102555]="我想体验麦格尼·铜须的归来以及卡德加在卡拉赞的冒险。"
D.Strings[102556]="我想体验围攻达拉然以及召唤阿洛迪的故事。"
D.Strings[102557]="在它划过天际的时候，你只要留在任意宝珠的范围内，就能一直飞翔了！你看，我现在就是这么做的！一直跟着宝珠飞，看看它们究竟指向哪里。"
D.Strings[102558]="这真的很简单。去摆弄一下那个盒子，就能开始一轮游戏了。你只要在所有格子都被填满前走完它显示出来的路线，就能赢得游戏。只要多赢几次，你就能激活那个盒子了。"
D.Strings[102559]="骑上我的魔刃豹，驾着它穿过周围那些魔网能量的节点。只要穿过足够多的节点，完成它的充能，你就成功了！记住，魔刃豹直线冲刺的速度很快，但转弯速度很慢，你得尽量少转弯。"
D.Strings[102560]="你离得太远了！快回来，别让他跑了！"
D.Strings[102561]="嘿，$n！你想要拆解装备吗？或许你想用抑魔金来强化你身上的装备？那你就找对矮人了！有话就说吧！"
D.Strings[102562]="这很简单！你知道拿几件制作出来的装备——帽子啊、指环啊、圣物啊、合剂啊之类的——然后把它们扔进这家伙喷火的小嘴里。再加上一些萨格拉斯之血当燃料，然后轰得一声！你就能得到抑魔金了！\n\n你知道的，那些工匠总是用邪能球茎、邪钢和混沌水晶来做装备。总之那种护甲里全是恶魔的材料。你只要给这些恶魔材料加热，就能得到抑魔金啦！"
D.Strings[102563]="等你弄到了足够的抑魔金粉尘，你就可以把它们团成一个小球，然后把它涂在你的手工护甲上，你的护甲就会变得更强大。"
D.Strings[102564]="管好你的舌头！戴斯蒙娜不是驴子，她是一头骡子！\n\n总之，我用她换了三份萨格拉斯之血。我想做双靴子。"
D.Strings[102565]="我该怎么获得抑魔金？"
D.Strings[102566]="抑魔金该怎么用？"
D.Strings[102567]="你的驴子怎么了？"
D.Strings[102568]="我要用魔法干掉你！"
D.Strings[102569]="小东西……大块头要碾碎你！"
D.Strings[102570]="对……你的脑子不错……把它给我！"
D.Strings[102571]="让我看看你的灵魂里有什么，凡人。"
D.Strings[102572]="我的猎犬又有新鲜的肉吃了！"
D.Strings[102573]="用力挣扎吧……我就喜欢筋疲力尽的猎物。"
D.Strings[102574]="这真是场灾难。我要楼下那个侏儒的小玩意儿！"
D.Strings[102575]="好的，好的……可你是在买早午餐啊。"
D.Strings[102576]="夜之子间谍已经逃跑了！"
D.Strings[102577]="感谢你的帮助，$n。相信我很快就要转运了。$b$b话说，你觉得我的盔甲看起来够黑暗吗？"
D.Strings[102578]="你卖些什么，莫戈斯？"
D.Strings[102579]="班布利！我真不敢相信自己的眼睛……你还活着！"
D.Strings[102580]="呃……你在说什么东西？噢，你说这些？我……呃……"
D.Strings[102581]="对……"
D.Strings[102582]="什么？噢……难怪……"
D.Strings[102583]="你手上是什么东西？"
D.Strings[102584]="你以为那些是我的……是吧？"
D.Strings[102585]="你觉得我会有这种东西吗？"
D.Strings[102586]="我们得离开这儿，否则就迟了。"
D.Strings[102587]="如果燃烧军团的恶魔觉得老安古斯已经完了，那么他们就有麻烦了！我会的把戏比达拉然的法师还多！"
D.Strings[102588]="达拉然下水道"
D.Strings[102589]="一个满是盗贼与罪犯的藏污纳垢之地，味道也令人难以忍受。$B$B至少有三条路可以进去：东边、西边以及北边的入口。"
D.Strings[102590]="英雄之家位于达拉然西南部的灰牙领地旁边。$B$B那里不仅设有露天啤酒店，还汇集了全城最好的烹饪训练师。"
D.Strings[102591]="你可以前往达拉然东北部的部落区，去风行者圣殿的“肮脏的野兽”瞧一瞧。$B$B听说那里非常脏乱，但是有一位很棒的烹饪训练师。"
D.Strings[102592]="克拉苏斯平台在达拉然的最东边。$B$B城市的飞行管理员就在那里。"
D.Strings[102593]="联盟旅客主要集中在达拉然西南部的灰牙领地。$B$B那里设有旅店，还有通往各大战场和暴风城的传送门。"
D.Strings[102594]="部落的访客主要集中在达拉然东北方的风行者圣殿。$B$B那里有旅店，也有通向不同城市的传送门。"
D.Strings[102595]="守护者大厅"
D.Strings[102596]="守护者大厅是位于达拉然中心的魔法焦点。"
D.Strings[102597]="你真走运！魔法商业区刚刚开了一家叫作“往日纪念”的新商店。"
D.Strings[102598]="我想要再次见证伊利丹·怒风在黑暗神殿的陨落，泽拉。"
D.Strings[102599]="你身上带着的是阿莎曼之牙，德鲁伊。林地中仍然流传着她英勇作战的故事。"
D.Strings[102600]="我看到了，你从翡翠梦境中取回了乌索克之爪。你的顽强能够与他媲美吗，德鲁伊？"
D.Strings[102601]="我在你的身上感受到了荒野猛兽的灵魂，德鲁伊。就好像阿莎曼又一次行走在我们之中。"
D.Strings[102602]="他们没骗我——乌索克的灵魂来到了雷霆图腾！"
D.Strings[102603]="阿莎曼之牙——你佩戴着的是怎样的奇迹啊，$n！伟大的猎豹之魂在我们脚下这片林地中与燃烧军团作战时英勇献身了。"
D.Strings[102604]="你可以在魔法商业区的坦克用品店二楼找到采矿训练师和供应商，就在达拉然的西北部。"
D.Strings[102605]="苹果树的水果货车通常停在达拉然的西南部。"
D.Strings[102606]="你看见没有，法拉？$n来了。只要乌索克的灵魂与我们同在，我们就不用怕那些鹰身人了。"
D.Strings[102607]="等等，$n。那是风行者家族的古老长弓吗？我父亲曾在第二次大战中与奥蕾莉亚并肩战斗过。我都没想到我们还能见到那把神器……"
D.Strings[102608]="啊哈哈！猎人。你的那把弓，是属于勇士的武器。我感觉它已经超越了这个世界，不是吗？"
D.Strings[102609]="噢，$n！你那对匕首一定能把燃烧军团杀得血流成河，对吧？那是恶魔的牙齿吗？!用它们来撕咬孕育了它们的手？我喜欢这想法。"
D.Strings[102610]="潜行者，那是——恶魔的獠牙？你把恶魔的牙齿当成武器了？真恶心！"
D.Strings[102611]="$n，你手里那两根是恶魔的獠牙吗？我喜欢你这思路！"
D.Strings[102612]="救救我们……牧师……你的法杖闪耀着我从未见过的光芒……"
D.Strings[102613]="噢……你感觉到了？空气中传来了暖意！这个陌生牧师的法杖闪耀着明亮的光芒……"
D.Strings[102614]="很高兴看到阿洛迪的法杖能落在你这么老练的法师手里，$n。肯瑞托就全靠你了！"
D.Strings[102615]="空气中弥漫着刺骨的寒意……而这就是源头。这个法师带着初代守护者的法杖。"
D.Strings[102616]="你将风暴之怒带到了雷霆图腾，武僧。你的双手仿佛各握着一团暴风云。"
D.Strings[102617]="看这边，布鲁夫。这家伙的双手各握着一团风暴。哈哈，努力战斗吧，小$r！"
D.Strings[102618]="这片林地很危险，你要我送你离开吗？"
D.Strings[102619]="我想离开这里。"
D.Strings[102620]="小心点，武僧，风暴将至。"
D.Strings[102621]="%s盯着$n的武器看。"
D.Strings[102622]="别在意。你就是风暴的化身。"
D.Strings[102623]="牧师……你那根法杖……非常不稳定。我在这里都能感应到它的混乱。"
D.Strings[102624]="这个牧师肯定是来帮我们的，马德兰尼尔。我感觉$g他:她;的法杖里有着充沛的神圣能量——非常强大，简直难以遏制。"
D.Strings[102625]="这家伙散发的邪能的臭味。嘿，术士！那是萨格拉斯权杖吗？你是怎么哄得肯瑞托放弃那玩意儿的？"
D.Strings[102626]="噢，很好。$n带着萨格拉斯权杖来了。你懂的，这是为了以防我们打穿时空虫洞并粉碎星球。"
D.Strings[102627]="我说，$r，那是萨格拉斯权杖吗？真的是！它的来历肯定有点不清不楚的吧，嗯？"
D.Strings[102628]="这么做将会消耗10份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？"
D.Strings[102629]="这么做将会消耗15份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？"
D.Strings[102630]="这么做将会消耗5份|TINTERFACE\\ICONS\\INV_MISC_ANCIENT_MANA.BLP:15|t远古魔力。确定要继续吗？"
D.Strings[102631]="军团正在全力向我们发动攻击，我们已经没有多少时间了。\n\n我们即将释放的奥术能量冲击波应该足够暂时将他们送回那个被诅咒的次元空间，给我们争取一个喘息的机会，同时也让我们能有时间寻找创世之柱。\n\n你准备好了吗？"
D.Strings[102632]="我准备好了，开始把达拉然传送到破碎群岛吧。"
D.Strings[102633]="我准备好离开了。"
D.Strings[102634]="是的，带我回去吧。"
D.Strings[102635]="我可以送你回以太大厅。你想回去吗？"
D.Strings[102636]="我们准备好离开了。"
D.Strings[102637]="感谢你解除了黑鸦堡垒的诅咒。"
D.Strings[102638]="起义军……不死……"
D.Strings[102639]="至少我死时……是自由的……"
D.Strings[102640]="我的生命……属于苏拉玛。"
D.Strings[102641]="为了胜利，前进！"
D.Strings[102642]="大魔导师和她手下的恶棍必将失败！"
D.Strings[102643]="我的家人需要我。谢谢你，英雄！"
D.Strings[102644]="你已经毁了自己的土地，外来者。你休想再毁掉我的！"
D.Strings[102645]="%s获得了|cFFFF0404|Hspell:230981|h[撕裂的灵魂]|h|r效果！"
D.Strings[102646]="<<7.1 PTR>>请帮我完成7.0的全部堕夜精灵内容！我要测试7.1！"
D.Strings[102647]="诅咒你，外来者！"
D.Strings[102648]="麦迪文？是你吗？"
D.Strings[102649]="前守护者的幻影在你面前徘徊。你感觉它正在聆听着什么，并期待能被注意到。"
D.Strings[102650]="我准备好将阿曼苏尔之眼送往达拉然了。"
D.Strings[102651]="艾泽拉斯的命运就在我们手中。"
D.Strings[102652]="我想前往勇气试炼（团队副本）。"
D.Strings[102653]="米米尔隆，我想念哈提以前的样子了，你能把它变回去吗？"
D.Strings[102654]="传送到魔力深渊。"
D.Strings[102655]="传送到王宫庭院。"
D.Strings[102656]="只要地上有点火我就得走开，这样叫我怎么打出最高的输出？"
D.Strings[102657]="我大部分时间都生活在阴影里。为什么？这是一种生活方式。你恐怕不会理解的。"
D.Strings[102658]="我才不是被上一个队伍踢出来的呢。是我把他们甩了，一群废物！"
D.Strings[102659]="有什么秘诀？像我一样去找野猪练上十年。这样你就能练出一身肌肉……还能带些培根回来。"
D.Strings[102660]="你问我是不是故意干掉了上次跟我决斗的那个猎人？才不是呢。我只是以为他在装死，所以我才会不停地捅他。我是说，谁能想到他那么容易就死了？真是个废物。"
D.Strings[102661]="如果我想对付你，那你根本看不见我的身形。除非我是故意让你看见的，但那将是你死前看到的最后一幅画面！"
D.Strings[102662]="你问我是什么等级？神级，老兄。神级。"
D.Strings[102663]="你问我的想法？活着就是为了胜利，至死方休！这就是我的座右铭。"
D.Strings[102664]="你试过假死吗？你知道那是我发明的吧？"
D.Strings[102665]="……于是我就说：“你看不见我，就杀不了我！”然后我就消失了！哈哈！你真该看看那个小鬼当时的表情。他连手里的蛋筒都差点掉了！"
D.Strings[102666]="……毒药？干嘛费那个劲儿，直接从背后捅就是了！"
D.Strings[102667]="我离开上一个队伍是因为他们都是废物。全部都是！我要组个新队伍，但我觉得你恐怕没资格参加。帮我把这个消息传播出去，好吗？"
D.Strings[102668]="死从天降？我用它干掉过1979个敌人了！你想变成第1800个吗？应该不想把？"
D.Strings[102669]="……于是我就说：“不错的故事，老兄。”哈！"
D.Strings[102670]="瑞兹尔很乐意帮助朋友。你看，瑞兹尔并不是坏恶魔！"
D.Strings[102671]="藏起烈焰之击的烈焰宝珠"
D.Strings[102672]="展示烈焰之击的烈焰宝珠"
D.Strings[102673]="被禁锢在时间里了。$b$b看见了吧，所以我一直坚持使用传送术！时间魔法是很危险的东西。$b$b<欧库勒斯顿了顿。>$b$b他们可能会被永远禁锢在那里。我们必须阻止艾利桑德！"
D.Strings[102674]="暗夜井的力量爆发了……$b$b肯定还有其他办法。我们会找到的！"
D.Strings[102675]="艾利桑德……你做了什么？"
D.Strings[102676]="我觉得这不可能！这样做需要的能量……"
D.Strings[102677]="织幻者图维斯就在简单附魔里做生意。"
D.Strings[102678]="这枚夏多雷护符充斥着能量，驱散了王宫的结界。"
D.Strings[102679]="我很受震动。放弃暗夜井可不容易。$b$b它的力量和诱惑会随着时间慢慢消逝。和我们一样，他们也在这个世界上找到了自己的道路。"
D.Strings[102680]="暗夜井……$b$b如此一来，夜之子将在艾泽拉斯的历史中翻开新的篇章。现在，他们摆脱了护盾和暗夜井，获得了真正的发展空间。我期待能看到他们的进步。"
D.Strings[102681]="这是正确的决定。$b$b太过强大的力量，太过沉重的责任，就算是艾利桑德也被毁掉了。我们必须学会放手。"
D.Strings[102682]="我一直很好奇，如果我们选择挽救暗夜井，那结果会怎么样？没有它的力量，我们会变成什么样？$b$b最终，我相信了塔莉萨的判断。我相信，在她的领导下，夜之子会走出全新的道路。"
D.Strings[102683]="暗夜井已不复存在了。$b$b这些夜之子得学会摆脱它的腐化能量，否则他们就死定了。但愿结局会是前者吧。"
D.Strings[102684]="必须这样。我们不再需要暗夜井和它的能量了。$b$b我们必须开创属于自己的未来。"
D.Strings[102685]="我准备好了，欧库勒斯。"
D.Strings[102686]="我准备好进入大殿了。"
D.Strings[102687]="是时候了。攻入大殿，进入暗夜要塞！"
D.Strings[102688]="……不用谢。"
D.Strings[102689]="唉。开始吧……咳咳……"
D.Strings[102690]="求你了？！我是你们的粉丝！"
D.Strings[102691]="我已经洗手不干了！"
D.Strings[102692]="唔。我不确定……"
D.Strings[102693]="快说话！"
D.Strings[102694]="唔……我有几百年没打量过奥杜尔的殿堂了。或许我该去看看其他守护者……我们有很多事可聊。再见！"
D.Strings[102695]="好好享受你们的战利品吧，勇士们！我很快就会再次需要你们的勇气和技巧。"
D.Strings[102696]="我的上古宿敌被击败了！将我束缚在英灵殿里的诅咒终于消失了。"
D.Strings[102697]="勇士必须智勇双全！"
D.Strings[102698]="又一个考验！小心点！"
D.Strings[102699]="|TInterface\\Icons\\SPELL_SHADOW_SHADETRUESIGHT.BLP:20|t%s开始施放|cFFFF0000|Hspell:228565\n|h[腐化吐息]|h|r！"
D.Strings[102700]="传送到王宫入口。"
D.Strings[102701]="传送到暗夜之泉。"
D.Strings[102702]="传送到艾利桑德的密室。"
D.Strings[102703]="传送到暗夜之塔。"
D.Strings[102704]="这座传送门内闪烁着一座高塔的影像。"
D.Strings[102705]="你听到远处有一扇门打开了。"
D.Strings[102706]="嘿，$n，从声音判断，你已经顺利击败夜之魇了。我觉得我们也该让这条龙彻底消停了。小心点，去把那些骨头收集起来，送回它们来的地方吧。"
D.Strings[102707]="对于你的热心营救，我真是感激不尽。$b$b要不是你们及时出手，我已经变成一具无脑的行尸走肉，受着暗夜井无尽的折磨了。现在……我终于摆脱它了。$b$b我始终相信塔莉萨会带领我们获得救赎的。现在，我确信夜之子可以也一定会得到救赎的。"
D.Strings[102708]="我准备好了，开始进攻吧。"
D.Strings[102709]="只有共同的敌人，才能让人抛弃分歧，团结成一支大军。$b$b一周前，这些精灵还在争吵不休。如今，多亏了你，我们可以对暗夜要塞发起总攻了。$b$b我虽然想上前线，可泰兰德要求你我和堕夜精灵一起殿后。来吧，朋友，让我们看看，这些精灵是怎么解决内部纠纷的。"
D.Strings[102710]="你准备好去调查那个时空谜锁后，就告诉我一声。"
D.Strings[102711]="我爱传送门。"
D.Strings[102712]="烧吧..."
D.Strings[102713]="好暗！"
D.Strings[102714]="好热！"
D.Strings[102715]="你好啊，我本来正像往常一样散步，然后发现这里出现了一个对非幽灵起效的体型转换法术。考虑到你目前的身高限制，我们或许可以试着清理一些浮龙。"
D.Strings[102716]="库雷恩，我给你送马掌来了。"
D.Strings[102717]="这是什么？噢，我订购的马掌总算总到了！等等……怎么回事？它们完全坏了，好像在雨水里泡了几十年。告诉那个“法师”，他该找个新供货商了。"
D.Strings[102718]="我和大法师奥图鲁斯来阻止援军抵达大门，但得由你来尽力击退他们，$n。$B$B如果他们的部队继续壮大，我们或许就守不住阵地了。"
D.Strings[102719]="该死的蜘蛛，数不清的尖叫蝙蝠，还有那些混账恶魔兽已经完全霸占了仆役宿舍。至少那些大家伙似乎已经被清除了。"
D.Strings[102720]="这些该死的害虫！你能相信吗，它们居然还在这里！？上次来的那群人完全没有帮助。对这种情况，你大概也束手无策吧？"
D.Strings[102721]="现在，和以前一样，我们必须为了生存而不择手段。"
D.Strings[102722]="这种果实真的治好了塔莉萨？太神奇了。"
D.Strings[102723]="Erana-dora isil。我对你感激不尽。"
D.Strings[102724]="你在城里救过我一次。现在又……我不值得你如此费心。"
D.Strings[102725]="终于到我了。我准备好获得自由了。"
D.Strings[102726]="这真的能够终结饥渴吗？"
D.Strings[102727]="我们不会忘记你和塔莉萨为我们所做的一切的。"
D.Strings[102728]="阿坎多尔是什么？是像传送门那样的东西吗？"
D.Strings[102729]="瓦尔托伊小姐说只要我吃了它，她就教我有关魔网的知识。她答应过的！"
D.Strings[102730]="它能让我像塔莉萨一样强大吗？她太酷了！"
D.Strings[102731]="你能把皮削掉吗？我不喜欢吃皮……"
D.Strings[102732]="呃！我想吃糖！"
D.Strings[102733]="给我的？！谢谢你！"
D.Strings[102734]="耶，魔法果子！"
D.Strings[102735]="哦不，我看不见了……"
D.Strings[102736]="哦不，真倒霉……"
D.Strings[102737]="真是个悲剧！"
D.Strings[102738]="天呐！"
D.Strings[102739]="我想谈谈奥术动能技术。"
D.Strings[102740]="你确定要我将有关奥术动能的知识从你的记忆中移除吗？"
D.Strings[102741]="你确定要学习这种新技术吗？"
D.Strings[102742]="奥术动能是一种技术，让法师可以用物理动能决定闪现术的传送方向，而不是像基础的闪现术那样只能传送到你面对的方向。"
D.Strings[102743]="我想移除奥术动能，朝我面对的方向闪现。"
D.Strings[102744]="我想学习奥术动能技术，让我可以向移动的方向闪现。"
D.Strings[102745]="我的时间有限，只能长话短说了。$b$b艾利桑德已经气疯了。她在策划着什么，可我还不清楚细节。$b$b我还在努力打探消息。等我搞清楚她的阴谋就立刻联系你。$b$b保重。"
D.Strings[102746]="他们已经注意到了你的新盟友。$b$b我不知道你是从哪儿找来这么一群人的，但他们对大步道的渗透行动进展喜人。可惜我不得不掩饰自己的情绪。$b$b城里的气氛越来越不安了。贵族们已经不再幻想能避免战斗了。艾利桑德不会允许他们坐视苏拉玛被外来者攻占的。$b$b但我现在还无法断言你们能获胜，我的朋友。$b$b小心点，保持坚强。我们回头见。"
D.Strings[102747]="我很高兴凡瑟尔没事。代我向他问好！但愿我能早日亲眼见到他。$b$b局势……越来越紧张了。暮色百合已经在贵族中造成的恐慌。他们还没有就如何应对当前的局面达成一致，但很可能是暴力镇压。我很为那些还困在城里的人担心。$b$b我收到风声说，大步道最近有行动——他们可能会加强对那一区域的控制。你们最好注意一下。$b$b如果有新消息，我再向你通报。"
D.Strings[102748]="按照你的要求，我打听了邪魂堡垒的情况。看来你们的努力已经大大拖延了他们运送囚犯的速度。遗憾的是，如果没有进一步的干扰，这一行动恐怕不会停止。$b$b在阿斯塔瓦港事件后，有人提出要对逃亡者进行扫荡。记得建议你的人小心点。更多逃亡者或许正在朝你们那儿去。$b$b此外，还有一个花边消息。王宫里最近掀起了一股新风尚，大家开始流行在头上顶一只装饰用的橙色小鸟。真是叫人看不懂。$b$b我会继续寻找我们的老朋友。一旦有新消息，我会直接联络你的。$b$b坚强点，首席奥术师。"
D.Strings[102749]="<关闭消息。>"
D.Strings[102750]="<听取第五条消息。>"
D.Strings[102751]="<听取第四条消息。>"
D.Strings[102752]="<听取第三条消息。>"
D.Strings[102753]="<听取第二条消息。>"
D.Strings[102754]="<听取第一条消息。>"
D.Strings[102755]="目前还没有行动。我猜艾利桑德应该是对城里目前的氛围很满意。城里非常安静。也许在残月酒馆的暴行后，我们的人民已经不敢大声呼号了……$b$b我还没发现凡瑟尔的下落。值得注意的是，我们在讨论中完全没提到他的名字。$b$b顺便提一句，艾利桑德是我见过的最不守时的家伙，当她的顾问真是倒了大霉了。$b$b我会尽快发来新消息的。小心点，塔莉萨。"
D.Strings[102756]="<莉莉丝的影像期待地望着你。想听听它带来的消息吗？>"
D.Strings[102757]="艾利桑德想用我杀一儆百，结果反而为我们的行动推波助澜。$b$b她在残月酒馆的行动罪无可赦。"
D.Strings[102758]="我看到了许多残月酒馆的老熟人！看到这么多人都逃过一劫，我总算能松口气了。$b$b至于那些死难者，我将为他们哀悼。"
D.Strings[102759]="阿坎多尔是夜之子的未来。尝过它的果实后，我终于可以用一直以来渴望的方式帮助我的人民了……帮他们摆脱魔力酒。"
D.Strings[102760]="我欠你一条命，$n。至于塔莉萨，我欠她一个未来。"
D.Strings[102761]="凡瑟尔挣扎着站了起来。"
D.Strings[102762]="空气变热了一点。"
D.Strings[102763]="空气中弥漫着某种诡异的黑暗寒风……"
D.Strings[102764]="我从希尔格林那里学到了很多，可我还有很多东西要学。$b$b但愿在面对艾利桑德时，我已经做好了准备。"
D.Strings[102765]="你好啊！你看到没有，我终于晋升为法师啦！虽然是在死后……但这始终是个巨大的荣耀。$b$b这次晋升也给我带来了新任务：装修塔楼。它可以变得更迷人一些，说不定大法师卡德加以后会用得着它。"
D.Strings[102766]="你！你在干什么？"
D.Strings[102767]="把它们混合起来！"
D.Strings[102768]="一份死亡……两份毁灭……"
D.Strings[102769]="再加一剂这个！"
D.Strings[102770]="加点这个……再加点那个……"
D.Strings[102771]="我好——久没有这么开心了！"
D.Strings[102772]="我这是骗谁呢？这才是真正的我！"
D.Strings[102773]="我想我是……罪有应得。"
D.Strings[102774]="总是……这样……"
D.Strings[102775]="我敢打赌，你更喜欢这样的我！"
D.Strings[102776]="我已经……无可救药了……"
D.Strings[102777]="可耻……真可耻……"
D.Strings[102778]="善良没什么用！"
D.Strings[102779]="净化你的头脑中漆黑的邪恶念头。记住她的教诲吧！"
D.Strings[102780]="我一直在研究高级魔法。说不定我还能申请加入肯瑞托！"
D.Strings[102781]="我不知道……我有点怀念过去的日子。"
D.Strings[102782]="圣女为我们指出了一条明路！"
D.Strings[102783]="好人……没好报……"
D.Strings[102784]="我……让……圣女……失望了……"
D.Strings[102785]="我不想再当好人了……真的！"
D.Strings[102786]="你想玩玩？那就来玩吧！"
D.Strings[102787]="我再也不会跟你们这种人鬼混了！"
D.Strings[102788]="噢，亲爱的……你可真迷人！"
D.Strings[102789]="圣女是不会赞成的！"
D.Strings[102790]="|cFFFF0000赫娅|r返回了战场！"
D.Strings[102791]="|cFFFF0404海姆达尔|r返回了战场！"
D.Strings[102792]="跟我上楼，我们可以避开那些好奇的顾客激活这个盒子……"
D.Strings[102793]="好了，去激活它吧……我得退开一点……在安全距离上观察它的变化。"
D.Strings[102794]="有人来了……你是谁？！等等！放开我！大胆！你知道我是谁吗？！"
D.Strings[102795]="看来暗夜井的下方存在着某个直通王宫的薄弱点！他们想把它封印起来，但我相信你一定能——"
D.Strings[102796]="激活盒子！"
D.Strings[102797]="<这个盒子发出单调的嗡嗡声，透着一种期待的感觉>"
D.Strings[102798]="攻打主门无异于送死，但或许还有其他办法。安达丽斯派她的奥术师去了秩序大殿。"
D.Strings[102799]="艾利桑德任命了一个新的首席奥术师：一个名叫安达丽斯的可怕女人。她们一起施展了一个突围的大型法术。"
D.Strings[102800]="塔莉萨，但愿你能顺利收到这个消息。我刚开完紧急会议，会上讨论部落和联盟兵临苏拉玛城下的事。"
D.Strings[102801]="这些血精灵身经百战，纪律严明。他们的力量会很有用的。"
D.Strings[102802]="暗夜精灵居然还在用弓箭！苏拉玛恐怕已经有几百年没有使用弓箭了。不知道他们肯不肯让我也参加练习……"
D.Strings[102803]="很难相信我们都是同一批精灵的后裔。看来我们并不是真的不受时光流逝的影响。"
D.Strings[102804]="一般人都要花上好几年才能掌握魔剑术。维多利亚更适合指导起义军学习基础的格斗技巧。"
D.Strings[102805]="这么说，高高在上的肯瑞托是来防止我们惹麻烦的。有他们在，我个人觉得安全多了。我很好奇，如果卡多雷那边惹出什么乱子，他们真的会出手调停吗？"
D.Strings[102806]="哼。你们的部队完全就是乌合之众。幸好我们的血骑士和魔导师将充当这次突袭的中坚力量，直击苏拉玛的心脏。"
D.Strings[102807]="暗夜井。一座超乎想象的魔力之泉。要是辛多雷拥有这么一座魔力之源会怎么样？……$b$b无所谓了。我们开创了自己的命运。我们的荣耀属于自己，而且我们也不再是魔瘾的奴隶了。$b$b这次攻城战是个里程碑式的时刻，$n。我们和失落已久的同胞，还有我们的敌人一起对抗世界上最强大的魔法师。我们的行动将决定全体精灵的命运。"
D.Strings[102808]="别忘了你的伪装！"
D.Strings[102809]="我们要将夜之子对我们的圣地所做的一切十倍奉还。"
D.Strings[102810]="或许我会写一本有关暗夜精灵历史的书。他们的故事真迷人。"
D.Strings[102811]="我跟那些辛多雷魔法师聊过。他们跟我说了自己家乡的大图书馆。总有一天，我一定要去看看……"
D.Strings[102812]="月之守卫曾发誓守护这片土地。虽然我们人数稀少，但我们会尽力而为的。"
D.Strings[102813]="我看过哨兵们在营地里练习射击。真是一群神射手……$b$b我们从来没有真正重视过弓箭。毕竟，在能调动世界本源力量发射火球时，谁还会用那种原始的武器呢？"
D.Strings[102814]="这些血精灵的魔法很强大。但愿这足以对抗暗夜井的力量。"
D.Strings[102815]="暮色卫队非常强大。要想完成目标，我们就需要所有可以出击的战士。"
D.Strings[102816]="释放你的怒火吧，奥尔阿纳斯，让我们的客人变得更强大！"
D.Strings[102817]="我召唤你，冰霜之魂奥尔阿纳斯，风暴的愤怒，冰川的碎片！"
D.Strings[102818]="我们的客人想在熔炉中考验自己的力量。帮帮他们吧，维斯莱斯！"
D.Strings[102819]="魔力之魂维斯莱斯，力量的守护者，意志的化身，现身吧！"
D.Strings[102820]="失败只是变革的契机。等你能集中精神时，再回来面对我们的考验吧。"
D.Strings[102821]="我们的队伍正在凋零，但我们会派出人手帮助你。去为我们复仇吧，把燃烧军团赶回地狱去。"
D.Strings[102822]="打得好！你展现出了超越年龄的潜力。"
D.Strings[102823]="全力考验一下我们的客人吧，奎玛尔！"
D.Strings[102824]="烈焰的化身，怒火的实形——来吧，烈焰之魂奎玛尔！"
D.Strings[102825]="很好。集中精神。你将接受月之守卫的传统试炼。"
D.Strings[102826]="来吧，我们得在那个深渊领主发现沙尔艾兰之前阻止它。"
D.Strings[102827]="|TInterface\\Icons\\inv_misc_monsterhorn_03.blp:20|t一头%s出现在海拉的远处！"
D.Strings[102828]="我来打通道路。你们去对付那头恶魔，我来切断塔楼与军团世界的联系。我们最好快一点！"
D.Strings[102829]="麦迪文？"
D.Strings[102830]="我在这座塔的各个角落留下了许多碎片……"
D.Strings[102831]="<回忆大酋长希尔瓦娜斯与吉恩·格雷迈恩的斗争>"
D.Strings[102832]="<回忆伊瑟拉的超脱>"
D.Strings[102833]="<回忆伊瑟拉的堕落>"
D.Strings[102834]="<回忆你初到苏拉玛的经历>"
D.Strings[102835]="<回忆卡德加的诱惑>"
D.Strings[102836]="<回忆伊利丹的伊利达雷>"
D.Strings[102837]="<回忆古尔丹的故事>"
D.Strings[102838]="<回忆大酋长希尔瓦娜斯的即位>"
D.Strings[102839]="<回忆破碎海滩大撤退>"
D.Strings[102840]="<回忆瓦里安·乌瑞恩国王之死>"
D.Strings[102841]="<回忆你在守望者地窟的监禁生涯>"
D.Strings[102842]="<回忆你在马顿的任务>"
D.Strings[102843]="<回忆伊利丹的末路>"
D.Strings[102844]="<回忆缚光载体>"
D.Strings[102845]="<这个盒子里散发出的力量使你回想起了在破碎群岛的经历。>"
D.Strings[102846]="他们没有发现我。如果没人发现从阴影中刺出的匕首，那么防线上的裂缝就会越来越大。"
D.Strings[102847]="尽管掌握着“精湛的奥术魔法”，可他们对扑面而来的炎爆术仍然毫无防备。我几乎都要为他们难过了。我说的是“几乎”。"
D.Strings[102848]="检查道标"
D.Strings[102849]="奥露乐在小小的墓碑前放下一朵暗紫色的鲜花。"
D.Strings[102850]="在古老雄伟的苏拉玛城外围，堕夜精灵们在为生存而战，腐蚀悄然滋长……"
D.Strings[102851]="要是她的表演没那么肤浅，我们就不会失业了！"
D.Strings[102852]="呃！他真是太讨厌了！那个混蛋。"
D.Strings[102853]="我要告诉你，其实我很聪明。"
D.Strings[102854]="你知道，我在台上时，并不是“真的”害怕。我只是演技逼真，真的。"
D.Strings[102855]="别告诉其他演员，但我很高兴我们的剧目暂时停演了——我很担心会在以后的职业生涯中被定型为铁皮人演员！"
D.Strings[102856]="你想让我叫你“宝贝”吗？或许还要来点旋风？那叫“浮夸”，亲爱的。"
D.Strings[102857]="噢，亲——爱的。真高兴见到你。你带玫瑰来了吗？"
D.Strings[102858]="人们甚至都不知道真正的童星是谁了！真是……可悲。"
D.Strings[102859]="大家都在追捧这些“机智”的改编，已经没有人欣赏经典作品了！"
D.Strings[102860]="噢，没关系，亲爱的。我已经不需要别人来帮我对台词了。我已经把它们牢牢记在心里了。"
D.Strings[102861]="我得承认，我很想去探索苏拉玛之外的世界。$B$B我一直对原始文化很感兴趣！"
D.Strings[102862]="噢，恢复旧貌的感觉真好。$B$B<瓦尔托伊用手背轻轻拂过高高的颧骨。>$B$B你也看到了，魔力对皮肤很有好处！"
D.Strings[102863]="我从没意识到我们是这么依赖暗夜井。摆脱它的召唤让我感受到了……自由。"
D.Strings[102864]="<给受伤的龙后包扎。>"
D.Strings[102865]="<这头受伤的龙后躲了起来，后来她闻到走失的雏鸟的气味。但她伤得太重，没法照顾雏鸟了。>"
D.Strings[102866]="<昔日的回响在你的脑海中盘旋。幻觉先是慢慢浮现，然后快速切换起来。$B$B你睁大眼睛，盯着麦迪文碎片的双眼，众多遥远的世界明灭不定。>"
D.Strings[102867]="我想了解卡拉赞的命运。"
D.Strings[102868]="这座塔出什么事了？"
D.Strings[102869]="<低语蒙蔽了你的头脑。你的思绪变得混乱。>"
D.Strings[102870]="离开后，您将很快进入战斗。\n\n我们建议您先浏览一下法术书，设置好动作条。\n\n确定要离开吗？"
D.Strings[102871]="|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s开始施放|cFFFF0000|Hspell:227573|h[守护者之息]|h|r！"
D.Strings[102872]="这边走，奥露乐。"
D.Strings[102873]="吃下你带来的果实后，我已经变了许多。$b$b我很怀念我的兄弟，但我知道他为什么会选择牺牲自己。$b$b我想求你帮我一个忙。我想报答别人的恩惠。我还想为我的兄弟复仇。$b$b请带我去见首席奥术师，我想向她效忠。"
D.Strings[102874]="抓死那家伙。"
D.Strings[102875]="真是个长羽毛的疯子！"
D.Strings[102876]="你不过是侥幸赢了一次而已！"
D.Strings[102877]="不要灰心，下次你一定会表现得更好！"
D.Strings[102878]="天降正义！"
D.Strings[102879]="酋长派我来这里研究本地的鸟类，以便我们更好地用它们长途传信。在这个靠近部落贸易中心的地方，我已经收集了不少珍稀品种。你想拿它们试试运气吗？"
D.Strings[102880]="他已经拼命跑了。我要陪他到最后一刻。$b$b谢谢你……所做的一切。我们俩已经无能为力了。"
D.Strings[102881]="要想救出门口的那些盟友，必须干掉这个怪物！"
D.Strings[102882]="那个畸体身上有很多能量触须。艾利桑德肯定是利用它来维持谜锁的。"
D.Strings[102883]="我们可以在这里控制王宫广场，从里面打开大门！"
D.Strings[102884]="谜锁被打破了！他们自由了！"
D.Strings[102885]="好计划。祝你们好运，英雄们。"
D.Strings[102886]="我们的部队肯定乱套了。我会把这里发生的事情告诉他们，让他们准备再次进攻。"
D.Strings[102887]="呃。既然他们现在不打算让我们演出，我干嘛还要穿着这套蠢衣服？！痒死了……"
D.Strings[102888]="我不能丢下那个花瓶！它是主人的心头肉！"
D.Strings[102889]="看来你已经收拾好了，斯嘉丽丝。只要有机会，就带着你的女儿们走。"
D.Strings[102890]="该死的恶魔渣滓休想碰我的女儿。"
D.Strings[102891]="我不能丢下我的孩子！他们肯定躲起来了……$b$b求求你，找到他们！"
D.Strings[102892]="我跟着你！快走！"
D.Strings[102893]="在你后面！"
D.Strings[102894]="你以为你能逃出艾利桑德的掌心吗？去死吧，叛徒！"
D.Strings[102895]="只是一个血精灵和一个$r坐在角落里讨论战术罢了。没什么好奇怪的。"
D.Strings[102896]="我很高兴这里还有别人。隐形法术只能让我走到这里了。他们有什么侦测手段吗？"
D.Strings[102897]="我会保护你们俩的。我们走！"
D.Strings[102898]="燃烧军团在这里的力量很强。尽量不要引起不必要的注意，$r。"
D.Strings[102899]="嘁，算你走运！"
D.Strings[102900]="哈！再试一次。"
D.Strings[102901]="小心点，燃烧军团在这里的势力很强。$b$b难道夜之子忘了我们在上古之战中失去的一切吗？这条道路充满了毁灭和死亡。"
D.Strings[102902]="等它们全都闪白光后，你就可以选了。"
D.Strings[102903]="仔细观察它们的移动轨迹，并在我停手后选出正确的桶。"
D.Strings[102904]="我会把这些桶的顺序打乱。但在游戏开始前，装有啤酒的桶会闪金光。"
D.Strings[102905]="当然是玩游戏啦！"
D.Strings[102906]="幸会，$n。想知道我们把啤酒喝到只剩一桶后会干些什么吗？"
D.Strings[102907]="埃涅阿斯，你该走了。"
D.Strings[102908]="我儿子在混乱中受了伤……我拖不动他。求求你，帮帮我们！"
D.Strings[102909]="你得离开这儿。这里不安全！"
D.Strings[102910]="他、他们来得很突然。露妮特——我的孩子！呃……"
D.Strings[102911]="我这就去！"
D.Strings[102912]="你父亲会把你送到安全的地方去的。快下楼去！"
D.Strings[102913]="我听到了尖叫声！我害怕！"
D.Strings[102914]="你父亲在楼下等你——快！"
D.Strings[102915]="妈、妈妈让我躲、躲起来。"
D.Strings[102916]="我说过你会来救我的，奥鲁瑞尔还嘲笑我。看看谁笑到了最后！"
D.Strings[102917]="啊，终于自由了！谢谢你，外来者。"
D.Strings[102918]="我们得让暗夜井成为历史。我们要为自己的失败负责，向艾泽拉斯的人民赎罪。"
D.Strings[102919]="对，你应该知道。我带你看看我们的新家……"
D.Strings[102920]="诺瑞莎！我以为再也见不到你了……"
D.Strings[102921]="把一切都告诉我。关于我们的女儿……"
D.Strings[102922]="阿布索伦！你怎么了？"
D.Strings[102923]="我可以到边境上去。谢谢你，告诉阿布索伦，我就来！"
D.Strings[102924]="是……你！那封信是你送的！"
D.Strings[102925]="枯竭吧。"
D.Strings[102926]="塔莉萨？你来决定吧……"
D.Strings[102927]="我们能稳住它！我们不需要暗夜井的滋养了，但我们仍能控制它的力量……"
D.Strings[102928]="你的灵魂将让燃烧军团更加强大！"
D.Strings[102929]="它在枯竭。没有了阿曼苏尔之眼，暗夜井很不稳定。"
D.Strings[102930]="我以为自己再也见不到了它！"
D.Strings[102931]="暗夜井……"
D.Strings[102932]="我们正一步步走向胜利。"
D.Strings[102933]="苏拉玛的战斗需要你的帮助，勇士。"
D.Strings[102934]="干得好，勇士。部落与你同在！"
D.Strings[102935]="敌人是不会休息的。我们也一样！"
D.Strings[102936]="你一直是个可靠的盟友。谢谢你，勇士。"
D.Strings[102937]="堕夜精灵需要帮助。你愿意再次响应召唤吗？"
D.Strings[102938]="|TInterface\\Icons\\spell_warlock_demonicportal_green.blp:20|t%s开始启动|cFFFF0000|Hspell:229610|h[恶魔之门]|h|r！进入门里追上他！"
D.Strings[102939]="|TInterface\\Icons\\inv_legionadventure.blp:20|t%s下令进行|cFFFF0000|Hspell:229284|h[轰炸]|h|r！"
D.Strings[102940]="小心，下面很深。"
D.Strings[102941]="我懂了！"
D.Strings[102942]="手放松。不用抓得这么紧。"
D.Strings[102943]="控制呼吸。在出手时要用力呼气。"
D.Strings[102944]="肩膀放松。你这样会影响机动性。"
D.Strings[102945]="这样呢？"
D.Strings[102946]="这样对吗？"
D.Strings[102947]="我知道了，希尔格林。"
D.Strings[102948]="我想我明白了。"
D.Strings[102949]="双脚分开一点。你这样会站不稳。"
D.Strings[102950]="我找不到渗透者，卡德加。你能帮我侦测他们的位置吗？"
D.Strings[102951]="决不能让古尔丹使用暗夜井。"
D.Strings[102952]="精灵们非常焦躁。肯瑞托只能尽量维持和平了。"
D.Strings[102953]="这里的紧张气氛简直叫人窒息。我们必须尽快出击……"
D.Strings[102954]="躲开那些狂暴的能量，还有……别摔下去，好吗？"
D.Strings[102955]="你必须穿过那些能量球，来为我给你的能力充能。噢，呃……"
D.Strings[102956]="我会对你施放一个法术，让你能在空中飞行。用它去攫取远处的目标吧。"
D.Strings[102957]="我们又来到这里了，$n。你注意到周围那些飞舞的魔力了吗？"
D.Strings[102958]="跑吧，小老鼠！"
D.Strings[102959]="逃跑会让你付出生命的代价！"
D.Strings[102960]="如果想活命的话，就待在屋里！"
D.Strings[102961]="都给我待在家里！"
D.Strings[102962]="我的防线……是完美的……"
D.Strings[102963]="这种行为必须受到严惩。"
D.Strings[102964]="其他人！救救其他人！"
D.Strings[102965]="尽你所能吧，$n，但你要小心点。"
D.Strings[102966]="卡多雷，准备冲击广场！艾露恩要求你们净化这里的邪恶！"
D.Strings[102967]="辛多雷，占领大步道，守住阵地！今天，圣光必将制裁我们的敌人！"
D.Strings[102968]="夏多雷，该夺回我们的城市了！前进！Anath'ashar！"
D.Strings[102969]="塔莉萨，你来带头冲锋。"
D.Strings[102970]="或许我该为你破一次例。"
D.Strings[102971]="这只是小菜一碟。刻苦的训练给了我坚定的决心。"
D.Strings[102972]="这对我不算什么。"
D.Strings[102973]="我们与燃烧军团势不两立。"
D.Strings[102974]="我的忠诚从未改变。"
D.Strings[102975]="艾利桑德休想逍遥法外。"
D.Strings[102976]="我效忠于全苏拉玛的人民。"
D.Strings[102977]="枯法者都没你这么讨厌。"
D.Strings[102978]="我跟你无话可说。"
D.Strings[102979]="我不明白你干嘛老来惹我。"
D.Strings[102980]="这种时候，你来沙尔艾兰做什么？"
D.Strings[102981]="他这副样子真叫我心碎。"
D.Strings[102982]="我们的朋友就躺在这儿。"
D.Strings[102983]="我们作好夺取大殿的准备了。现在就看瓦尔托伊的了。等她准备好，我会优先通知你的。"
D.Strings[102984]="我来寻求月之守卫的指点。"
D.Strings[102985]="你来到了我们的熔炉。数千年来，我们最尊贵的法师在这里经受考验。你来干什么？"
D.Strings[102986]="你踏上了一片圣地，外来者。你肯定是带着目的来的吧？"
D.Strings[102987]="你想要什么：智慧还是力量？或是两者兼有？"
D.Strings[102988]="别担心。他们不听我劝，有几百年没升级过结界了……"
D.Strings[102989]="他们的结界不会妨碍传送术吗？"
D.Strings[102990]="我有个主意！群体传送……但我需要帮手。"
D.Strings[102991]="特尔安的疯狂简直不知节制。要不是你，那头野兽或许会毁掉整个平台。"
D.Strings[102992]="特尔安的实验太离谱了！有一头野兽正在平台上肆虐！"
D.Strings[102993]="那些叛徒罪有应得。历史会记住他们的罪行的。"
D.Strings[102994]="艾利桑德的佞臣和情人就在她位于暗夜之塔顶层的私人套间里。不能让他们去向燃烧军团报警！"
D.Strings[102995]="我们离结束这场混乱又近了一步。艾利桑德的末日就要到了！"
D.Strings[102996]="只要控制了暗夜之塔，王宫就完了。快阻止仪式！"
D.Strings[102997]="没有了稳定的补给，王宫很快就会沦陷。干得好。"
D.Strings[102998]="找到王宫的补给线并切断它。飞行管理员沃尔纳斯应该就在队长宅邸附近。"
D.Strings[102999]="就当给那些炫耀武力的人一个教训吧。"
D.Strings[103000]="艾利桑德的私人构造体就在附近。要是它出了什么事，那就太可惜了……"
D.Strings[103001]="我不信我们的遮蔽法术会失效。快，找到奥鲁瑞尔，攻破大门！"
D.Strings[103002]="法多雷冲入了王宫！阻止他们，别让卫兵发现了！"
D.Strings[103003]="愿他们安息。暗夜井滋养过我们，可不管怎么看，它现在都已经成了痛苦之源。"
D.Strings[103004]="我先祖的灵魂被暗夜井的能量禁锢了。我们得让他们解脱。"
D.Strings[103005]="要是那只双头怪被暗夜井强化，那就糟了。谢谢你救了我们。"
D.Strings[103006]="一只双头怪正在破坏墓地！快阻止它，别让它造成更大的损失！"
D.Strings[103007]="|TInterface\\Icons\\ABILITY_PRIEST_FLASHOFLIGHT.BLP:20|t赫娅的|cFFFF0404|Hspell:228162|h[光明之盾]|h|r瞄准了|cFFFF0000$n|r！"
D.Strings[103008]="不！传送门……"
D.Strings[103009]="见识一下无尽的军团吧！"
D.Strings[103010]="传送门又有新燃料了！"
D.Strings[103011]="这不可能？你做了什么？"
D.Strings[103012]="开启结界！"
D.Strings[103013]="我们会送他回去的。快去向塔莉萨报喜吧。"
D.Strings[103014]="<咳嗽。>我得……休息了。谢谢你所做的一切。"
D.Strings[103015]="暮色百合……是所有人的……希望。"
D.Strings[103016]="他们想杀鸡儆猴。我们截取了他们的消息，并利用了它。"
D.Strings[103017]="欢迎回家，老朋友。"
D.Strings[103018]="Aran'ethil……噩梦结束了！"
D.Strings[103019]="终于……解脱了……"
D.Strings[103020]="他会好起来的。果实能治好他的。"
D.Strings[103021]="别动，我的朋友。我们救你出去。"
D.Strings[103022]="我不知道。但愿现在还不迟。"
D.Strings[103023]="我们还有多少时间？"
D.Strings[103024]="他将被公开处刑。"
D.Strings[103025]="这效果比我想的还要好！我要继续改进，为下一步的行动做准备。"
D.Strings[103026]="我看够了。我想我能压制邪能魔法对枯法者的作用。去灵魂引擎吧，我会把新的实验体送过去的。"
D.Strings[103027]="或许吧。首席奥术师知道该怎么做。我们把这些人送去沙尔艾兰。"
D.Strings[103028]="这些邪能水晶稳固了军团的力量。我们来看看枯法者能否对付它们。"
D.Strings[103029]="不！……我会……卷土重……"
D.Strings[103030]="你这一无是处的蝼蚁！"
D.Strings[103031]="我很乐意把你的灵魂消磨殆尽！"
D.Strings[103032]="哈！你这是自寻死路，凡人！"
D.Strings[103033]="传送宝珠非常完美。在动真格的之前，我们最好保密。"
D.Strings[103034]="我们必须结束这一切。"
D.Strings[103035]="我本该震惊的，可自从残月酒馆的事后，我就麻木了。"
D.Strings[103036]="我们被发现了！"
D.Strings[103037]="这样应该就够了。这个位置数据能——噢，算了。你做得很好。"
D.Strings[103038]="很好。好了就开始吧。使用测量器，然后跟着调正指示器走。呃……就是光，跟着光走！"
D.Strings[103039]="那好。去见希尔格林吧。他的训练会让你成为一个好战士。"
D.Strings[103040]="你肯定是阿鲁因的姐妹。他是我们的大恩人。他不会白白牺牲的。"
D.Strings[103041]="很荣幸见到你，首席奥术师。"
D.Strings[103042]="我兄弟长眠于此。我叫奥露乐。"
D.Strings[103043]="这棵树上的果实将我从疯狂边缘救了回来。我全好了，我想战斗。"
D.Strings[103044]="你还记得我吗，外来者？"
D.Strings[103045]="她就在外面等你。"
D.Strings[103046]="你还是那么准时，德琳。"
D.Strings[103047]="这边！大家都上船！"
D.Strings[103048]="但愿她能看到……"
D.Strings[103049]="我们恐怕不能在此久留。屏住呼吸。"
D.Strings[103050]="如果情况不对，就让枯法者做好准备。祝你好运，$n。"
D.Strings[103051]="我来开启传送门。出其不意对你有好处！"
D.Strings[103052]="成功了。护盾关闭了。"
D.Strings[103053]="很好，我这就开始。完成之后，我们“调整”过的设备就会全部停工了。"
D.Strings[103054]="我不敢在这里做手脚。我要回沙尔艾兰继续研究。"
D.Strings[103055]="唔……它们将一部分魔网能量引向了秩序大殿。"
D.Strings[103056]="这种卑鄙勾当肯定是某个矮人干的……"
D.Strings[103057]="好吧，这太幼稚了。"
D.Strings[103058]="机智的隐蔽法术，可那是什么？接着看。"
D.Strings[103059]="谁会把这么恶心的东西放在这儿？"
D.Strings[103060]="那些远离自然的自大狂，被邪能烧坏了脑子！"
D.Strings[103061]="这里的魔网在枯竭，可我看不到……等等！我有主意了。"
D.Strings[103062]="为了苏拉玛，我需要你的帮助。夜之子的存亡就在此一举了。"
D.Strings[103063]="勇士！我需要你帮忙。我们有很重要的事要做。"
D.Strings[103064]="勇士！又该展现你的力量和技巧了！"
D.Strings[103065]="它们暂时安全了，我也松了口气。唔，或许我该收养几只……"
D.Strings[103066]="鹰头猫之王尤隆在召唤小猫回家时遇到了麻烦。看看那些眼睛，勇士。你不能把它们丢在险境里！"
D.Strings[103067]="我来帮你。这个形态不太适合近距离战斗，但我们有一位强大的勇士。"
D.Strings[103068]="这种腐蚀非常残酷，但你击退了它……哪怕是暂时的。"
D.Strings[103069]="苏拉玛依然有莎拉达希尔的腐蚀痕迹。或许那些邪恶萨特的角还有更大的用处。"
D.Strings[103070]="看来你俩很亲密。盟友就是盟友……不管它有多小！"
D.Strings[103071]="海滩附近有只特别的生物在挑战当地的龙虾人。我能感受到你与它之间的联系……去帮帮它，勇士。"
D.Strings[103072]="看来跳舞也有危险！小心别绊倒了。"
D.Strings[103073]="自从上次……意外之后，黑羽部族又选了位新酋长。看来他们打算再举行一次仪式。"
D.Strings[103074]="干得好，勇士。你战斗起来就像狂怒的风暴！"
D.Strings[103075]="法尔加附近的山顶上酝酿着一场酷寒风暴。去消灭它的源头，以免严寒侵袭大地！"
D.Strings[103076]="这是最后一个了。解开这个结，能量就能恢复流动了。$b$b但愿你准备好了。"
D.Strings[103077]="干掉一个，还剩两个。你好了就说一声。"
D.Strings[103078]="啊，你来了。我以为这里会有发现，可是……"
D.Strings[103079]="我记得这股力量……凯尔巴洛！我们的目标是深红林地。"
D.Strings[103080]="嗯？你想了解什么？"
D.Strings[103081]="对，我知道汇聚的魔网为暗夜井提供了庞大的能量。驾驭这么多能量很危险，可要是她能……"
D.Strings[103082]="谢谢，勇士。决不能让卓格巴尔破坏我们的生活方式。我们是高岭部族！"
D.Strings[103083]="桀骜不驯的卓格巴尔把我们的补给箱扔到裂口底下去了。幸好我们能够轻松地找回它们……"
D.Strings[103084]="秩序终于恢复了。我们永远欢迎你，勇士。为了至高岭！"
D.Strings[103085]="卓格巴尔正在大肆破坏雷霆图腾，砸烂我们的战鼓，吓跑我们的牲畜。必须阻止这些捣乱分子！"
D.Strings[103086]="你控制大股能量的能力很惊人。这可不是什么小把戏。"
D.Strings[103087]="%s检查了碎片。"
D.Strings[103088]="你真能看到魔力流吗？还是感应到的？这种感应是时刻存在的，还是能控制的？"
D.Strings[103089]="你先去通知塔莉萨吧。我有几个问题要问我们这位朋友。"
D.Strings[103090]="我知道她的本事。所以我们必须阻止她。"
D.Strings[103091]="你是个出色的助手。你对魔网的了解都快赶上我了。"
D.Strings[103092]="在回沙尔艾兰前，我得休息一下。这比我想的累多了……"
D.Strings[103093]="%s喜欢你。"
D.Strings[103094]="%s高兴地叫着。"
D.Strings[103095]="%s看起来很满足。"
D.Strings[103096]="吼……"
D.Strings[103097]="%s刚刚冒险归来，感觉累坏了！"
D.Strings[103098]="小心，勇士！它来了！"
D.Strings[103099]="你最好快点。我感觉某种……饥渴的东西在靠近！"
D.Strings[103100]="那些……那些……暗夜精灵！"
D.Strings[103101]="那些住在树上的卡多雷蛮子。"
D.Strings[103102]="他们是从哪儿弄到这种材料的？"
D.Strings[103103]="我都不想去猜它是用什么做的。"
D.Strings[103104]="这是什么玩笑吗？！"
D.Strings[103105]="枯法者……被邪能魔法轻易击溃了。请……尽力救他们。我的伤……不算什么！"
D.Strings[103106]="我可不打算亲自出手。邪脉部队！杀了他们！"
D.Strings[103107]="让我们看看叛军的能耐吧！派你的精锐到莉莉丝的庄园来……否则我就要……询问更多的平民！"
D.Strings[103108]="可怜的塔莉萨……你想拯救你的人民，却拿走了他们唯一的救命稻草！莉莉丝恐怕要为你的傲慢付出代价了。"
D.Strings[103109]="来看看这些活死人的本事吧。进攻！"
D.Strings[103110]="哈！你就这点人手？一个外来者和一群嗜魔成瘾的活死人？看来你的日子不好过啊。"
D.Strings[103111]="艾利桑德任命你为首席奥术师？她一定是别无选择了。立刻放了莉莉丝！"
D.Strings[103112]="咕噜！"
D.Strings[103113]="啾？"
D.Strings[103114]="呼噜……"
D.Strings[103115]="我准备好了，瓦尔托伊。"
D.Strings[103116]="准备好举行仪式了吗，$n？"
D.Strings[103117]="这个洞真隐蔽。想不到欧库勒斯居然能把我们完好无损地送进来。"
D.Strings[103118]="舒适、隐蔽，而且充满了奥术能量。我要在这里建个工作室……"
D.Strings[103119]="我会用传送器前往庄园，并带上我们最强的枯法者。去那儿见我。"
D.Strings[103120]="游戏……开始！"
D.Strings[103121]="嗯？！"
D.Strings[103122]="干掉她！"
D.Strings[103123]="你们这些废物只会躲闪！"
D.Strings[103124]="出来一战，别再躲了！"
D.Strings[103125]="哇！你这么快就死了?"
D.Strings[103126]="<把你的越桔干分一些给失怙的利爪龙。>"
D.Strings[103127]="<把你的阿苏纳葡萄分一些给失怙的血眼龙。>"
D.Strings[103128]="<把你的烟熏大角鹿肉分一些给失怙的雪羽龙。>"
D.Strings[103129]="<把你的刺鼻的维库辣奶酪分一些给失怙的恐嘴龙。>"
D.Strings[103130]="<这只失怙的雪羽隼龙太虚弱了，几乎走不动路。>"
D.Strings[103131]="<这只失怙的利爪隼龙饿得哇哇大哭。>"
D.Strings[103132]="<这只失怙的血眼隼龙无法控制地颤抖着。它看起来吓坏了。>"
D.Strings[103133]="<这只失怙的恐嘴隼龙疯狂地四处寻找它的妈妈。>"
D.Strings[103134]="我想对你的研究提点建议。如果你不介意的话，可以看看书柜的顶上。"
D.Strings[103135]="但自从研究事故爆发后，我们就倾向于保持距离了。"
D.Strings[103136]="如果你愿意，可以帮我找魔力流，别妨碍我就行。"
D.Strings[103137]="可你得先把文献找到。我找不到它了……"
D.Strings[103138]="继续，想看看东部海岸的巨龙吗？"
D.Strings[103139]="那肯定很有趣。"
D.Strings[103140]="多头蛇。它们是神奇的生物。"
D.Strings[103141]="我到前面去为幸存者清理一片安全区域出来。坚持住，朋友。"
D.Strings[103142]="那就继续吧。"
D.Strings[103143]="嗯？噢，又是你。你肯定是来搞课余研究的吧？"
D.Strings[103144]="你来了！这边！"
D.Strings[103145]="练习一下你的攻击技能，消灭这些目标假人吧。"
D.Strings[103146]="唔。没我预计的那么近，但也够了。小心点。"
D.Strings[103147]="我会尽力把你传送到残月酒馆附近。保持联络。"
D.Strings[103148]="越来越多的疯鸟占据了这里。快去干掉几只，别让它们的蛋孵化了。"
D.Strings[103149]="小心这些猛禽的爪子！我们发现它们很凶猛。"
D.Strings[103150]="这些长羽毛的怪物简直繁殖无度！快去制止它们的狂欢！"
D.Strings[103151]="这群猛禽来自海上。把它们赶回去，否则我们就完了。"
D.Strings[103152]="我们听到了鸟叫声！但愿胜利者是你。"
D.Strings[103153]="干得好，你平息了这场猛禽的灾难。"
D.Strings[103154]="你折断了它们的翅膀。"
D.Strings[103155]="又一场大胜！你真是个出色的猎手。"
D.Strings[103156]="陌生的掠食者正在破坏这里的生态。快去削减它们的数量！"
D.Strings[103157]="谢谢你。我们会密切关注它们的数量的。"
D.Strings[103158]="下一个应该放在这儿。"
D.Strings[103159]="随便了，继续！"
D.Strings[103160]="我们进来了。"
D.Strings[103161]="如果你想拨弄魔力流，起码要找对节点。再往右边一点试试。"
D.Strings[103162]="|TINTERFACE\\ICONS\\SHA_ABILITY_ROGUE_BLOODYEYE:20|t当不应存在之物施放|cFFFF0000|Hspell:207720|h[见证虚空]|h|r时转开视线，以避免陷入恐惧！"
D.Strings[103163]="|TINTERFACE\\ICONS\\SHA_ABILITY_ROGUE_BLOODYEYE:20|当不应存在之物施放|cFFFF0000|Hspell:207720|h[见证虚空]|h|r时转开视线，以避免陷入恐惧！"
D.Strings[103164]="大法师卡莱，我们需要你的帮助。"
D.Strings[103165]="我们得立刻赶去卡拉赞，看看军团想干什么。我这就开启传送门。"
D.Strings[103166]="这样就够了，奥术师。我送你们去沙尔艾兰。跟我来。"
D.Strings[103167]="成功了！魔力重新流向了沙尔艾兰。"
D.Strings[103168]="就快……完成了！再坚持一会儿！"
D.Strings[103169]="魔力流很混乱……这需要一点时间。"
D.Strings[103170]="这个仪式需要我集中全部精神。千万别让人干扰我。"
D.Strings[103171]="燃烧军团占领了卡拉赞！我们得把它夺回来！"
D.Strings[103172]="不！我把注意力都放在破碎群岛上，忽略了我的防御措施……"
D.Strings[103173]="真可惜……结果似乎不是太好。水晶里的编码信息都乱了。我只能辨认出一部分……"
D.Strings[103174]="现在，把你发现的碎片拼起来。"
D.Strings[103175]="辛多雷和夏多雷，占领大步道并挡住敌人。等我们攻下阵地，卡多雷就冲上去占领广场。"
D.Strings[103176]="我的天。这算是赞美吗？"
D.Strings[103177]="这最后一个能让我扭转能量的流动，就像船舵一样。把它放在这儿就行了。"
D.Strings[103178]="好吧！我们可以照你说的做。可要是这座洞最后被魔法能量炸了，那都是你的错。"
D.Strings[103179]="我研究魔网几千年了，我当然能找到，正确的位置就在我脚下！"
D.Strings[103180]="我不是要“拨弄”，我是想震——哼。我觉得是这里……"
D.Strings[103181]="等等！你搞错了！我们只是想……好吧，我想你其实是对的……"
D.Strings[103182]="成了？看来你还有点儿能耐。"
D.Strings[103183]="可我能看见魔力流和魔网节点。你应该放在这儿。"
D.Strings[103184]="你确定那个位置对吗？这里更好一些。"
D.Strings[103185]="把它放到关键节点，我就能控制魔网的流向。"
D.Strings[103186]="看在这位勇士的份上，我才没出手。有话快说。"
D.Strings[103187]="还想躲吗，堕夜精灵？我在栖地就感应到你的传送波动了！"
D.Strings[103188]="啾！"
D.Strings[103189]="等等……你说什——"
D.Strings[103190]="好了！我基本锁定了你要求的地点。出发！"
D.Strings[103191]="下一站，阳光灿烂的阿苏纳！起码……我上次去时还是那样，那只是几千年而已。"
D.Strings[103192]="准备好了吗，$n？我最喜欢传送去新地方了！"
D.Strings[103193]="法师传送门的施法时间太长了。有了传送术，就能实现瞬间传送了！"
D.Strings[103194]="传送道标会为三角网络提供能量。我们得多建造一些道标。"
D.Strings[103195]="不再饥渴的感觉真好。现在的我什么都能传送！"
D.Strings[103196]="别再耽搁了。我们去找凡瑟尔。"
D.Strings[103197]="我知道。"
D.Strings[103198]="她……没有……看错你……"
D.Strings[103199]="所以你就对我们刀剑相向！你只是个叛徒罢了！"
D.Strings[103200]="我还有良心。我要为人民而战。"
D.Strings[103201]="你辜负了她，魔剑士。如果你留下，我这位置就是你的了。"
D.Strings[103202]="也许吧，但我还有朋友。"
D.Strings[103203]="认命吧，希尔格林。你不如我！"
D.Strings[103204]="欢迎光临，希尔格林。奥鲁瑞尔向你问好！"
D.Strings[103205]="放下剑，索拉米尔！"
D.Strings[103206]="你想破坏处刑？很好。我就先拿你开刀！"
D.Strings[103207]="我没能及时举起盾牌。出什么事了？"
D.Strings[103208]="莉亚德琳！我试着把她拉出来，但我得集中全部精神。小心点，$n。"
D.Strings[103209]="我维持不了防护法术了！我们得走了。"
D.Strings[103210]="没时间了。我把你送到安全地带去！"
D.Strings[103211]="我……没事。出什么事了？"
D.Strings[103212]="好险啊！我差点就破坏了时光流……但现在好多了。你没事吧？"
D.Strings[103213]="泰兰德！我试着把她拉出来，但我得集中全部精神。小心点，$n。"
D.Strings[103214]="小心！这里的时光紊乱已经引起了敌人的注意！好了，带路吧。"
D.Strings[103215]="这种时光魔法足以和青铜龙军团媲美了！我得集中精神维持防护法术。"
D.Strings[103216]="我们的盟友受到了魔力的灼烧。我可以帮大家暂时抵挡残余能量的伤害。"
D.Strings[103217]="蓝翼蓝龙是群宝贵的盟友。只要你肯帮忙，他们就会支持我们对燃烧军团的战斗。"
D.Strings[103218]="%s被附近子嗣的死激怒了！"
D.Strings[103219]="目前为止，苏拉玛的部队还不敢出城决战。但愿他们没在背地里搞什么小动作。"
D.Strings[103220]="今天早上，温蕾萨差点就对罗曼斯拔箭了。卡德加又去劝了她老半天。"
D.Strings[103221]="这些精灵总是在彼此挑衅。我们来这里，就是为了防止他们擦枪走火。"
D.Strings[103222]="卡德加号召有志者派出部队来支援这支大军。结果谁来了呢？\n\n血精灵和暗夜精灵。这两个水火不容的种族让联盟和部落的分歧都显得微不足道。"
D.Strings[103223]="苏拉玛是座充满魔力的城市，要入侵它是个极大的挑战。但愿我们能让这些部队保持团结，直到获胜。"
D.Strings[103224]="鬼祟的堕夜精灵在魔网废墟中重建魔力晶塔。蓝翼蓝龙想请你帮忙解决这个麻烦，勇士。"
D.Strings[103225]="我们绝不允许这几支军队之间发生冲突。我们就是来防止精灵们偏离目标的。"
D.Strings[103226]="卡多雷，辛多雷，奎尔多雷，还有夏多雷？都是一群小心眼，对吧？"
D.Strings[103227]="作为并肩作战的双方，部落与联盟的关系已经够紧张了。可精灵呢？他们间的紧张气氛都接近凝固了。"
D.Strings[103228]="你画得真好。我真想请你去肯瑞托上课……要不是你正忙着拯救世界的话，我一定会的。"
D.Strings[103229]="纳萨拉斯学院的学者以法术符文知识而著称。你或许能从徘徊在那里的幽灵处收集到一些古老的秘密。"
D.Strings[103230]="再也没有比肋排大餐更完美的美食了。"
D.Strings[103231]="很好，这是我最爱的奶酪。"
D.Strings[103232]="这跟我想的不一样，但知识就是知识。我们得留意其他的……学习机会。"
D.Strings[103233]="纳萨拉斯的法师以制造高品质的魔杖而著称。你最好去看看他们的技术能否帮我们对抗军团。"
D.Strings[103234]="大魔导师艾利桑德有令，禁止发表一切异见言论！"
D.Strings[103235]="反抗大魔导师的人都将付出惨重代价！"
D.Strings[103236]="我们知道你的家人在哪儿。快说，否则他们也要死！"
D.Strings[103237]="承认吧！你在包庇苏拉玛的叛徒！"
D.Strings[103238]="了解潜在的威胁可以让我们在战斗中占尽上风。你学得还是这么快！"
D.Strings[103239]="暮色卫队自以为能在革命的大潮中横行无忌。去回敬一下他们的傲慢吧！"
D.Strings[103240]="暮色卫队占领了深红林地里的岗哨。派出你麾下的枯法者，赶走他们吧！"
D.Strings[103241]="我不需要仆人，但你可以跟我走，帮我战斗。"
D.Strings[103242]="对，但你的灵魂可以做你想做的事了。你不用再服侍他了。"
D.Strings[103243]="那我跟你走。"
D.Strings[103244]="我已经服侍了他那么久，都不记得自由的感觉了。你需要仆人吗？"
D.Strings[103245]="|TInterface\\Icons\\Spell_Mage_ArcaneOrb.blp:20|t |cFFFF0000|Hspell:228877|h[奥能之环]|h|r开始从房间边缘向内塌缩！"
D.Strings[103246]="|TInterface\\Icons\\Spell_Mage_ArcaneOrb.blp:20|t%s用|cFFFF0000|Hspell:214278|h[神秘射线]|h|r瞄准了她的敌人！"
D.Strings[103247]="|TInterface\\Icons\\6BF_Explosive_Shard.blp:20|t%s引导|cFFFF0000|Hspell:209598|h[聚合]|h|r能量穿过她的敌人！"
D.Strings[103248]="|TInterface\\Icons\\SPELL_ARCANE_ARCANE01.BLP:20|t你将在6秒后|cFFFF0000|Hspell:209973|h[爆炸]|h|r！"
D.Strings[103249]="|TInterface\\Icons\\SPELL_ARCANE_INVOCATION:20|t|cFFFF0000|Hspell:210022|h[纪元宝珠]|h|r从天而降了！"
D.Strings[103250]="你被对空火枪击中了！"
D.Strings[103251]="我听说有些市民在坚守避难所……"
D.Strings[103252]="到处都是恶魔……"
D.Strings[103253]="求求你，帮我找个藏身之处吧！"
D.Strings[103254]="快！这里不安全！"
D.Strings[103255]="我安全了……谢谢你。"
D.Strings[103256]="这座城市已经疯了……"
D.Strings[103257]="我们……差点就死了！"
D.Strings[103258]="我们来救你了，凡瑟尔。再坚持一下。"
D.Strings[103259]="<凡瑟尔直直地盯着你，一言不发。>"
D.Strings[103260]="<凡瑟尔静静地躺着，双眼呆滞地凝视着虚无之处。>"
D.Strings[103261]="它连接的不是暗夜井而是魔网。可魔网还在我们手里，她是怎么……啊，我明白了！"
D.Strings[103262]="祝你们这些恶棍都变成枯法者！"
D.Strings[103263]="也许是个法力黑洞？唔……没什么。这需要大量能量。"
D.Strings[103264]="快，到废墟里去！"
D.Strings[103265]="非常有效！让我仔细看看……这法术真是惊人。"
D.Strings[103266]="纳萨拉斯学院的图书馆里据说保存着本地动物的详细研究资料。这种知识很有用。快去找找，一张纸都别放过！"
D.Strings[103267]="它能找到我们的朋友。"
D.Strings[103268]="这是什么法术？"
D.Strings[103269]="塔莉萨？！"
D.Strings[103270]="小声点，希尔格林。我也很高兴见到你。"
D.Strings[103271]="为了这项工作，我必须集中精神……你作好帮助我的准备了吗？"
D.Strings[103272]="谢谢你，希尔格林。小心点。"
D.Strings[103273]="很不幸，我认识逮捕凡瑟尔的人。"
D.Strings[103274]="别怕，首席奥术师。我一定会把他安全带回来的。"
D.Strings[103275]="这边！我感觉下面有能量汇聚，但守卫挡住了去路。你得清理一条通道出来。"
D.Strings[103276]="感谢艾露恩，你来了！我正需要帮手呢。"
D.Strings[103277]="虽然你是从对面营地过来的，不过见到你还是很高兴。快来，我们有很多事要讨论。"
D.Strings[103278]="啊，援军！这边，我有很多消息要告诉你。"
D.Strings[103279]="这边，$r。过来的时候，尽量不要惊动那些守卫。"
D.Strings[103280]="这法术的消耗比我想的还要大。你得独自去救凡瑟尔了。抱歉。"
D.Strings[103281]="大魔导师有令，必须找到并杀光叛徒！"
D.Strings[103282]="我们很接近了。我都能闻到他们的恐惧了！"
D.Strings[103283]="挖地三尺！那些叛徒休想逃跑！"
D.Strings[103284]="又一个误闯禁区的蠢货！"
D.Strings[103285]="擅入者死！"
D.Strings[103286]="他被关在谕令平台！肯定是为了公开处刑……"
D.Strings[103287]="专注！在那儿！"
D.Strings[103288]="他快变成枯法者了。他的思维开始混乱……我需要……"
D.Strings[103289]="……直到他无法思考！"
D.Strings[103290]="饥饿没有结束，反而愈演愈烈……"
D.Strings[103291]="他被带去了某个黑暗孤独的地方。他开始感觉饥饿在腹中扎根。"
D.Strings[103292]="而是为了受他保护，他曾为之牺牲的人。"
D.Strings[103293]="从残月酒馆被抓走时，他非常恐惧……但不是为了他自己。"
D.Strings[103294]="跟我说话，凡瑟尔……"
D.Strings[103295]="我准备好了，塔莉萨。"
D.Strings[103296]="施放寒冰箭以激活冰冷智慧，然后施放冰风暴。"
D.Strings[103297]="激活冰冷智慧后，冰风暴就会变成瞬发，造成的伤害也会大幅提高。"
D.Strings[103298]="施放寒冰箭可以触发“冰冷智慧”效果。"
D.Strings[103299]="冰风暴是你的另一个法术。它可以单独施放，但最好和其他技能配合使用。"
D.Strings[103300]="这样追踪人需要大量能量。但愿我能坚持住……"
D.Strings[103301]="但他还控制着我的身体，我能感觉到。"
D.Strings[103302]="我杀了你的主人，你不用再服侍他了。"
D.Strings[103303]="冥顽不灵……"
D.Strings[103304]="你是什么意思，自由？"
D.Strings[103305]="我好几个礼拜没参与他们的活动了！你一定要相信我！"
D.Strings[103306]="我们会找到你的朋友的。忏悔吧，那我们还能给你个痛快！"
D.Strings[103307]="是的，我击败了他。你自由了。"
D.Strings[103308]="你看上去不像我的主人……"
D.Strings[103309]="主人为客人准备了晚宴。\n\n但晚宴是不接待外人的，你的名字不在客人的名单里。你是来送晚宴用品的吗？"
D.Strings[103310]="信……在外面的……池塘……"
D.Strings[103311]="小心点，塔莉萨。我得回王宫了。"
D.Strings[103312]="你已经掌握了！"
D.Strings[103313]="你一定能成为联盟的强援。"
D.Strings[103314]="你一定能成为部落的强援。"
D.Strings[103315]="你学得很快！"
D.Strings[103316]="完全正确！"
D.Strings[103317]="我听说了一个有关凡瑟尔的可怕传言。"
D.Strings[103318]="很好！你一定经常练习。"
D.Strings[103319]="你学得真快！"
D.Strings[103320]="就是这样。我就知道你能行。"
D.Strings[103321]="谢谢。你有什么消息？"
D.Strings[103322]="欢迎回家，首席奥术师。感谢你能这么快赶来。"
D.Strings[103323]="你掌握得很好！"
D.Strings[103324]="既定的命运……我得想想。后会有期，勇士们。"
D.Strings[103325]="你已经所向披靡了！"
D.Strings[103326]="你的进步很大。"
D.Strings[103327]="我们面前还有许多难题。再见。"
D.Strings[103328]="关上一扇门或许比穿过它更容易。但有时，为了打破既定的命运，我们必须踏入未知的领域。"
D.Strings[103329]="别那么多愁善感！我要走了，但你要记住。"
D.Strings[103330]="我……不知道该怎么说，麦迪文。"
D.Strings[103331]="你拥有一切必备的力量，卡德加。你的心灵和勇气使你成为这个世界的守护者，一个比我更好的守护者。"
D.Strings[103332]="我早就说过了……我不想要这种力量！"
D.Strings[103333]="我的道路……在别处。而且，艾泽拉斯有新的守护者了，“年轻的信任”。"
D.Strings[103334]="恶魔被赶出卡拉赞了！多亏了你们，勇士。麦迪文，欢迎加入对抗燃烧军团的战斗。"
D.Strings[103335]="呃，这可真是……有趣。你们完成了任务，可我还没——"
D.Strings[103336]="我支持首席奥术师！"
D.Strings[103337]="为了塔莉萨！为了起义军！"
D.Strings[103338]="勇士！我听你指挥！"
D.Strings[103339]="来吧。我可不想让她久等。"
D.Strings[103340]="通往我庄园的传送门有人把守。你最好亲自来一趟。"
D.Strings[103341]="我有紧急消息，塔莉萨。"
D.Strings[103342]="让燃烧军团去死！让他们的同党都去死！"
D.Strings[103343]="勇士，我是来向你学习的。"
D.Strings[103344]="希尔格林向你问好。"
D.Strings[103345]="当然了，你得小心点。我感觉到了某种……从未遇到过的陌生存在……"
D.Strings[103346]="我知道。这是既定的宿命。但它现在终于被打破了。"
D.Strings[103347]="只能这样了。我们试过挽救他，但那背后有更大的阴谋。"
D.Strings[103348]="那是什么？别那么做。"
D.Strings[103349]="不要懈怠。你是要保卫你的家园和传承的夜之子。站直了！"
D.Strings[103350]="举起你的武器。举高点儿。要是觉得它太重，那就把自己练得强壮点儿。"
D.Strings[103351]="这也叫战斗姿态？你这副样子，这个营地里任何一个精灵都能撕碎你。"
D.Strings[103352]="不不不。我说了，列队，列队！"
D.Strings[103353]="还是没看到凡瑟尔……"
D.Strings[103354]="我们会找到他的，希尔格林。一定会。"
D.Strings[103355]="没错。大家都上船！可能会有点挤。"
D.Strings[103356]="唔，我得记得经常关掉你。过度使用可能会导致你变得……古怪。"
D.Strings[103357]="激活防御协议。"
D.Strings[103358]="现在，你可以在我离开时主持塔楼的防务了。"
D.Strings[103359]="$n，我们得搞清楚莉莉丝的情况。你还能在城里自由行动，对吧？"
D.Strings[103360]="没错。我有个想法，能把有限的力量在合适的时机投放到合适的地方。"
D.Strings[103361]="欧库勒斯，我们需要弥补援军的损失。"
D.Strings[103362]="没问题。"
D.Strings[103363]="瓦尔托伊，全力破解艾利桑德的法术。"
D.Strings[103364]="我有一阵子没收到她的消息了。这绝对不是巧合。"
D.Strings[103365]="莉莉丝为什么没有警告我们？作为艾利桑德的顾问，她肯定知道些什么！"
D.Strings[103366]="艾利桑德干了什么……这不可能！这需要大量能量——"
D.Strings[103367]="我们的部队都被艾利桑德的谜锁困住了。"
D.Strings[103368]="使用猛禽一击！"
D.Strings[103369]="他会做梦吗？他是不是被困在梦魇里了？"
D.Strings[103370]="他又昏睡了一年。麦迪文还会醒过来吗？"
D.Strings[103371]="后退，奥露乐。我们在等她。"
D.Strings[103372]="噢，可怜的我，太可怜了！我的生活完蛋了！\n\n你认识维维尔博士吗？他以前是博士，现在应该还是吧？天知道。\n\n死亡也阻止不了他，不，他对此早有预料。真是个天才侏儒，疯子都是天才。\n\n从心脏停跳的那一秒起，他植入自己体内的机械就启动了。他的体内充斥着黄水和电流。我不知道这算不算亡灵、炼金工程学，还是……其他什么玩意儿。\n\n当我们听说伟大的维维尔博士要招一个新的实习生，就全涌到这座岛上来报名了。现在，我都不知道自己到底算是活着还是死了。你看我都漏黄水了，真是好极了。\n\n其他人都自称为“苦力侏儒”了。祝他们好运吧，一帮蠢货。"
D.Strings[103373]="我们得立刻讨论一下。我来把你传送去沙尔艾兰。"
D.Strings[103374]="对目标假人使用猛禽一击。"
D.Strings[103375]="猛禽一击的攻击十分迅猛，只要你有足够的集中值就可以使用。"
D.Strings[103376]="现在目标正在流血，你的宠物也已加入战斗，该释放你自己的怒火了。"
D.Strings[103377]="我们还没有派出枯法者的大部队，敌军就崩溃了！继续训练他们吧，将来会派上大用场的。"
D.Strings[103378]="我们可以进攻苏拉玛了。在城市外围放置这些道标，让枯法者直接出现在大魔导师的部队头上！"
D.Strings[103379]="噢，烈酒。对。谢谢你。"
D.Strings[103380]="现在，能抵抗邪能的枯法者更多了。我们的革命绝不会失败！"
D.Strings[103381]="枯法者得为突击暗夜要塞的战斗做好准备。去邪魂堡垒提升他们的邪能抗性吧。"
D.Strings[103382]="多有趣多讽刺啊！看到被他们放逐的人出现在自家门口，那些贵族全都慌了！"
D.Strings[103383]="我准备完毕了。让我们看看苏拉玛的贵族要怎么对付从天而降的枯法者吧！"
D.Strings[103384]="魔网能量又开始流动了！干得好。"
D.Strings[103385]="魔网笼罩了苏拉玛，掩盖了大魔导师军队的动向。用我的眼镜去观察一下，解决干扰的源头！"
D.Strings[103386]="我们得尽快撤退。"
D.Strings[103387]="就是这样，这真是瓶好酒。"
D.Strings[103388]="这些补给对于我们的战役至关重要。部落又能继续前进了！"
D.Strings[103389]="越来越少的补给影响了我们的士气。到苏拉玛去，从夜之子压迫者那里弄些补给来！"
D.Strings[103390]="补给的到来重振了士气。你干得很好！"
D.Strings[103391]="他们把他传送走了。但我不知道他们把他弄到哪儿去了。"
D.Strings[103392]="他们说要用他来给其他人一个警告。"
D.Strings[103393]="他求他们饶了其他人。"
D.Strings[103394]="邪脉部队杀害了所有妨碍他们的人，但没有杀他。"
D.Strings[103395]="我在我的旅店里亲眼看到艾利桑德的部队冲进了残月酒馆。"
D.Strings[103396]="我们快要弹尽粮绝了，但敌人依然粮草充足。到苏拉玛去，从大魔导师的部队那里弄些补给来！"
D.Strings[103397]="一定要让夏多雷知道，混乱之后还有希望。我们得尽量多联络一些人！"
D.Strings[103398]="我们得把部落到来的消息告诉苏拉玛的市民。在城里张贴布告，让被压迫的人民知道援军快来了！"
D.Strings[103399]="起来反抗的夏多雷越多，解放苏拉玛时牺牲的就会越少。"
D.Strings[103400]="我们得把联盟到来的消息散布出去。在城里张贴布告，宣告大魔导师的统治即将结束。鼓励夏多雷起来反抗。"
D.Strings[103401]="他们竟然攻击逃难的同胞？我们要为这种暴行制裁艾利桑德！"
D.Strings[103402]="夏多雷趁艾利桑德的部队开进深红林地时逃出了苏拉玛。去吧，为难民们击溃那些夜之子。"
D.Strings[103403]="昔日骄傲的夏多雷竟然自相残杀？这局面比我想的还要绝望……"
D.Strings[103404]="艾利桑德的部队正在深红林地里伏击逃离苏拉玛的难民。这是个了解他们战斗力的绝佳机会！"
D.Strings[103405]="艾利桑德害死了那么多人，简直罪无可赦。我们必须为拯救同胞而战。"
D.Strings[103406]="艾利桑德和军团强迫平民登上驶向邪魂堡垒的船。挑一艘贡多拉，尽量多救几个夏多雷。"
D.Strings[103407]="艾利桑德攻击月之守卫的行为让我们的人民蒙羞。你维护了他们的传统，帮我们赎了罪。"
D.Strings[103408]="要战胜艾利桑德，需要远超我们自身的力量。登上月光熔炉，寻求月之守卫先贤的祝福吧。"
D.Strings[103409]="我们的秘密暂时……保住了。但这样的威胁恐怕不会是最后一次。"
D.Strings[103410]="军团的巡逻队正在接近沙尔艾兰。干掉他们，别让他们发现我们！"
D.Strings[103411]="要不是你，许多无辜者可能已经横尸街头了。虽然这只是一场小胜，但它很重要。"
D.Strings[103412]="平民都拿起武器保卫苏拉玛各处的避难所了。去找到遇险的无辜者，把他们送去安全地带！"
D.Strings[103413]="父亲！不！"
D.Strings[103414]="这力量……太……强了……"
D.Strings[103415]="别这么软弱！控制住你的魔力！"
D.Strings[103416]="凡瑟尔怎么了，玛瑞贝丝？"
D.Strings[103417]="凡瑟尔有危险！"
D.Strings[103418]="这里不安全。我们得尽快转移。"
D.Strings[103419]="艾利桑德和军团要为欠下的血债付出代价。他们的罪行罄竹难书！"
D.Strings[103420]="艾利桑德和军团的进攻杀害了许多夜之子。反击！让那些恶棍看看，我们绝不向暴君屈服。"
D.Strings[103421]="那就穿过传送门吧！$b$b卡德加还等着呢。"
D.Strings[103422]="多么可悲的伪装！你将为此付出生命的代价！"
D.Strings[103423]="主人，求求你！我不是……"
D.Strings[103424]="你去哪儿了，小废物？$B$B你以为没人盯着你们吗？"
D.Strings[103425]="你们很会伺候人，仆人。"
D.Strings[103426]="滚开，奴隶！"
D.Strings[103427]="虽然我不是士兵，可就算是打仗时，也需要有人铺床递水。$b$b这是我的天职。"
D.Strings[103428]="我准备关闭屏障了。你得赶快行动，在他们反应过来之前夺下入口。"
D.Strings[103429]="我们的人民必将摆脱燃烧军团！"
D.Strings[103430]="我准备好为苏拉玛而战了！"
D.Strings[103431]="我这就去散布消息……大魔导师的暴政到此为止了！"
D.Strings[103432]="暮色卫队不会知道袭击他们的是谁。"
D.Strings[103433]="传送门生效了，我们也没事。很好！我还怕再加个道标网络会过载呢。"
D.Strings[103434]="完全没预见到……这样的结局……"
D.Strings[103435]="可计划……完美无缺……"
D.Strings[103436]="螳臂当车，呵呵，多么可悲。"
D.Strings[103437]="和我预见的一样，那些凡人完蛋了。"
D.Strings[103438]="这座塔归燃烧军团了！"
D.Strings[103439]="我早就预见到了这个世界的毁灭！"
D.Strings[103440]="你们都将……一一倒下！"
D.Strings[103441]="毫无意义……而且不可避免。"
D.Strings[103442]="还剩一场战斗。再征服一个世界，我们的伟大计划就完成了！"
D.Strings[103443]="我们的燃烧远征吞噬了无数世界。这座塔楼将成为连接它们的通道。"
D.Strings[103444]="卡拉赞的能量辐射到了虚空中……就像吸引燃烧军团的明灯。"
D.Strings[103445]="主人！我的任务完成了！来夺取这个世界吧！"
D.Strings[103446]="我们的计划成功了！这座塔楼连通了军团所有的世界！"
D.Strings[103447]="看呐！末日向你们敞开了大门！"
D.Strings[103448]="无穷无尽的大军将从无数世界涌来！"
D.Strings[103449]="准备完毕。启动最后一步！"
D.Strings[103450]="不要抵抗了！我们的伟大计划必须实现。"
D.Strings[103451]="你们抵抗是因为受了蒙蔽。投降吧！"
D.Strings[103452]="你们都将跪拜臣服！"
D.Strings[103453]="消灭目标！"
D.Strings[103454]="你的抵抗毫无意义！"
D.Strings[103455]="烧死那家伙！"
D.Strings[103456]="发动弹幕轰炸！"
D.Strings[103457]="感受熵能的绞杀吧！"
D.Strings[103458]="主人！我……让你失望了。"
D.Strings[103459]="你不该回来的，愚蠢的凡人！你的塔楼归我们了！"
D.Strings[103460]="枯法者坚持不了多久，$n。召集一队精锐勇士杀进去吧。你肯定很熟悉这种战术了！当然，我们会支援你们的。"
D.Strings[103461]="等我们打破困住大军的时空谜锁，古尔丹就死定了！"
D.Strings[103462]="我感应到暗夜井了。艾利桑德肯定是逼急了，竟然将它超载到这种程度！"
D.Strings[103463]="艾利桑德最好的奥术师死了，她恐怕派不出援军了。缺口打开了。跟我走。"
D.Strings[103464]="$n！这边！"
D.Strings[103465]="安达丽斯是他们的防线中枢。大殿里又能使用传送术了。我会把塔莉萨和卡德加送到你那边去。"
D.Strings[103466]="你们都像……守护者……一样堕落……"
D.Strings[103467]="我……绝不……投降……"
D.Strings[103468]="纯净的灵魂才是和平的灵魂。"
D.Strings[103469]="布道结束了。"
D.Strings[103470]="干得好！现在，去找海拉！她的叛乱该结束了！"
D.Strings[103471]="小心，勇士们！有一头从梦魇中孕育出的狂暴野兽守护着海拉的国度。"
D.Strings[103472]="你们身上充满了堕落的臭气！"
D.Strings[103473]="埃提耶什……将被……劈碎……"
D.Strings[103474]="所以……最后……是这样……"
D.Strings[103475]="让我们开始净化吧！"
D.Strings[103476]="我已经……尽力……了……"
D.Strings[103477]="你们不明白我那么做时是什么感觉。很困难，但也很必要。"
D.Strings[103478]="一旦你习惯了，就能像杀害陌生人一样杀害朋友。"
D.Strings[103479]="我的法杖是一件圣物，但它是我的！"
D.Strings[103480]="你们和其他人一样，对吧？"
D.Strings[103481]="你们好，勇士们。我一直在等你们。"
D.Strings[103482]="孺子可教。"
D.Strings[103483]="小偷应得的下场！"
D.Strings[103484]="一切都按计划进行。"
D.Strings[103485]="净化了一个！"
D.Strings[103486]="越来越简单了。"
D.Strings[103487]="你们从未见过真正的麦迪文。"
D.Strings[103488]="这就是我：诞生前就不再洁净，生来就被污染。我是颗注定结出苦果的坏种子。"
D.Strings[103489]="泰坦希望他们的孩子过纯洁的生活。可这座塔从地基到尖顶都散发着堕落的臭气！"
D.Strings[103490]="别动。让它过去。"
D.Strings[103491]="寒冬降临了！"
D.Strings[103492]="我建议你们别动。"
D.Strings[103493]="好烫，好烫，好烫！"
D.Strings[103494]="给秃鹫的腐尸……"
D.Strings[103495]="这么多我的碎片……"
D.Strings[103496]="很基础……但很有效。"
D.Strings[103497]="你变弱了……我变强了！"
D.Strings[103498]="不忏悔……就死！"
D.Strings[103499]="像那头龙一样……燃烧吧！"
D.Strings[103500]="火的固有属性……"
D.Strings[103501]="放弃你们的贪婪和堕落吧！"
D.Strings[103502]="这座塔需要新装饰。"
D.Strings[103503]="冻结在时光中的回忆！"
D.Strings[103504]="站住，凡人！接受美德的洗礼吧！"
D.Strings[103505]="沐浴在圣光中吧，凡人！"
D.Strings[103506]="又是枯法者！我不会辜负艾利桑德的！你们输定了！"
D.Strings[103507]="安达丽斯犯了大错！她的护盾对于枯法者来说正是上等佳肴。派几个枯法者去安全地带，他们会吸干护盾的魔力。"
D.Strings[103508]="我要干掉你们！"
D.Strings[103509]="烈焰……在等着我……"
D.Strings[103510]="我……没法……自由了……"
D.Strings[103511]="还没……完呢……"
D.Strings[103512]="你们把我叫过来，就是为了送死吗？"
D.Strings[103513]="到此为止了！除非我死了，否则你们别想进去！"
D.Strings[103514]="凡人总是不吸取教训。"
D.Strings[103515]="可怜虫……不出我所料。"
D.Strings[103516]="还有谁？！"
D.Strings[103517]="又一份燃料！"
D.Strings[103518]="来吧！燃烧吧！"
D.Strings[103519]="把你们挫骨扬灰！"
D.Strings[103520]="了解痛苦的含义吧！"
D.Strings[103521]="那好吧！这份傲慢会让你们吃苦头的！"
D.Strings[103522]="难道我注定要永世听从凡人的召唤吗？"
D.Strings[103523]="够了！我要亲手了结你们！"
D.Strings[103524]="你的意志动摇了！"
D.Strings[103525]="怯懦的凡人！"
D.Strings[103526]="跑吧，胆小鬼！"
D.Strings[103527]="你的生命之血就是我的武器！"
D.Strings[103528]="火从心起！"
D.Strings[103529]="你的灵魂背叛了你的盟友！"
D.Strings[103530]="正义无所畏惧！"
D.Strings[103531]="让烈焰净化你们！"
D.Strings[103532]="强者必须为弱者的罪而受难！"
D.Strings[103533]="我将净化一切！"
D.Strings[103534]="安达丽斯的走狗倒下了，你可以进去了。去突破口！"
D.Strings[103535]="那边！那些施法者在用发生器保护大殿。消灭他们！"
D.Strings[103536]="看来你进不去了。去找到那个屏障的能量源并关闭它。"
D.Strings[103537]="没错。看来只能这样了……"
D.Strings[103538]="我可不想默默地死掉。"
D.Strings[103539]="哪怕只是说说，卫兵都会砍掉我们的头……"
D.Strings[103540]="我受够这种压迫了。我们要采取行动！"
D.Strings[103541]="我们早做好被发现的准备了。有了传送宝珠和抵抗邪能的枯法者，你有足够的手段打开突破口。"
D.Strings[103542]="我不明白他们怎么篡改了我的法术，这不——"
D.Strings[103543]="你以为这很隐蔽？！在真正的法术面前，你的老把戏不值一提！"
D.Strings[103544]="我的法术！出什么事了？！"
D.Strings[103545]="我们引以为傲的城市，陷入了混乱……可我们得到了什么？"
D.Strings[103546]="我受够燃烧军团了！我们有反抗的能力！"
D.Strings[103547]="大魔导师太过分了。"
D.Strings[103548]="他们抓走了我的女儿……我得做点什么。"
D.Strings[103549]="难道我们夏多雷就没有一点血性吗？"
D.Strings[103550]="我不想再忍受这种待遇了！"
D.Strings[103551]="来吧，勇士。肯瑞托和暮色百合的起义军已经占领了这层港口。"
D.Strings[103552]="真厉害。等战争结束后，我们得交流交流。"
D.Strings[103553]="呃，其实……我还有帮手。"
D.Strings[103554]="一整座城市？一下就传送走了？"
D.Strings[103555]="刚好赶上下一班渡船。它会带你们去灵魂引擎的！"
D.Strings[103556]="决不能让凡人破坏我们的伟大计划！"
D.Strings[103557]="我来帮你争取时间，监视者。"
D.Strings[103558]="武装起来的人民就能抵抗艾利桑德的暴徒了！"
D.Strings[103559]="平民们渴望摆脱艾利桑德的暴政。我们得把他们武装起来。"
D.Strings[103560]="勇士，跟我的辛多雷一起击溃敌军的先锋。"
D.Strings[103561]="时间有限。勇士，快上坐骑，跟我们一起去广场，别让夜之子稳住阵脚。"
D.Strings[103562]="去吧。我们会守住阵地，派出援军。"
D.Strings[103563]="多么脆弱的骨头，小蛆虫。它们太容易碎了！"
D.Strings[103564]="动起来，否则我就砍掉你的脑袋！"
D.Strings[103565]="我要把你像虫子一样碾碎！"
D.Strings[103566]="别挡路，蛆虫！"
D.Strings[103567]="小东西！我要碾碎你！"
D.Strings[103568]="没用的废物！继续干活儿！"
D.Strings[103569]="别碰我，渣滓！回去干活！"
D.Strings[103570]="你来迟了，小东西！"
D.Strings[103571]="现在，我们只需要联系——"
D.Strings[103572]="保护这些人逃出城市，德琳。$n，你跟我走。"
D.Strings[103573]="啊……平台。那里应该很合适。尽量跟上我们，德琳。"
D.Strings[103574]="我这个法术维持不了多久。到永月平台来见我，然后我们再继续。"
D.Strings[103575]="很好。这样就能找到他了。"
D.Strings[103576]="他的某个供应商肯定在这里招待过他。让他想起了单纯的时光。"
D.Strings[103577]="我感应到他了！至少他还活着。"
D.Strings[103578]="他肯定在这座花园里消磨了不少时光。在这里，他的精华很明亮。"
D.Strings[103579]="在那边。我们来了，凡瑟尔。"
D.Strings[103580]="他肯定在这里吃过许多顿饭……"
D.Strings[103581]="你的行为不合逻辑。我已经计算出了这场战斗所有可能的结果。"
D.Strings[103582]="这里变了……喧闹的人群消失了，换成了全副武装的卫兵。"
D.Strings[103583]="我制止不了他们。对不起，苏拉玛。"
D.Strings[103584]="这些恶魔可真不见外。恶心！"
D.Strings[103585]="我的同胞……被关着！有些都变成枯法者了。艾利桑德真是太残酷了。"
D.Strings[103586]="噢，苏拉玛……"
D.Strings[103587]="这里以前很热闹的。他们都去哪儿了？"
D.Strings[103588]="我现在有点……不舒服……"
D.Strings[103589]="噢，天呐！这会……留疤的。"
D.Strings[103590]="我需要……一点时间……"
D.Strings[103591]="一把锯屑下去，什么都解决了。"
D.Strings[103592]="我这就让清洁工来……打扫。"
D.Strings[103593]="唔！看来这家伙酒足饭饱了。"
D.Strings[103594]="我要把你扔出去！"
D.Strings[103595]="请不要无理取闹！"
D.Strings[103596]="请出示你的请柬！"
D.Strings[103597]="我看错他们了吗？但愿没有……"
D.Strings[103598]="真让人失望！"
D.Strings[103599]="站起来！战斗！"
D.Strings[103600]="训练那些枯法者人渣……真恶心！达里昂，守住入口！干掉敌人！"
D.Strings[103601]="这些凡人很有潜力。"
D.Strings[103602]="海拉可不会像我这么温柔！"
D.Strings[103603]="打得好，勇士们！我认输。"
D.Strings[103604]="那家伙太软弱了！"
D.Strings[103605]="和我想的一样弱！"
D.Strings[103606]="你已经……太…… 迟了……"
D.Strings[103607]="惊人的弱点！"
D.Strings[103608]="感受风暴之怒吧！"
D.Strings[103609]="你们能抵挡守护者的力量吗？"
D.Strings[103610]="见证泰坦赐予我的力量吧！"
D.Strings[103611]="符文使者！为我补充能量！"
D.Strings[103612]="瓦拉加尔！准备符文！我们考验考验这些英雄……"
D.Strings[103613]="如果你们愿意去结束她的统治，那就开口吧，我马上就派你们上前线！"
D.Strings[103614]="你们的心中真有勇气存在吗？"
D.Strings[103615]="只有懦夫才会害怕战斗！"
D.Strings[103616]="不想死的都站一起！"
D.Strings[103617]="排好队！"
D.Strings[103618]="那好吧！废物都将被赶出英灵殿！"
D.Strings[103619]="不用！我得确认他们能应对未来的任务。"
D.Strings[103620]="需要我们手下留情吗，奥丁？"
D.Strings[103621]="我们绝不向燃烧军团低头。"
D.Strings[103622]="真的吗？我们可以摆脱暗夜井？"
D.Strings[103623]="我得在更多卫兵赶来之前离开了。"
D.Strings[103624]="道路安全了？谢谢你，朋友。"
D.Strings[103625]="我相信暮色百合。"
D.Strings[103626]="海拉狗急跳墙了……她快完蛋了！"
D.Strings[103627]="克瓦迪尔在威胁可怜的村民？卑鄙！把那些懦夫赶回深海里去！"
D.Strings[103628]="决定性的胜利！那个海女巫高估了自己。"
D.Strings[103629]="海拉该死的魔法威胁到了至高岭。决不能让她完成仪式！"
D.Strings[103630]="本周到此为止，诸位！钓鱼大赛结束！"
D.Strings[103631]="赛程已经过半，剩余的奖品不多了。继续挥舞你们的鱼钩吧！"
D.Strings[103632]="第一名出现了！恭喜！恭喜！"
D.Strings[103633]="恭喜，你赢得了荆棘谷钓鱼大赛！将来你可以把这个荣耀说给你的孙辈听。噢，嘿……谢谢你的鱼！"
D.Strings[103634]="嘿，伙计！今天我们要举行一场钓鱼高手的比赛！你只要成为全世界前五十个为我带来大量美味可口鱼的人就赢了。现在，把你的鱼竿甩起来吧！"
D.Strings[103635]="我会找到他的。而且不会被发现。"
D.Strings[103636]="|TInterface\\Icons\\SPELL_SHADOW_SHADOWANDFLAME:20|t%s正在对|cFFFF0000$n|r施放|cFFFF0000|Hspell:228796|h[燃魂]|h|r！"
D.Strings[103637]="记住，$n，虽然你看起来像是他们的同类，但他们可能不会迅速接纳你。小心点。"
D.Strings[103638]="|TInterface\\Icons\\spell_fire_felfire.blp:20|t%s将|cFFFF0000$n|r选为了|cFFFF0000|Hspell:229242|h[邪能光束]的目标|h|r！"
D.Strings[103639]="什么传言？"
D.Strings[103640]="我不能久留，王宫里还有人等着我。我们得快一点。"
D.Strings[103641]="都来拿一瓶魔力酒吧！把它带给你们的家人！"
D.Strings[103642]="都出来吧！起义军为大家带来了魔力酒！"
D.Strings[103643]="啊，审讯员来了。你最好把知道的都告诉$G他:她;，恶魔！"
D.Strings[103644]="小心点，$n。虽然这个瓶子上有额外的防护措施，但它只能承受这么大的力量。"
D.Strings[103645]="让海浪碾碎你！"
D.Strings[103646]="我要给你一个飞吻！"
D.Strings[103647]="深呼吸……感受绝望！"
D.Strings[103648]="拥抱冰冷的死亡吧！"
D.Strings[103649]="让寒意撕碎你！"
D.Strings[103650]="迷雾带来了你的末日！"
D.Strings[103651]="看着，我的亡者大军！"
D.Strings[103652]="你们的努力毫无意义，凡人！奥丁休想脱身！"
D.Strings[103653]="你们很快就会加入我的克瓦迪尔了！"
D.Strings[103654]="你注意到我了吗？"
D.Strings[103655]="麻烦，真麻烦！"
D.Strings[103656]="品味大海的冰冷之吻吧！"
D.Strings[103657]="颤抖吧！战栗吧！动摇吧！"
D.Strings[103658]="让黑暗笼罩你的灵魂！"
D.Strings[103659]="让暗影带走你！"
D.Strings[103660]="他……别想……赢我……"
D.Strings[103661]="我诅咒你……奥丁……诅咒……你……"
D.Strings[103662]="我的统治……不会终结……"
D.Strings[103663]="英灵殿很快就会陨落。奥丁的末日已经降临了！"
D.Strings[103664]="奥丁的传奇勇士……哈！不值一提。"
D.Strings[103665]="啊，看，又一个囚犯！"
D.Strings[103666]="让他们排好队！"
D.Strings[103667]="女主人在塔底深处。$B$B女主人总是很忙，但还是会抽时间来见瑞兹尔。$B$B现在……瑞兹尔不敢回去了！万一女主人以为瑞兹尔叛变了怎么办？"
D.Strings[103668]="你说的这个主人在哪儿？"
D.Strings[103669]="溺死在绝望中吧，奥丁的走狗！"
D.Strings[103670]="我的！永远都是我的！"
D.Strings[103671]="又一条溺水的灵魂！"
D.Strings[103672]="来吧，凡人。你们赢得了永恒的折磨！"
D.Strings[103673]="感谢你们把自己的灵魂送上门来……省得我的瓦格里再去地表世界抓你们了。"
D.Strings[103674]="噢，不……奥丁强大的勇士们来摧毁我的王国了。我该怎么办？"
D.Strings[103675]="我们必须合力完成仪式……直到实现海拉的意志！"
D.Strings[103676]="|TInterface\\Icons\\INV_Icon_ShadowCouncilOrb_green.blp:20|t一颗|cFFFF0000|Hspell:228058\n|h[腐化宝珠]|h|r在追踪你！"
D.Strings[103677]="|TInterface\\Icons\\INV_Icon_ShadowCouncilOrb_purple.blp:20|t一颗|cFFFF0000|Hspell:227920|h[腐蚀宝珠]|h|r在追踪你！"
D.Strings[103678]="我得救了……谢谢你！"
D.Strings[103679]="帮帮我！卫兵抢走了我的一切！"
D.Strings[103680]="这边……我好几天没喝过魔力酒了！"
D.Strings[103681]="求求你，分我一口魔力酒……我有孩子！"
D.Strings[103682]="那好吧。我会警告我们在城内的部队。对于被我们忽略的世界，我还有很多东西要学。"
D.Strings[103683]="城里还有一些盲目追随大魔导师的夜之子。我们得小心点，不能误伤任何无辜者！"
D.Strings[103684]="而夏多雷远比你们想的强大。当时机来临，我们会与你并肩战斗。"
D.Strings[103685]="起义军可以战斗了？了不起。让我们看看他们的本事吧。"
D.Strings[103686]="就算遭到大魔导师的打压，我们也不能忘了自己的同胞。他们是起义军的支柱。"
D.Strings[103687]="你们的领袖应该理智一点。$b$b温蕾萨太过执着于向部落复仇，我们根本不敢把自己的侧翼托付给她。$b$b泰兰德是个哨兵。她对这种战斗毫无经验。虽然她的侦查报告很有用，但她应该把卡多雷从前线上撤下来。$b$b我的血骑士才是攻坚的主力。"
D.Strings[103688]="辛多雷是最理解堕夜精灵困境的人。我非常同情他们。$b$b可塔莉萨必须明白，叛乱和战争不是一回事。$b$b到目前为止，她的起义军只经历过几场零星冲突。他们没有像我们血精灵一样接受过血与火的洗礼。"
D.Strings[103689]="很好。我们的人手不足以长期占领这里。发兵速度越快越好。"
D.Strings[103690]="我要郑重声明，我反对在这次战争中相信任何一个部落成员。由于部落的背叛，我失去了我的丈夫和我的国王。$b$b我看不出还有什么理由继续相信你们。"
D.Strings[103691]="我从没想过自己会和卡多雷分享一片营地。但非常时期只有采取非常手段了。"
D.Strings[103692]="我得跟你谈谈，勇士。尽快来见我吧。"
D.Strings[103693]="大魔导师的暴徒在妨碍德琳分发魔力酒。去运河上找她，保护她顺利完成任务吧。"
D.Strings[103694]="该向我出生的城市发兵了。愿艾露恩帮助我们尽快结束这场冲突。"
D.Strings[103695]="来自塔莉萨的计划。"
D.Strings[103696]="苏拉玛。我出生在这里。一万年来，我从没想过自己会带着一支大军回到这里，从曾经保护我的那些精灵手中夺取它。"
D.Strings[103697]="我让你拿走艾露恩之泪时，还以为我们下面见面应该就是在与燃烧军团决战的战场上了。$b$b我没想到你会和一群魔瘾患者出现在我出生的城市脚下。$b$b有话快说，$r。我没心情听塔莉萨的请愿。"
D.Strings[103698]="有话快说，$r。我可不想让你在我的营地里逗留。$b$b你的部落让我的一位好友死在了破碎海滩上。你应该庆幸我们目前还有共同的敌人。"
D.Strings[103699]="好好教训那些恶魔。"
D.Strings[103700]="动作快点儿，朋友。"
D.Strings[103701]="我们会守住阵线的！"
D.Strings[103702]="别浪费了这些灵魂。把他们送走！"
D.Strings[103703]="苏拉玛还在不断送人来！快走！腾出位置！"
D.Strings[103704]="我们可不能让灵魂引擎久等！"
D.Strings[103705]="都跟上！灵魂引擎还等着呢！"
D.Strings[103706]="不要松开他们的锁链！"
D.Strings[103707]="我们表明了自己的立场。海拉加尔休想来占便宜。"
D.Strings[103708]="克瓦迪尔的臭气污染了阿苏纳的海岸！把他们赶回海里去！"
D.Strings[103709]="啊，这下好多了。你害我们担心了好久。"
D.Strings[103710]="提查尔！集中精神！"
D.Strings[103711]="我们需要一处据点，一个能观察局势的地方。"
D.Strings[103712]="灵魂引擎有燃料了！Kar Dan'Ashj！"
D.Strings[103713]="通往邪魂堡垒的通道开启了。把我们的囚犯送过去吧。"
D.Strings[103714]="夜之子已经同意交出多余的贫民了。"
D.Strings[103715]="|TInterface\\Icons\\inv_misc_monsterhorn_03.blp:20|t一头%s出现在海拉的附近！"
D.Strings[103716]="|TInterface\\Icons\\INV_Polearm_2H_OdynSpear_D_01.blp:20|t奥丁的|cFFFF0404|Hspell:228918|h[雷铸之矛]|h|r瞄准了你！"
D.Strings[103717]="邪魂堡垒……她彻底背叛了我们，这真是糟透了。"
D.Strings[103718]="|TINTERFACE\\ICONS\\SPELL_SHAMAN_IMPROVEDFIRENOVA:20|t麦迪文之影开始施放|cFFF00000|Hspell:228269|h[烈焰花环]|h|r！"
D.Strings[103719]="但眼下，我们需要联手。"
D.Strings[103720]="这种反应也不算过激。通常来说，我应该杀掉你们俩。"
D.Strings[103721]="|TInterface\\Icons\\INV_Misc_Horn_03:20|t海姆达尔开始吹响|cFFFF0404|Hspell:228012|h[勇气号角]|h|r！"
D.Strings[103722]="你的灌魔之瓶发出柔和的光芒，并微微发热。"
D.Strings[103723]="奥图鲁斯，小心！噢，是你吗，$n？你的样子……有点不一样了。"
D.Strings[103724]="这边，$n！我和大法师蕾尔达会尽力拖住他们的，但你得快一点！"
D.Strings[103725]="感谢你能来。我们是来讨论大家的共同利益的。"
D.Strings[103726]="塔莉萨，你熟悉敌情，这很重要。我们会在需要时召唤你的。"
D.Strings[103727]="我们有共同的目标。我们必须不惜一切代价阻止燃烧军团和古尔丹。"
D.Strings[103728]="我们的魔瘾是可以治愈的，但普及还需要一点时间。首先，我们得推翻艾利桑德，将军团赶出苏拉玛。"
D.Strings[103729]="让我们一起努力。辛多雷会制裁我们的敌人。"
D.Strings[103730]="我理解堕夜精灵的困境，我感同身受，首席奥术师。魔瘾……背叛……"
D.Strings[103731]="如果你坚持的话，那好吧。战争结束后，我的人民还需要盟友。显然你们不会是其中之一。"
D.Strings[103732]="我们不想做暗夜井的奴隶。我们想把军团赶出苏拉玛，并结束艾利桑德的高压统治。"
D.Strings[103733]="我们知道艾利桑德的道路会通向何方，并请求你们帮忙推翻她的统治。"
D.Strings[103734]="我们凭什么相信，等到击败你的对手之后，你不会为了暗夜井的魔力背叛我们，成为下一个艾利桑德……下一个艾萨拉？"
D.Strings[103735]="卡多雷愿意为击败军团、摧毁暗夜井而战。除此之外……就全赖艾露恩的智慧指引了。"
D.Strings[103736]="挪挪椅子都坐舒服，这场戏叫——魔法坏女巫！"
D.Strings[103737]="有个坏蛋锁起了所有的猢狲，她本来并不必管我们。"
D.Strings[103738]="讨厌的小鬼！别妨碍我们的干活！"
D.Strings[103739]="别来惹我们，废物！"
D.Strings[103740]="我和拉苏尔从小就认识。我们共同度过了生命中最美好的时光。"
D.Strings[103741]="那个女巫必须为她的背叛付出代价！"
D.Strings[103742]="我受够那个邪恶女巫的把戏了！"
D.Strings[103743]="必须阻止海拉。清算的时候到了！"
D.Strings[103744]="海拉的邪恶魔法囚禁了奥丁和瓦拉加尔。我们需要你这样的勇士来阻止她前进。"
D.Strings[103745]="我怀疑那个海女巫已经忍不住了，她正急于发动征服破碎群岛的战役。"
D.Strings[103746]="你……太迟了……"
D.Strings[103747]="海拉在召唤！"
D.Strings[103748]="全体报到！我们要启程了！"
D.Strings[103749]="再加把劲，否则我就把你们扔进水里去！"
D.Strings[103750]="就让这次失败的起义给所有反抗夏多雷的人一个教训吧！"
D.Strings[103751]="但苏拉玛会记住！我们是夜之子，最后的、真正的精灵。而你们只是昔日辉煌的拙劣遗孑。"
D.Strings[103752]="你们都贬低了自己高贵的血脉，你们都忘了我们与生俱来的古老力量。"
D.Strings[103753]="辛多雷？在所有精灵中，我以为你们最能理解我为拯救人民做出的选择。但你们却和废物和怪胎勾结了起来。"
D.Strings[103754]="奎尔多雷？一群沐猴而冠的暴发户，和低等种族通婚已经稀释了你们的血脉。你们配不上高等精灵之名。"
D.Strings[103755]="卡多雷？你们玷污了我们光辉的历史，躲在树林里，假作虔诚。你们已经跟森林里的巨魔一样野蛮了。"
D.Strings[103756]="这就是叛军的靠山，一群乌合之众。"
D.Strings[103757]="外来者，你能听见吗？外来者？我要传送一个道标过去！"
D.Strings[103758]="父、父亲……快跑……"
D.Strings[103759]="起来！我们得走了！"
D.Strings[103760]="我知道沙尔艾兰在哪儿。来吧，女士们。城里已经不安全了。"
D.Strings[103761]="我告诉他别过来了。"
D.Strings[103762]="%s对恶魔的尸体吐了一口口水。"
D.Strings[103763]="噢，谢谢你！这件杰作比我的生命还珍贵百倍。"
D.Strings[103764]="主人的花瓶呢？哪里去了？"
D.Strings[103765]="谢天谢地……你们都没事。来吧，我们离开这儿！"
D.Strings[103766]="布丽吉特？埃米尔？！你们在哪儿？"
D.Strings[103767]="艾利桑德知道凡瑟尔与叛军有关。他失踪了。"
D.Strings[103768]="已经太晚了。他们抓走了……凡瑟尔……"
D.Strings[103769]="别磨蹭。快上传送台。"
D.Strings[103770]="海拉能腐蚀雷铸勇士！"
D.Strings[103771]="她竟敢公开反抗我！"
D.Strings[103772]="看到主人倒下，午夜彻底愤怒了！"
D.Strings[103773]="海拉抢走了那些瓦拉加尔的灵魂？不可能！打倒她的秘术师，然后回来见我。"
D.Strings[103774]="这太过分了……就算被当成叛徒，我也认了！"
D.Strings[103775]="必须阻止艾利桑德！"
D.Strings[103776]="相信别人也有同感！我不会再充当艾利桑德的刽子手了！"
D.Strings[103777]="恶魔来的时候，我保持了沉默，可这……这太可怕了。"
D.Strings[103778]="我不敢相信，艾利桑德竟然对她的人民做这种事。我要反击！"
D.Strings[103779]="我还以为就我这么想……我支持暮色百合！"
D.Strings[103780]="你竟敢到这儿来？去死吧，恶棍！"
D.Strings[103781]="杀了你，艾利桑德一定会嘉奖我的！"
D.Strings[103782]="叛徒！我要杀了你！"
D.Strings[103783]="你跟他们是一伙儿的！去死吧，闯入者！"
D.Strings[103784]="多年来，海拉一直在组建大军。窃取阵亡维库人的灵魂对抗瓦拉加尔。"
D.Strings[103785]="软弱是不可饶恕的罪过。"
D.Strings[103786]="|TInterface\\Icons\\SPELL_SHADOW_LIFEDRAIN02:20|t%s开始对|cFFFF0000$n|r施放|cFFFF0000|Hspell:228835|h[吸收活力]|h|r！"
D.Strings[103787]="|TInterface\\Icons\\achievement_dungeon_MawofSouls.blp:20|t浓雾涌入了海湾……"
D.Strings[103788]="|TInterface\\Icons\\SPELL_SHAMAN_TIDALWAVES.BLP:20|t%s正在召唤|cFFFF0000|Hspell:228300|h[巨喉之怒]|h|r。快到高地上去！"
D.Strings[103789]="注意你的风度！"
D.Strings[103790]="你必须穿礼服赴宴！"
D.Strings[103791]="主人……但愿你……喜欢……我的服务……"
D.Strings[103792]="卫兵们真该好好工作了，连无赖都放进来了。"
D.Strings[103793]="清洁单位：开始打扫展览馆。"
D.Strings[103794]="主人已经不对劲很久了。但愿一场宴会能让他打起精神来！"
D.Strings[103795]="威慑协议成功生效。"
D.Strings[103796]="我最讨厌不速之客了！"
D.Strings[103797]="威慑模式已激活！"
D.Strings[103798]="部署反制措施。"
D.Strings[103799]="系统……即将……崩溃……"
D.Strings[103800]="欢迎来到——你们的末日！"
D.Strings[103801]="表现不错，老朋友！来吃点燕麦吧。"
D.Strings[103802]="我……漫长的狩猎……结束了。"
D.Strings[103803]="现在，我们狩猎只为取乐和屠杀的荣耀！"
D.Strings[103804]="啊，忠实的午夜。我们并肩狩猎多年，为主人供应了无数食物。"
D.Strings[103805]="我诅咒……你们这些……旁观者……"
D.Strings[103806]="有些人并非……天生……邪恶……"
D.Strings[103807]="如果你把我当朋友，就让那些猢狲赶走入侵者……然后我们就去见巫师！"
D.Strings[103808]="没人会为……坏女巫……难过……"
D.Strings[103809]="真的是你！亲爱的，我们再也不分开了！"
D.Strings[103810]="贝拉……是我！"
D.Strings[103811]="<喘气>你是谁？！"
D.Strings[103812]="已经……太……迟了……"
D.Strings[103813]="不！那些晚餐……还有图书馆……噢，布鲁特，我爱你！"
D.Strings[103814]="这诅咒……在扼杀我……"
D.Strings[103815]="成功了！成功了！"
D.Strings[103816]="噢，我最喜欢书了！"
D.Strings[103817]="好吧。嘿，你喜欢书吗？"
D.Strings[103818]="你又来了！"
D.Strings[103819]="我才没“整天”嚷嚷呢。你干嘛老这么说？！"
D.Strings[103820]="只要你别整天嚷嚷，我就不逃跑。"
D.Strings[103821]="噢，不不……这不行！这些外来者会毁掉解除诅咒的最后机会！"
D.Strings[103822]="很好！那你就饿死吧！"
D.Strings[103823]="绝不！我才不会跟你这种野人用餐！"
D.Strings[103824]="我是这座城堡的主人！我们将一起用晚餐！"
D.Strings[103825]="只有美……才能杀掉……野蛮……"
D.Strings[103826]="叫你勾引我的男朋友！"
D.Strings[103827]="事情不太顺利，对吧？"
D.Strings[103828]="看来我要……睡……碗柜了。"
D.Strings[103829]="但愿我没让你倒胃口，亲爱的！"
D.Strings[103830]="真爱的蜡烛在熊熊燃烧！"
D.Strings[103831]="快点！解决他们！"
D.Strings[103832]="不要……拿走……蜡烛……"
D.Strings[103833]="蜡烛是我的！"
D.Strings[103834]="看来……我的玫瑰……凋谢了……"
D.Strings[103835]="不要阻挡真爱！"
D.Strings[103836]="真好！晚餐又少了一个客人！"
D.Strings[103837]="鲁米诺尔！考德隆夫人！巴布丽特！让我们跟这些入侵者同归于尽！"
D.Strings[103838]="亲眼见证可怕的外表下是否会盛开爱情的玫瑰吧！现在……演出开始！"
D.Strings[103839]="美丽的贝拉会爱上野蛮的布鲁特吗？可怕的诅咒会夺走王子和仆人们的生命吗？"
D.Strings[103840]="今晚……将上演爱情与愤怒的传奇，它将再次证明，美不是肤浅的东西。"
D.Strings[103841]="晚上好，女士们先生们。欢迎各位前来观看今晚的演出！"
D.Strings[103842]="你最好赶快把真相说出来，瑞兹尔！"
D.Strings[103843]="很好，接着说。"
D.Strings[103844]="<瑞兹尔又往他脚下的石头边缩了缩。>$B$B别打瑞兹尔！如果朋友伤害了瑞兹尔，瑞兹尔就帮不了朋友了。$B$B瑞兹尔知道怎么帮朋友！"
D.Strings[103845]="女主人下令把凡人挡在塔外。她的主人要用这座塔搞个非常大的魔法。在燃烧军团，每个主人都有主人！"
D.Strings[103846]="你已经没用了，恶魔！"
D.Strings[103847]="我没时间陪你玩！把你主子的事都交代出来。"
D.Strings[103848]="对……对！瑞兹尔是个好仆人！瑞兹尔的主人是……$B$B<恶魔紧张地看了看四周。>"
D.Strings[103849]="这么说，你是个仆人？"
D.Strings[103850]="瑞兹尔不懂魔法，朋友。瑞兹尔只是个跑腿的！$B$B如果瑞兹尔懂魔法，就不用帮女主人收集样本了……$B$B<傻笑。>$B$B瑞兹尔可以自己创造魔法。"
D.Strings[103851]="魔法？什么魔法？"
D.Strings[103852]="瑞兹尔只是奉命行事！$B$B瑞兹尔只是在收集魔法样本。"
D.Strings[103853]="午夜站不稳了，猎手开始徒步作战！"
D.Strings[103854]="我为什么要饶你一命，恶魔？"
D.Strings[103855]="<哼哼唧唧，口齿含糊不清。>$B$B不！朋友不能伤害瑞兹尔！"
D.Strings[103856]="这头猎犬咆哮着。"
D.Strings[103857]="这头猎犬盯着你所在的方向。"
D.Strings[103858]="这头猎犬激动地嗅着空气。"
D.Strings[103859]="跑起来，午夜！为了胜利！"
D.Strings[103860]="该直面我的猎物了！"
D.Strings[103861]="我的猎物别想逃！"
D.Strings[103862]="列队！冲锋！"
D.Strings[103863]="我……成了……猎物。"
D.Strings[103864]="站起来吧，午夜！把他们踏成肉泥！"
D.Strings[103865]="他们毫无胜算！我是以此为生的！"
D.Strings[103866]="又能多一件战利品了！"
D.Strings[103867]="很好，很好！又来了一群盗马贼！"
D.Strings[103868]="我绝不……停止……玛吉亚……"
D.Strings[103869]="我帮你们挖好坟墓了！"
D.Strings[103870]="没有地盘的黑帮不值一提！"
D.Strings[103871]="继续……滚开！"
D.Strings[103872]="来跳舞吧！"
D.Strings[103873]="看来你们想跳舞，是吗？"
D.Strings[103874]="让我们一起对抗世界吧，宝贝！"
D.Strings[103875]="我只是想……耍个帅。"
D.Strings[103876]="这才叫劲歌热舞！"
D.Strings[103877]="想出去兜兜风吗？"
D.Strings[103878]="当爱情之歌响彻原野，他们能否终成眷属……还是以悲剧告终？现在……演出开始！"
D.Strings[103879]="被世仇隔离的两人结合了，让他们走到一起的是舞蹈……和暴力！"
D.Strings[103880]="今天……我们将认识一对分属哨兵岭敌对双方的有情人。"
D.Strings[103881]="女士们先生们，欢迎各位前来观看今晚的演出！"
D.Strings[103882]="别再骚扰主人的客人了！"
D.Strings[103883]="让我帮你拿外套吧！"
D.Strings[103884]="你们或许更适合去儿童桌。"
D.Strings[103885]="主人肯定没请过你！"
D.Strings[103886]="快给威利治疗！他太苍白了……噢，好吧，侏儒都很苍白。"
D.Strings[103887]="你看见了吗？！一团乱跑的史诗级雾气！还很恶心！"
D.Strings[103888]="噢！真粗鲁！我有点恶心。"
D.Strings[103889]="你是个幸运的家伙！当然，我需要一点你的脑组织……"
D.Strings[103890]="你们愿意深入冥狱深渊去斩杀海拉吗？"
D.Strings[103891]="我愿意以你的名义向她宣战，奥丁！"
D.Strings[103892]="燃烧军团的到来并不奇怪。这座塔下的能量在你我出生前就早已存在。$B$B我们落到如今这步田地确实不幸，但恐怕这一切本来就迟早都会发生。"
D.Strings[103893]="|TInterface\\Icons\\spell_mage_infernoblast:20|t你成为了|cFFF00000|Hspell:227615|h[炼狱箭]|h|r的目标！"
D.Strings[103894]="对目标假人使用鱼叉猛刺。"
D.Strings[103895]="裂痕可以让你的目标流血，对他们造成持续伤害。"
D.Strings[103896]="对目标假人使用裂痕。"
D.Strings[103897]="只要目标身上的裂痕效果消失，你就要及时补上。"
D.Strings[103898]="现在，该围殴你的目标了！"
D.Strings[103899]="侧翼打击要求你和你的宠物协同攻击，伤害很高。"
D.Strings[103900]="对目标假人使用侧翼打击。"
D.Strings[103901]="猫鼬撕咬是一种越用越强的攻击手段。"
D.Strings[103902]="累积猫鼬撕咬的层数，然后一次性将其释放以达到最大效果。"
D.Strings[103903]="对目标假人使用猫鼬撕咬。"
D.Strings[103904]="使用削凿同时攻击多名敌人！"
D.Strings[103905]="使用假死逃脱！"
D.Strings[103906]="使用侧翼打击！"
D.Strings[103907]="使用鱼叉猛刺！"
D.Strings[103908]="使用裂痕！"
D.Strings[103909]="使用猫鼬撕咬！"
D.Strings[103910]="生存猎人擅长近身格斗，能够使用各种手段凶猛地打倒猎物。"
D.Strings[103911]="有时你会发现自己被敌人包围了。别担心，你可以同时消灭一群敌人！"
D.Strings[103912]="削凿能让你用武器横扫面前的敌人，对所有目标造成伤害。"
D.Strings[103913]="使用削凿消灭所有的敌人。"
D.Strings[103914]="时间太紧了！我没法在这种环境下工作！"
D.Strings[103915]="这样下去的话，我们就需要更多的颜料了。"
D.Strings[103916]="使用萨满之怒！"
D.Strings[103917]="游客请注意：死吧！死吧！死吧！"
D.Strings[103918]="消灭一个！"
D.Strings[103919]="正在过载。准备——净化！净化！净化！"
D.Strings[103920]="馆长要……停止运转了。"
D.Strings[103921]="展览馆的目标是——消灭！消灭！"
D.Strings[103922]="|TInterface\\Icons\\ability_bossfelmagnaron_rune.blp:20|t奥丁开始从符文中|cFFFF0404|Hspell:227503|h[吸取能量]|h|r！"
D.Strings[103923]="真是难以置信。你不是开玩笑的吧？"
D.Strings[103924]="我知道，前所未有的事情发生了，一定是这样。不，这样说还不够。"
D.Strings[103925]="还是我们以前见过？"
D.Strings[103926]="你不会把我当成别人了吧？"
D.Strings[103927]="够了！你们证明了自己！有你们这些勇士，海拉必将败亡，而我也终于能够摆脱诅咒了。"
D.Strings[103928]="我没有朋友……当然，除了你，嘉琳黛尔。"
D.Strings[103929]="我们都有飞翔的权利！嘿，你说巫师真能把我变白吗？"
D.Strings[103930]="当然，亲爱的！虽然你那条旧裙子……噢，看！有新朋友来拜访我们了。"
D.Strings[103931]="艾尔菲拉，快下来！别像那些可怕的猴子一样飞来飞去！"
D.Strings[103932]="开始战斗吧，英雄们！"
D.Strings[103933]="海姆达尔！赫娅！考验一下这些凡人的勇士。我得确认他们有足够的勇气和能力应对之后的战斗。"
D.Strings[103934]="勇士们！海拉的爪牙已经血流成河！该进入冥狱深渊，终结那个女巫的黑暗统治了。但是……还有最后一个挑战！"
D.Strings[103935]="目前看来……还不错！但我要亲自考验一下你们！"
D.Strings[103936]="看来我太温柔了。攻击他们！"
D.Strings[103937]="|TInterface\\Icons\\Spell_Holy_PrayerOfHealing:20|t%s正在施放|cFFFF0000|Hspell:227508|h[群体忏悔]|h|r！"
D.Strings[103938]="|TInterface\\Icons\\Spell_Holy_InnerFire:20|t%s正在对你施放|cFFFF0000|Hspell:227789|h[神圣之地]|h|r！"
D.Strings[103939]="我们最好分头行动。我会设法避开塔里的魔法防御措施。而你恐怕得采取……更加暴力的手段了。"
D.Strings[103940]="真是乱七八糟！"
D.Strings[103941]="我第一次觉得自己……好邪恶。"
D.Strings[103942]="你邪恶的脑子是不是出了问题？"
D.Strings[103943]="这家伙该化妆了。"
D.Strings[103944]="见见我的仆人，听听他们的声音！"
D.Strings[103945]="你有飞翔的权利！"
D.Strings[103946]="抱歉害你掉下来了！"
D.Strings[103947]="听我的话，你就会受欢迎！"
D.Strings[103948]="我们在一起，就无所不能！"
D.Strings[103949]="|TInterface\\Icons\\spell_arcane_arcanetorrent_nightborne:20|t嘉琳黛尔正在施放|cFFFF0404|Hspell:227776|h[魔法威仪]|h|r！快使用|TInterface\\Icons\\spell_priest_void blast:20|t|cFFFF0404|Hspell:227405|h[反抗引力]|h|r的漩涡逃跑！"
D.Strings[103950]="那个巫婆她并不是坏心肠，但另一个女巫让她发了狂。"
D.Strings[103951]="今天这儿要排场新戏，你们都会以为这故事很熟悉。"
D.Strings[103952]="唱戏的家伙少废话，美猴王有了个新想法！"
D.Strings[103953]="欢迎，女士们先生们。今晚——喔唷！"
D.Strings[103954]="多么美丽的……悲剧。"
D.Strings[103955]="这里将属于嘉琳黛尔！"
D.Strings[103956]="现在，来见识一下真正的威仪吧！"
D.Strings[103957]="爱情是一种源自本能的过时理念！"
D.Strings[103958]="我才不回收发室呢！"
D.Strings[103959]="他们付的工资根本不值得我拼命！"
D.Strings[103960]="不用担心，孩子。我是你的酋长。"
D.Strings[103961]="现在，我代表着部落。"
D.Strings[103962]="我不需要保护，大使。年轻人，酋长的责任重大，但我被选中了，就必须挑起重担。"
D.Strings[103963]="我在孤儿院的朋友说，你总是把被遗忘者看得比部落更重，还抛弃我们。这是真的吗？"
D.Strings[103964]="谢谢你，孩子。但愿你是对的。"
D.Strings[103965]="他不只是一块宝石。他是我们的国王。"
D.Strings[103966]="他走了，孩子。他追随一个伟大的召唤去了。"
D.Strings[103967]="既然他变成了钻石，那肯定不会有事的。钻石可硬了！"
D.Strings[103968]="钻石会走路？"
D.Strings[103969]="那个大钻石呢？"
D.Strings[103970]="我们毫不怀疑，你一定会成功的。"
D.Strings[103971]="多亏了你的所作所为，守望者的传说已经传开了。"
D.Strings[103972]="对方毫无还手之力。"
D.Strings[103973]="我都没看到你来了。"
D.Strings[103974]="你知道该怎么做，祝你好运。"
D.Strings[103975]="果断出击，一击毙命。"
D.Strings[103976]="我们有个任务要交给你。"
D.Strings[103977]="我们已经为你标记出了目标。快行动吧。"
D.Strings[103978]="你的目标就在附近，刺客。"
D.Strings[103979]="你又挫败了一个威胁，干得好！"
D.Strings[103980]="你的身手很惊人，朋友。"
D.Strings[103981]="你的行动很果断，干得好！"
D.Strings[103982]="又解决了一个目标，太好了！"
D.Strings[103983]="你真是越来越厉害了，朋友。"
D.Strings[103984]="你又一次维护了和平。"
D.Strings[103985]="守望者再次感谢你。"
D.Strings[103986]="你的位置附近有一个致命的目标。去证明一下你的实力吧。"
D.Strings[103987]="附近潜伏着一个强大的敌人。将它绳之以法！"
D.Strings[103988]="小心！危险正在靠近。你必须消灭它。"
D.Strings[103989]="我们的猫头鹰在你的位置附近发现了一个目标。解决它。"
D.Strings[103990]="你附近就有一个目标。以正义的名义去消灭它吧。"
D.Strings[103991]="附近潜伏着一个强大的威胁。小心点！"
D.Strings[103992]="真是一次高效惊人的击杀。你的功绩完全能够媲美守望者了！"
D.Strings[103993]="干得好！许多人都会畏惧这种威胁，但你却充满了勇气。"
D.Strings[103994]="你真是潜力惊人！毫无疑问，我们还会再召唤你的。"
D.Strings[103995]="现在你体会到了守望者肩负的责任，朋友。感谢你的帮助。"
D.Strings[103996]="我们真走运！你附近就有一个我们追踪已久的目标。去消灭它，我们会铭记你对守望者的帮助的。"
D.Strings[103997]="我们相信你的能力足以将这个目标绳之以法。为我们组织效力，你就将获得奖励。"
D.Strings[103998]="这片土地充斥着危险，朋友。考验你勇气的时候到了。迅速果断地出击吧！"
D.Strings[103999]="破碎群岛是一片危机四伏的土地，朋友。守望者需要你帮忙解决这个威胁。"
D.Strings[104000]="守望者的责任就是保护我们的人民不受此类危险怪物的威胁。不要犹豫，不要手软，去干掉它吧！"
D.Strings[104001]="感谢你的帮助。这片土地的能量潮汐涨落不定，你要小心点。"
D.Strings[104002]="快把酒喝完！我们马上就要出发了！"
D.Strings[104003]="你有准备好的神器调查笔记吗？"
D.Strings[104004]="你的队伍已经选择将司克诺兹踢出气球！"
D.Strings[104005]="只要凑齐三位乘客，气球就立刻起飞。"
D.Strings[104006]="你好，$n。今天有肯瑞托主办的旅店趴活动。需要我将你传送到大家集中的旅店去吗？"
D.Strings[104007]="我喜欢你的眼镜，看起来很复古。"
D.Strings[104008]="破碎阶梯上通向舞厅的门开启了。"
D.Strings[104009]="你差点就赢了。下次再来吧。"
D.Strings[104010]="唔……谢谢参与？"
D.Strings[104011]="你输了！你什么都得不到！"
D.Strings[104012]="真可惜，太可惜了。"
D.Strings[104013]="是我的错觉吗？有人闻到胜利的味道了吗？"
D.Strings[104014]="唔。我敢打赌，你们当中没上心的人可不止一个。"
D.Strings[104015]="乱斗结束了……我们的英雄们赢了！所有的参与者都将获得满满一袋金币！"
D.Strings[104016]="难以置信……他们居然赢了！这真是奇迹！好吧，我开玩笑的，这种事经常发生。"
D.Strings[104017]="她是为乱斗而生的。当然，她现在看起来像只可爱的小猫咪，可等她被逼入绝境时就不是了。瞪大你们的眼睛，看清我们的下一位乱斗拳手——玛扎伦吧！"
D.Strings[104018]="如果你战胜不了他，那就加入他吧！等着他来把你的思想、脑袋和冰冻饮料一一融化吧，他就是——摧心者扎吉！"
D.Strings[104019]="你不用击败这些家伙，你只要想办法活下来就行了。噢，但我们要拿走你所有的装备和经验。好好享受这场荆棘谷越野赛吧！"
D.Strings[104020]="河马意味着死亡！别小看了我们的下一位乱斗拳手，他就是——森雅！"
D.Strings[104021]="这三位熊猫人为你准备了一个挑战……你要抢在他们前头，把这辆装满啤酒的推车拉到竞技场中央。获胜的小队可以畅饮这些美酒！"
D.Strings[104022]="我们今天的乱斗拳手是一群来自诺森德极地的企鹅。小心它们的滑行奔踏！"
D.Strings[104023]="我们今天的乱斗拳手是一头渴望复仇的健壮野兽。他不想帮你……他只想杀了你。他就是满腔仇恨的驼鹿，悲伤的守望者！"
D.Strings[104024]="|TInterface\\Icons\\INV_Misc_Food_Legion_gooOil_multi.blp:20|t焦油坑开始|cFFFF0000|Hspell:236333|h[喷发]|h|r！"
D.Strings[104025]="%s周围的地面开始渗出焦油……"
D.Strings[104026]="把我传送到旅店趴那里。"
D.Strings[104027]="欢迎参加肯瑞托旅店趴活动，$n。请随意享用这里的所有饮料和免费食物吧。我们将在几分钟后前往下一个旅店。"
D.Strings[104028]="呵呵，这趟旅程让我振奋了起来。感谢各位来陪伴我这个老猎人！"
D.Strings[104029]="呵呵。我说这个笑话就没事，因为我是个矮人，而且还是个猎人！"
D.Strings[104030]="因为弓没有可以装酒的枪管！"
D.Strings[104031]="矮人猎手为什么要用火枪打猎？"
D.Strings[104032]="有人知道什么好笑的笑话吗？我先说一个……"
D.Strings[104033]="我抑郁了。"
D.Strings[104034]="我能坐你的气球吗？"
D.Strings[104035]="|TInterface\\Icons\\SPELL_SHADOW_SOULLEECH_1.BLP:20|t%s开始|cFFFF0000|Hspell:236133|h[绽放]|h|r！"
D.Strings[104036]="这轮是$n请的！接下来的两分钟内，所有饮品全部免费！"
D.Strings[104037]="感谢$n的慷慨，比兹莫的贵宾室向所有拳手敞开了大门！"
D.Strings[104038]="$n花钱修改了竞技场的规则。如果你们想挑战未知的拳手，就去跟保镖谈谈吧！"
D.Strings[104039]="内幕消息。你们或许没有“赢得”进入贵宾室的资格，但有个好心人花钱为你们买到了准入资格。\n\n你们很走运，快进去吧，但别捣乱。"
D.Strings[104040]="你8级了，对吧？\n\n你真棒，进去吧。"
D.Strings[104041]="比兹莫和他的团队在矿道地铁旁开办这家俱乐部时，是冒了大风险的。为了建造这个地方，他花了不少金币。\n\n所以他建造了这个被他称为“贵宾室”的地方。在这里，有更好的观战视角，可以购买各种顶级饮料，还能为你提供出入私人会所的虚荣感。因为你看，只有8级或8级以上的拳手才能上去。\n\n你想进入贵宾室吗？那就多赢几场比赛吧，孩子。"
D.Strings[104042]="<出示贵宾室租赁表。>"
D.Strings[104043]="今天的赛场真是混乱。我敢打赌，这绝对比以往的任何一场比赛都血腥。我好像都被咬了一口。"
D.Strings[104044]="$n想知道：你们觉得自己够走运吗？ 快去跟温弗雷德·布朗爵士谈谈，试试你们……赚大钱的手气吧。"
D.Strings[104045]="暴风之盾保卫战（史诗难度）"
D.Strings[104046]="暴风之盾保卫战（英雄难度）"
D.Strings[104047]="暴风之盾保卫战"
D.Strings[104048]="埃索达保卫战（史诗难度）"
D.Strings[104049]="埃索达保卫战（英雄难度）"
D.Strings[104050]="埃索达保卫战"
D.Strings[104051]="达纳苏斯保卫战（史诗难度）"
D.Strings[104052]="达纳苏斯保卫战（英雄难度）"
D.Strings[104053]="达纳苏斯保卫者"
D.Strings[104054]="铁炉堡保卫战（史诗难度）"
D.Strings[104055]="铁炉堡保卫战（英雄难度）"
D.Strings[104056]="铁炉堡保卫战"
D.Strings[104057]="暴风城保卫战（史诗难度）"
D.Strings[104058]="暴风城保卫战（英雄难度）"
D.Strings[104059]="暴风城保卫战"
D.Strings[104060]="战争之矛保卫战（史诗难度）"
D.Strings[104061]="战争之矛保卫战（英雄难度）"
D.Strings[104062]="战争之矛保卫战"
D.Strings[104063]="银月城保卫战（史诗难度）"
D.Strings[104064]="银月城保卫战（英雄难度）"
D.Strings[104065]="银月城保卫战"
D.Strings[104066]="幽暗城保卫战（史诗难度）"
D.Strings[104067]="幽暗城保卫战（英雄难度）"
D.Strings[104068]="幽暗城保卫战"
D.Strings[104069]="雷霆崖保卫战（史诗难度）"
D.Strings[104070]="雷霆崖保卫战（英雄难度）"
D.Strings[104071]="雷霆崖保卫战"
D.Strings[104072]="奥格瑞玛保卫战（史诗难度）"
D.Strings[104073]="奥格瑞玛保卫战（英雄难度）"
D.Strings[104074]="奥格瑞玛保卫战"
D.Strings[104075]="|TInterface\\Icons\\ABILITY_HUNTER_PET_RAPTOR.BLP:20|t%s |cFFFF0000|Hspell:235886|h[召唤]|h|r她的迅猛龙群！"
D.Strings[104076]="|TInterface\\Icons\\SPELL_NATURE_UNRELENTINGSTORM.BLP:20|t%s开始施放|cFFFF0000|Hspell:235766|h[闪电新星]|h|r！"
D.Strings[104077]="冰霜十字架拥有强大的力量。同时拥有多个十字架是愚蠢的行为。一旦你放出了冰霜巨龙，我们就能再召唤一条了。"
D.Strings[104078]="我们为什么不能再举行一个仪式呢？"
D.Strings[104079]="我们目前还无法同时拥有多个裂隙之核。你已经拥有一个了。等你释放了它之后，我们会开始给另一个充能的。"
D.Strings[104080]="我们为什么不能给裂隙之核充能呢？"
D.Strings[104081]="我们一次只能引导一个达拉然之力。你似乎已经拥有一个聚焦水晶了。一旦你释放了它，我的法师就能再为你制作一块了。"
D.Strings[104082]="我们为什么不能再制作一块水晶呢？"
D.Strings[104083]="地狱火是种麻烦的生物，而且极其强大。我们必须谨慎对待它们。你已经拥有一个护命匣了，继续召唤并不明智。"
D.Strings[104084]="我们为什么不能再召唤一个地狱火？"
D.Strings[104085]="抱歉，在你部署好已经召集起来的部队前，我们无法召集新的部队。"
D.Strings[104086]="我为什么不能召集瓦格里？"
D.Strings[104087]="抱歉，我们的部队只够同一时间部署一位先锋。一旦你下达命令，我们就能再招募一位。"
D.Strings[104088]="我为什么不能再召唤一位先锋呢？"
D.Strings[104089]="如果你还想要的话，尽管来找我。我会帮你牵线的。"
D.Strings[104090]="你该去检查一下了。"
D.Strings[104091]="我会改的。"
D.Strings[104092]="我们已经回不去了。"
D.Strings[104093]="我就是没那么喜欢你了。"
D.Strings[104094]="我以为那是你！"
D.Strings[104095]="那只是一夜情而已。"
D.Strings[104096]="我们应该找找别人。"
D.Strings[104097]="不是你的问题，是我。"
D.Strings[104098]="我们还是朋友吧。"
D.Strings[104099]="欢迎欢迎！请随意享用免费的饮料和食物。"
D.Strings[104100]="最后说一次！我开了一道通向隔壁旅店的传送门！"
D.Strings[104101]="我们走，各位！去隔壁的旅店！"
D.Strings[104102]="你好，$c。你想更加了解你的神器吗？ \n\n我很乐意帮助你，但看来你身上还有神器调查笔记。阅读它们能够增加你的知识。"
D.Strings[104103]="<召唤蝌蚪跟随你。>"
D.Strings[104104]="弗肖枯萎了。愿她的孢子永远在赞加的微风中飘荡！"
D.Strings[104105]="弗肖来了！"
D.Strings[104106]="没有你们的帮助，弗肖无法在地表长期生存。我们需要治疗者、医师和蘑菇园丁来保护她！"
D.Strings[104107]="注意了，孢子人！荣耀的孢子人们！快来见证弗肖生长的奇迹吧！"
D.Strings[104108]="气球节快乐！想乘坐热气球吗？"
D.Strings[104109]="必须……逃出去！必须来……警告你……"
D.Strings[104110]="你必须阻止他们……"
D.Strings[104111]="今天就到此为止吧。感谢大家参与这次飞行……我们下次再一起来学习！"
D.Strings[104112]="有趣的猜想！答案是：“这是幻象！你在掩饰什么？”"
D.Strings[104113]="最后一个问题，就请$n来回答吧。在苏拉玛城，传统的问候语是哪一句呢？"
D.Strings[104114]="很接近了！正确答案应该是，“他们的皮肤”。"
D.Strings[104115]="$n。夜之子身体的哪一部分由于过分摄入魔力而产生了变异呢？"
D.Strings[104116]="吸食大量魔力对夜之子的身体产生了副作用。"
D.Strings[104117]="对，他们服用的物质就是魔力。"
D.Strings[104118]="$n，你能告诉我，夜之子是用什么精神药物来放松自己的吗？"
D.Strings[104119]="夜之子以难以相处著称。"
D.Strings[104120]="众所周知，苏拉玛是夜之子精灵的故乡。"
D.Strings[104121]="你们真喜欢交头接耳呀。观光开始了！"
D.Strings[104122]="好，最后一个是$n。那一定就是你了，对吧？"
D.Strings[104123]="很好，$n来了吗？"
D.Strings[104124]="嗯，说“到”就可以了。"
D.Strings[104125]="$n？$n来了吗？"
D.Strings[104126]="但首先，我要点个名。"
D.Strings[104127]="今天，我们将乘坐观光气球俯瞰古老的苏拉玛城。"
D.Strings[104128]="欢迎！请到篮子里来……准备体验你这一生中最有教育意义的气球之旅吧。"
D.Strings[104129]="好了，旅程结束了！这真是太有意思了！"
D.Strings[104130]="好了，我完成了。下面该换人了！"
D.Strings[104131]="这样的话，我只能跟$n结婚了！我就凑合一下吧。"
D.Strings[104132]="唔……我要杀掉$n。原因已经显而易见了。"
D.Strings[104133]="$n，你是个漂亮的人，而且看来你是这几个人中唯一一个会刷牙的，所以我要吻你。"
D.Strings[104134]="我先来！让我看看……"
D.Strings[104135]="玩法很简单。你只要选出一个想要亲吻的对象，一个想要结婚的对象和一个想要谋杀的对象。"
D.Strings[104136]="啊哦，我会一个！它叫做“亲吻、结婚、谋杀”。"
D.Strings[104137]="那么……你们知道什么适合气球派对的游戏吗？"
D.Strings[104138]="抱歉，我没有多少导游经验。"
D.Strings[104139]="看到下面的崇山峻岭了吗？那就是……呃……那就是风暴峡湾。"
D.Strings[104140]="欢迎光临！今天，我将带各位游览风暴峡湾。"
D.Strings[104141]="这是我经历过的最舒心的一次气球之旅。简直能称得上乐趣了。谢谢，谢谢各位！"
D.Strings[104142]="我可没有忘了你，$n。告诉我们一个秘密吧。我们不会批评你的。这个气球很安全。"
D.Strings[104143]="你呢，$n？你有什么让你寝食难安的秘密吗？"
D.Strings[104144]="$n，你也来试试吧。告诉我们一些你从来没有告诉过别人的秘密。来吧。"
D.Strings[104145]="现在你们都知道我的秘密了。你们呢？"
D.Strings[104146]="说出来之后感觉好多了。我以前从来没有跟别人说过这些。"
D.Strings[104147]="……呼。"
D.Strings[104148]="这样你满意了吧，父亲？嗯？你为我骄傲吗，父亲？！？！"
D.Strings[104149]="我恨气球。我这辈子都不想看到它了。我想要成为一个萨满，可不行！显然，“我们生来就是驾驶气球的料”。"
D.Strings[104150]="我得向你们三位承认。"
D.Strings[104151]="你知道吗？那就是，我已经受够了！"
D.Strings[104152]="在我们的右下方，就是庞家农场。请注意……"
D.Strings[104153]="<叹气>……"
D.Strings[104154]="这是前往半山的气球之旅。请不要随意触摸篮子里的任何东西，并全程抓紧。"
D.Strings[104155]="又是坐气球的？好吧……上来吧。"
D.Strings[104156]="你们三个自己聊吧。我得小心点，不能让气球撞上达拉然。"
D.Strings[104157]="那你呢，$n？你有什么珍贵的冒险故事吗？"
D.Strings[104158]="你呢，$n？"
D.Strings[104159]="你怎么样，$n？你去过哪些神奇的地方？"
D.Strings[104160]="啊，请原谅我的唠叨。你们肯定有更加精彩的冒险故事！"
D.Strings[104161]="我这辈子走过很多地方，但对那一次的印象特别深刻。"
D.Strings[104162]="在那道山脊的另一边，就是索拉查盆地，我在那里遇到过一个狼獾人部族和一个鱼人神谕者部族。都是奇怪的生物！"
D.Strings[104163]="啊……但我在诺森德确实留下了一些美好的回忆。"
D.Strings[104164]="遗憾的是，在我的旅行生涯中，并没有在这里停留太多时间。但我不能告诉你们原因。"
D.Strings[104165]="你们的下方，就是晶歌森林。"
D.Strings[104166]="欢迎。请坐下，好好享受这趟旅程吧。"
D.Strings[104167]="咳……看来我们已经很靠近目的地了。各位，向雷霆图腾问个好吧！"
D.Strings[104168]="你呢，$n？随便谁都行，让我高兴起来吧！"
D.Strings[104169]="要不你来，$n？"
D.Strings[104170]="$n，你知道什么笑话吗？"
D.Strings[104171]="就算是坐在气球上打小动物也没法让我打起精神来。"
D.Strings[104172]="但最近……呃，我不知道。我感觉有点低落。狩猎不像过去那么有意思了。"
D.Strings[104173]="这气球是我从一个小地精手里买来的，据说它很适合用来打驼鹿！"
D.Strings[104174]="欢迎，朋友们，欢迎参加奈辛瓦里的至高岭气球之旅！"
D.Strings[104175]="你干了什么？伦吉尔，你又搞砸了！！！！"
D.Strings[104176]="好了，头儿。我按照你说的，把焰火放在烧烤架上了。"
D.Strings[104177]="那么价格是多少呢？每位28,542金币——这还没有包含服务费哦！想赖账的话，小心伦吉尔打断你的腿哦。"
D.Strings[104178]="秘诀就是，不要告诉乘客价钱，先把他们弄上气球再说！"
D.Strings[104179]="你可能要问：我是怎么在运营着这么奢华的气球同时还赚到钱的。呃，我来告诉你！"
D.Strings[104180]="伦吉尔，你去加热一下烧烤架，然后把焰火准备好。"
D.Strings[104181]="要热毛巾吗？我们只为客人提供最好的服务！"
D.Strings[104182]="下方就是纳萨拉斯学院。我听说在古代，那是一座法师学院。"
D.Strings[104183]="有人要鱼子酱吗？我们只提供最好的鱼子酱！"
D.Strings[104184]="今天，我们要飞越破碎群岛的明珠——阿苏纳。"
D.Strings[104185]="要来杯免费的饮料吗？给。"
D.Strings[104186]="我们的气球是全艾泽拉斯最豪华的！你可以随便找个人问问，人人都这么说！"
D.Strings[104187]="快上来吧，新手气球驾驶员们！有人想要气球贴纸吗？给你。"
D.Strings[104188]="家才是最美好的，家才是最美好的，家才是最美好的……"
D.Strings[104189]="或是来到了未来？我不知道。总之，这太可怕了！我要回去！"
D.Strings[104190]="不可思议！我们穿越时空回到了过去！"
D.Strings[104191]="这是纳格兰？我们就在纳格兰！"
D.Strings[104192]="我想我们已经不在纳格兰了。"
D.Strings[104193]="我给这个宝贝装了一个超级廉价的时空加速器！准备体验真正的时间飞逝吧！什么？能出什么事呢？"
D.Strings[104194]="伙计们，你们走运了！这可不是通常意义上那种慢吞吞的、让人昏昏欲睡的气球之旅。"
D.Strings[104195]="欢迎光临！"
D.Strings[104196]="这是我应得的！"
D.Strings[104197]="守夜人擅长追踪。在暮色森林，每个黑暗的角落里都潜伏着动物。$b$b有时，你能看到它们瞪着圆滚滚的小眼睛，从灌木丛里窥探你。$b$b<哨兵努力克制着不让自己发抖。>$b$b话说，前几天我还感觉有个陌生的生物在森林的阴影里窥伺我。"
D.Strings[104198]="很好。现在，让我们安安静静地坐着，度过下面这一小时吧。"
D.Strings[104199]="我们将体验一次美妙的气球之旅，大家都会喜欢的。明白吗？"
D.Strings[104200]="这就是规矩。不遵守的人都将受到处罚。"
D.Strings[104201]="尤其不准打打闹闹！"
D.Strings[104202]="不准交头接耳、不准乱蹦乱跳、不准摇晃篮子。"
D.Strings[104203]="我们可是一只纪律严明的气球！"
D.Strings[104204]="请注意我的口令。"
D.Strings[104205]="%s对你使用了恐龙魔精，令你获得了一个适者生存效果！"
D.Strings[104206]="格隆戈要碾碎你！"
D.Strings[104207]="你想要爆鸣？那就拿去吧，笨蛋！"
D.Strings[104208]="从我的船上滚下去，联盟渣滓！"
D.Strings[104209]="从我的船上滚下去，部落渣滓！"
D.Strings[104210]="走开，除非你想被喷一脸的烟花！"
D.Strings[104211]="你获得了一条免费船只，可以在节日期间泛舟水上。请安全乘船！"
D.Strings[104212]="<叹气>……我也想玩排球……"
D.Strings[104213]="他们的垃圾都聚集到礁湖的这个角落了。我们绝不容忍这种对大自然的冒犯。"
D.Strings[104214]="其他种族轻率的派对给这片土地的环境造成了灾难性的破坏。"
D.Strings[104215]="唔……我敢打赌，那边那些海盗身上肯定有啤酒……"
D.Strings[104216]="我们大老远赶来庆祝赛艇日，而你居然忘了见鬼的啤酒！"
D.Strings[104217]="哎唷！难以置信！"
D.Strings[104218]="嘿，你！你们这些水手想参加派对吗？"
D.Strings[104219]="<呼呼！>真不敢相信 ，你竟敢造谣中伤我。而且还是在赛艇日！"
D.Strings[104220]="嘿，放松点，小家伙。是你和你的小鬼们先来扫荡我们的炸弹的，我只是以牙还牙而已！"
D.Strings[104221]="总是这样！我刚转身，你们这些恶棍就来偷我们的炸药！"
D.Strings[104222]="而另一边的则是一位矮人和他忠诚的、绝对绝对不会伤害主人的伙伴。"
D.Strings[104223]="打开你的陷阱，我要射击了，奥索！"
D.Strings[104224]="我这是罪有应得。"
D.Strings[104225]="你卖的东西为什么这么贵？"
D.Strings[104226]="我能帮什么忙呢？"
D.Strings[104227]="对，身份勋章和贵族之戒都很昂贵——贵到一般人根本无法独立购买。$b$b我建议你和其他冒险者组队并选出一名勇士。召唤深渊议会的高阶成员只需要一个勋章或戒指——但却需要很多英雄才能击败他们。$b$b祝你好运。"
D.Strings[104228]="扰乱暮光之锤的营地，袭击他们的高阶深渊议会！\n\n干掉那三个巨型异种蝎虫巢里的巨型异种虫。\n\n为我们的阵营收集水晶尘吧，那是一种珍贵的红色香料。\n\n深入安其拉，干掉盘踞在那里的其拉虫族，扫清上古之神的威胁！\n\n就连不爱战斗的冒险者也可以通过捐助战斗补给——也就是各种肉类——的方式来参与我们的行动。"
D.Strings[104229]="多年前的今天，一个名叫卡拉哈德的英雄敲响甲虫之锣，打开了安其拉的大门，发起了一场卡利姆多前所未见的战争。$b$b今天，我们回到希利苏斯追寻当年那些冒险者的脚步，纪念他们的英勇事迹。$b$b更重要的是：这是一场部落和联盟间的竞争。在接下来的24小时内积分更高的阵营可以将自己的旗帜挂在甲虫之锣旁，直到年末。"
D.Strings[104230]="今天，我们要庆祝甲虫之锣敲响的周年纪念日。你会看到，今天全希利苏斯都充满了节日气氛。$b$b作为一项传统，我们要从那三个异种蝎巢穴里召唤出巨大的昆虫。因此，我们需要肉，很多肉。$b$b你愿意帮忙吗？"
D.Strings[104231]="<回忆古尔丹的末日>"
D.Strings[104232]="多年的烹饪训练让你认出了这种奇怪的花。它很安全，甚至能让你的朋友们受益！"
D.Strings[104233]="作为一个熊猫人，你认识这种可食用的花。快把它塞进嘴里吧！"
D.Strings[104234]="草药学让你认识了许多天然的食材。这种肯定能吃！"
D.Strings[104235]="作为一名德鲁伊，你认识这种食物里所用到的植物和原料。它很安全，可以食用。"
D.Strings[104236]="$n净化了邪能宝珠，使所有人的爆击率提高了！"
D.Strings[104237]="$n摧毁了邪能宝珠，使所有人的爆击率提高了！"
D.Strings[104238]="$n吸收了地狱火宝典里的魔力，使所有人获得了减伤效果！"
D.Strings[104239]="恶魔猎手的训练让你对此早有准备。快来攫取这本地狱火宝典里的力量吧。"
D.Strings[104240]="作为一个术士，这点小小的邪能魔力对你毫无威胁。快吸收掉这本地狱火宝典的力量吧。"
D.Strings[104241]="对于牧师而言，这颗宝珠是邪恶的，必须被摧毁。"
D.Strings[104242]="而另一边的则是一位戴着致命头戴式火炮的海盗！举起你们的铁钩，为布莱曼吉欢呼吧！"
D.Strings[104243]="现在，在听听来自地下音乐震撼灵魂的节奏吧，他们就是强击乐队和他们的伴舞们！"
D.Strings[104244]="另一边的则是一个可怕的三人组……来自食人先锋的哈德森、硕鼠和杜普雷！"
D.Strings[104245]="为这位灯神欢呼吧，他真的能融化你的心。他就是——博斯塔乔！"
D.Strings[104246]="接下来这位挑战者就是害我们大出血的——射线博士提亚！"
D.Strings[104247]="而在另一边的，则是超凡入圣、不可思议、风靡大众的超级猎人——强尼·傲森！"
D.Strings[104248]="而我们的另一位挑战者，则是一位纵火狂晚期患者。拜托，卡尔，你不知道大火会烧死人吗？"
D.Strings[104249]="现在进入竞技场的是……一个不断播放美妙音乐的帅气机器。"
D.Strings[104250]="而在另一边的则是战锤议会！它不是由一个或两个，而是三个致命的矮人组成的超级战车！"
D.Strings[104251]="请插入一枚金币，与帕库大师一起战斗吧！"
D.Strings[104252]="而在另一边的则是……一头巨型恐龙！"
D.Strings[104253]="而在另一边的则是暗影及室内照明专家——暗影大师艾蒙！"
D.Strings[104254]="下面有请热衷于宠物收集的德莱尼——阿什卡祖！"
D.Strings[104255]="而他们的挑战者，则是死神的清道夫比尔！等等……什么？比尔，你在那儿干什么？"
D.Strings[104256]="看来对这……家伙来说，每天都是万圣节。来给奥里斯一点尖叫声吧！"
D.Strings[104257]="噢，好大一只海牛！它是来搞事的……它就是——灾鳍！"
D.Strings[104258]="那是个大蘑菇吗？看来这事儿真是越来越古怪了。"
D.Strings[104259]="而这边的是……一只海鸥？这是怎么回事，艾萨拉之眼？"
D.Strings[104260]="接下来这位来自暮色森林的阴暗小径，它就是——缝合怪！"
D.Strings[104261]="现在进入竞技场的是：一个不断播放音乐的侏儒杰作。"
D.Strings[104262]="我们领先了！为了联盟！"
D.Strings[104263]="Throm-ka！部落领先了！"
D.Strings[104264]="让我们来做点非常奇怪的事吧！"
D.Strings[104265]="扫描对手的摇摆水平。检测为零。"
D.Strings[104266]="你的节奏还不够水准。"
D.Strings[104267]="你的舞步很不流畅。"
D.Strings[104268]="步伐混乱。"
D.Strings[104269]="僵硬。"
D.Strings[104270]="节奏驱动器重新上线。节奏协议切换到打脸模式。"
D.Strings[104271]="律动电池供能不足。进入垃圾话模式。"
D.Strings[104272]="节奏回路损坏……"
D.Strings[104273]="你很有技巧！"
D.Strings[104274]="你要有报应了，节“揍”手！"
D.Strings[104275]="看看那些充满节奏的舞步！"
D.Strings[104276]="欢迎，准备迎接节奏的挑战吧。"
D.Strings[104277]="感受这大军的怒火吧！"
D.Strings[104278]="让我们来做点奇怪的事情吧！"
D.Strings[104279]="我要一个个抓住他们！"
D.Strings[104280]="我要成为最伟大的人！"
D.Strings[104281]="他们总是炸得那么快。"
D.Strings[104282]="噢，你们都要被炸飞！"
D.Strings[104283]="我们会玩得很开心的！"
D.Strings[104284]="你会看到的，我可是个爆脾气！"
D.Strings[104285]="过来吧……拥抱你所有的痛苦！"
D.Strings[104286]="这是开玩笑吗？"
D.Strings[104287]="音乐不要停！"
D.Strings[104288]="喵喵喵。"
D.Strings[104289]="喵喵。"
D.Strings[104290]="它亮了，伙计。"
D.Strings[104291]="整队！"
D.Strings[104292]="这让我怎么乐观得起来？"
D.Strings[104293]="如果你能闭上眼睛……"
D.Strings[104294]="你好哇。"
D.Strings[104295]="狂野之舞！"
D.Strings[104296]="1、2、3，跳！"
D.Strings[104297]="我找齐了所有的材料。"
D.Strings[104298]="这本来只是个很简单的任务。我只要把这个袋子送到岛上，然后收钱走人就是了。$b$b可现在，我的老板却想杀了我！"
D.Strings[104299]="小事一桩。"
D.Strings[104300]="回来，闪光蛋！"
D.Strings[104301]="看着我！"
D.Strings[104302]="我想挑战未知的敌人！"
D.Strings[104303]="我只是个业余爱好者。"
D.Strings[104304]="$n花钱修改了竞技场的规则。如果你们想挑战未知的拳手，就去跟步兵谈谈吧！"
D.Strings[104305]="<出示一袋开裂的骰子。>"
D.Strings[104306]="你们觉得自己很走运？正好，$n让你们都去跟赌场老板巴克多格尔谈谈……试试你们的手气吧！"
D.Strings[104307]="<出示烂赌鬼的合同。>"
D.Strings[104308]="你看了那些比赛吗？赛场里简直乱成一团。我好像还被咬了一口。"
D.Strings[104309]="别听萨拉隆的。没有任何人能击败虎虎生风的战锤、炽热的火焰和坚硬的钢铁。$b$b说到这个，我得回去干活儿了。"
D.Strings[104310]="拳手们，都注意了！$n跟灵魂医者做了笔买卖！大家可以尽情去送死了！"
D.Strings[104311]="<出示染血的天使雕像。>"
D.Strings[104312]="想买点……秘密武器吗？"
D.Strings[104313]="$n非常慷慨地为所有人购买了搏击药水。快点趁热来领吧！"
D.Strings[104314]="<出示拳手的药水分发机。>"
D.Strings[104315]="想买点什么吗？"
D.Strings[104316]="<出示免费饮料券。>"
D.Strings[104317]="哟！会是什么呢？"
D.Strings[104318]="承蒙$n的好意，所有人都可以免费乘坐飞艇！快来传送器这儿！"
D.Strings[104319]="不用担心。你可能没有“赢得”上飞艇的权利，但有个傻瓜为你“买”了单，所以你可以上去了。\n\n跳到那个传送器上去！它一定、大概不会弄死你的！"
D.Strings[104320]="<出示飞艇租赁表。>"
D.Strings[104321]="艾泽拉斯分裂时，许多知识都失传了。但我，露妮丽，能和大地与风对话。$b$b它们告诉了我许多秘闻，我会将这些知识传授给那些有能力的人。$b$b那么，你是这样的人吗？"
D.Strings[104322]="不！我们的河马！我们投降！"
D.Strings[104323]="你的乱羽雏鸟开始打瞌睡了。"
D.Strings[104324]="你的乱羽雏鸟用爪子紧紧抓着你的肩膀。"
D.Strings[104325]="你的乱羽雏鸟展开了双翼。"
D.Strings[104326]="你的乱羽雏鸟似乎很无聊。"
D.Strings[104327]="你的乱羽雏鸟似乎很惊讶。"
D.Strings[104328]="你的乱羽雏鸟想要进一步认识这个世界。"
D.Strings[104329]="你的乱羽雏鸟满足地叹了口气。"
D.Strings[104330]="成功了！这个蛋孵化了！"
D.Strings[104331]="里面的角鹰兽挣扎着想要逃跑。"
D.Strings[104332]="你听到蛋壳里传出一阵响动。"
D.Strings[104333]="这个蛋似乎变冷了。靠近点，让它保持温度。"
D.Strings[104334]="噢？这个蛋是不是在动？"
D.Strings[104335]="如果你想换回传统的飞行形态，我可以帮你，大德鲁伊。"
D.Strings[104336]="我想使用月翼猫头鹰形态。"
D.Strings[104337]="我不想再使用月翼猫头鹰形态了。"
D.Strings[104338]="你喜欢月翼猫头鹰的形态吗，大德鲁伊？"
D.Strings[104339]="我有虚空碎片，你要交易吗？"
D.Strings[104340]="军团战舰准备撤退了！立刻下船！"
D.Strings[104341]="|TInterface\\Icons\\ABILITY_WARLOCK_SOULSWAP.BLP:20|t转身避开加泽拉克斯的|cFFFF0000|Hspell:239217|h[眩目闪光]|h|r！"
D.Strings[104342]="|TInterface\\Icons\\ABILITY_MAGE_FIRESTARTER:20|t%s将|cFFFF0000$n|r选为了|cFFFF0000|Hspell:238502|h[聚焦恐惧烈焰]|h|r的目标！"
D.Strings[104343]="宝贝们，攻击！"
D.Strings[104344]="我需要一把宝箱钥匙。|cFF9400D3[100虚空碎片]|r"
D.Strings[104345]="你的圣物现在救不了你了！"
D.Strings[104346]="大教堂是我们的！"
D.Strings[104347]="燃烧军团必将消灭你！"
D.Strings[104348]="圣盾是我们的！"
D.Strings[104349]="他们战胜了萨什比特？！快跑！！！"
D.Strings[104350]="完成建造"
D.Strings[104351]="基尔加丹曾经跨越星海追杀我的人民，现在，他正在墓穴深处执行他的黑暗主子的命令。\n\n我们要让他为自己的罪行付出代价。欺诈者终于要倒下了！"
D.Strings[104352]="我的守望者们守住了大教堂。但要是让基尔加丹唤醒了他的主子位于墓穴深处的堕落化身，那我们的一切努力就都成了徒劳。\n\n看来伊利丹和他的追随者……暂时还有用。"
D.Strings[104353]="我承认，我对于你在大教堂里见到的艾格文的幻象很感兴趣。我一定可以从我的导师麦迪文的这位母亲身上学到很多东西，哪怕那只是守护者的一个残影。\n\n我会继续研究她的手稿。它们或许能告诉我们萨格拉斯之墓深处究竟有些什么。"
D.Strings[104354]="谢谢你，陌生人。我差点就完了！为了表达我的感谢，请收下这些东西作为报酬吧。"
D.Strings[104355]="你能送我去哀嚎洞穴吗？"
D.Strings[104356]="<你感觉玛纳波夫正在默默地审视着你。>"
D.Strings[104357]="森提纳克斯号充能完毕。"
D.Strings[104358]="森提纳克斯号召回了传送门并开始充能。"
D.Strings[104359]="要来几杯饮料吗？"
D.Strings[104360]="我知道这算不上什么旅店，但我们只能做到这样了。"
D.Strings[104361]="在战争年代，物资总是短缺的。"
D.Strings[104362]="我从没相信过背叛者或他的伊利达雷走狗，但为了大局，我愿意先搁置疑虑。\n\n可一旦燃烧军团倒下，我们还要那些被他们污染过的家伙干嘛？\n\n"
D.Strings[104363]="在这样的时代，我们的信仰都会受到严峻考验。我们或许会受到诱惑，向看似不可战胜……和不可阻挡的邪恶势力投降。\n\n但我们不能失去对圣光的信仰。它会带领我们走向胜利的。"
D.Strings[104364]="古尔丹被击败了，但他的主子基尔加丹的威胁更大。\n\n欺诈者会不遗余力地摧毁我们的世界。为了终结他的统治，我们必须做出一切必要的牺牲。"
D.Strings[104365]="你们这些冒险者留下的各种珍贵物品真是太惊人了。\n\n而且利润丰厚。"
D.Strings[104366]="|TInterface\\Icons\\artifactability_BalanceDruid_NewMoon.blp:20|t|cFFFF0000|Hspell:236357|h[艾露恩之泉]|h|r已达到新月状态。"
D.Strings[104367]="|TInterface\\Icons\\artifactability_BalanceDruid_FullMoon.blp:20|t|cFFFF0000|Hspell:236357|h[艾露恩之泉]|h|r已达到满月状态。"
D.Strings[104368]="|TInterface\\Icons\\SPELL_NATURE_MOONGLOW.BLP:20|t你受到了|cFFFF0000|Hspell:236519|h[月灼]|h|r的影响。"
D.Strings[104369]="|TInterface\\Icons\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t%s将你选为了|cFFFF0000|Hspell:236603|h[急速射击]|h|r的目标！"
D.Strings[104370]="|TInterface\\Icons\\SPELL_ARCANE_INVOCATION.BLP:20|t你受到了|cFFFF0000|Hspell:236712|h[月光信标]|h|r的折磨！"
D.Strings[104371]="|TInterface\\Icons\\inv_qiraj_skinsandworm:20|t%s钻入地下，大地|cFFFF0000|Hspell:238473|h[硬化]|h|r了它的鳞片！"
D.Strings[104372]="|TInterface\\Icons\\spell_shaman_earthquake:20|t%s准备冲锋！"
D.Strings[104373]="|TInterface\\Icons\\Ability_Earthen_Pillar.blp:20|t%s与钟乳石相撞，失去了硬化|cFFFF0000|Hspell:238473|h[邪能鳞片]|h|r！"
D.Strings[104374]="|TInterface\\Icons\\CREATUREPORTRAIT_INFERNAL_BALL_02.BLP:20|t%s正在施放|cFFFF0000|Hspell:238588|h[硫磺烈雨]|h|r！"
D.Strings[104375]="|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t|cFFFF0000|Hspell:237903|h[邪能涌动]|h|r使你昏迷了！在图腾完成施法前摧毁它！"
D.Strings[104376]="$n发出半声哀鸣。"
D.Strings[104377]="$n发出半声咆哮。"
D.Strings[104378]="$n发出半声啼鸣。"
D.Strings[104379]="$n发出半声怒吼。"
D.Strings[104380]="我再也不能对战争的残酷视而不见了。我必须亲眼看看燃烧军团的威胁。"
D.Strings[104381]="各大组织开始共享资源了，不用再研究神器知识了。我们每周都能获得新的知识。"
D.Strings[104382]="现在，只要你能源源不断地送来所需的资源，我们就能迅速为你获取神器知识。"
D.Strings[104383]="大法师卡德加知道我们该如何继续研究神器知识了。快去破碎海滩的救赎岗哨找他吧。"
D.Strings[104384]="我们的神器知识已经达到了当前允许的最高水平。"
D.Strings[104385]="我为什么不能研究神器知识了？"
D.Strings[104386]="成交！你最好别忘了！"
D.Strings[104387]="别担心，老弟，如果我们能渡过这一关，我就把我爸爸教我的刀法教给你。怎么样？"
D.Strings[104388]="可是，妈妈，你都让麦查上战场了！"
D.Strings[104389]="小奥罗，你留下！如果你出了什么事，你父亲会心碎的。"
D.Strings[104390]="拜托，让我也上战场吧！"
D.Strings[104391]="如果我死了，谁来照顾我的家人？"
D.Strings[104392]="我不能死……谁来救救我……"
D.Strings[104393]="请……让这噩梦停下来！"
D.Strings[104394]="我在哪儿？我想不起来了……"
D.Strings[104395]="我不想死……"
D.Strings[104396]="我怎么了？我的身体呢？"
D.Strings[104397]="感谢你的仁慈。我不会忘记你的……"
D.Strings[104398]="为暴风城……和国王陛下效劳是我的荣幸！"
D.Strings[104399]="我看见了……我看见圣光了……谢谢你。"
D.Strings[104400]="很荣幸能为你效劳，国王陛下……"
D.Strings[104401]="这场噩梦终于结束了……"
D.Strings[104402]="谢谢你。我不会忘记你的仁慈的……"
D.Strings[104403]="请……别忘了我们。别忘了我们的牺牲……"
D.Strings[104404]="燃烧军团已经包围了艾泽拉斯人。人人都得尽自己的义务！"
D.Strings[104405]="你最近复活过什么有趣的生物吗？"
D.Strings[104406]="宝藏大师伊克里格德对你做了一个粗鲁的手势。"
D.Strings[104407]="|TInterface\\ICONS\\INV_Artifact_PoweroftheDarkSide.blp:20|t堕落的化身正在召唤|cFFFF0404|Hspell:242017|h[漆黑之风]|h|r!"
D.Strings[104408]="|TInterface\\Icons\\SPELL_FIRE_FELRAINOFFIRE:20|t%s正在施放|cFFFF0000|Hspell:240910|h[末日决战]|h|r！"
D.Strings[104409]="|TInterface\\Icons\\Ability_Socererking_arcanemines:20|t%s制造了一个|cFFFF0000|Hspell:235059|h[断裂奇点]|h|r！"
D.Strings[104410]="你最近发现什么珍稀动物了吗？"
D.Strings[104411]="目前什么都没有。"
D.Strings[104412]="你那个袋子里有什么稀罕的恶魔小玩意儿吗？"
D.Strings[104413]="愿圣光照耀着你，我的朋友。你该安息了。"
D.Strings[104414]="不，我不能死！我还有家庭……我不能丢下他们！没有我，他们该怎么活下去？"
D.Strings[104415]="我在哪儿？当时我正在破碎海滩战斗……你能听见我说话吗？诸神在上……我是不是……死了？"
D.Strings[104416]="我……找不到我的身体了。我一直被关在灵魂引擎里，而现在……我的身体呢？我怎么了？！"
D.Strings[104417]="啊！盒子里是什么呢？！这里面原本是什么？！"
D.Strings[104418]="哈哈！太迟了，凡人！"
D.Strings[104419]="又是你？你别想抢走我的宝藏！"
D.Strings[104420]="太迟了！我已经拿到宝贝了！"
D.Strings[104421]="破碎海滩。"
D.Strings[104422]="破碎海滩是一片支离破碎的荒凉之地。我现在明白为什么一定要亲眼看看它了。"
D.Strings[104423]="|TINTERFACE\\ICONS\\SPELL_FIRE_FELPYROBLAST.blp:20|t堕落的化身施放了|cFFFF0404|Hspell:234418|h[毁灭之雨]|h|r!"
D.Strings[104424]="|TInterface\\Icons\\spell_hunter_lonewolf:20|t%s开始施放|cFFFF0404|Hspell:241772|h[恐怖嗥叫]|h|r!"
D.Strings[104425]="|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t%s将你选为了|cFFFF0000|Hspell:236011|h[折磨哀嚎]|h|r的目标！"
D.Strings[104426]="当然！请给我1级和2级的破碎群岛探路者技能，以及职业坐骑的最后一环任务！"
D.Strings[104427]="你！能帮我们测试一下破碎群岛的飞行机制吗？\n\n为了给这笔交易加码，我还会向你发放职业坐骑任务！\n\n你怎么说？"
D.Strings[104428]="我喜欢这个冰冻背包！哈哈！"
D.Strings[104429]="食人魔冰棍！哈！"
D.Strings[104430]="哈哈！愚蠢的冰冻食人魔。"
D.Strings[104431]="你确定要制作这件物品吗？这枚制甲工匠的奖章只能让你选择制作一件传说物品。"
D.Strings[104432]="我想制作板甲腰带。\n|TINTERFACE\\ICONS\\INV_Plate_DraenorCrafted_D_01Buckle.blp:32|t\n|Hitem:146667:0:0:0:0:0:0:0:110:0|h[瑞苏的不竭勇气]|h"
D.Strings[104433]="我想制作链甲手套。\n|TINTERFACE\\ICONS\\INV_GAUNTLETS_PLATE_RAIDPALADIN_I_01.BLP:32|t\n|Hitem:146668:0:0:0:0:0:0:0:110:0|h[警戒栖木]|h"
D.Strings[104434]="我想制作皮甲靴子。\n|TINTERFACE\\ICONS\\INV_Leather_RaidDemonHunterMythic_Q_02Boots.blp:32|t\n|Hitem:146669:0:0:0:0:0:0:0:110:0|h[哨兵的永恒庇护所]|h"
D.Strings[104435]="我想制作布甲护肩。\n|TINTERFACE\\ICONS\\INV_SHOULDER_CLOTH_RAIDWARLOCK_L_01.BLP:32|t\n|Hitem:146666:0:0:0:0:0:0:0:110:0|h[塞露布拉，暗夜的双子]|h"
D.Strings[104436]="现在，最重要的是：我们得决定你想做哪一类护甲。选的时候慎重点——这个奖章只够你学一堂课的。"
D.Strings[104437]="至于其他人，我们回学院去吧。显然你们还得再学上几百年。"
D.Strings[104438]="我……我喜欢好的铭文。记得保持……联系。"
D.Strings[104439]="你理应得到奖赏！给，希望它能对你有用。"
D.Strings[104440]="赞美艾露恩！谢谢你，英雄！"
D.Strings[104441]="漂亮的小鸟想要亮晶晶的金币吗？"
D.Strings[104442]="你有什么东西可卖吗？"
D.Strings[104443]="噢，铭文？我就喜欢别人写我的……强势生活。我知道一个小秘密。一个黑暗的秘密。\n\n你会去跟别人八卦吗？我就会。"
D.Strings[104444]="我自由了！你要为对我的侮辱永远痛苦下去，精灵！"
D.Strings[104445]="<拼命眨眼。>"
D.Strings[104446]="噢……好冷啊。你能行行好，为我燃烧你自己吗？"
D.Strings[104447]="噢，你有着美味的高尚品德。"
D.Strings[104448]="噢，你真可爱，可我已经跟别人签约了。"
D.Strings[104449]="唔……？唔。"
D.Strings[104450]="啊，没错，我知道它在哪儿。在卡拉赞荒废前，我和卡德加在我的密室里对它做过一些研究，它应该还在那儿。但我们恐怕没有太多时间去深入了解它。$b$b一般来说，去我的密室是很容易的事，但这个地下室里的恶魔恐怕挡住了通向密室的传送门。$b$b想办法在地下室里杀出一条路来，你就能找到另一边的传送门。三重火碟应该还在那儿。"
D.Strings[104451]="我来询问有关三分火碟的事。"
D.Strings[104452]="请接受这份报酬吧。"
D.Strings[104453]="祝……祝福你……多亏了你，我……我会活下去的！"
D.Strings[104454]="|TInterface\\Icons\\SPELL_FIRE_TWILIGHTFLAMEBREATH.BLP:20|t%s开始施放|cFFFF0000|Hspell:233983|h[回响之痛]|h|r！"
D.Strings[104455]="稍等一会儿，$n。让我们先完成手头这件护甲吧。"
D.Strings[104456]="看来你确实参加过！很好，我们开始吧。我会教你制作梦寐以求的传说护甲！"
D.Strings[104457]="我给你带来了制甲工匠的奖章。"
D.Strings[104458]="感谢你！请收下这个箱子吧。这是你应得的！"
D.Strings[104459]="救命！他们想抢我的补给！"
D.Strings[104460]="克索诺斯是不会被……击败的……"
D.Strings[104461]="恐惧战马是我的，术士……我的！"
D.Strings[104462]="我要碾碎你，爬虫！"
D.Strings[104463]="你要为你的罪行付出代价，术士！"
D.Strings[104464]="毫无疑问，你已经狠狠回敬了那些入侵我们森林的怪物。但如果我们能从水域本身抽出更多……邪恶的……腐蚀，那也将是一个重大的胜利！我建议你用鱼竿试试。"
D.Strings[104465]="<她扭着头，一脸厌恶地伸手接过了水球。>\n\n谢谢你。我很乐意摧毁它。"
D.Strings[104466]="腐蚀扼杀了我们的水域，杀害了那里曾经欣欣向荣的自然生物。我们必须反击！"
D.Strings[104467]="噢！最重要的是，锦鲤的数量好像太多了。如果你能抓到一些鲦鱼，我或许可以把它们放进河里？\n\n小心水族馆的守卫玛吉库斯。"
D.Strings[104468]="太棒了！来，把它们放进我的魔法水球里，剩下的就交给我了。\n\n<莎乐丝看着小鱼出了神。>"
D.Strings[104469]="在被流放之前，我是城里的水族馆管理员。我仍然要为水箱里的那些小生命负责，我是不会抛弃它们的。"
D.Strings[104470]="这只渡鸦看了看脚边闪闪发亮的卵石，然后又看了看水面。你的直觉告诉你，或许能用鱼竿找回它们。"
D.Strings[104471]="科尔宾高兴地叫了一声。"
D.Strings[104472]="这只渡鸦歪着脑袋看了看你。"
D.Strings[104473]="我正在收集那个碎裂图腾的碎片，也许有几百、甚至上千块。如果你运气够好，或许能用鱼竿钓到它们。"
D.Strings[104474]="<阿库勒仔细研究了碎片。>\n\n对，这些就是当初那个图腾的碎片。谢谢你，$c。"
D.Strings[104475]="许多年前，一个仪式图腾被闪电劈裂，遗失在这片水域。我想修复它，以纪念我的祖先。"
D.Strings[104476]="用鱼竿钓起海草！把海草给英帕斯！一点都不准留！"
D.Strings[104477]="英帕斯对仆从的工作很满意。"
D.Strings[104478]="英帕斯正在造船。你来帮忙！"
D.Strings[104479]="谢谢你，朋友！作为奖励，请接收我的一部分力量吧。愿它能帮你战胜我们的敌人。"
D.Strings[104480]="我箭无虚发！"
D.Strings[104481]="你休想躲过我的箭雨！"
D.Strings[104482]="站稳了，守夜人们！敌人来了！"
D.Strings[104483]="守夜人绝不会抛弃职责！"
D.Strings[104484]="拿起武器，守夜人们！军团来了！"
D.Strings[104485]="噢，拜托！这可不在我的教学计划之内！"
D.Strings[104486]="愿意永远跟我……一起冒险吗？"
D.Strings[104487]="快点！我们不可能一直等下去！"
D.Strings[104488]="你，让大家看看那个咒语该怎么用。"
D.Strings[104489]="现在，如果你们听过上一堂课，就会知道该用什么咒语把它炸成一团火球。"
D.Strings[104490]="别担心，学徒们，这个恶魔已经被安全地关入了魔法矩阵。"
D.Strings[104491]="呃……那个咒语怎么念来着？Ru shallora……呃……唔……abracadabra？"
D.Strings[104492]="教官，我不认为……"
D.Strings[104493]="<传送门散发着能量。门的另一端传来了尖叫声和其他令人不安的噪音。>\n\n等你获得更多虚空碎片后再来吧。"
D.Strings[104494]="谢谢你，$n！这正是我需要的。"
D.Strings[104495]="它很美，不是吗？你感觉到它的力量在你体内流淌、脉动，不断扰动我们周围的世界了吗？如果你愿意，我可以控制那股力量……"
D.Strings[104496]="有几个防护法术被打破了，它们开始消散了。我也不想这么说，但你恐怕得用鱼竿来钓起那些碎片了。"
D.Strings[104497]="勇士，我为你带来了法罗迪斯王子的礼物。我的法术能让你暂时变得更有力、更敏捷、更强大。请上前来接受你的礼物吧。"
D.Strings[104498]="英雄，我为你带来了艾尔的眷顾！请上前来接受她的祝福吧。"
D.Strings[104499]="很抱歉，我不能……"
D.Strings[104500]="我曾做过同样的梦，而且都梦到了你！"
D.Strings[104501]="但愿你能找到他。"
D.Strings[104502]="$n在乌瑞恩之陨激活了一座不稳定的虚空传送门！"
D.Strings[104503]="$n在暗影断口激活了一座不稳定的虚空传送门！"
D.Strings[104504]="$n在悲泣平台激活了一座不稳定的虚空传送门！"
D.Strings[104505]="$n在扭曲之地激活了一座不稳定的虚空传送门！"
D.Strings[104506]="$n在惊悚洞穴激活了一座不稳定的虚空传送门！"
D.Strings[104507]="$n在终末海滩激活了一座不稳定的虚空传送门！"
D.Strings[104508]="$n在幽灵废墟激活了一座不稳定的虚空传送门！"
D.Strings[104509]="$n在士兵之难激活了一座不稳定的虚空传送门！"
D.Strings[104510]="$n在啸风崖激活了一座不稳定的虚空传送门！"
D.Strings[104511]="$n在受难小径激活了一座不稳定的虚空传送门！"
D.Strings[104512]="$n在月光高地激活了一座不稳定的虚空传送门！"
D.Strings[104513]="$n在锯齿海湾激活了一座不稳定的虚空传送门！"
D.Strings[104514]="$n在鬼哭小径激活了一座不稳定的虚空传送门！"
D.Strings[104515]="$n在邪能要塞激活了一座不稳定的虚空传送门！"
D.Strings[104516]="$n在邪秽海滩激活了一座不稳定的虚空传送门！"
D.Strings[104517]="$n在魔誓地穴激活了一座不稳定的虚空传送门！"
D.Strings[104518]="$n在邪怒海滩激活了一座不稳定的虚空传送门！"
D.Strings[104519]="$n在邪火小径激活了一座不稳定的虚空传送门！"
D.Strings[104520]="$n在魔尘洞穴激活了一座不稳定的虚空传送门！"
D.Strings[104521]="$n在邪裂洞穴激活了一座不稳定的虚空传送门！"
D.Strings[104522]="$n在死木港激活了一座不稳定的虚空传送门！"
D.Strings[104523]="$n在黑暗监牢激活了一座不稳定的虚空传送门！"
D.Strings[104524]="$n在新月废墟激活了一座不稳定的虚空传送门！"
D.Strings[104525]="$n在痛苦海滩激活了一座不稳定的虚空传送门！"
D.Strings[104526]="$n在燃烬渠激活了一座不稳定的虚空传送门！"
D.Strings[104527]="我说不出话来了……我是这世界上最快乐的人！出发吧，下一场冒险在等着我们！"
D.Strings[104528]="我……我明白了。"
D.Strings[104529]="是你吗？……就是你！我有很多话要告诉你！该从哪儿开始呢？\n\n在经历过第一次冒险后，我就再也没法集中精神做任何事了，满脑子都是下一次冒险会是什么样。我的朋友们都说你是假的，我是在发疯，你只是个梦中的幻象。我就知道他们错了！那种感觉绝对不止是梦！\n\n我们经历过的每一次冒险，打倒的每一个敌人和聊过的每一句话都让我忍不住想问你……"
D.Strings[104530]="我会一直等下去，我知道他会来的！"
D.Strings[104531]="在你开口前，我也不知道这人长什么样。在我的第一个梦里，他是暗夜精灵。第二个梦里，他就变成了牛头人。到了第三个梦，他又成了暗夜精灵。在那些梦里，我们走遍了艾泽拉斯和德拉诺，对抗恶魔、巨龙、上古之神，甚至是鱼人！\n\n我以前的生活从来没有跟冒险沾过边。它们在我看来是那么真实。在我的最后一个梦里，我让他来这里见我。"
D.Strings[104532]="是你吗？！我梦中的那个人？！"
D.Strings[104533]="<肖恩期待地看着你>"
D.Strings[104534]="这当然不容易，但我们设法为你的勇士们弄到了一件最高品质的装备。\n\n不幸的是，我们的补给品极其有限，所以我们在分发时一定要格外小心。"
D.Strings[104535]="愿大地母亲与你同在，英雄！请走到图腾阵中来，接受她的祝福吧。"
D.Strings[104536]="战争领主，你准备好后，就用这座传送门回苍穹要塞吧。"
D.Strings[104537]="踢它！打它！烧死它！"
D.Strings[104538]="事实上，我想看看你的表演。"
D.Strings[104539]="你能闭嘴吗？"
D.Strings[104540]="又是你？\n\n你瞧，我不是来你这儿教你怎么做个$c的，所以你为什么还不滚？"
D.Strings[104541]="我只为最精锐的角斗士服务。"
D.Strings[104542]="嘿，伙计，除了打断演员的表演，你就没有其他事可干了吗？"
D.Strings[104543]="铲除这些邪恶的蠕虫有助于恢复这片海滩的平衡。谢谢你，英雄。"
D.Strings[104544]="<这只狗的毛皮油光水滑的，看起来十分健康。布琳妮显然把它照顾得很好。>\n\n<可它是怎么过来的？>"
D.Strings[104545]="<把取自达拉然街道的石子拿给这只狗看。>"
D.Strings[104546]="<这只狗嗅了嗅石子，舔了舔你的手，示意你放心。>"
D.Strings[104547]="<这只狗摇着尾巴，努力保持着坐姿，压抑着跳到你身上来的冲动。时隔多日，它很高兴能再次见到你。>"
D.Strings[104548]="但你得小心点，$n。如果森提纳克斯号派来的援军太多，你或许就要面对一场必败的战斗了……"
D.Strings[104549]="但是，如果你想战斗——或是，如果你想要虚空碎片——使用这些信标或许也不算什么坏事。"
D.Strings[104550]="这些信标在直接向森提纳克斯号请求支援。那很危险。"
D.Strings[104551]="哈！熏死他们！我不会因此被炒掉吧？人总要保持乐观嘛。你干得还是那么好，勇士。"
D.Strings[104552]="燃烧军团想扩大地盘。如果你能扑灭这个威胁，我们会很感激的，指挥官。"
D.Strings[104553]="使用|TInterface\\Icons\\SPELL_SHADOW_ENSLAVEDEMON.BLP:20|t |cFFFF0000|Hspell:111771|h[奴役恶魔]|h|r魅惑愤怒战马！"
D.Strings[104554]="我们派米妮瓦到前头去侦查了。使用黑锋之门，到冰冠堡垒去见她吧。"
D.Strings[104555]="把你自己献给军团吧。"
D.Strings[104556]="我愿用灵魂换取邪能之力！"
D.Strings[104557]="我自愿效忠燃烧军团。"
D.Strings[104558]="纳迦必胜……"
D.Strings[104559]="军团许诺会给我们力量，比艾萨拉女王更强大的力量！"
D.Strings[104560]="砍掉那些凡人的脑袋！"
D.Strings[104561]="军团休想击败我们！"
D.Strings[104562]="我们同时遭到了来自地面和空中的袭击，小心脑袋！"
D.Strings[104563]="暗影必胜！"
D.Strings[104564]="放弃吧！让它吞噬你！"
D.Strings[104565]="阿古斯！我深爱的故乡……他们做了什么？"
D.Strings[104566]="开始挑战冷酷的加苏尔。"
D.Strings[104567]="今晚，我们将享用凡人的血肉！"
D.Strings[104568]="你好，$c。我必须完成研究。\n\n你愿意帮我吗？"
D.Strings[104569]="这下纳迦该明白，和军团做交易是不会有好下场的。"
D.Strings[104570]="这些纳迦的首领要用人民的生命向军团换取力量。这些蠢货自愿赶来，却不知道它的代价。去告诉他们。"
D.Strings[104571]="你们的灵魂即将湮灭！"
D.Strings[104572]="我掌控着无尽的毁灭。"
D.Strings[104573]="让混沌吞噬你们！"
D.Strings[104574]="杀光凡人，把他们支离破碎的尸体给我带回来！"
D.Strings[104575]="我送你们上船！消灭他们，别让欺诈者更加强大！"
D.Strings[104576]="放弃吧！你们迟早会加入我们，俯首称臣的！"
D.Strings[104577]="你们的命运也会和他们一样！"
D.Strings[104578]="燃烧军团来收割你们的灵魂了！"
D.Strings[104579]="反抗我们的世界都陨落了。"
D.Strings[104580]="维伦当年的顽抗早已注定了你们的败亡。"
D.Strings[104581]="你们的生命无足轻重！我们是不朽的！"
D.Strings[104582]="面对命运吧！"
D.Strings[104583]="屈服于恐惧和欲望吧！"
D.Strings[104584]="谁会给你陪葬呢？"
D.Strings[104585]="吞噬他们！"
D.Strings[104586]="闷烧吧！痛苦吧！"
D.Strings[104587]="末日在召唤！"
D.Strings[104588]="快过来，我能恢复你们的视觉！"
D.Strings[104589]="小心，勇士们！注意接下来的幻象！"
D.Strings[104590]="我要用尖牙和利爪阻止他们！"
D.Strings[104591]="恶魔不会放过我们的！为了荒野！"
D.Strings[104592]="燃烧军团来了！我们要保卫家园！"
D.Strings[104593]="标记敌人，我来打倒它！"
D.Strings[104594]="你的远征结束了！"
D.Strings[104595]="这将是你们的最后一战！"
D.Strings[104596]="来吧。就算死在虚空，我们也要让欺诈者给我们陪葬！"
D.Strings[104597]="没错。只能这样了。去吧，勇士们！时间宝贵，我们得在传送门关闭前救回维伦。"
D.Strings[104598]="该去面对我们的命运了。我们必须得用传送门跟着欺诈者进入深渊。只有这个办法！"
D.Strings[104599]="封印传送门也无济于事，大法师。无论是花上几年还是千年，燃烧军团还是会一次次归来，直到我们无力抵抗。"
D.Strings[104600]="维伦！停下！"
D.Strings[104601]="不！我不想再逃避了！我要结束这一切！"
D.Strings[104602]="|TINTERFACE\\ICONS\\Ability_BossFelMagnaron_HandEmpowered.blp:20|t你获得了|cFFFF0000|Hspell:235271|h[灌注]|h|r效果！"
D.Strings[104603]="我想传送到基尔加丹处。"
D.Strings[104604]="我想传送到堕落的化身处。"
D.Strings[104605]="我想传送到戒卫侍女处。"
D.Strings[104606]="我想传送到恶魔审判庭处。"
D.Strings[104607]="我想传送到绝望的聚合体处。"
D.Strings[104608]="我想传送到月之姐妹处。"
D.Strings[104609]="我想传送到主母萨丝琳处。"
D.Strings[104610]="我想传送到哈亚坦处。"
D.Strings[104611]="我想传送到“混混”哈亚坦处。"
D.Strings[104612]="噢，你好，我们的布置还没有完成。\n\n如果你想见识一下比E.T.C.更致命更重磅的东西，那一定要来看看这个。\n\n你能帮我们宣传宣传吗？这将会是一场你绝对不想错过的视听盛宴！"
D.Strings[104613]="艾露恩会帮助那些保卫这片土地，勇敢抵抗燃烧军团的人。英雄，请走到月光中来，接受她的祝福吧。"
D.Strings[104614]="我要去萨格拉斯之墓（团队副本）。"
D.Strings[104615]="我要去永夜大教堂（地下城）。"
D.Strings[104616]="想知道打败燃烧军团的关键吗？\n\n是造房子，伙计。\n\n房子和更多的房子。哎呀！\n"
D.Strings[104617]="|TINTERFACE\\ICONS\\ability_fixated_state_red.blp:20|t一名锋颚角斗士锁定了你！"
D.Strings[104618]="主母萨丝琳召唤了一个暗鳞监工！"
D.Strings[104619]="你让他们逃过了一劫。圣光感谢你，英雄。"
D.Strings[104620]="勇士，军团将被俘的战士折磨得奄奄一息。救救他们，别让他们的圣火熄灭！"
D.Strings[104621]="我想把所有的金色鲦鱼都给你。"
D.Strings[104622]="你好啊，漂亮的小鸟。你想要这些亮晶晶的玩意儿吗？"
D.Strings[104623]="看来我找到了一些你急需的恶心水珠。"
D.Strings[104624]="干得好！解决了海怪的威胁后，我们就能集中精力对付军团了。"
D.Strings[104625]="我找到了许多图腾碎片。请收下吧。"
D.Strings[104626]="好吧。把这些被亵渎的海草都拿走吧。"
D.Strings[104627]="让邪能吞噬你！"
D.Strings[104628]="哈亚坦的|cFFFF0404|Hspell:232192|h[命令咆哮]|h|r引起了附近鱼人的注意！"
D.Strings[104629]="我其实挺喜欢鱼人的。但邪能鱼人……还是算了。"
D.Strings[104630]="邪能……鱼人？军团真是饥不择食啊。去解决它们，好吗？"
D.Strings[104631]="真不明白怎么会有人在意这些…这么恶心的生物。让我们来关心一些更紧急的事务吧。"
D.Strings[104632]="军团居然堕落到腐蚀这片海滩的鱼人。快去阻止这种亵渎行为！"
D.Strings[104633]="你的亮晶晶，给他们！"
D.Strings[104634]="这是我们的路，走开！"
D.Strings[104635]="此山是我开！"
D.Strings[104636]="这是我的峭壁，你死定了！"
D.Strings[104637]="可悲！真是浪费时间。现在有了墓穴的力量，我要杀光你们！"
D.Strings[104638]="看来，你和这世界的其他人一样蠢，想要挑战我？很好。"
D.Strings[104639]="%s触发了一个古老的防护法术！"
D.Strings[104640]="苏拉玛的鱼类都是我的朋友。"
D.Strings[104641]="我想净化这里的水域。"
D.Strings[104642]="这只渡鸦疑惑地看着你。"
D.Strings[104643]="河流在召唤我。"
D.Strings[104644]="英帕斯也不知道他为什么会在这里。"
D.Strings[104645]="有点意思。"
D.Strings[104646]="我要跟水流沟通了……"
D.Strings[104647]="请跟我去海滩吧。"
D.Strings[104648]="空虚……"
D.Strings[104649]="穿刺！"
D.Strings[104650]="占据！"
D.Strings[104651]="烙印！"
D.Strings[104652]="烈火！"
D.Strings[104653]="我得警告你，爆蛋器偶尔会导致海怪蛋孵化，而不是爆炸。科技进步总要有点小代价，不是吗？"
D.Strings[104654]="不过……我也不想剥夺你们死于古老奇迹之手的机会。就让这化身了结你们吧！"
D.Strings[104655]="你们眼前的躯壳曾承载过萨格拉斯的力量。但这座圣殿才是我们想要的。它能让我们将这世界化为灰烬！"
D.Strings[104656]="真是大言不惭，维伦。你枉为先知，总看不清我们世界注定的命运……所有世界注定的命运。"
D.Strings[104657]="|CFFF00000警告|R这将召唤出一个危险的敌人，需要数名英雄才能将其击败。摧毁此传送门将使你损失100枚虚空碎片。"
D.Strings[104658]="我准备好清扫煞魔了。"
D.Strings[104659]="我是恐怖图腾部族的玛加萨·恐怖图腾。我是部族的主母和巫婆长老。$b$b虽然贝恩将我逐出了雷霆崖，但我才是牛头人所需要的领袖。他们整天闲坐在帐篷里，等着联盟和燃烧军团不费吹灰之力地碾过他们。我和我的人民绝不会坐视那种事发生。我们要尽力生存下去。$b$b燃烧军团进攻了。恐怖图腾需要我。你是要来帮忙，还是要阻拦我呢？"
D.Strings[104660]="我已经清除了煞魔。"
D.Strings[104661]="使用虚空碎片令其过载[100]"
D.Strings[104662]="<这座传送门散发着能量。门的另一边传来了尖叫和其他令人不安的噪音。>"
D.Strings[104663]="煞魔余孽清除得怎么样了？"
D.Strings[104664]="你清除了大量的煞魔余孽，大宗师。我们感谢你的帮助。"
D.Strings[104665]="你好，大宗师$n。欢迎你的到访。我们正在全力清扫本地残余的煞魔。$b$b如果你能帮我们完成这个任务，或许我们也能帮你。你说呢？"
D.Strings[104666]="我是大地之环的先知。你是谁？"
D.Strings[104667]="你是这里的头儿？"
D.Strings[104668]="我找回了一些你想要的精华。请都拿走吧。"
D.Strings[104669]="我是恐怖图腾的玛加萨，你们得听我的！"
D.Strings[104670]="恶魔关不了我们多久。"
D.Strings[104671]="我得回营地去报告！"
D.Strings[104672]="攀爬"
D.Strings[104673]="如你所愿，女祭司。"
D.Strings[104674]="当然，我想试试。能出什么麻烦呢？"
D.Strings[104675]="再次感谢你。我们不会忘记你的善良的！"
D.Strings[104676]="我和我的姐妹们都欠你一条命。我们手中也没多少物资，但你可以从我们的补给中随便挑些有用的东西。"
D.Strings[104677]="愿艾露恩祝福你，勇士。看来这片林地已经无法再庇护我们不受燃烧军团侵害了。"
D.Strings[104678]="军团想靠亵渎这座昔日的圣殿来击溃我们的意志。你已证明了我们是不会被击垮的！"
D.Strings[104679]="基尔加丹喜欢派党羽来亵渎教堂。将这个恶心的怪物赶出我们的世界。"
D.Strings[104680]="那个审判官最喜欢让它的受害者充当炮灰。它是罪有应得。"
D.Strings[104681]="教堂里藏着一个审判官，它在驱使阵亡将士的灵魂对付我们。让它尖叫着滚回虚空去吧。"
D.Strings[104682]="杀得好。那个自大狂休想召唤出其他恶魔。"
D.Strings[104683]="我感觉到了一股堕落力量。去消灭它，削弱他们对教堂的控制。"
D.Strings[104684]="那头野兽倒下了。很好！基尔加丹很快也会倒下。"
D.Strings[104685]="军团召唤了一头嗜好凡人血肉的贪婪野兽。去消灭这怪物，别让它被放出来！"
D.Strings[104686]="很好。永夜大教堂摆脱了欺诈者的控制，让他暴跳如雷去吧。"
D.Strings[104687]="基尔加丹派了一位将军来视察永夜大教堂。去干掉她吧。"
D.Strings[104688]="我准备好前往斯考德-艾希尔了。\n\n我们可以出发了吗？"
D.Strings[104689]="起飞，我的宠物们！耶！"
D.Strings[104690]="吃点苦头吧！"
D.Strings[104691]="必须完成军团的任务。"
D.Strings[104692]="啊……终于。"
D.Strings[104693]="让这痛苦结束吧！"
D.Strings[104694]="那些恶魔想束缚元素。蠢货！现在他们明白这种亵渎行为的代价了！"
D.Strings[104695]="这些艾瑞达外行想用能量核心来制伏元素。去教教他们，这种力量是不能乱来的！"
D.Strings[104696]="这些灵魂选择了自己的命运！"
D.Strings[104697]="你们都将臣服于燃烧军团。我发誓！"
D.Strings[104698]="我的死也无法解除契约！"
D.Strings[104699]="这些灵魂属于燃烧军团！"
D.Strings[104700]="这改变不了什么。"
D.Strings[104701]="我的命运早已注定。"
D.Strings[104702]="死亡也无法带来安宁。"
D.Strings[104703]="我的痛苦永无止尽！"
D.Strings[104704]="我死后也无法解脱……"
D.Strings[104705]="这不是我的本意！"
D.Strings[104706]="我控制不了自己了。"
D.Strings[104707]="离开这里，$c！"
D.Strings[104708]="你确定要在达到19级时停止获取经验吗？"
D.Strings[104709]="我希望在达到19级时停止获取经验。"
D.Strings[104710]="真巧。她也不喜欢你。\n\n现在，快去干活儿吧。别让这玩意儿另一边的艾瑞达发现我动了手脚，关了传送门。"
D.Strings[104711]="我不喜欢这个恶魔。"
D.Strings[104712]="听说你为我准备了一个“出租恶魔？”"
D.Strings[104713]="敌人来了……我们快走！"
D.Strings[104714]="继续走！这里不安全……"
D.Strings[104715]="我们得快点，外来者！"
D.Strings[104716]="我没想到……"
D.Strings[104717]="这是个残酷又悲伤的地方。"
D.Strings[104718]="英雄，这边。"
D.Strings[104719]="别说教了！杀了他们！"
D.Strings[104720]="月神会高兴的，月葬！"
D.Strings[104721]="女神祝福你的箭矢！"
D.Strings[104722]="瞄得真准，姐妹！"
D.Strings[104723]="别浪费时间了。消灭他们！"
D.Strings[104724]="愿暗夜战士指引你，姐妹！"
D.Strings[104725]="锐不可当！"
D.Strings[104726]="你挡我道了！"
D.Strings[104727]="正中目标！"
D.Strings[104728]="认罪吧！忏悔吧！"
D.Strings[104729]="月神，揭露他们的罪孽！"
D.Strings[104730]="付出代价吧，异端！"
D.Strings[104731]="见证她的荣耀吧！"
D.Strings[104732]="女神，烧死无信者！"
D.Strings[104733]="尝尝他们的血肉，宠物！"
D.Strings[104734]="我瞄准你了！"
D.Strings[104735]="神罚天降！"
D.Strings[104736]="艾露恩之光照耀万物！"
D.Strings[104737]="我来，姐妹。我的战刃在欢唱！"
D.Strings[104738]="亚萨，我来解决异教徒！"
D.Strings[104739]="别磨蹭了，卡丝帕莲！胜利是我的！"
D.Strings[104740]="艾露恩……原谅我们……"
D.Strings[104741]="不！我……应该……赢的……"
D.Strings[104742]="我们辜负了……女神……"
D.Strings[104743]="下次让我先出击！"
D.Strings[104744]="神殿安全了。打得好，姐妹们！"
D.Strings[104745]="月神赐予了我们胜利！"
D.Strings[104746]="效率真低……但效果不错。"
D.Strings[104747]="你取悦了女神，姐妹！"
D.Strings[104748]="你应该信仰女神！"
D.Strings[104749]="你的弓蒙受神恩！"
D.Strings[104750]="杀得好，姐妹！"
D.Strings[104751]="猎物倒下了！"
D.Strings[104752]="女神会高兴的，姐妹！"
D.Strings[104753]="杀得有点慢，姐妹！"
D.Strings[104754]="狩猎结束了！"
D.Strings[104755]="你太冲动了，卡丝帕莲。"
D.Strings[104756]="愿女神指引你！"
D.Strings[104757]="我先上了，姐妹们！"
D.Strings[104758]="我随时准备着，卡丝帕莲。"
D.Strings[104759]="姐妹们！小心！"
D.Strings[104760]="亵渎者！必须把他们赶出艾露恩的圣殿！"
D.Strings[104761]="对！让他们来吧！他们的尸体将成为点燃世界的燃料！"
D.Strings[104762]="干得好。恶魔损失惨重，别想那么快恢复了。"
D.Strings[104763]="杀光恶魔，毁掉他们的堡垒！"
D.Strings[104764]="破碎海滩可不适合独行。我们得找到安度因，否则就迟了！"
D.Strings[104765]="我这就去安排船！"
D.Strings[104766]="现在，该我向他们学习了。带我去父亲牺牲的地方吧。我要亲眼看看那里。"
D.Strings[104767]="总有像提里奥和伯瓦尔……还有我父亲那样的英雄用生命保护着我。"
D.Strings[104768]="我们家族的国王总是为了暴风城的自由，与他们的士兵并肩作战。"
D.Strings[104769]="我的曾祖父拜拉瑟恩国王，祖父莱恩国王，也为此而牺牲。"
D.Strings[104770]="我父亲不是第一个为抗击军团而死的暴风城国王。"
D.Strings[104771]="一次又一次，我远远观望着暴风城的英雄为了维护艾泽拉斯的和平而流血牺牲。"
D.Strings[104772]="我母亲死后，他只有我了。"
D.Strings[104773]="我父亲想让我远离战争，说暴风城离不开乌瑞恩家族的统治，坚持让我留下。但他的眼睛骗不了我……他怕失去我。"
D.Strings[104774]="这里比我想的还要糟。"
D.Strings[104775]="来，我们前进吧。"
D.Strings[104776]="这里简直满目疮痍，根本不适合长眠。"
D.Strings[104777]="这就是我们部队登上破碎海滩的地方。"
D.Strings[104778]="这就行了！那么……卡塔拉克？卡萨克斯？你是怎么念出来的？"
D.Strings[104779]="我要躲在这里，直到这一切都结束为止。"
D.Strings[104780]="你找到了？太好了！我正在烦恼该换什么礼物呢……"
D.Strings[104781]="英雄！我飞过来的时候出了一点小事故。我弄丢了一些特别的硬币，那是要送给……额，算了。如果你能找到并把它们送回来，那我将感激不尽！"
D.Strings[104782]="伤得太重……我得休息一下了……"
D.Strings[104783]="%s召唤了一名恶魔副官！"
D.Strings[104784]="%s强化了恶魔传送门！"
D.Strings[104785]="%s延长了恶魔传送门的持续时间！"
D.Strings[104786]="%s召唤了一座恶魔传送门！"
D.Strings[104787]="军团长存……"
D.Strings[104788]="你的盟友们的尸体将成为我的孩子们口中的美餐！"
D.Strings[104789]="|TInterface\\Icons\\inv_egg_01:20|t一堆孵化的蛋|cFFFF0404|Hspell:240319|h[正在孵化]|h|r！"
D.Strings[104790]="蜘、蜘、蜘蛛……"
D.Strings[104791]="终于……又能呼吸了。"
D.Strings[104792]="我感觉毒素正在离开我的血管。谢谢你！"
D.Strings[104793]="勇士，我们脚下的土地正在腐烂。腐朽的生物时刻都在扩散。你得消灭它们！"
D.Strings[104794]="亲爱的柯瑞安……没有你我该怎么办？"
D.Strings[104795]="谢谢你，陌生人！那些小鬼都是凭空冒出来的！我手头也不宽裕，但你理应得到奖赏。看看我们的补给，挑你需要的拿吧。"
D.Strings[104796]="看来他们回归大地了。"
D.Strings[104797]="那些傲慢的艾瑞达以为能号令艾泽拉斯的大地？制裁它们！"
D.Strings[104798]="这不是请求。<对他使用绞袭。>"
D.Strings[104799]="别担心，先知……我们会盯着末日石的。"
D.Strings[104800]="没有她，你会更强！"
D.Strings[104801]="别听她的！我才是这里唯一、真正的力量之源！"
D.Strings[104802]="下次再来哦。我或许还有任务要交给你。"
D.Strings[104803]="完美的梦境……真是胡扯！这个世界只有痛苦，孩子。"
D.Strings[104804]="呸！我一点都不比潮汐之石差，更别说其他发霉的古董了！"
D.Strings[104805]="连她的残影都这么唠叨！你现在明白我的感受了吧？"
D.Strings[104806]="你叫我吗，耐普图隆？"
D.Strings[104807]="啊……只是一个力量残影。没什么好担心的，孩子。"
D.Strings[104808]="你亲眼见证了末日石的破坏力。你是艾泽拉斯的忠实守护者。可就算在你手中，它的力量依然在你的人民中引起了混乱和恐慌。想想吧，万一它落入不怀好意的人手里……$b$b我们不能让这种事情发生。$b$b在等待你醒来时，我们详细讨论了该怎么处理这件神器。我们原本打算将它送进某个元素位面，但每个位面都各有风险。$b$b对末日石来说，没有比这里更安全的地方了，这里是艾泽拉斯的中心。它将由大地之环妥善保管，绝对不能再次使用。把它放到这个基座上吧，不能再让它离开这里了。"
D.Strings[104809]="她还活着？不！她别想再束缚我！"
D.Strings[104810]="你好，先知。你好点了吗？"
D.Strings[104811]="欺诈者！我们是来终结你对艾泽拉斯的入侵的。你主人的远征结束了！"
D.Strings[104812]="我要吞噬你们的灰烬！"
D.Strings[104813]="邪能强化了我！"
D.Strings[104814]="撕裂现实！"
D.Strings[104815]="你们居然还活着！没关系。见证这奇迹吧，凡人！绝望吧！这世界将成为你们的坟墓！"
D.Strings[104816]="基尔加丹会从那些船上汲取力量！"
D.Strings[104817]="抵抗毫无意义！我的力量来自无穷大军！"
D.Strings[104818]="你们抵抗不了天性。"
D.Strings[104819]="我感觉到你内心的腐蚀。"
D.Strings[104820]="对抗内心的黑暗吧！"
D.Strings[104821]="什么？就算看到了自己的猜忌和恐惧，你们也不投降吗？"
D.Strings[104822]="顽强抵抗我的仆从并不困难。可你们敢面对内心的阴影吗？"
D.Strings[104823]="伊萨隆！去碾碎他们！"
D.Strings[104824]="承受我的怒火吧！"
D.Strings[104825]="燃烧吧！毁灭吧！"
D.Strings[104826]="还敢反抗？！我要回敬你的傲慢！"
D.Strings[104827]="无谓的挣扎！艾泽拉斯必将毁于军团之手！"
D.Strings[104828]="傲慢的凡人！从踏入虚空的那一刻，你们的命运就注定了！"
D.Strings[104829]="倒在我的利刃下吧！"
D.Strings[104830]="英雄！选个好目标吧！"
D.Strings[104831]="让我看看你的实力！瞄准敌人！"
D.Strings[104832]="别丧失信仰！"
D.Strings[104833]="你还不能死！"
D.Strings[104834]="愿圣光保佑你！"
D.Strings[104835]="倒下吧，英雄！"
D.Strings[104836]="这是命中注定的！"
D.Strings[104837]="魔誓者，盯住他们！"
D.Strings[104838]="术士们，烧死这些废物！"
D.Strings[104839]="邪脉精灵！让他们看看顽抗的下场！"
D.Strings[104840]="艾瑞达！让这些杂种看看抵抗是多么愚蠢！"
D.Strings[104841]="谁会来救你们？"
D.Strings[104842]="倒在主人面前吧！"
D.Strings[104843]="你们这些蠢货竟敢追来！"
D.Strings[104844]="不！你休想分开我们，欺诈者。我们会彼此信任，并肩作战。我们会一起结束你的远征！"
D.Strings[104845]="现在，你软弱的怒火又将盟友引向了毁灭。看着我的无穷大军杀光他们吧！"
D.Strings[104846]="圣光能救你的儿子吗？拉基什临死前，眼中闪烁的是信仰之光呢？还是对抛弃他的父亲的仇恨呢？"
D.Strings[104847]="是你失去了信仰。我们本可以携手阻止萨格拉斯，拯救阿古斯的！"
D.Strings[104848]="真的目光短浅！你这是在逃避军团必将胜利的现实！"
D.Strings[104849]="你跨越星海，不断追杀同胞的征程该结束了！"
D.Strings[104850]="我们出发吧，大领主，去营救失踪的战友！"
D.Strings[104851]="跟你一起上战场是种荣耀，大领主。"
D.Strings[104852]="很荣幸能与你并辔而行，大领主。"
D.Strings[104853]="我随时可以出发，大领主！"
D.Strings[104854]="传送门要关了！我们可以封印传送门，结束入侵了。"
D.Strings[104855]="绝不！远征不会停止！享受这短暂的胜利吧。我们还会回来的，一次又一次，直到彻底打垮你们！"
D.Strings[104856]="对！臣服于这力量吧！"
D.Strings[104857]="加把劲儿，孩子！你怎么回事？"
D.Strings[104858]="如此强大……如此混乱！"
D.Strings[104859]="你的力量太强了。你控制不了它！"
D.Strings[104860]="我撕裂了这世界的烈焰。现在，听我号令！"
D.Strings[104861]="萨格拉斯欺骗了你，基尔加丹。投降吧！结束了！"
D.Strings[104862]="还没从一再的失败中吸取教训吗，欺诈者？"
D.Strings[104863]="你们还要负隅顽抗！你们还要螳臂当车！这简直疯狂！你们怎么还不投降？"
D.Strings[104864]="……结束了……"
D.Strings[104865]="凡人……失败了。"
D.Strings[104866]="主人……必胜！"
D.Strings[104867]="终结！"
D.Strings[104868]="那个恶魔伤害的不仅是民众，还有土地本身！如果你还想用末日石，那就赶快！"
D.Strings[104869]="腐蚀必将被净化！"
D.Strings[104870]="守护者……"
D.Strings[104871]="劈斩！"
D.Strings[104872]="诅咒！"
D.Strings[104873]="凡人……死吧！"
D.Strings[104874]="杀了……你！"
D.Strings[104875]="别犹豫！别留手！打碎世界，结束一切！"
D.Strings[104876]="你的傀儡断线了，基尔加丹！"
D.Strings[104877]="该死的凡人！你们在这里四处钻营，打击我的部下，自以为能和军团抗衡。英雄……勇士……全是蠢货！"
D.Strings[104878]="结束……一切……"
D.Strings[104879]="可以开始窃取夜之子裁缝的秘诀了吗？"
D.Strings[104880]="让我听听你对时尚的见解吧。"
D.Strings[104881]="在我教你制造传奇物品前，你得先从时尚观学起。这没有商量的余地！可以开始了吗？"
D.Strings[104882]="就算被捕，我们的战士依然斗志昂扬。你的大地之环……真差劲。"
D.Strings[104883]="听到风声了吗，孩子？它在尖叫，祈求摆脱军团。"
D.Strings[104884]="想想威严的大地……象征坚实、守护、稳定。但它颤抖时，就会造成严重破坏。"
D.Strings[104885]="水的力量象征温和的滋养。它是最被动和柔弱的元素。军团想用它做什么呢？"
D.Strings[104886]="恶魔以为能像控制邪能火焰一样控制艾泽拉斯的火焰。他们错了！"
D.Strings[104887]="如果你不敢用，那要这么强大的神器干什么？末日石在我手里会更有用。"
D.Strings[104888]="知道吗，要是你肯用末日石，我们早就完事了。"
D.Strings[104889]="想让我们的大地自残吗？愚蠢的艾瑞达！"
D.Strings[104890]="你们的天空属于军团！"
D.Strings[104891]="我们的翅膀遮天蔽日！"
D.Strings[104892]="我要拿你的尸体来喂蝙蝠。"
D.Strings[104893]="你以为能在我眼皮底下拿走末日石吗？那你就大错特错了！我们抓紧时间吧。"
D.Strings[104894]="送我去风神王座吧。"
D.Strings[104895]="这里不欢迎你！！你从哪儿来的就滚回哪儿去！"
D.Strings[104896]="谢谢你们，勇士。请净化缠绕这座大厅的黑暗吧。"
D.Strings[104897]="我想抵抗，但失败了。我终于自由了。"
D.Strings[104898]="我应该更坚强的。告诉泰兰德……我很抱歉。"
D.Strings[104899]="引擎吞噬万物！"
D.Strings[104900]="凡人的灵魂……太可悲了！"
D.Strings[104901]="艾露恩在此无能为力。这里属于军团！"
D.Strings[104902]="吃吧，引擎！吃吧！"
D.Strings[104903]="我要为主人抓住你！"
D.Strings[104904]="别违抗主人的意志！"
D.Strings[104905]="葬身于这座神殿吧！"
D.Strings[104906]="我屈服了，你们也一样！"
D.Strings[104907]="见证我们的胜利吧！"
D.Strings[104908]="挣扎是徒劳的！"
D.Strings[104909]="我们的工作……得继续……"
D.Strings[104910]="引擎……在颤抖……"
D.Strings[104911]="引擎需要更多灵魂！"
D.Strings[104912]="这些灵魂都归我们了！"
D.Strings[104913]="真是大丰收！"
D.Strings[104914]="那家伙加入了我们！"
D.Strings[104915]="又收割了一个！"
D.Strings[104916]="你们的灵魂只是燃料！"
D.Strings[104917]="你们是引擎的燃料！"
D.Strings[104918]="你们的灵魂归我们了！"
D.Strings[104919]="我们要品味你的痛苦！"
D.Strings[104920]="你会加入我们的！"
D.Strings[104921]="怒气爆发！"
D.Strings[104922]="我相信你一定能搞定你那边。但愿其他人也能顺利。"
D.Strings[104923]="空虚……孤寂……"
D.Strings[104924]="深入灵魂的绝望！"
D.Strings[104925]="感觉到末日的魔爪了吗？"
D.Strings[104926]="啊，灵魂的羁绊！"
D.Strings[104927]="生与死……的交织！"
D.Strings[104928]="你们也将感受这痛苦！"
D.Strings[104929]="让他们的痛苦淹没你！"
D.Strings[104930]="听听绝望者的尖叫吧！"
D.Strings[104931]="我们一起经历了许多困难，$n。"
D.Strings[104932]="我准备好发动突袭了。"
D.Strings[104933]="你好，$n。你知道皇家池塘里曾经生活着全阿苏纳最大最美丽的鱼吗？皇室成员们常来水边观赏它美丽的泳姿，以此忘记自己身上的重担。\n\n现在……噢，出了点问题！"
D.Strings[104934]="除了激怒元素，他们什么都得不到！"
D.Strings[104935]="没有了能量核心，它们完全失控了！"
D.Strings[104936]="奴役艾泽拉斯的元素……燃烧军团太过分了！"
D.Strings[104937]="噢，你要找埃索达的出口？我忘了，很多新来的都不怎么熟悉这些神圣的殿堂。纳鲁之座的上层环道有一处斜坡，可以送你去地表。"
D.Strings[104938]="秘蓝岛"
D.Strings[104939]="祭坛被燃烧军团腐化了！"
D.Strings[104940]="“金刚怒目镇四魔。”"
D.Strings[104941]="“迅捷无畏如疾风。”"
D.Strings[104942]="“万物之中皆真理。”"
D.Strings[104943]="“安忍不动如大地。”"
D.Strings[104944]="东部王国的暴风城或铁炉堡"
D.Strings[104945]="外域的地狱火半岛"
D.Strings[104946]="如果你想去我们位于外域的家园，可以使用圣光穹顶的传送门前往地狱火半岛。"
D.Strings[104947]="圣光穹顶里有一座通往暗夜精灵主城，达纳苏斯的传送门。"
D.Strings[104948]="要前往暴风城的话，你得走海路。首先，你要前往地表的秘蓝岛。然后从那里沿路前往瓦拉尔港口。瓦拉尔号会送你到鲁瑟兰村。那里有一艘船可以把你送去暴风城及东部王国。如果你不知道怎么去地表，我也可以告诉你出口在哪儿。"
D.Strings[104949]="我们是这个世界的新移民，但已经与联盟的各大主城建立了联系。\n\n你想去哪儿呢？"
D.Strings[104950]="我族一直在追求与世隔绝的宁静生活，所以与其他地方的联系并不紧密。但按照我们与部落签订的条约规定，我们还是会提供前往其他主城和前线的旅行方式。\n\n你想去哪儿呢？"
D.Strings[104951]="幽暗城或奥格瑞玛"
D.Strings[104952]="要前往幽暗城以及奥格瑞玛或卡利姆多，你需要使用位于日怒之塔内的传送器。"
D.Strings[104953]="我们有座通往外域地狱火半岛的传送门。它就位于日怒之塔内。"
D.Strings[104954]="干得好，大宗师。敌人……暂时被压制住了。"
D.Strings[104955]="大宗师！我们收到消息说，蔑魔部族又准备进攻了。请在他们行动前破坏这个计划！"
D.Strings[104956]="祝福你，我的朋友！武僧欠你一份情。"
D.Strings[104957]="英雄，我们收到消息说，蔑魔部族又准备进攻了。请在他们行动前破坏这个计划！"
D.Strings[104958]="你的活力给我留下了深刻的印象，先知，我相信你对桑德兰的信任是有道理的。我会转而效忠他的。"
D.Strings[104959]="今天是你占据了上风，先知。我会重新考虑与桑德兰结盟的事的。"
D.Strings[104960]="看来准备得很顺利。"
D.Strings[104961]="我们得去告诉卡德加。"
D.Strings[104962]="但创世之柱无法带来胜利。只有兼具力量与勇气的联军才能战胜燃烧军团。等你们做好决战的准备，我的残影就会回来帮助你们。艾泽拉斯的命运就掌握就在你们手中。"
D.Strings[104963]="|TInterface\\ICONS\\Spell_Arcane_PortalDarnassus.blp20|t %s 开始施放|cFFFF0404|Hspell:234676|h[扭曲的映像]|h|r！"
D.Strings[104964]="|TINTERFACE\\ICONS\\SPELL_SHADOW_LIFEDRAIN02.BLP:20|t %s开始施放|cFFFF0404|Hspell:234423|h[吸取生命]|h|r！"
D.Strings[104965]="但还有希望。只要将创世之柱放进下方的大厅，你们就能修复我的结界，逼退入侵者。然后，你们得深入墓穴，用阿曼苏尔之眼镇压邪能风暴，并斩断军团与艾泽拉斯的联系。"
D.Strings[104966]="我是提瑞斯法守护者，艾格文。我以这个残影作为保护，以防止我在陵墓这里设下的结界失效。没错，我感觉军团之主正在密谋着…夺取他的战利品。"
D.Strings[104967]="多年前，圣盾保护了新生的世界之魂免遭疯狂的腐蚀。今天，它又保护了艾泽拉斯的勇士们。"
D.Strings[104968]="不会吧？守护者！"
D.Strings[104969]="如此野蛮的武器无法替代锋利的战刃，但我想它至少很有效。"
D.Strings[104970]="我们的盟友声称他们的船上加装了毁灭性武器。快去试试他们的武器吧！"
D.Strings[104971]="终于落单了。"
D.Strings[104972]="我来封锁空域。看好圣盾！"
D.Strings[104973]="啊，死亡的怀抱。真叫人放松！"
D.Strings[104974]="伊利丹，要是我的战刃刺穿你的心脏，你可别见怪。这里的恶魔太多了，我很难认出你来。"
D.Strings[104975]="我们的死亡骑士派出了一群亡灵幼龙轰炸这里。你有兴趣吗？"
D.Strings[104976]="让他们来吧。我和玛维来堵住阶梯。"
D.Strings[104977]="我们失败了。军团将我们逼出了墓穴。你们是保护圣盾的最后壁垒了。他们来了……"
D.Strings[104978]="邪能腐蚀正在这片海滩上肆虐。教团需要你的帮助。"
D.Strings[104979]="多米尔在等着你，死亡领主。准备好去搞点破坏了吗？"
D.Strings[104980]="鉴于我的头衔中有“历史学家”这种字眼，我就得保持低调朴素的学者风范。$b$b也就是说，这些单调的土褐色长袍都采用了超细纤维，透气吸汗，轻薄耐用，而且用水刺法织成，蓬松且耐腐蚀，抗皱又不容易缩水。$b$b就是这样了。$b$b还有，你看我的皮肤，水分充足且充满活力。"
D.Strings[104981]="这应该能打断他们的计划，至少是拖延一下。感谢你的帮助！"
D.Strings[104982]="军团打算从这个营地攻击半神们。帮我们打乱他们的计划吧！"
D.Strings[104983]="这可以减缓邪能在这里的扩张速度。"
D.Strings[104984]="我们的部队正在地面与军团交战。必须在我们元气大伤前将圣盾放到塔楼里。"
D.Strings[104985]="这片海滩上遍布着邪能腐蚀。接受我的礼物，去净化这片土地吧。"
D.Strings[104986]="愚蠢的恶魔还没吃够教训吗？他们赢不了我们！"
D.Strings[104987]="恶魔又想攻击半神了。去让这些怪物明白干扰大自然的下场吧！"
D.Strings[104988]="要让那多嘴的恶魔安静下来，最好就是丢下一具冰冷的尸体。干得好！"
D.Strings[104989]="军团最野蛮的战士艾杜瓦尔经常自吹自擂。去干掉那个大话王！"
D.Strings[104990]="干得好。我们要让军团知道，不管躲到哪儿，他们都得死。"
D.Strings[104991]="有个叫德萨诺斯的恶魔潜伏在纳迦中。干掉一切拦路虎，把这个渣滓赶出我们的世界！"
D.Strings[104992]="军团用凡人血肉喂养那只怪物。杀得好！"
D.Strings[104993]="空气中的臭气说明附近有一头恐怖追踪者。为了夺回神殿，我们得击败这只军团的邪恶宠物。"
D.Strings[104994]="那个贪婪的巨人是罪有应得。干得好！"
D.Strings[104995]="你的表现还是那么出色，战争领主。我对你的期望从未落空。"
D.Strings[104996]="这座墓穴不仅引来了燃烧军团。一个贪婪而强大的海巨人，藻拳也出现在这里，打算将神殿的圣物据为己有。你必须阻止他！"
D.Strings[104997]="战争领主！纳迦和他们的海巨人走狗又重操旧业了。去教教他们规矩吧！"
D.Strings[104998]="传说迪墨的凶猛无人能挡。很高兴我们也有传奇的英雄可以阻止这一威胁！"
D.Strings[104999]="军团唤醒了古老的多头蛇，迪墨。消灭那头怪兽，不要让它把怒火释放到我们的世界。"
D.Strings[105000]="很好，英雄们。没有达加尔，墓穴中的纳迦势力就大大削弱了。"
D.Strings[105001]="邪脉精灵的魔法还是……有闪光点的。可惜他们滥用了它。他们是罪有应得。"
D.Strings[105002]="潮汐之石引出了艾萨拉女王的狂热追随者，包括狡猾的督军达加尔。这正是铲除这一威胁的好机会。"
D.Strings[105003]="打得好！这应该能让鲁尔留在墓穴里了。"
D.Strings[105004]="鲁尔生前是个强大的战士。他在死后变成了怪物，并跟我们作对。把他送回坟墓吧。"
D.Strings[105005]="她终于安息了，这是她应得的。我要谢谢你。"
D.Strings[105006]="但愿它能物有所值。"
D.Strings[105007]="一位可靠的朋友为保卫这座神殿献出了生命。可她的遗体被亵渎了，成了徘徊在大厅中的女妖。去帮她解脱吧！"
D.Strings[105008]="你对我要给予你的礼物缺乏足够的敬意。大部分人一辈子都见识不到这种指引体系，$n。$b$b<叹气>关键在于，后世将根据你的服装来评价你。有了我的研究和指导，你就能制造出让你鹤立鸡群的传奇物品。我们开始吧。"
D.Strings[105009]="干得漂亮！嗯，也许用”震撼“更贴切？"
D.Strings[105010]="我们的潜行者要在这里完成一个任务，需要帮手。这些震撼弹能助他们一臂之力！"
D.Strings[105011]="没错，伊利丹。基尔加丹和军团过去的确击败过我们。但只要我们团结一致，世界就能得救。一定能！"
D.Strings[105012]="年轻人就是没耐心。$b$b工匠的手艺取决于他们所用的材料，而——让我们面对现实吧——就因为你一直用那种垃圾布料，所以你看起来活像暴风城的会计，而不是未来的传奇。$b$b想想吧——将来他们为你画像时，你身上的衣服或护甲的款式和质地可是要流芳百世的。那不就是你想要的吗？"
D.Strings[105013]="基尔加丹一直在追杀我的人民，但我们逃够了。他要为他对阿古斯和我儿子的暴行付出代价。"
D.Strings[105014]="我都开始后悔选这个专业技能了。"
D.Strings[105015]="这次爆炸比上一次还要猛烈！特塞斯会满意的。"
D.Strings[105016]="暗影之刃，我们的密探发现有恶魔盘踞在这个洞穴里。我们已经提供了必要的补给。你知道该怎么做！"
D.Strings[105017]="大法师，悲泣平台的邪脉精灵抓了一些魔刃豹。如果能把它们放出来，这些魔法生物或许会有用！"
D.Strings[105018]="你很勇敢，卡德加，但胜利需要的不仅是勇气。你们的联军并不缺乏勇气……结果却在破碎海滩惨遭屠杀。欺诈者会利用你们的恐惧与猜忌对付你们。"
D.Strings[105019]="我们会阻止基尔加丹的计划。这次不会再失败了。"
D.Strings[105020]="精灵将这座神殿建在了古老的魔力之地上。我相信，我那宿敌的躯体就在这里。但在信徒的帮助下，黑暗泰坦可能再次归来，而且力量更胜往昔！"
D.Strings[105021]="你能赶紧说重点吗？"
D.Strings[105022]="它们非常有用！像个恶魔猎手一样在空中滑翔的感觉如何啊，英雄？"
D.Strings[105023]="别管那个！想想你迄今为止所浪费的潜力吧！$b$b这不全是你的错，但你对其他细枝末节和实用性的关注显然超过了时尚。在HSST系统下，你可以弥补这些错误，甚至还有机会成为真正的传奇。$b$b这可是一条布满荆棘的险途。"
D.Strings[105024]="创世之柱已经就位。回大教堂吧，我会揭示这座神殿的古老秘密。"
D.Strings[105025]="勇士！我们需要去邪能喷口上给能量核心充能了。要是你被喷到天上去了，这对破烂的翅膀应该会有用。尽管使用它们吧！"
D.Strings[105026]="你对我的手挺感兴趣啊。"
D.Strings[105027]="你的双手优美但有力，饱经战火洗礼又敏锐灵巧——只有这样的手才能制作出配得上英雄的服装或护甲。$b$b你孩提时代读过的那些昔日传说，里面的剑与魔法总是乏善可陈，可他们的服饰——噢，他们的服饰！这才是这些传说流传至今的根本。$b$b知道这个秘密的人可不多，而你现在就是其中之一了！"
D.Strings[105028]="这些完美的泪珠象征着我们所期待的理想世界。今天，它们将净化你们的心灵，为决战做好准备。"
D.Strings[105029]="江海之水从这块石头中淌出，那是艾泽拉斯的生命之血。今天，它将净化破坏世界的黑暗。"
D.Strings[105030]="我的残影只能陪你们到这里了，勇士们。生前，我独自背负了太多，这份傲慢让我历尽艰辛。你们要团结一致，才能征服前方的黑暗。再见。"
D.Strings[105031]="我的专利发明“锤须时尚品味系统”具有自然的品鉴体系。经过完善的研究，精心的调整以及各位的认真测试，这套HSST体系将成为你学习过程中的潜在帮手。$b$b它有不少危险，$n，但回报绝对超乎你的想象！"
D.Strings[105032]="这把锤子铸造过古老的奇迹，更塑造了大地。今天，它将为我们打破命运的束缚。"
D.Strings[105033]="人们都不理解我为何利用纳迦获得萨格拉斯之眼，但为了艾泽拉斯的未来，这是必须的。别犹豫，去做你该做的事情吧!"
D.Strings[105034]="小心。这里的幽灵恐怕不会太友善……也不会宽恕我。"
D.Strings[105035]="我有一个世纪没来过这里了。我做了该做的事，但也付出了代价。"
D.Strings[105036]="休息一下吧，你得恢复力量，前面还有试炼在等你。"
D.Strings[105037]="英雄，道路打开了，使用创世之柱穿过艾格文的结界，别让军团占据化身。"
D.Strings[105038]="那我们得抓紧时间了。"
D.Strings[105039]="你好，$n。你在破碎海滩的事迹已经传回了暴风城。你为联盟带来了巨大的荣耀。"
D.Strings[105040]="我能感觉到，军团之主正在复活萨格拉斯的化身。如果让基尔加丹将黑暗泰坦的力量注入这具身体，我不知道这世界上还有谁能阻止它。"
D.Strings[105041]="我的防御结界挡住了去路。每道封印都要用创世之柱才能打开。小心，恶魔会不计代价地阻止你们前进。"
D.Strings[105042]="我将这座神殿的每一层都封印了起来，防止入侵者深入。我没想到军团能找到其他途径前往它黑暗的核心。"
D.Strings[105043]="我有些消息要告诉你，$n。到目前为止，你学到的专业技能都只是儿戏。既无挑战性，也不够优雅时尚！$b$b此时此刻，我已经不仅仅是个时尚历史学家了，年轻的$r，我还是个哲学家以及——我也不怕告诉你——这一带的时尚领军人物。"
D.Strings[105044]="守护者艾格文的残影出现了，就像在大教堂时一样。"
D.Strings[105045]="军团带来了一些新恶魔。来看看它们会不会像其他恶魔一样流血吧。"
D.Strings[105046]="一个不留！如果我们失败，世界将化为火海！"
D.Strings[105047]="快，集结队伍！我们得冲过去！"
D.Strings[105048]="我会把这些加入储备的。再次感谢，屠魔者！"
D.Strings[105049]="邪能之槌号的能量储备告急，屠魔者。陵墓附近的邪能可以为能量核心充能。你可以用那边的邪能喷口。"
D.Strings[105050]="奥格瑞玛或东部王国"
D.Strings[105051]="在莫高雷这样的地方并没有太多的旅行路线，不过我会尽力帮助你的。\n\n你想要去哪里？"
D.Strings[105052]="你可以在灵魂高地下面找到传送门，将你送到外域的地狱火半岛的废土。"
D.Strings[105053]="达纳苏斯有一座通往地狱火半岛的传送门，就在月神殿里。按照我的指引先去达纳苏斯吧。到了那里之后，如果你有需要，可以再问其他哨兵月神殿怎么走。"
D.Strings[105054]="虚空干扰器即将开建，来捐献物资吧。"
D.Strings[105055]="虚空干扰器遇袭！我们无法再享受它的增益了！"
D.Strings[105056]="虚空干扰器建设完毕！现在，你们可以使用它的各项功能了。"
D.Strings[105057]="指挥中心即将开建，来捐献物资吧。"
D.Strings[105058]="指挥中心遇袭！我们无法再享受它的增益了！"
D.Strings[105059]="指挥中心建设完毕！现在，你们可以使用它的各项功能了。"
D.Strings[105060]="东部王国的暴风城"
D.Strings[105061]="地狱火半岛是一片位于外域的贫瘠土地。你要前往那里的话，可以使用月神殿里的传送门。"
D.Strings[105062]="埃索达是德莱尼人的飞船和家园。你可以在月神殿里找到通往埃索达的传送门。"
D.Strings[105063]="前往埃索达的船将从西部码头启航。"
D.Strings[105064]="前往暴风城的船就从那边的南部码头出发。"
D.Strings[105065]="要前往暴风城的话，你得先用城市中心的传送门前往鲁瑟兰村。到达泰达希尔脚下后，再去南边的码头坐船。"
D.Strings[105066]="居住在海岛上的我们依赖大海以及魔法力量出行。\n\n你想去哪儿呢？"
D.Strings[105067]="我放好陷阱了，英雄！把恶魔引进去，将它放逐吧！"
D.Strings[105068]="现在，为即将到来的大战打磨好利刃吧！伊利达雷必胜！"
D.Strings[105069]="有屠魔者指挥，燃烧军团输定了！现在，我们来庆祝胜利吧！"
D.Strings[105070]="吉恩和维伦好像在议论我，但我听不清楚他们的话……"
D.Strings[105071]="我们得压低声音，尽量表现得自然点，否则别人会听到我们说话的……"
D.Strings[105072]="暴风城和其他联盟主城"
D.Strings[105073]="诺森德的嚎风峡湾"
D.Strings[105074]="铁炉堡不是暴风城那样的港口城市，但我们也能提供通往其他大陆的各种途径。\n\n你想去哪儿呢？"
D.Strings[105075]="我准备好战斗了。"
D.Strings[105076]="你跟玛加萨一起来的？我就知道她会来救我们的。"
D.Strings[105077]="谢谢你，我的钉锤听候你的差遣。"
D.Strings[105078]="复仇的时候到了。"
D.Strings[105079]="我想我该去监督邪能之槌号的修理工作了。那里见，屠魔者。"
D.Strings[105080]="噢，诺森德的嚎风峡湾。它离这儿可不近。去找狮鹫管理员格莱斯·瑟登，他会安排一只狮鹫送你去米奈希尔港。北地之矛号会从那里启程前往瓦加德。"
D.Strings[105081]="你说地狱火半岛？那片位于外域的焦热废土？呃，我们的法师在秘法区的秘法大厅里设了一座传送门，可以把你送去那里。"
D.Strings[105082]="我恨你……"
D.Strings[105083]="噢，那个发光的玩意儿？被我弄丢了。"
D.Strings[105084]="真的？！只要把古代束缚碎片交给我就能解除咒语了！"
D.Strings[105085]="当然！我该怎么做？"
D.Strings[105086]="你到底要不要放我出去？"
D.Strings[105087]="好的，就下周吧。"
D.Strings[105088]="那么……下周怎么样？"
D.Strings[105089]="无数纪元前，我在虚空的最深处诞生并成了现在这副鬼样子。"
D.Strings[105090]="嘿，伊克。你的生日是哪天？我们要开个庆生派对！"
D.Strings[105091]="可是永远飘浮在某个蠢货地精设下的牢笼里？那叫恶心……"
D.Strings[105092]="一直飘着看起来很有趣啊。"
D.Strings[105093]="我就当你承认了。"
D.Strings[105094]="如果你敢靠近我，我就咬掉你的手。"
D.Strings[105095]="恶魔会怕痒吗？"
D.Strings[105096]="东部王国的银月城"
D.Strings[105097]="卡利姆多的奥格瑞玛"
D.Strings[105098]="东部王国的荆棘谷"
D.Strings[105099]="魔法师们打开了传送门，通往外域的地狱火半岛。你可以在法师区找到它。"
D.Strings[105100]="耀眼的精灵在幽暗城地上的废墟里放置了球形的传送器。只要摸一下就可以把你带到他们的家乡银月城去。"
D.Strings[105101]="米菲会把你带到寒冷的诺森德。她的气球会从洛丹伦废墟北面靠左的那座塔楼上出发。你可以前往嚎风峡湾的复仇港，去干掉维库人。"
D.Strings[105102]="你其实也不知道它们有什么用，对吧？"
D.Strings[105103]="这是个秘密，因为未知的原因，由古老的秘密守护者守护了多年。"
D.Strings[105104]="你为什么这么喜欢虚空碎片？"
D.Strings[105105]="战争占据了我全部的精力和注意力。我都没时间去悲伤。"
D.Strings[105106]="自从父亲的纪念碑从要塞移到这里之后，我就没来过雄狮之眠。"
D.Strings[105107]="这里的鱼早就被我钓光了，可现在兵荒马乱的，出城太危险了。"
D.Strings[105108]="奥格瑞玛是部落的中心，汇集了遍及艾泽拉斯内外的交通线路。\n\n你想去哪儿呢？"
D.Strings[105109]="诅咒之地与通往德拉诺的传送门"
D.Strings[105110]="大灾变中开放的区域"
D.Strings[105111]="破碎群岛上方的达拉然"
D.Strings[105112]="潘达利亚的蜜露村"
D.Strings[105113]="莫高雷的雷霆崖"
D.Strings[105114]="诺森德的北风苔原"
D.Strings[105115]="东部王国的幽暗城或银月城"
D.Strings[105116]="我们在潘达利亚的盟友允许我们开启了一座传送门，直接通往翡翠林的蜜露村。它就位于荣誉谷的中央。"
D.Strings[105117]="肯瑞托在暗影裂口里设立了一座传送门，帮助大家前往破碎群岛上方的达拉然。"
D.Strings[105118]="我们的法师在暗影裂口里开启了一座传送门，帮助大家前往诅咒之地，以进入德拉诺。"
D.Strings[105119]="我们有座通往外域地狱火半岛的传送门。它就位于奥格瑞玛地下的暗影裂口。"
D.Strings[105120]="但即使走在熟悉的台阶上，我也依然感到迷惘。"
D.Strings[105121]="暴风城是我的家。我对它的每家商店和每条街道都了如指掌。"
D.Strings[105122]="要前往诺森德的北风苔原，你就得搭乘飞艇强风号。在它准备前往战歌要塞时，去西侧飞艇塔找格里布·拉姆罗克吧。"
D.Strings[105123]="去奥格瑞玛中央高地的西侧飞艇塔找斯纳尔克吧。她是负责荆棘谷方向的飞艇管理员，能告诉你飞艇何时起飞，前往我们位于东部王国南部的格罗姆高岗哨。"
D.Strings[105124]="要前往幽暗城或银月城的话，你该去奥格瑞玛中央高地的东侧飞艇塔找弗雷萨。他可以告诉你前往提瑞斯法林地的布瑞尔的飞艇何时起飞，布瑞尔就在幽暗城北部。在幽暗城的入口处有一个传送器，可以送你前往银月城。"
D.Strings[105125]="前往卡利姆多中部雷霆崖的飞艇将从奥格瑞玛中央高地的西侧飞艇塔起飞。飞艇管理员泽莉·哈特诺兹可以为你提供更多信息。"
D.Strings[105126]="|TInterface\\Icons\\inv_misc_horn_03:20|t%s|cFFFF0000|Hspell:237937|h[强化]|h|r了所有议会成员！"
D.Strings[105127]="|TInterface\\Icons\\inv_misc_horn_03:20|t%s|cFFFF0000|Hspell:237937|h[强化]|h|r了她和她的一名盟友！"
D.Strings[105128]="|TInterface\\Icons\\inv_misc_horn_03:20|t%s|cFFFF0000|Hspell:237937|h[强化]|h|r了$n！"
D.Strings[105129]="到目前为止，这个术士还是很有用的，尤其是在破解敌人的魔法方面。\n\n他几次都害得我们差点送命，不过我在跟这种恶棍合作时，就知道要面对这种风险了。\n\n虽然他有一大堆缺点，但他也救过我好几次。无论是好是坏，我们都要一起干到底。"
D.Strings[105130]="你看，这些传送门可不会自己劫持自己。我需要时间来完成它，否则你不是掉进军团的熔炉，就是变成某个深渊领主的腹中美食了。\n\n你想传送到深渊领主的肚子里吗？噢，当然，这乍看之下是个好主意，出其不意嘛。但接着，你就会被邪能胃液消化掉，并奇怪你的伟大计划哪儿去了。\n\n快让我回去干活。"
D.Strings[105131]="艾泽拉斯的英雄们，在破碎群岛的战役中，你们的团体已变得十分强大。现在，我们需要你们的力量和勇气了。让我们团结起来，将军团赶出艾泽拉斯！"
D.Strings[105132]="|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t一枚符文被|cFFFF0000|Hspell:237908|h[引爆]|h|r了！"
D.Strings[105133]="卡利姆多的泰达希尔或埃索达"
D.Strings[105134]="破碎群岛的达拉然"
D.Strings[105135]="潘达利亚的坡东村"
D.Strings[105136]="军团将会是你们的末日……"
D.Strings[105137]="这些物资属于军团！"
D.Strings[105138]="你的行为超出了我们同盟的界限，死亡骑士。"
D.Strings[105139]="你休想找到你想要的东西，死亡使者。现在，这座神殿不再欢迎你了，滚出去！"
D.Strings[105140]="我不知道你在说什么。如果你不介意的话，我还有事情要做。如果你有其他问题，可以直接问我们的管家。"
D.Strings[105141]="有头巨龙死在了冰冠冰川北边的冰川里。把你知道的都告诉我。"
D.Strings[105142]="亡灵的臭气都跟你一起进入了这座生命的圣殿。别再这里待得太久。"
D.Strings[105143]="暴风城是联盟的中心，汇集了遍及艾泽拉斯内外的交通线路。\n\n你想去哪儿呢？"
D.Strings[105144]="矿道地铁是前往铁炉堡的最快途径。你可以在矮人区找到它。"
D.Strings[105145]="我们在潘达利亚的新盟友允许我们开启了一座传送门，直接通往翡翠林的坡东村。它就位于暴风要塞旁的湖泊西侧。"
D.Strings[105146]="你很走运，达拉然现在就在破碎群岛上方，肯瑞托在暴风要塞里开设了一座传送门。"
D.Strings[105147]="不管你们怎么评价阿尔萨斯，前巫妖王在对付燃烧军团时确实很厉害。"
D.Strings[105148]="我们有座通往外域地狱火半岛的传送门。它就位于法师塔顶层的巫师圣殿内。"
D.Strings[105149]="法师们在法师塔里开了一座传送门，帮助大家前往诅咒之地，以进入德拉诺。它就在名叫亮火的法师的身旁。"
D.Strings[105150]="远离阿彻鲁斯，对新鲜的尸体和骨堆进行老式的、美妙的实地调研，这种感觉太棒了。"
D.Strings[105151]="如果这就代表了燃烧军团所依赖的通灵术，那我们的处境可比我想的要好多了。"
D.Strings[105152]="要去卡利姆多的埃索达或者泰达希尔的话，你该去找纳尤拉。她是勇者号的码头管理员。那艘船会从暴风城港口最南边的码头出发。"
D.Strings[105153]="什么样的帮助？"
D.Strings[105154]="燃烧军团一直想要复制天灾军团这一杰作。\n\n因此，他们找到了能够制作白骨傀儡的纳斯雷兹姆。\n\n他们招募了这些堕落的灵魂行者，一群粗通亡灵法术的恶棍。\n\n我代表黑锋骑士团来此巡视及审判。英雄，如果你有需要的话，我也可以提供帮助。"
D.Strings[105155]="我不再是军团的工具了。"
D.Strings[105156]="我……我自由了。谢谢你。"
D.Strings[105157]="只有你能终结这痛苦。抗争吧！"
D.Strings[105158]="摆脱腐蚀吧，我的朋友！"
D.Strings[105159]="安息吧，兄弟！这是你应得的。"
D.Strings[105160]="有东西在威胁我的兔子！小可怜……快做点什么！"
D.Strings[105161]="我们先解决那恶魔，$n！然后才是艾德里斯。"
D.Strings[105162]="别怕，大人。我能复活更多。"
D.Strings[105163]="恶魔进攻了，我的士兵还没恢复！"
D.Strings[105164]="我的小鸡到底怎么了？"
D.Strings[105165]="……最后，我们当然也不能忘了五大浮冰群：北部、南部、东部及西部理论上不能称为冰川的小型浮冰群，真有意思……"
D.Strings[105166]="那可是当头一棒。但我们的屠魔者很坚强，亲爱的——看！"
D.Strings[105167]="屠魔者还昏迷着。我很担心，万一——"
D.Strings[105168]="从北部大型冰川往后，按照构造排序，依次为东北部中型冰川，南部小型冰川，西南部微型冰川，西南偏南部微型冰川，东南偏南部微型冰川，最南部微型冰川，第一及第二北部微型移动冰川……"
D.Strings[105169]="咳咳！好吧！原本那里是有……冰川的……很大……就在冰冠冰川北边……但几年前，它飘走了……我就知道这么多，我发誓！你可以去问……塔里奥！"
D.Strings[105170]="<特利索尔姆眯起了眼睛。>\n\n像你这样的死亡使者问这个干什么？"
D.Strings[105171]="噢，你好！感谢你再次光临。\n\n怎么，这是你第一次来？\n\n今天几号？"
D.Strings[105172]="不，我想不起来了。非常抱歉，我还在为亲爱的伊瑟拉悲伤，眼下根本想不了别的。你问过青铜龙军团的成员吗？他们的记性可好了。"
D.Strings[105173]="见证邪能之力吧！"
D.Strings[105174]="把你知道的有关北方冰川的事都告诉我，曾有一头强大的巨龙陨落在那里。"
D.Strings[105175]="不管那么多了。抓紧！"
D.Strings[105176]="<莱瑟库斯的眼神十分迷离。>\n\n噢，怎么了？我没看见你。\n\n<莱瑟库斯打了个哈欠。>"
D.Strings[105177]="这要不了多久！"
D.Strings[105178]="真的吗？他到底要怎么阻止无穷无尽的恶魔大军入侵和屠杀所有人？"
D.Strings[105179]="恐惧会愚弄你的头脑。你该休息一下了，简妮。"
D.Strings[105180]="别以为毁了几条船就胜利了。我保证，这是最后一次了。下次见面的时候，你们就死定了！"
D.Strings[105181]="又有愚蠢的凡人来挑战我？那好吧！"
D.Strings[105182]="对，来吧。我正觉得无聊呢。"
D.Strings[105183]="伊利丹，把阿格拉玛之盾送去大教堂。我会和卡德加深入墓穴追杀那个怪物。基尔加丹的暴政很快就要结束了。"
D.Strings[105184]="孟菲斯托斯！"
D.Strings[105185]="或许吧。但不是今天，恶魔！"
D.Strings[105186]="别吵了！集中精神！"
D.Strings[105187]="圣光亦然。"
D.Strings[105188]="几个徒有其表的凡人就想阻止我们？"
D.Strings[105189]="给，这些应该有用。把它们放在船上。我能远程引爆它们。"
D.Strings[105190]="你太轻信伊利丹了，先知。我会盯着他完成任务的。"
D.Strings[105191]="伊利丹，你来得可真早！守望者们，让恶魔猎手在这儿玩蝙蝠吧，我们去干点实事。"
D.Strings[105192]="又是传送门？！我们的援军呢？"
D.Strings[105193]="今天我们赢了一场，但前面的危机依然深重。军团之主还没黔驴技穷呢。"
D.Strings[105194]="术士们抢了你的世界，纳斯雷兹姆！我要是你，就会谦虚点儿。"
D.Strings[105195]="对。我们收到了。祝你好运。"
D.Strings[105196]="他们的旗舰还在。我们得在达拉然失守前摧毁它！黑暗收割议会开启了传送门。去好好招呼他们吧，$n。"
D.Strings[105197]="$n，阿加诺斯的部队就驻扎在东北方。我们必须在盟友溃败之前关闭传送门。"
D.Strings[105198]="看来你输定了，卡格拉斯。"
D.Strings[105199]="弓箭手！火力全开！"
D.Strings[105200]="啊！少了一艘船。"
D.Strings[105201]="你和其他人去西边的山上。有个艾瑞达带队保卫着岗哨。你知道该怎么做。"
D.Strings[105202]="很好！他们自以为早有准备，但他们没想到团结的艾泽拉斯会如此强大！"
D.Strings[105203]="我们得先攻占海滩，才能夺取西边的废墟。"
D.Strings[105204]="军团休想获胜！我们要让他们看看团结的力量。为了艾泽拉斯！"
D.Strings[105205]="我们得占领这座岛西边的废墟。从那里，我们可以派出所有的部队围攻灵魂引擎上方的旗舰。"
D.Strings[105206]="你带领部队继续向前，我来对付这些船。"
D.Strings[105207]="$n，我们对南部海滩的突袭遭到了激烈抵抗。"
D.Strings[105208]="我们得兵分几路，从四面八方包抄他们。"
D.Strings[105209]="我在哪儿？你是谁？"
D.Strings[105210]="水……不要让其他人喝这种水！"
D.Strings[105211]="我想要停下来，但是做不到……感觉自己像是个提线傀儡。"
D.Strings[105212]="它们进入了我的脑袋……我的意志！"
D.Strings[105213]="我……没法控制我自己。"
D.Strings[105214]="很多人最近的举止都有点奇怪……但愿这不是什么传染病。"
D.Strings[105215]="你看起来很累，又在外头奔波了一天吗？"
D.Strings[105216]="你的脸色不太好。你没事吧？"
D.Strings[105217]="请快点，大宗师。那些幸存者就全指望你了！"
D.Strings[105218]="啊……大宗师。阿麦和布兰琪在村里等你。我得休息……一下了。"
D.Strings[105219]="这些鸦堡卫士刚复活，或许还没有被彻底腐蚀！他们可能还有救！"
D.Strings[105220]="你的邪恶之力在沸腾。唤醒这头巨龙吧，把它据为己有。"
D.Strings[105221]="你窃取了巨龙的生命力。现在，让它为你所用吧。用你的黑暗亵渎它。"
D.Strings[105222]="附近有许多凶猛的亡灵。他们在吸食它的生命力。抢走它，杀光他们。"
D.Strings[105223]="就要到了，你的前方有生命存在。给这片失落之地带去死亡吧。"
D.Strings[105224]="当然，你要是死了，那阿彻鲁斯就归我了。阿尔萨斯或许想报复那座堡垒，但是我……另有打算。"
D.Strings[105225]="它就在这儿。你的补给都被冻住了吧？冰层下有凶猛的亡灵。考验你意志的时候到了。"
D.Strings[105226]="抓紧缰绳。"
D.Strings[105227]="继续向北，冲进暴风雪里去。"
D.Strings[105228]="去北方吧。找到冰川……和你的命运。"
D.Strings[105229]="你的内心和我一样空虚。"
D.Strings[105230]="他们的史料就藏在这座圣殿里。是手下留情还是一个不留……全由你决定。"
D.Strings[105231]="他警告了盟友，他们肯定严阵以待了。"
D.Strings[105232]="红龙知道些什么。他们的秘密就藏在红玉圣殿里。"
D.Strings[105233]="去找历史的守护者——青铜龙吧。别手软。"
D.Strings[105234]="可这里只剩海水，没有亡灵的踪迹。"
D.Strings[105235]="一具太古巨龙的骨架，它生前强大得超乎想象。"
D.Strings[105236]="看前面……看到了吗？"
D.Strings[105237]="在这里，我看到亡灵涌过一座冰架，寻找阿尔萨斯渴望的宝物。"
D.Strings[105238]="到冰冠冰川北方去吧，你会看到我所看到的一切。"
D.Strings[105239]="但透过无尽寒冰的冰冷触须，我感觉到那里空无一物。"
D.Strings[105240]="我看到一个幻象……数千亡灵涌向诺森德的北方，寻找强大的力量。"
D.Strings[105241]="统御头盔告诉了我很多事，死亡领主。"
D.Strings[105242]="艾德里斯？你也被腐蚀了？我很难过，你的长眠被打扰了。"
D.Strings[105243]="跟军团作对的人都得死！"
D.Strings[105244]="你还不明白吗？燃烧军团已经赢了！"
D.Strings[105245]="这毫无意义……我们完了！我们都完了！"
D.Strings[105246]="你别想逃出燃烧军团的掌心！"
D.Strings[105247]="为了主人！为了燃烧军团！"
D.Strings[105248]="向战争领主致敬！"
D.Strings[105249]="苍穹要塞。"
D.Strings[105250]="我陪你去雄狮之眠。"
D.Strings[105251]="不需要再祈祷了。我想知道我的人民到底是怎么想的。"
D.Strings[105252]="不太走运，是吧？格雷迈恩国王肯定不会高兴的，但我相信你已经尽力了。"
D.Strings[105253]="我得去搞清楚。跟我走。"
D.Strings[105254]="这是你自找的！开打吧！"
D.Strings[105255]="你是在招惹星球的喉舌！星球的喉舌！"
D.Strings[105256]="我体内的岩浆都沸腾了！"
D.Strings[105257]="回去干活儿！"
D.Strings[105258]="为我们的世界而战！"
D.Strings[105259]="这些岩石有许多故事。"
D.Strings[105260]="我是艾泽拉斯的喉舌！"
D.Strings[105261]="仆从！吃了它。"
D.Strings[105262]="啊！我的“召唤勇士”法术成功了。仆从！我们得去跟我的另一位前主人战斗了。出发！"
D.Strings[105263]="太神奇了！虽然我们经常召唤恶魔和元素，可我从未想到这扇门会是双向的。"
D.Strings[105264]="勇士，我们营地附近有一股能量似乎与你特别契合。你愿意去调查一下吗？"
D.Strings[105265]="嘿！看看这些宝藏！"
D.Strings[105266]="哎唷！我猜这玩意儿就是干这个用的！噢，好吧。"
D.Strings[105267]="啊！你干了什么？！永远被锁在这个位面？还有比这更可怕的命运吗？！"
D.Strings[105268]="不！你怎么敢！我决不向这种愚蠢的生物屈膝！"
D.Strings[105269]="古代束缚碎片开始辐射出强大的能量。"
D.Strings[105270]="我是宝藏大师伊克里格迪库斯！等等……你手里的是什么？"
D.Strings[105271]="噢，嘿。你是谁？"
D.Strings[105272]="嘿，蠢货！我觉得你带给我的这块碎片坏了。我试着用石头和其他东西砸过它了！"
D.Strings[105273]="没关系，我马上就能带着所有的宝藏逃之夭夭了！"
D.Strings[105274]="入侵者！你怎么找到我的巢穴的！"
D.Strings[105275]="多玛塔克斯撕开了新的邪能传送门！"
D.Strings[105276]="来吧，小勇士，让我们用正义之潮淹没敌人！"
D.Strings[105277]="我的水都被染绿了。或许待会儿要好好过滤一番。"
D.Strings[105278]="倒在正义的大潮之下吧！"
D.Strings[105279]="你无法阻挡洪水！"
D.Strings[105280]="滚开，邪能渣滓！"
D.Strings[105281]="你的火焰熄灭了！"
D.Strings[105282]="让流水净化一切！"
D.Strings[105283]="让失败淹没你！"
D.Strings[105284]="谢谢你，勇士。战局真是越来越白热化了！"
D.Strings[105285]="耐普图隆派出了他最强的勇士之一来帮助我们，并提起了你的名字。我很期待你们两个所能造成的破坏。"
D.Strings[105286]="不！燃烧军团会……摧毁……你们的世界……"
D.Strings[105287]="我要杀光你们的半神！"
D.Strings[105288]="辉煌的战绩！你让那些水臭虫认清了现实。"
D.Strings[105289]="英雄！纳迦和它的海巨人一直在骚扰我们的战士。去教训教训这些恶棍吧！"
D.Strings[105290]="大法师，我们得放出悲泣平台的邪缚魔刃豹！看管它们的弃誓者相当强大。适当使用法术吸取应该会很有用！"
D.Strings[105291]="真是场英勇的战斗，冲走了邪恶的火焰，淹没了邪能的火苗。$b$b对于一个可悲的旱鸭子来说，你干得很不错。"
D.Strings[105292]="我在梦境林地深处等你。谢谢你带我过来！"
D.Strings[105293]="我……还活着！谢谢你，朋友！太谢谢你了！"
D.Strings[105294]="我再也不离开纳萨拉斯了！"
D.Strings[105295]="谢谢你，英雄！我还以为自己死定了！"
D.Strings[105296]="我很虚弱，蛛网吸干了我的全部精力。"
D.Strings[105297]="我要回梦境林地了。谢谢你！"
D.Strings[105298]="必须阻止那个指挥官。我相信你！"
D.Strings[105299]="谢谢你，大德鲁伊。我都做好最坏的打算了。"
D.Strings[105300]="我不会让它变成现实的。"
D.Strings[105301]="凡人！伟大的耐普图隆派我来为这些侵略者送上毁灭和审判。这些白痴被邪能烧坏了脑子，居然敢入侵我们的世界。$b$b跟我一起战斗吧，我们将一起熄灭他们邪恶的火焰。"
D.Strings[105302]="让那个指挥官尝尝我的利刃！"
D.Strings[105303]="来吧，孩子们，吃吧！"
D.Strings[105304]="你来之前，我已经问出了一切。我知道指挥官在哪儿了！"
D.Strings[105305]="仪式已经准备好了，跟我去召唤平台吧。"
D.Strings[105306]="阿格拉玛之盾的能量耗尽了！"
D.Strings[105307]="控制住那头野兽，我召唤他们过来……"
D.Strings[105308]="封锁天空，不然我们就别想打断导管了！"
D.Strings[105309]="如果联结再维持下去，阿苏纳就完了！"
D.Strings[105310]="我们得再封锁天空一段时间，绝不能在这个时候失败。"
D.Strings[105311]="这东西散发出的能量简直不可思议。"
D.Strings[105312]="不要停，直到打断联结为止！"
D.Strings[105313]="集火攻击。我们必须打断联结！"
D.Strings[105314]="你听到了吧！我们得立刻找到袭击的策划者！别浪费时间了！"
D.Strings[105315]="我得找个安全的地方恢复一下了。你得找到幕后黑手并干掉他们！"
D.Strings[105316]="应该……留在……学校里的……"
D.Strings[105317]="我没认真……想过……"
D.Strings[105318]="我有拳头，还要书干什么！"
D.Strings[105319]="哈！到底谁才是聪明人？"
D.Strings[105320]="领教了吧？"
D.Strings[105321]="失败者才看书！"
D.Strings[105322]="站住，懦夫！"
D.Strings[105323]="我要踩扁你们！"
D.Strings[105324]="我要去破碎海滩看看我父亲做出的牺牲。"
D.Strings[105325]="我要碾压你们这些笨蛋！"
D.Strings[105326]="小笨蛋也想跟军团耍花招？再想想吧！"
D.Strings[105327]="谢谢你，朋友。我知道怎样才能明白这顶王冠的分量。"
D.Strings[105328]="我的末日……已刻在……轮回中……"
D.Strings[105329]="现在……我将成为……肥料……"
D.Strings[105330]="凡人都不懂得欣赏真正的美。"
D.Strings[105331]="他们没有尊重大自然。"
D.Strings[105332]="虫子的食物来了！"
D.Strings[105333]="现在应该堆肥了！"
D.Strings[105334]="你们破坏了自然的完美！"
D.Strings[105335]="这片古老的土地不属于你们！"
D.Strings[105336]="我的触须会抓住你们的！"
D.Strings[105337]="国王要明白每一条政令的分量和代价。如果一个罗盘都能让他崩溃，那要是恶魔打上门来怎么办？"
D.Strings[105338]="我要榨干你们的生命力！"
D.Strings[105339]="我们需要信心，他也一样。安度因没去过破碎海滩，他没见过士兵们的牺牲……而这种牺牲还会继续下去。"
D.Strings[105340]="这将是你们的最后一口气！"
D.Strings[105341]="感觉喉咙发紧吗？"
D.Strings[105342]="对，小宝贝们。邪能凸显出了我们真正的美。"
D.Strings[105343]="安度因深受圣光眷顾。他会成为明君的，我们要有信心。"
D.Strings[105344]="预言打不赢战争，先知。那孩子很善良，但未经磨练。"
D.Strings[105345]="年轻的国王会是个好领袖。我早有预见。"
D.Strings[105346]="我听到了人民的呼声，我父亲的顾问们呢？他们恐怕也不像信任父亲那样信任我。"
D.Strings[105347]="人民喜欢我，尊敬我……但不能像信赖他一样信赖我。"
D.Strings[105348]="可悲的灵魂！这就叫残酷了吗……"
D.Strings[105349]="你把父亲的罗盘带回来以后，我向圣光祈求指引，并希望他的灵魂安息。但圣光并未回应。"
D.Strings[105350]="你要付出代价！"
D.Strings[105351]="我的工作……全毁了！"
D.Strings[105352]="看，这家伙等不及了！"
D.Strings[105353]="注意，凡人！听话的人将有幸侍奉军团！"
D.Strings[105354]="还会有……更多……痛苦……"
D.Strings[105355]="这失败……会纠缠我……"
D.Strings[105356]="他们的身体崩溃了！我胜利了！"
D.Strings[105357]="凡人的心智太脆弱了。真没劲。"
D.Strings[105358]="那家伙崩溃了！"
D.Strings[105359]="死了？真脆弱！"
D.Strings[105360]="多么软弱的意志！"
D.Strings[105361]="你现在归我了！"
D.Strings[105362]="我不怪这小伙子的选择。我父亲牺牲了一切来拯救人民。他是个明君。"
D.Strings[105363]="对，我爸爸也这么说。好吧，我是瓦里安国王。小心了，恶魔！"
D.Strings[105364]="别扮安度因，扮瓦里安吧！他更强大。"
D.Strings[105365]="求饶吧，凡人！"
D.Strings[105366]="你会崩溃的！"
D.Strings[105367]="我是安度因国王！我要杀光所有恶魔！"
D.Strings[105368]="反抗只会带来痛苦！"
D.Strings[105369]="我要烧尽你的傲慢！"
D.Strings[105370]="何必受苦呢？臣服于军团吧！"
D.Strings[105371]="我能让你们摆脱黑暗！投降吧！"
D.Strings[105372]="这苦难……将成为……荣耀……"
D.Strings[105373]="辜负……主人的……痛苦……"
D.Strings[105374]="他们的灵魂将永远遭受失败的折磨！"
D.Strings[105375]="他们太容易死了。"
D.Strings[105376]="忍不下去了？"
D.Strings[105377]="脆弱的凡人！"
D.Strings[105378]="又一具破碎的尸体！"
D.Strings[105379]="他们有理由害怕。如果不能将军团堵在破碎海滩，恶魔就会冲向这里，我们的家园和心脏。"
D.Strings[105380]="我保证……这一定很疼！"
D.Strings[105381]="你还能忍多久？"
D.Strings[105382]="你的痛苦将成为传说！"
D.Strings[105383]="真滑稽，我还以为我听到了……不可能。我肯定是出现幻觉了。"
D.Strings[105384]="给我尖叫吧！"
D.Strings[105385]="我要切碎你！"
D.Strings[105386]="至少暴风城很安全。乌瑞恩国王会保护这座城的。"
D.Strings[105387]="让痛苦刺穿你！"
D.Strings[105388]="痛苦！无可估量的痛苦！"
D.Strings[105389]="他们上周从破碎海滩带回了我堂兄的尸体。我想后头还会有更多牺牲者。"
D.Strings[105390]="比我想得要快，但没关系。该干活儿了！"
D.Strings[105391]="呸！是我的拷打……等等！有凡人来了！格罗斯那蠢货又失败了！"
D.Strings[105392]="肉体痛苦？呸！精神折磨才是王道。拉基什就是这么屈服的。"
D.Strings[105393]="承认吧，我才是对的！打垮躯壳才能驯服灵魂。"
D.Strings[105394]="燃烧军团会为此付出代价的！"
D.Strings[105395]="尽快消灭那些小鬼。他们不算最难对付。但如果不加以遏制，他们就会淹没你！"
D.Strings[105396]="醒醒，戈德林。"
D.Strings[105397]="<邪能消散了，戈德林安详地沉睡着。>"
D.Strings[105398]="我知道一个法术。跟我来。"
D.Strings[105399]="我需要一身伪装，才能在城里低调地走动。"
D.Strings[105400]="格雷迈恩国王说过你会来。请直接进去吧。"
D.Strings[105401]="他们……想腐蚀戈德林！快，大德鲁伊！"
D.Strings[105402]="恶魔最近都别想通过这座传送门了！"
D.Strings[105403]="要他们好看！"
D.Strings[105404]="想象一下吧，进来的恶魔都会被这些藤蔓糊一脸！真经典！"
D.Strings[105405]="传送门应该就在这附近……睁大你的眼睛！"
D.Strings[105406]="我理解他的悲伤，但国王就该待在王座上。破碎海滩才是重中之重。去把安度因劝回来吧！"
D.Strings[105407]="安度因一直不眠不休，怎么劝也不肯返回宫殿。我的话完全无法安慰他。"
D.Strings[105408]="客人到了。这下或许就能联系上国王了。"
D.Strings[105409]="谢谢你把父亲的罗盘带回来。它让我明白我是多么思念他。"
D.Strings[105410]="与军团的战争打响后，我几乎无暇思考和喘息……甚至是悼念他。也许该做出改变了。"
D.Strings[105411]="这罗盘是我给父亲的生日礼物。将它送出后不久，我的船就在潘达利亚搁浅了。真是恍如隔世……"
D.Strings[105412]="来吧！我们得去救出戈德林！"
D.Strings[105413]="救救我！快！"
D.Strings[105414]="噢，又来看演出了？记得多给点小费，伙计！"
D.Strings[105415]="不喜欢我的表演？那就来尝尝我的魔法靴子吧！"
D.Strings[105416]="你们这是自寻死路。放下武器，向你们的主人致敬吧！"
D.Strings[105417]="这需要时间，但有了你，这片土地迟早会恢复。干得好，英雄！"
D.Strings[105418]="哈哈！再见，变戏法的！"
D.Strings[105419]="我感觉附近又有恶魔存在。勇士，全靠你去消灭它们了！"
D.Strings[105420]="待会儿见，魔法——魔术，呃——魔力——啊，算了算了！"
D.Strings[105421]="好！我去拿东西，总算能摆脱这儿了。"
D.Strings[105422]="稍等。我这就把你弄出来。"
D.Strings[105423]="呼，好险啊！你懂的，兔子可不便宜！"
D.Strings[105424]="狼是怎么进来的？！好了，别傻站着，杀了它！"
D.Strings[105425]="好了，伙计，去那边逛逛，看看兔子们出什么事了。"
D.Strings[105426]="什么鬼！？"
D.Strings[105427]="给，你来试试。"
D.Strings[105428]="然后把兔子塞进去，接着……铛铛！"
D.Strings[105429]="好了。首先，你要为自己选一顶内置袖珍次元传送门的帽子。"
D.Strings[105430]="回守护者圣殿，我会送你一些小玩意儿作为谢礼。"
D.Strings[105431]="测试很充分了，伙计。我们该考虑大量生产的问题了！"
D.Strings[105432]="别担心那些实验体。我相信，它们已经习惯这些东西了。"
D.Strings[105433]="我就说了嘛！看那家伙多棒！"
D.Strings[105434]="嘿，伙计！我有个建议！"
D.Strings[105435]="我们一直在寻找敢于深入那座邪恶巢穴的志愿者。那里遍布蛛网，你出来后可能就得换鞋了。正好我在达拉然有关系，可以给你打个折！"
D.Strings[105436]="干得好，英雄！只要军团的阴影还笼罩着这世界，我们就要保持警惕。"
D.Strings[105437]="英雄，鲑鱼溪有一股邪恶力量。去找到军团并消灭它！"
D.Strings[105438]="我有个棘手的任务要交给你，勇士。为了施展某个复杂的法术，我们需要从惊悚洞穴的蜘蛛那里搞些蛛丝来。你能帮忙吗？"
D.Strings[105439]="我见过恶毒的纳迦、愤怒的幽灵和阴险的恶魔。但蜘蛛……恶心！"
D.Strings[105440]="不能再浪费时间了！我已经准备好了！"
D.Strings[105441]="哇……艾维娜……"
D.Strings[105442]="你必须破坏遇到的所有蛛卵。决不能让这些害虫扩散开来！"
D.Strings[105443]="蜘蛛！军团有那么多恶魔，为什么要选择蜘蛛来入侵我的国度？"
D.Strings[105444]="艾维娜！"
D.Strings[105445]="伤害我的孩子的人将付出代价！"
D.Strings[105446]="噢！我是在泰安诺遇见他的。当时他被一只鹰身人抓住了，而且身上一丝不挂！哈哈！\n\n那个鹰身人忙着跟一只女妖吵架，争论到底应该由谁先上，她们根本没有注意到我。\n\n他看起来很不舒服，所以我就出手了。后来的事你都知道了！"
D.Strings[105447]="艾维娜，鸟儿会为你带去各地的消息。请帮我们找到恶魔的目标！我们要为同胞复仇！"
D.Strings[105448]="我们能帮什么忙吗？"
D.Strings[105449]="想到我的兄弟姐妹是死于一次“声东击西”……不可饶恕！"
D.Strings[105450]="你是怎么遇到艾萨斯的？"
D.Strings[105451]="我觉得所有形式的魔法都很神奇。既然护盾已经消失，我已经等不及要把它们学个遍了！"
D.Strings[105452]="艾维娜！你的孩子们需要你。燃烧军团正在屠杀利爪德鲁伊！"
D.Strings[105453]="如果我的长老们知道我跟一个外来者厮混，一定会放逐我的……甚至更糟。"
D.Strings[105454]="夏多雷已经与世隔绝了那么多年。我们很难接受新思想。"
D.Strings[105455]="我不确定这是否管用，但最好还是试试……退后！"
D.Strings[105456]="我在前面等你。"
D.Strings[105457]="我发现她完全是机缘巧合，真的。呃，好吧，是她发现了我。\n\n当时我遭遇了一点……情况……一只鹰身人、一只女妖和……噢，算了。\n\n总之，莱娜用惊人的法术技巧把我救了出来，然后提出要加入提瑞斯秘法会。\n\n我怎么能拒绝呢？"
D.Strings[105458]="再跟我说说奥术师莱娜的事吧。"
D.Strings[105459]="干得好！疫病似乎被压制住了。"
D.Strings[105460]="一种可怕的瘟疫吞噬了死木港。住在岛上的鹰身人就是病毒携带者。决不能让她们的腐蚀扩散开来！"
D.Strings[105461]="邪能疫病又一次侵袭了死木港，大祭司。我们得在它传入内陆之前扼制住这种疾病。"
D.Strings[105462]="精彩的战斗！这艘船随时可能炸成碎片。但没关系！我们的巨鹰会把你安全地送回去的！"
D.Strings[105463]="好险啊。感谢你的帮助。"
D.Strings[105464]="快，英雄们。拉善需要你们！"
D.Strings[105465]="呵呵。这个星球就这点力量吗？太弱了。我想要真正的挑战。"
D.Strings[105466]="邪脉诱捕者在对野生动物用他们的扭曲魔法。带上这瓶法力根茎药膏，为受伤的动物涂抹。快，别让腐蚀扎根！"
D.Strings[105467]="破坏军团战舰、营救盟友的任务就交给你了。这个指挥官归我！"
D.Strings[105468]="这些战鹰会送我们去目的地的。准备好了吗？要升空了！"
D.Strings[105469]="上船后，你得救出所有俘虏。等我的人安全后，就点燃这些炸药并迅速撤离！"
D.Strings[105470]="明白了。英雄们，我们去集结点。"
D.Strings[105471]="该攻击军团战舰了。梅拉，勇士们，到雷霆图腾外来找我。他们要血债血偿！"
D.Strings[105472]="干得好，英雄们。虽然只封闭了两条隧道，但总比没有强。"
D.Strings[105473]="英雄们……干掉这个……恶魔……"
D.Strings[105474]="纳瓦罗格的一个地卜师正在封印隧道，挡住军团。你要全力保护他！"
D.Strings[105475]="你背叛了我们的人民，与恶魔崇拜者勾结在一起！"
D.Strings[105476]="勇士，军团想从地下潜入雷霆图腾。帮忙击退他们！"
D.Strings[105477]="我的选民带来了生命之礼。接受它，继续战斗吧！"
D.Strings[105478]="你是真正的自然卫士。我要谢谢你。"
D.Strings[105479]="雷霆图腾遭到攻击！在干掉天上那艘恶魔战舰前，我们得先救援战友。"
D.Strings[105480]="就算首领死了，邪脉诱捕者也不会住手！带上这瓶法力根茎药膏，为受伤的动物涂抹。尽力多救几条生命！"
D.Strings[105481]="邪火小径全是忠于军团的神秘学者。不能让他们站稳脚跟！"
D.Strings[105482]="你真强大！那些神秘学者肯定后悔与我们为敌了！"
D.Strings[105483]="就算坎雷萨德归来，这些神秘学者依然忠于军团。不能让他们夺回邪火小径！快去干掉几个恶棍，吸收他们的能量源！"
D.Strings[105484]="强大的燃烧军团进攻了，我们只能勉强抵挡他们的围攻。"
D.Strings[105485]="这个破坏者原本是部落成员——事实上，他曾是我手下的一个夺日者。\n\n当初，议会里的某些人就强烈反对我们重返肯瑞托。你可以想象，这会给他们足够的口实再次驱逐我们。\n\n如果这件事真的发生了，我们的停战协议就会破裂，艾泽拉斯也必将落入燃烧军团之手。"
D.Strings[105486]="你现在的任务是立刻去战场报到。消灭那些正在撕裂前线的恶魔！"
D.Strings[105487]="燃烧军团是怎么接触到达拉然的武器的？"
D.Strings[105488]="看来我们的盟友设法击退了攻击……做好准备。"
D.Strings[105489]="我们在武器核心旁发现了破坏者的尸体。他的灵魂被抽干了……呃，真是可怕的死法。\n\n情况恐怕比我透露的还要糟糕。"
D.Strings[105490]="如果这是佯攻，那主攻方向呢？问问艾维娜吧。她应该知道！"
D.Strings[105491]="我见识过纯粹的暗影……你最好别去尝试。"
D.Strings[105492]="穿着那身衣服，你永远都别想成为真正的法师。"
D.Strings[105493]="学徒……？学弟……？弟子……？对，我想应该是这个词儿……"
D.Strings[105494]="等等……我没关火焰试炼？我记得我关了的……"
D.Strings[105495]="好好学习。"
D.Strings[105496]="前进吧，随便你……干嘛！"
D.Strings[105497]="你千万别死了！"
D.Strings[105498]="这是我……还是我的幻象？"
D.Strings[105499]="你喜欢……试炼吗？"
D.Strings[105500]="对我来说，学徒总是多多益善。"
D.Strings[105501]="许多人都为保护世界而战，我只是其中之一。"
D.Strings[105502]="我跟我兄弟曾一起经历过许多战争与考验。"
D.Strings[105503]="小心那些龙。他们不可靠！"
D.Strings[105504]="我将毁灭敌人！"
D.Strings[105505]="我要保卫这里。"
D.Strings[105506]="愿圣光祝福你，旅行者。"
D.Strings[105507]="你好啊，冒险者。"
D.Strings[105508]="邪火长矛在此时或许会很有用……"
D.Strings[105509]="你瞧，绿色的服装也许更适合我……"
D.Strings[105510]="燃烧军团都没你这么讨厌！"
D.Strings[105511]="我的家族可不是以性情温和著称的。"
D.Strings[105512]="或许我父亲对你的评价是正确的。"
D.Strings[105513]="快住手。"
D.Strings[105514]="我不会再甘当猎物了。"
D.Strings[105515]="光荣地战斗吧，外来者。"
D.Strings[105516]="愿诸神与你同在。"
D.Strings[105517]="我是坚不可摧的。"
D.Strings[105518]="我的盾已经蓄势待发了。"
D.Strings[105519]="你好啊，外来者。"
D.Strings[105520]="蠢货德鲁伊……声东击西成功了！"
D.Strings[105521]="我怎么就没去养一些恐惧战马呢？"
D.Strings[105522]="你不是该去收集材料什么的吗？"
D.Strings[105523]="你给我带鲜血来了吗？"
D.Strings[105524]="愿邪能之蹄赐予你矫健的步伐。"
D.Strings[105525]="恶魔将臣服于我们。"
D.Strings[105526]="克索诺斯在召唤。"
D.Strings[105527]="那匹恐惧战马必将属于我们。"
D.Strings[105528]="我们今天要召唤些什么？"
D.Strings[105529]="你需要我帮忙吗？"
D.Strings[105530]="你要召唤什么吗？"
D.Strings[105531]="滚去黑暗的冥狱深渊吧！"
D.Strings[105532]="来吧！我的人需要帮助！"
D.Strings[105533]="干得好。到莱莫扎夫人的塔楼附近来找我吧，我来召唤传送门。"
D.Strings[105534]="记住，在夜之子灵魂石吸取能量时，离它远点！"
D.Strings[105535]="这个法师会把你送过来。这任务可不简单，做好准备！"
D.Strings[105536]="等你到了之后，我们会打开恶魔国度的传送门……并彻底解决他！"
D.Strings[105537]="先知已经准备好了咒语，我也冥想了很久。库鲁尔死定了。"
D.Strings[105538]="我已经把位置告诉了你的法师。等你一到，我们就进入图加的洞穴并解决他。"
D.Strings[105539]="我们得在他进攻雷霆图腾前干掉他，还有他那该死的宠物。不过，这可不容易。"
D.Strings[105540]="图加·鲜血图腾又出现在了至高岭。他还带着一只灌注了邪能的巨型蠕虫。"
D.Strings[105541]="来吧，$n，去让艾德里斯彻底安息。"
D.Strings[105542]="有两位来自鲑鱼溪的勇猛战士坚持要参战。但即使有他们帮忙，这场战斗依然危险。"
D.Strings[105543]="是时候了，我的朋友。我在黑鸦堡垒的上层塔楼里找到了艾德里斯。他打算复活一支亡灵大军！"
D.Strings[105544]="我回守护者圣殿去等你，大法师$n。"
D.Strings[105545]="我说，你就这么想吃我一剑吗？"
D.Strings[105546]="我是北郡骑士麦斯米兰，少女的保护神！你怎么敢这样？！"
D.Strings[105547]="你知道自己在跟谁说话吗？"
D.Strings[105548]="那就再见吧。"
D.Strings[105549]="走开！我还得去屠龙呢！"
D.Strings[105550]="我们一起去斩杀强大的怪兽吧！"
D.Strings[105551]="我们又见面了，侍从！"
D.Strings[105552]="多么古怪的巨龙！但没关系！"
D.Strings[105553]="神剑！进攻！"
D.Strings[105554]="我要用强大的长剑杀了你！"
D.Strings[105555]="好吧，也不是很难。"
D.Strings[105556]="又一名恶魔倒在了我的重击之下！"
D.Strings[105557]="你看到我的胜利了吗，侍从？"
D.Strings[105558]="我得……稍事休息。"
D.Strings[105559]="协助我！"
D.Strings[105560]="交给你了，侍从。"
D.Strings[105561]="别担心我，大宗师。我带着水下呼吸药剂呢。"
D.Strings[105562]="啊，游泳真是提神醒脑……我想起了游到科赞那次。可大宗师罗处对他起皱的爪子有点不高兴！"
D.Strings[105563]="我跟你说过猢狲和奶油馅饼的故事吗？唔……或许最好的应该留到最后。"
D.Strings[105564]="大宗师，聪明的酒仙能善用美酒……而不会被美酒控制。"
D.Strings[105565]="不要害怕失败，大宗师，跌倒了再爬起来就行。"
D.Strings[105566]="俗话说的好，亡羊补牢，为时未晚。"
D.Strings[105567]="聪明的武僧总能认清自我，从不人云亦云。"
D.Strings[105568]="风筝在风的帮助下才能高飞，大宗师。"
D.Strings[105569]="大宗师，纸上谈兵和缘木求鱼一样荒唐。"
D.Strings[105570]="记住，过了河才能拆桥！"
D.Strings[105571]="你有进步了吗，大宗师？"
D.Strings[105572]="懒汉是成不了大事的，大宗师。"
D.Strings[105573]="多听听不同意见，大宗师。俗话说得好：兼听则明，偏信则暗。"
D.Strings[105574]="懒牦牛从不洗澡。"
D.Strings[105575]="祝你好运，大宗师！"
D.Strings[105576]="或许你该少吃点魔法汉堡，大宗师……"
D.Strings[105577]="又见面了，大宗师。"
D.Strings[105578]="我们今天去哪儿，大宗师？"
D.Strings[105579]="我准备好送你去英灵殿了。等你的盟友到齐且做好准备时，就跟我说一声。"
D.Strings[105580]="我们应该放弃！燃烧军团的力量会毁掉我们的！"
D.Strings[105581]="我们一起回迷踪岛吧！"
D.Strings[105582]="你的技巧真令人印象深刻，大宗师！我曾经效忠过许多伟大的武僧领袖，很荣幸能为你效劳。"
D.Strings[105583]="你显然具备了大宗师的睿智、正直和坚强。现在只剩一个试炼了……证明你还拥有大宗师的力量吧！"
D.Strings[105584]="你对卜大师耐心，对土地精尊重，对影踪派负责，而且信赖锦鱼人。"
D.Strings[105585]="但在这次反省中，我看到了一个非常有趣的人……你！"
D.Strings[105586]="由于为大宗师海特之死难过，我一直四处云游，自我反省。"
D.Strings[105587]="他不在？你确定？或许你该再观察一下，大宗师……"
D.Strings[105588]="大宗师！你找到班禄了吗？"
D.Strings[105589]="大宗师，我有个主意……"
D.Strings[105590]="看来我们走进了死胡同。我要通过冥想思考一下。"
D.Strings[105591]="大宗师，我们可以继续寻找班禄了吗？"
D.Strings[105592]="你去哪儿了？噢，等着。谢谢你能对老人这么有耐心。"
D.Strings[105593]="走慢点好吗？抱歉，我的脚已经软了。"
D.Strings[105594]="等等我！我这把老骨头已经大不如前了。"
D.Strings[105595]="呼！真是刺激又累人的旅程。请让我休息一会儿。或许你可以问问这些土地精是否见过班禄。"
D.Strings[105596]="噢！一行爪印！看看它们通向哪里……"
D.Strings[105597]="你发现了什么？我看看……"
D.Strings[105598]="去找找有关班禄下落的线索吧。"
D.Strings[105599]="大宗师！这边。"
D.Strings[105600]="或许我们该回到那里去寻找他的下落。"
D.Strings[105601]="但自从军团入侵晴日峰后，班禄就失踪了。看来那次灾难……深深地触动了他。"
D.Strings[105602]="数百年来，班禄一直是历代大宗师的坐骑。他也为这个身份而感到自豪！"
D.Strings[105603]="至尊天神之一的白虎雪怒有个叫做班禄的儿子。"
D.Strings[105604]="大宗师！有空听听老人家的故事吗？"
D.Strings[105605]="那一夜后，我成了家族唯一的幸存者。"
D.Strings[105606]="我只能安慰自己他们迟早会受到诸神的审判。"
D.Strings[105607]="但这没用。他们每次都能脱身。我得集中精神完成眼前的任务。"
D.Strings[105608]="又有埋伏！拿起武器！"
D.Strings[105609]="胆小鬼！如果让我知道他们的来历，我一定要杀光他们和幕后主使。"
D.Strings[105610]="我忘不了他们来袭的那一夜。我母亲和弟弟在我眼前倒下，而我只能落荒而逃。"
D.Strings[105611]="看来我是别想摆脱过去了。"
D.Strings[105612]="保持警惕。他们可能还没放弃。"
D.Strings[105613]="我生活在这里时，整日都在躲避暗杀我家族的刺客。"
D.Strings[105614]="树丛里有动静！小心！"
D.Strings[105615]="我们在风暴峡湾的瓦狄斯丹见，再从那里前往斯考德-艾希尔。"
D.Strings[105616]="很荣幸与你并肩战斗，战争领主$n。我要去苍穹要塞了。回头见！"
D.Strings[105617]="<彻夜狂欢，并在神射手营地中醒来。>"
D.Strings[105618]="精彩的狩猎！此时此地，这才是真正的荒野之魂。让我们彻夜狂欢，将烦恼留到明天吧！"
D.Strings[105619]="随着你的靠近，%s大声叫了起来。"
D.Strings[105620]="安静，阿维亚什。$n是我们的盟友。"
D.Strings[105621]="蔑潮的命运就看你的了。愿诸神与你同在，外来者！"
D.Strings[105622]="你们的肯瑞托能送你去奥丁的殿堂。快！必须让希格林清醒过来，否则就迟了！"
D.Strings[105623]="外来者！希格林冲去英灵殿挑战奥丁了。她被怒火冲昏了头脑，这是自寻死路！"
D.Strings[105624]="唔，它原本肯定是夜之子为了构建和谐婚姻而制造出来的。噢——而且它必须是刚刚制造完毕，尚未使用的。只要以上任何一点不满足，结果就会是场灾难。\n\n如果流言是真的，艾萨斯或许能帮上忙。据说他收了一个非常漂亮的夜之子学徒！这简直是丑闻。\n\n你得请他把你介绍给她。"
D.Strings[105625]="我该去哪儿找这种东西？"
D.Strings[105626]="他必将崛起！他将……统治……"
D.Strings[105627]="守望结束了！别唤醒……黑暗之王……"
D.Strings[105628]="世界的希望将给你们陪葬！"
D.Strings[105629]="守望继续。但……我在为谁效劳？"
D.Strings[105630]="软弱的血肉之躯！"
D.Strings[105631]="必然的结局。"
D.Strings[105632]="你们休想干扰主人的工作！"
D.Strings[105633]="下面的东西不能被凡人看到！"
D.Strings[105634]="坚定的目标遭遇了不可抗力，我听到……新的召唤。"
D.Strings[105635]="我坚定守望了千万年。然后，他的声音召唤了我。"
D.Strings[105636]="我并不是第一个守护这座神殿的人，可我担心受命保护这里的古代守护者都已经……小心。我会尽可能地保护你们的。"
D.Strings[105637]="杀了我，凡人！然后夺回欺诈者的战利品！"
D.Strings[105638]="身体……头脑……损坏了。我让造物者失望了！"
D.Strings[105639]="我准备好赴宴了。"
D.Strings[105640]="奥丁和他最伟大的猎人正在永恒猎场等着你呢。"
D.Strings[105641]="你的恶魔视觉可以帮你追踪它的血迹。"
D.Strings[105642]="干得好！有你这样的勇士在，我们的世界就不会沦陷！"
D.Strings[105643]="欢迎，勇士。你是应奥丁的召唤而来的吗？"
D.Strings[105644]="我体内的风暴之怒在沸腾！你做好准备了吗？"
D.Strings[105645]="看看呼啸的战斧吧！"
D.Strings[105646]="我父亲的鲜血之力在我体内流淌！"
D.Strings[105647]="你准备好了就说一声，勇士。然后我们就起飞。"
D.Strings[105648]="那个恶魔渣滓亵渎了这片土地，勇士。我们得消灭它！"
D.Strings[105649]="|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s开始引导|cFFFF0000|Hspell:237945|h[邪父之血]|h|r !"
D.Strings[105650]="|TInterface\\Icons\\ABILITY_WARLOCK_SHADOWFURYTGA.BLP:20|t附近的地面上出现数枚|cFFFF0000|Hspell:237908|h[符文]|h|r。"
D.Strings[105651]="|TInterface\\Icons\\ABILITY_WHIRLWIND.BLP:20|t%s制造了一场|cFFFF0000|Hspell:237866|h[剑刃风暴]|h|r！"
D.Strings[105652]="|TInterface\\Icons\\ABILITY_WARRIOR_RAMPAGE.BLP:20|t%s获得了|cFFFF0000|Hspell:237947|h[狂战士之怒]|h|r !"
D.Strings[105653]="|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t%s开始施放|cFFFF0000|Hspell:237952|h[先祖知识]|h|r！"
D.Strings[105654]="|TInterface\\Icons\\ACHIEVEMENT_BOSS_SVALASORROWGRAVE.BLP:20|t阵列中的数名黑暗瓦格里|cFFFF0000|Hspell:237761|h[冲过]|h|r战场！"
D.Strings[105655]="德克加尔绝不投降！"
D.Strings[105656]="我的力量来自先祖！"
D.Strings[105657]="这么多宝藏，就等着我伸手去拿了！"
D.Strings[105658]="我能号令千军万马，凡人！"
D.Strings[105659]="燃烧军团可能想拖垮我们——让我们的盟友像被暴雨侵袭的山谷一样逐渐崩溃，但我们绝不会投降。这是我们与生俱来的天性，我们一定会战斗至太阳再次升起的那一刻。"
D.Strings[105660]="好好研究这些符文，$c。我可不想知道失败的后果！"
D.Strings[105661]="我在那儿等你。动作快点，否则就迟了！"
D.Strings[105662]="大德鲁伊！我需要帮助！"
D.Strings[105663]="肯瑞托的法师能开启通往他身边的临时传送门。你得阻止克希雷姆……但可能的话，请饶他一命！"
D.Strings[105664]="在那里，克希雷姆能用聚焦之虹在魔网内掀起浩劫。"
D.Strings[105665]="德鲁伊们！我们胜利了。艾维娜雕像已经安全了。大德鲁伊，把雕像放到基座上去吧。"
D.Strings[105666]="成功了。我们把雕像送回梦境林地吧。"
D.Strings[105667]="我玩腻了！"
D.Strings[105668]="艾维娜！请帮帮我们！"
D.Strings[105669]="你太迟了，小德鲁伊！这飞行力量将帮我们摧毁达拉然！"
D.Strings[105670]="错！你才死定了，恶魔！"
D.Strings[105671]="军团！有了这雕像，那座浮空城就没法庇护懦弱的凡人了。"
D.Strings[105672]="先看看出了什么事……小心点！"
D.Strings[105673]="我们阿苏纳见，大德鲁伊。"
D.Strings[105674]="什么……飞行形态不管用？！没有神像，我们也失去了双翼！所有人传送到梦境林地重新集结！"
D.Strings[105675]="圣殿失守了。全体起飞！撤退！"
D.Strings[105676]="你这卑鄙的……不！神像！"
D.Strings[105677]="死在军团的力量之下吧！"
D.Strings[105678]="死吧，魔崽子！"
D.Strings[105679]="你听到没有？圣殿的方向传来了尖叫声！我们得回去！"
D.Strings[105680]="去他的前线！我要绕到后方去除掉那些施法者和火炮。你可以跟我一起去！"
D.Strings[105681]="大德鲁伊！艾维娜圣殿又遭到攻击了，这次是全面入侵！那位半神需要帮助！"
D.Strings[105682]="我准备好了，主母。"
D.Strings[105683]="安息吧，酒仙。"
D.Strings[105684]="我该走了，朋友们。阿麦，你已经成熟，不再是个普通的酿酒师了。"
D.Strings[105685]="大宗师，你就是那道光！不要动摇你对抗军团的决心！"
D.Strings[105686]="我看见，无穷恶魔像海啸般淹没我们……所有光都熄灭了……只有一处例外。"
D.Strings[105687]="我的身体、灵魂……在燃烧……"
D.Strings[105688]="金刚不坏彭戍虚弱地咳嗽着。"
D.Strings[105689]="我要去邪翼岩架。"
D.Strings[105690]="战争领主万岁！ Lok-tar！"
D.Strings[105691]="很荣幸能与你并肩战斗，战争领主$n。我去苍穹要塞了。"
D.Strings[105692]="他老了，但还很强壮！他能挺过去的……对吧？"
D.Strings[105693]="我残余的力量能救你们！"
D.Strings[105694]="裂口能抵抗她的魔法！"
D.Strings[105695]="我的结界还在！它能保护你！"
D.Strings[105696]="祝你好运，$c。你需要运气……"
D.Strings[105697]="看来法姆巴尔找到了你们失踪的法师。我这就召他回来。"
D.Strings[105698]="|TINTERFACE\\ICONS\\Ability_BossFelLord_FelSpike.blp:20|t多玛塔克斯开始施放|cFFFF0404|Hspell:234107|h[混沌能量]|h|r！快隐蔽！"
D.Strings[105699]="法姆巴尔没有任何发现……"
D.Strings[105700]="法姆巴尔发现了什么……"
D.Strings[105701]="我……不太舒服……"
D.Strings[105702]="很好……等他们过去后，愚蠢的“抗魔联军”就死定了。他们的末日即将到来。"
D.Strings[105703]="我会尽快通知召唤师的。他们只会听我的指令开启传送门。"
D.Strings[105704]="我们即将发动攻击。你召集完部队了吗？"
D.Strings[105705]="小心，勇士！我们得盯着敌人，因为他们也会盯着我们！"
D.Strings[105706]="开席吧！为了荒野之夜！为了巨兽！为了狩猎大师！"
D.Strings[105707]="哈哈，我想它喜欢你，猎人！现在，你和这头野兽已经缔结了契约，这种契约超越了这个世界，能影响凡世。现在，让我们回到宴会上去吧，把那些烦恼留到明天！"
D.Strings[105708]="你愿意接受这头狼鹰的陪伴吗？"
D.Strings[105709]="你明白这个传说要告诉我们什么吗？伙伴的力量总比孤身一人要强得多。"
D.Strings[105710]="现在，回篝火边来吧，好猎人，让我们彻夜畅饮！"
D.Strings[105711]="她的灵魂与你签订了契约，她的孩子就将在凡俗世界响应你的召唤。"
D.Strings[105712]="她认可了你。霍克努夫尼尔与这位猎人同在！"
D.Strings[105713]="她感到了你的力量和与野兽的羁绊。猎人，靠近她，接受她的考验吧。"
D.Strings[105714]="那是霍克努夫尼尔，世界初生时的荒野之王！"
D.Strings[105715]="什么？最罕见最强大的兽灵出现了，它已有无数年未曾光临这片土地了。"
D.Strings[105716]="看！狼母菲瑞奇，地上最强的野兽，和强大的天空之王维托尼尔。"
D.Strings[105717]="兽灵们对你的评价很高，狩猎大师。我们传说中著名的掠食者都出现了。这真是我见过的最盛大的荒野之夜！"
D.Strings[105718]="恐怖深渊之王拉努夫战胜了哈布洛克。拉努夫与这位猎人同在！"
D.Strings[105719]="巨枭哈布洛克就在你头上。野兽都畏惧她的利爪，并在夜里躲避着她锐利的视线。"
D.Strings[105720]="野蛮杀戮之王托尔捕杀了凯特林尔。托尔与这位猎人同在！"
D.Strings[105721]="巨豹凯特林尔正在你面前喝水。这个轻盈、凶猛的掠食者有着可怕的獠牙和利爪！"
D.Strings[105722]="加罗斯是黑色风暴之王布约恩带来的。布约恩与这位猎人同在！"
D.Strings[105723]="你发现了巨虫加罗斯的踪迹。她有许多孩子，藏身在地道深处。"
D.Strings[105724]="海提尔是岩石峭壁之王赫尔多抓来的。今夜，赫尔多与这位猎人同在！"
D.Strings[105725]="巨鹿海提尔出现了！他最为敏捷，还有长矛般锋利的角。祝你好运，猎人！"
D.Strings[105726]="在黑暗中寻找这些聪明的野兽可不容易，但真正的猎人也是追踪大师。"
D.Strings[105727]="猎人，你吃饱之后，就离开餐桌进入荒野吧。猎物在等待着你！"
D.Strings[105728]="举杯向我们的猎兽者——狩猎大师致敬吧！"
D.Strings[105729]="去狩猎那些高贵的兽魂，让它们安息。"
D.Strings[105730]="我们之中有个人已被选中，将走入黑夜。"
D.Strings[105731]="今日之夜，传说中的巨兽之魂将出现在这片土地上。"
D.Strings[105732]="荒野之夜再次降临了，朋友们。"
D.Strings[105733]="军团派了全视之眼来侦察我军部署。不可容忍！别让他们发现任何对我们不利的情报。"
D.Strings[105734]="谁都别想骗过燃烧军团。"
D.Strings[105735]="你听到没有？声音是从这上面传出来的！"
D.Strings[105736]="入侵者？出来！"
D.Strings[105737]="%s的邪能炸弹爆炸了！"
D.Strings[105738]="呸呸呸！真没想到我会兴高采烈地喝下那么恶心的东西！"
D.Strings[105739]="我太虚弱了……谢谢你的帮助！"
D.Strings[105740]="祝福你，大宗师！"
D.Strings[105741]="这可真……刺激……"
D.Strings[105742]="阿加莎……会……很高兴的……"
D.Strings[105743]="但愿这个能比上一个有趣一些。"
D.Strings[105744]="我们来玩玩吧，$c！"
D.Strings[105745]="别担心，乌丽娅——这家伙看起来很有精神。$G他:她;肯定不会轻易放弃的。"
D.Strings[105746]="好了！成了。"
D.Strings[105747]="让开，我来把草药放进酒里……"
D.Strings[105748]="你们坚定的意志鼓舞了部队。这说明，只要团结，我们就能拯救艾泽拉斯！"
D.Strings[105749]="天呐，看来阿加莎又发现了一个有趣的小玩具。"
D.Strings[105750]="军团抵挡不了圣光的力量。因为圣光有你这样的勇士！"
D.Strings[105751]="你今天拯救了许多生命，英雄。感谢你的高贵行为。"
D.Strings[105752]="你将圣光带到了这个黑暗之地。谢谢。"
D.Strings[105753]="勇士！圣光需要你！"
D.Strings[105754]="圣光庇佑！盟友需要你。勇士，请帮帮他们！"
D.Strings[105755]="召集盟友吧，英雄。你将要面对的威胁是个重大挑战！必须竭尽全力。"
D.Strings[105756]="你和你的朋友们战斗力惊人。只要我们齐心协力，必将战胜军团！"
D.Strings[105757]="我又欠了你一声谢谢。我都快习惯欠你人情了！"
D.Strings[105758]="干得好！你打击目标的手段让我想起了年轻的时候。那时我还是个小伙子呢。"
D.Strings[105759]="你挽救了很多生命，勇士。你应该自豪！"
D.Strings[105760]="干得好！至少……我们暂时击退了军团。"
D.Strings[105761]="召集盟友吧，勇士。我们遭遇严重威胁，需要英雄！"
D.Strings[105762]="这边！快来！"
D.Strings[105763]="这边，勇士！"
D.Strings[105764]="斥候报告说附近有个致命的敌人。我们该采取主动！"
D.Strings[105765]="附近的盟友有麻烦了，勇士。快帮帮他们！"
D.Strings[105766]="英雄！敌人已渗透了这一带。我们就靠你了！"
D.Strings[105767]="你抵挡不了我！"
D.Strings[105768]="让我看看你的决心！"
D.Strings[105769]="你大难临头了！"
D.Strings[105770]="碾碎你！"
D.Strings[105771]="烧吧！在痛苦中燃烧吧！"
D.Strings[105772]="还有……更多……痛苦……"
D.Strings[105773]="我赢得了荣耀……还剥夺了这些凡人的荣耀。"
D.Strings[105774]="又一个敌人倒下了！"
D.Strings[105775]="太脆弱了！"
D.Strings[105776]="来迎接末日吧！"
D.Strings[105777]="你的痛苦只会取悦我！"
D.Strings[105778]="入侵者！杀了你们就能赢回主人的欢心！"
D.Strings[105779]="这地方尽是恶毒的能量。我们走！"
D.Strings[105780]="你好像丢了什么东西。需要我帮忙吗？"
D.Strings[105781]="需要炸什么东西吗？老伊克斯这里就有合适你的法杖！"
D.Strings[105782]="你和你的战友打得很好。在即将到来的战斗中，这种坚定尤为可贵。"
D.Strings[105783]="这样一个强敌的死能鼓舞士气……并在恶魔心中埋下恐惧的种子。"
D.Strings[105784]="打击军团并非只能依靠蛮力。干得好！"
D.Strings[105785]="精彩的战斗。军团开始惧怕你了！"
D.Strings[105786]="我需要你和你的盟友，勇士。召集部队吧！"
D.Strings[105787]="来了个强敌。用尽一切手段打倒它吧！"
D.Strings[105788]="我们是朋友啊！你怎么能对我和我的家人做这种事？"
D.Strings[105789]="看来我最终还是被那个恶魔的毒药毒死了……"
D.Strings[105790]="我真想睡上一整天。"
D.Strings[105791]="<打哈欠>已经要回去干活儿了吗？"
D.Strings[105792]="勇士，我们的盟友需要帮助。快行动吧！"
D.Strings[105793]="它会在哪儿呢？！"
D.Strings[105794]="我肯定把它丢在这附近了……"
D.Strings[105795]="你不如去找找还有什么值得回收的。"
D.Strings[105796]="勇士！我们需要你！准备战斗！"
D.Strings[105797]="欢迎来到铭文师的殿堂，$c。需要我为你推荐几种卷轴吗？"
D.Strings[105798]="燃烧军团重创了这片土地。这里似乎没有幸存者了。"
D.Strings[105799]="又一个！与这些“恶魔”结盟绝对是个错误。"
D.Strings[105800]="<叹气>又死了一个哨兵。"
D.Strings[105801]="<叹气>他走得太早了。"
D.Strings[105802]="愿艾露恩指引你的灵魂，孩子。"
D.Strings[105803]="他们永远想不到它会埋在这里……"
D.Strings[105804]="等你回去之后，我会送上谢礼的。但愿它能对你有用。"
D.Strings[105805]="分裂的我们只能风流云散，而团结的我们则能风卷残云。但愿这议会从此长存。"
D.Strings[105806]="我已经是风元素领主了，你们都在我的国度中飘荡。我们别给这个议会留下一丝浊气。"
D.Strings[105807]="我看到先知已经说服你们向我投诚了。很好。让我清除你们脑中最后的一丝疑虑吧。"
D.Strings[105808]="一旦他们发现你的意图，就会想方设法把你逐出这个位面。但我会祝福你，这能暂时防止他们得逞。"
D.Strings[105809]="花言巧语毫无意义，恶魔。见识一下我领导的大军的怒火吧！"
D.Strings[105810]="他们认定萨尔萨隆才是王位的正统继承人。我要你说服他们改变主意。"
D.Strings[105811]="风会将我的意志传递到这个星球最遥远的角落，但是我不可能无处不在。在天空之墙，我的某些臣民还未能接受我的晋升。"
D.Strings[105812]="这家伙得好好打理一番，然后才能跟你去邪能之槌号。去跟耶德瑞斯谈谈，他会送你回船的。"
D.Strings[105813]="艾德里斯……你真没用！我们……不怕你！"
D.Strings[105814]="|TInterface\\Icons\\INV_SPEAR_08.BLP:20|t%s用|cFFFF0000|Hspell:235933|h[苦痛之矛]|h|r瞄准了|cFFFF0000$n|r！"
D.Strings[105815]="这……不对劲。我在哪儿？"
D.Strings[105816]="怎么回事？有股黑暗力量……侵蚀着我……"
D.Strings[105817]="|TInterface\\Icons\\Ability_Rogue_BloodyEye:20|t萨什比特的|cFFFF0000|Hspell:237726|h[轻蔑凝视]|h|r锁定了|cFFFF0000$n|r！"
D.Strings[105818]="他肯定会派仆从来阻止我们。我得全力以赴才能维持传送门，这样，挡住他们的任务就交给你了。"
D.Strings[105819]="我来激活传送门。等它开启后，我要你放下召唤石，将阿拉萨斯和愤怒战马吸引过来。"
D.Strings[105820]="你有恶魔视觉，要追踪它很容易。但如果它逃回出生地，那要把它带回来就难了。蝙蝠非常……活跃。"
D.Strings[105821]="抱歉，屠魔者，它跑了。但你看到了吗？这是血迹。这就方便了！"
D.Strings[105822]="快，束缚住它！"
D.Strings[105823]="驯服这种桀骜的野兽需要强大的气势。那当然是我的长处……但这次，我建议直接把它打服。"
D.Strings[105824]="几天前，这只魔蝠袭击了我们的营地。生擒成年的魔蝠是很难的，所以我坚持留下了它。"
D.Strings[105825]="伊利达雷！放它出来！"
D.Strings[105826]="|TInterface\\ICONS\\Ability_FelArakkoa_FelDetonation_Green:20|t小心！躲开|cFFFF0404|Hspell:238005|h[灾变新星]|h|r以免离开船只！"
D.Strings[105827]="我从未这么鲜活过！"
D.Strings[105828]="多米尔迅速干掉了他们。听到尖叫声了吗？多么美妙！"
D.Strings[105829]="四骑士挡住了那些恶魔。"
D.Strings[105830]="又来了一群！把他们送进坟墓！"
D.Strings[105831]="快看天启四骑士！他们居然能抗住那么多敌人，不可思议。"
D.Strings[105832]="军团将在多米尔的阴影下瑟瑟发抖。在死亡与毁灭面前，它们都会跪地求饶！"
D.Strings[105833]="那些恶魔……呸！我们绝不认输，何况我们还控制了多米尔和她的子嗣。"
D.Strings[105834]="准备好亮出秘密武器了吗？"
D.Strings[105835]="你们阻止不了我！来吧，士兵们！"
D.Strings[105836]="我厌倦了等待。"
D.Strings[105837]="克索诺斯祭师开始施放灾厄降临！"
D.Strings[105838]="我来挡住库鲁尔的爪牙。接受痛苦的试炼吧。"
D.Strings[105839]="我应该能重新激活他们的传送门。这地方充斥着灵魂。"
D.Strings[105840]="|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|t%s用|cFFFF0000|Hspell:236304|h[灵体射击]|h|r瞄准了你！"
D.Strings[105841]="我也去，大宗师。别再浪费时间了！"
D.Strings[105842]="精彩的表现。要是我们的部队也能接到这种任务该有多好。现在，在援军找到你之前，快出去吧。"
D.Strings[105843]="马瑞斯和他的宠物术士逆转了一座恶魔传送门。穿过它，看看你能给另一边造成怎样的破坏吧。"
D.Strings[105844]="这不怪你，阿麦！但……我们得快点……找到解药。已经有人丧命了……"
D.Strings[105845]="那个恶魔袭击了我，在庆祝美酒里下了毒，还变成我的样子……"
D.Strings[105846]="我们得回五晨寺去！你准备好了就告诉我！"
D.Strings[105847]="在危险面前迟疑并不是弱点，而是起来响应战斗召唤的机会。"
D.Strings[105848]="我闭着眼睛都能酿出好酒。但织雾之道对我来说是个挑战。我希望有一天能成为这方面的高手。"
D.Strings[105849]="四风谷的生活太平静了，这对大部分人都算是好事。但对我来说，这就太无聊了。我更希望能时不时来点刺激的。"
D.Strings[105850]="我的家族世代酿酒，所以这门手艺已经成了我的本能！但我还是想尝试一些不同的东西。"
D.Strings[105851]="所谓路遥知马力。我们必须牢记自己的训练。"
D.Strings[105852]="我们必须保持镇静！让盟友们看看我们真正的精神面貌！我们不会变成恶魔希望的样子！"
D.Strings[105853]="抬起头来，年轻的战士。我们的旅途才刚刚开始。"
D.Strings[105854]="我们得保持坚强。"
D.Strings[105855]="我知道现在很疼，但多年后当我们回顾今天，回忆我们为之奋斗的一切，以及我们所付出的一切，我们会发现正是这一切成就了我们。"
D.Strings[105856]="许多战士在风暴来临时都会隐蔽起来，但现在可没时间隐蔽。我们得举起武器，直接冲向大自然的心脏。"
D.Strings[105857]="他们很强大，有着比夏日的高温还要灼热的鲜血。我向你保证，他们会慢慢恢复的。但我们也要尽自己的一份力，尽快赶回去！我们的人民需要我们！"
D.Strings[105858]="我不得不……抹杀……你们的存在！"
D.Strings[105859]="凡人无法理解我的职责。这神圣的任务就是……侍奉主人！"
D.Strings[105860]="是时候了！你的死期到了！"
D.Strings[105861]="站起来！对……站起来！"
D.Strings[105862]="你们体内充满了能量！消灭这些恶魔！"
D.Strings[105863]="这是命令！"
D.Strings[105864]="站起来吧，士兵们！"
D.Strings[105865]="如果这就是你们世界最强的猎人，那它就真该完蛋了！"
D.Strings[105866]="又来了吗？我的猎犬会撕碎你的！"
D.Strings[105867]="我不怕野兽！军团是无穷无尽的！"
D.Strings[105868]="酒仙！不！"
D.Strings[105869]="出……出什么事了？她什么意思？大宗师，我们得立刻赶回寺院！你准备好了就说一声！"
D.Strings[105870]="我成功了，小武僧们。你们的教派完了！"
D.Strings[105871]="我就知道这么多了。"
D.Strings[105872]="阿麦，你可真单纯。可惜你必须死！"
D.Strings[105873]="酒仙？你在说什么？我们正到处找你呢！"
D.Strings[105874]="大宗师。你做的比我想的还要好。看来我得亲自对付你了！"
D.Strings[105875]="风暴蜜酒真棒！难怪军团会怕它！"
D.Strings[105876]="我无法选择命运……你们也一样！"
D.Strings[105877]="感受灵魂分裂的痛苦吧！"
D.Strings[105878]="来吧，这个世界的勇士们，让我一个一个干掉你们！"
D.Strings[105879]="织邪者！解决这些入侵者！"
D.Strings[105880]="他们的指挥官已死，护盾也被关闭，蓝龙们可以全力攻击舰船了。他们会在进攻开始前派人去接你的。"
D.Strings[105881]="$n！快，过来！我们解决它！"
D.Strings[105882]="幼龙会将我们送到军团的战舰上去对付他们的指挥官。等你解决了他，他们会抢在总攻开始前回去接你出来的。"
D.Strings[105883]="本地的蔚蓝幼龙已经答应帮助我们反抗燃烧军团，但他们需要你的帮助。尽你一切的力量协助他们吧。"
D.Strings[105884]="该去破碎海滩了，多米尔。"
D.Strings[105885]="<多米尔眼神空洞地对你点了点头。>"
D.Strings[105886]="你们的世界必将燃烧！"
D.Strings[105887]="为了至高岭的荣耀。我准备好了！[加入场景战役队列]"
D.Strings[105888]="我建议尽快行动。天空中布满了那些邪恶的畜生。\n\n我们直击燃烧军团核心的机会出现了。我们得把战火烧到前线上去。"
D.Strings[105889]="干得好，英雄。你的事迹将在英灵殿代代流传！"
D.Strings[105890]="摧毁他们的火炮和屏障，让英勇的瓦拉加尔跟他们真刀真枪地打一场！"
D.Strings[105891]="这些懦弱的恶魔都躲在防御工事后面。带上我的圣锤，去杀光他们！"
D.Strings[105892]="你们以为躲在这破酒坊里就能逃过一劫吗？军团无所不知！"
D.Strings[105893]="你们的努力太迟了，可怜虫们……"
D.Strings[105894]="军团是怎么知道风暴蜜酒的？我们一直严格保密的……"
D.Strings[105895]="我讨厌鱼人，但他们也不该死在燃烧军团的手里。谢谢你，英雄。"
D.Strings[105896]="太邪恶了！恶魔在抽取无辜的灵魂，为邪恶魔法供能。阻止他们，英雄！"
D.Strings[105897]="打得好！在这场战争中，每次胜利都很重要。"
D.Strings[105898]="我们的海岸上燃起了邪能之火！快进攻，不能让威胁侵入内陆。"
D.Strings[105899]="享受混乱吧……"
D.Strings[105900]="绝妙的讽刺！恶魔这么快就内讧了！"
D.Strings[105901]="傲慢的爬虫！这是无谓的挣扎！"
D.Strings[105902]="胜利的天平向我们倾斜了！去悬崖解决那个恶魔。等肃清天空，我就去那里找你。"
D.Strings[105903]="我是，呃，我们是……"
D.Strings[105904]="你不能把我的盟友变成你的无脑奴隶！"
D.Strings[105905]="我来把这些托林尼尔巨龙复活成我的士兵，下一个就轮到多米尔了。"
D.Strings[105906]="我来点火。我一直盼着这一刻呢！"
D.Strings[105907]="呃！我要离开这儿！"
D.Strings[105908]="布满虚空的黑暗就里有什么……？"
D.Strings[105909]="好痛！"
D.Strings[105910]="真粗鲁！"
D.Strings[105911]="哎唷！你为什么要这么对我？"
D.Strings[105912]="我只想休息一会儿……"
D.Strings[105913]="我终于看清了！"
D.Strings[105914]="我……在哪儿？"
D.Strings[105915]="黑暗消散了！谢谢你，英雄。"
D.Strings[105916]="|TInterface\\ICONS\\Ability_IronMaidens_ConvulsiveShadows.blp:20|t堕落的化身将你选为了|cFFFF0404|Hspell:236604|h[暗影之刃]|h|r的目标！"
D.Strings[105917]="我准备好面对希格林了（免费）。"
D.Strings[105918]="我准备好面对库鲁尔了（免费）。"
D.Strings[105919]="我准备好面对莱斯特了（免费）。"
D.Strings[105920]="我准备好面对克希雷姆了（免费）。"
D.Strings[105921]="很荣幸能见到你，大宗师。我们后会有期！"
D.Strings[105922]="送我去见阿加莎……（免费）"
D.Strings[105923]="我说——"
D.Strings[105924]="请让我——"
D.Strings[105925]="你，救救我！"
D.Strings[105926]="我的骨头！"
D.Strings[105927]="我不能——"
D.Strings[105928]="啊啊！！！"
D.Strings[105929]="我感觉我的血肉正在从骨头上剥落！"
D.Strings[105930]="什么都是绿色的，我看不见了！"
D.Strings[105931]="啊啊！好烫，好烫！"
D.Strings[105932]="送我去见影歌（免费）。"
D.Strings[105933]="我准备好面对图加·鲜血图腾了（免费）。"
D.Strings[105934]="抱歉，$n！你之前暂时拖延的那些灾难现在都可以解决了。请来跟我谈谈吧。"
D.Strings[105935]="无知是福。等他们明白这份礼物的代价时就已经迟了。木已成舟，但愿我的决定是正确的。"
D.Strings[105936]="这个决定令我心情沉重，但他们每天无忧无虑的笑容让我稍感欣慰。"
D.Strings[105937]="他们或许永远不会原谅我，但他们至少能苟活下来。我的家族暂时安全了。"
D.Strings[105938]="啊，故乡的天空！我居然还能见到这个世界。"
D.Strings[105939]="在我生前，欺诈者嘲笑过我的天赋。看看谁能笑到最后吧！"
D.Strings[105940]="小心！这个古代魔像里还有能量。你最好先摧毁它，免得军团继续为它充能。"
D.Strings[105941]="啊！这里全是泰坦的臭味！"
D.Strings[105942]="有趣的方法。要是他们只对自己的灵魂使用，会有更高的成就。"
D.Strings[105943]="我讨厌幽灵！他们总是唠叨着生前的一切。吞掉他们的灵魂，消灭他们！"
D.Strings[105944]="纳迦是堕落的种族。他们拥有魔力，但是缺乏我的族人天生的敏锐。"
D.Strings[105945]="确实如此，叔叔。但这至少是个开始……"
D.Strings[105946]="我知道自己罪孽深重。"
D.Strings[105947]="恶魔！全是恶魔！"
D.Strings[105948]="那蠢货把我当做收割能量的小玩意儿。他为自己的无知付出了代价！"
D.Strings[105949]="出……出什么事了？鲜血在……沸腾……我……我……"
D.Strings[105950]="%s眨了眨眼，表情困惑。他的眼睛里泛着邪能的光泽。"
D.Strings[105951]="恶魔……崇拜者？"
D.Strings[105952]="啊，我的前主人！复仇的时候到了！"
D.Strings[105953]="这家伙很强，但很蠢。这种仆从毫无用处。"
D.Strings[105954]="我知道一些古代咒语，能操纵这世界的生命之血。这里就是理想的施法地点。"
D.Strings[105955]="感觉到了吗？这世界的生命之血就在这儿的地下流淌。"
D.Strings[105956]="我们到了那群蠢货一败涂地的地方。记住，勇气无法取代力量。"
D.Strings[105957]="自从我们相识之后，你的技巧大有进步。再过几千年，你或许就能与我最出色的学徒比肩了。"
D.Strings[105958]="这里真像阿古斯……扭曲、支离破碎。我都有点想家了！"
D.Strings[105959]="你上次差点死在这里。算你走运，这次有我陪你。"
D.Strings[105960]="闻到风中烧焦的肉味了吗？啊，故乡的味道！"
D.Strings[105961]="军团投入此地的力量不过是九牛一毛。他们还有不少杀手锏呢。"
D.Strings[105962]="军团征服了这片海滩。很快，我们就会反过来征服军团！"
D.Strings[105963]="用我的黑锋之门，或者你自己开。我们阿彻鲁斯见。"
D.Strings[105964]="视线依然有点模糊，但我还能战斗。"
D.Strings[105965]="为了女王，去死吧！"
D.Strings[105966]="哈亚坦……不够……厉害……"
D.Strings[105967]="哈亚坦……让女王……失望了……"
D.Strings[105968]="打砸时间到了！"
D.Strings[105969]="来啊，小朋友！用点力！"
D.Strings[105970]="死亡！杀戮！"
D.Strings[105971]="你！去拿潮汐之石！"
D.Strings[105972]="去帮帮我们的野蛮勇士！"
D.Strings[105973]="仆从们！战斗！"
D.Strings[105974]="没用的畜生！真不明白女王喜欢他什么！"
D.Strings[105975]="闭嘴，蠢货！杀了他们！"
D.Strings[105976]="哈亚坦！碾碎他们的骨头！"
D.Strings[105977]="我受够这些失败者了！看看纳迦的真正实力吧！"
D.Strings[105978]="弱智！非要我亲自对付这群暴民吗？"
D.Strings[105979]="废物！你们竟敢让女王失望？"
D.Strings[105980]="杀光入侵者！夺回我们的东西！"
D.Strings[105981]="这些蠢货送潮汐之石来了！尊贵的女王早有预见！"
D.Strings[105982]="干得好。在杀了那些恶魔并夺回补给后，我们离攻占破碎海滩又近了一步。"
D.Strings[105983]="可悲的凡人。你一事无成！臣服吧……否则就死！"
D.Strings[105984]="让我的宠物活吞了你们！"
D.Strings[105985]="让深海吞噬你们！"
D.Strings[105986]="你们的灵魂属于深海！"
D.Strings[105987]="感受深海的冰冷吧！"
D.Strings[105988]="死神来抓你们了！"
D.Strings[105989]="大海涌动着力量！"
D.Strings[105990]="享用血肉吧！"
D.Strings[105991]="吃了他们！"
D.Strings[105992]="这种死法……有失身份……"
D.Strings[105993]="噢！……可耻……"
D.Strings[105994]="艾萨拉女王的统治不可动摇！"
D.Strings[105995]="一万年了，凡人还是那么可悲！"
D.Strings[105996]="洒鱼食了！"
D.Strings[105997]="该喂鱼了！"
D.Strings[105998]="以艾萨拉之名，去死吧！"
D.Strings[105999]="去肃清海滩上的恶魔部队，并取回那些战争物资。"
D.Strings[106000]="这片海滩上有前一次突袭中沉没的船骸，其中有对抗军团的关键物资。"
D.Strings[106001]="我很抱歉，德拉丝。我不敢奢求你的原谅，但我需要你的帮助。"
D.Strings[106002]="这……是你干的？你怎么能？"
D.Strings[106003]="他们的灵魂被军团束缚，只能为恶魔主子卖命。"
D.Strings[106004]="但这个契约却让我们的祖先遭遇了比死亡更可怕的命运。"
D.Strings[106005]="你得理解！我是想保护我们家族……"
D.Strings[106006]="奈鲁斯？解释一下，叔叔！"
D.Strings[106007]="终于！复仇……我复仇了！"
D.Strings[106008]="你的抵抗精神抵抗了污秽的邪能魔法！"
D.Strings[106009]="随着你离欺诈者越来越近，诅咒之喉开始拉扯你的手。"
D.Strings[106010]="谢谢你，英雄。今天，你帮了高岭诸族一个大忙。"
D.Strings[106011]="邪能图腾就在这里接受恶魔的训练。净化洞穴中的邪恶，把他们的主子送回扭曲虚空吧！"
D.Strings[106012]="我的错。看来那个傲慢的“女神”还盯着这里。好吧……"
D.Strings[106013]="守望者，死守大教堂！守住这里，让盟友攻入下方的墓穴。"
D.Strings[106014]="你可别死在别人手里了，背叛者！"
D.Strings[106015]="还活着吗，玛维？"
D.Strings[106016]="我来保护侧翼。没了我，你能行吗，守望者？"
D.Strings[106017]="这世界……必将属于……军团……"
D.Strings[106018]="你们的血肉将熊熊燃烧！"
D.Strings[106019]="军团之力将倾泻到你们头上！"
D.Strings[106020]="他们的护盾破了！一个不留！"
D.Strings[106021]="地狱火！摧毁他们的阵型！"
D.Strings[106022]="恶魔们！打破护盾！"
D.Strings[106023]="军团！烧焦他们的骨头！"
D.Strings[106024]="我的战斧渴望血肉！"
D.Strings[106025]="这座破败的神殿里残留着一些力量。它是我们的！来吧，进入法阵，夺取它。"
D.Strings[106026]="这家伙……很坚强。没事！这些灵魂会有用的。"
D.Strings[106027]="我代表基尔加丹感谢你们把圣盾送上门来。"
D.Strings[106028]="只有在欺诈者自己的地盘上才能击倒他。来吧，我们尝尝他的灵魂！"
D.Strings[106029]="让我指导你和这家伙战斗吧。虽然它只保留了一丝堕落泰坦的力量，但没有我的经验，你也毫无机会。"
D.Strings[106030]="入侵者胡乱腐蚀了其他入侵者……真老套。把他们骗上合适的道路会更有用，你说呢？"
D.Strings[106031]="傲慢的古代精灵那么珍惜自己的灵魂。多么绝妙的讽刺！"
D.Strings[106032]="我就喜欢看到仇敌的祭坛被他们自己的崇拜者的灵魂玷污。"
D.Strings[106033]="有时，纳迦会向军团乞讨一些残羹冷炙。但他们的女王还想要更多。"
D.Strings[106034]="从诞生的那一刻起，深渊领主就笨重而且愚蠢。军团还放大了这些特点。"
D.Strings[106035]="这家伙在这个世界肆虐已久。他的阴谋并未全部得逞，但得逞的那些都后患无穷。"
D.Strings[106036]="想想吧……一个军团恶棍毁灭了无价的知识。"
D.Strings[106037]="我感觉这世界的心跳正在加速。它的生命之血即将喷薄而出。"
D.Strings[106038]="你的盟友说我居心叵测。但我只是让你沿着选定的道路快步前进罢了。"
D.Strings[106039]="圣光只会把你们剩下的人变成迟钝的顺民。而我能提供自由和力量。希望你能记住我的慷慨。"
D.Strings[106040]="选择了你真好。其他使用者可不会像你那样大杀四方。我很欣赏你的“耐力”。"
D.Strings[106041]="这片土地变化真大。大灾变、大分裂、大清洗……你们根本不明白。"
D.Strings[106042]="大分裂之后，我花了几个世纪才回到地表。纳迦太痴迷于神器了。"
D.Strings[106043]="这场冲突只是上古战争的余波，那时还没有多管闲事的泰坦。无穷大军在无尽的战斗中碰撞。但你们的小战争……也有点看头。"
D.Strings[106044]="这点微不足道的小冲突只能算小打小闹。当轮回结束，真正的大战才会降临。"
D.Strings[106045]="我们……才是……最后的赢家……"
D.Strings[106046]="几个世纪前，深渊之神在此惨败于七头之神。但通常，失败最终都会转化为恩佐斯的优势。"
D.Strings[106047]="相比曾矗立于此的庞然大物，那高耸入云的邪能高塔不算什么。"
D.Strings[106048]="这里总是充满了力量。艾格文被吸引至此，之前是精灵，再之前是巨魔。而巨魔之前……"
D.Strings[106049]="交出圣盾，我就给你们一个痛快！"
D.Strings[106050]="多谢你们把圣盾送上门来！"
D.Strings[106051]="够了！让我看看，没了那玩意儿，你们还能干什么。"
D.Strings[106052]="我喜欢看你们痛苦的表情！"
D.Strings[106053]="你们抵挡不了军团的力量！"
D.Strings[106054]="小心暗影！"
D.Strings[106055]="逃？蠢货！我要杀光你们！"
D.Strings[106056]="我不信这片土地见识过堪比克坦斯之战的大屠杀。那是很久之前的事了……"
D.Strings[106057]="这不就是被你们凡人引以为耻的地方吗？但愿你们这次表现得好些……"
D.Strings[106058]="这么多死亡……这么多力量！"
D.Strings[106059]="你无处可逃了，恶魔！"
D.Strings[106060]="尽管装腔作势吧，玛维。但现在，请你尽力跟上我。"
D.Strings[106061]="你以为你逃得了吗，伊利丹？再跑的话，我就用链子把你拴起来。"
D.Strings[106062]="我去追恐惧魔王。你们来对付其他渣滓。"
D.Strings[106063]="恶魔堵住了前路，但他们挡不住我们的怒火。"
D.Strings[106064]="我去追伊利丹。你来对付这些怪物。"
D.Strings[106065]="又是伊利丹留下的烂摊子！跟紧点……我们得杀过去。"
D.Strings[106066]="伊利丹！见鬼，这太鲁莽了！"
D.Strings[106067]="啊，贵客终于到了。我要拔光你脑袋上的角，背叛者！"
D.Strings[106068]="你逃不出我的手心，恶魔！"
D.Strings[106069]="很好，大法师！我坚信你能成功。大法师万岁！秘法会万岁！"
D.Strings[106070]="生意不错。$b$b非常不错。$b$b<纳格尔将几枚硬币塞进了口袋。>$b$b诺格弗格先生一定会非常满意的——继续加油！"
D.Strings[106071]="灵魂石已经就位。使用魔法矩阵启动城市的防护吧！"
D.Strings[106072]="啊，别在意。等到莫格莱尼看到我们飞起来，他一定会吓一跳的！"
D.Strings[106073]="|TInterface\\Icons\\ACHIEVEMENT_BOSS_LORDMARROWGAR:20|t %s 颤抖着朝绝望的聚合体喷吐，使灵魂电路发生过载！"
D.Strings[106074]="还算不错。"
D.Strings[106075]="到底是什么引发了这次奔踏事件？"
D.Strings[106076]="你觉得我看起来像是术士吗？我完全不明白你为什么会这么想。也许这是季节性的狂奔行为，是恐惧战马迁徙或者求偶……或者随便跑着干些什么的季节。$b$b或者它们就是跑来妨碍咱们送酒的！"
D.Strings[106077]="很简单！你站到桶上去。$b$b你可以依靠出众的脚法躲开那些奔马，把桶送到地方！就像我师父常说的那样：“如果你能站在酒桶上躲开奔马，那你也能躲开敌人的重拳。”$b$b我接受的训练很……奇特。你看，你只要跳上那只酒桶，一直将它滚到巡逻队那里。还有，小心下面的马群！ "
D.Strings[106078]="噢，很高兴见到你。我们的兄弟姐妹正在斜坡下战斗，但他们的酒喝完了！$b$b这些惊慌失措的野兽四处乱跑，害得我们没法直接把酒桶滚下去……$b$b但我想到了一个主意……"
D.Strings[106079]="|TInterface\\Icons\\Spell_Deathknight_Defile:20|t灵魂世界中没有灵魂的存在，%s开始施放|cFFFF0000|Hspell:236507|h[寂灭]|h|r！"
D.Strings[106080]="|TInterface\\Icons\\Spell_Deathknight_Defile:20|t物质世界中没有灵魂的存在，%s开始施放|cFFFF0000|Hspell:236507|h[寂灭]|h|r！"
D.Strings[106081]="我们一起去拆掉那些恶魔的骨头吧！"
D.Strings[106082]="|TInterface\\Icons\\SPELL_SHADOW_SHADESOFDARKNESS:20|t%s 开始释放大群|cFFFF0000|Hspell:236075|h[哀嚎之魂]|h|r！"
D.Strings[106083]="|TInterface\\Icons\\ABILITY_WARLOCK_SOULLINK:20|t%s用|cFFFF0000|Hspell:236449|h[灵魂束缚]|h|r将生命精华捆绑在了一起！"
D.Strings[106084]="|TInterface\\Icons\\SPELL_WARLOCK_SOULBURN:20|t %s开始发出一连串|cFFFF0000|Hspell:236011|h[折磨哀嚎]|h|r！"
D.Strings[106085]="|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t%s命令萨鲁克张开|cFFFF0000|Hspell:234621|h[吞噬巨口]|h|r！"
D.Strings[106086]="|TInterface\\Icons\\Ability_Butcher_Whirl.blp:20|t%s开始施放|cFFFF0000|Hspell:232722|h[切割旋风]|h|r！"
D.Strings[106087]="苍穹要塞的瓦拉加尔们！欢呼吧，让它响彻殿堂！"
D.Strings[106088]="这让我们喘了口气。现在，我的人会守住阵线的。"
D.Strings[106089]="所有人都上前线。又来了一群恶魔！"
D.Strings[106090]="我想，军团低估了大自然，还有你的韧性和决心！"
D.Strings[106091]="至高岭的野生动物也起来反抗恶魔了！去打碎地狱火，找到他们入侵的源头。"
D.Strings[106092]="去雷霆图腾！我的骑手会守住天空，你来扫荡地面。"
D.Strings[106093]="打得好！我们的部队正……"
D.Strings[106094]="燃烧军团开进了至高岭！我的盟友正在本地与恶魔全面开战。勇士，为了扭转局面，你得直击他们的要害！"
D.Strings[106095]="法师塔被摧毁了，但很快就会修好的。"
D.Strings[106096]="法师塔遇袭！"
D.Strings[106097]="法师塔正在建设中。"
D.Strings[106098]="我……很不舒服。"
D.Strings[106099]="那东西……钻进了我的脑海。我停不下来！"
D.Strings[106100]="我的头……出什么事了？"
D.Strings[106101]="出……出什么事了？这里不是营地！"
D.Strings[106102]="嘿，接着！"
D.Strings[106103]="快想想办法！"
D.Strings[106104]="冲你去了！"
D.Strings[106105]="我想为法师塔捐献战争物资。"
D.Strings[106106]="你太小了！这简直就像陪兔子玩耍一样。"
D.Strings[106107]="你的战斗方式一点也不出奇，不过我也不在乎。你很快就会败在我的力量之下的。"
D.Strings[106108]="真是有趣，你居然还要坚持战斗，哪怕注定要失败。"
D.Strings[106109]="多么愉快的一天，因为我们找到了璀璨的珍宝！"
D.Strings[106110]="我已经完成训练了。"
D.Strings[106111]="接下来就交给我们好了。继续战斗吧，勇士。"
D.Strings[106112]="我们的骑手与军团展开了激烈的空战。去帮帮那些坠地的骑手。我们得守住这里！"
D.Strings[106113]="你的胜利为我的人民带来了希望。军团休想占领我们的土地！"
D.Strings[106114]="无论要做什么，你都能信任我。"
D.Strings[106115]="这次失败不会打垮我。"
D.Strings[106116]="走吧，别管我。我会跟上的。"
D.Strings[106117]="弱者必将被淘汰。"
D.Strings[106118]="有好玩的了！"
D.Strings[106119]="你会死在我手里的！"
D.Strings[106120]="有种就跑吧，但你跑不了多远！"
D.Strings[106121]="我们要一起保护这片土地。"
D.Strings[106122]="我是来与你并肩战斗的。"
D.Strings[106123]="小心，狩猎大师。我们不知道附近有什么危险。"
D.Strings[106124]="住手吧，否则就让德宾帮你住手。"
D.Strings[106125]="你跨过了不能逾越的界限！"
D.Strings[106126]="你肯定还会别的吧？"
D.Strings[106127]="你还真执著，是吧？"
D.Strings[106128]="我更喜欢你安静的样子。"
D.Strings[106129]="我愿意以黑暗收割的名义做任何事。"
D.Strings[106130]="让你看看我的力量！"
D.Strings[106131]="别让我拖你后腿。"
D.Strings[106132]="我感觉乏力……"
D.Strings[106133]="让我恢复一下力气。"
D.Strings[106134]="我们的力量在滋长！"
D.Strings[106135]="我们的力量无可匹敌。"
D.Strings[106136]="你不是我们的对手！"
D.Strings[106137]="感受黑暗收割议会的力量吧！"
D.Strings[106138]="这世界有太多无主的力量了。"
D.Strings[106139]="很荣幸能与你这样的强者并肩战斗。"
D.Strings[106140]="裘碧卡真该放逐你。"
D.Strings[106141]="你真想唤醒恶魔吗？"
D.Strings[106142]="我可不是好惹的！"
D.Strings[106143]="不该让黑暗收割议会的领袖浪费时间！"
D.Strings[106144]="你有病，是吗？"
D.Strings[106145]="我真傻，还以为罗兰已经够烦了。"
D.Strings[106146]="你觉得自己很聪明吗？"
D.Strings[106147]="这应该很有趣……"
D.Strings[106148]="这只是暂时的挫折。"
D.Strings[106149]="真是没想到。"
D.Strings[106150]="我需要一点时间。"
D.Strings[106151]="你的挣扎结束了。"
D.Strings[106152]="虚空在等着你。"
D.Strings[106153]="你该从这世界上消失！"
D.Strings[106154]="你死期将至！"
D.Strings[106155]="让暗影淹没我们的敌人！"
D.Strings[106156]="我来帮你了。"
D.Strings[106157]="你无需独自行动。"
D.Strings[106158]="会有惊喜等着我们吗？"
D.Strings[106159]="这一点都不好笑。"
D.Strings[106160]="我有这么罪大恶极吗？"
D.Strings[106161]="你无事可做了吗？"
D.Strings[106162]="这就是我做错了事的代价吗？"
D.Strings[106163]="既然你不尊重我，那就受死吧！勇士，帮我干掉这杂种！"
D.Strings[106164]="你不敢跟我单打独斗？先祖的神圣遗骨会唾弃你的可耻行为的！"
D.Strings[106165]="傻丫头。他们听命于我，而不是你所谓的荣誉！"
D.Strings[106166]="我会完成任务的。"
D.Strings[106167]="我为大领主而战！"
D.Strings[106168]="你得独自前进了。"
D.Strings[106169]="我需要休息一会儿。"
D.Strings[106170]="我的灵魂虚弱了……"
D.Strings[106171]="我们的意志很强大。"
D.Strings[106172]="迅捷而严厉的审判。"
D.Strings[106173]="接受审判吧！"
D.Strings[106174]="我会证明自己的。"
D.Strings[106175]="很荣幸能与你同行，大领主。"
D.Strings[106176]="我要弥补我的错误。"
D.Strings[106177]="事实上，还真有。\n\n不久前，有个流浪的女武神来到这里，在镇子外面建起了营地。她只有在购买补给时才会到镇上来，而且从不跟人有眼神交流。\n\n我本打算去盘问一下她的来意，不过你可以代我去问。她的营地就在东边的海滩上。"
D.Strings[106178]="最近有引人注目的维库人经过这里吗？"
D.Strings[106179]="我会盯着你的，外来者。"
D.Strings[106180]="我很熟悉瓦尔基拉的法德罗汀预言，但我没读过它的原文。让我看看你找到的卷轴。\n\n<布丽娜仔细阅读着卷轴上的文字。>\n\n如果这些卷轴说的是真的，那我们中间可能有一个斯科瓦尔德的后裔！无论瓦尔基拉怎么想，你一定要帮我们把她弄走。\n\n去俯视镇子的塔楼里找英薇德吧。她一直密切关注着进出贾德维克的人流。如果最近有值得注意的人来过，她应该会知道。"
D.Strings[106181]="斯洛迪说你能帮我找到这些卷轴中提到的这个维库人。"
D.Strings[106182]="我听到了斯洛迪的号角声。你就是他说的那个外来者吧？"
D.Strings[106183]="可怜的小狼！至少你帮它们摆脱了军团的奴役。谢谢你，勇士。"
D.Strings[106184]="我不知道你为什么会对维库人的预言感兴趣，但你带来的卷轴好像是真的。我会提醒贾德维克的维库人让你过去，好让你找到要找的人。\n\n女祭司布丽娜是村子里最有学问的人。或许你该去找她？"
D.Strings[106185]="我对预言了解不多，但自从斯科瓦尔德倒台后，贾德维克确实多了几张生面孔。\n\n你该去和女祭司布丽娜谈谈。她就住在镇中心。她可能知道你说的这个预言。"
D.Strings[106186]="我在寻找这些卷轴中提到的那个维库人。"
D.Strings[106187]="小心点，$c。贾德维克的维库人对外来者非常警惕。"
D.Strings[106188]="你好，$c. \n\n我已经收到了托尔里的命令——我的剑不会伤害你的。"
D.Strings[106189]="军团腐蚀了啸风山的狼，并驱使它们攻击苍穹之角。快阻止这种邪恶的仪式！"
D.Strings[106190]="你竟敢打断我？"
D.Strings[106191]="你好像……有点……不对劲。"
D.Strings[106192]="别想偷东西。我们盯着呢，一刻都不会放松。"
D.Strings[106193]="你想偷藏什么东西吗？"
D.Strings[106194]="回去干活儿。否则我就罚你去擦矿坑的笼子。"
D.Strings[106195]="你竟敢跟我说话？"
D.Strings[106196]="搞清你的身份，否则我不介意提醒你一下。"
D.Strings[106197]="啊，$n。我就知道你能行。面对燃烧军团时，我会做好准备的。"
D.Strings[106198]="我两次都差点死在恶魔手上。它们不会有第三次机会了。"
D.Strings[106199]="你不会后悔的，暗影之刃。我会干掉所有挡路的军团恶魔和叛徒！"
D.Strings[106200]="你竟敢来打扰燃烧军团的仆人！"
D.Strings[106201]="你的宝贝又少又乏味。你应该把它们交给我，让我去“扔掉它们”。"
D.Strings[106202]="谁派你来的？是不是瑞格强普？告诉他，是崔格图斯偷了他的亮晶晶。不是我！"
D.Strings[106203]="你别想轻易摆脱恐怖图腾。孩子，我们会崛起的。"
D.Strings[106204]="斯奇利普和费里斯卡被派进迷宫后就音讯全无了。快干活吧，否则审计员会把我们都派去迷宫的。"
D.Strings[106205]="你的脸怎么了？"
D.Strings[106206]="嘘。审计员们会听见的。"
D.Strings[106207]="别碰我的亮晶晶！"
D.Strings[106208]="你的样子很欠揍。"
D.Strings[106209]="你管这叫一大包？哈！小猫小狗都比你有力气。"
D.Strings[106210]="真无聊。快点把我们想知道的事情都交代了，否则就去死吧。"
D.Strings[106211]="我厌倦这种游戏了。不想死的话就快点说。"
D.Strings[106212]="他们有什么计划，恶魔？"
D.Strings[106213]="别想违抗我。快说。"
D.Strings[106214]="你会老实交代的，恶魔。"
D.Strings[106215]="你休想反抗燃烧军团！"
D.Strings[106216]="你不是我和我的猎犬们的对手！"
D.Strings[106217]="因为我比你更了解恶魔旅行。站好点。"
D.Strings[106218]="你打算怎么让我穿过传送门？"
D.Strings[106219]="变形？"
D.Strings[106220]="看来，这里就是那些地狱火小偷窃取那些小玩意儿的地方。$b$b好吧，在此逗留期间，我们也能弄些回去。我为你准备了一份行窃……或者说购物清单。你只要照章办事就行了。\n\n接下来，某个会戏法的幻术师就该把你变成他们的样子了。呸！幻象。一点保障都没有。\n\n我要做的，不是幻象，而是把你“变形”成这些家伙的样子。话说你的演技怎么样？"
D.Strings[106221]="干得好！我们得召集议会。只有跟他们合作，我们才能困住如此强大的野兽。"
D.Strings[106222]="快，制服愤怒战马，别让它跑了！"
D.Strings[106223]="你永远别想得到愤怒战马，凡人！"
D.Strings[106224]="我那些废物仆从虽然倒下了，但我是不会让你赢的。"
D.Strings[106225]="他们疯了吗？！他们会毁掉我们的！"
D.Strings[106226]="那些助祭在施展某种仪式法阵。总之，别给他们留下完成仪式的人手！"
D.Strings[106227]="阿拉萨斯用邪能护盾护住了他的助祭！你得先驱散它才能消灭他们！"
D.Strings[106228]="助祭们！让火雨降到这只爬虫的头上！"
D.Strings[106229]="小心，术士！这些地狱猎犬的牙齿对凡人是有毒的。但它们对你的恶魔没用！"
D.Strings[106230]="我的猎犬会撕碎你的血肉！"
D.Strings[106231]="什么？！你竟敢试图召唤我的战马？"
D.Strings[106232]="道路开启了，术士！快激活召唤石！"
D.Strings[106233]="这是什么？一个凡人妄图窥探我的国度？！"
D.Strings[106234]="啊，很高兴再次见到你，$n。"
D.Strings[106235]="现在，让我们穿越扭曲虚空，去拿回属于我们的东西吧！"
D.Strings[106236]="赫尔努拉斯不会放过你的，$c……"
D.Strings[106237]="我要拿你去喂恐惧战马！"
D.Strings[106238]="等等……我干了什么！？祖瑞瓦会砍了我的脑袋的！离我远点！"
D.Strings[106239]="去找祖瑞瓦……她在塔楼上……看着呢。"
D.Strings[106240]="你想问……我们的首领？当然……我什么都告诉你……"
D.Strings[106241]="……我说了什么？去死吧，术士！"
D.Strings[106242]="……不……我不会……背叛军团的！"
D.Strings[106243]="……够了！我要杀了你，恶魔！"
D.Strings[106244]="你说首领……？你随时都能对我发号施令……"
D.Strings[106245]="什么？我对你来说还不算首领吗？"
D.Strings[106246]="我们的首领……？我不知道……"
D.Strings[106247]="呃……如果你这么说的话……"
D.Strings[106248]="噢天呐……多么可爱的……蹄子……"
D.Strings[106249]="噢……很好……等等，你想干什么……？"
D.Strings[106250]="有了你收集来的材料，我们距离夺取愤怒战马的又近了一步。\n\n在我们建造传送门时，你可以集中精力去寻找一个吸引阿拉萨斯和愤怒战马的诱饵。"
D.Strings[106251]="为了引出阿拉萨斯，我们需要制造一座能够持续连通克索诺斯的传送门。这比我们平时建造的传送门要难得多，需要源源不断的资源供应。"
D.Strings[106252]="现在，我们得做准备了。"
D.Strings[106253]="很好。我就知道你不会让我失望。"
D.Strings[106254]="愤怒战马必将属于我！"
D.Strings[106255]="虽然那个虫语者对战马本身所知不多，但赫尔努拉斯现在肯定已经制造出一匹战马了。他将这匹战马送给了他最强大的将军，邪能骑士阿拉萨斯。麻烦的是，阿拉萨斯很少离开克索诺斯，他更喜欢远程遥控部队。\n\n但是，我想我们或许能把他引出来。为此，我需要你的帮助。\n\n你愿意接受这个挑战吗？"
D.Strings[106256]="我就长话短说了。\n\n自从被燃烧平原的黑石兽人“免职”之后，我就一直在秘密研究克索诺斯的恐惧战马。在某次仪式中，我设法捕获了一头来自另一边的奇怪恶魔——一头被我们称为“虫语者”的恶魔。\n\n经过数周的拷问后，那个恶魔透露说，赫尔努拉斯一直在为克索诺斯的邪能骑士制造一种更强大的战马。\n\n他将其称为愤怒战马。"
D.Strings[106257]="你叫我来做什么？"
D.Strings[106258]="很高兴认识你，虚空领主。"
D.Strings[106259]="到恐痕裂隙来找我吧，我会详细解释的。"
D.Strings[106260]="我们首次进入克索诺斯的位面已经是很久之前的事了，但是一个全新的机会正在召唤我们回到那里。"
D.Strings[106261]="你好啊，术士。我来向你通报一项发现，相信你会很感兴趣的。"
D.Strings[106262]="好好欣赏恶魔眼中的恐惧吧。我们要打垮他们！"
D.Strings[106263]="那个恶魔罪该万死。现在，它将承受它那邪恶主子的怒火了。"
D.Strings[106264]="军团逃不了的。我们要赶尽杀绝！"
D.Strings[106265]="了不起的胜利。你的意志很坚定。"
D.Strings[106266]="享受消灭军团走狗的美妙滋味吧！"
D.Strings[106267]="这游戏很快就会结束。燃烧军团必败。"
D.Strings[106268]="每一次打击都能令军团离末日更近一步。"
D.Strings[106269]="你的力量增长真惊人。军团知道你的威名……而且害怕它。"
D.Strings[106270]="又来了一个军团的爪牙。消灭它！"
D.Strings[106271]="啊，对，军团渣滓的臭味。找到臭味的源头，消灭它！"
D.Strings[106272]="我感觉附近有目标。快攻击！"
D.Strings[106273]="来了个邪恶的敌人。做你该做的事！"
D.Strings[106274]="目标过来了。把它送回虚空！"
D.Strings[106275]="这个军团的密探低估了你。它的这个做法显然是错误的。"
D.Strings[106276]="军团又派出了一批爪牙。立刻消灭这个威胁。"
D.Strings[106277]="这里挤满了恶魔。目标过来了！"
D.Strings[106278]="又消灭了一个威胁。很好！"
D.Strings[106279]="这波入侵者正在我们面前节节败退。干得好！"
D.Strings[106280]="干得好！你的技巧比任何军团武器都厉害。"
D.Strings[106281]="了不起！那废物毫无机会。"
D.Strings[106282]="便宜那个恶魔了。下一个目标！"
D.Strings[106283]="警告已经发出！"
D.Strings[106284]="这就是入侵者的下场。"
D.Strings[106285]="打得好，勇士。保持警惕。"
D.Strings[106286]="附近有潜在的威胁。去找到它，然后干掉！"
D.Strings[106287]="恶魔增长得比老鼠还快。杀了这家伙，别让它召唤出更多同类！"
D.Strings[106288]="前方……有新目标。把它送回扭曲虚空吧！"
D.Strings[106289]="斥候报告说，此地存在严重威胁。消灭它！"
D.Strings[106290]="我们还忙着呢。快点干掉这家伙。"
D.Strings[106291]="该向军团发出警告了。把这家伙切碎了送回去！"
D.Strings[106292]="附近有威胁。去消灭目标。"
D.Strings[106293]="有个威胁需要你去解决。快点。"
D.Strings[106294]="想找指挥官吗？先面对我吧，懦夫们！"
D.Strings[106295]="深渊领主。呸！一堆傲慢的肉块。那些死亡恶魔的精华或许还有用处。"
D.Strings[106296]="屠魔者，前线需要你。抽出那些从墓穴中涌出的恶魔精华，用这些强大的灵魂撕碎那个邪能领主！"
D.Strings[106297]="此地容不下这么庞大的军团战争机器。他们在派出新机甲前得三思而行！"
D.Strings[106298]="我们要一起保卫家园不受军团的侵扰。"
D.Strings[106299]="小心，伙计们，克伦克会打飞你们的！"
D.Strings[106300]="我和德宾回营地了，你可以去那儿找我们。"
D.Strings[106301]="你休想打断我们的工作。这是军团的地盘！"
D.Strings[106302]="这片土地休想恢复……"
D.Strings[106303]="你们圣骑士的行动太好猜了。来吧，让我们看看你那把剑到底有什么力量……"
D.Strings[106304]="药膏生效了？呃……这是当然的嘛。干得好，勇士。"
D.Strings[106305]="我们派往那里的斥候都成了蜥蜴凝视下的受害者！用这瓶魔法药膏救出那些石化的斥候吧。"
D.Strings[106306]="我再也不靠近任何蜥蜴了！"
D.Strings[106307]="我像那样呆了多久了？"
D.Strings[106308]="别考验我的耐心！来吧，风暴！"
D.Strings[106309]="你的脑袋跟酒杯一样空空如也吗？"
D.Strings[106310]="这样就够了，谢谢。"
D.Strings[106311]="祝你尝遍天下美酒，朋友！"
D.Strings[106312]="你永远猜不到会有何等奇景在等着你！"
D.Strings[106313]="跟好友小酌两杯是最美妙的享受。"
D.Strings[106314]="好酒需要等待。"
D.Strings[106315]="烂泥怎么跑得这么快？"
D.Strings[106316]="好酒要用心酿造。"
D.Strings[106317]="回来！我要你的核心碎片！"
D.Strings[106318]="肮脏的烂泥！慢点儿！"
D.Strings[106319]="喝了吗？"
D.Strings[106320]="我刚学了一招，叫做“捅马蜂窝”！让我给你演示一下吧？"
D.Strings[106321]="你害的我没法控制思想了，小家伙。"
D.Strings[106322]="拜托，别来烦我。我在冥想呢。"
D.Strings[106323]="不打败军团，我们就不得安宁。"
D.Strings[106324]="邪恶无法在纯洁的心灵中扎根。"
D.Strings[106325]="我们为艾泽拉斯而战。"
D.Strings[106326]="我们是混沌海洋中的平衡力量。"
D.Strings[106327]="你是黑暗中的灯塔。"
D.Strings[106328]="疾风知劲草。"
D.Strings[106329]="|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆开始对你进行最后一次追踪！"
D.Strings[106330]="伊利丹大人，很高兴看到你来了……守望者们，让恶魔猎手在这儿玩蝙蝠吧，我们去干点实事。"
D.Strings[106331]="去解决恐怖指挥官阿加诺斯！别的交给我们。"
D.Strings[106332]="|TInterface\\Icons\\ACHIEVEMENT_BOSS_GENERALVEZAX_01.BLP:20|t一枚召唤符文召唤出了一个|cFFFF0000|Hspell:236461|h[梦魇之物]|h|r来追踪你！"
D.Strings[106333]="|TInterface\\Icons\\SPELL_MAGE_RUNEOFPOWER.BLP:20|t莱斯特向附近投放了一枚|cFFFF0000|Hspell:236460|h[召唤符文]|h|r！"
D.Strings[106334]="|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆又开始追踪你了！"
D.Strings[106335]="|TInterface\\Icons\\ABILITY_CREATURE_DISEASE_05.BLP:20|t一只来自异界的恶魔之手开始施放|cFFFF0000|Hspell:235578|h[异世之握]|h|r！"
D.Strings[106336]="|TInterface\\Icons\\INV_MISC_SHADOWEGG.BLP:20|t莱斯特|cFFFF0000|Hspell:235446|h[撕裂]|h|r了通往虚空的裂隙！"
D.Strings[106337]="|TInterface\\Icons\\ability_fixated_state_red:20|t卡兰姆开始追踪你！"
D.Strings[106338]="你不配沐浴阳光！"
D.Strings[106339]="我要有乐子啦！哈哈哈！"
D.Strings[106340]="现在去哪儿……"
D.Strings[106341]="好多易燃物，呵呵呵！"
D.Strings[106342]="我要失控了……这感觉真不错！"
D.Strings[106343]="我要生气了……"
D.Strings[106344]="我已经摩拳擦掌，准备行动了。"
D.Strings[106345]="为了联盟。"
D.Strings[106346]="坚强点。"
D.Strings[106347]="我一定会成功的，战争领主。"
D.Strings[106348]="你将倒在我愤怒的利爪下！"
D.Strings[106349]="我的怒火暂时……平息了……"
D.Strings[106350]="战争领主，我让你……失望了……"
D.Strings[106351]="我的爪子……钝了……"
D.Strings[106352]="你的死亡只会激起我的怒火！"
D.Strings[106353]="我的爪子淌着你的鲜血！"
D.Strings[106354]="我要用你的皮磨爪子！"
D.Strings[106355]="我要毁灭你！"
D.Strings[106356]="我们要一起消灭敌人！"
D.Strings[106357]="我们誓死保卫艾泽拉斯！"
D.Strings[106358]="你好，战争领主。我准备好战斗了！"
D.Strings[106359]="不要惹火我！"
D.Strings[106360]="我的战斧更加饥渴了。"
D.Strings[106361]="愿你的武器永远锋利。"
D.Strings[106362]="你不会失望的，战争领主$n。"
D.Strings[106363]="畏惧我的怒火吧！"
D.Strings[106364]="我将再次高举战斧……"
D.Strings[106365]="我很虚弱……"
D.Strings[106366]="我的怒火……熄灭了……"
D.Strings[106367]="你真的需要我帮忙吗？"
D.Strings[106368]="我的怒火无穷无尽！"
D.Strings[106369]="胜利的喜悦！"
D.Strings[106370]="我的战斧在渴望鲜血！"
D.Strings[106371]="我们得摧毁这个邪恶。"
D.Strings[106372]="我们的怒火将拯救艾泽拉斯！"
D.Strings[106373]="你好，我会与你并肩战斗的。"
D.Strings[106374]="别再胡闹了！"
D.Strings[106375]="你就这么喜欢看我难受吗？"
D.Strings[106376]="我会尽力的，大法师。"
D.Strings[106377]="Anar'alah belore，燃烧吧！"
D.Strings[106378]="我……还不够强大……"
D.Strings[106379]="我需要……休息。"
D.Strings[106380]="我得……休息一下……"
D.Strings[106381]="滚回黑暗无光的国度吧！"
D.Strings[106382]="该点火了！"
D.Strings[106383]="又消灭了一个目标！"
D.Strings[106384]="我们要烧尽这黑暗！"
D.Strings[106385]="我们会帮助提瑞斯秘法会的！"
D.Strings[106386]="Bal'a dash，大法师。我们将并肩战斗！"
D.Strings[106387]="或许……我就不是……这块料……"
D.Strings[106388]="真的，住手！否则我要拿你练回旋踢了！"
D.Strings[106389]="好了，好了……已经够了！"
D.Strings[106390]="哈哈哈！住手！好痒！"
D.Strings[106391]="我能跟你一起去吗？"
D.Strings[106392]="咱们有空喝一杯！"
D.Strings[106393]="你好啊，英雄！"
D.Strings[106394]="想尝尝我的特酿美酒吗？"
D.Strings[106395]="哇！我会努力的，大宗师！"
D.Strings[106396]="让开，否则就死！哇……啊啊！"
D.Strings[106397]="抱歉让你失望了，大宗师……"
D.Strings[106398]="我回头得多喝几杯……"
D.Strings[106399]="哎哟！我真该留在酿造厂……"
D.Strings[106400]="嘿，我最擅长这个了！"
D.Strings[106401]="我居然把真气浪费在你身上！"
D.Strings[106402]="噢，很好！我正缺少实战练习呢！"
D.Strings[106403]="我要打飞你！"
D.Strings[106404]="你肯定没见识过这样的回旋踢！"
D.Strings[106405]="你休想穿透我的迷雾！"
D.Strings[106406]="你肯定不懂得欣赏好酒！"
D.Strings[106407]="我保证不让你倒下，大宗师！"
D.Strings[106408]="大宗师，我会掩护你的！"
D.Strings[106409]="让我们卷起袖子，大干一场吧！"
D.Strings[106410]="我想我可以……帮你一把。"
D.Strings[106411]="我不接受……这个结果……"
D.Strings[106412]="你得……独自前进了……"
D.Strings[106413]="库斯卡总能达到目的。"
D.Strings[106414]="去喂鱼吧！"
D.Strings[106415]="你真该去学游泳。"
D.Strings[106416]="恐惧库斯卡的力量吧！"
D.Strings[106417]="这次我们能来点好玩的吗？"
D.Strings[106418]="屠魔者。我想我有空帮你。"
D.Strings[106419]="我主沉浮！"
D.Strings[106420]="我要淹死你！"
D.Strings[106421]="这要不了多久。"
D.Strings[106422]="你的死亡会取悦伊利丹大人！"
D.Strings[106423]="我受够你的胡闹了！有胆子的话就来找我吧！"
D.Strings[106424]="燃烧军团将征服一切！你们可悲的圣殿将灰飞烟灭。"
D.Strings[106425]="……如果我还能吃小菜的话。"
D.Strings[106426]="至于没吓死的，我很乐意用斧子劈碎它们。总之，小菜一碟！"
D.Strings[106427]="等恶魔看到这些龙，它们恐怕会吓死！"
D.Strings[106428]="别误会……天启四骑士是最强的。但亡灵巨龙……"
D.Strings[106429]="多米尔和她的子嗣归我们了，局势要变了！"
D.Strings[106430]="辉煌的胜利，勇士们！有关你们的颂歌必将在英灵殿里久久流传。"
D.Strings[106431]="你干掉了指挥官。很好！维瑟尔的幼龙会护送你离开。我要亲手给这艘邪恶战舰最后一击！"
D.Strings[106432]="我们得从空中打击燃烧军团！幼龙会把你送上恶魔的空中堡垒，你可以从那里摧毁他们的地狱火战舰。"
D.Strings[106433]="英雄们，回来吧。维瑟尔的子嗣来帮忙对付入侵者了。飞上天空，夺取胜利吧！"
D.Strings[106434]="维瑟尔的子嗣……又被抓走了。去救出它们，它们就能帮我们反击了。"
D.Strings[106435]="等着吧。这场战斗会很壮观的！"
D.Strings[106436]="今天，燃烧军团必败！为了艾泽拉斯！"
D.Strings[106437]="我们必须占领岛屿西侧的废墟。在那里，我们就能将所有部队送往灵魂引擎了！"
D.Strings[106438]="我需要你在我指挥其他战线时带领我的部队和团队。"
D.Strings[106439]="在莫可名状的力量中燃烧吧！"
D.Strings[106440]="你们将从这世界消失！"
D.Strings[106441]="一个损坏的魔能机甲核心足以制造出一大群畸体！找到那些核心碎片，别让军团拿回他们的造物！"
D.Strings[106442]="干得好！燃烧军团留下的伤痕迟早会消失的。"
D.Strings[106443]="军团会腐蚀一切！摧毁他们的邪能腐化器，别让风暴峡湾受到污染！"
D.Strings[106444]="我准备好开始试炼了，奥丁。"
D.Strings[106445]="我准备好返回苍穹要塞了。"
D.Strings[106446]="你带来了什么？"
D.Strings[106447]="很荣幸能来此为你效劳，战争领主。祝愿你顺利通过试炼。"
D.Strings[106448]="我能送你回苍穹要塞。你做好离开的准备后就说一声吧，战争领主。"
D.Strings[106449]="我准备好出发了。请召唤传送门吧。"
D.Strings[106450]="这力量归你了，$n。结束这一切吧。"
D.Strings[106451]="联结断开了。得尽快行动，$n。我们法隆戴尔见。决战即将打响。"
D.Strings[106452]="蠢货！看看远方的天空吧，你们的世界即将走向末日！"
D.Strings[106453]="我……我不敢相信自己居然输了。或许我没有资格得到晋升。"
D.Strings[106454]="等我打败了你，就离晋升又近了一步了。"
D.Strings[106455]="为勇士的胜利欢呼吧！战争领主万岁！"
D.Strings[106456]="哈哈哈……战争领主战胜了所有挑战者！试炼完成了！"
D.Strings[106457]="这真是百年难遇的精彩战斗！阿斯丽娅如此强势，许多观众都以为她战无不胜了。看来她的傲慢毁了她！"
D.Strings[106458]="法师塔发出爆裂声，时间静止了！"
D.Strings[106459]="复活我们的战士，让他们继续战斗总比变成邪能燃料强。"
D.Strings[106460]="我得找到艾德里斯。我去侦察堡垒，能进攻了再通知你。再见，$n。"
D.Strings[106461]="恶魔在用我们的伤员当诱饵！我们得让所有士兵回到前线。去那里帮助他们……小心那些阴影。"
D.Strings[106462]="享受这短暂的胜利吧。我已经看透了你们的战术，摸清了你们的弱点。现在，我要去黑鸦堡垒复活我的大军了！"
D.Strings[106463]="了不起。只要选对了工具，最强大的魔法也能解除。"
D.Strings[106464]="狩猎大师，发射照明弹吧。暗影兽为燃烧军团控制了关键地带。找出这些野兽，让我们的弓箭消灭它们。"
D.Strings[106465]="好……来吧……抗击“军团”！"
D.Strings[106466]="士兵们，过来！我需要力量！"
D.Strings[106467]="召唤部队吧，“大人”。我会让他们更强大的！"
D.Strings[106468]="我投降，战争领主。你已经证明了自己，毫无疑问，你是个出众的战士。"
D.Strings[106469]="艾德里斯还告诉了我们该去找谁！他们应该就在农场附近。我们走！"
D.Strings[106470]="等等！住手，我……我坚持不住了。你显然比我更强壮。"
D.Strings[106471]="迪莎，诺索斯，泰索斯！列队！给我干掉那些入侵者！"
D.Strings[106472]="我准备好参加最后的总攻了。[加入场景战役队列]"
D.Strings[106473]="我来开启传送门。"
D.Strings[106474]="让我们一起碾碎燃烧军团吧，大法师$n！"
D.Strings[106475]="我的剑已经很久没有畅饮鲜血了。不知道它会不会喜欢你的血……"
D.Strings[106476]="她的剑已经在这里放倒了许多战士。战争领主能获胜吗？"
D.Strings[106477]="我绝不向你这种人投降，庶民！"
D.Strings[106478]="你这蠢货，$r。如果死亡才能让你接受教训，那就这样吧。"
D.Strings[106479]="我参加过这个试炼上千次了。每一次，我都能让奥丁看到，他的战士不配与我同场竞技。"
D.Strings[106480]="你在摆弄你根本不理解的力量，凡人！你的桀骜不驯只会让你丧命！"
D.Strings[106481]="臣服于军团的力量吧！你们的努力毫无意义，凡人！"
D.Strings[106482]="恶魔的力量衰退了，但是我们没时间自鸣得意。我在神殿外面等你。我们该主动出击了。"
D.Strings[106483]="恐吓是军团的利器。但智商可不是。"
D.Strings[106484]="军团想用一个不稳定的仪式修复魔能机甲。去干扰那个仪式，用他们的力量对付他们自己。"
D.Strings[106485]="那些水晶被摧毁以后，里面的邪能也消散了。看来它们的威胁解除了。"
D.Strings[106486]="邪脉精灵从军团那里获得了邪恶的能量水晶。快把那些玩意儿抢过来毁掉。不用顾忌那些精灵的性命。"
D.Strings[106487]="军团正在向阿苏纳推进！我们得削减恶魔数量，让他们的弱点暴露出来！"
D.Strings[106488]="我很荣幸能在此受到奥丁的欢迎。我会证明，他选择我的力量是明智之举。"
D.Strings[106489]="就算你倒下了，也不用感到羞愧。我的防御是无懈可击的。"
D.Strings[106490]="我很乐意碾碎你。"
D.Strings[106491]="你是来提拔我的吗，兄弟？"
D.Strings[106492]="我的盾牌能挡住千军万马。我才不信区区一个$r就能刺穿它。"
D.Strings[106493]="我们差点就撑不下去了。非常感谢！"
D.Strings[106494]="我们差点就撑不下去了。非常感谢，$c。"
D.Strings[106495]="这酒的泡沫特别丰富。我正需要提神呢。"
D.Strings[106496]="啊！新鲜的、清凉的美酒！"
D.Strings[106497]="恶魔要为他们的罪行付出千百倍的代价。保持攻势！"
D.Strings[106498]="这是对军团的一次沉重打击！"
D.Strings[106499]="每次胜利都能让我们前进一大步并壮大我们的部队。谢谢你，勇士。"
D.Strings[106500]="巡逻队在本地发现了一个强敌。它的死能大大削弱军团在本地的力量。"
D.Strings[106501]="军团正在向一个强大的敌人靠拢。我们得防止他们集结起更多的兵力！"
D.Strings[106502]="军团在本地的力量很强。准备好，勇士。圣光必胜！"
D.Strings[106503]="无论军团出现在哪里，我们都要碾碎他们，直到彻底将他们赶回去为止。"
D.Strings[106504]="我们每打倒一个敌人，就会再来一个。保持警惕。"
D.Strings[106505]="他们是自寻死路！"
D.Strings[106506]="这群乌合之众竟敢再次踏足艾泽拉斯。就用他们对待其他世界的方法来对待他们吧。消灭他们。"
D.Strings[106507]="又一只军团的蝼蚁从石头底下窜出来了。让它看看我军的实力吧！"
D.Strings[106508]="我感觉附近有个强敌。全力出击，将它赶出我们的世界！"
D.Strings[106509]="虽然与议会成员相处愉快，但我并不想重新加入议会。"
D.Strings[106510]="这是抗魔联军的又一次胜利。我们决不能浪费这个优势！"
D.Strings[106511]="谢谢你，勇士。你让我们在无尽的攻势中暂时喘了口气。"
D.Strings[106512]="打得好，就像个真正的大法师！唔，这么说似乎不够响亮……"
D.Strings[106513]="这个敌人对我军造成了严重威胁。击败他可以争取到更多的准备时间！"
D.Strings[106514]="我要把你像个破布娃娃一样扔出去，$r！"
D.Strings[106515]="附近有个强大的军团密探。他们太危险了，不能坐视不理，你必须将其击败！"
D.Strings[106516]="报告说，这里有个特别强大的恶魔。我们得尽快消灭它！"
D.Strings[106517]="他还活着吗？"
D.Strings[106518]="哦，你想让我扮演怪兽吗？"
D.Strings[106519]="别磨蹭。"
D.Strings[106520]="战士们，欢迎参加怒火试炼！"
D.Strings[106521]="我生活在暗影中。"
D.Strings[106522]="我的剑已经蓄势待发了。"
D.Strings[106523]="虚空领主！你成功了！坎雷萨德回来了。"
D.Strings[106524]="要我帮你挖座坟吗？"
D.Strings[106525]="俗话说，红颜祸水啊。"
D.Strings[106526]="亡灵不死。"
D.Strings[106527]="我的战斧饥渴难耐了！"
D.Strings[106528]="亡灵欢迎你。"
D.Strings[106529]="我打倒过无数勇士和酋长！你只是个渺小的废物！"
D.Strings[106530]="干得好！我们的部队会乘胜追击的。"
D.Strings[106531]="有支巡逻队被困在了这群疯马后方！我们得送些酒去激励他们。可怎么办呢……"
D.Strings[106532]="你全部的力量都比不上我的一根手指！"
D.Strings[106533]="别来烦我，小鬼。"
D.Strings[106534]="恐怖图腾必将再次崛起。"
D.Strings[106535]="跟紧你的朋友……"
D.Strings[106536]="走吧，小鬼。"
D.Strings[106537]="你想让老玛加萨做什么？"
D.Strings[106538]="我没功夫陪你犯傻。"
D.Strings[106539]="别让他们吸走他的力量！"
D.Strings[106540]="你休想干扰仪式！"
D.Strings[106541]="坎雷萨德的力量属于燃烧军团！"
D.Strings[106542]="我伤得很重，但我以前还受过比这更重的伤。我很快就会向燃烧军团复仇的！"
D.Strings[106543]="你想被割破喉咙吗？那正合我的口味。"
D.Strings[106544]="你能住手吗？"
D.Strings[106545]="注意天空！"
D.Strings[106546]="愿风托起你的双翼。"
D.Strings[106547]="我们应该互帮互助。"
D.Strings[106548]="有危险吗？我来解决！"
D.Strings[106549]="我准备好了！把我送到勇者之门去。[加入场景队列]"
D.Strings[106550]="你准备好响应荣耀的召唤了吗，$c？"
D.Strings[106551]="在援军抵达前，我们不能继续前进了。全体后退！"
D.Strings[106552]="按她说的做，大家都出去！"
D.Strings[106553]="%s绝望地瘫倒在地面上。"
D.Strings[106554]="%s的双眼失神，她的猎枪落在了地上。"
D.Strings[106555]="白发人送黑发人，真是悲剧……"
D.Strings[106556]="加洛德！他……走了。我们得撤退，等待援军到来！"
D.Strings[106557]="我得……坐一会儿……"
D.Strings[106558]="我……坚持不住了……"
D.Strings[106559]="但愿你准备好了，战争领主。如果你有需要，我带了一些补给。"
D.Strings[106560]="你做好战斗的准备后，就向强壮的丹鲁尔发起挑战吧。只要站到符文上，战斗就会开始。"
D.Strings[106561]="谢谢你，战士。"
D.Strings[106562]="我现在明白萨满的话是什么意思了。我已经学会了谦卑，也将因此而变得更加强大。"
D.Strings[106563]="我期待着和你的比赛，战士。如果你能撑到那一关的话。"
D.Strings[106564]="你看起来意志很坚定，但我的意志更强大。我的精神同样如此。"
D.Strings[106565]="我跟我的部族的萨满交谈时，他预见到了我今天的胜利。或许你应该直接认输，战士。"
D.Strings[106566]="我误判了你的实力，伙计。我一直以为体格能决定胜负，或许我错了。"
D.Strings[106567]="如果你想离开也没关系。我的大部分对手一看我的体格就认输了。"
D.Strings[106568]="我想请你跟我一起练来着，但这些哑铃都快跟你一样大了。你还是回去练练肌肉再来吧。"
D.Strings[106569]="你的体格跟你的力量很相称，小崽子。"
D.Strings[106570]="我很好奇，等你输了之后，谁还会记住你的名字……"
D.Strings[106571]="你这种人根本不应该来这儿。这片土地是属于我们的，只有我们才有资格参加这个试炼！"
D.Strings[106572]="等你倒下后，他羞愧的样子一定很搞笑。"
D.Strings[106573]="奥丁是个傻瓜，居然选你做他的勇士。"
D.Strings[106574]="我们不能让燃烧军团成功。"
D.Strings[106575]="你休想干扰我们的计划。坎雷萨德的力量将属于燃烧军团！臣服于我们的力量吧！"
D.Strings[106576]="圣光必胜！"
D.Strings[106577]="兄弟会将带头冲锋！"
D.Strings[106578]="见证圣光的力量吧！"
D.Strings[106579]="啊，我不在的时候，你可别把敌人都杀光了。"
D.Strings[106580]="我得撤退了。"
D.Strings[106581]="让我们一路同行。"
D.Strings[106582]="我在你身边。"
D.Strings[106583]="倒在圣光之下吧！"
D.Strings[106584]="为了兄弟会！"
D.Strings[106585]="恐惧我的利刃吧！"
D.Strings[106586]="让我们净化这片大地的黑暗吧。"
D.Strings[106587]="兄弟会团结一致！"
D.Strings[106588]="让瘟疫吞噬你！"
D.Strings[106589]="莱斯特虽然逃跑了，但我们会找到他的。到时候，希望你能再来帮忙。"
D.Strings[106590]="你的选择很明智。我们会功成名就的。"
D.Strings[106591]="我们绝不能动摇，无论那个恶魔干了什么。"
D.Strings[106592]="我……控制不了自己……"
D.Strings[106593]="我的头……离……离那东西远点儿！"
D.Strings[106594]="振作起来，罗兰。援军到了。"
D.Strings[106595]="唔，美味……就像黑暗中的匕首！最后一个目标在暴风城。这也将是最有难度的目标！"
D.Strings[106596]="他就在墙边。听说他是个懦夫，全靠护甲来保命。让他明白自己错得有多离谱吧！"
D.Strings[106597]="垂死的尖叫……真美妙！下一个目标在铁炉堡，藏身在矮人议会的阴影里。"
D.Strings[106598]="目标正在战士区附近开花园派对。小心！她的朋友是强大的施法者，她也是。小心那些卫兵。"
D.Strings[106599]="啊，干脆利落……很好！下一个目标在达纳苏斯。我建议你从泰达希尔下面的村子进去。"
D.Strings[106600]="你的第一个目标伪装成了游览城市的谦卑牧师。小心他的水晶魔像！尽量分开他们……别搞出太大的动静。"
D.Strings[106601]="记住……哪怕你是想帮忙，联盟也会觉得你是在攻击自己人。"
D.Strings[106602]="我们不能冒险让你去盟友的城市搞暗杀。但在埃索达，你清除目标的能力毋庸置疑。等你解决了目标，我就去银月城。"
D.Strings[106603]="可怜虫！无论藏在何处，暗影都能找到他们。来吧，去见见你的同僚。拉文霍德爵士为你准备了礼物。"
D.Strings[106604]="在那儿！最拥挤的地方——拍卖行。记住：安静、精准，然后迅速逃离！"
D.Strings[106605]="唔，美味……就像黑暗中的匕首！最后一个目标在奥格瑞玛。这也将是最有难度的目标！"
D.Strings[106606]="他就在篝火旁。听说他是个懦夫，全靠护甲来保命。让他明白自己错得有多离谱吧！"
D.Strings[106607]="垂死的尖叫……真美妙！下一个目标在雷霆崖，藏身在牛头人领袖的阴影里。"
D.Strings[106608]="目标正在盗贼区上方的露台上喝茶。小心！她的朋友是强大的施法者，她也是。你得想办法上去。"
D.Strings[106609]="啊，干脆利落……很好！下一个目标在幽暗城。我建议你从西边的下水道进去。"
D.Strings[106610]="你的第一个目标伪装成了游览城市的富裕贵族。小心他的奥术魔像！尽量分开他们……别搞出太大的动静。"
D.Strings[106611]="记住……哪怕你是想帮忙，部落也会觉得你是在攻击自己人。"
D.Strings[106612]="我们不能冒险让你去盟友的城市搞暗杀。但在银月城，你清除目标的能力毋庸置疑。等你解决了目标，我就去埃索达。"
D.Strings[106613]="我们的密探锁定了银月城和埃索达的疑似人偶。"
D.Strings[106614]="恶魔知道只要他们一入城，就会被伊利达雷发现，所以派出了这些……人偶。"
D.Strings[106615]="看来军团的恐惧魔王制造出了极为逼真的亡灵傀儡，连我都很难发现他们！"
D.Strings[106616]="他言语清晰，皮肤……也保养得很好。但某些迹象出卖了他。"
D.Strings[106617]="这不对，不应该是这个颜色。"
D.Strings[106618]="你看，我在这里割一刀……"
D.Strings[106619]="我自以为是个老猎人，却也差点被骗过了。"
D.Strings[106620]="暗影之刃！这边！"
D.Strings[106621]="走吧，罗兰。在你生病前，我们离开这鬼地方。"
D.Strings[106622]="这世界已经够黑暗了，不需要更多的暗影。谢谢你，勇士。"
D.Strings[106623]="艾瑞达咒术师正在召唤黑暗的虚空之力。快阻止他们！"
D.Strings[106624]="这地方像不像你家？"
D.Strings[106625]="你没地方可去了吗，罗兰？"
D.Strings[106626]="你非要跟这么紧吗，罗兰？"
D.Strings[106627]="接受我的庇护吧，英雄们！"
D.Strings[106628]="我们来开启传送门，但坚持不了多久。你得想办法阻止莱斯特！"
D.Strings[106629]="卡兰姆坚持要先行一步，可我担心他无法独自面对挑战。"
D.Strings[106630]="我们掌握的信息很少，但他似乎找到了利用扭曲虚空的能量强化自身通灵魔法的办法。"
D.Strings[106631]="勇士！我们的法师锁定了莱斯特·法师之矛在扭曲虚空中的位置！"
D.Strings[106632]="打倒那个怪物！谁都别想过去！"
D.Strings[106633]="别处正需要我。好好享受这……临别礼物吧！"
D.Strings[106634]="我欠你一条命，牧师。"
D.Strings[106635]="我不会忘记你的仁慈的。"
D.Strings[106636]="迷雾终于散开了……"
D.Strings[106637]="痛苦减轻了。谢谢你，$n。"
D.Strings[106638]="把阿格拉玛之盾放进去。等你们的信号，英雄们！"
D.Strings[106639]="拿起武器！恶魔来了！"
D.Strings[106640]="枪手，攻击这个凡人渣滓！用地狱之火消灭他们！"
D.Strings[106641]="我们准备好了。"
D.Strings[106642]="做好准备！军团会不惜一切来抢圣盾的。"
D.Strings[106643]="看来你控制了她们的人口增长。很好！我们可不想让这些怪物冲出这片海滩。"
D.Strings[106644]="鹰身人已经够讨厌了，而效忠军团的鹰身人？不可容忍！控制住这个新威胁吧，勇士。"
D.Strings[106645]="太迟了，凡人！我的指挥舰到了！"
D.Strings[106646]="前面有危险，旅行者。某种恶疾笼罩了这片区域。"
D.Strings[106647]="呃，真不幸。你这样的高手肯定能复活他的吧？"
D.Strings[106648]="别吵了！我们得救这条船！"
D.Strings[106649]="别说风凉话了，亲爱的赛丝诺。他们抢先破坏了我们的武器。等你帮忙杀掉这些家伙之后，我们再考虑修理！"
D.Strings[106650]="他们怎么能靠这么近，玛沃伦斯？邪能之槌号怎么不朝他们开火？"
D.Strings[106651]="邪能之槌号摧毁了一艘燃烧军团的飞船，还把其他飞船吓得纷纷逃窜，那场面真是太壮观了！"
D.Strings[106652]="你说得对，赛丝诺。不冒险的话，大家都得死。屠魔者$n，我们去主控制台！"
D.Strings[106653]="谢谢你，大领主。我的先祖得到了安息。"
D.Strings[106654]="大领主，你得用手里的武器解放这些邪缚之魂。摧毁他们的吊坠，帮我的祖先摆脱这古老的诅咒。"
D.Strings[106655]="干得好，勇士。愿他们的灵魂安息。"
D.Strings[106656]="这些废墟里的幽灵由于某个古老的契约而受到军团的束缚。去让他们安息吧。"
D.Strings[106657]="真壮观！在魔力消逝前，好好享受吧。"
D.Strings[106658]="据说，埋在这些废墟里的遗骸含有魔力。让我们验证一下这些传言吧！去找到那些古老的骨头，把它们放在毁坏的祭坛上。"
D.Strings[106659]="该死，我要成立自己的法师团……炉石……还有魅魔！唔，再想想还是算了吧！"
D.Strings[106660]="但愿你不介意我抄个近道。"
D.Strings[106661]="我得额外收费……"
D.Strings[106662]="噢！别打了！打那个英雄吧！"
D.Strings[106663]="我会把修理费账单……寄给你的。"
D.Strings[106664]="这就是不给小费的下场！"
D.Strings[106665]="我真应该按尸体收费。"
D.Strings[106666]="对，我知道自己很棒。"
D.Strings[106667]="我最好先投个人身保险……"
D.Strings[106668]="噢，看我变个戏法，伙计！"
D.Strings[106669]="准备接受毛茸茸的可爱死亡吧！"
D.Strings[106670]="该死的！我们走！"
D.Strings[106671]="选张牌吧，随便选！"
D.Strings[106672]="我想我们今天收集的遗物够多的了。歇歇吧，好好享受你的战利品！"
D.Strings[106673]="我还有一张王牌呢！"
D.Strings[106674]="如此古老而且丰富的废墟足以令任何收藏家欣喜若狂。去多找些遗物来，但要小心那些滞留尘世的幽灵！"
D.Strings[106675]="伟大的阿卡扎曼扎拉克要开演啦！"
D.Strings[106676]="只要你付得起钱，我这儿有的是法术！"
D.Strings[106677]="好了，给这些傻瓜一点颜色瞧瞧吧。"
D.Strings[106678]="休息吧，英雄。这是你应得的。"
D.Strings[106679]="勇士！你得挡住军团的大军。到前线去找我们的盟友，坚守阵地吧！"
D.Strings[106680]="军团耍了我们！他们的攻击只是障眼法，是为了在盾憩岛上建立据点！"
D.Strings[106681]="燃烧军团竟敢袭击风暴峡湾！勇士，把他们赶出这片土地，荣耀就将属于你！"
D.Strings[106682]="很好，但你还能复制这次胜利吗？"
D.Strings[106683]="好战术。"
D.Strings[106684]="别放弃。"
D.Strings[106685]="再加把劲儿。"
D.Strings[106686]="看来你确实准备好了。"
D.Strings[106687]="多亏你的帮助，我们研究出了可靠的解药。"
D.Strings[106688]="我们的部队被一只蜘蛛抓去喂她的邪恶子嗣了！干掉这些蜘蛛，收集它们的毒囊，帮助我们研究解药。"
D.Strings[106689]="我们的部队安全返回营地了，最重要的是所有人的毒都解了！干得好！"
D.Strings[106690]="一只蜘蛛把我们的部队抓去喂她的致命子嗣了。大宗师，我们得靠你杀掉那只恶魔，并用清创生血为俘虏解毒！"
D.Strings[106691]="之前，我每时每刻都在衰弱！谢谢你。"
D.Strings[106692]="谢谢你，大宗师。"
D.Strings[106693]="你的行为唤醒了幽灵！"
D.Strings[106694]="我们尽力拖住了敌人。但恶魔还会进攻，早做准备吧。"
D.Strings[106695]="上吧，摧毁敌人在这片平原的据点，让他们无险可守！一个都别放过！"
D.Strings[106696]="军团撤退了！快跳船！角鹰兽会接住你们的！"
D.Strings[106697]="又来了？我得花上许多年才能把这身护甲穿回去了。哼。"
D.Strings[106698]="这是你要的材料，奥拉尔德。"
D.Strings[106699]="虽然耐心是种美德，但我们没法那么奢侈了。做好准备。"
D.Strings[106700]="你真的认为你的伙伴们已经准备好跟我们一起出击了吗？"
D.Strings[106701]="不好好训练就得死。在这里，没有第二种选择。"
D.Strings[106702]="我敢肯定，格雷森会对我们的收获感到满意的。代我向他问好。"
D.Strings[106703]="成了！要我自己说的话，这绝对是我最好的作品之一！现在，它归你了。"
D.Strings[106704]="最后但也是最重要的，宝石！"
D.Strings[106705]="现在，我要从这里锤打魔石……还有这里……"
D.Strings[106706]="首先，我要熔炼这块矿石……"
D.Strings[106707]="好的，我们来升级这套骑甲吧！"
D.Strings[106708]="我……还活着，但没法战斗了。快，勇士，快去阻止他！"
D.Strings[106709]="干得好。用那些大家伙的力量对付他们自己……真是个好主意！"
D.Strings[106710]="纳迦一直是个大威胁。我们制服了他们的一个蛮兵。去以纳迦的力量对付他们自己吧！"
D.Strings[106711]="我准备好返回了，格雷森。"
D.Strings[106712]="你准备好返回职业大厅后就说一声，大领主。我会把我们安全送回去的。"
D.Strings[106713]="你好了就说一声，我会把大家安全送回去的。"
D.Strings[106714]="我们圣光秘殿见。你可以在那里安全地给它套上骑甲。"
D.Strings[106715]="它被束缚住了，大领主！圣光眷顾了我们！"
D.Strings[106716]="那匹马！快，抓住它！"
D.Strings[106717]="我，雷曼会再次将瘟疫散布到这片土地上，所有人都将匍匐在我的脚下！"
D.Strings[106718]="你和你那群可悲的乌合之众都将加入我的亡灵大军！"
D.Strings[106719]="你在找什么东西吗？！哈哈哈！"
D.Strings[106720]="有人偷走了尸体！这可不妙……"
D.Strings[106721]="尸体呢？！它应该在这里的！"
D.Strings[106722]="让他们殿后，我们进去对付瑞文戴尔。"
D.Strings[106723]="圣骑士们，上马！出发！"
D.Strings[106724]="骑甲完成了！现在，该去瑞文戴尔的墓穴对付他的鬼魂了。"
D.Strings[106725]="我来给骑甲洒上圣水。剩下的，就看你和你的武器了。"
D.Strings[106726]="很好，你拿到了圣水，大领主。非常感谢你救了我的圣骑士。"
D.Strings[106727]="结束了？！真的吗？大领主，是你……我……我想我可以自己回去。谢谢你。"
D.Strings[106728]="我的灵魂似乎被慢慢抽出了身体。那个亡灵巫师，他……我得去找格雷森了。"
D.Strings[106729]="他们一拥而上。我……想要战斗，可是……谢谢你救了我，大领主。"
D.Strings[106730]="吃了他们，烂口！"
D.Strings[106731]="吸入佩斯图隆的浓烟，加入我的大军吧！"
D.Strings[106732]="奥塞尼会给你们个痛快的！"
D.Strings[106733]="你来迟了，圣骑士。你的战友已经没救了。他们的灵魂壮大了我的部队……"
D.Strings[106734]="这座城市属于亡者！很快，你也会一样！"
D.Strings[106735]=" 你的努力是徒劳的，圣骑士！死亡将再次笼罩这座城市……"
D.Strings[106736]="也许像你这样的高手更合适去找圣水。请带上我的圣骑士们。天知道这里还藏着什么东西。"
D.Strings[106737]="我派了三个好手去找圣水，但一个都没回来。我很担心他们。"
D.Strings[106738]="我们去对付指挥官坎托马斯吧（需要能量充沛的钥石）。"
D.Strings[106739]="我们去对付指挥官艾德里斯吧（使用加洛德的免费钥石）。"
D.Strings[106740]="一项严酷而危险的任务正等着我们，$n。这两个人也要和我们一起来，说要“确保我们能够正确地完成任务”。他们不该这样做的。"
D.Strings[106741]="你要……付出代价！你要……"
D.Strings[106742]="不……我的宝贝！"
D.Strings[106743]="你帮我们的部队抵挡了一次最讨厌的空袭。唔，或许伊利达雷会需要被你吓跑的那些幼崽……"
D.Strings[106744]="但，你得先为抢走我的宠物付出代价！"
D.Strings[106745]="此刻，我的萨亚德正在诱惑软弱的法师。你的盟友会自愿倒向军团！"
D.Strings[106746]="你太迟了！莱维娅的力量归我了！有了她的知识，我的人就能潜入肯瑞托，从内部瓦解它！"
D.Strings[106747]="魔蝠！我讨厌这些长翅膀的恶魔！它们不但会骚扰我们的部队，而且繁殖得像兔子一样快。我们得削减它们的数量！"
D.Strings[106748]="必须阻止那个鬼母！祝你好运，勇士。"
D.Strings[106749]="她身边有重兵把守，但肯瑞托的法师应该能开启通往她身边的传送门。"
D.Strings[106750]="现在，她恐怕已掌握了不少窃取自莱维娅的力量。要是真的，天知道她会做出什么来。"
D.Strings[106751]="勇士，很高兴能找到你。维多利亚应该告诉你了，我们找到了鬼母阿加莎。"
D.Strings[106752]="快！军团很快就会击溃我们。"
D.Strings[106753]="记得常来鲑鱼溪看看，这里还有很多鸟可以打呢！"
D.Strings[106754]="合作愉快！谢谢你救了我们的镇子。"
D.Strings[106755]="谢谢你，$n。我们破坏了军团分裂我们的阴谋。肯瑞托在等着我们胜利的消息呢。他们给我了一件东西，能帮你快速返回。"
D.Strings[106756]="愿你安息，指挥官。"
D.Strings[106757]="堡垒……失守了……"
D.Strings[106758]="灵魂的耐受力极为惊人，但逐渐被邪能吞噬的痛苦远远超出了凡人的想象。"
D.Strings[106759]="军团的战舰坠毁时，放出了制造它时剩余的灵魂。这些灵魂在哀嚎，迷失在无尽的痛苦中。请帮它们解脱吧！"
D.Strings[106760]="来吧，士兵们！接受我的恩赐，消灭军团！"
D.Strings[106761]="我不会再让你威胁生者了，艾德里斯！"
D.Strings[106762]="那我们出发吧。"
D.Strings[106763]="小心，勇士，有东西从传送门里出来了……很强大！"
D.Strings[106764]="见证邪能的力量吧！"
D.Strings[106765]="等大家休息好之后，我们就出发。"
D.Strings[106766]="小心，艾德里斯被军团蛊惑了，他看我们都是敌人。"
D.Strings[106767]="成功了！赞美艾露恩！时间恐怕不多了。"
D.Strings[106768]="多亏你的努力，俘虏们都逃出生天了。干得好。"
D.Strings[106769]="这附近关押着一些俘虏。请尽力救出他们，勇士！"
D.Strings[106770]="他们是自愿牺牲的，也得到了安息。你干得很好。"
D.Strings[106771]="邪能图腾的牛头人正在亵渎尸体。谁都不该遭此下场。去让他们安息吧，勇士。"
D.Strings[106772]="愚蠢的凡人！你们真的以为燃烧军团会这么容易就被击败吗？"
D.Strings[106773]="莱瑟拉可不喜欢别人管她的闲事！"
D.Strings[106774]="可怜虫！塞琳喜欢让外来者帮她做事？"
D.Strings[106775]="代我向茉德拉问好，$c。还有……谢谢。"
D.Strings[106776]="在……你身后……"
D.Strings[106777]="我又得帮你收拾烂摊子了，兄弟！"
D.Strings[106778]="废物！让开，看我是怎么做的，兄弟。"
D.Strings[106779]="有个潜行者混入了我们的城市！"
D.Strings[106780]="死神来抓我了！"
D.Strings[106781]="这里有燃烧军团的密探！"
D.Strings[106782]="你休想打倒我，恶棍！"
D.Strings[106783]="这里有刺客！"
D.Strings[106784]="平民，帮帮我！"
D.Strings[106785]="啊！完美的标本，死亡领主。给，这个或许对你有用。"
D.Strings[106786]="请原谅，大领主。我……我需要独自思考一下。"
D.Strings[106787]="有趣的巫术。黑暗魔法也有它的用处。"
D.Strings[106788]="你的巫妖自称有个计划，但需要被邪能杀死的人的骨头。如果你觉得有用，就帮帮他吧，但你得看好……那个……东西。"
D.Strings[106789]="让烈焰淹没你们！"
D.Strings[106790]="燃烧军团在入侵诸界时，总能找到将其扭曲的新方法。"
D.Strings[106791]="痛苦的亡者在响应恶魔主子的召唤。快打倒他们！"
D.Strings[106792]="你不会后悔的，大德鲁伊！我随时都能行动！"
D.Strings[106793]="卡萨纳提尔的牢笼在为达拉然的防御工事充能，虽然这只是暂时的，但看到那恶魔的精华没有逃脱，我还是很欣慰。来，我们回守护者圣殿。"
D.Strings[106794]="炸开它！"
D.Strings[106795]="啊啊啊！！我的头……"
D.Strings[106796]="门要关了——小心！"
D.Strings[106797]="里面的守军肯定更多。拉文凯斯领主已经不在了，艾德里斯肯定占据了他的房间。他总是自视过高。"
D.Strings[106798]="那……是……什么！？"
D.Strings[106799]="你给我记住了，$c！我们还会再见的！"
D.Strings[106800]="你破除了我的幻像！渣滓！"
D.Strings[106801]="干得好！摧毁魔能机甲能对军团造成沉重打击。"
D.Strings[106802]="如果再不解决这个魔能机甲，我担心盟友的生命可能遭到威胁。"
D.Strings[106803]="天呐，你很强嘛。打垮你一定会很有趣！"
D.Strings[106804]="不！你干了什么！我要让你痛不欲生！"
D.Strings[106805]="大法师，我很惊讶，你居然将恶魔卡萨纳提尔囚禁在夜之子灵魂石中，并设计出压制护盾，以便安全地驱使他的力量。这真是天才之作！"
D.Strings[106806]="那来吧，$c。逗我笑吧。"
D.Strings[106807]="虽然我对莱维娅感到很满意，但是拒绝这份礼物未免太粗鲁了。"
D.Strings[106808]="所以肯瑞托又给我送玩具来了？"
D.Strings[106809]="拉文凯斯领主会玩忽职守，可我不会。士兵们，进攻！"
D.Strings[106810]="我要跟他们拼个你死我活！我们动手吧，精灵。"
D.Strings[106811]="我不回去！我要阻止对镇子的攻击！"
D.Strings[106812]="你来的正是时候，我随时可能进攻。而在此之前，我还是要劝你们俩赶快回鲑鱼溪。你们没必要参战！"
D.Strings[106813]="法姆巴尔发现了莱维娅的踪迹！"
D.Strings[106814]="去找到莱维娅，法姆巴尔！"
D.Strings[106815]="法姆巴尔耐心地等待着追踪莱维娅踪迹的指令。"
D.Strings[106816]="我们会把这些鹤送去安全的地方。将来，等恶魔滚出破碎海滩，它们的雏鸟就能回家了。"
D.Strings[106817]="好……困。"
D.Strings[106818]="我不想再跟生者打交道了。"
D.Strings[106819]="够了！我要继续长眠了！"
D.Strings[106820]="锯齿海湾的鳄鱼在袭击咸水鹤的芦苇地。请帮忙找到那些可怜的小鸟，我把它们送去安全地带！"
D.Strings[106821]="可恶！恶魔入侵摧毁了破碎海滩的大量栖息地。野生动物都无家可归了！"
D.Strings[106822]="击杀小鬼仆从，别让他们为阿加莎补充能量！"
D.Strings[106823]="感谢帮忙！对于戈德林来说，这些恶魔不算什么，但恶魔太多，就难说了……"
D.Strings[106824]="戈德林需要帮助！为了作弊，有个恶魔带来了援军。我们要让他自食其果！"
D.Strings[106825]="很好。干得好，大德鲁伊！"
D.Strings[106826]="戈德林把猎物逼入了绝境，该我们出手了。你也能出脚、出爪……够尖就行！"
D.Strings[106827]="法姆巴尔的嗅觉很强。穿过传送门去找他吧，他会带你找到失踪的法师。"
D.Strings[106828]="保护我，孩子们！我会给你们力量的！"
D.Strings[106829]="裘碧卡，你在吗？别让他们控制我！我不想堕落！"
D.Strings[106830]="我受够这些把戏了！"
D.Strings[106831]="让我回到平台上。"
D.Strings[106832]="一艘军团战舰在远方实体化了。"
D.Strings[106833]="我们会好好利用这些补给的。干得好，勇士。"
D.Strings[106834]="勇士！我们找到了一艘部落飞艇的残骸。你得在军团发现它之前找回它的货物。"
D.Strings[106835]="你沉重打击了军团，$n。净化已经开始了。我等你回来。"
D.Strings[106836]="|TInterface\\Icons\\spell_fire_felrainoffire:20|t军团战舰开始施放|cFFFF0404|Hspell:235085|h[邪能轰炸]|h|r！小心！"
D.Strings[106837]="我一直在等待这一天，万恶勇者！现在，鞭子已经易手了！"
D.Strings[106838]="你知道吗，这根鞭子可不是摆设。说吧，打破我的契约，我就会让你看到它的神奇之处……"
D.Strings[106839]="你该等我摆脱契约的束缚后再来找我。噢，我一定会让你大开眼界的……"
D.Strings[106840]="所以你们凡人自以为能战胜军团？真稀奇。你们就像一群可爱的小老鼠，还不知道巨大的掠食者已经盯上了你们。"
D.Strings[106841]="呃，我恨这些船。太单调了，应该再加点锁链。"
D.Strings[106842]="如果你看见了万恶勇者就说一声。我和他之间……还有笔账要算。"
D.Strings[106843]="特德保证过，我们能把这地方烧成灰烬。"
D.Strings[106844]="作为一艘燃烧军团的战舰，这里可不太暖和。"
D.Strings[106845]="我很冷。我的外套是针对四处着火的地狱火世界设计的。"
D.Strings[106846]="如果这家伙掉了斗篷，那我想要。"
D.Strings[106847]="噢……已经放弃了？"
D.Strings[106848]="唔。我想我应该把安全词告诉他。"
D.Strings[106849]="噢，那家伙绝对是伪劣产品。"
D.Strings[106850]="看来这些恶魔根本经不起一鞭子啊……"
D.Strings[106851]="呃，这些恶魔的质量也大不如前了。"
D.Strings[106852]="它死了。真可惜。我还拿它有用呢。"
D.Strings[106853]="你想让我把活儿都干了吗？"
D.Strings[106854]="我的“主人”命令我来帮你，所以你尽量别死了。"
D.Strings[106855]="把我送到平台上。"
D.Strings[106856]="等等……有点不对劲！我……我控制不住了……"
D.Strings[106857]="符文激活了。稳定住传送门。"
D.Strings[106858]="你搞清楚这些符文了吗？我们没多少时间了！"
D.Strings[106859]="符文似乎生效了！邪能减弱了……"
D.Strings[106860]="好吧，我来稳定传送门。你要明白自己在做什么，$c！"
D.Strings[106861]="我能防止它关闭，但你得帮我稳住它……"
D.Strings[106862]="那边！裂隙正在消失，但传送门依然不够稳定，无法通过。"
D.Strings[106863]="把我带到黑鸦堡垒顶部。"
D.Strings[106864]="获救者的赞歌响彻了英灵殿。你干得非常好！"
D.Strings[106865]="军团的猎犬在吸食亡者的生命精华，他们的灵魂在哭泣。去解放那些灵魂，净化军团的渣滓吧！"
D.Strings[106866]="你好，大领主。格雷森大人就在里面等你。$b$b他正在监督骑甲净化仪式的准备工作。$b$b你准备好之后，我会护送你进去的。"
D.Strings[106867]="我们需要个送死的……呃……志愿者到传送门另一边去削减恶魔数量。去跟特德谈谈，他能给你点恶魔，帮你热热身。"
D.Strings[106868]="你得承认，邪脉精灵的魔法还是……有闪光点的。可惜他们滥用了它的潜力。他们罪有应得。"
D.Strings[106869]="对！对！对！挨揍不好受，对吧？军团的渣滓！"
D.Strings[106870]="虚空领主，我们打开了通往军团运输舰的传送门，那里全是恶魔。让它们尝尝充当强者傀儡的滋味吧！"
D.Strings[106871]="秘法会的法师要你帮忙调查占据了悲泣平台的邪缚魔刃豹。这根魔杖或许能移除它们身上的魔法。"
D.Strings[106872]="但愿这场与燃烧军团的战争结束时，大地之环有办法修复这片伤痕累累的土地。"
D.Strings[106873]="英雄，大地之环的萨满正努力压制荼毒这片土地的邪能诅咒。他们需要你在净化仪式期间协助作战。"
D.Strings[106874]="干得好，先知。接下来就交给你的萨满吧。"
D.Strings[106875]="先知！邪火元素在用诅咒烧灼大地。请净化我们战士身上的诅咒，驱散这些怪物的魔法。"
D.Strings[106876]="尽快赶去城墙的北端！城堡顶端盘踞着一股黑暗力量！"
D.Strings[106877]="一头恶魔守住了黑鸦堡垒？立刻消灭他！"
D.Strings[106878]="我得休息一下。小心点，勇士！"
D.Strings[106879]="我们不会倒下！"
D.Strings[106880]="圣光使我们永存。"
D.Strings[106881]="感受圣光的力量吧！"
D.Strings[106882]="织梦者会派角鹰兽送你们登船。消灭这次战役的指挥官，其他懦弱的恶魔就会撤退了。祝你们好运，勇士们！"
D.Strings[106883]="夺取塔楼的关键就在于打倒里面的首领。我们必须夺下那座塔楼！"
D.Strings[106884]="屏障关闭了，但邪恶的军团依然笼罩着我们。如果我们能占领塔楼顶层，织梦者就能帮你们登上恶魔舰船。"
D.Strings[106885]="我感觉你从破碎海滩带来了危险的消息。我们在紫罗兰城堡见。"
D.Strings[106886]="我夺回阿利卡了。末日石呢？"
D.Strings[106887]="我来稳定它！挡住恶魔，直到我阻止他们为止！"
D.Strings[106888]="这个蠢货！她的传送门已经过载了，正在撕开通往扭曲虚空的裂隙！"
D.Strings[106889]="邪能墙堵住了守望者塔楼的入口。让你的队伍上去摧毁军团为屏障供能的机器。我们会守住这里的。"
D.Strings[106890]="你们输定了，恶魔！"
D.Strings[106891]="把军团赶出这个世界！"
D.Strings[106892]="防御者，行动！该我们进攻军团了！"
D.Strings[106893]="我们得净化这片古老森林里的军团力量。下令吧，英雄们，拯救瓦尔莎拉的战役即将打响！"
D.Strings[106894]="奥丁祝福你，陌生人！"
D.Strings[106895]="我再也不用成为猎犬的饲料了！"
D.Strings[106896]="谢谢你，陌生人！愿我们在英灵殿再会！"
D.Strings[106897]="最终的死亡……降临到我们头上了。"
D.Strings[106898]="放了我，陌生人。我宁愿永远在冥狱深渊中沉沦，也不想遭受此地等待着我的命运！"
D.Strings[106899]="那些猎犬会吞掉我们的！"
D.Strings[106900]="请让我解脱！"
D.Strings[106901]="唔……我觉得他应该不止这点本事。"
D.Strings[106902]="嘿，你！我带了些玩具来供你借用。祝你好运。"
D.Strings[106903]="这是圣水，格雷森。"
D.Strings[106904]="唔……劳伦斯……让我看看……\n\n噢，没错，她之前来过。她想找一根特殊属性的法杖。这件事很奇怪，真的，因为我通常只会向术士客户推荐那种法杖。\n\n我花了几天时间来寻找，但最后还是找到了，并且按照她的要求把它送去了魔术旅馆。"
D.Strings[106905]="有什么能效劳的吗？"
D.Strings[106906]="|TInterface\\Icons\\ABILITY_CREATURE_CURSED_03.BLP:32|t孟菲斯托斯使用|cFFFF0000|Hspell:233206|h[暗影消退]|h|r隐蔽了身形！"
D.Strings[106907]="你躲不了的，孟菲斯托斯！"
D.Strings[106908]="我们开始突袭吧。"
D.Strings[106909]="必须不惜一切阻止敌人！"
D.Strings[106910]="%s开始引导|cFFFF0404|Hspell:234728|h[奥能毁灭]|h|r！"
D.Strings[106911]="我们得通知其他职业组织。我们要去破碎海滩了。"
D.Strings[106912]="我来开启通向奥术师莱娜的传送门。稍等。"
D.Strings[106913]="高阶巫师，我需要你说服其他职业组织与我们一起对抗燃烧军团。"
D.Strings[106914]="你好！这里真是进行奥术冥想的好地方，你不觉得吗？"
D.Strings[106915]="|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t 化身开始施放|cFFFF0404|Hspell:234724|h[歼灭]|h|r！"
D.Strings[106916]="|TINTERFACE\\ICONS\\SPELL_FEL_ELEMENTALDEVASTATION:20|t堕落的守护者开始施放|cFFFF0404|Hspell:233856|h[净化协议]|h|r！"
D.Strings[106917]="|TINTERFACE\\ICONS\\SPELL_FIRE_FELHELLFIRE:20|t 化身开始施放|cFFFF0404|Hspell:239132|h[割裂现实]|h|r!"
D.Strings[106918]="|TINTERFACE\\ICONS\\SPELL_FIRE_FELFIRENOVA:20|t 化身开始向你施放|cFFFF0404|Hspell:234059|h[释放混沌]|h|r！"
D.Strings[106919]="很好，$n。但在宣布胜利之前，还有很多事要做。"
D.Strings[106920]="干得好。那些无耻的骗子干扰了重要行动。"
D.Strings[106921]="军团开启的传送门里涌出了一群恶心的小鬼。勇士，去干掉那些小恶魔！"
D.Strings[106922]="那些邪恶生物的死会激怒军团。快去黑鸦堡垒。我们得继续进攻！"
D.Strings[106923]="很不幸，海巨人强占了那些货物。去杀掉他们，把船骸里失落的补给拿回来。"
D.Strings[106924]="在首次突袭中，有些珍贵的补给沉入了海底。它们对于抵抗军团的战斗依然有用。"
D.Strings[106925]="燃烧军团就像瘟疫，能令大地生病。我们得在他们的力量继续扩散前净化那些恶魔！"
D.Strings[106926]="恶魔先入侵我们的土地，现在又染黑了天空。"
D.Strings[106927]="很荣幸与你并肩战斗，战争领主$n。我要去救赎岗哨了。回头见！"
D.Strings[106928]="你很英勇，战争领主$n。我要去救赎岗哨了。回头见。"
D.Strings[106929]="去召集其他职业组织。我们要去破碎海滩了。"
D.Strings[106930]="这些长羽毛的家伙毫无忠诚可言。咸饼干把我丢在了沉船上，但作为一个成功的海盗船长，我可不能没有合适的伙伴！纳纳斯是我的新搭档，而且他非常有用！$b$b总之，谁还需要鸟呢？作为船员，纳纳斯管用多了。"
D.Strings[106931]="怎么换成猢狲了？"
D.Strings[106932]="嘿， $n。我期待着一场盛大的爆炸！"
D.Strings[106933]="海拉……我辜负了你……"
D.Strings[106934]="我要为女主人的死报仇！只要我还有一口气在，污秽的外来者就别想控制克瓦迪尔！"
D.Strings[106935]="立刻送我去营地！[加入场景队列]"
D.Strings[106936]="这些恶魔要为他们的所作所为付出代价。我发誓！"
D.Strings[106937]="咸饼干！亏我还把你当成兄弟呢！你太让我伤心了！"
D.Strings[106938]="库鲁尔回来了？我们得准备突袭那个恶魔的巢穴。卡莱，你务必要保障伊利达雷的物资供应。"
D.Strings[106939]="呸！这些维库人以为他们能偷走我们的火药？他们一定会偷鸡不成蚀把米的！"
D.Strings[106940]="什么？！火药被鹰身人抢走了？我得召集船员前往至高岭！"
D.Strings[106941]="干得好，你解决了那些巨人！你搜集到的补给品会对战事大有帮助的。"
D.Strings[106942]="你的法术冷却和减益状态都重置完毕了。"
D.Strings[106943]="哪儿都不见她的踪影。她肯定又被抓走了！"
D.Strings[106944]="你闭嘴，克丽西娅！"
D.Strings[106945]="嘿，多罗莉亚，这人在找你。"
D.Strings[106946]="唔，那个戴着面具的不就是她吗？噢，等等，对——不对，我没见过她。"
D.Strings[106947]="你肯定比戴着两只眼罩的海盗还要瞎。"
D.Strings[106948]="太好了！你绝对是最佳人选。我们随时都能提供所有已知威胁的情报。"
D.Strings[106949]="我通常不会干涉自然的演化……但我可不想同时对付海怪和燃烧军团的大军！"
D.Strings[106950]="她和她的克瓦迪尔无耻地偷走了许多强大的灵魂。我们要解放他们，让他们在天上获得应有的地位。"
D.Strings[106951]="我们似乎遇到了一个巨蛋的问题……呃，蛋本身没问题，问题是它们孵化出来的海怪。"
D.Strings[106952]="联盟的战士们！我们有任务了！"
D.Strings[106953]="你好，战争领主。在这个艰难的时刻，你正是我们所需要的那种坚强领袖。"
D.Strings[106954]="达利乌斯阁下，我要你去召集其他职业组织形成联军，共抗燃烧军团。"
D.Strings[106955]="啊哈！有线索了！不对，只是些灰尘而已。"
D.Strings[106956]="嗯，也许她就在这里……"
D.Strings[106957]="打扰一下，好心的先生，你见到我的多罗莉亚了吗？"
D.Strings[106958]="部落战士们，行动！"
D.Strings[106959]="你得救了，我的爱人！等等……好像有什么不对。"
D.Strings[106960]="伊崔格，我要你去召集其他职业组织形成联军，共抗燃烧军团。"
D.Strings[106961]="在囚禁我们时，肯瑞托将库鲁尔的心脏藏在了达拉然的金库里，以防它落入军团之手。"
D.Strings[106962]="来吧，侍从！我去最高的那座山等你。"
D.Strings[106963]="别害怕，我的爱人，我们会追上那些强盗，把你救出来的。"
D.Strings[106964]="麦斯米兰？你怎么知道我在这儿？"
D.Strings[106965]="多罗莉亚，我的爱人，我终于找到你了！你还好吗？"
D.Strings[106966]="有人闯入了金库！"
D.Strings[106967]="过来，英雄们！用圣盾保护我，我来把这家伙抓出来！"
D.Strings[106968]="产蛋的怪物就在这个洞里！去看看上层区域！"
D.Strings[106969]="你重创了他们。现在，全力对付这些蛋吧。"
D.Strings[106970]="你吸引了它！它过来了！"
D.Strings[106971]="我来告诉你燃烧军团想要什么——我的棺材本儿！军团级的防护结界可不便宜，甜心！"
D.Strings[106972]="噢，灾难呀！祸事呀！我们在失去客户的信任！$B$B<格鲁托妮雅顿了顿，确认你在听。>$B$B或许10个金币熟悉的香味能让我恢复记忆！$B$B我只收不带记号的金币，谢谢。"
D.Strings[106973]="我看见那个恶魔在一片混乱中躲进了一座传送门。他足有两个牛头人那么大——没准是三个！"
D.Strings[106974]="我……决不……投降……"
D.Strings[106975]="求你……让我走吧。我还有家庭呢。"
D.Strings[106976]="为什么？你为什么要这么做？"
D.Strings[106977]="我什么都不知道……"
D.Strings[106978]="滚……出……我的……脑袋！"
D.Strings[106979]="我的……头……从我的脑子里……滚出去。"
D.Strings[106980]="停下！求求你，停下！"
D.Strings[106981]="邪能熔炉每损失一条灵魂，敌人都会更弱。干得好。"
D.Strings[106982]="恶魔又从苏拉玛掠夺了一批难民。快去帮暗影议会的潜行者救出俘虏吧，免得他们变成邪能燃料。"
D.Strings[106983]="邪能熔炉每损失一条灵魂就能削弱敌人。干得好。"
D.Strings[106984]="暗影之刃，恶魔又从苏拉玛掠夺了一批难民。你和你的潜行者得救救他们，以免他们变成邪能燃料。"
D.Strings[106985]="塔耶·钢皮"
D.Strings[106986]="梅尔汉·光怒"
D.Strings[106987]="娜琳·夺心"
D.Strings[106988]="古尔德克·石盾"
D.Strings[106989]=S[21236]
D.Strings[106990]="拉希恩·光陨"
D.Strings[106991]="只要打碎足够的蛋，产下它们的怪物肯定会出来拼命！"
D.Strings[106992]="就是这里。杀掉所有怪物，打碎所有的蛋！"
D.Strings[106993]="白银之手的圣骑士想在邪火小径举行个神圣仪式，但遭到了军团的反击。杀掉那个恶魔首领，让我们净化此地。"
D.Strings[106994]="干得好。你为我们争取到了完成任务所需要的时间。"
D.Strings[106995]="感谢你的帮助，我们会完成任务，向提里奥的牺牲致敬的。"
D.Strings[106996]="我们想去净化提里奥的陨落之地，但被军团击退了。我们需要你，大领主。"
D.Strings[106997]="力量的魅力是巨大的，许多人都会受其蛊惑。我们别无选择，只能终结这些术士的威胁。"
D.Strings[106998]="军团麾下的强大术士都聚集到了邪火小径。我们得在他们变强之前阻止他们和他们疯狂的主子。"
D.Strings[106999]="至少没上巨型激光眼球，对吧？"
D.Strings[107000]="很好，英雄！剩下的就交给我们的德鲁伊吧。"
D.Strings[107001]="看到这片古老的土地被那些怪物玷污，我十分痛心。快阻止他们！"
D.Strings[107002]="这次会来许多。那个机器涌动着圣光。"
D.Strings[107003]="我发誓，再也不跟铜须家的人一起冒险了！"
D.Strings[107004]="我们还没死！"
D.Strings[107005]="我随时可以送你回去，大祭司。"
D.Strings[107006]="我准备好返回达拉然了。"
D.Strings[107007]="你准备好离开了吗，大祭司？只要你说一声，我就把潜艇开回达拉然去。"
D.Strings[107008]="你想从队伍中移除哪个圣骑士？"
D.Strings[107009]="这座遗忘之城里的部队将无法再躲藏在阴影中。$b$b我听候你的吩咐。"
D.Strings[107010]="让我们给这个邪恶之地带去光明吧。$b$b我该怎么帮助你？"
D.Strings[107011]="你好，大领主。我愿意为你效劳。"
D.Strings[107012]="我……输了？这……不可能……"
D.Strings[107013]="为……什么？"
D.Strings[107014]="亲爱的伽留斯，快用我教你的法术。别搞砸了！"
D.Strings[107015]="你的武器要涂点毒药吗？"
D.Strings[107016]="我没时间犯蠢！"
D.Strings[107017]="你以为你自己能搞定吗？"
D.Strings[107018]="我需要治疗之水。"
D.Strings[107019]="我需要……喘口气。"
D.Strings[107020]="我这把老骨头需要休息了。"
D.Strings[107021]="感受恐怖图腾的愤怒吧！"
D.Strings[107022]="我动动手指就能毁灭你！"
D.Strings[107023]="你这蠢货，竟敢挡我的路！"
D.Strings[107024]="你不是元素的对手！"
D.Strings[107025]="我都没出汗。"
D.Strings[107026]="我对蠢货没什么耐心。"
D.Strings[107027]="塞西亚·橡棘"
D.Strings[107028]=S[18571]
D.Strings[107029]="卡尔贡·光须"
D.Strings[107030]="守备官艾德里"
D.Strings[107031]="守备官达兰安"
D.Strings[107032]=S[18572]
D.Strings[107033]="听我的，孩子。"
D.Strings[107034]="要去杀几个敌人吗？"
D.Strings[107035]="你走吧……我会跟上来的。"
D.Strings[107036]="你能帮我解决那家伙吗？"
D.Strings[107037]="墓穴在召唤我……"
D.Strings[107038]="我的斧子饥渴难耐了！"
D.Strings[107039]="游戏时间！"
D.Strings[107040]="我会让你一个人玩吗？"
D.Strings[107041]="该把敌人送上绞架了！"
D.Strings[107042]="死到临头了！"
D.Strings[107043]="啊，对，芬芳的死亡。"
D.Strings[107044]="欢迎来到坟场！"
D.Strings[107045]="让血流成河吧！"
D.Strings[107046]="你抵挡不了这力量！"
D.Strings[107047]="女王，赐予我力量吧！"
D.Strings[107048]="谁都别想再抗拒我！"
D.Strings[107049]="不！我是应许之人！"
D.Strings[107050]="别担心……我会好的。"
D.Strings[107051]="你走吧，别管我！"
D.Strings[107052]="别管我……"
D.Strings[107053]="你不是我的对手！"
D.Strings[107054]="让我送你上路吧。"
D.Strings[107055]="人人都得孤独地死去！"
D.Strings[107056]="化为灰烬吧！"
D.Strings[107057]="喜欢我背后捅刀子？！"
D.Strings[107058]="我是专业的！"
D.Strings[107059]="看到底是谁救谁？"
D.Strings[107060]="我从暗影中来。"
D.Strings[107061]="快搞定它！"
D.Strings[107062]="我……呃……我真的得走了！再见！"
D.Strings[107063]="不想死就滚！"
D.Strings[107064]="需要再来点小花招吗？"
D.Strings[107065]="看来你需要我帮忙。"
D.Strings[107066]="毫无挑战。"
D.Strings[107067]="噢，看来你死了。"
D.Strings[107068]="别惹拿匕首的公主。"
D.Strings[107069]="我要撤了！"
D.Strings[107070]="你先走！"
D.Strings[107071]="别担心，你很快就会死的。"
D.Strings[107072]="见识一下我的匕首吧！"
D.Strings[107073]="你该倒下了！"
D.Strings[107074]="这……跟我没关系！伽留斯·米尔摩才不会被区区一个魅魔催眠呢！"
D.Strings[107075]="噢，我的头……出……什么事了？"
D.Strings[107076]="瓦里斯，解决这群暴民。"
D.Strings[107077]="尝尝我的爪子！"
D.Strings[107078]="我掩护你，大德鲁伊！"
D.Strings[107079]="哈！你抓不住我们！"
D.Strings[107080]="满爪血腥的感觉真好！"
D.Strings[107081]="那个方向还有更多！"
D.Strings[107082]="啊！好疼！"
D.Strings[107083]="伽留斯晕了过去。"
D.Strings[107084]="我得……喘口气了。"
D.Strings[107085]="我得撤退了。加油！"
D.Strings[107086]="尝尝我的爪子吧！"
D.Strings[107087]="我要抓死你！"
D.Strings[107088]="让我们来搞破坏吧！"
D.Strings[107089]="让我去对付他们！"
D.Strings[107090]="末日石太不稳定了。我们得把它藏在大漩涡里，不能让别人得到。把它交给努波顿吧，他会好好照看的。"
D.Strings[107091]="快——进神殿！找到那个操纵攻击的恶魔并干掉他。"
D.Strings[107092]="我需要你的支援！"
D.Strings[107093]="我需要你的利刃！"
D.Strings[107094]="我需要你的保护！"
D.Strings[107095]="我准备好接受召唤了。"
D.Strings[107096]="在你的领导下，黑暗收割议会将获得远超以往的力量。"
D.Strings[107097]="我是来帮你应对军团的威胁并给出建议的。这些任务极其困难，所以请做好准备。$b$b我们需要虚空碎片来突破他们的防御，或帮助你抵抗他们的可怕进攻。我有时会有一些多余的碎片，但不一定。请按照情况自行准备好碎片。"
D.Strings[107098]="你阻碍了军团的军工生产，虽然只是暂时的。在这里，每次胜利都很宝贵。"
D.Strings[107099]="他们在为熔炉收取矿石。我们每抢走一块矿石，针对我们的力量就会减少一些。"
D.Strings[107100]="遵……命。"
D.Strings[107101]="杀了入侵者，兄弟！"
D.Strings[107102]="什么？！你做了什么？不！！"
D.Strings[107103]="毁掉我？！不，兄弟。你的剑只会变成我的工具！"
D.Strings[107104]="我不能让你祸害艾泽拉斯，莱斯特。如果你不投降，我只能毁掉你了！"
D.Strings[107105]="你真蠢，居然跟着我来到这里，兄弟。扭曲虚空滋养了我的力量。我的强大已经超出了你的想象！"
D.Strings[107106]="肯瑞托给了我一块传送水晶。他们肯定在等着你成功的消息。非常感谢，$n。我们后会有期。"
D.Strings[107107]="但是即便如此，在你击败他们的军团主子前，我还是会盯着这些叛徒的。"
D.Strings[107108]="没有图加，邪能图腾的威胁就减弱了。"
D.Strings[107109]="我来了！我准备——怎么？图加死了！你居然不等我！"
D.Strings[107110]="这改变不了……什么。军团……必胜……"
D.Strings[107111]="看，我最伟大的造物！军团的力量必将毁灭雷霆图腾！"
D.Strings[107112]="我告诉你……你这是白费力气。"
D.Strings[107113]="我准备让你来决定，究竟该如何获取净化仪式的最后一种材料。$b$b也许你还可以顺便发现到底是什么惊扰了这片被圣光抛弃之地里的亡灵。"
D.Strings[107114]="你这是螳臂当车！我的邪能兽只会更强大！"
D.Strings[107115]="蠢货！我是故意让你找到的。现在，我要向雷霆图腾和你……复仇！"
D.Strings[107116]="召集盟友！为雷霆图腾而战！我们必胜！"
D.Strings[107117]="你们四分五裂的部族挡不住无穷大军！"
D.Strings[107118]="控制一下，不要引发毁灭！"
D.Strings[107119]="先知！住手！你要撕裂元素位面了！"
D.Strings[107120]="怎么回事？！你……不可能……打败我！"
D.Strings[107121]="火墙！啊！你去阻止图加，我会尽快赶去的！"
D.Strings[107122]="好帮手太难找了。我只能……亲自下场了。"
D.Strings[107123]="你拿着什么，小萨满？你竟敢拿块石头来挑战我？"
D.Strings[107124]="好的，宝贝，我不会让他们毁掉今晚的约会的！"
D.Strings[107125]="亲爱的伽留斯，这些入侵者打断了我们的独处！快干掉他们！"
D.Strings[107126]="我全听你的，小甜心！"
D.Strings[107127]="我准备好前往大漩涡了。"
D.Strings[107128]="我们认为那座失落的泰坦宝库就位于大漩涡东北方，应该很快就能找到。\n\n你准备好了吗，大祭司？"
D.Strings[107129]="这或许可以安排一下。大宗师$n，你看上去不太好。你应该回晴日峰去！"
D.Strings[107130]="如果你要去找那个末日守卫，就告诉我一声，先知。我可以将我的能量导入你的末日石。"
D.Strings[107131]="还有最后一个求助，凡人。桑德兰需要你的帮助。"
D.Strings[107132]="我愿意加你们，但这个洞穴只能容纳肉体凡胎。让我的力量导入你的末日石，用它碾碎我们的敌人吧！"
D.Strings[107133]="塞拉赞恩需要帮助，她就在附近的洞穴里。快去！"
D.Strings[107134]="先知！驾驭着我的怒火，用炎魔之王的力量熔化燃烧军团吧！"
D.Strings[107135]="斯莫德隆需要你的帮助，先知。他就在山脊上。"
D.Strings[107136]="引导我的力量进入末日石，摧毁那些邪能散播器吧！"
D.Strings[107137]="美味的灵魂！我还要更多！"
D.Strings[107138]="失落的泰坦宝库……而且保存完好？它会被载入史册的！你们觉得这些小玩儿意是啥？"
D.Strings[107139]="|TInterface\\Icons\\SPELL_FIRE_FELIMMOLATION:20|t%s开始施放|cFFFF0000|Hspell:233062|h[地狱燃烧]|h|r。快躲起来！"
D.Strings[107140]="|TInterface\\Icons\\SPELL_SHADOW_SUMMONINFERNAL:20|t%s用|cFFFF0000|Hspell:233272|h[碎裂星辰]|h|r瞄准了你！快躲起来！"
D.Strings[107141]="|TInterface\\Icons\\ABILITY_WARLOCK_BURNINGEMBERSGREEN:20|t%s用|cFFFF0000|Hspell:232249|h[彗星冲撞]|h|r瞄准了你！"
D.Strings[107142]="谁敢打断我的盛宴？"
D.Strings[107143]="我期待着看到你葬身火海。再见了，凡人！"
D.Strings[107144]="你成功摧毁了我的船，但这将是你的最后一次胜利了！"
D.Strings[107145]="够了！我没时间玩游戏！"
D.Strings[107146]="这块木头看起来有点吓人，但它的魔力依然强大，足够我们使用了！"
D.Strings[107147]="这棵树里还有许多有用的心木！"
D.Strings[107148]="燃烧军团的力量衰退了。我们必须一鼓作气，结束这一切！"
D.Strings[107149]="我准备好关闭能量源了。"
D.Strings[107150]="英雄不死，必将复兴！"
D.Strings[107151]="快到外面来见我！该斩断军团的触手，解放阿苏纳了！"
D.Strings[107152]="这只是一个……开始……"
D.Strings[107153]="我们无穷无尽！我们的目光远超这可悲的世界。"
D.Strings[107154]="邪能图腾抓走我的人民，强迫他们参战。我们得阻止这种恶行！"
D.Strings[107155]="没错。大祭司，给我们点时间，把它们记入圣光编年史。我们神殿见。"
D.Strings[107156]="那就是你。"
D.Strings[107157]="她知道虚空很快就会发现这个大厅。她知道谁能保护它们，并用它们来侍奉圣光。"
D.Strings[107158]="你错了，丫头。我……我们……就是为此而来的。"
D.Strings[107159]="没有人来照料这些小可怜了！"
D.Strings[107160]="唔，管理员关机了。这个大厅可能耗尽了能量。"
D.Strings[107161]="这是最后一批了。但愿这是我最后一次遇到这种事……"
D.Strings[107162]="那些大家伙肯定也会活过来的。小心！"
D.Strings[107163]="我感觉我兄弟身上有腐蚀。你要小心。"
D.Strings[107164]="光耀之子，它们很少见，用驱散法术就能赶走。"
D.Strings[107165]="真是好极了！我们走！"
D.Strings[107166]="无法执行。清除协议无法终止。访客可能遭到腐蚀。如听到来源不明的低语，请直接走进烧灼光柱。"
D.Strings[107167]="呃……关掉它，行吗？"
D.Strings[107168]="啊，对，不止一次了！伟大的代言人。所以关掉它，好吗？"
D.Strings[107169]="又？你以前也见过这种事？"
D.Strings[107170]="见鬼！又来了！"
D.Strings[107171]="警报！发现虚空能量。启动清除协议。"
D.Strings[107172]="这些高贵的生物在我们不懂自保时，就保护过我们……"
D.Strings[107173]="这颗星球成型后，遭到了侵略性堕落实体的轰炸。战斗损耗逐渐减少了寻觅者的数量。现在，已知的仅剩这几只了。"
D.Strings[107174]="它们出什么事了？"
D.Strings[107175]="那这里只有三只？"
D.Strings[107176]="检索中……当前已知寻觅者数量：三。"
D.Strings[107177]="种群？我们连一个都没见过！它们还剩多少？"
D.Strings[107178]="学名：寻觅者。由塑造者灌注圣光的凶猛生物。从种群中优选最强个体并接受训练，依照协议帮助守护者快速前往腐化地点。"
D.Strings[107179]="请听我说。"
D.Strings[107180]="呃，管理员先生，寻觅者到底是个啥？"
D.Strings[107181]="寻觅者……对，她指引我来这儿肯定就是这个意思。她想让我们找到这些生物。"
D.Strings[107182]="代言人状态确认。欢迎，代言人。您来回收寻觅者吗？"
D.Strings[107183]="你什么意思？没必要？我？你才“没必要”，你这小……"
D.Strings[107184]="未发现必要生命形态。重新扫描。"
D.Strings[107185]="噢，我知道接下来该怎么办！拿起武器！"
D.Strings[107186]="正在扫描生命形态。"
D.Strings[107187]="系统激活。发现访客。"
D.Strings[107188]="我们必须同时激活它们。大祭司，你来好吗？"
D.Strings[107189]="真可惜。"
D.Strings[107190]="嗨，我想你不用再找什么拉杆、开关了，布莱恩！"
D.Strings[107191]="哇，好大的门！但这里肯定会有个拉杆的。拉杆无处不在！"
D.Strings[107192]="准备停靠。"
D.Strings[107193]="我们好像接近宝库入口了。"
D.Strings[107194]="那感觉就像……日出。"
D.Strings[107195]="所以……她“感觉”你应该来这儿？"
D.Strings[107196]="呃，比如你是一个世界的灵魂，对吧？那你的感觉会是什么样的呢？你会时而像崩塌的山脉，时而像漆黑的深海。那种感觉我没法描述出来。"
D.Strings[107197]="那是啥？"
D.Strings[107198]="是的，但她不是用语言。而是……感觉……但不是凡人的感觉。"
D.Strings[107199]="我说，哥哥……是那个叫艾泽拉斯的星球……让你来的吗？"
D.Strings[107200]="眼下风平浪静，连大漩涡附近也一样。"
D.Strings[107201]="我从探险者协会的朋友那里借了一艘小潜水艇。等你到了，我们就从阿苏纳的海滩出发，大祭司。"
D.Strings[107202]="大祭司！我带来了重要消息。"
D.Strings[107203]="我很荣幸能被选中执行这个任务。我不会让你失望的，大宗师$n。"
D.Strings[107204]="我要你去说服其他势力跟我们一起对抗燃烧军团。我们必须团结一致！"
D.Strings[107205]="燃烧军团大举入侵艾泽拉斯。每个人都必须贡献自己的力量。"
D.Strings[107206]="我很累了。但在确认大家都安全无恙之前，我还不能休息。"
D.Strings[107207]="有了你的领导和风暴蜜酒，我们必胜！"
D.Strings[107208]="我来面对赞达尔。送我上去！"
D.Strings[107209]="我们必须将此地从军团的腐蚀中解放出来！"
D.Strings[107210]="看来库鲁尔的走狗来过这里。"
D.Strings[107211]="愿奥丁祝福你。"
D.Strings[107212]="愿英灵殿的大门向你敞开。"
D.Strings[107213]="感谢奥丁，我还以为自己死定了！"
D.Strings[107214]="噢，你知道的……\n\n别人都盯着呢。\n\n你快走吧！"
D.Strings[107215]="其他人呢？"
D.Strings[107216]="天呐，我正缺一个头冠呢。感谢你的细心体贴。\n\n<密使高兴地对你笑了笑。>"
D.Strings[107217]="灰石和绿火。又来了。"
D.Strings[107218]="所以我才会被派来这里。"
D.Strings[107219]="为什么哪儿都有恶魔？"
D.Strings[107220]="你追得太远了，$n。我的宝贝小鬼会让你尝尝超乎想象的痛苦。"
D.Strings[107221]="你真是太固执了！亲爱的小鬼们，保护我！"
D.Strings[107222]="送我去破碎海滩！"
D.Strings[107223]="你真是战斗力惊人。可惜你不是天生的战士！但是我想凡人总会有点缺陷。"
D.Strings[107224]="有些蔑魔战士还不知道他们的神王已经完了。加入我的瓦拉加尔，送这些蠢货去见那个神王吧！"
D.Strings[107225]="为了瓦拉加尔！"
D.Strings[107226]="战争领主！有些蔑魔战士还不知道他们的神王已经完了。送这些叛逆去见老主子，赢得我的赞赏吧。"
D.Strings[107227]="你打断了我的宴会，这是个致命的错误，凡人！"
D.Strings[107228]="我的计算机！你……你是怎么猜到我的密码的？！我用了很多符号和大写字母的！"
D.Strings[107229]="她会追悔莫及的。军团才是我们真正的盟友！"
D.Strings[107230]="请注意。本舰即将自毁。请尽快离开本舰。"
D.Strings[107231]="是塞琳派你来的？她真要勾结外人来对付自己的同胞？"
D.Strings[107232]="背叛者都要付出生命的代价！"
D.Strings[107233]="你无耻，莱瑟拉！你发誓要保护苏拉玛的。"
D.Strings[107234]="回头见。"
D.Strings[107235]="在那艘臭哄哄的船上呆了好几个月，我都精神失常了。而且，那种情况也需要我这样的专业人士……\n\n也许我该弄几个分身出来。"
D.Strings[107236]="你为什么跟其他人分开了？"
D.Strings[107237]="我很高兴你遵守了我们的约定，屠魔者$n。也许之前是我看错了你。"
D.Strings[107238]="没关系！你会付出代价的……我要吞掉你的灵魂！"
D.Strings[107239]="卑贱的凡人！你对我的船做了什么？！"
D.Strings[107240]="血洗这片土地！一个凡人都不要放过！他们的灵魂都将属于我！"
D.Strings[107241]="我想……我能打败他的。但谢了。"
D.Strings[107242]="啊，屠魔者$n。既然你来了，就帮个忙吧。"
D.Strings[107243]="邪能还需要更多灵魂燃料！我还要更多！"
D.Strings[107244]="穆恩厌恶地向玛加萨的脚下吐了一口唾沫。"
D.Strings[107245]="不够……我还要更多的灵魂！"
D.Strings[107246]="她嘲讽了我们的警惕性，然后独自离开了。之后我就没有见过她。"
D.Strings[107247]="我向你保证，她别想在这里自由行动。"
D.Strings[107248]="但让她在外面行动的话会造成更大的危险。还是由我们盯着她比较好。"
D.Strings[107249]="我知道你和其他牛头人都不想在这里看到她，穆恩。"
D.Strings[107250]="可怜虫？！先知，把她赶出去！我跟她不共戴天！"
D.Strings[107251]="冷静点，你这小丑。这件事比你那个可怜虫酋长要重要得多！"
D.Strings[107252]="你竟然让这个怪物进入我们的圣地？？她谋杀了我们的酋长！"
D.Strings[107253]="如果有需要，我可以送你回守护者圣殿。"
D.Strings[107254]="我见识过你所谓的“礼物”，恶魔。我决不跟你们同流合污！"
D.Strings[107255]="你的抵抗是徒劳的！要么加入我们，要么我就剥下你的皮做斗篷！"
D.Strings[107256]="嘿！帮我打开这些镣铐！"
D.Strings[107257]="谢谢你，要不是被锁住了，我一定要亲手揍扁那个丑八怪！"
D.Strings[107258]="又有烤肉啦！"
D.Strings[107259]="你的生命属于军团！"
D.Strings[107260]="踩碎你的骨头！"
D.Strings[107261]="帮我修下护甲，古尔。"
D.Strings[107262]="古尔不会用微型铁砧。\n\n<这个莫尔葛蛮兵瞪着脚下。>"
D.Strings[107263]="那就送我去大漩涡吧，否则我就一个人带走它。"
D.Strings[107264]="混账小鬼！末日石必须留在我身边！"
D.Strings[107265]="我觉得把它交给努波顿才是最安全的做法。"
D.Strings[107266]="末日石，快把它给我！"
D.Strings[107267]="我不会把末日石给你的，玛加萨。"
D.Strings[107268]="好！你成功了！现在飞碟合而为一了！"
D.Strings[107269]="别把我当成手下，$r。你在我眼里只是个小鬼。"
D.Strings[107270]="攻击他们的防线，$n。干掉这些恶魔！"
D.Strings[107271]="我想去盲眼沼泽帮忙。"
D.Strings[107272]="我们得尽快处理这个威胁。"
D.Strings[107273]="你连传送门都开不了，还怎么使用末日石的力量？傻孩子。"
D.Strings[107274]="你从这里往前走，我走另一边。稍后我来找你。"
D.Strings[107275]="你休想……击败军团……"
D.Strings[107276]="你想要末日石？那就来拿吧！"
D.Strings[107277]="为了雷霆图腾！"
D.Strings[107278]="你得去帮帮其他人！"
D.Strings[107279]="挡住他们！"
D.Strings[107280]="不要放弃，$n！"
D.Strings[107281]="斯科瓦尔德的后裔必须死！"
D.Strings[107282]="走吧，孩子。去救我的部族。"
D.Strings[107283]="别废话！你们的先知呢？！"
D.Strings[107284]="最后，将剩余能量逐出奥术飞碟里的方法和之前很像。不要让它成长到你对付不了的程度。"
D.Strings[107285]="这些生物活得越久，力量就越强。尽快烧死它们，打断它们的成长。"
D.Strings[107286]="你终于要对冰霜飞碟里的能量进行最后的净化。想想你先前见过的那些生物，好好利用那些知识吧。"
D.Strings[107287]="这个飞碟中溢出的能量会减慢你的速度，最终毁灭你。反制它们的法术，并尽快远离它们攻击的区域吧。"
D.Strings[107288]="这是最后一次净化仪式了，大法师。记住先前的敌人给你的教训，那样就万事俱备了。"
D.Strings[107289]="德宾！你能听见吗？等我出去以后，一定要杀光迫害我们的诱捕者！"
D.Strings[107290]="你真是及时雨啊，战争领主$n！"
D.Strings[107291]="如果你想夺回它，我相信它肯定就在他们聚居的奥特兰克废墟的某处。"
D.Strings[107292]="但不用担心。我都没办法帮助安东尼达斯完成这个研究，他们就更不可能了。"
D.Strings[107293]="还是那些食人魔。肮脏的野兽。他们不久前洗劫了我们的废墟。很不巧，飞碟也被他们带走了。"
D.Strings[107294]="啊，没错。是的。我是说，它原本在我手上。呃，你看，它已经被偷了。"
D.Strings[107295]="你的眉毛还在吧？有些尝试了那个法术的学徒法师就没那么走运咯！"
D.Strings[107296]="大法师塞德瑞克，我在找安东尼达斯送你的飞碟。它在你手上吗？"
D.Strings[107297]="咒法师，你的火法师正在惊悚洞穴对付无尽的蜘蛛。法力风暴先生愿意提供他的独创法术。他说你们是“老朋友”了。"
D.Strings[107298]="当时，我跟大法师奥图鲁斯一起研究过它。他可能还记得它的下落。你可以在卡拉赞外面找到他。"
D.Strings[107299]="你说的是三分火碟。没错，他把它给我了，但那都是好久之前了。那时我还在卡拉赞学习呢。"
D.Strings[107300]="卡德加，我在找安东尼达斯多年前送给你的飞碟。"
D.Strings[107301]="我会牢记你的事迹，总有一天，蔑潮也会的。"
D.Strings[107302]="看来你是对的，外来者。谢谢你帮我找到正途。"
D.Strings[107303]="$n！你出去过了吗？我们正在努力抵挡恶魔！"
D.Strings[107304]="我们绝不能让这些恶魔玷污我们的家园！"
D.Strings[107305]="如果你们还能战斗，就集结起来保卫雷霆图腾吧！我们绝不能放弃！"
D.Strings[107306]="小心！燃烧军团的攻势简直连绵不绝。"
D.Strings[107307]="$n！他们的攻击已经令我们损失了不少人手！你的任何帮助都能让我们尽可能守住雷霆图腾！"
D.Strings[107308]="如果你觉得自己能完成安东尼达斯未竟的研究，那它就归你了。祝你好运，大法师$n。"
D.Strings[107309]="安东尼达斯死后，我决定把飞碟收藏起来。我已经没必要继续研究它了。"
D.Strings[107310]="自从……呃，自从一位问起它的老朋友很快就与世长辞后，我已经很久没有想起它了。"
D.Strings[107311]="战争领主$n！幸好你找了我。"
D.Strings[107312]="我在寻找安东尼达斯的奥术飞碟。它在你这儿吗？"
D.Strings[107313]="你好，$n。我能帮你什么忙吗？"
D.Strings[107314]="好吧！我要亲手了结了你！"
D.Strings[107315]="你的话语真是掷地有声，勇敢的$c。我们必须团结起来！"
D.Strings[107316]="燃烧军团！你得去警告其他人！"
D.Strings[107317]="我会好起来的，你得去帮帮其他人！"
D.Strings[107318]="谢谢你。感谢你的帮助。"
D.Strings[107319]="你的话语说明了你的勇敢，$n。保重。"
D.Strings[107320]="我们得确保所有的恶魔都确实被击败了。等你有空时，请回暗影大厅来见我们。"
D.Strings[107321]="未来的歌谣都将传颂今天等待着我们那份荣耀。"
D.Strings[107322]="只要我们的部队联合起来，燃烧军团就输定了！"
D.Strings[107323]="自由了！让我——"
D.Strings[107324]="可惜你们看不到了。死吧！"
D.Strings[107325]="有了这支能潜地的野兽大军，我将埋葬雷霆图腾！"
D.Strings[107326]="我发现了能承受邪能的野兽。"
D.Strings[107327]="别磨蹭，暗影之刃。我们走！"
D.Strings[107328]="呃，刚才的情况真火爆，幸好你擅长处理“高温”。"
D.Strings[107329]="勇士，秘法会的法师需要你帮忙清理惊悚洞穴里的蜘蛛。他们的火法师可以帮你。"
D.Strings[107330]="好了，用这个锚点下去吧！"
D.Strings[107331]="我准备好前往永恒之眼了。"
D.Strings[107332]="好，任务就快完成了。离开洞穴，用特塞斯给的火柴点燃火药。"
D.Strings[107333]="其实，还有件事。在附近洒些火药，制造一场“小”爆炸。"
D.Strings[107334]="很好。接着很简单——悄悄离开洞穴，剩下的就交给火药吧。"
D.Strings[107335]="顺便说一句，你要是不想被邪能长剑砍死，最好别被人发现。"
D.Strings[107336]="着陆后，你会看到一个桶。里面就是……你找来的邪能火药。"
D.Strings[107337]="我准备好面对图加了（需要能量充沛的钥石）。"
D.Strings[107338]="我准备好面对图加了（使用纳瓦罗格的能量充沛的钥石）。"
D.Strings[107339]="我们要跟图加和他的虫群战斗了！如果你准备好了，我就带你过去。"
D.Strings[107340]="你帮我保护了这片土地。现在该我帮你了。来吧，我们找个安全的地方聊聊。"
D.Strings[107341]="我永远感激你，$c。"
D.Strings[107342]="谢谢你，英雄。你把我从可怕的命运中救了出来。"
D.Strings[107343]="谢谢你，战争领主。为了联盟！"
D.Strings[107344]="你来得正是时候。我以为要被他们吃掉了……"
D.Strings[107345]="*嗅*这真是……美妙，伙计。"
D.Strings[107346]="我永远感激你，战争领主。"
D.Strings[107347]="谢谢你，战争领主。为了部落！"
D.Strings[107348]="等等……他忘了，对吧？我就知道。看来你得想想其他办法了！"
D.Strings[107349]="就差一步了！快离开那儿，用特塞斯给的火柴点燃火药。"
D.Strings[107350]="太迟了，蠢货！我掌握了毁灭雷霆图腾的利器！"
D.Strings[107351]="你最好在沿途多洒一些火药。你也不想让特塞斯失望，对吧？"
D.Strings[107352]="很好——你洒下的火药迟早会派上用场的。现在，快离开洞穴吧。"
D.Strings[107353]="还有，你最好别被发现。这些恶魔很野蛮！"
D.Strings[107354]="在洞底，你会发现你之前弄到的火药。拿上那些火药。"
D.Strings[107355]="使用锚点垂降到洞里，然后等待我的进一步指示。"
D.Strings[107356]="到了！让军团尝尝我们的怒火。"
D.Strings[107357]="在接受王冠前，我得完成弟弟的请求，祭奠家人。\n\n如果艾尔知道是谁害了我全家，那我得问问她。\n\n你准备好了就说一声。"
D.Strings[107358]="有秘法会掌舵，我们的联军一定能彻底碾碎燃烧军团！"
D.Strings[107359]="我敢肯定，这些叛逃者有着强大的强化手段。聪明的法师应该很擅长窃取它，$n！"
D.Strings[107360]="啊，到了！"
D.Strings[107361]="快去……警告图加……"
D.Strings[107362]="图加会为我报仇的。"
D.Strings[107363]="你们太迟了……图加赢定了……"
D.Strings[107364]="我已经准备好前往大本营了。"
D.Strings[107365]="别磨蹭了，暗影之刃。我们上去！"
D.Strings[107366]="非常好！最困难的任务已经完成了，现在你只要摧毁那艘船就行了！"
D.Strings[107367]="好消息，$n！那座传送门似乎生效了！你没有缺胳膊断腿吧？"
D.Strings[107368]="德宾，你还活着！我都快绝望了，老朋友。"
D.Strings[107369]="颤抖吧，我会将军团的力量倾泻到这个可悲的世界！"
D.Strings[107370]="跟紧我，大人。"
D.Strings[107371]="孟菲斯托斯大人，如果您愿意的话，我可以护送您前往驾驶层的控制台。"
D.Strings[107372]="请原谅，主人，但你必须自行输入自毁密码。"
D.Strings[107373]="不幸的是，我没有启动此类指令的必要权限。"
D.Strings[107374]="护盾发生器下线后，即可启动自毁指令摧毁此船。"
D.Strings[107375]="我过载了发生器。接下来该怎么做？"
D.Strings[107376]="耐心点，特塞斯。别那么着急。"
D.Strings[107377]="嘿，我已经忍不住内心的激动了！我要看爆炸！"
D.Strings[107378]="那边！阻止那个恶魔，别让他召唤同类！"
D.Strings[107379]="我用聚焦之虹归还了能量。艾泽拉斯的魔网应该恢复正常了。"
D.Strings[107380]="猜谜游戏结束了！"
D.Strings[107381]="大鱼吃小鱼！"
D.Strings[107382]="你们无法抵挡大海的召唤！"
D.Strings[107383]="让潮汐碾碎你！"
D.Strings[107384]="风暴并非总是从天而降……"
D.Strings[107385]="啃光他们的骨头！"
D.Strings[107386]="交出潮汐之石，我或许会饶你们一命……"
D.Strings[107387]="女王赋予了我支配大海的力量！"
D.Strings[107388]="面对波涛下的伟力吧！"
D.Strings[107389]="我辜负了……女王……"
D.Strings[107390]="拉善的骑手占领了天空。召唤他的巨鹰帮你守卫雷霆图腾吧！"
D.Strings[107391]="是啊，乔安娜，多亏了这位勇敢的$c。"
D.Strings[107392]="……你内心的阴影也消失了！"
D.Strings[107393]="大法师克希雷姆！你回来了……"
D.Strings[107394]="但愿这些火药……炸烂你的脸……"
D.Strings[107395]="我去侦察。你搞定以后，就把图腾带来给我。"
D.Strings[107396]="维伦在爆炸前将我们送了出来。库鲁尔就没这么幸运了。"
D.Strings[107397]="你成功了！我还以为你被炸死了。"
D.Strings[107398]="暗影休想控制我！"
D.Strings[107399]="我能治愈你的伤口。不要忘记圣光。"
D.Strings[107400]="唉……好吧。"
D.Strings[107401]="哈哈哈！你说那是螃蟹？你对于恶魔的无知已经暴露无遗了！我们得尽快开展对你的后期训练，以免你整天坐井观天！"
D.Strings[107402]="我只看见两只死螃蟹，你就想让我看这个？"
D.Strings[107403]="当然了，侍从！你也看到了，我突袭了这片海滩并挡住了燃烧军团。但我们还有很多事情要做。昨晚，他们想突破我的防线，但我坚定地挡住了他们的进攻。他们恐怖的尸体就在那边，但我估计你不敢多看它们几眼。"
D.Strings[107404]="训练？"
D.Strings[107405]="我的侍从？是你吗？我差点认不出了。你老得太厉害了！无所谓了，我想就算是比你年纪还大的人也得坚持训练。"
D.Strings[107406]="又见面了，麦斯米兰。"
D.Strings[107407]="你好啊，麦斯米兰。"
D.Strings[107408]="保重，主人！"
D.Strings[107409]="想摧毁这艘船的话，过载发生器可以对引擎造成灾难性的损害。"
D.Strings[107410]="覆盖完毕。如我的主人所愿，我已自行解锁了引擎室。"
D.Strings[107411]="他过载了自己的力量！小心！"
D.Strings[107412]="见证库鲁尔的怒火吧！"
D.Strings[107413]="那好吧。你们别想再挡路了。"
D.Strings[107414]="请稍等，正在关闭防御系统……"
D.Strings[107415]="当然。为孟菲斯托斯大人服务，您的愿望就是我的命令。"
D.Strings[107416]="这……根本……不可能。"
D.Strings[107417]="圣光熄灭了，先知。去死吧。"
D.Strings[107418]="我无法再维持屏障了。我们得速战速决！"
D.Strings[107419]="你为缰绳而来？哈！那就来试试吧！"
D.Strings[107420]="噢，那样最好了。就这么做吧。"
D.Strings[107421]="我们……绝不……屈服！"
D.Strings[107422]="需要我关闭船上所有的应急和防御系统吗，我的黑暗领主？"
D.Strings[107423]="我们有着无穷的力量和无尽的大军。臣服于军团的力量吧！"
D.Strings[107424]="如您所知，孟菲斯托斯，这艘船拥有多种防御系统以预防各种灾难性故障。"
D.Strings[107425]="哈！就剩你们了。没希望了，蠢货们。"
D.Strings[107426]="嗨！欢迎你，疲惫的旅人。来我劈啪作响的火堆旁坐坐吧。别害怕，我已经守住了滩头的阵地，很快就能挫败燃烧军团对这片土地的侵袭！"
D.Strings[107427]="你要坚强点，勇士。别放弃！"
D.Strings[107428]="你才是孤家寡人，库鲁尔！你死定了。"
D.Strings[107429]="这世界将被我毁灭。"
D.Strings[107430]="缰绳……"
D.Strings[107431]="吃了他们，宠物！"
D.Strings[107432]="提克迪奥斯可耻地败于伊利丹·怒风之手后，邪能与烈焰之主萨格拉斯钦点您领导纳斯雷兹姆走向荣耀。"
D.Strings[107433]="当然，大人。您是孟菲斯托斯，最强大最睿智的纳斯雷兹姆。"
D.Strings[107434]="如果你以为我这把骨头会冻在这里，那你就错了。哈哈，我们走！"
D.Strings[107435]="我只用吹灰之力就足以摧毁你们。"
D.Strings[107436]="让我们教你做亡灵吧！"
D.Strings[107437]="来吧，我们去挑战他！"
D.Strings[107438]="抱歉。那个族长以为他的宠物能拖住我。"
D.Strings[107439]="干得好，大法师。但你后头将要面对的溢出能量就没那么好对付了。"
D.Strings[107440]="傲慢的蠢货！我掌握着千万世界的灵魂之力！"
D.Strings[107441]="如果你有需要的话，我为你准备了新鲜的食物和绷带，大法师。"
D.Strings[107442]="大法师，如果你需要的话，我这些宝珠会对你的任务非常有用。"
D.Strings[107443]="大法师，如果你需要修理装备的话，我可以为你效劳。"
D.Strings[107444]="看来斯科瓦尔德的传承尚在，并未消失。"
D.Strings[107445]="按照您的要求，我现在可以提供常规程序以外的多项服务，以更好地服务我的黑暗领主。"
D.Strings[107446]="我的标准程序已经改写，以满足孟菲斯托斯大人的所有需求。"
D.Strings[107447]="当然，孟菲斯托斯大人。请稍等，我正在启动您先前的用户设置……"
D.Strings[107448]="我要摧毁这艘船。你有什么建议吗？"
D.Strings[107449]="关于我自己，你有什么能告诉我的吗？孟菲斯托斯大人是谁？"
D.Strings[107450]="告诉我你之前的设置，S.I.R.I.。"
D.Strings[107451]="你今天做得很好。谢谢你。我们该回去了。"
D.Strings[107452]="你带头吧，勇士。"
D.Strings[107453]="接下来，需要我们齐心协力了。"
D.Strings[107454]="干得好。现在，我们得直接深入扭曲虚空了。"
D.Strings[107455]="大德鲁伊！用你的魔法彻底关闭传送门吧！"
D.Strings[107456]="我们得关闭传送门！"
D.Strings[107457]="允许访问。您好，孟菲斯托斯大人。我能帮您什么忙吗？"
D.Strings[107458]="检测到能源故障……启动系统恢复……"
D.Strings[107459]="恶意自动支配协助矩阵——M/A/D/A/M——启动。欢迎你，使用者。"
D.Strings[107460]="你这是找死。"
D.Strings[107461]="你在挑战我的耐心。去死吧！"
D.Strings[107462]="你们都将被主人的怒火吞噬。"
D.Strings[107463]="无尽烈焰将吞噬你们！它不可阻挡！"
D.Strings[107464]="站住！这里是艾尔的宝库，来者何人？"
D.Strings[107465]="为了库鲁尔！为了军团！"
D.Strings[107466]="是……我把毒酒带来的。要是我先检查一遍……"
D.Strings[107467]="布兰琪！解释一下！大家差点都没命！"
D.Strings[107468]="我已经尽快赶来示警了，可还是迟了……"
D.Strings[107469]="酒仙？你刚想杀了我们！"
D.Strings[107470]="我一直想学习织雾之道！再见，酒仙。"
D.Strings[107471]="如果有需要，这些学徒会为你补充精力。我建议你重视他们的帮助。"
D.Strings[107472]="安东尼达斯本想独自完成这个项目。他耐心、睿智，还是一位魔法大师。现在，你必须证明自己比他更强，才能完成他未竟的工作。"
D.Strings[107473]="我会解除压制它们的结界。我相信只要你把神器中的能量导入飞碟，就会得到回应。"
D.Strings[107474]="这世界就这点本事吗？真可悲。"
D.Strings[107475]="安东尼达斯为这些飞碟注入了我们法师梦寐以求的力量。但他和他的同僚没能打散过剩的能量，让它们变成了现在这个样子。"
D.Strings[107476]="你看到酒仙了吗？"
D.Strings[107477]="我们好像喝多了……酒劲过去后会很难受的！但关闭传送门已经是小菜一碟了！"
D.Strings[107478]="你的死期到了，主母！"
D.Strings[107479]="就快成功了！坚持住！"
D.Strings[107480]="你的“自然之力”不是邪能之力的对手！"
D.Strings[107481]="库鲁尔必将重生！"
D.Strings[107482]="干掉他们，瓦祖恩。我即将重生了。"
D.Strings[107483]="我们得在部队彻底崩溃前击败那个指挥官！"
D.Strings[107484]="跟我们一起展翅高飞吧！"
D.Strings[107485]="我的力量不断增长。你们大难临头了！"
D.Strings[107486]="那些变异的孢子长在这座峭壁的最顶上。你需要一路杀上去，祝你好运！"
D.Strings[107487]="末日使徒开启了一条虚空裂隙！"
D.Strings[107488]="试试神圣魔法。这通常都会管用的。"
D.Strings[107489]="希望你在被消灭后能完成一项小调查，帮助我们在未来更好地为你服务。"
D.Strings[107490]="你输入的密码错误。已向你处派出安保人员，请在原地等待。"
D.Strings[107491]="这边，大德鲁伊。她就在岛上！"
D.Strings[107492]="这个维库人是神王的继承人。她想觐见艾尔。"
D.Strings[107493]="这边，大德鲁伊！我们找到她了！"
D.Strings[107494]="你回斯考德-艾希尔来干什么，外来者？\n\n……你带来的这个维库人又是谁？"
D.Strings[107495]="专心对付营地！"
D.Strings[107496]="好吧。回头见！"
D.Strings[107497]="唔，我想不出来。"
D.Strings[107498]="你们竟敢站在我的国土上？那好吧。"
D.Strings[107499]="呃……这比我想的要难！你有没有为这种场合准备过什么名言警句？"
D.Strings[107500]="呃……等等。离开前，我得说几句拉风的台词。"
D.Strings[107501]="听着，你来解决这个不管是不是我惹出来的麻烦，而我要闪亮退场了。"
D.Strings[107502]="沾血的嘴唇尝不出猪排的美味。你明白我的意思吧？"
D.Strings[107503]="我？我可不是战士。"
D.Strings[107504]="你毁了我的午睡。"
D.Strings[107505]="你真不该这么偷偷靠近别人。"
D.Strings[107506]="嘿！哇！"
D.Strings[107507]="帮帮我们的部队，大德鲁伊。我来想办法找到他们的指挥官。"
D.Strings[107508]="我们的部队已经把他们压回了路障后面，但更多恶魔仍然在不断凭空出现。"
D.Strings[107509]="恶魔已经在破碎海滩扎根了。他们已经待得够久了。"
D.Strings[107510]="你的战斗技巧进步了，阿麦。你已经成熟，不再是个普通的酿酒师了。"
D.Strings[107511]="酒仙，抱歉这里太乱了！我马上就让大家回去干活。"
D.Strings[107512]="衷心感谢，大宗师$n。"
D.Strings[107513]="敌人来了！"
D.Strings[107514]="保持警惕。我怀疑我们清净不了多久。"
D.Strings[107515]="我们会终结燃烧军团的，哪怕要为此付出生命。"
D.Strings[107516]="站到符文上。快！"
D.Strings[107517]="酒仙！坚持住！我们来了！"
D.Strings[107518]="我要先说明一下我们能做到什么以及做不到什么。\n\n我们可以穿过这座传送门，前往我之前所联结到的一个恶魔通道。\n\n但我们无法知道另一边有什么，因为魔法没有这个效果。\n\n所以，你先请。祝你好运，“英雄”。"
D.Strings[107519]="选项3：对计算机使用你的神器力量。"
D.Strings[107520]="选项2：对计算机发泄你的恼怒，不断用力踢它。"
D.Strings[107521]="选项1：拔掉计算机的能源线，然后再插回去。"
D.Strings[107522]="输入密码：“L0rd Meph1str0th rulez。”"
D.Strings[107523]="输入密码：“密码。”"
D.Strings[107524]="输入密码：“诸界都将化为火海。”"
D.Strings[107525]="愿命运眷顾你。库鲁尔的爪牙一定会冲出来帮忙的。"
D.Strings[107526]="在风暴峡湾要小心从事，外来者。作为斯科瓦尔德的女儿，我有许多敌人。"
D.Strings[107527]="我要步行前进了，再见，外来者。"
D.Strings[107528]="我伤得……太重了……"
D.Strings[107529]="今天，诸神青睐了我！"
D.Strings[107530]="这很冒险，但一小口就能带来必要的力量。干杯！"
D.Strings[107531]="我从没见过这么多恶魔！风暴蜜酒是我们唯一的机会。"
D.Strings[107532]="倒在我的长矛之下吧！"
D.Strings[107533]="很好。起来吧，希格林！我宣布你为蔑潮神后！"
D.Strings[107534]="我……愿意。哪怕是死，我也要统一蔑潮，将军团赶出这片土地！"
D.Strings[107535]="你愿意放下所有的疑虑，为你的人民服务吗？"
D.Strings[107536]="我现在确信我的预见是正确的了。你注定要统一蔑潮，对抗军团。"
D.Strings[107537]="你拥有能够克服邪能的力量和决心……你是第一个能做到这点的维库人！"
D.Strings[107538]="什么？！我犯下了大错，显然不适合领导人民了！"
D.Strings[107539]="我很高兴看到你恢复理智。我的审判如下：你必须担负起王者的重任，你必须成为神后！"
D.Strings[107540]="我愿意接受你的一切惩罚。"
D.Strings[107541]="伟大的艾尔。我恳请你原谅我的所作所为。"
D.Strings[107542]="原谅我，艾尔……"
D.Strings[107543]="不……邪能别想控制我……绝不！"
D.Strings[107544]="复仇无法让她复活，希格林。你的人民需要领袖。如果你失败，蔑潮就完了!"
D.Strings[107545]="可……母亲……我要为你报仇！"
D.Strings[107546]="你必须得克服腐蚀，希格林！你有这力量！"
D.Strings[107547]="我……我在做什么？这不对！"
D.Strings[107548]="很好。你选了死亡！"
D.Strings[107549]="你选吧……离开这里，或者死。"
D.Strings[107550]="什么？外来者来阻止我了？我欠你很多情，但你不能妨碍我伸张正义！"
D.Strings[107551]="你别想永远躲在高墙后面，奥丁！"
D.Strings[107552]="我能让传送门维持一小段时间。如果你想再次使用它，就得寻找额外的能量了。"
D.Strings[107553]="希格林……你干了什么？"
D.Strings[107554]="母亲！我要为你复仇！"
D.Strings[107555]="我要让奥丁看看真正的恐惧，我要当着他的面摧毁英灵殿！"
D.Strings[107556]="希格林！不！不要向黑暗沉沦！"
D.Strings[107557]="我弟弟说的对！泰坦守护者不比军团好多少！"
D.Strings[107558]="所以他下令灭绝了斯科瓦尔德家族的血脉。"
D.Strings[107559]="奥丁担心神王的继承人会将蔑潮部族卖给燃烧军团。"
D.Strings[107560]="那好吧。是奥丁亲自下令处死斯克瓦尔德的家人的。"
D.Strings[107561]="噢，孩子……真相是很残酷的。你真想知道吗？"
D.Strings[107562]="到底是谁……下令刺杀了我母亲？"
D.Strings[107563]="很好。问吧，孩子。"
D.Strings[107564]="但在成为你的女王前，我还想一个问题。"
D.Strings[107565]="伟大的艾尔，按照你的要求，我击败了蔑潮王位的争夺者。"
D.Strings[107566]="看来这是真的……魔王归来了。"
D.Strings[107567]="他已经……死了……"
D.Strings[107568]="不！弟弟！"
D.Strings[107569]="然后……你就会明白……"
D.Strings[107570]="或许你该问问他们，那夜的刺客是谁派来的……"
D.Strings[107571]="你……你觉得你的主子比我的强大……"
D.Strings[107572]="抱歉，弟弟。我不能让军团腐蚀维库人。"
D.Strings[107573]="不！我决不放弃！"
D.Strings[107574]="放弃吧，姐姐！只有邪能才能帮你打败我！"
D.Strings[107575]="可怜的姐姐……你拒绝，就是与我为敌！"
D.Strings[107576]="不，我绝不做军团的傀儡！"
D.Strings[107577]="我们的血脉天生能够抵抗它……但是它依然存在。你需要做的，只是放弃抵抗！"
D.Strings[107578]="看来你忘了父亲喂我们邪能的事。它的影响肯定蒙蔽了你的心智。"
D.Strings[107579]="哦不，托瓦德……你感染了邪能！怎么会？！"
D.Strings[107580]="你说呢？！我接受了父亲留下的礼物！你和母亲最排斥的礼物！"
D.Strings[107581]="托瓦德，是你！我不是想抛弃你，但我那时不够强大！你怎么活下来的？"
D.Strings[107582]="姐姐……还记得那个当初被你抛弃的弟弟吗？"
D.Strings[107583]="没时间了。去维克特！"
D.Strings[107584]="你听了到吗？我们最好去看看外面怎么了！"
D.Strings[107585]="德克加尔会支持你登上王位。但你还需要解决一个大麻烦。"
D.Strings[107586]="等等！你证明了自己的力量！我输了。"
D.Strings[107587]="你是奥丁的女儿也没用，丫头。我要惩罚你的傲慢！"
D.Strings[107588]="你投降吗？"
D.Strings[107589]="维尔布兰德！作为神王血脉并以艾尔之名，我要求继承蔑潮的王位！"
D.Strings[107590]="我去赫达沙尔了。回头见，$c。"
D.Strings[107591]="我输了。看来我确实低估了你，女武神。"
D.Strings[107592]="别废话了，符文先知！"
D.Strings[107593]="你有你父亲的风采，女武神，但你内心也有他的黑暗。"
D.Strings[107594]="先祖，帮帮我！"
D.Strings[107595]="神王的崽子来继承他的遗志了？斯科瓦尔德的时代结束了，你的也一样！"
D.Strings[107596]="符文先知法尔加！我是神王血脉希格林。以瓦尔基拉之名，我要挑战你！"
D.Strings[107597]="我要赶去霍斯瓦尔德。你能去那里等我吗，$n？"
D.Strings[107598]="我愿意为你所用。我该怎么做？"
D.Strings[107599]="很好。既然我对蔑潮部族如此重要，那我不会拒绝这个任务。"
D.Strings[107600]="我知道这事关重大，孩子，但你是唯一的希望。"
D.Strings[107601]="如果你失败了，蔑潮部族就会四分五裂，风暴峡湾也会落入军团之手。"
D.Strings[107602]="作为斯科瓦尔德的孩子，你有权继承他的王位。所有质疑你权威者都得俯首称臣。"
D.Strings[107603]="没错。很久之前，我预言过瓦尔基拉将与蔑潮部族并肩对抗可怕的敌人。而带领他们的将是神王与女武神的后裔。"
D.Strings[107604]="这位外来者说，我要统一蔑潮……"
D.Strings[107605]="斯科瓦尔德的血脉要重返瓦尔基拉？你明白它的意义吗，孩子？"
D.Strings[107606]="荣耀的艾尔，预言中的孩子来了！"
D.Strings[107607]="等等……那张脸……跟我来，孩子！"
D.Strings[107608]="神王的继承人！？你在胡说什么？"
D.Strings[107609]="这些女人的护甲……让我想起了我母亲……"
D.Strings[107610]="斯考德-艾希尔！小时候，我母亲提过这里和它强大的女武神。它真的很壮观！"
D.Strings[107611]="为了安全起见，我就不会说那位准神王是怎么死的。"
D.Strings[107612]="还有件事。如果这个预言中的领袖真是神王的后裔，斯科瓦尔德的死可能会引起麻烦。"
D.Strings[107613]="<控制台冰冷地矗立在你面前。发光的恶魔符文在终端表面飞舞着。>\n\n已授予权限。"
D.Strings[107614]="<控制台冰冷地矗立在你面前。发光的恶魔符文在终端表面飞舞着。>\n\n请输入密码："
D.Strings[107615]="最后一扇！快！"
D.Strings[107616]="这边！我们得打开这扇门。"
D.Strings[107617]="我到处都没找到酒仙。她逃出去了吗？"
D.Strings[107618]="这可悲的世界将亲眼目睹库鲁尔的怒火！"
D.Strings[107619]="躲？呸！你真是越老越糊涂了，先知。"
D.Strings[107620]="看来命运让我们再次走到了一起，战士。"
D.Strings[107621]="看来命运让我们再次走到了一起，术士。"
D.Strings[107622]="看来命运让我们再次走到了一起，萨满。"
D.Strings[107623]="看来命运让我们再次走到了一起，潜行者。"
D.Strings[107624]="看来命运让我们再次走到了一起，大祭司。"
D.Strings[107625]="看来命运让我们再次走到了一起，大领主。"
D.Strings[107626]="看来命运让我们再次走到了一起，武僧。"
D.Strings[107627]="看来命运让我们再次走到了一起，法师。"
D.Strings[107628]="看来命运让我们再次走到了一起，猎人。"
D.Strings[107629]="看来命运让我们再次走到了一起，德鲁伊。"
D.Strings[107630]="看来命运让我们再次走到了一起，恶魔猎手。"
D.Strings[107631]="看来命运让我们再次走到了一起，死亡骑士。"
D.Strings[107632]="干得好，英雄！你救了许多高贵的灵魂，没让它们成为邪恶魔法的燃料。"
D.Strings[107633]="军团玷污了风暴峡湾的海滩！不要放过任何一个恶魔！"
D.Strings[107634]="墨古里斯顿了顿，然后瞪着你，脸上露出疑似微笑的表情，然后迅速跑开了。"
D.Strings[107635]="你说恶魔知不知道他们喝了风暴蜜酒会怎么样？"
D.Strings[107636]="我以为这里很安全。不久前，军团还对我们一无所知。"
D.Strings[107637]="出现吧，恶魔。你躲不过圣光的眼睛！"
D.Strings[107638]="好多恶魔！"
D.Strings[107639]="我感觉远方有一股黑暗之力，就在扭曲虚空里。让我们看看屏障的另一端有些什么吧。"
D.Strings[107640]="我是来观察萨格拉斯之墓上方的虚空，寻找未知的答案的。"
D.Strings[107641]="%s彻底抽干了聚焦之虹！你失败了！"
D.Strings[107642]="库鲁尔的心脏被燃烧军团偷走了。"
D.Strings[107643]="圣光不会抛弃我们的。"
D.Strings[107644]="你成功了！我痊愈了！"
D.Strings[107645]="我预感你会来，$n。今天，你带来了不祥的兆头。"
D.Strings[107646]="墨古里斯指了指南部海滩上的恶魔建筑。"
D.Strings[107647]="我要让它们一点一点吞噬你的灵魂！"
D.Strings[107648]="怎么回事？！这些生物必须立刻准备好，不得有误！"
D.Strings[107649]="我们去平台吧，别再跟他错过了。你先走！"
D.Strings[107650]="先知维伦会花大量时间去照料伤员。我们应该从急救站找起。"
D.Strings[107651]="他去克拉苏斯平台了，嘴里还嘟囔着什么陵墓之类的。"
D.Strings[107652]="你跟先知正好错过了。"
D.Strings[107653]="就不该让法师来干恶魔猎手的活儿！"
D.Strings[107654]="唔，看来情况更糟了。试试暗影魔法吧。"
D.Strings[107655]="谢谢你！让那些恶魔看看我们的本事吧！"
D.Strings[107656]="谢谢你。我还以为这里不会成为燃烧军团的目标呢……"
D.Strings[107657]="祝福你，朋友！"
D.Strings[107658]="呼，难受死我了。谢谢你！"
D.Strings[107659]="墨古里斯先指了指一条样子丑陋的鱼，然后转头看向你。它似乎想让你对它做点什么。"
D.Strings[107660]="魔王库鲁尔的心脏……糟了。"
D.Strings[107661]="可能依然有恶魔潜伏在那里。小心点。"
D.Strings[107662]="那个野蛮人似乎非常注意保护它。他一离开金库，就马上逃之夭夭了。"
D.Strings[107663]="我只知道它看上去像某种心脏。有头绪吗？"
D.Strings[107664]="哟，我看见那个恶魔抢走了什么。快过来。"
D.Strings[107665]="我们恐怕无法马上知道情况。内层区域还被邪能火焰封锁着！"
D.Strings[107666]="我们甚至不知道自己是否安全，而你还在问金库？！只有六人议会的成员才能进去！"
D.Strings[107667]="这有什么关系？金库里收藏着我们最需要严加看守的圣物！任何一个都不容有失！"
D.Strings[107668]="真可怜！清创生血也许能帮他们。"
D.Strings[107669]="我们进去吧。"
D.Strings[107670]="大宗师$n，谢谢你这么快赶来。快帮我开门！"
D.Strings[107671]="好吧，格鲁托妮雅。燃烧军团到底在找什么？"
D.Strings[107672]="它到底拿走了什么？"
D.Strings[107673]="金库里少了什么没有？"
D.Strings[107674]="你知道被抢走的是什么东西吗？"
D.Strings[107675]="什么东西在袭击中被偷了？"
D.Strings[107676]="我要进入我的银行。"
D.Strings[107677]="但愿武僧们喜欢我的庆祝美酒！再见，大宗师。"
D.Strings[107678]="这一定会很好用的！"
D.Strings[107679]="淘气的林精显出了真身。"
D.Strings[107680]="谢谢，英雄。我们得维持和谐。这是生存的保障。"
D.Strings[107681]="还需要大量的桶来装它。这种物质很不稳定，所以普通的木材是无法胜任的。"
D.Strings[107682]="大宗师！该欢庆胜利了！"
D.Strings[107683]="大宗师$n！我和酒仙布兰琪刚刚讨论了一下破碎海滩的局势。我们该召集艾泽拉斯的各方势力一起向燃烧军团发起总攻了。"
D.Strings[107684]="我的呼吸是风暴的怒火！小家伙，告诉我该攻击哪里才能让敌人倒下！"
D.Strings[107685]="那个恶魔移动战舰去进攻勇者之门了！我派了瓦格里去协助你，英雄。我们不能输！"
D.Strings[107686]="送我去风暴烈酒酿造厂。"
D.Strings[107687]="谢谢。我在那儿等你！"
D.Strings[107688]="哦，不！我们好不容易才开始生产风暴蜜酒！"
D.Strings[107689]="大宗师！军团占领了风暴烈酒酿造厂！救救我们！"
D.Strings[107690]="准备好爪钩，死亡领主。我们去山顶。"
D.Strings[107691]="以伊利丹之名，去死吧！"
D.Strings[107692]="银行？这怎么——"
D.Strings[107693]="<玛洛恩赞许地看了你一眼。>"
D.Strings[107694]="艾斯格里姆！你要为这腐蚀付出代价，恶魔！"
D.Strings[107695]="看呐，你的宝贝勇士，瓦格里！相信这一定会是一次感人的重逢……"
D.Strings[107696]="不过……请继续垂死挣扎吧。我喜欢看你们折腾！"
D.Strings[107697]="可悲的凡人！就连你们的小瓦格里也无法让你们逃过一死……"
D.Strings[107698]="你得立刻回救赎岗哨去，$n。那里有了一些……怎么说呢……新动向。"
D.Strings[107699]="咕噜噜……"
D.Strings[107700]="多谢多谢，朋友！"
D.Strings[107701]="你休想逃避湮灭！"
D.Strings[107702]="哈！尖叫吧，挣扎吧！在临死前，对着天空愤怒哀嚎吧！"
D.Strings[107703]="这是主人的意志！"
D.Strings[107704]="血！到处都是血！"
D.Strings[107705]="难以……抗拒……"
D.Strings[107706]="怪物，到处都是怪物！"
D.Strings[107707]="先祖在对我说话！他们说你必须死！"
D.Strings[107708]="这里……不是英灵殿！"
D.Strings[107709]="奥丁的胡子在上……我在哪儿？"
D.Strings[107710]="谢谢你，陌生的小个子。"
D.Strings[107711]="我诅咒这些恶魔！"
D.Strings[107712]="那些声音……他们撒谎！他们不是先祖！"
D.Strings[107713]="跟我一起回我的法师塔吧，我们有很多事要讨论……"
D.Strings[107714]="谢谢，$n。谢谢你饶我一命。我……迷失了本性……"
D.Strings[107715]="不……魔网还是太弱……没有魔力……艾泽拉斯就会……"
D.Strings[107716]="进展顺利。现在，摧毁艾泽拉斯……"
D.Strings[107717]="现在，见证这无穷之力吧！"
D.Strings[107718]="挡住他们，英雄！为了艾泽拉斯！"
D.Strings[107719]="你别想抗拒军团的意志，大法师。都去死吧！"
D.Strings[107720]="我得将这力量还回魔网去！"
D.Strings[107721]="不……这不对！"
D.Strings[107722]="所有魔力都是我的！"
D.Strings[107723]="尝尝魔法吧，骗子！"
D.Strings[107724]="被抽干魔力后，我的恶魔主人就能占领你们的世界……我也将获得无穷的力量！"
D.Strings[107725]="你太迟了，$c！掌握了聚焦之虹，我就能直接从艾泽拉斯的魔网中抽取奥术能量来强化自身的法力！"
D.Strings[107726]="送我去破碎海滩的受难小径。"
D.Strings[107727]="看来我得亲自动手了！"
D.Strings[107728]="如果你离开这个副本，进度就将重置。你确定要离开吗？"
D.Strings[107729]="我想离开哀嚎洞穴。"
D.Strings[107730]="送我去哀嚎洞穴。"
D.Strings[107731]="哀嚎洞穴里充斥着变异的怪物。\n\n我们得在它们泛滥开来之前将其消灭。"
D.Strings[107732]="只有经过刻苦训练的人才能进去。\n\n等你把15只宠物训练到满级后，就算准备好了。"
D.Strings[107733]="我要怎么才能进去？"
D.Strings[107734]="立刻去那里见见我的仆人，强大的维瑟尔。你们要一起让军团明白，风暴峡湾是怎么欢迎恶魔的！"
D.Strings[107735]="阿苏纳的人民欠你一份情，英雄！"
D.Strings[107736]="也许吧。我能看出这个新阵地有不少好处。"
D.Strings[107737]="送我上战场吧，我准备好出一份力了。"
D.Strings[107738]="我们在与燃烧军团的战斗中已经付出了惨重的代价。许多勇敢的英雄在这场战役中牺牲。我们决不能让他们的牺牲白费。\n\n让我们把握住胜利的机会吧！"
D.Strings[107739]="我会搞定这里的。回头见，$n。"
D.Strings[107740]="唔。真是刚出虎穴又入狼窝啊。好吧，至少这里的地形更适合对抗军团。"
D.Strings[107741]="让我们看看自己的表现如何吧，好吧？"
D.Strings[107742]="诺达尼尔圣泉被燃烧军团占领了！消灭侵略军，绝不能让阿苏纳彻底陷落！"
D.Strings[107743]="再次感谢你，你见到肯瑞托的人时，请代我向他们问好！"
D.Strings[107744]="要想清除这些叛徒，我们还有大量工作要做。但多亏你的努力，这要不了多少时间！"
D.Strings[107745]="我们已经夺回了大部分关键系统的控制权——包括传送网络。它能将你安全地送回达拉然！"
D.Strings[107746]="你成功了！这是希科·瑟玛普拉格最后一次把他的丑脑袋伸进我们的城市了。"
D.Strings[107747]="噢，不，你不能！我是有备而来的！"
D.Strings[107748]="把所有人都派上去。全部！保护我，你们这些蠢货！"
D.Strings[107749]="好极了！传感器显示瑟玛普拉格退回了下层的工匠议会。你必须彻底解决他！"
D.Strings[107750]="不！！！我的导弹！"
D.Strings[107751]="坐下，放轻松！从数学的角度来说，你现在什么都做不了，只能痛苦地死去。"
D.Strings[107752]="嘀嗒，嘀嗒。我们马上就能发射了！"
D.Strings[107753]="他们在这儿。"
D.Strings[107754]="以大机械师的名义，站住！"
D.Strings[107755]="准备应战。"
D.Strings[107756]="我看到他们了。"
D.Strings[107757]="邻近路线发现入侵者。"
D.Strings[107758]="附近存在服从等级较低的实体。正在确认源头。"
D.Strings[107759]="威胁传感器触发。"
D.Strings[107760]="发现敌人。启动战斗继电器。"
D.Strings[107761]="附近发现未经授权的实体。"
D.Strings[107762]="我们控制住了这次意外的入侵。请去看看先知阿卡鲁好吗，屠魔者$n？"
D.Strings[107763]="该区域发现入侵者。"
D.Strings[107764]="贪婪的轮齿看向你的方向！"
D.Strings[107765]="你休想活着出去。"
D.Strings[107766]="你的脑袋将成为这些殿堂里的装饰品！"
D.Strings[107767]="谁敢踏入瑟玛普拉格的领地？"
D.Strings[107768]="这里有外人。"
D.Strings[107769]="附近有人。"
D.Strings[107770]="以瑟玛普拉格之名，出来吧！"
D.Strings[107771]="出来，让我杀了你！"
D.Strings[107772]="我看见什么东西了！"
D.Strings[107773]="穴居人不蠢！"
D.Strings[107774]="不可能！我的计算是……完美的……"
D.Strings[107775]="没关系。一切都很好，很完美！只要杀了你，再敲平你造成的这些难看的凹痕，我们就能消灭你所有的宝贝朋友了。"
D.Strings[107776]="拜托，拜托，那个该死的引爆按钮呢？我记得我装过引爆按钮的！"
D.Strings[107777]="想想吧，你将孤零零一个人死在这下面。就像多年前，我被丢在这里等死时一样。"
D.Strings[107778]="你得再加把劲儿，尊敬的英雄。我可是全艾泽拉斯最伟大的发明家！"
D.Strings[107779]="见识一下盟友给予我的力量吧。我——大机械师瑟玛普拉格，将是你的送葬者！"
D.Strings[107780]="我应该恭喜你，英雄，可我担心你的努力是徒劳的。我会制造一枚新导弹，而这一次，你别想再阻止我了！"
D.Strings[107781]="他……来了……"
D.Strings[107782]="这怎么可能？你一无是处！"
D.Strings[107783]="你的世界，所有世界，都将燃烧！这是你们的命运！"
D.Strings[107784]="你比我想的要强大。但没关系。"
D.Strings[107785]="没希望了。我们无处不在。我们是燃烧军团！"
D.Strings[107786]="你太迟了，凡人。艾泽拉斯死定了。"
D.Strings[107787]="你做得很好，小侏儒。很快，就没有人能阻挡燃烧军团的力量了！"
D.Strings[107788]="武器受损严重。如果现在激活它们，我们也会完蛋……或许能把主引擎核心里的能量转出来……"
D.Strings[107789]="欢迎加入，多米尔！跳上去吧，死亡领主，该回阿彻鲁斯了。"
D.Strings[107790]="我们坚持不了多久。必须摧毁那些船！"
D.Strings[107791]="刚才好险啊！感谢你的帮助。我担心控制室里的杰斯可能遇到了麻烦！"
D.Strings[107792]="马顿失守了。我总算解脱了。但如果邪能之槌号也丢了，那就不太方便了。"
D.Strings[107793]="屠魔者$n，很高兴看到你回来！看来他们这次要来真的了！"
D.Strings[107794]="又是恶魔……虽然我希望船上能多点刺激，但这可不是我想要的。"
D.Strings[107795]="该去提醒那些恶魔了，邪能之槌号是我们的！"
D.Strings[107796]="别以为就你一个人，死亡领主。前进！"
D.Strings[107797]="主母玛沃伦丝恶毒地看了考瓦斯一眼。"
D.Strings[107798]="来吧，主母！"
D.Strings[107799]="发现卫兵！"
D.Strings[107800]="他的拳头……也很硬！"
D.Strings[107801]="恶心的恶魔！"
D.Strings[107802]="你们要为囚禁我付出代价，畜生！"
D.Strings[107803]="屠魔者$n，帮帮我！"
D.Strings[107804]="净化……暂时完成了。保持警惕，燃烧军团不会善罢甘休的。"
D.Strings[107805]="罗兰·阿博纳斯干咳了一声。"
D.Strings[107806]="我们不会坐视燃烧军团亵渎我们的土地。保卫法隆戴尔！"
D.Strings[107807]="屠魔者$n，我们需要你那锋利的战刃来挡住这些恶魔！"
D.Strings[107808]="小偷！这是我的船！"
D.Strings[107809]="那是我的宝藏！"
D.Strings[107810]="感谢你能这么快赶来，屠魔者$n！"
D.Strings[107811]="屠魔者$n，一群恶魔登上了邪能之槌号！请你立刻前去支援！"
D.Strings[107812]="深渊猎犬发出了可怕的咆哮。"
D.Strings[107813]="深渊猎犬感觉附近有什么东西。"
D.Strings[107814]="深渊猎犬在空气中嗅着什么。"
D.Strings[107815]="他们不断涌来……"
D.Strings[107816]="我还以为自己撑不下去了。谢谢，$n！"
D.Strings[107817]="刚才好险啊。谢谢！"
D.Strings[107818]="我终于自由了？"
D.Strings[107819]="我们会找到他们的。赛丝诺女士呢？"
D.Strings[107820]="考瓦斯！屠魔者！之前都没事。但军团的传送门突然出现，然后咱们就得拼命了！大部分斥候都失踪了。"
D.Strings[107821]="凡德尔，我们来帮你了。出什么事了？"
D.Strings[107822]="将魔能机甲骗到地雷上方以将其摧毁！"
D.Strings[107823]="绿色篮球回到了基地！"
D.Strings[107824]="紫色篮球回到了基地！"
D.Strings[107825]="橙色篮球回到了基地！"
D.Strings[107826]="$n丢掉了绿色篮球！"
D.Strings[107827]="$n丢掉了紫色篮球！"
D.Strings[107828]="$n丢掉了橙色篮球！"
D.Strings[107829]="得分！$n打进了绿色篮球。"
D.Strings[107830]="得分！$n打进了紫色篮球。"
D.Strings[107831]="得分！$n打进了橙色篮球。"
D.Strings[107832]="$n拿到了紫色篮球！"
D.Strings[107833]="$n拿到了橙色篮球！"
D.Strings[107834]="$n拿到了绿色篮球！"
D.Strings[107835]="干得好！感谢你的帮助，燃烧军团休想占领这片土地！"
D.Strings[107836]="送我去地表。"
D.Strings[107837]="送我去马顿。"
D.Strings[107838]="接下来就看你的了。我会在远处盯着你。"
D.Strings[107839]="不用跳——我们的魔蝠很乐意活动一下翅膀！"
D.Strings[107840]="我准备好了。我们回去吧，卡雷。"
D.Strings[107841]="你成功了，大法师$n。我已经准备好了庆祝活动，但我想在职业大厅里当着大家的面举办。$b$b你准备好之后，我就把我俩送回去。"
D.Strings[107842]="伊利达雷！马顿需要我们。出发！"
D.Strings[107843]="你听到从塔楼废墟传来的轰鸣声了吗？这绝对是个坏兆头。小心点！"
D.Strings[107844]="愚蠢的凡人！你大难临头了！"
D.Strings[107845]="魔典对他的控制又加深了。他已经疯狂错乱了。"
D.Strings[107846]="屠魔者$n！我们在马顿的斥候送来了紧急消息！"
D.Strings[107847]="稳住！这里要塌了！"
D.Strings[107848]="现在，我们要发射了！！！"
D.Strings[107849]="小心点，$c。恐怕他不会热情欢迎你的。"
D.Strings[107850]="你就这点本事吗？其实艾瑞达并不以剑术闻名，对吧？"
D.Strings[107851]="多么迟缓无力的攻击。真可悲。"
D.Strings[107852]="噢！真是闪闪发亮！你要把它给我？"
D.Strings[107853]="你有发现了吗？有魔法物品吗？嘿！告诉我吧！"
D.Strings[107854]="嘿！你找到什么好东西没有？！"
D.Strings[107855]="我们遭到了袭击，损失惨重。到处都是燃烧军团的传送门！我们需要援军！"
D.Strings[107856]="赛丝诺女士几个小时前下去帮忙了，但这似乎很严重。我们要跟她去吗？"
D.Strings[107857]="屠魔者$n！我们刚刚收到了贝拉斯留在马顿的斥候传来的紧急消息！"
D.Strings[107858]="我的新盟友给了我超乎想象的礼物——你派你们的救世主独自前来无异于送死。"
D.Strings[107859]="你真是越老越糊涂了，格尔宾。"
D.Strings[107860]="不！裂隙要关闭了！"
D.Strings[107861]="莱维娅……对，我认识她。她经常来光顾，最近一次就是几天前。\n\n暗影魔法很危险——所以肯瑞托不喜欢有人在城里研究那种东西——但她搞的那些东西比你平时见识过的那些还要糟糕。但愿她起码能到城外去搞研究。\n\n你可以到楼上去看看她有没有留下什么东西。"
D.Strings[107862]="希望你喜欢我的造物，兄弟。可惜还是要这样……"
D.Strings[107863]="秘法会的宝库里收藏了大量魔法物品。这里面肯定有达拉然用得上的……"
D.Strings[107864]="你知道莱维娅·劳伦斯吗？"
D.Strings[107865]="你的小脑瓜根本不明白我将掌握怎样的力量！或许我该让你尝尝我的厉害……"
D.Strings[107866]="求求你，兄弟！不要屈服于黑暗！"
D.Strings[107867]="愚蠢的兄弟，你太迟了。扭曲虚空和无尽的力量在等着我！等我归来时，世界都将臣服于我！"
D.Strings[107868]="别再发疯了，兄弟！你还有救！"
D.Strings[107869]="当然，当然。莱维娅嘛。那个高个子姑娘？浅色头发那个？她来买过卷轴和墨水，说她需要制作什么仪式符文之类的。\n\n她提到过她需要某种特殊的法杖，但我们这里可不卖那种东西。我让她去好战的秘法师那儿看看了。\n\n或许你该去那里找找？"
D.Strings[107870]="%s开始激活！"
D.Strings[107871]="我不会就此放弃的！"
D.Strings[107872]="你的审判毫无价值！"
D.Strings[107873]="你的审判毫无价值！燃烧军团会毁灭白银之手的！"
D.Strings[107874]="我尊重你的审判，大领主。我迟早会证明自己的。"
D.Strings[107875]="你不会为自己的选择后悔的。"
D.Strings[107876]="我宣誓效忠白银之手。"
D.Strings[107877]="我很荣幸能为你效劳，大领主。"
D.Strings[107878]="结界失效了！干掉这些邪恶的邪教徒吧！"
D.Strings[107879]="骑士们，拿起武器！让我们剿灭这些残兵败将！"
D.Strings[107880]="我去侦察一下，看看能发现什么。到破碎海滩来找我吧，$n！"
D.Strings[107881]="遵命，大工匠！立刻关闭屏障。"
D.Strings[107882]="闪簧队长，请暂时关闭屏障。"
D.Strings[107883]="大人……我辜负了你……"
D.Strings[107884]="这是虚空之誓的仁慈！"
D.Strings[107885]="蠢货……你们真以为能轻松逃跑吗？"
D.Strings[107886]="大法师，用你的力量说服这两个家伙合而为一吧！"
D.Strings[107887]="这一天，我已经等了一万年了！"
D.Strings[107888]="我们绝不向燃烧军团投降！"
D.Strings[107889]="我的死……改变不了什么……"
D.Strings[107890]="我的兄弟们会了结你的……"
D.Strings[107891]="你休想阻止暗影……"
D.Strings[107892]="回头吧……趁你还有机会……"
D.Strings[107893]="把奥术炸弹放进传送门里摧毁它们。一旦传送门关闭，我们就开始清理这些入侵者！"
D.Strings[107894]="恶魔正从荒废圣殿的传送门里涌出。我的守夜人很快就会被击溃的！"
D.Strings[107895]="你的骚扰到此为止了！"
D.Strings[107896]="这里不欢迎你，入侵者！"
D.Strings[107897]="你会闭上嘴的！"
D.Strings[107898]="你的刺探到此为止了！"
D.Strings[107899]="暗影……在召唤……"
D.Strings[107900]="你赢不了的……"
D.Strings[107901]="万物都将……消亡……"
D.Strings[107902]="虚空之誓……为我复仇……"
D.Strings[107903]="你的世界完了！"
D.Strings[107904]="万物都将臣服于虚空之誓！"
D.Strings[107905]="我干嘛要帮你？我犯不着为你冒险！"
D.Strings[107906]="我们就全指望你了！你愿意做吗？"
D.Strings[107907]="我们不能继续冒险待援了。已经没时间了。"
D.Strings[107908]="聪明的推断，非常聪明，但你恐怕已经太迟了。我们马上就能用辐射关照你们在破碎海滩上的宝贝小卫兵了！"
D.Strings[107909]="长官，我们有理由相信，瑟玛普拉格就是幕后黑手。而且他还掌握了某种导弹武器！"
D.Strings[107910]="这将开启一个限时事件。你确定吗？"
D.Strings[107911]="我们不会让诺莫瑞根再次陷落的。"
D.Strings[107912]="真厉害！触摸那块灵魂碎片的大部分凡人都会死掉的。"
D.Strings[107913]="我发誓，我就知道这么多！"
D.Strings[107914]="他们中有个人给了我这张羊皮纸。拿去吧，我可不想跟邪教扯上关系！"
D.Strings[107915]="你别想发现我们的秘密！"
D.Strings[107916]="我什么都不知道！别来烦我！"
D.Strings[107917]="带路吧，我们去下水道，$n。但愿还不迟。"
D.Strings[107918]="大法师$n，我们有客人。请来我的房间找我。"
D.Strings[107919]="暗影将……吞噬一切……"
D.Strings[107920]="谁都别想阻止虚空之誓的归来！"
D.Strings[107921]="愚蠢的凡人！这次软弱无力的进攻只会像上次一样失败……而这次，你们将无路可逃！"
D.Strings[107922]="逼退他们！他们休想获胜！"
D.Strings[107923]="愚蠢的凡人！你竟敢放跑我们的俘虏？那你就来代替他们吧！"
D.Strings[107924]="如果传送器的燃料耗尽，我们就需要一把|Hitem:143653:0:0:0:0:0:0:0:90:0|h[能量充沛的钥石]|h来启动它。你准备好了就站上去吧！"
D.Strings[107925]="克希雷姆激活了聚焦之虹！"
D.Strings[107926]="我会把你送进城市深处。衰减器里的燃料只够传送一次，所以我们决不能空手而归！"
D.Strings[107927]="校准高压缓冲器……调整微型加速器……"
D.Strings[107928]="我们得立刻送你去诺莫瑞根！"
D.Strings[107929]="我就知道你们靠得住。如果部落再次被逐出肯瑞托，并与联盟各自为战的话，燃烧军团就会吞噬我们的世界。"
D.Strings[107930]="只有你们和我最信赖的副手。但我隐瞒不了多久。"
D.Strings[107931]="我来召唤传送门。我们另一边见，大法师$n！"
D.Strings[107932]="小心，英雄！来了一个末日领主！"
D.Strings[107933]="终端状态：未保护。正在关闭。"
D.Strings[107934]="守住阵线！屠魔者到了！"
D.Strings[107935]="守住阵线！大德鲁伊到了！"
D.Strings[107936]="守住阵线！大宗师到了！"
D.Strings[107937]="守住阵线！虚空领主到了！"
D.Strings[107938]="守住阵线！大法师到了！"
D.Strings[107939]="守住阵线！先知到了！"
D.Strings[107940]="守住阵线！死亡领主到了！"
D.Strings[107941]="守住阵线！大祭司到了！"
D.Strings[107942]="守住阵线！暗影之刃到了！"
D.Strings[107943]="守住阵线！狩猎大师到了！"
D.Strings[107944]="守住阵线！大领主到了！"
D.Strings[107945]="守住阵线！战争领主到了！"
D.Strings[107946]="你——什么？！"
D.Strings[107947]="跟我做生意的人多了去了，凯尔希。我为什么要了解某个诺莫瑞根闲汉的情况？"
D.Strings[107948]="正在激活3B终端保护模块。"
D.Strings[107949]="系统状态：启动中。"
D.Strings[107950]="啊，没错！艾泽拉斯的力量归我了！"
D.Strings[107951]="我和大法师$n会想办法修好达拉然的武器的。我们一定要做到！"
D.Strings[107952]="如果这个消息泄露出去，停战协议就会破裂的。还有谁知道这事？"
D.Strings[107953]="噢，情况很糟。叛徒是部落的人……"
D.Strings[107954]="一根细细的电线搭在卡片上，绷得紧紧的！"
D.Strings[107955]="祝你好运，伙计。塔纳利斯的沙漠是位严酷的女神！"
D.Strings[107956]="战争领主$n，我们很多事要讨论！别再浪费时间了。"
D.Strings[107957]="让我们搁置那些微不足道的口角，继续攻击燃烧军团吧！我们得团结艾泽拉斯的所有主要势力！"
D.Strings[107958]="很好。做好准备，然后尽快赶来破碎海滩吧。"
D.Strings[107959]="我们还能将克瓦迪尔派上前线。他们死不足惜，就让他们去对付军团好了。"
D.Strings[107960]="战争领主！邪恶的海拉终于被击败了。她无法再阻止我夺回属于我的东西了！"
D.Strings[107961]="无法……抵抗！"
D.Strings[107962]="这是主人的命令！"
D.Strings[107963]="要不是被海拉掠走，他们早就成为瓦拉加尔了。现在，见证他们的转变吧！"
D.Strings[107964]="很好，战争领主$n。你找回了我迷失的战士！"
D.Strings[107965]="我把那套瞄准系统卖给了“那个”希科·瑟玛普拉格？噢，天呐。"
D.Strings[107966]="<把你在瑟玛普拉格营地里找到的线索告诉穆克斯。>"
D.Strings[107967]="引力将在15秒后消失！"
D.Strings[107968]="噢，对了，我还忘了说。这个终端马——上就要自毁了。再见！"
D.Strings[107969]="当然，前提是你要能熬过破碎海滩的大规模辐射，以及稍后燃烧军团对你所熟悉、珍爱的一切的伟大清洗。"
D.Strings[107970]="如果你听到了这段留言，那意味着你将受到独家邀请，见证我加冕为全艾泽拉斯所有凡人之王的光辉时刻！"
D.Strings[107971]="你好，地表居民！我，是唯一的、独一无二的大机械师瑟玛普拉格！"
D.Strings[107972]="小心地取出打孔卡。"
D.Strings[107973]="不不不不，啊啊！！！"
D.Strings[107974]="噢，我真的要生气啦！"
D.Strings[107975]="哎哟！噢，要来阴的是吧？好吧，来试试打断这个吧！"
D.Strings[107976]="<这肯定就是格朗克斯的助手的遗体了。>$B$B<你注意到灰烬中有什么东西戳了出来。这肯定是她想要归还的那张打孔卡！>"
D.Strings[107977]="<你以前在燃烧军团手中见过这种书籍。显然，六人议会对于有军团密探参与其中的担忧是道理的。>"
D.Strings[107978]="<这种机器通常在工程学商店中作为主要的辅助设备来使用。而这架直升机显然已经风光不再了。>"
D.Strings[107979]="插入打孔卡。"
D.Strings[107980]="<这台闲置中的机器发出了有节奏的滴答声。>"
D.Strings[107981]="<你注意到这个设备正面有一个插槽，可能就是用来插穆克斯所说的那张打孔卡的。>$B$B<要是能找到那张卡片就好了……>"
D.Strings[107982]="维库人要为此付出代价。以巫妖王之名，把他们变成亡灵！"
D.Strings[107983]="你要去寻找霜牙的挽具，但现在已经迟了。它落到了入侵的维库人之手。他们在用它驯养冰霜巨龙。"
D.Strings[107984]="在你的指挥下，天启四骑士给恶魔带去了浩劫。但现在，另一条力量之路在等着你。"
D.Strings[107985]="你对军团的抵抗卓有成效，死亡领主。我很满意。"
D.Strings[107986]="我要回恐痕裂隙，把我们的计划告诉其他议会成员。"
D.Strings[107987]="那好吧，我觉得这家伙已经没用了，你说呢？"
D.Strings[107988]="我们得到前头侦察一下。战场见，死亡领主！"
D.Strings[107989]="哈！他们毫无机会。"
D.Strings[107990]="他们的死亡就是我们的救赎。"
D.Strings[107991]="燃烧军团毫无廉耻。他们必将走向灭亡。"
D.Strings[107992]="干得好，英雄！我们的联盟绝对不会让燃烧军团夺走阿苏纳！"
D.Strings[107993]="他是你的前任，虚空领主。坎雷萨德是议会的创始人。\n\n他将我们团结到一起，并对我们一视同仁，带领我们追寻超乎想象的强大力量。\n\n但他对力量的渴望永无止尽。伊利丹战死在黑暗神殿后，坎雷萨德就迷上了他在那里见识到的力量。他想像伊利丹一样控制恶魔能量，并准备不惜一切代价做到这一点。\n\n我曾对坎雷萨德发过誓，一旦他迷失在那种力量里，我就会放逐他。为了他，也为了所有人，我必须遵守誓言。"
D.Strings[107994]="再次骑上多米尔吧，死亡领主。带领我们踏上战场。"
D.Strings[107995]="坎雷萨德是谁？"
D.Strings[107996]="我们必须不惜一切代价，继续放逐坎雷萨德。"
D.Strings[107997]="现在加入我们还来得及……"
D.Strings[107998]="你的力量根本比不上他！"
D.Strings[107999]="邪能之火会吞噬你的！"
D.Strings[108000]="黑暗收割议会的真正领袖必将再次崛起！"
D.Strings[108001]="坎雷萨德，赐予我力量吧！"
D.Strings[108002]="我们的领袖会回来的！"
D.Strings[108003]="我们不会罢休的！"
D.Strings[108004]="我让你失望了，坎雷萨德！"
D.Strings[108005]="我不会白白牺牲的！"
D.Strings[108006]="很快，坎雷萨德就会再次加入我们！"
D.Strings[108007]="你太迟了！仪式就要完成了。"
D.Strings[108008]="燃烧军团正在吸取巨龙盟友的魔力。你得救他们！"
D.Strings[108009]="我相信那个善良的大法师克希雷姆仍然潜藏在那个疯子的内心深处。"
D.Strings[108010]="我还有最后一个要求，$c。虽然克希雷姆可能不会留手，但请你饶他一命。"
D.Strings[108011]="我们或许能用它找到克希雷姆，不过这需要时间。"
D.Strings[108012]="这传送门很不稳定，但还有余波。"
D.Strings[108013]="你得跟着他穿过传送门。去吧！否则就迟了！"
D.Strings[108014]="看来魔典像侵蚀克希雷姆一样侵蚀了我……现在，他带着聚焦之虹跑了！"
D.Strings[108015]="够了！放下武器……"
D.Strings[108016]="你太迟了！学徒萨纳斯，解决这个跟踪者！"
D.Strings[108017]="说实话，你挺强的，对吧？但是好好想想吧，别来阻止我！"
D.Strings[108018]="聚焦之虹会让我成为史上最强大的法师！来阻止我看看吧！"
D.Strings[108019]="克希雷姆……你干了什么？"
D.Strings[108020]="暗影……消失了？"
D.Strings[108021]="暗影……吞噬了我……"
D.Strings[108022]="我……差点就死了……"
D.Strings[108023]="我……我这是在哪儿？"
D.Strings[108024]="你得训练得再刻苦一点！"
D.Strings[108025]="不不不！你的架势完全错了！"
D.Strings[108026]="靠这样的动作，你永远别想击败燃烧军团！"
D.Strings[108027]="我的弟子……攻击！"
D.Strings[108028]="等等……你不是真正的学徒！我要杀了你，骗子！"
D.Strings[108029]="小心点。错误的答案会损害你的健康。我是认真的！"
D.Strings[108030]="了不起的尝试……但从头到尾，完全、彻底错了！"
D.Strings[108031]="你想……用暴力打开屏障？我可没这么教过你！"
D.Strings[108032]="顺序很重要，学徒！或许你该再看看笔记。"
D.Strings[108033]="住手好吗？！你闯大祸了！"
D.Strings[108034]="那一定很疼。"
D.Strings[108035]="不，不！不是那个！"
D.Strings[108036]="拜托，总有人来找死，我还怎么集中精神？"
D.Strings[108037]="你们这些饭桶到底出过海没有？！"
D.Strings[108038]="回去干活儿，食人魔！我们付钱是让你干什么的？"
D.Strings[108039]="别再说废话了，否则我就让你去走跳板！"
D.Strings[108040]="我觉得它应该和克希雷姆教导学徒的顺序有关。\n\n但我才开始学习奥术魔法，所以我也不知道接下来的顺序是什么。"
D.Strings[108041]="呃，你好。我能帮你什么吗？"
D.Strings[108042]="我？我对此毫无头绪。你别听威克斯的就对了。\n\n那个变态就喜欢看学徒被那道机关谜题烧得焦头烂额。"
D.Strings[108043]="不管你做什么，都别碰那些宝石，除非你知道正确的顺序。\n\n我见过搞错顺序的家伙的下场，那可是非常不妙的。"
D.Strings[108044]="噢，那个东西。\n\n好吧，我会把我知道的都告诉你——第一块宝石绝对是代表火焰的那块……\n\n<威克斯对自己轻笑了起来。>"
D.Strings[108045]="你来烦我干嘛？\n\n你以为有了这身漂亮袍子，就能来对我们指手画脚了吗？"
D.Strings[108046]="你想通过屏障？那你祝好运吧，伙计。\n\n记住，不要重复触摸任何一块水晶，明白吗？那样的话，你会遇到大麻烦的。"
D.Strings[108047]="我整天训练，希望大法师能注意到我。可直到现在，我都一事无成！\n\n我在怀疑，他到底还打不打算收学徒了……"
D.Strings[108048]="有个学徒很肯定地告诉过我，正确的顺序就是从右到左。\n\n我记得他是叫……亨里克？"
D.Strings[108049]="我很确信，只要我努力学习，克希雷姆一定会让我进塔的。\n\n如果我能弄到一顶像你这么漂亮的帽子，也会有些正面的作用。"
D.Strings[108050]="我曾经见一个学徒进去过，但我只看到他先激活了白色宝石，然后才是红色宝石。"
D.Strings[108051]="我以前也有一件像你这么漂亮的衣服，但我受够了被其他学徒挑战的日子。\n\n我相信，凭我出色的施法能力，克希雷姆一定会让我进塔的！"
D.Strings[108052]="一个亲传弟子曾经告诉过我：“你必须先精通传统学派，然后才能深入暗影的领域。”\n\n我觉得那是一种暗示。"
D.Strings[108053]="你知道那个屏障谜题的线索吗？"
D.Strings[108054]="对，克希雷姆是有点疯，但他仍然是位声名远播的大法师！想想我能从他那里学到些什么吧！"
D.Strings[108055]="挑战？很好，但你最好小心点。克希雷姆指导过我的冰霜法术。"
D.Strings[108056]="这帽子怎么看都那么蠢……"
D.Strings[108057]="好了，天呐！拿去吧！"
D.Strings[108058]="我要为了那顶帽子挑战你！"
D.Strings[108059]="先是那些愚蠢的试炼，现在他又让我来挖这个满是尘土的废墟。但愿这个亲传弟子的名额能够物有所值。\n\n什么？你，快走开。我正在……考古呢……"
D.Strings[108060]="嘿，大德鲁伊！这边！"
D.Strings[108061]="嘿，$r！你在找什么东西吗？"
D.Strings[108062]="燃烧军团肯定想利用梦魇的凋零之力。我可能是他们的第一个目标，但却绝不会是最后一个。我们得找到并击败那个带头攻击我们的人民的家伙。"
D.Strings[108063]="我们会解决这个麻烦的。"
D.Strings[108064]="燃烧军团想腐蚀我？$b$b那位人类国王的死让我感到迷惘。由于他的勇猛，我选择了他作为我的勇士，可他靠自身的能力克服了嗜血的欲望，从而伸张信念、保护人民。他死后，我进入了翡翠梦境进行反省。$b$b燃烧军团肯定是在那时发现了我。"
D.Strings[108065]="你差点被燃烧军团腐蚀了。"
D.Strings[108066]="我感觉……有点不舒服。出什么事了？"
D.Strings[108067]="祝你被克希雷姆变成蟑螂……"
D.Strings[108068]="住手！够了！拿走这件愚蠢的长袍吧！"
D.Strings[108069]="你以为你能战胜我？！好吧，那要是遇上五个我呢？！"
D.Strings[108070]="我，呃，需要你的长袍……"
D.Strings[108071]="看来那些地精已经把这座废墟搜刮一空了。\n\n按照这个速度，我就别想找到能让大法师看重的东西了！"
D.Strings[108072]="现在，别来烦我了。"
D.Strings[108073]="够了。你比我强。拿着这个护肩吧……"
D.Strings[108074]="做好准备吧！"
D.Strings[108075]="噢，你选错地精了，伙计。现在是火球时间！"
D.Strings[108076]="我需要那个护肩。"
D.Strings[108077]="这座塔已经荒废了几百年了，里面一定锁着无数奇迹。\n\n这份宝藏一定能让克希雷姆刮目相看，而他也会让我成为他的亲传弟子。现在，要是我能打开这扇门……"
D.Strings[108078]="这片土地在军团手中饱受折磨。你的行动让它恢复了一丝安宁。"
D.Strings[108079]="军团的腐蚀已经扩散到了瓦尔莎拉之心！我们的卫兵需要你的帮忙，才有希望打败恶魔。"
D.Strings[108080]="把那些恶魔送回地狱去！开火！"
D.Strings[108081]="锁定目标！连续射击！"
D.Strings[108082]="所有火炮，向目标开火！"
D.Strings[108083]="炮火准备……发射！"
D.Strings[108084]="过去的一万年中，我从来没有想到过军团会有一天来到这片林地的门口。\n\n不管怎样，我绝不会允许他们踏进林地一步！"
D.Strings[108085]="我会永远感谢你的！"
D.Strings[108086]="赞美你，英雄！"
D.Strings[108087]="啊，这下好多了。谢谢你！"
D.Strings[108088]="只……只不过是皮外伤！我还可以……噢！别介意，我会回到防线上去的。"
D.Strings[108089]="我欠你一条命！我会回到防线上去的。"
D.Strings[108090]="谢谢你……我这就回去防守。"
D.Strings[108091]="我和我的追随者与你同在，大德鲁伊。平衡必须得到恢复！"
D.Strings[108092]="最大的考验就要来临了。你必须……彻底净化燃烧军团对艾泽拉斯的腐蚀。"
D.Strings[108093]="大德鲁伊，我见证了你克服每一个试炼，实力稳步增长的过程。"
D.Strings[108094]="你已经为这场战争付出了许多，勇士。但这恐怕还不够。"
D.Strings[108095]="战争领主，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108096]="虚空领主，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108097]="先知，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108098]="暗影之刃，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108099]="大祭司，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108100]="大领主，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108101]="大宗师，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108102]="大法师，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108103]="狩猎大师，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108104]="大德鲁伊，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108105]="屠魔者，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108106]="死亡领主，你再次为艾泽拉斯的未来而战了。我代表议会感谢你。"
D.Strings[108107]="目标来了，小伙子们！开火！"
D.Strings[108108]="嘿，目标在那儿！火炮……开火！"
D.Strings[108109]="巨熊的力量与你同在。我们会成为你可靠的守护者。绝不容忍失败。"
D.Strings[108110]="大德鲁伊……毫无疑问，你已经向我证明了你的力量。我会骄傲地与你并肩作战，对抗燃烧军团。"
D.Strings[108111]="后退，举起武器。我们要给它灌注一部分议会的力量。"
D.Strings[108112]="一起来，我们大家都得出力。"
D.Strings[108113]="力量显现：Kirin'var torel，ahm shalar, azakim！"
D.Strings[108114]="现在，该集中精神将他们赶出艾泽拉斯了。我们要不惜任何代价，彻底结束这一切！"
D.Strings[108115]="军团想利用它破坏我们在萨格拉斯之墓的行动。多亏你的努力，他们失败了。"
D.Strings[108116]="还……没……完……"
D.Strings[108117]="迟了，凡人！等解决了你们，这世界就将燃烧！"
D.Strings[108118]="我并不喜欢部落，但他们的士兵与我们一同浴血抗击了恶魔。$b$b要不是他们的英勇与配合，我们都活不到现在。"
D.Strings[108119]="在杀光所有的恶魔，为每一个倒下的部落战士复仇前，我是不会离开这座岛的！"
D.Strings[108120]="不付出巨大的牺牲，是不可能打败燃烧军团的。伊利丹大人对此深有体会。"
D.Strings[108121]="可能是吧，但我对我们的指挥官有信心。他们会指引我们走向胜利的！"
D.Strings[108122]="军团的军力似乎每天都在增强。"
D.Strings[108123]="天空变得昏暗了。我们必须加快速度。"
D.Strings[108124]="我准备好了。把我送到城墙上去！"
D.Strings[108125]="这里的空气太潮湿了，想要长时间飞行是非常困难的事，不过我发明了一种粉尘，可以让我们延长展翅的时间，至少足够完成突袭。\n\n等你渗透进营地，只要发出信号，我们就会开始行动。"
D.Strings[108126]="我准备了一种粉尘，可以让我的德鲁伊们在这种潮湿的空气中飞上一小段时间。\n\n到营地去吧，只要你发出命令，我们就会开始掩护行动。"
D.Strings[108127]="你不能直接问一个术士为什么要打恶魔！"
D.Strings[108128]="那么……既然你是个术士……为什么还要打恶魔？"
D.Strings[108129]="如你所愿，战争领主。你准备好离开了吗？"
D.Strings[108130]="所有人都去海滩！军团的攻势简直连绵不绝！"
D.Strings[108131]="我们要前往冥狱深渊。"
D.Strings[108132]="我和我的部队会跟随你前往破碎海滩。我们要把燃烧军团从这个世界上冲走！"
D.Strings[108133]="我得承认，先知，我对你的成就感到惊讶。"
D.Strings[108134]="后会有期，士兵。"
D.Strings[108135]="别担心我。我会自己离开的……"
D.Strings[108136]="不把这些小眼睛的恶魔都揍死在这块该死的石头上，我就不休息……"
D.Strings[108137]="看来我得自己动手了……"
D.Strings[108138]="那些混账恶魔偷了我的装备……"
D.Strings[108139]="……你还在等什么？我们还有恶魔要杀呢。"
D.Strings[108140]="耐普图隆，先知请求你的帮助！"
D.Strings[108141]="也该有人来了。我都开始无聊了……"
D.Strings[108142]="我想了解一下你从军团密探那里得到的信息。"
D.Strings[108143]="听候你的吩咐，先知。"
D.Strings[108144]="我的岩石战士会将燃烧军团打得粉身碎骨的！"
D.Strings[108145]="深岩之洲的大军已准备就绪了，肉人。"
D.Strings[108146]="石母……先知在召唤。"
D.Strings[108147]="你需要大地为你做什么？"
D.Strings[108148]="天空之墙的大军已经集结起来了。风会助你一臂之力的。"
D.Strings[108149]="我听到了风中的低语。进攻燃烧军团的时候到了。"
D.Strings[108150]="桑德兰，先知要见你！"
D.Strings[108151]="风关注着你。"
D.Strings[108152]="我的研究……要给我陪葬……"
D.Strings[108153]="你怎么进来的？我的研究是绝密！"
D.Strings[108154]="很快，燃烧军团就会明白燃烧到底是什么滋味了。"
D.Strings[108155]="我们得靠你帮忙猎杀这些目标。现在你是唯一有可能阻止他们的人。"
D.Strings[108156]="如果让这些恶魔得逞，我们所有的努力——还有牺牲——就全白费了。"
D.Strings[108157]="他们的密探遍布艾泽拉斯，妄图破坏我们在那座墓穴的行动。他们是军团最强大的勇士。"
D.Strings[108158]="正如你看见的，破碎海滩外仍然有军团的触手。"
D.Strings[108159]="需要我帮什么吗？"
D.Strings[108160]="我们是不会坐以待毙的。"
D.Strings[108161]="我的部队已经为这一天准备多时了。他们的怒火正在火焰之地肆虐。"
D.Strings[108162]="斯莫德隆，听这个凡人的！"
D.Strings[108163]="你好，大领主。"
D.Strings[108164]="活动双腿的感觉真好！现在，该找个恶魔去活动一下我的拳头了！"
D.Strings[108165]="自由了？我不会忘记你的恩情的！"
D.Strings[108166]="恶魔要为此付出代价！"
D.Strings[108167]="我要战斗到咽下最后一口气为止！"
D.Strings[108168]="让燃烧军团去死！"
D.Strings[108169]="我的斧子呢？我还有恶魔要杀呢！"
D.Strings[108170]="燃烧军团要为此付出代价！"
D.Strings[108171]="那个笼子差点变成我的棺材……"
D.Strings[108172]="我要谢谢你，勇士！"
D.Strings[108173]="我得跟你的领主谈谈。"
D.Strings[108174]="终于自由了！去帮帮其他人吧，我会好起来的……"
D.Strings[108175]="该死！又是进攻！小心！"
D.Strings[108176]="噢，唔。这么说传言是真的？达拉然的宝贝武器都完蛋了？我一定要去参加葬礼……\n\n我想我们可以说服夜之子灵魂石跟我们合作。但首先，我们需要一个非常顽固的护盾发生器。"
D.Strings[108177]="你能想到安全使用夜之子灵魂石的方法吗？"
D.Strings[108178]="来吧。我想这件事情最好还是……私下讨论。"
D.Strings[108179]="唔……只要足够努力，一切皆有可能！如果我们让所有的法师都把精力集中在这上面，应该就能安全地使用它了……当然，那样可能有点不够效率。\n\n也许我们可以用护盾把它保护起来？卡德加的古怪朋友艾丽最擅长对付这种疑难杂症。让我们问问她是怎么想的吧！"
D.Strings[108180]="你能想到安全使用夜之子灵魂石作为武器的方法吗？"
D.Strings[108181]="有趣的想法，大法师$n！用燃烧军团自己的魔法来对付他们 ，真是难以言喻的优雅。但我们不能冒着让卡萨纳提尔逃脱的风险…… \n\n大法师卡雷对魔法物品很有研究，而且他为人谨慎可靠。让我们问问他是怎么想的吧？"
D.Strings[108182]="达拉然可以把夜之子灵魂石当做武器使用吗？"
D.Strings[108183]="我们得在他们的防线稳固之前出击！在每座建筑旁种下毁灭之种，那样它们会碾碎那些建筑。快！"
D.Strings[108184]="军团是残酷的敌人，但你救了这片森林。全瓦尔莎拉都感激你的胜利！"
D.Strings[108185]="恶魔占领了月爪谷上面的土地！军团在抽取树木的生命精华构筑工事，树木在哭泣。"
D.Strings[108186]="他们需要帮手去对付一个巨大的威胁，而且只叫了你。"
D.Strings[108187]="在那之前，不要让任何人看到你发现的东西。祝你好运，勇士。"
D.Strings[108188]="送我去托里姆峰！"
D.Strings[108189]="又来了？！噢，不！别告诉我这里头又有你的事！"
D.Strings[108190]="艾萨斯？你就是我们的秘密客人？出什么事了？"
D.Strings[108191]="军团潜入达拉然并破坏了城里的武器……恐怕修不好了。"
D.Strings[108192]="糟了……糟了。我们当然会帮忙的！"
D.Strings[108193]="大法师！肯瑞托需要你！"
D.Strings[108194]="如果你要响应他们的召唤，就去紫罗兰城堡找他们吧。"
D.Strings[108195]="六人议会需要你，战争领主。"
D.Strings[108196]="六人议会需要你，虚空领主。"
D.Strings[108197]="六人议会需要你，先知。"
D.Strings[108198]="六人议会需要你，暗影之刃。"
D.Strings[108199]="六人议会需要你，大祭司。"
D.Strings[108200]="六人议会需要你，大领主。"
D.Strings[108201]="六人议会需要你，大宗师。"
D.Strings[108202]="六人议会需要你，大法师。"
D.Strings[108203]="六人议会需要你，狩猎大师。"
D.Strings[108204]="六人议会需要你，大德鲁伊。"
D.Strings[108205]="六人议会需要你，屠魔者。"
D.Strings[108206]="六人议会需要你，死亡领主。"
D.Strings[108207]="你感觉一股强大的力量进入了你的脑海。"
D.Strings[108208]="那个白痴派你来找他的火药？这是我们光明正大地抢来的！"
D.Strings[108209]="军团位于森林内的据点被摧毁了！感谢你的帮助，大地会痊愈的。"
D.Strings[108210]="恶魔开启了一座传送门，召唤他们的同类。快消灭他们，否则这座森林就完了！"
D.Strings[108211]="玩家人数不足。"
D.Strings[108212]="唔……某位获胜者似乎已经离开了赛场。真是吃了大亏！"
D.Strings[108213]="|TINTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t你被|cFFFF0000|Hspell:239153|h[自动粉碎]|h|r锁定了！"
D.Strings[108214]="INTERFACE\\ICONS\\SPELL_BURNINGSOUL.BLP:20|t你成为了|cFFFF0000|Hspell:240209|h[自动粉碎]|h|r的目标！"
D.Strings[108215]="我们为什么要来永恒之井？"
D.Strings[108216]="我们为什么要来海加尔山？"
D.Strings[108217]="我们为什么要来安多哈尔？"
D.Strings[108218]="我们为什么要来斯坦索姆？"
D.Strings[108219]="我拓展业务范围了，伙计。这里什么东西都有，机会遍地啊。"
D.Strings[108220]="你的胳膊刚好能伸进洞里，但还是没能精准地填满整个空间。"
D.Strings[108221]="你的胳膊在洞里显得很小，但除此之外，什么都没有发生。"
D.Strings[108222]="<将胳膊伸进洞里。>"
D.Strings[108223]="你面前有一块奇怪的石头。它的中央有一个发光的洞，令它看起来很特别。\n\n这个石头上的洞大概跟你的胳膊差不多粗细。"
D.Strings[108224]="<将胳膊放到魔方下面。>"
D.Strings[108225]="<魔方快速重组了自己。>\n\n请将你的胳膊放到魔方下面。"
D.Strings[108226]="我的创造者们要找一个有趣的继承者。"
D.Strings[108227]="我能够给你第一个印记。"
D.Strings[108228]="我已经接受了永恒者的智慧。"
D.Strings[108229]="你有着怎样的智慧？"
D.Strings[108230]="我是智慧魔方。"
D.Strings[108231]="幼龙给了你一个强大的祝福！"
D.Strings[108232]="幼龙为你肃清了红玉巨龙圣地！"
D.Strings[108233]="幼龙为你肃清了翡翠巨龙圣地！"
D.Strings[108234]="幼龙为你肃清了黑曜石巨龙圣地！"
D.Strings[108235]="幼龙为你肃清了碧蓝巨龙圣地！"
D.Strings[108236]="燃烧军团总算少了一个主子，但这场战争还远未结束。\n\n这就是萨格拉斯真正的计划吗？他的终极目标？还是说这是别人干的。某个早已背叛过这个世界的人。\n\n<玛维眯起眼睛望向天空。>\n\n我会盯紧他们……并做好准备的。"
D.Strings[108237]="传送"
D.Strings[108238]="我们准备好了。让我们再试一次吧！"
D.Strings[108239]="请允许我介绍一下自己。我是伟大的阿尔阿巴斯。我被暂时囚禁在了这个破旧的容器里。或许你愿意大发善心听听我的遭遇？"
D.Strings[108240]="你正在使用|TInterface\\ICONS\\Achievement_ChallengeMode_Auchindoun_Hourglass.blp:32|t [窃取时间]！"
D.Strings[108241]="|TInterface\\Icons\\INV_MISC_AMMO_ARROW_03:20|t%s用|cFFFF0000|Hspell:230139|h[多头蛇射击]|h|r瞄准了敌人！"
D.Strings[108242]="时间耗尽了。"
D.Strings[108243]="我把解毒剂弄丢了。你捡到了吗？"
D.Strings[108244]="联盟即将在新工匠镇举办诺莫瑞根马拉松！"
D.Strings[108245]="联盟正在新工匠镇庆祝诺莫瑞根马拉松的举办呢！"
D.Strings[108246]="新工匠镇的诺莫瑞根马拉松开始啦！"
D.Strings[108247]="新工匠镇的诺莫瑞根马拉松开始啦！你能创造新的个人记录吗？！"
D.Strings[108248]="记得多喝水，为诺莫瑞根马拉松养精蓄锐吧！它很快就要在新工匠镇开始啦！"
D.Strings[108249]="你有没有训练？诺莫瑞根马拉松就要开始啦！"
D.Strings[108250]="干掉那头龙崽子！为了部落！"
D.Strings[108251]="以联盟的名义！干掉那头龙崽子！"
D.Strings[108252]="聪明的龙。我抓住过你一次，下次你还会落到我手里的！"
D.Strings[108253]="打开传送门！干掉那头青铜龙！别让它跑了！"
D.Strings[108254]="你扭曲时光的好日子到头了，小龙崽子！"
D.Strings[108255]="死神已经扼住了你那长满鳞片的喉咙，小龙。"
D.Strings[108256]="接受你的命运吧，小龙。你的时空之旅到此为止了。"
D.Strings[108257]="奇怪。你在这里干什么？"
D.Strings[108258]="巨龙来了！杀了那头龙！"
D.Strings[108259]="乖乖受死吧，巨龙！"
D.Strings[108260]="你死到临头了，小龙……"
D.Strings[108261]="烂肿要吃小龙！"
D.Strings[108262]="<回忆基尔加丹的溃败>"
D.Strings[108263]="<回忆安度因取回萨拉迈恩的过程>"
D.Strings[108264]="<回忆萨格拉斯之墓的开启>"
D.Strings[108265]="<回忆基尔加丹对达拉然的攻击>"
D.Strings[108266]="我已经大大放慢了时间流逝的速度，以便我们进行准备，而不用浪费宝贵的时间。$b$b你准备好出发后，就告诉我一声吧！"
D.Strings[108267]="克罗米需要我们的帮助？当然。我们可以引开火炮的火力，以便她安全飞离……"
D.Strings[108268]="我们需要德鲁伊引开外面的火炮，以帮助一头青铜龙逃离安多哈尔。"
D.Strings[108269]="这——这上头说你带来了守护者雷姆洛斯本人的命令！很好，那你有什么命令呢，$n？"
D.Strings[108270]="<出示塞纳里奥议会文件。>"
D.Strings[108271]="塞纳里奥议会不能坐视部落和联盟的士兵盲目厮杀。如果能安慰一些受伤的士兵，那我就满足了。"
D.Strings[108272]="我准备好了。我们去救你的命吧！\n|cFF0000FF（开启场景战役。）|r"
D.Strings[108273]="|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t过于靠近|cFFFF0000|Hspell:234621|h[吞噬巨口]|h|r将会导致|cFFFF0000|Hspell:232885|h[活体吞噬]|h|r！"
D.Strings[108274]="我看到你已经解决了那些巨龙圣地。请接受来自青铜龙军团的祝福吧。"
D.Strings[108275]="不用担心来自红玉巨龙圣地的攻击。我会消灭巫妖的。"
D.Strings[108276]="不用担心来自翡翠巨龙圣地的攻击。我会消灭萨特的。"
D.Strings[108277]="不用担心来自黑曜石巨龙圣地的攻击。我会消灭恐惧魔王的。"
D.Strings[108278]="不用担心来自碧蓝巨龙圣地的攻击。我会消灭虚空巨怪的。"
D.Strings[108279]="克罗米已经死了。"
D.Strings[108280]="遵命，主人。我们会在你指定的时间搞定这件事的。那头青铜龙绝对预料不到。我只需要在黑曜石巨龙圣地外来一下就够了。"
D.Strings[108281]="拖住那些红玉圣地守卫。我会从巨树内部发动主人策划的攻击。"
D.Strings[108282]="你在这儿……"
D.Strings[108283]="我听见你了……"
D.Strings[108284]="|TInterface\\Icons\\spell_shadow_painspike:20|t你受到了|cFFFF0000|Hspell:233983|h[回响之痛]|h|r的影响！"
D.Strings[108285]="守护者封印的力量减弱了。"
D.Strings[108286]="使用这把钥匙穿过市政厅。你就能从那里进入斯坦索姆的后街了。"
D.Strings[108287]="那到底是什么鬼？"
D.Strings[108288]="最好马上把它们分发给其他市民。大家都急需口粮。"
D.Strings[108289]="这么多粮食！农夫们这个星期可真够卖力的。"
D.Strings[108290]="冷静，胡椒。你怎么了？"
D.Strings[108291]="我觉得有点。但这不关我的事。"
D.Strings[108292]="你说这些粮食是不是有问题？"
D.Strings[108293]="在另一边的，则是一位极具吸引力的魔像。小心，这个魔像能把你揍得砰砰响！"
D.Strings[108294]="你感觉到了吗？这附近有宝藏。"
D.Strings[108295]="我感觉附近有宝藏。"
D.Strings[108296]="还剩一分钟。咱们玩的就是心跳，对吧？"
D.Strings[108297]="还有五分钟。你说我们能及时搞定吗？"
D.Strings[108298]="注意时间！只剩十分钟了……"
D.Strings[108299]="返回大裂口。"
D.Strings[108300]="传送到化身密室。"
D.Strings[108301]="有了封印的力量，我们就能直接前往化身密室了。"
D.Strings[108302]="那头龙来了！魔犬们，咬死她！"
D.Strings[108303]="|TInterface\\Icons\\SPELL_DEATHKNIGHT_ARMYOFTHEDEAD.BLP:20|t金属骑士召唤出一支|cFFFF0000|Hspell:245162|h[亡者大军]|h|r来攻击德芙琳·斯蒂克斯！"
D.Strings[108304]="|TInterface\\Icons\\WARRIOR_DISRUPTINGSHOUT.BLP:20|t德芙琳·斯蒂克斯跳了下来，对死亡金属骑士发出一声|cFFFF0000|Hspell:245150|h[尖啸]|h|r！"
D.Strings[108305]="凋零野猪将在一分钟后登台演出！快来岛屿东边的岩石之釜加入我们吧。"
D.Strings[108306]="|TInterface\\Icons\\ABILITY_UPGRADEMOONGLAIVE.BLP:20|t女猎手卡丝帕莲正在施放|cFFFF0000|Hspell:236480|h[战刃风暴]|h|r！"
D.Strings[108307]="|TInterface\\Icons\\ABILITY_DRUID_ECLIPSE.BLP:20|t女祭司月葬施放了|cFFFF0000|Hspell:233263|h[月蚀之拥]|h|r！"
D.Strings[108308]="|TInterface\\Icons\\INV_Misc_Herb_Arrowbloom.blp:20|t亚萨·袭月上尉的|cFFFF0000|Hspell:236304|h[灵体射击]|h|r正在瞄准！"
D.Strings[108309]="畅饮美酒，乐享肯瑞托旅店趴！快去魔术旅馆找安妮布里亚·日酒，与其他人一起狂欢吧！"
D.Strings[108310]="我们可以帮忙。"
D.Strings[108311]="我们正在寻找袭击克罗米的人。我们听说你遇到了一些魔网方面的麻烦——你觉得这两件事会有联系吗？"
D.Strings[108312]="我们正在寻找袭击克罗米的人。你遇到过什么怪事吗？"
D.Strings[108313]="我们会你帮忙保卫巨龙圣地的。"
D.Strings[108314]="我们正在寻找袭击克罗米的人。我们听说你遇到了亡灵的麻烦。"
D.Strings[108315]="我们正在寻找袭击克罗米的人。我们觉得你可能会知道些什么。"
D.Strings[108316]="老实说，我也不敢确定。但这很有可能。这一地区的魔网一直不稳定。但今天，它的动向特别奇怪。有人在扰动魔网。"
D.Strings[108317]="嗯？青铜龙军团来这里干什么？"
D.Strings[108318]="有。梦游者们非常不安。我们就快……控制不住局势了。"
D.Strings[108319]="你们好。我能帮你们什么忙吗？"
D.Strings[108320]="没错。通常我们每天只会遇到一两个迷路的食尸鬼。可今天，他们居然成群结队的来攻击我们。这种情况已经有快十年不曾出现了。"
D.Strings[108321]="我？为什么人人都要怀疑黑龙？我觉得很惭愧，克罗诺姆。$b$b不，我对袭击一无所未知。这么说吧，我只是来诺森德……散心的。但我惊讶地发现，我们深爱的巨龙圣地已经被骷髅占领了。如果你想要找可能会对付巨龙的人，你最好从这些亡灵，以及它们可能存在的幕后主使找起。"
D.Strings[108322]="我知道这个圣地已经废弃好几年了，可是……真的吗？有骷髅活动？父亲肯定会不高兴的。"
D.Strings[108323]="肯瑞托即将举办旅店趴！请在活动开始后来魔术旅馆享用美味的饮料和食物吧！"
D.Strings[108324]="我想我们应该先去找头青铜龙聊聊，从那儿查起。"
D.Strings[108325]="欢迎大家来暴风城和奥格瑞玛的拍卖行踊跃参加我们举行的舞会！"
D.Strings[108326]="大家都跳起来吧！我们已经接管了暴风城和奥格瑞玛的拍卖行，舞会即将开始！"
D.Strings[108327]="我们即将在暴风城和奥格瑞玛的拍卖行举行舞会！希望能在现场见到你！"
D.Strings[108328]="再问一下，你刚说什么来着？"
D.Strings[108329]="敌人……在……梦境里……"
D.Strings[108330]="阻止这折磨……"
D.Strings[108331]="帮帮我……"
D.Strings[108332]="拜访达拉然的织幻者图维斯或其他任意幻化师参加时尚试炼！"
D.Strings[108333]="快准备好你们的服装！时尚试炼就要开始了！"
D.Strings[108334]="袭击你的人……就在巨龙之掌内……"
D.Strings[108335]="去水边……寻找答案……"
D.Strings[108336]="你必须阻止……巨大的梦魇……"
D.Strings[108337]="这里说，他们的首领就在上边的某个飞碟上。该去解决他了！"
D.Strings[108338]="让人忍不住要想，我们到底是把宝贝藏在箱子里面还是外面了，对吧？"
D.Strings[108339]="好像我们希望人们发现它们似的！那些闪闪发光的黄金镶边和嵌满宝石的锁……"
D.Strings[108340]="那么，如今的宝箱是怎么回事呢？它们太贵太漂亮了……"
D.Strings[108341]="那个小家伙非常棒……就是把他唠叨了个死！"
D.Strings[108342]="你们知道他曾经用那些侏儒的小玩意儿把一只鹦鹉和一条鲨鱼组合成了终极海盗宠物吗？"
D.Strings[108343]="你们都知道疯狂的海军少将吉格普朗克，对吧？"
D.Strings[108344]="答案是：六个海盗！"
D.Strings[108345]="什么东西有六条腿，六只手和六只眼睛？"
D.Strings[108346]="下面是一个脑筋急转弯……"
D.Strings[108347]="他是在打折的时候买的！"
D.Strings[108348]="我问他给了上将多少钱才搞到那条船的，他告诉了我他的秘密……"
D.Strings[108349]="所以，盐蹄船长很快就弄到了他的第一条船，对吧？"
D.Strings[108350]="只要一个海盗！"
D.Strings[108351]="你们都知道他，一个完美主义者。这个耳洞打了两个小时。最后我问他要多少钱，他说……"
D.Strings[108352]="我昨天刚找急浪船帮的“帅小伙”邓肯打了个耳洞……"
D.Strings[108353]="来月光林地参加枭兽节，了解枭兽之道吧！"
D.Strings[108354]="枭兽节即将开始！请在活动开始后，来月光林地了解有关它的一切吧！"
D.Strings[108355]="我举起杯子告诉他，因为我们就是那么伟大！"
D.Strings[108356]="喝了几杯之后，他盯着我的眼睛问我，血帆海盗是怎么变得如此伟大的……"
D.Strings[108357]="上周，我在藏宝海湾跟一个恐怖船员的炮手喝酒……"
D.Strings[108358]="哈，现在，谁给我买杯酒来？"
D.Strings[108359]="好了，做好准备，伙计们。我马上就要让你们前仰后合了……"
D.Strings[108360]="谢了，伙计。不是只有宝箱里才能找到宝藏的。"
D.Strings[108361]="那就去告诉别人吧。告诉别人老噩耗也没那么糟糕。"
D.Strings[108362]="没错，那就帮我买杯酒吧，好吗？"
D.Strings[108363]="你没骗我吧？非常感谢你，朋友。"
D.Strings[108364]="耶！让我们来喝一杯！"
D.Strings[108365]="我漂过无数大洋，经历过无数次抢劫。这是真正的海盗式的幽默！"
D.Strings[108366]="我要宰了你……噢，等等，你喜欢这个笑话？谢谢。从来都没有人说过喜欢它。"
D.Strings[108367]="谢谢了，你这老海狗。"
D.Strings[108368]="祝你跟你的狐朋狗友都中黑斑！"
D.Strings[108369]="跟刽子手跳舞去吧，笑话是讲给老水手们听的。"
D.Strings[108370]="闭上你那灌饱了黄汤的臭嘴，自己走木板去吧，你这海狗的杂种！"
D.Strings[108371]="闭上你的臭嘴，否则咱们就白刀子进红刀子出，成不了海盗的可怜虫！"
D.Strings[108372]="我要剐了你！"
D.Strings[108373]="自己去舱底爬去吧，砸场子的家伙。"
D.Strings[108374]="哈！你行你上啊，无赖！"
D.Strings[108375]="哦？那你就是个丑八怪……你全家都是丑八怪！"
D.Strings[108376]="你的笑话真可怕！"
D.Strings[108377]="你的笑话是最棒的！"
D.Strings[108378]="当然，给我讲个笑话吧。"
D.Strings[108379]="脱掉鞋子，拿杯烈酒，听我来讲个笑话吧！"
D.Strings[108380]="我想前往卡拉赞（地下城）。"
D.Strings[108381]="你好，欢迎参加史诗邀请赛！\n\n我能将你直接传送到任意《军团再临》地下城中。\n\n请在传送前确认您已经选择了史诗难度。"
D.Strings[108382]="送我去黑暗神殿（时空漫游团队副本）。"
D.Strings[108383]="送我去黑暗神殿。"
D.Strings[108384]="你好，$n。你可能不记得我了，我们会在下周相识的。你还想再次造访黑暗神殿吗？"
D.Strings[108385]="50,000金币"
D.Strings[108386]="需要金币吗？我这儿有50,000金币。"
D.Strings[108387]="在你获得|TINTERFACE\\ICONS\\SPELL_FEL_INCINERATE.BLP:20|t |cFFFF0000|Hspell:240209|h[动荡的灵魂]|h|r的时候跳入深坑！"
D.Strings[108388]="吃饱了！"
D.Strings[108389]="吃得好饱……"
D.Strings[108390]="有点不舒服……"
D.Strings[108391]="今天是海盗日，这可是开派对的好日子！\n\n如果你受够了这些无聊的恐怖船员，就去南边的海滩……那里才是真正的海盗派对。\n\n那里是我们强大的血帆海盗的地盘。告诉他们，是老威斯克派你去的，他们或许会让我回去……"
D.Strings[108392]="你的池塘小马是哪儿来的？"
D.Strings[108393]="你要敢弄破一个小马，就会被永远赶出派对……就这样。我才不需要小马派对呢……\n\n小马都不是真正的海盗……它们都不会开炮……连手都没有……哇……"
D.Strings[108394]="蠢货吉格普朗克派我来……秘密侦查……他从来没来过……我也要生活的！"
D.Strings[108395]="烈酒，烈酒……我爱烈酒！\n烈酒，烈酒……别啃日志！\n嗝儿，嗝儿……给我烈酒！\n还要小心你的小细腿儿……\n\n你相信吗？这是我现编的！"
D.Strings[108396]="如果你觉得这个派对缺乏水的元素，那就等着看我的派对吧……\n\n你喜欢小马吗？"
D.Strings[108397]="……我才不在乎谁在听！\n\n听着，无聊……白痴……蠢货！\n\n哈……活该……"
D.Strings[108398]="我是来……参加派对的……可恐怖船员的派对简直比……影踪派的派对还不如！\n\n哈！"
D.Strings[108399]="今天是我的大日子！我是个海盗……对，我是彻头彻尾的海盗！\n\n接招吧，恐怖船员！"
D.Strings[108400]="还剩10秒！"
D.Strings[108401]="还剩30秒！"
D.Strings[108402]="|TInterface\\Icons\\INV_Axe_2H_UndeadGuitar_C_01.blp:20|t强力和弦如雨点般落下，用它们对你的敌人造成|cFFFF0000|Hspell:245034|h[心灵冲击]|h|r吧！"
D.Strings[108403]="这是什么？！我不可能失败！"
D.Strings[108404]="你们失败了，凋零野猪。现在，你们粉丝都已经加入了我的亡者大军！"
D.Strings[108405]="我的大军又多了一条亡魂！"
D.Strings[108406]="我的音乐又收割了一条灵魂！"
D.Strings[108407]="我从每座墓穴中召唤出食尸鬼。尽管挣扎吧，他们终将带来你们的末日！"
D.Strings[108408]="黑暗笼罩大地，来自哀嚎之墙的女妖也将随之降临！"
D.Strings[108409]="就算你们全力奋战，身体仍然会僵硬破碎！"
D.Strings[108410]="我要彻底证明，只有从墓穴中归来的骑士才有资格统治重金属领域。"
D.Strings[108411]="我们调整一下战术吧。\n|cFF0000FF（变更克罗米的天赋。）|r"
D.Strings[108412]="<调整克罗米的天赋>"
D.Strings[108413]="我们又见面了！"
D.Strings[108414]="我觉得这事儿比听起来的更严重！"
D.Strings[108415]="没什么特别的。魔网又开始紊乱了，但这在世界的这一地区很常见。"
D.Strings[108416]="事实上，的确有。翡翠巨龙圣地的护园者一直在努力让梦游者保持沉睡。一些古树已经从梦境中意外醒来，而我们还没搞清楚原因。"
D.Strings[108417]="亡灵又开始活动了。\n\n红玉巨龙圣地与亡灵的冲突由来已久。自从巫妖王陨落后，大部分冲突已经平息。但最近，这种事件又开始增多了。"
D.Strings[108418]="最近有什么怪事吗？"
D.Strings[108419]="你的气质有点奇怪，$r。你似乎有些……超凡脱俗，仿佛不属于这个世界。\n\n<卡雷苟斯低头看了看克罗米。>\n\n啊，我明白了。时空旅行。这……或许能解释你的特殊气质。\n\n<卡雷苟斯警惕地看着你。>"
D.Strings[108420]="我看到你和克罗诺姆在一起。我能问问……你们是从未来还是过去来的吗？\n\n我又想了想，你还是别回答了。这种事最好还是留给青铜龙们去操心吧。"
D.Strings[108421]="我……遇到麻烦了吗？"
D.Strings[108422]="欢迎来到龙眠神殿，时空旅行者。如果你们有需要，议会随时为你们效劳。"
D.Strings[108423]="我们再尝试一次吧！"
D.Strings[108424]="我相信我们一定解决这个麻烦的。你准备好了就告诉我一声吧。"
D.Strings[108425]="我们再试一次。这次我们要给自己稍微多留一点时间。\n\n你准备好吗？"
D.Strings[108426]="你准备好了吗？机不可失啊……相信我。"
D.Strings[108427]="时间能治愈一切……除了……致命伤……"
D.Strings[108428]="这不对……"
D.Strings[108429]="看来我该……去……"
D.Strings[108430]="也许下次吧……"
D.Strings[108431]="不……不应该是这样的……"
D.Strings[108432]="耶！我做到了！"
D.Strings[108433]="噢，很好！一切都解决了！"
D.Strings[108434]="抱歉，但……这是注定的！"
D.Strings[108435]="噢！你的时间已经用完了！"
D.Strings[108436]="我可比看上去厉害多了，你知道的……"
D.Strings[108437]="时间线不会自己修复的！"
D.Strings[108438]="该我亲自动手了！"
D.Strings[108439]="好吧……我先攻击这个家伙……"
D.Strings[108440]="唔……抱歉。"
D.Strings[108441]="它们或许能帮我们搞定安多哈尔的事。"
D.Strings[108442]="有趣……这些文件上说它们的携带者都是塞纳里奥议会的大人物。"
D.Strings[108443]="它在这里没什么用，但在永恒之井的话……"
D.Strings[108444]="泰兰德的月亮石？怎么来的？"
D.Strings[108445]="我想我们可以用它来激怒海加尔山的火元素。"
D.Strings[108446]="一个硫磺道标……有意思！"
D.Strings[108447]="收起来吧，我们下次去斯坦索姆时用。"
D.Strings[108448]="那是斯坦索姆的大门钥匙？哈！今天真走运！"
D.Strings[108449]="后会有期，$n！"
D.Strings[108450]="但这就交给未来的我们吧！呃，是未来的你和过去的我。算了算了，时间真复杂。"
D.Strings[108451]="大家为什么都想要我死？我想我们迟早会搞清楚的。"
D.Strings[108452]="似乎有许多人想杀我。恶魔、元素生物、亡灵、虚空领主……甚至还有部落和联盟！"
D.Strings[108453]="但我还是有些担心……"
D.Strings[108454]="那就好！"
D.Strings[108455]="一切似乎都……正常了。时间线更清晰了。我看不到自己的死亡了。"
D.Strings[108456]="呼！这下我就安全了。"
D.Strings[108457]="传送门在那儿！我们走！"
D.Strings[108458]="井的另一边应该有座时间传送门。跟我来，我认识路！"
D.Strings[108459]="我伤得很重。我们得把我送回龙眠神殿去。"
D.Strings[108460]="哦，不！我在那儿！"
D.Strings[108461]="上古之战前的永恒之井。距离你现在的时代大约是一万年，$n。大概吧。"
D.Strings[108462]="我想我会好起来的。感谢帮助！"
D.Strings[108463]="感觉好点了吗？"
D.Strings[108464]="别担心。我们保护你！"
D.Strings[108465]="噢，我受伤了！我能痊愈的……但还需要一点时间。"
D.Strings[108466]="我在那儿！"
D.Strings[108467]="我记得这里原来没有这么多火元素的……"
D.Strings[108468]="我想起来了！我应该就在前面。"
D.Strings[108469]="让我看看……我们在海加尔山，大灾变刚刚过去。"
D.Strings[108470]="随时为你效劳！"
D.Strings[108471]="谢谢你救了我，亲爱的我！"
D.Strings[108472]="呃！看看那个丑八怪。看来我们无法回避，只能正面应战了。"
D.Strings[108473]="我猜我们得进入斯坦索姆了！我们走吧，时间不多了！"
D.Strings[108474]="我没法击退他们。他们把你抓进城里去了！"
D.Strings[108475]="克罗米！感谢流沙，你终于来了。他们把你抓进城里去了！"
D.Strings[108476]="第三次大战时期的斯坦索姆。我记得，今天是阿尔萨斯王子的伤心日。"
D.Strings[108477]="我想是的。回头见！"
D.Strings[108478]="火炮哑火了。你能搞定它吗？"
D.Strings[108479]="我可以保护好自己，可有那门防空炮在，我没法飞走。快去破坏那些路障并解决它！"
D.Strings[108480]="联盟也想抓我？到底出什么事了？"
D.Strings[108481]="联盟的士兵们！守住阵地！她不可能一直躲下去。"
D.Strings[108482]="你瞧，这就是身为侏儒的苦恼。有些部落的士兵总是把你当做软柿子捏。"
D.Strings[108483]="它在那儿！我命令你们，杀了那头龙！"
D.Strings[108484]="这是刚经历过大灾变的安多哈尔。我们卷入了一场部落和联盟的冲突。"
D.Strings[108485]="哇……这扇门可有年头了！它指向永恒之井。"
D.Strings[108486]="啊……这是第三次大战时期的斯坦索姆。"
D.Strings[108487]="啊哈！海加尔山。我去过那里山次，呃，三次。嗯，应该是三次。"
D.Strings[108488]="有趣……这是安多哈尔。它始终是我的最爱！去看看我有没有遇到什么麻烦吧。"
D.Strings[108489]="这些家伙真是老谋深算！就算是有青铜龙在帮他们，我都不会惊讶了。"
D.Strings[108490]="我看得出来，你没听懂。简单地说，他们打算在不同时空节点上同时袭击我。"
D.Strings[108491]="我私下有个怀疑，敌人可能在策划一场跨越时空的袭击。否则他们何必要用时空碎片，对吧？"
D.Strings[108492]="看这个……它带着时光碎片。我要把它带去龙眠神殿，看它指向哪里。"
D.Strings[108493]="我从未想过要跟一个虚空领主作对。难以置信！"
D.Strings[108494]="别管魔网了，我们直接去找那虚空领主。时间宝贵！"
D.Strings[108495]="我们下去找找线索吧。这些干扰或许源于想要杀我的人。"
D.Strings[108496]="快看！时光碎片。我们得把它带回龙眠神殿去。"
D.Strings[108497]="奇怪。我不记得自己跟萨特有过冲突，不管是现在还是未来。"
D.Strings[108498]="记住，那个萨特就在水边的骨爪里。我们去干掉他吧！"
D.Strings[108499]="梦游者提供了三条线索……巨大的梦魇，水边，巨龙之掌。我们得搞清楚它们的含义。"
D.Strings[108500]="我们能帮忙，对吗？"
D.Strings[108501]="我们可以帮忙！"
D.Strings[108502]="唔……时光碎片。我们把它带回龙眠神殿吧。它会指向何时何地呢？"
D.Strings[108503]="唔！我很好奇，军团到底想对我干什么？"
D.Strings[108504]="幸好我们已经知道幕后黑手就是那个恐惧魔王。在他杀掉我之前，我们先去干掉他！"
D.Strings[108505]="看来他暴露了自己的位置。哈！我们快去黑曜石巨龙圣地的入口干掉他吧！"
D.Strings[108506]="恐惧魔王？还有青铜龙……等等，他说的是我吗？"
D.Strings[108507]="他的想法不错。我们去那个阴森的洞穴找线索吧。"
D.Strings[108508]="嗯？这是什么？时光碎片？我得把它带回龙眠神殿调查一下。"
D.Strings[108509]="我们及时解决了一个威胁！"
D.Strings[108510]="我们直接去找那个巫妖，$n。如果他真的是指挥者，那杀了他就能打乱他们的部署。"
D.Strings[108511]="他在树里，对吧？我们抓住他吧。他的死期到了！"
D.Strings[108512]="一个巫妖！噢！我早就猜到了……奇怪，我根本没预见到这件事。"
D.Strings[108513]="来吧，$n。我们去解决亡灵的首领。他们或许对即将发动的袭击知道些什么。"
D.Strings[108514]="听起来我们得去调查几个巨龙圣地了。我们走，呃……调查巨龙圣地去！"
D.Strings[108515]="魔网扰动？嘁……典型的蓝龙的问题。"
D.Strings[108516]="谢谢，阁下。我们去看看。如果有发现，我们会通知你的。"
D.Strings[108517]="我们会去看的。谢谢！"
D.Strings[108518]="我确定他往黑曜石巨龙圣地去了。"
D.Strings[108519]="怪事？我想想……哦！我之前确实见过那头黑龙。他叫什么来着？死亡之翼？不，不，不，不对……是另一个。戴帽子的那个。"
D.Strings[108520]="亡灵袭击了红玉巨龙圣地？我们去看看。谢谢，艾莉。"
D.Strings[108521]="让我们四处打听一下，看看能不能搞清这些暗影箭的来源。"
D.Strings[108522]="这点时间可能不够救我的，但我已经尽力而为了。"
D.Strings[108523]="此刻，距离我的死亡还有15分钟。"
D.Strings[108524]="好了，成功了！"
D.Strings[108525]="让我们最后试一次……"
D.Strings[108526]="我开始担心了，$n。这次袭击的策划者显然做了充分的准备。他们用某种方法阻碍了我的时空传送！"
D.Strings[108527]="别担心！四个小时可能早了点。我们试试一个小时。"
D.Strings[108528]="呃！奇怪。有什么东西在阻止我进入那个时间点。"
D.Strings[108529]="好了，我会把我们送到袭击发生前四个小时。这能让我们有足够的时间来解决麻烦。"
D.Strings[108530]="有人想要杀你。事实上，刺客随时可能出现……"
D.Strings[108531]="我们要去哪儿？干嘛要离开龙眠神殿？"
D.Strings[108532]="噢！好吧。你从来都没误导过我。将来也没有。"
D.Strings[108533]="跟我来！我们没时间了！"
D.Strings[108534]="嗨！我在这儿干嘛？"
D.Strings[108535]="嘿！克罗米！"
D.Strings[108536]="这次我多争取了几秒钟，但我们得快点行动。"
D.Strings[108537]="我们又要出发啦！"
D.Strings[108538]="嗨！你在这儿干嘛？"
D.Strings[108539]="很好。我在那儿。嗨，我好啊！"
D.Strings[108540]="好吧……让我看看。看来没错，误差不超过一分钟。我死了没？"
D.Strings[108541]="戴上你的头盔。我们要穿越时空啦！"
D.Strings[108542]="阿古斯——燃烧军团的王座。它的地狱火机器为萨格拉斯提供了无穷无尽的大军。\n\n黑暗泰坦的好日子也该到头了。\n\n我们的目标很简单。我们必须杀进阿古斯，让燃烧军团俯首称臣。"
D.Strings[108543]="萨格里特钥石撕裂了现实的结构。现在，燃烧军团的老巢就出现在我们面前，它的大军已经蓄势待发。\n\n图拉扬就在那里的某个地方。奥蕾莉亚也是。但愿如此吧。如果我们能找到那些老朋友，圣光军团或许能帮我们结束这场战争。"
D.Strings[108544]="我一直相信我还能再见到阿古斯。回归故乡的画面总是不断出现在我的预见中。\n\n可我没想到会是这样。\n\n毫无疑问，我们彼此两个世界的命运已经交织在了一起。阿古斯还有救吗？还是为了阻止萨格拉斯，我们就必须牺牲它？在这个问题上，我的预言非常模糊，充满了不确定性。\n\n看来我们必须自己创造命运了。愿圣光拯救我们，$n。"
D.Strings[108545]="噫！"
D.Strings[108546]="唉！"
D.Strings[108547]="还不累！"
D.Strings[108548]="不要睡！"
D.Strings[108549]="不要睡觉！"
D.Strings[108550]="|TInterface\\Icons\\SPELL_FEL_ELEMENTALDEVASTATION.BLP:20|t你受到了|cFFFF0000|Hspell:236329|h[星辰燃烧]|h|r的影响。被碎裂星辰锁定时，躲到地狱火柱后面去！"
D.Strings[108551]="|TInterface\\Icons\\TRADE_ARCHAEOLOGY_SHARK JAWS:20|t将|cFFFF0000|Hspell:232913|h[污染墨汁]|h|r带到萨鲁克身边，以终止他的|cFFFF0000|Hspell:234621|h[吞噬巨口]|h|r！"
D.Strings[108552]="部落失去了对矿井的控制。"
D.Strings[108553]="部落获得了对矿洞的控制。"
D.Strings[108554]="联盟失去了对矿洞的控制。"
D.Strings[108555]="联盟获得了对矿洞的控制。"
D.Strings[108556]="部落失去了对岩架的控制。"
D.Strings[108557]="部落获得了对岩架的控制。"
D.Strings[108558]="联盟失去了对岩架的控制。"
D.Strings[108559]="联盟获得了对岩架的控制。"
D.Strings[108560]="部落失去了对灯塔的控制。"
D.Strings[108561]="部落获得了对灯塔的控制。"
D.Strings[108562]="联盟失去了对灯塔的控制。"
D.Strings[108563]="联盟获得了对灯塔的控制。"
D.Strings[108564]="部落失去了对桥梁的控制。"
D.Strings[108565]="部落获得了对桥梁的控制。"
D.Strings[108566]="联盟失去了对桥梁的控制。"
D.Strings[108567]="联盟获得了对桥梁的控制。"
D.Strings[108568]="部落失去了对磨坊的控制。"
D.Strings[108569]="部落获得了对磨坊的控制。"
D.Strings[108570]="联盟失去了对磨坊的控制。"
D.Strings[108571]="联盟获得了对磨坊的控制。"
D.Strings[108572]="部落失去了对路口的控制。"
D.Strings[108573]="部落获得了对路口的控制。"
D.Strings[108574]="联盟失去了对路口的控制。"
D.Strings[108575]="联盟获得了对路口的控制。"
D.Strings[108576]="部落失去了对海滩的控制。"
D.Strings[108577]="部落获得了对海滩的控制。"
D.Strings[108578]="联盟失去了对海滩的控制。"
D.Strings[108579]="联盟获得了对海滩的控制。"
D.Strings[108580]="部落失去了对瞭望台的控制。"
D.Strings[108581]="部落获得了对瞭望台的控制。"
D.Strings[108582]="联盟失去了对瞭望台的控制。"
D.Strings[108583]="联盟获得了对瞭望台的控制。"
D.Strings[108584]="杀了那个搞破坏的家伙！"
D.Strings[108585]="谢谢你救了我。"
D.Strings[108586]="杀了碧火！"
D.Strings[108587]="克罗克在地下！"
D.Strings[108588]="救救克罗克！"
D.Strings[108589]="找到克罗克！"
D.Strings[108590]="帮帮克罗克！"
D.Strings[108591]="碧火有解药！"
D.Strings[108592]="你是最好的！"
D.Strings[108593]="你真棒。"
D.Strings[108594]="我爱你。"
D.Strings[108595]="<枭兽宝宝似乎非常喜欢你。>"
D.Strings[108596]="给予解药。"
D.Strings[108597]="帮帮我。"
D.Strings[108598]="请帮帮忙。"
D.Strings[108599]="救命……"
D.Strings[108600]="矿洞已关闭。"
D.Strings[108601]="矿洞即将关闭。"
D.Strings[108602]="矿洞已激活。"
D.Strings[108603]="矿洞即将激活。"
D.Strings[108604]="岩架已关闭。"
D.Strings[108605]="岩架即将关闭。"
D.Strings[108606]="岩架已激活。"
D.Strings[108607]="岩架即将激活。"
D.Strings[108608]="灯塔已关闭。"
D.Strings[108609]="灯塔即将关闭。"
D.Strings[108610]="灯塔已激活。"
D.Strings[108611]="灯塔即将激活。"
D.Strings[108612]="桥梁已关闭。"
D.Strings[108613]="桥梁即将关闭。"
D.Strings[108614]="桥梁已激活。"
D.Strings[108615]="桥梁即将激活。"
D.Strings[108616]="磨坊已关闭。"
D.Strings[108617]="磨坊即将关闭。"
D.Strings[108618]="磨坊已激活。"
D.Strings[108619]="磨坊即将激活。"
D.Strings[108620]="路口已关闭。"
D.Strings[108621]="路口即将关闭。"
D.Strings[108622]="路口已激活。"
D.Strings[108623]="路口即将激活。"
D.Strings[108624]="海滩已关闭。"
D.Strings[108625]="海滩即将关闭。"
D.Strings[108626]="海滩已激活。"
D.Strings[108627]="海滩即将激活。"
D.Strings[108628]="眺望台已关闭。"
D.Strings[108629]="眺望台即将关闭。"
D.Strings[108630]="眺望台已激活。"
D.Strings[108631]="眺望台即将激活。"
D.Strings[108632]="碧火是坏蛋！"
D.Strings[108633]="<枭兽宝宝一想到萨维诺克斯就哭了起来。>"
D.Strings[108634]="萨维诺克斯好可怕！"
D.Strings[108635]="你能送我去死亡矿井吗？"
D.Strings[108636]="<枭兽宝宝的肚子咕咕叫着，它指了指怒风兽穴。>"
D.Strings[108637]="浆果！"
D.Strings[108638]="饿！"
D.Strings[108639]="给上将拿杯酒来！还有救生圈！"
D.Strings[108640]="已经抢完藏宝海湾了吗，上将？哈，在你的指挥下，那些软骨头毫无机会！"
D.Strings[108641]="去找上将吧！"
D.Strings[108642]="大家都尖叫吧！"
D.Strings[108643]="大家都准备好了吗？"
D.Strings[108644]="旁若无人地舞蹈吧！"
D.Strings[108645]="好了各位，举起你们的手！"
D.Strings[108646]="好了，各位，让我们放松一下吧！"
D.Strings[108647]="等我训练完这些小家伙，他们就会成为月火术大师了！"
D.Strings[108648]="看看这些枭兽宝宝。他们始终无法长时间专注于月火术。"
D.Strings[108649]="你必须高度集中精力才能连续多次施放月火术。"
D.Strings[108650]="月火术对枭兽很重要。"
D.Strings[108651]="舰队上将特塞斯说该出发了……"
D.Strings[108652]="开始打呼。"
D.Strings[108653]="练习了一整天的舞蹈和月火术，枭兽宝宝需要好好休息，补充精力。"
D.Strings[108654]="休息对枭兽宝宝很重要。"
D.Strings[108655]="请安静点。别吵醒了枭兽宝宝！"
D.Strings[108656]="嘘。"
D.Strings[108657]="他说“呕”，我们说“嚯”！"
D.Strings[108658]="追逐船只，四海为家！"
D.Strings[108659]="前进，血帆海盗，前进！"
D.Strings[108660]="我们要把她砸得稀巴烂……"
D.Strings[108661]="噢，再走一程就能到站……"
D.Strings[108662]="我们要绕过海角……"
D.Strings[108663]="噢，你们这些海盗和恶棍……"
D.Strings[108664]="荆棘谷外海风劲吹……"
D.Strings[108665]="早晨醒来，酒桶空空……"
D.Strings[108666]="红裤子们！"
D.Strings[108667]="还有著名的红宝石号！"
D.Strings[108668]="多产天鹅号也一样！"
D.Strings[108669]="等我们返回荆棘谷，再也不和心上人分开！"
D.Strings[108670]="我们穿上白衬衣……"
D.Strings[108671]="祝西部勇士号健康……"
D.Strings[108672]="祝红鲸号健康……"
D.Strings[108673]="漂亮的赤红漩涡号要出海挣酒钱。"
D.Strings[108674]="所以打起精神来，小伙子们。永远别让自己心情低落！"
D.Strings[108675]="从阿拉希到藏宝海湾，真是一段漫长的旅程！"
D.Strings[108676]="直到我们到达荆棘谷海角！"
D.Strings[108677]="我们又叫又吼，跨过咸咸的大海！"
D.Strings[108678]="我们又叫又嚷，像个真正的血帆海盗！"
D.Strings[108679]="交出你们的宝藏和啤酒！"
D.Strings[108680]="乘风破浪去藏宝海湾！"
D.Strings[108681]="风儿忽高又忽低，船儿带我去远方！"
D.Strings[108682]="我们是海盗！血帆海盗！"
D.Strings[108683]="“噢，你们是海盗还是皇家舰队？”他大喊。"
D.Strings[108684]="我看见上风口有片残骸，下风口有条大船……"
D.Strings[108685]="看船头，看船尾，看天气和风向……"
D.Strings[108686]="给我点时间打倒这个大老粗！"
D.Strings[108687]="唉，这话击倒了我这个大老粗！"
D.Strings[108688]="“我来自铁炉堡，最崇拜铜须！”"
D.Strings[108689]="我用矮人语向她问好，她清脆地答道……"
D.Strings[108690]="我接过所有的帆，喊道：“快停下！”"
D.Strings[108691]="她拉着帆索，在船头手舞足蹈……"
D.Strings[108692]="遇到了一个漂亮妞儿……"
D.Strings[108693]="我走上藏宝海湾的木板……"
D.Strings[108694]="这里是血帆的地盘。"
D.Strings[108695]="别玩水！"
D.Strings[108696]="交出宝藏，饭桶。"
D.Strings[108697]="血帆的派对永不结束！"
D.Strings[108698]="谁都别想惹血帆海盗！"
D.Strings[108699]="不加入血帆，你就别出海！"
D.Strings[108700]="我们要拿出血帆海盗的血性！"
D.Strings[108701]="旱鸭子走开！"
D.Strings[108702]="你看起来很眼熟……我是不是抢过你的海滨别墅？\n\n哈，对了！就是你！你的仆人都尖叫着跑进了葡萄园，对吧？然后我们把整座别墅都烧成了白地？\n\n多么美妙的时光啊。"
D.Strings[108703]="喜欢宝藏吗，旱鸭子？太可惜了！宝藏都是我们的！"
D.Strings[108704]="我以前在下层甲板上见过你没有？还是我喝糊涂了……"
D.Strings[108705]="人人都想成为血帆海盗，可只有少数人才有胆子付诸实践。"
D.Strings[108706]="怯懦的克罗斯比完全是活该。"
D.Strings[108707]="如果你稍后还需要烧烤，就来找我。我最擅长玩火了。"
D.Strings[108708]="我从未如此自由过！"
D.Strings[108709]="推我去藏宝海湾，那我就能更加大声地嘲骂他们了！"
D.Strings[108710]="看看这个旱鸭子，连海马都没有！哈！"
D.Strings[108711]="我这样会不会更可怕一点？"
D.Strings[108712]="他们已经没有红色的了。"
D.Strings[108713]="停下！别再戳我的充气玩具了，否则我就要揍你了！"
D.Strings[108714]="你的海马呢，伙计？"
D.Strings[108715]="别对我评头论足的。尤其是在海盗日！"
D.Strings[108716]="快点，小马！我们必须在日落时到达藏宝海湾！\n\n我敢肯定，你都没使劲儿。"
D.Strings[108717]="这是一年中海军上将唯一不会管我的日子。\n\n是全艾泽拉斯瑟瑟发抖的日子。 \n\n我是满怀雄心壮志的狂野海盗！藏宝海湾必将……熊熊燃烧！"
D.Strings[108718]="冲——锋——！\n\n<海军少将吉格普朗克停顿了一下，然后撅起了嘴。>\n\n好吧，我们还是等涨潮吧。这会让我们更有气势一点。"
D.Strings[108719]="见证海军少将吉格普朗克的无边怒火吧！就连藏宝海湾大得吓人的耗子都别想活命！"
D.Strings[108720]="整个藏宝海湾都在恐惧我的到来！这在古代传说里早有预言。"
D.Strings[108721]="但愿这头该死的腌公马沉到海底去！它不听我的命令。前进，畜生，否则我就揍得你满地爬！"
D.Strings[108722]="<海军少将吉格普朗克疯狂地踢着腿，可他的脚就是碰不到水面。>"
D.Strings[108723]="我将在日落后抵达藏宝海湾。然后，在夜色的掩盖之下，我要让他们尝尝血帆的怒火！"
D.Strings[108724]="血帆海盗抢了我家的渔船，但他们没有杀掉我深爱的亲人。\n\n他们将我从没有宝藏和烈酒的无聊生活里救了出来！我天生就是当海盗的料！"
D.Strings[108725]="我没上过任何名牌学院，但我抢过那些学院！"
D.Strings[108726]="没有在咸咸的海雾中对着朝阳喊过海员号子，那你就算白活了一辈子。"
D.Strings[108727]="砰！砰！"
D.Strings[108728]="砰！砰！砰！"
D.Strings[108729]="今天，我们都是海盗。可明天，你就得拿出真本事了。"
D.Strings[108730]="一把弯刀，一手法术，一瓶烈酒。身为血帆海盗，你已经别无所求了。"
D.Strings[108731]="美酒就等于法力，如果你够壮的话。"
D.Strings[108732]="你会解除巫毒诅咒吗？"
D.Strings[108733]="藏宝海湾必将燃烧！"
D.Strings[108734]="你见过燃烧的大海吗？"
D.Strings[108735]="跟上节奏！"
D.Strings[108736]="你感觉到节奏了吗？"
D.Strings[108737]="跳舞！跳舞！跳舞！"
D.Strings[108738]="所有人……都跳起来吧！"
D.Strings[108739]="我喜欢跳舞！"
D.Strings[108740]="恐怖船员……最多只能吓唬他们自己，对吧？"
D.Strings[108741]="欢迎参加派对！"
D.Strings[108742]="我是强大的海盗！"
D.Strings[108743]="等你成为了血帆海盗，每天都是海盗日！"
D.Strings[108744]="你去哪儿了？我们还没喝够呢！"
D.Strings[108745]="请随意，不用客气。"
D.Strings[108746]="欢迎参加枭兽节！"
D.Strings[108747]="激活导管"
D.Strings[108748]="来吧，熊猫人！"
D.Strings[108749]="我就喜欢那些熊猫人憨态可掬的舞姿。该跳起来了！"
D.Strings[108750]="呜——！狼人们，秀秀你们的野性吧！"
D.Strings[108751]="来吧，狼人的兄弟姐妹们！让他们看看狼人的舞蹈！"
D.Strings[108752]="他们的舞蹈充满了异域风情。让我们欣赏德莱尼的表演吧！"
D.Strings[108753]="让我们欢迎德莱尼上台！"
D.Strings[108754]="侏儒！他们很可爱，不是吗？"
D.Strings[108755]="让我们有请那些侏儒上台，好让大家都能看见他们！"
D.Strings[108756]="暗夜精灵！让我们看看你们在泰达希尔是怎么跳舞的吧！"
D.Strings[108757]="来欣赏一下这些美丽自信的暗夜精灵的舞姿吧！我恐怕很快就会心动不已了……"
D.Strings[108758]="现在，轮到矮人向我们展示他们的派对了！"
D.Strings[108759]="看看那些矮人的舞步！而且他们还能边跳边稳稳地端着啤酒杯！"
D.Strings[108760]="我听过一种传闻，说人类不会跳舞。来证明一下我是错的吧！"
D.Strings[108761]="这是你们的城市，人类。展示一下你们的骄傲吧！"
D.Strings[108762]="你应该知道，这座城市还有一座拍卖行的，对吧？"
D.Strings[108763]="好了，我这边都安排好了。只要激活能量导管，传送台就能动了！"
D.Strings[108764]="目标活动处于正常参数内。代言人正在等你。"
D.Strings[108765]="目标确认：代言人的盟友。暂停执行毁灭协议。"
D.Strings[108766]="|TInterface\\Icons\\Spell_Deathknight_Defile:20|t灵魂世界中没有灵魂的存在，灵魂女王德雅娜开始施放|cFFFF0000|Hspell:236507|h[寂灭]|h|r！"
D.Strings[108767]="就是这样！她清醒过来了。她在……恐惧。小心！"
D.Strings[108768]="噢，对。"
D.Strings[108769]="你应该知道，奥格瑞玛还有一座拍卖行的，对吧？"
D.Strings[108770]="难以置信，他们居然包下了整栋楼来开舞会！这下叫我去哪儿卖这些裤子？"
D.Strings[108771]="这是我们的城市，兽人们。向他们展示一下我们的骄傲吧！"
D.Strings[108772]="站起来吧，兽人的兄弟姐妹们！让我们看看你们的舞姿！"
D.Strings[108773]="血精灵！轮到你们跳了。"
D.Strings[108774]="尽情欣赏血精灵的美妙舞姿吧！"
D.Strings[108775]="让我看看那些地精的舞步吧！"
D.Strings[108776]="让我们有请那些地精上台，好让大家都能看见他们！"
D.Strings[108777]="来吧，牛头人！让我们看看来自莫高雷的舞蹈。"
D.Strings[108778]="小心你们的脚！接下来是牛头人的舞蹈时间，他们的蹄子踩人可是很疼的。"
D.Strings[108779]="接下来是巨魔的舞蹈时间！鞋子束缚不了他们灵活的腿脚！"
D.Strings[108780]="来吧，巨魔！让大家看看你们是怎么跳舞的！"
D.Strings[108781]="该请被遗忘者跳舞了。他们的舞步能让你无法呼吸。"
D.Strings[108782]="现在有请被遗忘者上台！"
D.Strings[108783]="摇滚宝贝们！你们来对地方了！请允许我向你们介绍……凋零野猪！"
D.Strings[108784]="凋零野猪正在暗月岛的东边举办他们的地下演唱会！你们的大明星，凋零野猪将在十分钟后登台献唱！"
D.Strings[108785]="如果你们想体验一下抑郁的感觉，那么凋零野猪的演唱会将在二十分钟后开始！"
D.Strings[108786]="你们也可以来见识一下顶级的乐队！凋零野猪的演唱会将在三十分钟后开始！"
D.Strings[108787]="宝贝，宝贝，宝贝！这里有你们所见过的最邪恶、最真实、最致命的乐队！他们能让你眉飞色舞，面目全非！在遇到这些家伙前，我还是个细皮嫩肉的活人！而现在，我成了个死掉的大富豪！\n\n每个小时的半点，请来这里观赏凋零野猪的演出吧！"
D.Strings[108788]="我想参加时尚试炼！"
D.Strings[108789]="我想幻化装备。"
D.Strings[108790]="我这里工具齐全，能够调整你的武器和护甲的外观。\n\n我们可开始了吗？"
D.Strings[108791]="没错……今天的竞赛没有主题。你们爱穿什么就穿什么吧！"
D.Strings[108792]="今天的规矩就是素雅的白色长袍和闪闪发光的盔甲！"
D.Strings[108793]="众所周知，史诗护甲都是紫色的。快用这最后一种彩虹的颜色来装扮你自己吧！"
D.Strings[108794]="你想做个农夫？厨师？科学家还是海盗呢？噢……我已经等不及想看看他们的创意了！"
D.Strings[108795]="你代表塞拉摩吗？还是肯瑞托？如果需要换上战袍，去找奈莉谈谈吧！"
D.Strings[108796]="该来点乐子了，展示一下你们的疯狂着装吧！"
D.Strings[108797]="让大家看看你魔力四射的时装！别忘了附魔！"
D.Strings[108798]="熊猫人的时尚从內而外都散发着和谐。让大家看看你们的平常心！"
D.Strings[108799]="为了部落！为了联盟！让我们看看你们的阵营风采吧。"
D.Strings[108800]="来秀秀你们的邪恶面吧！"
D.Strings[108801]="穿上你最吓人的装束，让我们在颤栗中感受时尚吧。哦……我已经开始起鸡皮疙瘩了！"
D.Strings[108802]="来点幽默感，秀出你最光怪陆离的奇装异服吧！"
D.Strings[108803]="快来让我的心脏骤停吧！不要怕暴露！"
D.Strings[108804]="快把脸上的妆擦干净，画上战纹吧！"
D.Strings[108805]="快把自己裹起来！让我们看看你在诺森德的冰封海滩上会穿些什么！"
D.Strings[108806]="今天的竞赛主题是……随心所欲！"
D.Strings[108807]="今天的竞赛主题是……圣光英雄！"
D.Strings[108808]="今天的竞赛主题是……紫色史诗！"
D.Strings[108809]="今天的竞赛主题是……平凡的英雄！"
D.Strings[108810]="今天的竞赛主题是……战袍时代！"
D.Strings[108811]="今天的竞赛主题是……搞怪派对！"
D.Strings[108812]="今天的竞赛主题是……魔法塑形！"
D.Strings[108813]="今天的竞赛主题是……和谐禅意。"
D.Strings[108814]="今天的竞赛主题是……阵营之光！"
D.Strings[108815]="今天的竞赛主题是……致命黑暗！"
D.Strings[108816]="今天的竞赛主题是……毛骨悚然！"
D.Strings[108817]="今天的竞赛主题是……混搭风！"
D.Strings[108818]="今天的竞赛主题是……大众情人！"
D.Strings[108819]="今天的竞赛主题是……开战时刻！"
D.Strings[108820]="今天的竞赛主题是……冬季着装！"
D.Strings[108821]="今天就到此为止了。下期活动再见！"
D.Strings[108822]="至于其余的参与者，继续努力吧。你们很快就能成为冠军了。"
D.Strings[108823]="最后，则是今晚的幻化冠军。让我们一起喊出那个名字，$n！"
D.Strings[108824]="第二名属于……$n！你看起来真棒！"
D.Strings[108825]="第三名是……$n！恭喜$n！"
D.Strings[108826]="而右边，则是独一无二的$n！"
D.Strings[108827]="在你们的左边，是光彩照人的$n！"
D.Strings[108828]="比赛将在两分钟后开始。帅哥美女们，祝你们好运！"
D.Strings[108829]="如果你需要做头发，我们也提供了理发椅。"
D.Strings[108830]="利用接下来的时间准备你们的服装吧。"
D.Strings[108831]="噢，我最喜欢迷人的短裤了。"
D.Strings[108832]="今天的竞赛主题是……夏季时尚！"
D.Strings[108833]="但愿各位都带来了最美的战袍，因为今晚的竞争似乎会很激烈！"
D.Strings[108834]="欢迎来到时尚试炼：艾泽拉斯的时尚地标！"
D.Strings[108835]="惊叹它的辉煌吧！你们无法逃避注定的命运！"
D.Strings[108836]="睁开眼睛吧，$n！里面等着你的只有谎言。真相就在天空中！"
D.Strings[108837]="这里只能给出空洞的承诺！财富也救不了你！"
D.Strings[108838]="财富毫无意义！看看天空吧！末日已经降临了！"
D.Strings[108839]="钱财拯救不了你，$n！"
D.Strings[108840]="真理现世了！"
D.Strings[108841]="看看天空吧！伟大的命运终于降临了！"
D.Strings[108842]="张开双臂，拥抱面前的毁灭吧！"
D.Strings[108843]="这一刻终于到来了！我们即将踏上末日之旅！"
D.Strings[108844]="我一直在梦想着这一刻，但我从未想到它会如此……美丽。"
D.Strings[108845]="送我去时尚试炼！"
D.Strings[108846]="设施锁定确认。遭遇威胁。"
D.Strings[108847]="末日……"
D.Strings[108848]="……在黑暗之中。"
D.Strings[108849]="<控制不住地颤抖。>"
D.Strings[108850]="<呓语。>"
D.Strings[108851]="<胡言乱语。>"
D.Strings[108852]="我该怎么对孩子们说？"
D.Strings[108853]="我们能做些什么吗？"
D.Strings[108854]="这不可能是末日！不可能！"
D.Strings[108855]="我也不知道自己还能做什么了！"
D.Strings[108856]="到此为止了？它是这个意思吗？我还有很多事想做……"
D.Strings[108857]="天空又变黑了！我们还有希望吗？"
D.Strings[108858]="万一有东西来攻击城市怎么办？我们该怎么做？"
D.Strings[108859]="它有什么含义？这是世界末日吗？"
D.Strings[108860]="看来我们得做些准备了，勇士！你最好把我们的发现告诉卡德加。祝你好运！"
D.Strings[108861]="军团……和上古之神在纠缠着她。可还有更加……巨大的阴影……"
D.Strings[108862]="与世界之魂对话可不像跟凡人闲聊。这或许就是她需要代言人的原因。"
D.Strings[108863]="我们希望大家能以耐心冷静的态度等待进一步的消息。"
D.Strings[108864]="我们是代表你们来的。没有必要恐慌。请注意时刻保持秩序。"
D.Strings[108865]="如果你发现任何可疑活动和可疑举止，请果断通知我们。"
D.Strings[108866]="由于最近客流激增，请大家务必保持冷静、有序的态度。"
D.Strings[108867]="请保持冷静，有序排队。等这里有位置之后，就会有银行职员来为大家服务的。"
D.Strings[108868]="我肯定，我们家那个保险柜绝对能抵挡世界末日。"
D.Strings[108869]="世界末日？呸！我就想拿到我们的钱，可这些家伙的动作慢得像蜗牛。"
D.Strings[108870]="这种时候，能有人来搭把手又有什么不好呢？我们就想把自己的东西安全拿回家，以防……额，你懂的。"
D.Strings[108871]="别动！大家都不希望自己的战利品泡汤，对吧？"
D.Strings[108872]="没见过别人保护自己的财产吗？接着走，别停下！"
D.Strings[108873]="听着——我们确信这里的货物都是“安全”的，可万一呢？"
D.Strings[108874]="……在黑暗中，圣光必胜。"
D.Strings[108875]="修理就快完成了。"
D.Strings[108876]="愿我们再次崛起。"
D.Strings[108877]="这些事看起来或许让人有些不安，但黑暗的彼端还有希望在闪耀。"
D.Strings[108878]="准备工作就快完成了。一段伟大的旅程正在等着我们。"
D.Strings[108879]="感谢圣光的祝福，我们即将踏上新的旅途。"
D.Strings[108880]="没必要道歉。你们没做错什么。我们只是需要确认街道对你们来说是安全的。"
D.Strings[108881]="这种时候，孩子们可不该在街上乱跑。很快就会有人来照看你们的，直到我们确认城市里一切安全。"
D.Strings[108882]="这不是你们的错，孩子们。但在我们确认安全之前，你们真的不应该跑出来。"
D.Strings[108883]="你们的父母呢？你们不该在这种时候在城里乱跑。"
D.Strings[108884]="拜托！有人看见他们的父母了吗？他们真的不应该在这种时候乱跑。这不安全。"
D.Strings[108885]="议会很快就会放出消息了，我敢肯定。"
D.Strings[108886]="我们得听我们的领袖的，而不是城里那些闲言碎语。我们很快就会收到更多消息了。"
D.Strings[108887]="我很好奇，街面上什么时候才能平静下来。自从这件事发生之后，城里一直闹哄哄的。"
D.Strings[108888]="先前在街上走动时，我已经听腻了各种猜测。最近城里充满了不安的气氛。"
D.Strings[108889]="我们得努力保持积极的态度。大家的麻烦已经够多了。我们要给其他人做出榜样。"
D.Strings[108890]="我完全信任我们的领袖。我们不该被城里的风言风语误导。俗话说得好，三人成虎嘛。"
D.Strings[108891]="看看头顶的天空吧！真相终于大白天下！"
D.Strings[108892]="这年头，充满魔力的已经不止是天空了！放松一下，看看我们新到的动物吧。"
D.Strings[108893]="嘿，$n！议会放出什么消息了吗？"
D.Strings[108894]="我们越来越不安了。到底发生什么事了，你有消息吗？"
D.Strings[108895]="有什么事吗，$n？"
D.Strings[108896]="街面上有什么消息吗，$n？"
D.Strings[108897]="请尽量不要发出噪音。这些动物已经非常紧张了。"
D.Strings[108898]="看呐，看呐，我漂亮的动物们！生活很快就会恢复正常的……但愿如此。"
D.Strings[108899]="小心点。最近宠物们都相当暴躁。你最好暂时离围栏远点。"
D.Strings[108900]="要是这些宠物太顽皮了，请别跟它们计较。有什么东西激怒了它们。"
D.Strings[108901]="%s变得十分不安。"
D.Strings[108902]="小心点，$n！话说，议会有消息了吗？"
D.Strings[108903]="外头出什么事了？外面越来越吵了。但愿我们很快就能听到最新的消息。"
D.Strings[108904]="你好！我和鲁希安正在讨论最近的局势呢。你给我们带什么新消息来了吗？"
D.Strings[108905]="外面怎么样了，$n？每天都有人跑来跑去，可大家似乎都所知不多。"
D.Strings[108906]="今天有什么消息吗？我们好久没有听到新消息了。"
D.Strings[108907]="这种等待消息的日子让我有点神经紧张。"
D.Strings[108908]="但愿我们很快就能收到最新的消息。上一次公告都是好久之前了。"
D.Strings[108909]="有时我都开始怀疑，我们究竟还能不能得到一个答案了。为什么会发生这种事呢……"
D.Strings[108910]="但愿你一切都好，$n。至于我么，呃……"
D.Strings[108911]="噢不！又洒了一杯酒。最近发生的一切似乎已经让我的手开始发抖了。"
D.Strings[108912]="啊，$n！你来给我们评评理……我和埃里雷一直在争论议会的评估到底完成了没有。有什么消息吗？"
D.Strings[108913]="拉张椅子坐下来歇歇吧。我们知道外头有点乱，所以请把你的担忧先留在门外吧。"
D.Strings[108914]="埃里雷。拜托！别当着客人的面发疯。我们还不知道那到底是什么，瞎猜毫无意义。"
D.Strings[108915]="我也想保持乐观，可我真的不知道该期待什么。"
D.Strings[108916]="你今天听说什么新消息了吗？"
D.Strings[108917]="我不断回来打探消息，可得到的回复总是一成不变。"
D.Strings[108918]="那是什么意思？我以前从来没见过这种东西。"
D.Strings[108919]="我还没打听到什么新消息，$n。你呢？"
D.Strings[108920]="我需要一个答案。"
D.Strings[108921]="我要知道发生了什么事。"
D.Strings[108922]="我在寻找答案。你听说什么新消息了吗？"
D.Strings[108923]="你在这里很安全，$n。自从那件事发生后，埃德尔鲁就坚持要去守门。但我并不担心。"
D.Strings[108924]="我们的大门永远向你敞开，$n。但愿这里的气氛能比外面平静一些。"
D.Strings[108925]="很高兴再次见到你，$n。你是来聊天的吗？还是来买补给的？还是来告诉我……外面出了什么事的？"
D.Strings[108926]="欢迎光临！议会公布他们的发现了吗，$n？"
D.Strings[108927]="$n，很高兴见到你！你知道出什么事了吗？"
D.Strings[108928]="眼冒金星算是正常吗？"
D.Strings[108929]="我只想让自己恢复正常。"
D.Strings[108930]="这真是太让人心烦意乱了。我不知道自己能不能挺过去。"
D.Strings[108931]="他们说那都是我想象出来的，可这个……这个不一样。我发誓！"
D.Strings[108932]="必须阻止它。我已经撑不住了。"
D.Strings[108933]="拜托。你一定要救救我们。"
D.Strings[108934]="我感觉它又靠近了……"
D.Strings[108935]="我以前从没见过这种病，$n。我们会坚持研究下去的。请把出现类似症状的人都送来吧。"
D.Strings[108936]="真希望事态能够平息下来。恐慌的人群一直在不断涌来。"
D.Strings[108937]="很快，我们就得让病人到别处就诊了。我想我们已经没有资源来维持表面的秩序了。"
D.Strings[108938]="有消息了吗，$n？这些症状反复出现，但我们对此找不到任何解释！"
D.Strings[108939]="我们已经没有多余的空间来容纳病人了。我不知道我们还能坚持多久。"
D.Strings[108940]="我不知道我们还能坚持多久，$n。我们的补给已经开始短缺了。"
D.Strings[108941]="我们已经增加了额外的助手，很快就会轮到你们了。请保持耐心。"
D.Strings[108942]="如果里面太挤了，请先到门外就诊。我们在外面设置了额外的诊室，那里的助理会帮助大家的。"
D.Strings[108943]="$n！病人还在不断涌来！我从没见过这种病。"
D.Strings[108944]="请保持镇静。我们会挨个帮助大家的，但请各位耐心点。"
D.Strings[108945]="如果市民继续出现这些症状，我们就得开始培训额外的帮手了。"
D.Strings[108946]="你是来帮忙的吗，$n？我还没有诊断出来。到处都有出现症状的人。"
D.Strings[108947]="议会希望大家能保持冷静，直到他们完成对局势的评估。"
D.Strings[108948]="如果你发现任何可疑举动、魔法或其他情况，请立即举报。"
D.Strings[108949]="在议会完成调查前，我们必须保持冷静。"
D.Strings[108950]="我们会与议会密切合作，直到问题解决为止。"
D.Strings[108951]="议会已经注意到了这个情况。他们希望大家保持冷静，直到评估完成。"
D.Strings[108952]="请保持冷静。答案很快就会揭晓的。"
D.Strings[108953]="我们需要答案！我们都不知道会发生什么事。"
D.Strings[108954]="大家都在做什么？他们把孩子们都吓坏了。"
D.Strings[108955]="我们该不该担心呢？"
D.Strings[108956]="那是什么意思？"
D.Strings[108957]="你有什么新消息吗？"
D.Strings[108958]="我们也想知道答案。"
D.Strings[108959]="万一出什么事了怎么办？"
D.Strings[108960]="出什么事了？我们究竟被隐瞒了什么？"
D.Strings[108961]="议会让我来调查这些新添的烧灼痕迹。它们是最近才出现的。"
D.Strings[108962]="别靠得太近，$n。这里刚刚被袭击过，还不安全。"
D.Strings[108963]="这些痕迹还很新。在我们的清理工作结束之前，请尽量远离这里，$n。我们可不希望你受伤。"
D.Strings[108964]="我不知道他在唠叨些什么，但听起来不妙。而且他已经不是这周第一个这么说的人了！"
D.Strings[108965]="嘿嘿，进来吧！来休息一下，然后再出去为我们的未来而奋斗。"
D.Strings[108966]="嘿，你！啊，算了。我还以为你是……你知道的……他们中的一员。"
D.Strings[108967]="外面的人怎么样了？"
D.Strings[108968]="关于外头的事，有什么消息吗？"
D.Strings[108969]="你有什么关于天空的消息吗，$n？"
D.Strings[108970]="大家都在商店、银行里进进出出的……到底出什么事了？我都开始紧张了。"
D.Strings[108971]="有人想来点儿甜点吗？再也没有什么能比新鲜美味的甜食更能振奋人心的了。"
D.Strings[108972]="$n，这边！如果你听说了任何消息，请立即告诉我。我打包货物也是需要一点时间的。"
D.Strings[108973]="准备很重要，$n。我的货物随你挑——当然不是免费的。"
D.Strings[108974]="你准备好了吗，$n？你的某些盟友似乎无法很好地应对局面。"
D.Strings[108975]="黑暗笼罩了天空，$n。但愿你已经准备好了。"
D.Strings[108976]="我知道现在局势很紧张，可别害怕，尽情在这个神秘刺激的乐园里放飞你的思绪吧！"
D.Strings[108977]="欢迎，$n！我们有个规矩：那就是保持乐观的态度！别让外面的骚乱干扰了你的情绪。"
D.Strings[108978]="再也没有东西比玩具更能解忧消愁了。请在店里随便看看吧！"
D.Strings[108979]="请进，$n！暂时把你的忧愁留在门外吧。卫兵已经向我们保证过一切正常了。"
D.Strings[108980]="唔？有什么不对吗？请往里走！"
D.Strings[108981]="外面怎么样了，$n？客人太多了，完成订单都很困难。但愿一切都好。"
D.Strings[108982]="客人都很喜欢我们的货物。我相信到时候他们肯定不会——噢！欢迎光临，$n。"
D.Strings[108983]="盯着你知道的就行了，伊克斯。没必要瞎猜。现在，打起精神来，我们有客人了。"
D.Strings[108984]="%s收起了武器。"
D.Strings[108985]="别动！啊！这已经是第几次了？先是卫兵们来突击检查，现在你又……好吧，虽然东西已经不多了，但你尽管看吧。"
D.Strings[108986]="举起你的手！呃！又是你。我最近赶走了太多恶棍，我都不知道该怎么思考了。"
D.Strings[108987]="站住！噢，是你吗，$n？那些该死的强盗成天在这里转悠！随便看看吧，但请快一点。"
D.Strings[108988]="等等！等等！有什么新消息吗，$n？大家都在焦急地等待着最新的消息呢。"
D.Strings[108989]="$n！抱歉打扰了，可你收到什么消息了吗？最近总有卫兵跑来跑去的，可他们也说不出所以然来。"
D.Strings[108990]="这边，$n！有什么消息吗？我也没听说什么，但这里的某些人似乎已经崩溃了。"
D.Strings[108991]="街上的氛围就像天空一样阴沉，但希望依然为我们带来了光明。"
D.Strings[108992]="天空已经告诉了我们很多事情，$n。这个时代告诉了你什么？"
D.Strings[108993]="别让别人的行为影响了你。在面对未知事件时，我们必须保持镇静。"
D.Strings[108994]="记住……急于下结论的人或许能够抢先一步，但他们多半到不了想要的终点。"
D.Strings[108995]="抱歉，我最近有点紧张。欢迎光临。"
D.Strings[108996]="议会肯定早有准备了，科尔塔。现在，打起精神来。我们有新客人了。"
D.Strings[108997]="请进！我正在跟科尔塔讨论最近的局势呢。我想听听你的看法。"
D.Strings[108998]="欢迎光临，我们的补给恐怕已经不多了。自从……你知道的……那件事之后，我们就在加班加点地完成订单。"
D.Strings[108999]="不，科尔塔。我觉得没什么可担心的。现在集中精神。别让我们的客人久等了。"
D.Strings[109000]="欢迎，旅行者！外面怎么样了？"
D.Strings[109001]="只要你不抬头看，那就没什么问题。继续！"
D.Strings[109002]="管好你自己的事吧，朋友。"
D.Strings[109003]="末日降临啦，$n！至少他们是这么说的。看上起似乎也的确是那么回事。"
D.Strings[109004]="我不知道你怎么想，但我绝不会穿着普通的法师长袍去见造物主的。"
D.Strings[109005]="想要风风光光地离开的时候，价钱就无所谓了。我已经破产了……但这很快也无所谓了。"
D.Strings[109006]="像你这样的$c来这里做什么，$n？为了迎接众所周知的世界末日，所以来找一件时髦的礼服吗？"
D.Strings[109007]="啊，$n。你正是我要找的$c。喜欢我的新衣服吗？啊——我这是蒙谁呢？这很快就没有意义了。"
D.Strings[109008]="我建议你扔掉那身破玩意儿，换一件更加时髦的衣服。等世界末日来临时，你看着或许会漂亮一些。"
D.Strings[109009]="我们会想办法搞清这一切的。等到行动的时机来临时，相信我们的盟友会做好准备的。"
D.Strings[109010]="不管我手上有什么事情，我都忍不住停下来往天上看。"
D.Strings[109011]="你看到急救站了吗？那里的队伍都排到门外了。"
D.Strings[109012]="你不可能说自己没感觉到。看看我们周围。这个世界都开始自我怀疑了。"
D.Strings[109013]="我们的世界还有多久就会崩溃？"
D.Strings[109014]="头顶的天空每天都在迫近。这难道就没完没了了？"
D.Strings[109015]="我……我控制不住。我试着让自己忙碌起来，可心里总有种感觉……这种感觉……我也不知道该怎么形容。"
D.Strings[109016]="可它是怎么跑上去的？总不可能是凭空出现的吧？"
D.Strings[109017]="你看见他们了吗？那些到处游荡，自言自语的人？"
D.Strings[109018]="不。你不会是以为……那不可能！"
D.Strings[109019]="我很好奇那究竟是什么意思。"
D.Strings[109020]="我不想再回答出什么事了。我开始对自己的回答失去信心了。"
D.Strings[109021]="议会肯定会在适当的时候公布更多的消息。与此同时，请记住越是这种时候，越能够体现一个人的本性。"
D.Strings[109022]="我们对议会失去信仰之时，就是达拉然分崩离析之日。我们必须团结起来，不要为还没有发生的事而战战兢兢。"
D.Strings[109023]="如果这就是末日怎么办？"
D.Strings[109024]="不！你得听我的。我告诉你——你得离开这儿！"
D.Strings[109025]="天知道。我一抬起头，就看见那个怪物挂在上面了。"
D.Strings[109026]="……对，可有些人不知道该期待什么。应该有人以身作则，站出来说点什么，尤其是在这个时候。"
D.Strings[109027]="就像我说的，我不知道他们说了什么，但他们看起来……很担忧。"
D.Strings[109028]="我不清楚他做了什么，但他的行为似乎有点——噢。抱歉我走神了。没事。一切都很好！"
D.Strings[109029]="别让闲言碎语干扰了你的情绪。在这种时候，我们必须保持坚强。"
D.Strings[109030]="别让未知的恐惧压垮你。我们不知道前面会有什么。"
D.Strings[109031]="你说得对。我们不知道前方会有什么。可只要黑暗降临，我们就会共同面对。"
D.Strings[109032]="达拉然之光燃烧得如此耀眼。可一旦黑暗降临，我们的盟友就会严阵以待。我确信这一点。"
D.Strings[109033]="你不……明白……"
D.Strings[109034]="很快，这个世界的心脏将停止跳动。"
D.Strings[109035]="你的勇气会消失殆尽。"
D.Strings[109036]="目标：艾泽拉斯。发现轻度心律不齐，但生命体征处于可接受范围内。已更新事故报告。"
D.Strings[109037]="威胁信号已消除。设施防御度74.39%%。修复中。"
D.Strings[109038]="未发现本地威胁。感谢先前的帮助。"
D.Strings[109039]="威胁已消除。正在配置修复矩阵。"
D.Strings[109040]="萨……格……拉斯……"
D.Strings[109041]="天空熊熊燃烧。黑暗中的……长剑……伤口……灼痛……"
D.Strings[109042]="痛苦的……沙漠。血流……成河。"
D.Strings[109043]="她的情绪很糟糕。我得集中精神，让她进入——呃啊！"
D.Strings[109044]="黑暗泰坦来了！必须阻止他！阿古斯……军团的老巢。她说我们的命运就在那里。"
D.Strings[109045]="告诉我吧，小丫头。是什么刺激了你……"
D.Strings[109046]="这些幻象肯定是她的梦境……她的梦魇。如果我们帮她克服恐惧，艾泽拉斯应该就能向我们传递信息了。"
D.Strings[109047]="有东西触发了防御系统！小心，你有伴儿了！"
D.Strings[109048]="她最近似乎……很烦恼。很难理解。希望你能帮我联络上她。"
D.Strings[109049]="泰坦造了这些大厅，以监护世界之魂。在这里，我能听见她钻石般清澈的声音。"
D.Strings[109050]="好了。这个传送台会带你深入地下，进入凡人从未踏足过的地方……契约大厅！下来吧，我有很多东西要给你看。"
D.Strings[109051]="啊，你就快到了。快去东边山上的造物者悬台。我告诉你怎么进去。"
D.Strings[109052]="勇士！艾泽拉斯需要我们。"
D.Strings[109053]="你们这些瞎子。睁大眼睛好好看看！"
D.Strings[109054]="你成功了！梦魇被阻止了。继续前进，我就在下一个大厅里。"
D.Strings[109055]="我感觉她在恐惧……在猜忌。我们得帮她！有些防御节点失效了。要是能重新激活它们，或许会有帮助！"
D.Strings[109056]="自我修复模块恢复。外部协助评估：感谢。"
D.Strings[109057]="重启序列完成。正在初始化警戒协议。"
D.Strings[109058]="发现异常。启动382115号防御协议。"
D.Strings[109059]="可惜布莱恩没有跟来。我兄弟最喜欢开启泰坦的大门了！"
D.Strings[109060]="到诺森德的索拉查盆地来见我吧。我们要一起搞清楚这件事！"
D.Strings[109061]="我想，她是想向我传达一个信息……一个警告。但她有点不对劲。"
D.Strings[109062]="你好啊，$n。既然梦魇消失了，我们就能听清她想说什么了。下令吧，我们马上开始。"
D.Strings[109063]="她现在平静了一些，但还是很担心。我应该可以联络上她了。$b$b你准备好了吗，$n？"
D.Strings[109064]="让我们听听她怎么说吧，麦格尼。"
D.Strings[109065]="她的噩梦……她巨大的恐惧……我们必须帮忙！"
D.Strings[109066]="别担心，丫头。我们会保护你的。我们必须保护你！"
D.Strings[109067]="如果灭世者还活着，那她就非常危险了。难怪她这么担心……"
D.Strings[109068]="我想离开死亡矿井。"
D.Strings[109069]="不行！"
D.Strings[109070]="你别想从我这儿过去！"
D.Strings[109071]="你别想抢走我的船！小鸟去开炮！猴子去升帆！"
D.Strings[109072]="阴暗的人影从大锅中装了一瓶黏液。"
D.Strings[109073]="力量飞跃！"
D.Strings[109074]="我没时间跟你打机锋。所以，我要拉风地退场了。"
D.Strings[109075]="你最好祈祷我们后会无期。"
D.Strings[109076]="没关系，我已经拿到想到的东西了。"
D.Strings[109077]="那就是我！"
D.Strings[109078]="还有，如果你伤了我的宝贝牛头人一根毫毛，那你就有大麻烦了……"
D.Strings[109079]="好像这种废物真能阻止我们似的……"
D.Strings[109080]="又想来破坏我们的计划吗？哈！"
D.Strings[109081]="嘿，你！你就是那个牛头人说的人！"
D.Strings[109082]="我只能送你到这里了。但愿你的小伙伴们足够强大，能陪你走完剩下的路。"
D.Strings[109083]="死亡矿井里有不少动静。\n\n我怀疑那里已经被各种生物占领了。我们要去调查一下吗？"
D.Strings[109084]="送我去死亡矿井。"
D.Strings[109085]="被邪能腐化的野兽越少越好。"
D.Strings[109086]="军团已经开始腐蚀野兽了。其中有一个就在鱼人的洞穴里。你必须消灭它！"
D.Strings[109087]="伊利丹惨败于黑暗神殿后，我曾试图抛开我的情绪……我的猜忌和怨恨。"
D.Strings[109088]="此刻，敌人正在集结……阴云正在汇聚。从今天起，守护我们的世界和亲人的重任……就交给你了。"
D.Strings[109089]="勇士……我有话要说。"
D.Strings[109090]="我们的世界之魂很痛苦……"
D.Strings[109091]="就算军团覆灭，还会有新的威胁出现。相信你是应对它们的不二人选，哥哥。"
D.Strings[109092]="我寻求力量……但不是为了征服或统治。它只是一种手段……拯救艾泽拉斯的手段。"
D.Strings[109093]="在面对质疑时，只有你能让我排除杂念，坚定前行。泰兰德。"
D.Strings[109094]="你想回现在的希利苏斯时，只要说一声就行了。"
D.Strings[109095]="啊啊！有怪物！"
D.Strings[109096]="你能让我看看变成世界创伤前的希利苏斯是什么样吗？"
D.Strings[109097]="希利苏斯一直吸引着古老、邪恶的力量。\n\n我可以开启一条时光隧道，让你见证曾经雄踞沙漠的黑暗帝国，或是强大军队间的激战。\n\n那么丰富的历史，那么多的痛苦。\n\n但那不着急。我相信你来这里是另有目的的。"
D.Strings[109098]="啊，我见过这个。上一个家伙没能成功。"
D.Strings[109099]="我曾在艾泽拉斯和德拉诺与燃烧军团战斗过，甚至见证过他们的腐蚀是怎么渗透时间流的。\n\n可在通向阿古斯的裂隙打开前，我从未想过他们会邪恶到这种程度。看看他们是怎么扭曲这个世界的……\n\n如果我们不能阻止他们，艾泽拉斯也会变成这样。"
D.Strings[109100]="一个新世界，如果可以这么称呼它的话。$b$b所以这就是军团想要对艾泽拉斯做的……"
D.Strings[109101]="<他似乎在自言自语。>\n\n如果我能反转脉冲频率并将它导入垂直晶塔，我就能……我在说什么呢？这是胡言乱语。"
D.Strings[109102]="<她似乎在自言自语。>\n\n如果我能反转脉冲频率并将它导入垂直晶塔，我就能……我在说什么呢？这是胡言乱语。"
D.Strings[109103]="我也参加过一两次杰德尼大赛，但这些参赛者比我见识过的强多了。我得承认，我都有点嫉妒了！哈哈！"
D.Strings[109104]="多么精彩的一招！"
D.Strings[109105]="考虑到学宫就在我们附近，它们的长势已经十分喜人。再过一个月，它们就能为你的家庭提供终生照明了。再过一年，它们就能充当哨兵了。$b$b<他将手放在附近一块水晶的表面，令它散发出柔和的光芒。>$b$b无论走到哪里，我都能种出最好的水晶。"
D.Strings[109106]="我到现在都不敢相信，我居然又踏上了一个新世界的土地。从德拉诺和外域到被军团占领的世界，我们不断追逐着古尔丹和塔隆戈尔，可它仍然让我透不过气来。阿古斯是一个惨痛的教训，告诫我们绝不能输给燃烧军团。"
D.Strings[109107]="这里人真多！你们在办聚会吗？"
D.Strings[109108]="现形吧，恶魔。"
D.Strings[109109]="<哈顿无动于衷地看着基尔加丹讲话。>"
D.Strings[109110]="你觉得阿克蒙德和维伦到底在争论些什么？"
D.Strings[109111]="这个世界受伤了。它的精华淌进沙漠……就像麦格尼预见的那样。"
D.Strings[109112]="执政团面临着危险！保持警惕！"
D.Strings[109113]="<哈顿握紧了拳头。>$b$b好象有点不对劲。"
D.Strings[109114]="是的，不过我并不清楚是怎么回事。也许并没什么大不了的。"
D.Strings[109115]="嗯……我想你也许是对的。空气好象都变沉重了，有种不祥的感觉，但我说不清是哪里来的。"
D.Strings[109116]="入侵者过来了。不想变成舰队的靶子的话，就碾碎他们！"
D.Strings[109117]="有个基尔加丹的信徒想为它的主子复仇。准备迎接攻击！"
D.Strings[109118]="敌人靠近了。准备。我们要为世界的未来而战。"
D.Strings[109119]="一次伟大的胜利。任何军团爪牙都不能轻视这股力量。"
D.Strings[109120]="我想前往执政团之座（地下城）。"
D.Strings[109121]="|cFFFF0000|Hspell:252508|h[帕拉克希斯号]|h|r到了！快隐蔽！"
D.Strings[109122]="为了强化虚空之光熔炉所做的牺牲是不会被遗忘的。"
D.Strings[109123]="他们真的无穷无尽，我们必须找到彻底阻止他们的方法。"
D.Strings[109124]="紫队获得了皇帝之赐！"
D.Strings[109125]="请救救其他人！"
D.Strings[109126]="你……自寻死路。"
D.Strings[109127]="它孤寂……虚弱……但又美妙！"
D.Strings[109128]="我不会让双界行者干扰我们的行动的。不惜一切代价抓住他。"
D.Strings[109129]="我将回归虚空。"
D.Strings[109130]="他们会不遗余力地腐蚀我和我的同胞。但是，你的到来或许能扭转局面。"
D.Strings[109131]="不，圣光在上，不要让我们的努力白费！"
D.Strings[109132]="伊利丹成了看管黑暗泰坦的狱卒。他的牺牲阻止了军团。终于，燃烧的远征……结束了。"
D.Strings[109133]="我们会用尽阿古斯的最后一点力量将他束缚在此。万神之座将成为萨格拉斯……以及我们自己的牢笼。"
D.Strings[109134]="成功了！阿格拉玛的精华自由了！他回到了兄弟们的身旁。"
D.Strings[109135]="宣誓效忠我吧，让你的人民加入我的事业。"
D.Strings[109136]="哈顿！你不用这么做！"
D.Strings[109137]="现在我不能再躲藏了。帮帮我……否则一切都完了。"
D.Strings[109138]="重生即将到来。灵魂们准备好了吗？"
D.Strings[109139]="这里充满痛苦……和低语。简直难以抵抗！但艾欧娜尔在催促我们前进。"
D.Strings[109140]="众神的灵魂终于自由了，但他们承受了太多的痛苦。就让我稍作停留，安慰他们一下吧。"
D.Strings[109141]="我的兄弟阿古斯即将苏醒。新生的万神殿将协助主人摧毁你们腐臭的世界。但你们活不到那一天了。"
D.Strings[109142]="有点旧了，不过还能用。这些应该够了。"
D.Strings[109143]="军团的要塞随时可能陷落！别让他们休息！不要松懈！"
D.Strings[109144]="钥石还在不断汲取力量。有意思……或许我们可以用它撕开更加庞大的裂隙。"
D.Strings[109145]="跟我想的一样……这块石头枯竭了，但完好无损。它应该还有用。"
D.Strings[109146]="主人……我让你失望了。"
D.Strings[109147]="我自由了……"
D.Strings[109148]="虚空的大军总想在我们的世界建立一个据点。你们的抵抗对维持平衡至关重要。"
D.Strings[109149]="这里的虚空能量失控了。去阻止黑暗之潮，别让它淹没我们。"
D.Strings[109150]="一群光铸者被困在了敌后。我们得救出他们。"
D.Strings[109151]="要小心点，每个世界都充斥着无数恶魔。我们还有很多事情要做。"
D.Strings[109152]="这里是军团的心脏，守卫森严。现在就进攻太过疯狂。我们得多做些准备才能扭转局势。"
D.Strings[109153]="我们将深入阿古斯的心脏，给军团最后一击！"
D.Strings[109154]="够了！这件事过去了。无论有没有圣光之母，我们都得完成任务。"
D.Strings[109155]="别担心，阿古斯破碎的大地上仍有强大的力量。我们只需找到它！"
D.Strings[109156]="太棒了！这里的古树产出了大量含有特殊成分的石化树脂。呃……你不介意帮我弄点样本回来吧，我的朋友？"
D.Strings[109157]="我们也一样。辛多雷曾有一个领袖跟军团达成了交易，试图毒害我们。"
D.Strings[109158]="我要战斗到底。"
D.Strings[109159]="军团一定会不择手段来摧毁我们的世界。"
D.Strings[109160]="废话。我们面对着创造宇宙的原始之力。你会被它们影响并不丢人。这只说明你和它们的契合度很高。"
D.Strings[109161]="你迅速打消了那头恶魔的野心。但其他恶魔肯定还会走上它的老路。"
D.Strings[109162]="我们每打倒一个目标，都是黑暗泰坦的失败。"
D.Strings[109163]="他带来了我们前所未见的力量。"
D.Strings[109164]="可现在，我们不再孤单了。"
D.Strings[109165]="看呐，一个急于证明实力的邪魔。去打消它的野心。"
D.Strings[109166]="有个野蛮的恶魔纠集了大批同类。去让他们明白信错人了。"
D.Strings[109167]="又来了一个军团的勇士。快去了结它。"
D.Strings[109168]="不经过奋战，圣光就无法获胜。今天，你履行了你的职责，勇士。"
D.Strings[109169]="我感觉有个邪恶的存在……它想扑灭圣光。快拿起武器，打倒这个敌人！"
D.Strings[109170]="附近来了一个阴险的黑暗勇士。去打倒它！"
D.Strings[109171]="军团部队涌入了这一区域。把他们赶出去，为了圣光！"
D.Strings[109172]="不久前，巴拉特发射了信号弹。起码他还活着。我还没收到其他人的消息。"
D.Strings[109173]="我们的每一次胜利都会动摇军团的统治。"
D.Strings[109174]="请去找到我们的队长！她到西边去保护我们的最后一座炮台了！"
D.Strings[109175]="我该回维迪卡尔了。我会在那里找到知识桂冠的下落。保重，我的朋友。"
D.Strings[109176]="麦格尼没说谎。阿格拉玛复活成了……萨格拉斯的仆人。"
D.Strings[109177]="阻止她们！泰坦的魔法决不能落入军团之手！"
D.Strings[109178]="看看这些军团的武器。很快，它们就会任我……我们……驱使了！"
D.Strings[109179]="这家伙有野心，但缺乏天赋。"
D.Strings[109180]="一切都将重塑。一切都将毁灭！"
D.Strings[109181]="将火炮对准基尔加丹的船！"
D.Strings[109182]="很好。我们的士兵康复了，我完成了我的工作，而敌人也被削弱了！这就叫共赢。"
D.Strings[109183]="威胁中止。"
D.Strings[109184]="敌方士兵已清除。"
D.Strings[109185]="帕拉克希斯号进场了。"
D.Strings[109186]="没关系。我会搞定的。"
D.Strings[109187]="你的骨头可以作为备用零件。"
D.Strings[109188]="准备被肢解吧。"
D.Strings[109189]="来吧，我们必须深入黑暗。"
D.Strings[109190]="军团的心脏……我很快就会把它挖出来。"
D.Strings[109191]="要想进攻要塞，必须先摧毁那些火炮。你的任务很艰巨，勇士。"
D.Strings[109192]="军团靠攻城火炮集结起了一支大军。伊利丹应该已经到那里去打击他们的阵地了。"
D.Strings[109193]="你做好出击的准备了吗？"
D.Strings[109194]="你在前头开路，我们从地面向要塞推进。"
D.Strings[109195]="你让我教你使用虚空作为武器。现在这件武器归你了。"
D.Strings[109196]="这些可以稍后再想。但它必须死。"
D.Strings[109197]="我派了斥候去侦查军团入侵玛凯雷的规模，可他们没回来。如果他们还活着的话……请找到并帮助他们。"
D.Strings[109198]="|TInterface\\Icons\\SPELL_SHADOW_CURSEOFTOUNGES.BLP:20|t帕拉克希斯号开始|cFFFF0000|Hspell:249934|h[净化]|h|r船上所有的敌人！"
D.Strings[109199]="$n周围凝聚起了疫病能量。"
D.Strings[109200]="下令吧，英雄们，我们马上开始突袭。"
D.Strings[109201]="就捉襟见肘了。消除军团的优势就能为我们创造拯救艾泽拉斯的最佳机会！"
D.Strings[109202]="该走我们自己的路了，朋友。"
D.Strings[109203]="你能回来真是太好了。圣石……发生了一些变化。"
D.Strings[109204]="不愿臣服？那去死吧！"
D.Strings[109205]="|TInterface\\ICONS\\SPELL_SHADOW_PAINSPIKE:20|t一名大型裂隙守护者开始施放|cFFFF0000|Hspell:245164|h[绝望碎片]|h|r！"
D.Strings[109206]="他就毁在缺乏信仰上。邪能将吞噬一切弱者。"
D.Strings[109207]="可悲！烧死他们！"
D.Strings[109208]="啊！该死的女巫！"
D.Strings[109209]="后退，杂种！"
D.Strings[109210]="见证纳斯雷兹姆的力量吧！"
D.Strings[109211]="我们一直在想办法进入此地！想不到是一介凡人帮我们站稳了脚跟。我们会记住你的贡献的！"
D.Strings[109212]="真可惜。他站错了队，浪费了自己的潜力。"
D.Strings[109213]="想想吧，要是这台机器充满我们的力量。有趣……"
D.Strings[109214]="她已经破茧化蝶，成为我们中的一员了。"
D.Strings[109215]="<将你的手放在石头上。>"
D.Strings[109216]="我掌握着宇宙的力量！"
D.Strings[109217]="你的信仰不堪一击。"
D.Strings[109218]="不！我不能失败……"
D.Strings[109219]="军团，让这些废物看看，我们是靠什么统治宇宙的！"
D.Strings[109220]="看来我得亲自出手了！"
D.Strings[109221]="所有战舰，向我的位置集中！"
D.Strings[109222]="$n附近的地面上有一颗疫病能量球。"
D.Strings[109223]="哈！我是最好的杀手！"
D.Strings[109224]="军团还在垂死挣扎，就让我们来为他们送葬吧。回维迪卡尔去，准备致命一击。"
D.Strings[109225]="萨格拉斯想腐蚀其他泰坦！如果不阻止他，万神殿就会在黑暗中重生。别再浪费时间了！"
D.Strings[109226]="阿古斯的核心深处传来了众神的痛苦呻吟。"
D.Strings[109227]="我认识那些军团将军的标识。在萨格拉斯占领我们的世界前，他们都指挥过我们的大军，为阿古斯带来过和平。"
D.Strings[109228]="|TInterface\\Icons\\PRIEST_ICON_CHAKRA_GREEN.BLP:20|t邪能在你体内流淌。"
D.Strings[109229]="如果军团在那里召集援军，那我们必须摧毁它，否则就会被恶魔打垮。"
D.Strings[109230]="利用我的传送门去杀敌吧。快！"
D.Strings[109231]="图拉扬，我开始攻击北线了。我们拖住他们的部队，好让你攻击主要目标。"
D.Strings[109232]="我们正在推进！保持攻势！"
D.Strings[109233]="是的，我是有一个“真名”。但那与你无关。"
D.Strings[109234]="千万记住，偶数面不能闭合。绝对不要搞错了！"
D.Strings[109235]="来吧，跟我聊聊。"
D.Strings[109236]="或许我应该听父母的话，改行去当珠宝匠……"
D.Strings[109237]="如果失败，你们都得没命。守住玛凯雷！"
D.Strings[109238]="老朋友们，很高兴再次见到你们。自从你们在德拉诺的大爆炸中失踪后，我简直不敢多想。"
D.Strings[109239]="你休想折磨我！"
D.Strings[109240]="对！跑吧！跑吧！"
D.Strings[109241]="你逃进了深渊，懦夫！"
D.Strings[109242]="阿古斯必将……崛起……"
D.Strings[109243]="安托鲁斯，我回来了……"
D.Strings[109244]="你们真脆弱，在黑暗中颤抖。"
D.Strings[109245]="能活到现在，你们已经赚了。"
D.Strings[109246]="轰炸本区域！"
D.Strings[109247]="我可以让你暂时保留文凭。"
D.Strings[109248]="奇怪……连幽灵都来听基尔加丹的演讲了，但这事没那么简单。我感觉有恶魔存在。去人群里找到它，不要让它发动伏击。"
D.Strings[109249]="真是神奇，他们居然还是低估了凡人，不是吗？"
D.Strings[109250]="军团想在玛凯雷安营扎寨。尽力干扰他们，让他们收拾烂摊子去吧。"
D.Strings[109251]="你们最好再快一点，凡人！"
D.Strings[109252]="它就藏在执政团之座里。我感觉那里只有黑暗。"
D.Strings[109253]="邪能的真正力量在我体内流淌！"
D.Strings[109254]="你还不懂吗？这是唯一的方法。我会让你懂的！"
D.Strings[109255]="我的生命属于军团！"
D.Strings[109256]="我击溃过无数凡人。你觉得自己会有机会吗？"
D.Strings[109257]="根据协议，我向你告别。"
D.Strings[109258]="我得跟你打招呼。你好。"
D.Strings[109259]="我带来了你订购的邪能页岩。"
D.Strings[109260]="别浪费我的时间。"
D.Strings[109261]="我代表着……一种可能性。"
D.Strings[109262]="我们都有自己的路。选择你的吧。"
D.Strings[109263]="与军团的战斗必须步步为营。我们要品味胜利的甘甜，接受失败的苦涩。"
D.Strings[109264]="圣光军团时刻准备着。"
D.Strings[109265]="道标发出能量的嗡鸣声。"
D.Strings[109266]="但是还有希望，有一件宝物能帮我们占得先机。"
D.Strings[109267]="你……休想……逃跑……"
D.Strings[109268]="萨格拉斯不容抗拒！"
D.Strings[109269]="不要嘲弄我的痛苦！"
D.Strings[109270]="穷追猛打！"
D.Strings[109271]="你的光熄灭了。"
D.Strings[109272]="不！黑暗……是我的……"
D.Strings[109273]="|TInterface\\Icons\\SPELL_FIRE_FELFLAMERING.BLP:20|t金加洛斯强化了|cFFFF0000|Hspell:246779|h[恶魔炸弹]|h|r！"
D.Strings[109274]="塔尔加斯临死前说……连圣光也逃不出去。他是什么意思？"
D.Strings[109275]="军团不会罢休的。小心点。"
D.Strings[109276]="许多人想杀我。可他们都死了，而我还活着！"
D.Strings[109277]="你休想杀掉我！邪能之心会保护我的！"
D.Strings[109278]="Pheta thones gamera。愿圣光指引我们。"
D.Strings[109279]="我们来帮你，维伦。"
D.Strings[109280]="来看看都我干了什么吧。然后，我或许就能正视这一切了。"
D.Strings[109281]="让开。我要亲自解决他们。"
D.Strings[109282]="恶魔在自己的血肉里植入了孢子，以掩盖他们的进攻。去让他们明白，他们最终还是难逃一死吧！"
D.Strings[109283]="立刻出击，勇士们！纳鲁暂时被削弱了！"
D.Strings[109284]="你偷了我的力量！阿古斯不再回应我了！"
D.Strings[109285]="我们会保护维伦找到知识桂冠。"
D.Strings[109286]="我不会熄灭的……"
D.Strings[109287]="对，那个纳鲁。我们得进去，奥蕾莉亚，你学的技巧能打开通道。"
D.Strings[109288]="烈焰又吞噬了一具尸体！"
D.Strings[109289]="没有光能穿透我的阴影。"
D.Strings[109290]="等等，小家伙！别动！"
D.Strings[109291]="我真后悔……接了……这个活儿……"
D.Strings[109292]="你们想靠那些破装备来摧毁我的机器？"
D.Strings[109293]="这是躲不开的话题，可一想到它，我就惶恐。我该怎么向奥蕾莉亚解释我们的姐妹成了一个怪物？真相会让她心碎的。"
D.Strings[109294]="军团会记住我的！"
D.Strings[109295]="这场战斗可不会让你们轻松获胜。"
D.Strings[109296]="一头燃烧的恶魔在深渊中恐吓我们的盟友。立刻去消灭它。"
D.Strings[109297]="温蕾萨，我想知道。我们的姐妹怎么了？"
D.Strings[109298]="骄傲地握紧萨斯多拉吧，勇士。你证明了自己配得上它。"
D.Strings[109299]="温蕾萨告诉我，你参与了她在尼斯卡拉的行动。你曾冒着生命危险来救我，还防止了她落入审判官的陷阱。"
D.Strings[109300]="你要为你的行为付出代价。"
D.Strings[109301]="阿古斯之魂则不同。他很痛苦……崩溃。小心，别让他的痛苦压垮你！"
D.Strings[109302]="这块圣石一直在我们心中低语。想不到你也能听到，外来者。"
D.Strings[109303]="你来干什么？"
D.Strings[109304]="我们要拯救自己的家园。"
D.Strings[109305]="登上炮台，把那些蝙蝠打下来！我们就全靠你了！"
D.Strings[109306]="我们会赢下这场战争的。"
D.Strings[109307]="我或许无法直接帮助你，但我掌握了一些有趣的信息。"
D.Strings[109308]="我还被要求允许外行人参加试炼。"
D.Strings[109309]="学宫资源不对你们中的某个人……开放。"
D.Strings[109310]="黑暗遮蔽了圣光。"
D.Strings[109311]="恐怕……来不及阻止他了……"
D.Strings[109312]="你可以从一条待定任务线中获得此物品。而现在，你可以直接从地上捡到它！"
D.Strings[109313]="你们才是腐蚀之源。为了拯救宇宙，我们要清除你们的存在。"
D.Strings[109314]="来自那个世界的援军中断了，但这只是暂时的。"
D.Strings[109315]="又一个被军团污染的世界。在他们加入阿古斯的战斗前，抢先消灭他们的部队，封印这条裂隙吧！"
D.Strings[109316]="我对你很有信心，$n。你搞定以后就来附近找我。"
D.Strings[109317]="我们必须——"
D.Strings[109318]="你们的骨灰将被吹进宇宙！"
D.Strings[109319]="靠近点，英雄，我要看着你们的血肉剥落！"
D.Strings[109320]="先知维伦很高兴你响应了他的召唤。德莱尼一直在盼着这一天。"
D.Strings[109321]="<艾娜拉给了你一块金色的水晶。>$b$b去放逐黑暗吧，$n。让圣光赢得胜利。"
D.Strings[109322]="警告：你即将掉入一条黑暗裂隙。你可能无法再爬出来。你确定要这么做吗？"
D.Strings[109323]="军团的怒火必将吞噬你们！"
D.Strings[109324]="这就是艾泽拉斯的最强实力吗？"
D.Strings[109325]="这……不……可能……"
D.Strings[109326]="传送门……不能……关闭……"
D.Strings[109327]="这就是跟我们作对的下场。"
D.Strings[109328]="一艘军团运兵舰突然出现在了主入口上方。"
D.Strings[109329]="控制台显示出了一个数字7。"
D.Strings[109330]="控制台显示出了一个数字2。"
D.Strings[109331]="说说那块石头的事吧。"
D.Strings[109332]="你找到它了！真强大……我这里都能感觉到。"
D.Strings[109333]="试炼完成了吗？"
D.Strings[109334]="如果你想知道的话，我曾经是学宫的钥匙保管员，管理着它所有的锁和门。$b$b为了抵抗时间的侵蚀，我将自己的灵魂放进了这个构造体里。这样我就能永远守护者学宫了。$b$b对付你这样的家伙就是我永远的责任。"
D.Strings[109335]="别让激光扫中你。我估计那会很痛的。"
D.Strings[109336]="够了。你证明了自己的实力。"
D.Strings[109337]="觐见高阶启迪者时，你应该鞠躬。"
D.Strings[109338]="啊，大宰相。\n\n他是大执政官的副手，负责管理学宫的日常事务。\n\n每当有人接受训诫时，听到的常常都是他的声音。大家都不怎么喜欢他，但很尊敬他。\n\n据我所知，他在接受军团的邪能魔法后，将自己的名字改成了加拉克苏斯。\n\n除此之外，我就不清楚他的经历了。"
D.Strings[109339]="我无力反抗了。一旦萨格拉斯获胜，众生都将陷入黑暗。"
D.Strings[109340]="勇士们！军团想为他们那可怕的主人来捕获我的精华！"
D.Strings[109341]="我誓死保卫阿古斯！"
D.Strings[109342]="来吧，勇士。帮我护送她前往维迪卡尔。然后我们就离开！"
D.Strings[109343]="我感觉泽拉在中央大厅里。感谢圣光！我们没来迟。"
D.Strings[109344]="拉尔加的不朽之源消失了。你终于能杀掉他，夺回阿古斯邪能之心了。"
D.Strings[109345]="向我敞开灵魂吧。"
D.Strings[109346]="臣服于主人的大军吧！"
D.Strings[109347]="艾泽拉斯必将沦陷！"
D.Strings[109348]="你的父母还活着，阿拉托尔，我肯定。但现在，专心迎接之后的战斗吧。"
D.Strings[109349]="武器装填完毕，目标已锁定。"
D.Strings[109350]="发现敌人。部署武器。"
D.Strings[109351]="道标已放出，先知！"
D.Strings[109352]="你受伤了吗？看起来似乎还好。我相信，一顿美餐马上就能让你生龙活虎起来。"
D.Strings[109353]="该死，反抗啊！"
D.Strings[109354]="阿拉托尔！图拉扬！？"
D.Strings[109355]="圣光在上……"
D.Strings[109356]="让这件武器过载会把恶魔吸引过来的。"
D.Strings[109357]="你休想躲在黑暗中！"
D.Strings[109358]="你们必须付出代价，邪魔！"
D.Strings[109359]="不！你看到的只是谎言！"
D.Strings[109360]="很抱歉让你变成这样。安息吧。"
D.Strings[109361]="嗯……跟紧我们！"
D.Strings[109362]="<破译员毫无生气的眼睛瞪着天空。她的身下压着一本薄薄的册子。>"
D.Strings[109363]="这里的水被诅咒了，不要乱喝。"
D.Strings[109364]="我们发现了你的信息。"
D.Strings[109365]="我发现了一个幸存者。快过来。"
D.Strings[109366]="我们一直在默默蛰伏，不断适应。在我们有需要时，这片土地仍然会回应我们的祈求。"
D.Strings[109367]="有一条近路。我们能用自己的力量帮你。"
D.Strings[109368]="他们的离开让我心痛，温蕾萨阿姨。我等待多年，不能在这个时候失去他们。"
D.Strings[109369]="你先攻击。"
D.Strings[109370]="道标已着陆。小心点，先知。"
D.Strings[109371]="来吧，勇士。让圣光指引你！"
D.Strings[109372]="你自己是怎么做到的？"
D.Strings[109373]="对，这个样本应该可以。"
D.Strings[109374]="我的头……有点晕。"
D.Strings[109375]="湮灭……在召唤。"
D.Strings[109376]="拥抱虚空吧。"
D.Strings[109377]="这超出了你的能力，凡人。"
D.Strings[109378]="啊……暗影降临了！"
D.Strings[109379]="你身边的圣光如此闪耀。你又怎么能拥抱暗影呢？"
D.Strings[109380]="阿坎恩……干了什么？"
D.Strings[109381]="他们会追杀我们的。暗影知道我们在反抗他们。回头，快回头！"
D.Strings[109382]="愿圣光宽恕。"
D.Strings[109383]="死神拥抱了我。"
D.Strings[109384]="圣光……必败。"
D.Strings[109385]="黑暗在号令我。听从召唤吧！"
D.Strings[109386]="等待结束了！向先知复仇！"
D.Strings[109387]="我一直在……等待……安息。"
D.Strings[109388]="为什么……这么黑？"
D.Strings[109389]="我们要坐着它前往地表。小心点。"
D.Strings[109390]="快去暴风城港口吧。我们的机会来了，去结束这场战争吧。"
D.Strings[109391]="我不在乎阿古斯有多么恐怖。只要有机会在那里找到奥蕾莉亚，我就跟你们去。"
D.Strings[109392]="我得完成未尽的任务，双界行者。"
D.Strings[109393]="他们可真是勤劳。可惜他们注定失败。"
D.Strings[109394]="先说说你的目的吧。"
D.Strings[109395]="阿坎恩想起来了。埃索隆在召唤！星光将再次照亮它！"
D.Strings[109396]="你……休想……击溃我们！"
D.Strings[109397]="奥蕾莉亚？"
D.Strings[109398]="<含糊不清的祈祷声。>"
D.Strings[109399]="执政团之冠是一个管道，能够融合我们的力量。我们每个人都拥有三分之一的部件。"
D.Strings[109400]="我的技师们对此早有准备。"
D.Strings[109401]="今天就是你的死期，恶魔！"
D.Strings[109402]="你们就这点本事吗？真可悲……"
D.Strings[109403]="幽灵……都是那一天牺牲的人。"
D.Strings[109404]="那我们就行动吧，大主教。"
D.Strings[109405]="这声音……哈顿？你是怎么在这个地狱里活下来的？"
D.Strings[109406]="出来吧。"
D.Strings[109407]="蠢货！你所知的军团体现不了我们真正的辉煌。"
D.Strings[109408]="索林小子，找到那头偷走我们塞拉摩麦酒的野猪！"
D.Strings[109409]="这块水晶……发出了熟悉的声音。"
D.Strings[109410]="但回忆就到此为止吧。我留下的水晶里其实有三条口信。最后一条是给你的，勇士。"
D.Strings[109411]="我感觉这块水晶上有巫术存在。"
D.Strings[109412]="你为梦想中的艾泽拉斯奋斗了一生。现在，你必须为现实中的它而战了。"
D.Strings[109413]="我已看清了我的命运和责任。保卫世界的重任就交给你……和我哥哥了。"
D.Strings[109414]="|TInterface\\ICONS\\ABILITY_WARRIOR_COLOSSUSSMASH.BLP:20|t加洛西灭世者往后一倾，准备施放|cFFF00000|Hspell:244969|h[根除]|h|r！快跑！"
D.Strings[109415]="好了，各位……坚持住！"
D.Strings[109416]="那个所谓的全视者派他的爪牙来杀我了？哈！"
D.Strings[109417]="看来哈克穆德不想看到跟他同名同姓的任何东西。再见！"
D.Strings[109418]="<回忆泽拉的复活>"
D.Strings[109419]="全力出击！不要对这些恶魔手软！"
D.Strings[109420]="伊利达雷！给这些恶魔一个痛快吧。"
D.Strings[109421]="伊利达雷！燃烧军团正在靠近！"
D.Strings[109422]="恶魔过来了。我们得尽力拖住他们！"
D.Strings[109423]="Pheta thones gamera。他们来了！"
D.Strings[109424]="恶魔！来了！立刻撤到安全地带去！"
D.Strings[109425]="所有人立刻撤回维迪卡尔！"
D.Strings[109426]="魔术师瓦西里恩带着那些重塑物品去哪儿了？"
D.Strings[109427]="所以凡人就是这么传承技艺的？有意思……"
D.Strings[109428]="<你用眼角的余光扫到了奥蕾莉亚。她正在盯着你的弓看。>"
D.Strings[109429]="我很高兴卡德加选择陪你一起来。在你的队伍中，我只认识他一个人。真的已经过去那么久了吗？$b$b<图拉扬将目光从你身上移开。>$b$b哈！他真是一点都没变。一提到他，他就……"
D.Strings[109430]="<奥蕾莉亚朝你苦笑。>$b$b又是阿古斯美好的一天。$b$b不过，现在能在空中看到家乡了，这让我心中充满了希望。回家再不是一个遥不可及的梦，而是必将到来的现实。"
D.Strings[109431]="我们是来支援你的。祝你好运，勇士。"
D.Strings[109432]="我简直不敢相信我们的世界遭遇了什么。$b$b看看外面，我只能看到仇恨和荒芜。$b$b我有些庆幸自己必须待在维迪卡尔上。我可不想踏上那片被诅咒的土地。$b$b我已经锁定了我们下方的坐标，这个距离很近，足以让你设置传送器了。你准备好之后，就告诉我一声吧。"
D.Strings[109433]="经历了漫长岁月的风霜洗礼，墨迹已经无法辨识了。"
D.Strings[109434]="很久以前，安尼赫兰深渊里枯瘦的奴隶发起过一场起义，让克罗库恩的人民摆脱了束缚。$B$B这些镣铐提醒着克罗库恩的居民，只有反抗才能保留自由的希望。"
D.Strings[109435]="我希望能被选去当启迪者。灵魂束缚是种神奇的魔法，而且我已经习惯跟警卫们合作了。或许有一天，我也能够成为他们中的一员，就像夸拉姆那样。\n\n话又说回来，我也喜欢美食……还是算了吧……"
D.Strings[109436]="他们真魁梧！轰！啪！砰！\n\n<奈丽兴高采烈地模仿着他们的动作。>"
D.Strings[109437]="看看这个，$c。一艘由圣光驱动的飞船，还有一支强大且像精灵一样长寿的军团。这股力量确实配得上这次远征。"
D.Strings[109438]="这些光铸德莱尼一辈子都在跟军团斗争。也许连我都能从他们身上学习一二。$b$b我是说也许。"
D.Strings[109439]="但愿奥露乐还在坚持练习。我给她开列了一张每天的训练清单。$b$b你也有兴趣？很简单。每天一百个俯卧撑、一百个仰卧起坐和一百个深蹲，然后跑上一万九百三十六码。"
D.Strings[109440]="<驻足聆听。>"
D.Strings[109441]="|TInterface\\Icons\\SPELL_NATURE_SLEEP:20|t%s用|cFFFF0000|Hspell:254244|h[催眠气罐]|h|r瞄准了你！"
D.Strings[109442]="<观看生命缚誓者的恳求。>"
D.Strings[109443]="<看来她的守望终于结束了。>"
D.Strings[109444]="啊哈哈哈哈！今天我真是走运！"
D.Strings[109445]="为什么一个虚灵会跟一船的德莱尼一起旅行？"
D.Strings[109446]="啊哈哈！都是我的！都是我的！"
D.Strings[109447]="你怎么敢做这样的猜测！"
D.Strings[109448]="属于我们的命运终于到来了！荣耀属于艾瑞达！"
D.Strings[109449]="看到这么多熟悉的面孔是件好事。很多人都是来听基尔加丹讲话的。"
D.Strings[109450]="军团失败了，萨格拉斯也被囚禁了。可他的含恨一击可能会毁了我们。"
D.Strings[109451]="你也许遇到了什么情况，陌生人。保持警惕。"
D.Strings[109452]="我有种若有所失的感觉，但说不上是为什么。不用担心。"
D.Strings[109453]="<他向另一个方向看去。>$b$b肯定出了什么大事。我想要跑，但我的腿动不了了。"
D.Strings[109454]="军团以为这里固若金汤。我们要证明他们错了！"
D.Strings[109455]="真快。对军团的每次打击都能为我们增加胜算。"
D.Strings[109456]="光与影都具有毁灭的力量。对于你眼前这个敌人，随意选择你喜欢的武器吧。"
D.Strings[109457]="每打倒一个这样的敌人，我们就离胜利又近了一步。"
D.Strings[109458]="看来你选好了武器。我也一样。"
D.Strings[109459]="我想传送到寂灭者阿古斯那里。"
D.Strings[109460]="我在梦中看到你们的世界……被毁灭了！"
D.Strings[109461]="|TInterface\\Icons\\ABILITY_THUNDERKING_LIGHTNINGWHIP:20|t女巫会正准备施放|cFFFF0000|Hspell:246763|h[高戈奈斯之怒]|h|r！"
D.Strings[109462]="紫队赢得了皇帝之赐！"
D.Strings[109463]="<战争机甲发出能量的嗡鸣声，随时能够投入战斗。>"
D.Strings[109464]="湿地蹒跚者陷入了邪能狂怒，摆脱了腐蚀者的控制！"
D.Strings[109465]="他们在这里动用了全部力量。真不愧是燃烧军团。$b$b非常好。"
D.Strings[109466]="局势很严峻。$b$b从这里直接发动攻击的代价太高了。而且，城墙上那些火炮非常强大，足以击落维迪卡尔。$b$b我建议利用这座要塞来发动游击战。刺杀他们的重要领袖，在他们的部队中间制造破坏。$b$b我知道这不是你和图拉扬想要听到的，但耐心的猎人必须懂得见机行事。"
D.Strings[109467]="欢迎来到阿古斯的心脏。"
D.Strings[109468]="金队获得了皇帝之赐！"
D.Strings[109469]="这玩意儿还不坏，但是把豆子丢进水里就号称这是饮料也太可惜了。我要把这些咖啡带回著名的雷酒部族让他们试试。想象一下吧，一桶加上了这些咖啡豆的陈年美酒……"
D.Strings[109470]="暗影。"
D.Strings[109471]="%s的宠物科尔宾想要戳你的眼睛。"
D.Strings[109472]="来自邪能……归于邪能。"
D.Strings[109473]="真巧，我的宠物们都饿了。"
D.Strings[109474]="那个？那只是我召唤出来的传送门，能够让你安全地往返达拉然。$B$B天知道我们什么时候会需要援军！"
D.Strings[109475]="记住……这改变不了……什么。"
D.Strings[109476]="这把钥匙已经重铸了。拿着它，去夺回武器库吧。"
D.Strings[109477]="我们的故乡……它怎么了？"
D.Strings[109478]="圣光军团的兄弟们正等着我们。我们必须团结才能取得胜利。"
D.Strings[109479]="黑暗传送门正在撕裂现实，让黑暗能量涌入我们的位面。去阻止它们，英雄们！"
D.Strings[109480]="一个来自虚空的存在出现在我们的世界。决不能让它肆意散播腐蚀。"
D.Strings[109481]="我赞赏你的英勇。在战场上，每一个士兵都很宝贵。"
D.Strings[109482]="我们要将军团赶出所有被亵渎的世界。这只是个开始！"
D.Strings[109483]="准备完毕。快，发射主炮！"
D.Strings[109484]="我在想……不，这不可能……"
D.Strings[109485]="我们还有任务，我们还有世界要去拯救。我们必须前行！"
D.Strings[109486]="我们团结了起来，在艾泽拉斯争取一席之地。我们还意识到自己需要盟友。"
D.Strings[109487]="打得好。恶魔大潮只会在我们剑下崩溃！"
D.Strings[109488]="我们要冲进庭院，迅速解决他们。为了艾泽拉斯！"
D.Strings[109489]="占领此地能争取到宝贵的时间，为总攻安托鲁斯做好准备。"
D.Strings[109490]="一头恶魔对维迪卡尔发起了冲锋。它的死亡将向敌人传达强烈的警告。"
D.Strings[109491]="干得好。这下恶魔就会退缩了！"
D.Strings[109492]="此地有一个必须打倒的目标。你可以随意选择合适的武器。"
D.Strings[109493]="虽然无法再在此繁衍生息，但阿古斯是我们的故乡。至少我们今天不用辛苦了，外来者。"
D.Strings[109494]="你这是自寻死——<停顿>怎么了？我否定你什么了吗？哼。你根本不懂真正的渴望。"
D.Strings[109495]="一定要成功。"
D.Strings[109496]="再大的牺牲也是值得的。"
D.Strings[109497]="我得承认，你的话让我松了口气。我还担心只有我才这么觉得呢。"
D.Strings[109498]="我感觉到一个拥有强大力量并且充满恶意的个体。必须打倒这个恶魔！"
D.Strings[109499]="决定性的胜利。你没让我失望。"
D.Strings[109500]="无论他们派出多少怪物，我们都会杀光他们。"
D.Strings[109501]="有威胁在靠近。去消灭它，让恶魔明白，别跟我们作对。"
D.Strings[109502]="他为我们指出了新的未来。"
D.Strings[109503]="在漫长的旅途中，我们遗失了太多传统。但玛凯雷的幽灵还没忘。直到今天，杰德尼还在举行着格斗仪式。他们或许会欢迎新的挑战者！"
D.Strings[109504]="又一个大言不惭的恶魔勇士。去让它闭嘴。"
D.Strings[109505]="到处都是恶魔。去吧，去战斗！一个不留！"
D.Strings[109506]="虽然军团很残酷，但恶魔别想逃脱圣光的制裁。"
D.Strings[109507]="这个恶棍亵渎了我失落已久的故乡。去结束他的暴行吧！"
D.Strings[109508]="你战斗时的英姿就好像已经和军团斗争了一千年。"
D.Strings[109509]="我们为生存而战。"
D.Strings[109510]="它比风声更微弱，但我觉得很熟悉。它就像艾泽拉斯的召唤，可……那不是她。"
D.Strings[109511]="军团想要夺取这个燃烧世界的力量。决不能让他们成功。"
D.Strings[109512]="看来他们还没找到维伦……但也没放弃。"
D.Strings[109513]="我是圣光之剑！"
D.Strings[109514]="军团占领了这片森林。去赶走他们。"
D.Strings[109515]="机会来了。结束战斗吧！"
D.Strings[109516]="你把他们赶回去了！继续进攻！"
D.Strings[109517]="又一次胜利，英雄们。恶魔都逃出这个世界躲起来了。"
D.Strings[109518]="阿古斯的泰坦之魂是打败军团的关键。我们得坚持到摧毁它为止……否则萨格拉斯就赢了。"
D.Strings[109519]="他觉得我需要帮助？就为了对付军团？好吧……别掉队。"
D.Strings[109520]="守住防线。终止这场入侵！"
D.Strings[109521]="我们就在他倒下的中庭集合。祝你好运。"
D.Strings[109522]="那些声音更响亮、更紧迫了。但是，它们控制不了我。"
D.Strings[109523]="只要他一死，我就打开通道。"
D.Strings[109524]="我们得找到她的灵魂。可怎么找？"
D.Strings[109525]="废物。我会让你们明白自己大错特错了。"
D.Strings[109526]="这就是你拒绝的力量！"
D.Strings[109527]="玛凯雷……只剩下这些了。"
D.Strings[109528]="看呐！实质化的痛苦！"
D.Strings[109529]="痛苦在黑暗中等着你！"
D.Strings[109530]="这才是真正的美！你们这些凡人中总算有一个能欣赏它的人了。"
D.Strings[109531]="这里充满潜力，可都浪费在了无谓的远征上。"
D.Strings[109532]="萨格拉斯想组建黑暗万神殿！我们得抢在阿格拉玛之前找到艾欧娜尔之魂！"
D.Strings[109533]="那个钻石小矮子在圣石大厅里等你。他很……悲伤。"
D.Strings[109534]="受宠若惊吧！你们将参加我的终极武器测试！"
D.Strings[109535]="请允许我介绍我的最新发明。"
D.Strings[109536]="我行走于星辰间的虚空，在我面前，你们能有什么胜算？"
D.Strings[109537]="那个堕落者休想亵渎这副铠甲！"
D.Strings[109538]="希望你们喜欢我的发明。"
D.Strings[109539]="炮手们，集火我标记的目标！"
D.Strings[109540]="结束了，凡人。你们的脑袋值一大笔赏金，我就是为此而来的。"
D.Strings[109541]="$n附近的地面上有一颗奥术能量球。"
D.Strings[109542]="这点残骸勉强够用！"
D.Strings[109543]="你们的骨头会帮我大赚一笔的。"
D.Strings[109544]="很好，很好，我就知道你们会来的。我正缺试验品呢。你们一定能担此重任！"
D.Strings[109545]="军团的阵型崩溃了，但依然兵力充足。我的部队会把他们拖在这里。"
D.Strings[109546]="勇士们，打倒那个怪物！"
D.Strings[109547]="维迪卡尔会尽量吸引火力，图拉扬，但我们坚持不了多久。你得瓦解他们的防线！"
D.Strings[109548]="我们攻破了城墙！"
D.Strings[109549]="姐妹是种复杂的生物。尤其是亡灵姐妹。"
D.Strings[109550]="他们在撕裂诺甘农的心智！"
D.Strings[109551]="我等待了那么久……"
D.Strings[109552]="我将在阿古斯的烈焰中重生。"
D.Strings[109553]="你成功了，勇士！来吧，我们去泽尼达尔救泽拉！"
D.Strings[109554]="见证燃烧王座的力量吧！"
D.Strings[109555]="向我的位置开火！"
D.Strings[109556]="<奥术回响遮罩>"
D.Strings[109557]="这些徘徊的幽灵还有许多未解之谜。他们为什么滞留此地？又为什么要抵制我们？研究他们的精华或许能让我们找到答案。"
D.Strings[109558]="黑暗不断从这里涌出，凝结成纯净的虚空水晶。影卫对这种资源垂涎欲滴。我们得抢先得到它。"
D.Strings[109559]="能够证明身份的部分可得保持完整。"
D.Strings[109560]="执政团之冠复原了！"
D.Strings[109561]="挑衅是不可容忍的！"
D.Strings[109562]="我有义务为你服务。"
D.Strings[109563]="怎么样，$n？我能帮你什么忙吗？"
D.Strings[109564]="你无法拒绝这份礼物！"
D.Strings[109565]="如此……强大。"
D.Strings[109566]="|TInterface\\Icons\\SPELL_FIRE_FLAMETOUNGE.BLP:20|t金加洛斯强化了|cFFFF0000|Hspell:248475|h[轰鸣之击]|h|r！"
D.Strings[109567]="记得留意那些被邪能包裹的草药。里面可能仍然存在星辰之耀。"
D.Strings[109568]="只要你能走路，就能战斗。"
D.Strings[109569]="让圣光烧灼你们的灵魂！"
D.Strings[109570]="哈！你来的太迟了。什么都逃不出那座圣殿。圣光也不能。"
D.Strings[109571]="|TInterface\\ICONS\\SPELL_FIRE_TWILIGHTNOVA:20|t总督奈扎尔开始施放|cFFFF0000|Hspell:248736|h[永恒暮光]|h|r！"
D.Strings[109572]="我戳到你的痛处了吗？"
D.Strings[109573]="即使这样的泥沼也掩盖不了军团的恶臭。去撕碎他们！"
D.Strings[109574]="吸干传送门能量！纳鲁的弱点能成为你的力量！"
D.Strings[109575]="邪能之心充斥着阿古斯的能量。我很快就能无敌了！"
D.Strings[109576]="你来得真及时。我们得找到知识桂冠。如果让塔尔加斯得到它就糟了。"
D.Strings[109577]="我感觉里面散发出强烈的绝望。鲁拉……"
D.Strings[109578]="是基尔加丹的船。即使已经坠毁，它依然讨厌。去清除它造成的破坏吧。"
D.Strings[109579]="安静。村子掩盖了我们的存在。没有人会来伤害我们的。"
D.Strings[109580]="剑圣特拉蒙简单地点点头。"
D.Strings[109581]="正在萃取"
D.Strings[109582]="你们的脑袋将成为我的战利品。"
D.Strings[109583]="<这位守备官喘着粗气，脓液不断从他的钉锤和盾牌上滴落。>$b$b怎么了？"
D.Strings[109584]="<传达法瑞娅的命令。>"
D.Strings[109585]="我的战场上没有你们的位置。"
D.Strings[109586]="斥候找到了阿苟纳的遗体。这多亏了你和这个外来者，大主教。"
D.Strings[109587]="军团不会放松，我们也一样。"
D.Strings[109588]="他们会一个一个明白，这场远征多么愚蠢。"
D.Strings[109589]="不可能！我不相信她会成为部落的领袖。他们曾对我们的人民犯下累累罪行。"
D.Strings[109590]="显然你的技巧和头脑足以驾驭萨斯多拉。你为这把弓带来了荣耀，它从前的主人也会欣慰的。"
D.Strings[109591]="<阿古斯邪能之心>"
D.Strings[109592]="轻浮的外来者。傲慢会毁了你的。"
D.Strings[109593]="你真慷慨。"
D.Strings[109594]="我最不想见到的人成了守门人……$n，还是由你去交涉比较好。"
D.Strings[109595]="非常感谢。我能找到路的。"
D.Strings[109596]="倒下吧，凡人！"
D.Strings[109597]="|TINTERFACE\\ICONS\\INV_STONE_05.BLP:20|t你的枯竭的裂隙石变成了|cFFFF0000|Hitem:151702|h[充能的裂隙石]|h|r！"
D.Strings[109598]="凡人。为了防止你们被腐蚀，我白白战斗了数千年。直到最近，我才看清真相。"
D.Strings[109599]="我得承认，这些试炼给我带来了很多……乐趣。"
D.Strings[109600]="主电源开启！"
D.Strings[109601]="环境公正！"
D.Strings[109602]="灌注"
D.Strings[109603]="魔蝠开始飞向艾欧娜尔的平台！"
D.Strings[109604]="我们或许无法让他们恢复清醒，但能防止更多人被控制。"
D.Strings[109605]="军团已经毁灭了一千个世界。你们的也不会例外。"
D.Strings[109606]="你们的世界必将陨落……"
D.Strings[109607]="看，克索诺斯，一个地狱火与枯骨的世界！"
D.Strings[109608]="你们就这点本事？哈。真可悲。"
D.Strings[109609]="末日女武神泰勒斯塔正在组建恶魔大军。不能让她得逞。"
D.Strings[109610]="|TInterface\\ICONS\\SPELL_WARLOCK_DEMONICPORTAL_PURPLE:20|t上层虚空裂口出现了一条虚空裂缝！"
D.Strings[109611]="它的目标就是干掉你。祝你好运。"
D.Strings[109612]="你准备好接受坚韧试炼了吗？"
D.Strings[109613]="一千个世界的大军都来对抗你们。你们死定了！"
D.Strings[109614]="干得好。维迪卡尔又安全了。"
D.Strings[109615]="道路肃清了。开火！"
D.Strings[109616]="艾娜拉，控制住这些幽灵。"
D.Strings[109617]="我们会保护你的，生命的缚誓者。"
D.Strings[109618]="这点力量不过是冰山一角。"
D.Strings[109619]="来吧，让萨格拉斯的走狗看看，他们招惹了什么人。"
D.Strings[109620]="每当我的猎物跑掉时，我也有这种感觉。不过它们通常只是垂死挣扎而已。"
D.Strings[109621]="严重系统故障……"
D.Strings[109622]="在见识过诱惑了我们兄弟的力量后，我们中只剩下少数人还掌握着真正的魔法。我会利用一切能够获得的优势。"
D.Strings[109623]="我们的部队会夺回泽尼达尔。虽然我们找回了最珍贵的东西，但也不能让这艘船落入军团之手。"
D.Strings[109624]="将塔布羊交给森林入口处的克罗库！"
D.Strings[109625]="半神的心脏。这不仅仅是个象征，奥蕾莉亚。"
D.Strings[109626]="我不会屈服！你休想占据我！"
D.Strings[109627]="集中精神。想想你受过的训练。"
D.Strings[109628]="我们会坚守阵地的。但愿圣光军团还有幸存者。"
D.Strings[109629]="很快，军团就会蜂拥而至。"
D.Strings[109630]="海滩搞定了。再试一次。"
D.Strings[109631]="遵命，大审判官！"
D.Strings[109632]="如他们所愿。"
D.Strings[109633]="你白费力气，蝼蚁！"
D.Strings[109634]="法瑞娅！你还活着！"
D.Strings[109635]="一切都将毁灭！……只有虚空长存。"
D.Strings[109636]="<拿起信函>"
D.Strings[109637]="可是……你们为何不联系我们？联系同胞？联系我？"
D.Strings[109638]="这太疯狂了！"
D.Strings[109639]="该死的虚空，它感染了动物！"
D.Strings[109640]="别让那孩子久等了。"
D.Strings[109641]="|TInterface\\Icons\\ability_priest_pathofthedevout:20|t%s开始施放|cFFFF0000|Hspell:244509|h[萨格雷的羁绊]|h|r。"
D.Strings[109642]="一条隧道！难怪你们能生存下来……"
D.Strings[109643]="我们得团结起来，才能打败军团，酋长。现在，我们的朋友正身处险境。"
D.Strings[109644]="别让它靠近我们！用你的魔法！"
D.Strings[109645]="它很危险，姐妹们。控制住！"
D.Strings[109646]="小心点。我们去找其他人，为之后的战斗做准备。"
D.Strings[109647]="执政团之末"
D.Strings[109648]="先知维伦就在前面，勇士。"
D.Strings[109649]="没错，伊利丹。这可能是我们占得先机的最佳机会。"
D.Strings[109650]="尚不可用"
D.Strings[109651]="坚强点，兄弟姐妹们。我们得拖住他们，直到其他部队抵达。为了艾泽拉斯！"
D.Strings[109652]="我的道路指引我前往执政团之座……命运在那里等着我。"
D.Strings[109653]="在那之前，我会盯着你的进度。"
D.Strings[109654]="啊，好吧，我改天告诉你。在那之前，我会关注你的进展。"
D.Strings[109655]="记住……只要还能自控，你就能控制这股力量。它就无法控制你。"
D.Strings[109656]="准备了，奥蕾莉亚。你的朋友会吸引它的注意。"
D.Strings[109657]="就连纳鲁也会……陨落……"
D.Strings[109658]="拥抱萨格拉斯！"
D.Strings[109659]="我还以为起码能在此找到一个有潜力的灵魂呢。"
D.Strings[109660]="召唤你的不是埃索隆！等等！"
D.Strings[109661]="那么，你为什么没变成那样？"
D.Strings[109662]="我们要阻止低语。尖耳朵应该明白的。"
D.Strings[109663]="记住，你们并不孤独。救赎就在外面的某处。"
D.Strings[109664]="沿着山梁走就能抵达深渊了。小心点，待会儿见。"
D.Strings[109665]="我们一起打倒这头野兽吧。"
D.Strings[109666]="是的，先知。"
D.Strings[109667]="<维伦大喊一声。>"
D.Strings[109668]="数百年前，我就站在这个地方，召唤德莱尼追随我。现在，我又来到这里寻找其他的碎片。"
D.Strings[109669]="重新获得执政团之冠后，我们就能避免重蹈泽尼达尔的覆辙。"
D.Strings[109670]="我们可以离开了，先知维伦。"
D.Strings[109671]="我都习惯从各种恶魔的手里把你救出来了。"
D.Strings[109672]="奥蕾莉亚！你总是那么准时。"
D.Strings[109673]="我准备好与你并肩战斗了。"
D.Strings[109674]="我上次见到这个地方时，满脑子想的都是逃走。塔尔加斯，我最信赖的顾问，背叛了我。"
D.Strings[109675]="等等……有情况。"
D.Strings[109676]="玛凯雷曾是艾瑞达文明的巅峰。"
D.Strings[109677]="我们都愿意为此而献身。不是我们终结军团的远征……就是他们毁灭我们。"
D.Strings[109678]="这座小屋……很眼熟。"
D.Strings[109679]="我们的阵线越来越涣散了。杀掉他们的指挥官，以免我们溃败！"
D.Strings[109680]="我们守不了这条阵线多久了。"
D.Strings[109681]="我要追到那些巨魔的洞穴里去，找到风暴战锤烈酒！"
D.Strings[109682]="永恒之井。我不是个感性的人……可我在多年前制造的这口力量之泉最能体现我对艾泽拉斯的奉献。"
D.Strings[109683]="你见证过我的过去，英雄。我想请你帮我完成最后的心愿。"
D.Strings[109684]="但现在不是考虑个人遗憾的时候。我们必须治愈世界，勇士。"
D.Strings[109685]="可是……我们也有过共同的目标，为共同的事业奋斗过。那是段美好的日子。"
D.Strings[109686]="我的一生中，曾两次见证世界崩裂。我祈求月亮母亲不要让我再见到第三次。"
D.Strings[109687]="玛法里奥……我们还在子宫里时就争斗不休。这斗争贯穿了我们的一生。"
D.Strings[109688]="泰兰德……很久以前，你那么信任我，甚至愿意将我放出牢笼。"
D.Strings[109689]="虽然我无法忍受你的酋长的所作所为，$r，但我们必须并肩战斗，拯救我们的世界。"
D.Strings[109690]="你要把哈克穆德留在这里吗？"
D.Strings[109691]="<回想另一段历史>"
D.Strings[109692]="<回忆萨格拉斯之墓的事件>"
D.Strings[109693]="给这些恶魔一个痛快。"
D.Strings[109694]="坚守阵地，伊利达雷！恶魔来了。"
D.Strings[109695]="恶魔来了！做好准备！"
D.Strings[109696]="恶魔来了！快去维迪卡尔！"
D.Strings[109697]="撤退！这里已经不安全了。"
D.Strings[109698]="瓦西里恩？他说要去找新商品，所以到阿古斯的维迪卡尔上去了。"
D.Strings[109699]="这里出什么事了，先知？"
D.Strings[109700]="别管我，我只是在观察你的一举一动。"
D.Strings[109701]="看来你对我们的战争机甲很感兴趣，勇士。它们是可怕的战争机器，能够制造和承受大量伤害。它们甚至可以飞行。但为了避免吸引军团的注意，我们得保持低调。"
D.Strings[109702]="维迪卡尔真是圣光的奇迹，代表着艾端达曾经的文明，也代表着德莱尼人的现在。不过并不是所有的房间都像这间一样宏伟。有些房间的空间有限。"
D.Strings[109703]="那么多恶魔，那么多靶子……"
D.Strings[109704]="但愿六人议会的其他成员一切安好。我是说，他们当然不会有事的。他们可都是强大的大法师！对。这样很好。"
D.Strings[109705]="这些光铸者似乎被灌注了圣光的精华。难怪他们如此强大，能够与燃烧军团抗衡。"
D.Strings[109706]="碧绿的魔火吞噬了我们的家园。过了很久，燃烧军团又打开了一道通往新世界的大门。那片繁盛而原始的土地让军团的恶魔们燃起了前所未有的征服欲望。\n\n就在他们的部队整装待发时，一个绿色皮肤的战士从那道大门中走了出来。他的手中只拿着一把利刃，踏上战场之前只发出了一声雄壮的战吼。\n\n他在恶魔的军阵中留下了一片尸山血海。那目空一切的姿态最终引起了黑暗之王的注意，黑暗之王想要亲眼见证他的死亡。\n\n战士临终前劈出了最后一击，那一击会让人永远铭记。"
D.Strings[109707]="有趣的小游戏，不是吗？我想我们确实需要这样基本的仪式，来提醒自己已经走过了多远的路。阿古斯有太多值得自豪的东西了。"
D.Strings[109708]="我参与了这次锦标赛的奖品挑选工作。相信我们的胜利者一定会对那些奖品满意的。"
D.Strings[109709]="我要管它叫拍拍！"
D.Strings[109710]="这里就将成为军团的葬身之地。圣光与我们同在。"
D.Strings[109711]="只有被遮罩选中的人才能拥有这份宝藏。"
D.Strings[109712]="要是欧库勒斯能来就好了。他肯定会花上一整天来研究这艘飞船的。$b$b……$b$b说不定他现在都能研究出摧毁它的办法了。你说的对，他或许还是不要跟来比较好。"
D.Strings[109713]="又一个想要为我效忠的人？眼睛越多，全视者能看到的就越多。"
D.Strings[109714]="可他们都被虚荣心……和对力量的渴望蒙蔽了。"
D.Strings[109715]="真开心……大餐之前还有甜点！"
D.Strings[109716]="必须……逃出去！"
D.Strings[109717]="我在听讲呢。滚开！"
D.Strings[109718]="赞美基尔加丹！赞美萨格拉斯！"
D.Strings[109719]="我们能拯救世界，$n，一定能。"
D.Strings[109720]="我感觉不到任何异常，真的。"
D.Strings[109721]="<瑞斯塔兰不安地晃动着身体。>$b$b不管那是什么，都离我们不远。"
D.Strings[109722]="是的。我敢肯定。有什么黑暗而可怕的东西就在我们中间。"
D.Strings[109723]="看上去一切正常，陌生人。"
D.Strings[109724]="当然不会，怎么可能？别挡着我，我要听我们的领袖讲话。"
D.Strings[109725]="是的！我一来这里就感觉到了。都让我起鸡皮疙瘩了！"
D.Strings[109726]="我感觉附近有个令人不安的存在。你觉得会是什么呢？"
D.Strings[109727]="我们的地面部队已经肃清了这一区域，维迪卡尔就等你了。我们可以护送你。你做好出发的准备了吗？"
D.Strings[109728]="来了一头强大的恶魔。拿它杀鸡儆猴吧！"
D.Strings[109729]="我比过去更加强大！做好准备吧，凡人。"
D.Strings[109730]="|TInterface\\Icons\\ABILITY_MAGE_POTENTSPIRIT:20|t女巫会正准备施放|cFFFF0000|Hspell:245910|h[诺甘农的幽灵军团]|h|r！"
D.Strings[109731]="它又完好如初了！"
D.Strings[109732]="考瓦斯，萨格里特钥石的状态如何？"
D.Strings[109733]="只要我们还活着，军团就休想占据阿古斯。"
D.Strings[109734]="我的战刃在渴望恶魔的鲜血。"
D.Strings[109735]="你有什么情报，奥蕾莉亚？"
D.Strings[109736]="这里有许多猎物。"
D.Strings[109737]="任务完成了。回维迪卡尔吧，我们还有很多事要做。"
D.Strings[109738]="圣光。"
D.Strings[109739]="我不会被打垮的。"
D.Strings[109740]="%s的宠物科尔宾在你耳边高声啼鸣。"
D.Strings[109741]="我很好，$n。谢谢你的关心。$B$B在你走上战场前，我想告诉你，如果你需要找个地方休息，尽管来找我帮忙。$B$B保重。"
D.Strings[109742]="你将是第一个。"
D.Strings[109743]="你身后的是什么？"
